P.entries["item:stalker-claws"] = {n="Кігті Переслідувача",s="Кігті Переслідувача — пазурі, здобуті зі степових переслідувачів, що блукають хвилястими рівнинами Малгору. Шамани тауренів використовують їх як важливі складники, вирізьблюючи традиційні очисні тотеми для очищення осквернених водяних криниць.",h="Кігті Переслідувача — пазурі, здобуті зі степових переслідувачів, що блукають хвилястими рівнинами Малгору.",kw={"кігті переслідувача","степовий переслідувач","тотем","малл тандергорн","криниця тандергорнів","гобліни","малгор"},ang={["class:Shaman"]="Кігті диких рівнинних хижаків уособлюють люту чистоту природи — неодмінний матеріал для зв'язування й наснаження очисних тотемів.",["race:Tauren"]="Збирання цих кігтів служить священному обов'язку вашого племені — відновити святі води, отруєні безоглядними промисловими зайдами."},sec={{t="Хижаки рівнин",b="Трав'янисті степи Малгору — домівка смертоносних природних хижаків, серед них і потайних степових переслідувачів. Ці звірі живуть первісним інстинктом і смертельною точністю — неодмінна рівновага в задумі Матері-Землі. Малл Тандергорн, прагнучи зцілити вражену землю, потребує цих кігтів не зі злості на звірів, а тому, що чиста природна лють, з якою вони полюють, має духовний відгук, здатний протидіяти штучній скверні."},{t="Очищення криниць",b="Коли підприємства гоблінів почали бурити й копати по всьому центральному Калімдору, хімічні отрути просочилися глибоко в підземні води, що живлять прабатьківські криниці тауренів. Особливо постраждала Водяна Криниця Тандергорнів, уражена мерзенною скверною. Зв'язавши Кігті Переслідувача й Кігті Пуми в Очисний Тотем Громорога, племінні шамани створюють духовний провідник, здатний вичистити бруд і неприродний мул із природних джерел землі."}},faq={{q="Звідки беруться Кігті Переслідувача?",a="Їх здобувають, полюючи на степових переслідувачів на трав'янистих пагорбах Малгору, здебільшого на схід і на захід від Села Бладгуф.",al={"де знайти кігті переслідувача","хто дропає кігті переслідувача","джерело кігтів переслідувача"}},{q="Навіщо Маллу Тандергорну ці кігті?",a="З цих кігтів і кігтів рівнинних пум Малл Тандергорн виготовляє Очисний Тотем Громорога. Природна чистота й сила корінних мисливців рівнин потрібні, щоб очистити отруєні криниці.",al={"навіщо збирати кігті переслідувача","призначення мулла тандергорна","використання кігтів переслідувача"}},{q="Чому Водяна Криниця Тандергорнів забруднена?",a="Криницю отруює неприродне промислове забруднення від гоблінських розробок у Малгорі, які порушують природну рівновагу й отруюють місцеві ґрунтові води.",al={"хто отруїв криницю","чому колодязь тандергорнів хворий","забруднення тандергорнів"}},{q="Що стається, коли кігті зібрано?",a="Зібравши кігті, Малл вирізає з них очисний тотем, який треба віднести просто до Водяної Криниці Тандергорнів, щоб вигнати звідти рештки скверни.",al={"що далі","наступний крок після кігтів","обряд очищувального тотема"}}},fp="13,218,23.477.0,19.437.0,33.127.0,43.214.0,42.165.0,42.162.0"}
P.entries["item:steelgrill-s-tools"] = {n="Інструменти Стілґрила",s="Інструменти Стілґрила — спеціалізований набір механічного знаряддя, замовлений для Белдіна Стілґрілла, головного техніка Складу Стілґрила. Белдін, відомий тим, що жене облогові машини — й власне обладнання — на межу можливостей, часто ламає інструменти й залежить від постачання з сусіднього Хараноса, щоб його майстерня працювала.",h="Інструменти Стілґрила — спеціалізований набір механічного знаряддя, замовлений для Белдіна Стілґрілла...",kw={"інструменти стілґрила","белдін стілґрілл","склад стілґрила","облогові машини","харанос","інженерія","пілот стоунґір"},ang={["profession:Engineering"]="Кожен інженер поспівчуває скруті Белдіна: ремонт важких облогових машин із великими зусиллями регулярно забирає дугові ключі й тонкі гайкові ключі.",["race:Dwarf"]="Утримувати броньовані облогові машини Альянсу — справа дворфійської гордості, і постачання Белдіна гарантує, що броньований авангард Айронфорджа лишається боєздатним."},sec={{t="Майстер із важкою рукою",b="Белдіна Стілґрілла широко вважають одним із найкращих техніків облогових машин у Дун Мороґу, але його напористий стиль ремонту сумнозвісний серед місцевих торговців. Невтомно працюючи над броньованими танками й механічними пристроями, Белдін нищить тонке обладнання майже так само швидко, як його встигають викувати. Ламаючи дугові ключі й зриваючи зубчасті тріскачки, механік без упину робить нові замовлення в Хараносі, щоб його ремонтні верстаки не порожніли."},{t="Щоб машини їхали",b="Ця партія інструментів життєво важлива, щоб бойові машини Айронфорджа лишалися на ходу. На своєму складі на північний схід від Хараноса Белдін обслуговує бойові машини для досвідчених водіїв, як-от Пілот Стоунґір. Без свіжого запасу гайкових ключів і тріскачок важливі облогові машини стояли б напівзібраними в снігу, і зупинилися б і склад, і місцева оборона."}},faq={{q="Для чого потрібні Інструменти Стілґрила?",a="Це нові механічні інструменти на заміну старим, які доставляють Белдінові Стілґріллу на Склад Стілґрила. Вони потрібні Белдінові, щоб ремонтувати важкі дворфські машини, зокрема пошкоджену облогову машину Пілота Стоунґіра.",al={"що це за інструменти","призначення інструментів стілґрила"}},{q="Чому Белдін Стілґрілл так швидко нищить інструменти?",a="Белдін — надзвичайно грубий механік, що працює своїм знаряддям до знемоги. За словами постачальників із Хараноса, він ламає дугові гайкові ключі й ікласті храповики мало не швидше, ніж місцеві майстри встигають їх робити.",al={"чому зламані інструменти","навіщо белдіну інструменти"}},{q="Звідки цей ящик з інструментами?",a="Партію збирають і комплектують у сусідньому селищі Харанос, а тоді передають мандрівникам, що прямують на північний схід до Складу Стілґрила.",al={"де взяти інструменти","звідки ящик з інструментами"}},{q="Хто такий Белдін Стілґрілл?",a="Белдін — дворф-майстер механіки, власник і керівник Складу Стілґрила на північний схід від Хараноса. Його вважають найкращим знавцем облогових машин у краї.",al={"хто такий белдін","белдін стілґрілл лор"}}},fp="18,328,24.468.0,27.376.0,37.220.0,52.224.0,40.154.0,25.174.0"}
P.entries["item:steelsnap-s-rib"] = {n="Ребро Стілснапа",s="Ребро Стілснапа — похмурий трофей, здобутий із туші лютого ватажка гієн Стілснепа в Тисячі Голок. Принесене до Тандер Блафа, воно стає відчутним доказом того, що істоту, позбавлену благословення Земної Матері, знищено.",h="Ребро Стілснапа — похмурий трофей, здобутий із туші лютого ватажка гієн Стілснепа в Тисячі Голок.",kw={"ребро стілснапа","стілснеп","гієни","тисяча голок","мелор стоунгуф","узвишшя мисливців","мисливець"},ang={["class:Hunter"]="Здобути ребро ватажка зграї — перевірка вміння мисливця вистежувати небезпечну здобич і усувати загрози, що порушують рівновагу дикої природи.",["race:Tauren"]="Для тауренів принести цей трофей означає виконати обов'язок перед Земною Матір'ю, знищивши істоту, чия нестримна жорстокість плямує священну рівновагу."},sec={{t="Полювання поза благословенням",b="Більшість полювань тауренів провадять заради прожитку, заради честі чи в пошуках гармонії з природою. Та Стілснеп — здобич іншого роду. Цей лютий ватажок гієн блукає дном каньйону Тисячі Голок на південь від Табору Е'ток, тероризує мирних звірів і збирає зграї дрібніших хижаків для безглуздого кровопролиття. Коли майстер полювання Мелор Стоунгуф з Узвишшя Мисливців прирікає Стілснепа на смерть, він вимагає важку кістку — ребро Стілснепа — як незаперечне підтвердження, що тирана вбито, а каньйон очищено від цієї напасті."}},faq={{q="Для чого потрібне Ребро Стілснапа?",a="Ребро приносять Мелорові Стоунгуфу на Узвишшя Мисливців у Тандер Блафі, щоб завершити полювання на Стілснепа. Воно — відчутний доказ того, що лютого звіра-гієну переможено.",al={"завдання ребра стілснапа","хто хоче ребро стілснапа","що робити з ребром стілснапа"}},{q="Де знайти Стілснепа, щоб здобути ребро?",a="Стілснеп никає північно-західною частиною Тисячі Голок, блукаючи дном каньйону на південь від Табору Е'ток, зазвичай у супроводі вірних побратимів зі зграї.",al={"місце стілснапа","де стілснап","знайти стілснапа"}},{q="Чому Мелор Стоунгуф хоче смерті Стілснепа?",a="Мелор вважає Стілснепа неприродним тираном, що існує поза благословенням Земної Матері. На відміну від звичайних хижаків, які полюють, щоб вижити, Стілснеп сіє безглузде кровопролиття й страх серед мирних звірів, тож його треба знищити.",al={"чому вбити стілснапа","мотив мелора стоунгуфа","лор стілснапа"}},{q="Хто такий Мелор Стоунгуф?",a="Мелор Стоунгуф — досвідчений мисливець-таурен з Узвишшя Мисливців у Тандер Блафі, який доручає молодим слідопитам вистежувати небезпечних звірів по всьому Калімдору.",al={"хто такий мелор","місце мелора стоунгуфа","мелор мисливського підйому"}}},fp="15,245,27.553.0,33.177.0,42.148.0,47.240.0,23.165.0"}
P.entries["item:stolen-silver"] = {n="Викрадене Срібло",s="Викрадене срібло — повернена скринька з монетами Орди, призначеними для гарнізону варти Перехрестя. Її найдивнішим чином потягли в дикі хащі люті раптори Пусток, чим неабияк приголомшили наглядачів застави.",h="Викрадене срібло — повернена скринька з монетами Орди, призначеними для гарнізону варти Перехрестя.",kw={"викрадене срібло","раптори","угіддя рапторів","ґазроґ","перехрестя","платня"},ang={["faction:Horde"]="Перехрестя — стратегічне серце Орди в Пустках. Повернувши ці гроші, ви дбаєте, щоб місцеві бійці були ситі, вчасно отримували платню й були готові тримати оборону проти набігів кентаврів і Альянсу."},sec={{t="Звірине пограбування",b="Неосяжні дикі простори Пусток постійно загрожують шляхам постачання, але мало хто чекав, що місцеві сонцелускі раптори полюватимуть на скриньки з монетами. Коли перехопили вантаж із платнею для гарнізону Перехрестя, раптори затягли скриньку до своїх спільних гнізд в Угіддях Рапторів на південь від Раджета. Для наглядачів на кшталт Ґазроґа ця крадіжка виявила тривожну хитрість хижаків: вони, схоже, або цінують блискучі дрібнички, або мають розум, що далеко перевершує звичайних диких звірів."}},faq={{q="Що таке Викрадене Срібло?",a="Це важка скриня, повна срібних монет на платню вартовим Перехрестя. Її викрали під час нападу диких рапторів і затягли до їхніх гнізд.",al={"що таке викрадене срібло","що за срібло"}},{q="Навіщо рапторам викрадати скриню з монетами?",a="Чим керувалися хижаки, лишається загадкою навіть для таких бувалих воїнів, як Ґазроґ. Звірі зазвичай шукають поживу, але раптори Пусток славляться незвичайною кмітливістю, і щось змусило їх затягти блискучу металеву скриню глибоко до свого лігва.",al={"чому раптори хочуть срібло","розум рапторів","чому срібло"}},{q="Куди забрали срібло?",a="Раптори затягли скриню до Угідь Рапторів — скелястого каньйону з гніздами на південь від Раджета, на сході Пусток.",al={"місце викраденого срібла","де срібло"}},{q="Хто шукає Викрадене Срібло?",a="Ґазроґ, орк із Перехрестя, шукає скриню. У ній — повна місячна платня для виснажених захисників застави.",al={"хто хоче срібло","хто здає викрадене срібло"}}},fp="13,239,15.530.0,26.173.0,41.248.0,27.128.0,37.141.0"}
P.entries["item:stone-of-relu"] = {n="Камінь Релу",s="Камінь Релу — давня археологічна реліквія, знайдена в Багнокраї. Археолог Флеґонґат вважає його ключем до прихованих сил первісних скам'янілостей; ненадовго камінь загубився, коли на вченого дорогою напали місцеві раптори.",h="Камінь Релу — давня археологічна реліквія, знайдена в Багнокраї.",kw={"камінь релу","флеґонґат","ліга дослідників","раптори","багнокрай","скам'янілості"},ang={["faction:Alliance"]="Експедиції Альянсу в Гавані Менетіл покладаються на віднайдені артефакти на кшталт Каменя Релу, щоб виправдати виснажливі розкопки на небезпечних болотах.",["race:Dwarf"]="Для Ліги Дослідників Камінь Релу — важливе знаряддя, щоб скласти докупи історію походження давнього життя й забуту спадщину світу."},sec={{t="Ключ до давніх реліквій",b="Знайдений під час робіт Ліги Дослідників, Камінь Релу, як вважають, має силу, потрібну, щоб розкрити доісторичні скам'янілості, зібрані в Калімдорі та Східних Королівствах. Археолог Флеґонґат визначив цей артефакт як каталізатор, що вивільнить таємниці і його власних зразків із Багнокраю, і скам'янілості, яку шукач Ремтревел відкопав на Темному Узбережжі."},{t="Загублений серед боліт",b="Коли Флеґонґат ішов дорогами Багнокраю на зустріч із шукачем Велґаром, на нього напала зграя плямистих рапторів. У метушні реліквія загубилася, і її проковтнув один із ненажерливих звірів, тож Ліга мусила наймати шукачів пригод, щоб полювати на болотяних рапторів і вирізати давній камінь із їхніх горлянок."}},faq={{q="Що таке Камінь Релу?",a="Камінь Релу — давній артефакт, який шукає Археолог Флеґонґат. Він вважає, що камінь — це ключ або каталізатор, здатний розкрити приховані таємниці й силу, що дрімають у доісторичних скам'янілостях.",al={"камінь релу","що це за камінь","артефакт релу"}},{q="Як камінь опинився в шлунку раптора?",a="Археолог Флеґонґат ніс реліквію дорогою через Багнокрай на зустріч із Шукачем Велґаром, коли на його загін напали плямисті раптори. У метушні камінь загубився, і його проковтнув один зі звірів-падальників.",al={"чому раптори його мають","хто загубив камінь","як його загубили"}},{q="Що Флеґонґат збирається робити з каменем?",a="Флеґонґат хоче поєднати камінь зі своєю знайденою скам'янілістю та скам'янілістю, яку відшукав Шукач Ремтревел на Темному Узбережжі, щоб за допомогою реліквії розгадати й вивільнити їхні приховані магічні таємниці.",al={"що флеґонґат зробить з каменем","призначення каменю релу"}}},fp="13,258,23.387.0,19.330.0,26.207.0,41.217.0,48.190.0"}
P.entries["item:stonetalon-sap"] = {n="Сік з Кам'яного Кігтя",s="Сік з Кам'яного Кігтя — липка, сильна речовина, яку добувають просто з неповоротких живичних звірів, що бродять скелястими висотами Гір Кам'яного Кігтя. Це важливий реагент для знахаря Темного Списа Джин'Зіла, який використовує його сирі лісові властивості, щоб зварити злісне зілля.",h="Сік з Кам'яного Кігтя — липка, сильна речовина, яку добувають просто з неповоротких живичних звірів, що...",kw={"сік з кам'яного кігтя","живичні звірі","знахар джин'зіл","малака'джин","озеро міркфаллон","вуду"},ang={["race:NightElf"]="Осквернення рідної природи Гір Кам'яного Кігтя знахарем Орди, щоб отруїти полонених вартових, — наруга над природою й Елуною.",["race:Troll"]="Знахар Джин'Зіл показує хист Темного Списа обертати улюблений ворогом край на смертоносне знаряддя вуду."},sec={{t="Гіркий збір",b="Ця густа рідина, що скрапує з деревних живичних звірів біля Озера Міркфаллон і Піку Кам'яного Кігтя, несе зосереджену сутність давньої рослинності гір. У природі, у спокої, сік нешкідливий, але в руках досвідченого алхіміка чи знахаря його легко обернути на щось куди темніше. Джин'Зіл із Малака'джина жадає його, щоб зварити те, що глузливо називає «лісовою магією», — смертельний напій, яким має мучити полонених вартових з-поміж нічних ельфів самою сутністю їхньої улюбленої дикої природи."}},faq={{q="Які створіння мають Сік з Кам'яного Кігтя?",a="Його збирають із сокових звірів — дивних лісових створінь, що водяться біля Озера Міркфаллон і вище, на схилах, що ведуть до Піку Кам'яного Кігтя.",al={"де взяти сік кам'яного кігтя","хто дропає сік кам'яного кігтя","соковиті звірі"}},{q="Для чого Знахар Джин'Зіл використовує сік?",a="Джин'Зіл змішує сік з очима скакунів, сутінковими вусами й лускою феєвого дракона, щоб зварити отруйне зілля, яке випробовує на нічних ельфах, ув'язнених у його клітках.",al={"чому джин'зіл хоче сік","рецепт лісової магії джин'зіла"}},{q="Де найкраще шукати сокових звірів?",a="Сокові звірі живуть у гаях довкола Озера Міркфаллон і на буйних зелених стежках, що здіймаються до Піку Кам'яного Кігтя.",al={"місце соковитих звірів","соковиті звірі озера міркфаллон"}},{q="Чи магічний сік сам по собі?",a="Він від природи насичений первісною життєвою силою нагір'я Кам'яного Кігтя, але щоб обернути його на смертельну отруту, потрібні тролівське моджо й особливі реагенти.",al={"чи магічний сік кам'яного кігтя","властивості соку кам'яного кігтя"}}},fp="14,283,16.519.1,36.148.0,47.163.1,43.109.0,30.160.0"}
P.entries["item:stormpike-banner"] = {n="Прапор Стормпайк",s="Прапор Стормпайк — військовий стяг, захований глибоко в підступній Печері Крижаного Крила в Долині Альтерак. Новобранці Альянсу мусять пройти повз диких гарпій, щоб повернути його в межах обряду посвяти й довести, що гідні носити відзнаку Стормпайків.",h="Прапор Стормпайк — військовий стяг, захований глибоко в підступній Печері Крижаного Крила в Долині Альтерак.",kw={"прапор стормпайк","варта стормпайків","печера крижаного крила","долина альтерак","лейтенант гаґґердін","дун балдар"},ang={["faction:Alliance"]="Повернення прапора позначає ваш офіційний вступ до Варти Стормпайків і дає право нести їхню бойову відзнаку в боротьбі з Кланом Морозного Вовка.",["race:Dwarf"]="Прапор уособлює законні права Айронфорджа та священну місію клану Стормпайк — відшукати реліквії титанів по всій долині."},sec={{t="Обряд прийняття",b="Щоб офіційно вступити до лав експедиції Стормпайків у Долині Альтерак, новобранці мусять довести свою мужність ще до першого зіткнення з орками клану Морозного Вовка. Лейтенант Гаґґердін посилає новоприбулих солдатів Альянсу до Печер Крижаного Крила на південний захід від Дун Балдара. Захований глибоко в цьому крижаному підземному лігві, Прапор Стормпайк — справжнє випробування: кожен, хто наважиться протистояти місцевим гарпіям, захопить стяг і повернеться живим, отримує звання й відзнаку новачка Варти Стормпайків."}},faq={{q="Де знаходиться Прапор Стормпайк?",a="Прапор устромлено глибоко в Печерах Крижаного Крила — скутій кригою системі печер на південний захід від Дун Балдара в Долині Альтерак.",al={"місце прапора","де прапор стормпайк","як знайти прапор"}},{q="Чому новобранці мають принести прапор?",a="Лейтенант Гаґґердін вимагає, щоб кожен новобранець Альянсу довів свою хоробрість, перш ніж стати до бою. Хто принесе прапор із небезпечної печери, де аж кишить гарпіями, отримує свою першу Відзнаку Стормпайк.",al={"випробування полігону","чому принести прапор","завдання геґердіна"}},{q="Які загрози чатують на прапор у печері?",a="Печери Крижаного Крила люто захищають дикі місцеві гарпії, що жорстоко нападають на кожного, хто прийде по стяг.",al={"монстри біля прапора","вороги печери льодокрила"}},{q="Кому віддати знайдений прапор?",a="Віднесіть знайдений прапор Лейтенантові Гаґґердіну — офіцерові Альянсу, що стоїть біля входу в Горах Альтерак.",al={"здати прапор","кому віддати прапор"}}},fp="16,248,19.546.0,38.137.0,44.232.0,46.129.0,41.131.0"}
P.entries["item:stormpike-s-request"] = {n="Запит Стормпайк",s="Запит Стормпайка — письмове замовлення, яке Горянин Стормпайк надіслав із пагорбів Лох Модану до Стормвінда. У листі він просить майстра-броняра Фурена Лонґбірда викувати особливий щит неперевершеної дворфійської якості.",h="Запит Стормпайка — письмове замовлення, яке Горянин Стормпайк надіслав із пагорбів Лох Модану до Стормвінда.",kw={"запит стормпайк","горянин стормпайк","фурен лонґбірд","щит","лох модан","дворфійський квартал"},ang={["profession:Blacksmithing"]="Це замовлення — свідчення слави майстрів-бронярів: видатна дворфійська ковальська робота знаходить замовників у цілих королівствах.",["race:Dwarf"]="Для дворфів доставка цього замовлення підтримує родинні й ремісничі зв'язки між горянами, що стережуть Каз Модан, і майстрами, що живуть на чужині в людських містах."},sec={{t="Замовлення з півночі",b="Несучи службу далеко на півночі, в Лох Модані, Горянин Стормпайк потребує нового міцного щита, щоб протистояти небезпекам дворфійського прикордоння. Не довіряючи звичайним ковалям, він наполягає, щоб щит викував Фурен Лонґбірд — броняр, чию легендарну майстерність він шанує понад усе. Фурен тепер живе далеко на півдні, серед людей у Дворфійському Кварталі Стормвінда, — Стормпайк вважає, що з Айронфорджу його виманили не інакше як королівським викупом, — тож горянин покладається на мандрівних шукачів пригод, щоб доставити його офіційне замовлення через королівства."},{t="Рід Стормпайків",b="Доставлений у жвавий Дворфійський Квартал Стормвінда, лист потрапляє просто до вправних рук Фурена Лонґбірда. Стормпайки — горда й поважна дворфійська родина, відома по всьому Каз Модану і бойовою витримкою, і чималими статками, тож їхнє замовлення має вагу. Радий звісткам і роботі зі своєї рідної півночі, Фурен погоджується виконати замовлення й береться кувати щит для горянина."}},faq={{q="Що таке Запит Стормпайк?",a="Це письмове замовлення Горянина Стормпайка з Лох Модану: він просить майстра обладунків Фурена Лонґбірда викувати йому якісний щит.",al={"що це за лист","предмет наказ стормпайка","запит стормпайк"}},{q="Хто написав цей лист?",a="Його написав Горянин Стормпайк — дворф-вартовий, що захищає перевали Лох Модану й щиро захоплюється ковальським хистом Фурена Лонґбірда.",al={"хто надіслав запит стормпайка","хто це написав","горянин стормпайк"}},{q="Куди треба доставити цей лист?",a="Його адресовано Фуренові Лонґбірду, який працює у своїй кузні в Дворфійському Кварталі Стормвінда.",al={"куди нести запит стормпайка","хто отримує лист","доставити запит стормпайка"}},{q="Чому Стормпайк наймає коваля аж у Стормвінді?",a="Горянин Стормпайк вважає майстерність Фурена неперевершеною й не погоджується на жодного іншого зброяра, хоч Фурен і покинув Айронфордж, щоб займатися ремеслом серед людей на півдні.",al={"чому фурен","чому не кувати в айронфорджі","чому слати до стормвінда"}}},fp="19,237,21.578.0,18.448.0,28.154.0,22.144.0,34.105.0,57.191.0"}
P.entries["item:stormwind-armor-marker"] = {n="Талон на Обладунок Стормвінда",s="Талон на Обладунок Стормвінда — офіційний військовий реквізиційний знак, який видають шукачам пригод, що допомогли королівству. Його можна обміняти в уповноважених ремісників, як-от Сара Тімберлейн у Лісозаготівельному Таборі Східної Долини, на щойно виготовлене спорядження.",h="Талон на Обладунок Стормвінда — офіційний військовий реквізиційний знак, який видають шукачам пригод, що...",kw={"талон на обладунок","реквізиція","сара тімберлейн","східна долина","обладунок","стормвінд"},ang={["faction:Alliance"]="Талон утілює господарські зв'язки, що напряму з'єднують прикордонні поселення на кшталт Лісозаготівельного Табору Східної Долини з військовим командуванням Стормвінда."},sec={{t="Військові реквізиції",b="Підтримання закону й порядку по всьому Лісі Елвінн виснажує ресурси королівства. Замість роздавати стандартне спорядження просто з військових застав, командири часом видають офіційні знаки, відомі як талони на обладунок. Ці реквізиційні квитки засвідчують, що носій доблесно послужив Стормвінду, й уповноважують місцевих найнятих майстрів забезпечити його підігнаним обладунком."},{t="Постачання Східної Долини",b="Одне з головних місць, куди несуть ці талони, — Лісозаготівельний Табір Східної Долини на східному рубежі Елвінну. Там ремісники на кшталт Сари Тімберлейн працюють за замовленням війська Стормвінда, перетворюючи місцеві матеріали на захисний одяг із тканини й шкіри. Пред'явивши талон, новобранці отримують підігнаний захист, що допоможе їм берегти довколишні ліси."}},faq={{q="Для чого потрібен Талон на Обладунок Стормвінда?",a="Це офіційний військовий талон, який дають шукачам пригод, що допомагають варті Стормвінда. Він засвідчує вашу службу й дає змогу отримати обладунок у майстра, що працює на замовлення армії.",al={"що таке талон на обладунок","призначення талона","використання талона стормвінда"}},{q="Хто приймає талон?",a="Його приймає Сара Тімберлейн у Лісозаготівельному Таборі Східної Долини, просто на схід через річку в Лісі Елвінн. Вона має угоду з армією Стормвінда на виготовлення тканинного й шкіряного спорядження.",al={"хто бере талон","куди здати талон","талон сари тімберлейн"}},{q="Чому Стормвінд видає талони, а не роздає обладунки одразу?",a="На віддалених заставах варти часто бракує складів, кузень і кравецьких майстерень, щоб спорядити новобранців на місці. Видаючи талони, польові командири доручають спорядження місцевим ремісникам, як-от Сара Тімберлейн, які мають власні майстерні.",al={"чому талони замість обладунків","чому армійські талони","військові ваучери ельвін"}},{q="Яке спорядження можна отримати за талон?",a="Талон дає власникові право вибрати новий тканинний чи шкіряний обладунок, виготовлений на замовлення армійськими постачальниками.",al={"яку броню отримаю","нагороди за талон","тканина чи шкіра"}}},fp="22,251,21.397.0,21.379.0,50.208.0,23.204.0,69.259.0,47.137.0"}
P.entries["item:stoutmantle-s-response-to-solomon"] = {n="Відповідь Стаутмантла Соломону",s="«Відповідь Стаутмантла Соломону» — письмове послання, яке везуть із Сентінел Гілла до Лейкширу. У ньому Ґраян Стаутмантл з гіркотою повідомляє Магістратові Соломону, що знекровлене Народне ополчення не може виділити жодного вояка на оборону Гір Редріджу.",h="«Відповідь Стаутмантла Соломону» — письмове послання, яке везуть із Сентінел Гілла до Лейкширу.",kw={"відповідь стаутмантла соломону","ґраян стаутмантл","магістрат соломон","лейкшир","редрідж","народне ополчення"},ang={["faction:Alliance"]="Цей лист оголює політичну гниль, що паралізує саме серце Альянсу: віддалені поселення мусять благати допомоги одне в одного, поки столиця тримає свої сили при собі.",["race:Human"]="Для людських захисників це послання — похмуре нагадування, що сільська глибинка, як-от Вестфол і Редрідж, однаково відчайдушно бореться за виживання без королівської варти Стормвінда."},sec={{t="Відмова на благання",b="Під безжальним тиском орків Блекрок і гнолів Магістрат Соломон із Лейкширу звернувся до Сентінел Гілла, сподіваючись, що місцеві сили Вестфолу пришлють підкріплення. Письмова відповідь Ґраяна Стаутмантла приносить гірку звістку. Прохання магістрата завдає Стаутмантлові болю, і він чітко дає зрозуміти: Соломон не усвідомлює, наскільки тяжка війна поглинає Вестфол. Народне ополчення постало з відчаю саме тому, що Корона відкликала свій гарнізон і залишила фермерів і добровольців самих протистояти Братству Дефіас. Стаутмантл пояснює, що його власні сили стікають кров'ю й розтягнуті до краю, тож він не може пожертвувати людьми, щоб рятувати ще одне покинуте прикордоння."},{t="Забуті королівством",b="Листування показує спільну трагедію південних людських земель у 25 році після Темного Порталу. І Редрідж, і Вестфол цілком покинуті королівським двором у Стормвінді. Поки король Варіан Рінн вважається зниклим, а постійне військо королівства з незрозумілих причин не пускають до провінційних кордонів, віддаленим містечкам лишається або створювати власну добровольчу варту, або загинути. Коли Соломон отримує запечатану відповідь, до нього доходить: жодне з містечок не врятує інше; усе королівство розлазиться по швах, а столиця мовчить."}},faq={{q="Що написано у Відповіді Стаутмантла Соломону?",a="Ґраян Стаутмантл пояснює, що Вестфол охоплений жорстокою війною з Братством Дефіас і, як і Редрідж, покинутий армією Стормвінда. Він сумує за полеглими захисниками, але твердо відмовляє Магістратові Соломону в проханні про військове підкріплення.",al={"що каже лист","зміст листа стаутмантла","текст відповіді соломону"}},{q="Чому Соломон узагалі попросив допомоги у Вестфолу?",a="На Лейкшир тяжко нападають гноли й орки Блекрок, а його прохання до Генерала Маркуса Джонатана в Стормвінді досі не принесло жодних військ. Не маючи офіційної підтримки, Магістрат Соломон звернувся через Елвінн до Народного ополчення, сподіваючись, що такі самі захисники прикордоння зможуть виділити бійців.",al={"чому просити вестфолл","соломон просить стаутмантла","чому лейкшир просив ополчення"}},{q="Чому Народне ополчення не може виділити бійців?",a="Народне ополчення — добровольче військо, яке ледве втримує Сентінел Гілл і довколишні рівнини від Братства Дефіас. Втрати зростають щодня, підтримки регулярної армії немає, тож, пославши бійців до Лейкширу, Вестфол залишився б зовсім беззахисним.",al={"чому ополчення не допомагає","чи може вестфолл допомогти редріджу","чому відмовити соломону"}},{q="Чому армія Стормвінда не захищає ці містечка?",a="Ніхто в жодному з містечок цього не знає. Стаутмантл пише лише, що Стормвінд відкликав свої війська й залишив Вестфол беззахисним, а Магістрат Соломон може тільки гадати, що ж такого важливого відірвало армію Стормвінда від її народу. Обидва сільські краї змушені боронитися самотужки, силами місцевих добровольців.",al={"де армія стормвінда","чому стормвінд не допоможе","дезертирство стормвінда"}}},fp="33,251,13.687.0,21.551.1,42.282.0,57.293.0,48.269.0,52.322.0"}
P.entries["item:strange-smelling-powder"] = {n="Дивно Пахучий Порошок",s="Дивно Пахучий Порошок — загадковий осад, знайдений під час розслідування підозрілих диверсій довкола Лох Модану. Побоюючись, що це нестійка підривна речовина, Головний Інженер Гіндервір терміново шле гінця на північ, до знавця вибухівки.",h="Дивно Пахучий Порошок — загадковий осад, знайдений під час розслідування підозрілих диверсій довкола Лох...",kw={"дивно пахучий порошок","гіндервір","ешлан стоунсмерк","дун модр","вибухівка","диверсія","лох модан"},ang={["profession:Engineering"]="Інженери впізнають сірчаний запах нестійких підривних сумішей, що не відповідають звичним формулам, якими користуються на гірничих заставах Альянсу.",["race:Dwarf"]="Для дворфів захист кам'яних споруд і водосховищ Лох Модану понад усе, тож будь-який натяк на ворожу вибухівку — негайна криза для всього клану."},sec={{t="Небезпечна знахідка",b="Цей дивний порошок знайшли серед слідів диверсії, що загрожує спорудам Лох Модану, і він одразу стривожив Головного Інженера Гіндервіра. Різкий запах і дрібна текстура свідчать, що це спеціально виготовлена підривна суміш, а не звичайний гірничий вибуховий порох. Не знаючи ні хімічної природи суміші, ні її походження, Гіндервір не наважується порпатися в ній сам: найменша іскра може накликати лихо."},{t="Шлях на північ",b="Дворфійські інженери не ризикують із небезпечними реагентами, тож Гіндервір відсилає зразки порошку крізь Браму Алґаз до Багнокраю. Там, у Дун Модрі біля Мосту Тандол, досвідчений знавець вибухівки Ешлан Стоунсмерк має роздивитися крупинки й з'ясувати, який нищівний вибух готують диверсанти."}},faq={{q="Що таке Дивно Пахучий Порошок?",a="Це підозрілий хімічний осад, знайдений у Лох Модані під час розслідування місцевих диверсій. Через різкий сморід і склад дворфські інженери підозрюють, що це вибухова речовина.",al={"що таке дивно пахучий порошок","що це за порошок","порошок лох модану"}},{q="Навіщо Головний Інженер Гіндервір хоче його дослідити?",a="Гіндервір підозрює, що порошок — особлива вибухівка. Щоб зрозуміти розмах і небезпеку змови проти Лох Модану, йому потрібен висновок фахівця, що добре знається на підривній справі.",al={"навіщо досліджувати порошок","порошок гіндервейра","кому потрібен порошок"}},{q="Хто може розпізнати порошок?",a="Головний Інженер Гіндервір посилає мандрівників віднести зразок Ешланові Стоунсмерку — знавцеві вибухівки, що служить далеко на півночі з полком у Дун Модрі, біля Мосту Тандол.",al={"хто впізнає порошок","куди нести порошок","знавець порошку"}},{q="Чому перевозити порошок небезпечно?",a="Окрім природної нестійкості невідомої вибухової речовини, доведеться ще й пройти небезпечний шлях крізь Браму Алґаз на болотисті, ворожі дороги Багнокраю.",al={"чи небезпечний порошок","чому небезпечно"}}},fp="23,268,20.427.0,14.358.1,32.197.0,52.214.0,28.180.0,41.189.0"}
P.entries["item:strangely-marked-box"] = {n="Дивно Помічена Скриня",s="Дивно Помічена Скриня — вантаж, знайдений у збруї, пристебнутій до мертвих морських черепах на березі Темного Узбережжя. На її таємничій поверхні — рунічні письмена зміїстих наг, і це доводить ученим нічних ельфів, що морські створіння викидалися на берег не випадково.",h="Дивно Помічена Скриня — вантаж, знайдений у збруї, пристебнутій до мертвих морських черепах на березі Темного...",kw={"дивно помічена скриня","наги","морські черепахи","ґвенніт блай'леґґонд","храм місяця","темне узбережжя"},ang={["class:Priest"]="Рятуючи реліквії з берега, ви допомагаєте вченим Храму Місяця в Обердайні вберегти узбережжя від морської порчі.",["race:NightElf"]="Скрині з припасами наг, прив'язані до місцевих морських черепах на Темному Узбережжі, попереджають калдореїв: їхні давні спотворені родичі планомірно виходять на берег із Великого Моря."},sec={{t="Трофеї глибин",b="Кількох велетенських морських черепах та інших морських створінь просто викидає на оповиті імлою пляжі Темного Узбережжя, та інші туші розповідають куди зловіснішу історію. На деяких — уламки верхової збруї та покинуті ноші, прив'язані просто до панцирів. Серед решток цих погнутих пристосувань лежать запечатані скрині, вкриті чужими звивистими рунами. Мурлоки Сірої Імли, що шукають поживи, часто оселяються в порожніх грудних кошиках і розбитих возах, обгризають падло й стережуть усе, що там лишилося."},{t="Докази наступу наг",b="Коли скриню приносять Ґвенніт Блай'Леґґонд, дослідниці, що представляє Храм Місяця в Обердайні, знаки на ній відкривають своє справжнє походження. Письмена й прив'язані ноші належать нагам, які використовують величезних черепах як в'ючних тварин, щоб переправляти на суходіл припаси й військове спорядження. Знайдені скрині з припасами підтверджують, що наги навмисно діють на північних берегах і, можливо, женуть своїх тварин на південь, до Ашенвалю, тож жрецтво Обердайна відсилає реліквії просто до Дарнасуса для подальшого вивчення."}},faq={{q="Де знайти Дивно Помічену Скриню?",a="Скриню дістають із покинутих вантажних кошів, прив'язаних до панцирів мертвих морських черепах, викинутих на берег Темного Узбережжя. Довкола цих туш часто товчуться мурлоки з племені Сірої Імли, що ласують падлом і захищають його.",al={"де знайти дивно помічену скриню","місце скрині","скриня черепашачого візка"}},{q="Хто зробив Дивно Помічену Скриню?",a="Скриню й написи на ній зробили наги. Вони прилаштовують вантажні коші до живих морських черепах, щоб перевозити провізію, зброю й спорядження з морських глибин на береги Калімдору.",al={"хто зробив скриню","позначки на скрині","руни на скрині","що за позначки"}},{q="Кому в Обердайні потрібна ця скриня?",a="Ґвенніт Блай'Леґґонд, дослідниця, що працює в Обердайні для Храму Місяця, забирає скриню, щоб розібратися в дивних викидах на берег і зрозуміти, наскільки зросла загроза від наг.",al={"кому віддати скриню","здати скриню","хто хоче скриню"}},{q="Чому морські черепахи несли ці скрині?",a="Наги приручають або поневолюють гігантських морських черепах як в'ючних тварин: прив'язують їм на спини упряж і коші, щоб іти в бій і доставляти припаси на суходіл. Ґвенніт підозрює, що одну таку черепаху вбили, коли вона прямувала далі на південь — можливо, до Ашенвалю.",al={"чому черепахи мають скрині","черепашачі візки","чому черепахи з ременями"}},{q="Що стається зі скринею, коли віддати її Ґвенніт?",a="Ґвенніт Блай'Леґґонд пересилає скриню й решту знахідок з узбережжя до Храму Місяця в Дарнасусі, щоб провідники нічних ельфів могли з'ясувати масштаби вторгнення наг.",al={"куди йде скриня","скриня надіслана до дарнасуса"}}},fp="20,303,20.544.0,26.575.1,40.224.0,34.200.0,32.183.0,46.269.0,52.196.0"}
P.entries["item:strigid-owl-feather"] = {n="Перо Стригідної Сови",s="Пера Стригідної Сови збирають із диких сов-стригід, що гніздяться у вітті Тельдрассила. Хоч це природне лісове пір'я, його шукають сумнівні постаті, яким потрібна сировина для таємних оборудок.",h="Пера Стригідної Сови збирають із диких сов-стригід, що гніздяться у вітті Тельдрассила.",kw={"перо стригідної сови","сова-стригіда","пір'я","зенн фаулгуф","сатир","доланаар","тельдрассил"},ang={["class:Druid"]="Друїди високо шанують крилатих мисливців Тельдрассила, тож бачити, як їхнє пір'я збирають під облудним приводом на підозрілі складники, — прикро.",["race:NightElf"]="Сов Тельдрассила мають за створіння Елуни, тож їхній визиск застарілим сатиром на кшталт Зенна Фаулгуфа — образа священному лісу."},sec={{t="Лісове пір'я й темні оборудки",b="У шатрах Тельдрассила живуть сови-стригіди й верескуни — корінні хижі птахи, що полюють по всій Короні Землі. Їхній пух і пера — звична знахідка на лісовій долівці, та часом вони привертають око тих, хто шукає живі складники. За Доланааром сатир-відступник Зенн Фаулгуф користається з недосвідчених мандрівників, що спускаються дорогою з Тінедолу, і підбурює їх здобувати пера стригід разом із павутинним шовком та іклами нічних шаблезубів для своїх тіньових справ."}},faq={{q="Де знайти Пір'я Стригідної Сови?",a="Це пір'я збирають, полюючи на сову-стригіду та верескливу стригіду, що живуть у лісах довкола Доланаара та по всьому Тельдрассилу.",al={"місце пера","де падає пір'я стригідної сови","фарм пір'я сови"}},{q="Кому потрібне Пір'я Стригідної Сови?",a="Сатир на ім'я Зенн Фаулгуф, що причаївся біля стежки до Доланаара, просить наївних шукачів пригод принести це пір'я, а також павутинний шовк Вебвуда й ікла нічних шаблезубів.",al={"кому потрібне пір'я сови","здати пір'я сови","зенн пір'я сови"}},{q="Для чого Зенн Фаулгуф використовує пір'я?",a="Зенн запевняє, що це реагенти для його таємних справ у лісі, хоча насправді найбільше він тішиться тим, що обдурює довірливих новачків і змушує їх робити за нього брудну роботу.",al={"навіщо зенн пір'я","призначення реагента зенна"}}},fp="19,226,32.519.1,38.139.0,31.160.0,45.165.0"}
P.entries["item:sturdy-dragonmaw-shinbone"] = {n="Міцна Гомілкова Кістка Драконячої Пащі",s="Міцні Гомілкові Кістки Драконячої Пащі — тривкі кістяні трофеї, зібрані з орків-ренегатів Драконячої Пащі в Багнокраї. Їх потребує майстриня обладунків Велора Найтлі в Андерсіті: ці кістки стають опорними розпірками для обладунків, які вона кує для воїнів на замовлення.",h="Міцні Гомілкові Кістки Драконячої Пащі — тривкі кістяні трофеї, зібрані з орків-ренегатів Драконячої Пащі в...",kw={"міцна гомілкова кістка драконячої пащі","драконяча паща","орки","велора найтлі","багнокрай","табір анґерфанґ","воїн"},ang={["class:Warrior"]="Здобути ці щільні орківські кістки й перевірити їх голими руками — так ви доводите свою фізичну силу й водночас збираєте основу для обладунків на замовлення.",["race:Undead"]="Велора Найтлі — взірець типового прагматизму Відступників: кістки ворогів вона перетворює на корисне спорядження для героїв Темної Леді."},sec={{t="Кістки для каркаса",b="Куючи грізні наголінники для воїнів передової, ковалі потребують сировини, що витримає найсуворіші удари. В Андерсіті Велора Найтлі цінує щільні кістки орків-ренегатів Драконячої Пащі, які окопалися в Таборі Анґерфанґ на півночі Багнокраю. Орки Драконячої Пащі славляться кремезною, міцною статурою, тож їхні гомілки чудово підходять як опорні скоби. Та не кожна зібрана кістка витримає навантаження: воїни мусять перевіряти кожну голіруч і відкидати ті, що ламаються під тиском."}},faq={{q="Чим ці гомілкові кістки міцніші за звичайні?",a="Орки Драконячої Пащі від природи мають масивний кістяк, але через дрібні тріщини чи крихкість багато кісток не годяться для обладунків. Щоб переконатися, що кістка міцна, воїн згинає її голими руками: лише ті, що не ламаються, вважають досить міцними для каркаса захисних наголінників.",al={"чому гомілкові кістки міцні","міцність кісток драконячої пащі","перевірка гомілкових кісток"}},{q="Кому потрібні Міцні Гомілкові Кістки Драконячої Пащі?",a="Їх шукає Велора Найтлі, майстриня обладунків з Андерсіті. Вона використовує їх як основні розпірки каркаса, коли виготовляє грізні наголінники для перспективних воїнів Орди.",al={"кому потрібні гомілкові кістки","кістки велори найтлі","здати гомілкові кістки драконячої пащі"}},{q="Де збирають ці кістки?",a="Їх здобувають з орків-ренегатів Драконячої Пащі, що захопили Багнокрай на південь від Аратійського нагір'я, — передусім у Таборі Анґерфанґ серед пагорбів на південний захід від Мосту Тандол.",al={"де взяти гомілкові кістки драконячої пащі","місце гомілкової кістки драконячої пащі","кістки енґерфенґа"}},{q="Чому Велора Найтлі робить обладунки з орківських кісток?",a="Ремесло Відступників часто поєднує кістки, сухожилля й метал у моторошне, але надзвичайно міцне бойове спорядження. Клан Драконячої Пащі ворогує з Ордою Тралла, тож його рештки — законна здобич для ковалів-Відступників, яким потрібен міцний, витривалий матеріал.",al={"чому орківські кістки","відступники обладунки з кісток","велора кісткове ремесло"}}},fp="25,235,19.551.0,58.307.0,37.166.0,31.194.0,47.265.0"}
P.entries["item:sully-balloo-s-letter"] = {n="Лист Саллі Баллу",s="Лист Саллі Баллу — розмокле, ніжне послання, знайдене біля затонулих останків дворфійського воїна під Мостом Тандол. Адресований його дружині Сарі в Айронфорджі, він утілює тихі особисті трагедії, що ховаються за великими конфліктами Каз Модану.",h="Лист Саллі Баллу — розмокле, ніжне послання, знайдене біля затонулих останків дворфійського воїна під Мостом...",kw={"лист саллі баллу","саллі баллу","сара баллу","міст тандол","удова","айронфордж","багнокрай"},ang={["faction:Alliance"]="Доставити лист — скорботна мить співчуття: останні думки полеглого воїна дійдуть до його вдови, а не будуть забуті під мостом.",["race:Dwarf"]="Для дворфів цей лист утілює болісні жертви, на які йдуть звичайні горяни й воїни, щоб стерегти високі мости й гірські перевали Каз Модану."},sec={{t="Останнє прощання під хвилями",b="Під велетенськими кам'яними опорами Мосту Тандол, що з'єднує Багнокрай з Аратійським нагір'ям, лежить скелет дворфа, придавлений глибоко під бурхливою водою. У його руці затиснутий крихкий, розмоклий конверт із цим листом. Написаний із болісною старанністю в його останні дні чи години, він починається зворушливими словами: «Моя люба Саро…». Хоч пергамент і постраждав від довгого перебування у воді, чорнило досі береже незгасну любов дворфійського захисника, який так і не повернувся додому, до міста Айронфордж."},{t="Доставка до Айронфорджа",b="Принести лист Сарі Баллу в Айронфордж — означає принести їй скорботне, спустошливе завершення. Живучи в дворфійській столиці, Сара зносить болісну невідомість, знайому багатьом, чиї рідні пішли на війну. Останні думки її чоловіка Саллі підтверджують найгірші побоювання — він загинув далеко від дому, під крижаними течіями північної переправи, — але й зберігають його відданість, що пережила смерть."}},faq={{q="Де знайти Лист Саллі Баллу?",a="Лист дістають із розмоклого конверта, затиснутого в руці кістяка дворфа на дні під Мостом Тандол, що відділяє Багнокрай від Аратійського нагір'я.",al={"місце листа","де лист саллі","де знайти лист саллі баллу"}},{q="Хто такий Саллі Баллу?",a="Саллі Баллу — дворф-солдат, що загинув біля Мосту Тандол, захищаючи важливу північну переправу; його рештки так і лишилися притиснуті течією на дні річки.",al={"хто такий саллі баллу","історія саллі баллу","що сталося з саллі"}},{q="Кому адресовано лист?",a="Лист адресовано пані Сарі Баллу, засмученій дружині Саллі, що живе у великому дворфському гірському місті Айронфорджі.",al={"кому лист","хто така сара баллу","куди здати лист саллі"}},{q="Що стається, коли віддати лист Сарі Баллу?",a="Отримавши лист, Сара Баллу з болем дізнається, що її чоловік лежить мертвий під крижаною водою, але дорожить нагодою прочитати останні слова, які він із любов'ю їй написав.",al={"реакція сари баллу","здати лист","завершення завдання листа саллі"}}},fp="21,272,34.545.0,21.404.1,37.212.0,21.178.0,31.130.0,56.203.1"}
P.entries["item:sunscorched-shell"] = {n="Обпалена Сонцем Шкаралупа",s="Обпалена сонцем шкаралупа — міцні рештки яєць віверн, які збирають під гніздовищами Високосіду в Тисячі Голок. Загартована пекучою пустельною спекою, вона дуже цінна для вправних майстрів обладунків, які вміють перетворити її на захисний лак для кольчужних кілець.",h="Обпалена сонцем шкаралупа — міцні рештки яєць віверн, які збирають під гніздовищами Високосіду в Тисячі Голок.",kw={"обпалена сонцем шкаралупа","віверни","високосід","тисяча голок","матіель","фурен лонґбірд","кольчуга","лак"},ang={["class:Warrior"]="Воїни, яким потрібна кольчуга на замовлення, допомагають Матіелю збирати цю міцну шкаралупу, щоб викувати зміцнений обладунок.",["profession:Blacksmithing"]="Ця шкаралупа показує, як кмітливі ковалі дивляться далі звичайної руди й перетворюють природні мінеральні покриття на захисний лак для кольчуг."},sec={{t="Пустельні кладки",b="Віверни Високосіду гніздяться високо на скелях-голках південного Калімдору, і їхні яйця витримують нещадне пустельне сонце й пекучі вітри. Уламки шкаралупи накопичуються під гніздовищами, і сухе підсоння випікає їх до дивовижної твердості. Випадковому мандрівникові вони здаються лише крихким сміттям, але ці обпалені сонцем рештки мають природну міцність, тож для майстрів особливого ремесла це цікавий реагент."},{t="Лак майстра",b="У Дарнасусі майстер обладунків Матіель вивчає ремісничі прийоми, які першим опанував його колега, дворф-коваль Фурен Лонґбірд. Зацікавлений відкриттями Фурена, Матіель виготовляє з цієї шкаралупи тонкий лак, що зміцнює кольчужні обладунки. Правильно оброблене й нанесене, це багате на мінерали покриття зростається з металевими кільцями й робить броню значно витривалішою, не обтяжуючи того, хто її носить."}},faq={{q="Де знайти Обпалену Сонцем Шкаралупу?",a="Вона розкидана на землі під гніздами віверн по всьому Високосіду — високій столовій горі, що здіймається з дна каньйону на заході Тисячі Голок.",al={"де знайти обпалену сонцем шкаралупу","де шкаралупа","шкаралупа хайперча"}},{q="З якого створіння ця шкаралупа?",a="Це уламки шкаралупи яєць віверн Високосіду, що гніздяться на вершинах плато в Тисячі Голок.",al={"яке створіння знесло яйця","яйця виверн","походження шкаралупи"}},{q="Навіщо Матіелю Обпалена Сонцем Шкаралупа?",a="Матіель хоче випробувати прийоми виготовлення обладунків, які відкрив Фурен Лонґбірд. Він перетоплює затверділу шкаралупу на міцний лак, яким покриває й зміцнює кільця кольчуги.",al={"шкаралупа матіеля","для чого шкаралупа","лак для броні"}},{q="Хто такий Фурен Лонґбірд і до чого він тут?",a="Фурен Лонґбірд — колега Матіеля по ковальському ремеслу з Дворфійського Кварталу Стормвінда. Його досліди з незвичними реагентами й прийомами гартування надихнули Матіеля експериментувати з лаком зі шкаралупи віверн.",al={"зв'язок фурена","шкаралупа фурена лонґбірда"}}},fp="17,257,15.447.0,21.390.0,35.143.0,40.104.0,41.174.0,46.223.0"}
P.entries["item:super-reaper-6000-blueprints"] = {n="Креслення Суперкосаря 6000",s="Креслення Суперкосаря 6000 — технічні схеми велетенської механізованої лісорубки, яку Венчурна Компанія застосовує в Горах Кам'яного Кігтя. Розроблені під наглядом гнома-інженера Ґерензо Ренчвісла, ці плани дуже жадані для його незадоволених суперників-гоблінів.",h="Креслення Суперкосаря 6000 — технічні схеми велетенської механізованої лісорубки, яку Венчурна Компанія...",kw={"креслення суперкосаря 6000","суперкосар 6000","ґерензо ренчвісл","венчурна компанія","круча вітрорізу","зіз фіззікс"},ang={["profession:Engineering"]="Креслення відбивають химерне поєднання грубої гоблінської корпоративної сили й скрупульозної гномської механіки — з технічними схемами, від яких губляться звичайні винахідники.",["race:Gnome"]="Креслення Ґерензо Ренчвісла доводять, що навіть безжальні гоблінські синдикати на кшталт Венчурної Компанії зрештою покладаються на гномську кмітливість, щоб будувати складні важкі машини."},sec={{t="Промислове шпигунство на Кручі Вітрорізу",b="Невпинна суцільна вирубка Венчурної Компанії на Кручі Вітрорізу тримається на велетенських механізованих лісозаготівельних машинах — Суперкосарях. На превеликий жаль традиційних гоблінських інженерів, компанія доручила розробку моделі Суперкосар 6000 гномові на ім'я Ґерензо. Ці креслення містять схеми машини, і їх носять оператори Венчурної Компанії, що працюють на ній по всій кручі. Коли гоблінського інженера Зіза Фіззікса вигнали з робіт, його швидко найняв Спаттервалв, щоб викрасти розробки. Проте розшифрувати заплутані, химерні гномські технічні позначки Ґерензо виявляється майже так само важко, як відібрати креслення силою."}},faq={{q="Що таке Суперкосар 6000?",a="Це величезна механічна лісорубна машина, створена для суцільної вирубки лісу Венчурною Компанією в Горах Кам'яного Кігтя: вона валить і переробляє деревину з нещадною промисловою ефективністю.",al={"що таке суперкосар","машина суперкосар"}},{q="Хто сконструював Суперкосар 6000?",a="Креслення розробили під керівництвом Ґерензо Ренчвісла — гнома-інженера, якого Венчурна Компанія найняла очолити механічні роботи на Кручі Вітрорізу, на превелике невдоволення місцевих гоблінів-механіків.",al={"хто зробив креслення","хто сконструював суперкосар"}},{q="Навіщо Зізові Фіззіксу ці креслення?",a="Зіза вигнали з Венчурної Компанії, і його одразу найняв Спаттервалв. Викрадені креслення Суперкосаря — для Зіза нагода довести новому босові, чого він вартий і який він геніальний механік.",al={"навіщо зізу плани","кому потрібні креслення"}},{q="У кого на Кручі Вітрорізу креслення?",a="Креслення носять оператори Венчурної Компанії, що наглядають за машинами й вирубують ліс по всій Кручі Вітрорізу.",al={"де падають креслення","хто дропає креслення"}}},fp="28,296,38.695.0,30.210.0,35.198.0,43.186.0,43.140.0"}
P.entries["item:supplies-for-sven"] = {n="Припаси для Свена",s="Припаси для Свена — пакунок найнеобхіднішого, зібраний у Даркширі для відлюдного табору Свена Йорґена. Серед жахіть Сутінколісся Свен і його невеличкий загін тримаються лише завдяки співчутливим містянам, як-от родина Каревінів, і продовжують нести варту проти тіней.",h="Припаси для Свена — пакунок найнеобхіднішого, зібраний у Даркширі для відлюдного табору Свена Йорґена.",kw={"припаси для свена","свен йорґен","табір свена","даркшир","каревіни","сутінколісся"},ang={["class:Paladin"]="Непохитний опір Свена темряві Сутінколісся побожні люди вважають справжньою справою Світла, тож ці припаси — важлива послуга братові по вірі.",["faction:Alliance"]="Нічна Варта ледве встигає захищати Даркшир, тож мандрівники Альянсу часто стають єдиним надійним гінцем до віддалених застав на кшталт табору Свена."},sec={{t="Рятівна нитка для табору",b="Нести через Сутінколісся спорядження для виживання й найпотрібніші речі — справа непроста. Свен Йорґен і жменька його прибічників таборують у північно-західній глушині лісу, далеко від безпеки Даркшира. Їх так мало, а варта така виснажлива, що вони не можуть відпустити до міста жодного бійця. Цей пакунок — рятівна нитка від родини Каревінів: він дає відрізаному таборові їжу, бинти й матеріали, щоб устояти."}},faq={{q="Хто надіслав ці припаси?",a="Припаси передає родина Каревінів із Даркширу. Знаючи, як відчайдушно бореться Свен Йорґен у глушині, вони зібрали ці харчі, щоб підтримати його табір.",al={"хто надіслав припаси для свена","хто спакував припаси свена","припаси родини каревін"}},{q="Чому Свен не може сам забрати припаси?",a="Загін Свена надто малий. Лише кілька вцілілих товаришів захищають табір на північному заході Сутінколісся від звірів і нежиті, тож вони не можуть відпустити нікого небезпечними дорогами до Даркширу.",al={"чому свен не бере їжу","чому доставка для свена","навіщо припаси"}},{q="Де табір Свена?",a="Табір Свена розташований на північно-західній околиці Сутінколісся, серед пагорбів, далеко за межами прямого захисту Нічної Варти.",al={"де свен йорґен","місце табору свена","знайти свена в сутінколіссі"}},{q="Хто такий Свен Йорґен?",a="Свен Йорґен — поселенець із прикордоння й палкий вірянин Світла, що колись фермерував у Сутінколіссі. Коли його оселю спіткало лихо, він заснував на прикордонні озброєний табір, щоб завдавати ударів темним силам, які мучать край.",al={"хто такий свен","історія свена йорґена"}}},fp="17,280,23.494.0,24.185.0,38.210.0,29.140.0,19.227.0"}
P.entries["item:surena-s-choker"] = {n="Намисто Сурени",s="Намисто Сурени — зачароване намисто з кровавика, яке Ґакін Зв'язувач Темряви подарував своїй колишній учениці Сурені Каледон. Після того як Сурена зрадила Ґакіна й утекла до Братства Дефіас, майстер-чорнокнижник послав послушників-початківців силою повернути прикрасу.",h="Намисто Сурени — зачароване намисто з кровавика, яке Ґакін Зв'язувач Темряви подарував своїй колишній учениці...",kw={"намисто сурени","сурена каледон","ґакін","ерлан драджмур","братство дефіас","кровавик"},ang={["class:Warlock"]="Повернення цього намиста від Сурени Каледон — засадниче випробування для чорнокнижників із людей і гномів: доказ того, що сентиментам немає місця в гонитві за демонічною силою."},sec={{t="Утрачений вклад майстра",b="Ґакін Зв'язувач Темряви, що тихо працює під «Зарізаним Ягням» у Стормвінді, узяв Сурену Каледон перспективною ученицею темних мистецтв. Зачарований її юною привабливістю й магічним хистом, Ґакін подарував їй цінне намисто з кровавика на поміч у навчанні. Та Сурена покинула навчання й утекла з Ерланом Драджмуром, розбійником, пов'язаним із Братством Дефіас. Не бажаючи лишати такий могутній артефакт у руках зрадниці, Ґакін доручає новачкам, що прагнуть влади над порожнечею, вистежити Сурену на Гарбузовій Ділянці Брекуеллів, повернути намисто й показати, де лежить справжня вірність."}},faq={{q="Чому Ґакін Зв'язувач Темряви хоче повернути Намисто Сурени?",a="Ґакін подарував Сурені намисто з кривавиком, коли вона ще була його ученицею. Коли ж вона кинула навчання й утекла з членом Братства Дефіас, Ґакін не захотів лишати зрадниці такий цінний артефакт темної магії.",al={"чому ґакін хоче намисто","ґакін намисто сурени","чому повертати намисто"}},{q="Хто така Сурена Каледон?",a="Сурена Каледон — колишня учениця чорнокнижника зі Стормвінда, що виявляла природний хист під наглядом Ґакіна Зв'язувача Темряви. Вона відвернулася від наставника, щоб утекти з Ерланом Драджмуром і переховуватися серед розбійників Дефіасу в Лісі Елвінн.",al={"хто така сурена","лор сурени каледон","у кого намисто"}},{q="Де знайти намисто?",a="Намисто носить сама Сурена Каледон, що переховується серед бандитів Дефіасу на Гарбузовій Ділянці Брекуеллів на сході Лісу Елвінн.",al={"де сурена","місце намиста","де сурена каледон"}},{q="Для чого намисто, коли його повернуто?",a="Повернене намисто доводить безжальність і відданість учня Ґакінові Зв'язувачу Темряви. Ґакін так і не каже, що з ним зробить, — лише шкодує про змарнований талант Сурени й сподівається, що вкладене в нового учня дасть інші плоди.",al={"що ґакін робить з намистом","призначення намиста","навіщо чорнокнижникам намисто"}}},fp="15,266,26.637.0,56.237.0,22.241.0,30.146.0,50.245.0"}
P.entries["item:swoop-gizzard"] = {n="Шлунок Стрімкокрила",s="Шлунок стрімкокрила — орган хижих птахів, що ширяють над Малгором. Його високо цінують у традиційних народних ліках як важливий складник для очищення від смертельних отрут.",h="Шлунок стрімкокрила — орган хижих птахів, що ширяють над Малгором.",kw={"шлунок стрімкокрила","стрімкокрил","маур рейнколлер","маззранаш","село бладгуф","малгор","ліки"},ang={["race:Tauren"]="Для мисливців і шаманів-тауренів збирання таких частин — шана традиції, за якою кожна частина звірів Малгору служить для прожитку й зцілення племені."},sec={{t="Рідкісний народний складник",b="Стрімкокрили — хижі птахи, що живуть на рівнинах і столових горах Малгору; вони славляться гострим зором і звичкою живитися падлом. Їхнє пір'я й м'ясо таурени використовують у побуті, а от нутрощі — надто шлунок — особливо цінують травники й цілителі. У поєднанні з іншими сильнодійними частинами звірів, як-от кістки кугуарів і серця вовків, цей щільний м'язистий орган допомагає знешкоджувати отруту від укусів звірів і зупиняти гнійне зараження, що поширюється тілом."},{t="Ліки від укусу Маззранаша",b="У Селі Бладгуф знахар Маур Рейнколлер став жертвою легендарного степового довгоступа Маззранаша й дістав люту отруйну рану в плече. Впадаючи в маячню від отрути, що повільно розходиться тілом, Маур покладається на шлунок стрімкокрила разом із серцем степового вовка, стегновою кісткою рівнинного кугуара й лускою степового довгоступа, щоб приготувати цілющу припарку, здатну вигнати смертельну отруту звіра."}},faq={{q="Для чого потрібен Шлунок Стрімкокрила?",a="Це важливий лікарський інгредієнт для Маура Рейнколлера в Селі Бладгуф. Разом із трьома іншими частинами звірів він дає ліки, що можуть очистити від отруйної зарази, спричиненої лютим степовим довгоступом Маззранашем.",al={"використання шлунка стрімкокрила","навіщо мені шлунок стрімкокрила","призначення шлунка"}},{q="Звідки беруться шлунки стрімкокрилів?",a="Їх здобувають із різних стрімкокрилів, що ширяють над рівнинами Малгору: звичайних, жилавих і кігтистих.",al={"де знайти шлунок стрімкокрила","хто дропає шлунок стрімкокрила","полювання на стрімкокрилів"}},{q="Навіщо Маурові Рейнколлеру саме ця частина?",a="Маура вкусив Маззранаш — надзвичайно лютий степовий довгоступ, чий укус несе отруту, що спричиняє шалену гарячку й жахіття. Традиційна тауренська медицина використовує сильнодійні частини звірів, зокрема шлунок, щоб протидіяти саме тій отруті, що тече в його жилах.",al={"ліки маура","чому шлунок","ліки від мазранаш"}},{q="Чи використовують шлунок для чогось іще, крім ліків для Маура?",a="Ні. Поза особливими народними ліками Маура Рейнколлера в Селі Бладгуф шлунки стрімкокрилів не мають звичного застосування ні в кулінарії, ні в алхімії, ні в ремеслах.",al={"інше використання шлунка стрімкокрила","приготування шлунка стрімкокрила","алхімія шлунка стрімкокрила"}}},fp="13,198,22.479.0,31.402.0,33.239.0,34.151.0,49.284.0,56.158.0"}
P.entries["item:tablet-of-verga"] = {n="Скрижаль Верги",s="Скрижаль Верги — магічний камінь із викарбуваними демонічними рунами, без яких не скорити темних сутностей. Її викрав зловісний культ Палаючого Клинка й заховав глибоко у своєму лігві в Череп-скелі. Повернувши артефакт, адепти темних мистецтв в Оргріммарі зможуть розгадати ритуали, потрібні, щоб скорити блукача Порожнечі.",h="Скрижаль Верги — магічний камінь із викарбуваними демонічними рунами, без яких не скорити темних сутностей.",kw={"скрижаль верги","палаючий клинок","череп-скеля","блукач порожнечі","чорнокнижник","тіньова розколина"},ang={["class:Warlock"]="Для чорнокнижників, що навчаються в Оргріммарі, повернути цю скрижаль — важлива віха, що доводить їхню цінність для Орди й відкриває таємниці, потрібні, щоб скорити блукача Порожнечі, вірного захисника.",["faction:Horde"]="Палаючий Клинок так близько від брам Оргріммара — постійна загроза молодій державі Тралла; вириваючи з його рук викрадені реліквії, Орда б'є по впливу культу."},sec={{t="Викрадена реліквія",b="На Скрижалі Верги викарбувано особливі ритуальні руни, потрібні, щоб прикликати істот Нижнього Світу й підкорити їх волі господаря. Коли культові Палаючого Клинка вдалося викрасти скрижаль, він заховав її в потаємній скрині в Череп-скелі, трохи на схід від Оргріммара. Для чорнокнижників, що нишком працюють у тінях Тіньової Розколини, повернути реліквію вкрай важливо — не лише щоб вивчити її давні знаки для прикликання блукача Порожнечі, а й щоб позбавити фанатиків-культистів їхньої власної темної переваги."}},faq={{q="Де знаходиться Скрижаль Верги?",a="Скрижаль зберігається в Схованці Палаючого Клинка в Череп-скелі — печерному комплексі, де аж кишить культистами, просто на схід від Оргріммара в Дуротарі.",al={"місце скрижалі верги","де знайти скрижаль верги","де скрижаль верги"}},{q="Хто хоче повернути Скрижаль Верги?",a="Ґан'рул Бладай, майстер-чорнокнижник із Тіньової Розколини під Оргріммаром, доручає новачкам повернути скрижаль, щоб навчити їх викликати могутніших прислужників.",al={"хто хоче скрижаль верги","кому віднести скрижаль верги","скрижаль ґан'рула"}},{q="Яку силу містить скрижаль?",a="На камені вирізьблено давні руни, без яких не завершити ритуал виклику й підкорення блукача Порожнечі — створіння, витягнутого з Викривленого Нижнього Світу.",al={"що робить скрижаль","лор скрижалі верги","руни скрижалі верги"}},{q="Навіщо Палаючий Клинок її викрав?",a="Культ Палаючого Клинка невтомно шкодить Орді й нарощує власну демонічну силу. Позбавити чорнокнижників Оргріммара ключових ритуальних текстів, а знання зберегти для себе — прямо на руку культистам.",al={"чому палаючий клинок має скрижаль","палаючий клинок верга"}}},fp="15,316,14.500.0,37.158.0,40.180.0,35.158.0,35.225.0"}
P.entries["item:tainted-heart"] = {n="Опоганене Серце",s="Опоганене Серце — уражене пошестю рослинне осердя, видобуте зі споганеної рослинності Тельдрассила. Передане шукачам пригод ботаніком Деналаном, воно потребує магічного й живильного очищення, щоб позбутися залишків огидних сил.",h="Опоганене Серце — уражене пошестю рослинне осердя, видобуте зі споганеної рослинності Тельдрассила.",kw={"опоганене серце","осквернене осердя","деналан","скверна","грядка","ґрунт","тельдрассил"},ang={["class:Druid"]="Для друїдів Кола Кенарія робота над очищенням Опоганеного Серця дає пряме розуміння повзучої скверни, що загрожує здоров'ю молодого Світового Дерева.",["profession:Herbalism"]="Травники й ботаніки оцінять майстерність Деналана в змішуванні особливо збагаченого ґрунту, здатного витягати неприродну гниль із живої рослинної тканини."},sec={{t="Осквернене Осердя",b="Природна рівновага Тельдрассила потерпає від неприродної недуги, що спотворює корінні рослини й звірів. Зчистивши огидний мох, який обліпив уражений наріст, Деналан показує залишене осердя — Опоганене Серце. Хоч і звільнене від зовнішньої гнилі, воно досі просякнуте темрявою. Деналан прагне з'ясувати, чи може особливо приготована, багата на поживу земля побороти залишки скверни й повернути життя споганеному."},{t="Ліки Деналана",b="Покладене в зачаровану грядку Деналана, серце виявляє дивну, невгасиму життєву силу. Воно жадібно вривається в багатий ґрунт і вбирає цілющу поживу. За мить земля випалює скверну, і очищене серце постає живим, пульсуючи чистою силою й пориваючись захищати тих, хто його зцілив."}},faq={{q="Що таке Опоганене Серце?",a="Це серцевина оскверненої рослини з Тельдрассила. Ботанік Деналан зняв зовнішній мерзенний мох, але саме серце просякнуте скверною, доки його не очистять.",al={"що таке опоганене серце","предмет опоганене серце"}},{q="Хто очищує Опоганене Серце?",a="Деналан просить шукачів пригод посадити його в особливо підготовлений вазон біля Озера Ал'Амет. Поживний ґрунт сам очищує серце від неприродної скверни.",al={"хто очищає серце","як очистити опоганене серце"}},{q="Що стається, коли серце посаджено?",a="Серце заривається в ґрунт вазона. За мить воно з'являється знову — цілком очищене, сповнене життя й готове поєднатися з тим, хто його відродив.",al={"що буде з серцем","результат посадженого серця"}},{q="Чому серце взагалі осквернене?",a="Світовим Древом Тельдрассил шириться дивна хвороба, що оскверняє місцеві рослини, деревляників і звірів по всіх його гілках.",al={"чому осквернене","скверна тельдрассила серце"}}},fp="13,219,16.438.0,16.326.1,26.180.0,31.187.0,33.166.1,46.143.0"}
P.entries["item:tainted-keg"] = {n="Опоганене Барильце",s="Опоганене Барильце — барило викраденого дворфійського темного пива, отруєного смертоносним варивом Відступників, яке зготував Аптекар Лайдон. Під виглядом частунку його доставляють полоненим людським фермерам у Таррен Міллі, і воно стає моторошним польовим випробуванням отрут, які розробляє Королівське Аптекарське Товариство.",h="Опоганене Барильце — барило викраденого дворфійського темного пива, отруєного смертоносним варивом...",kw={"опоганене барильце","еліксир агонії","аптекар лайдон","таррен мілл","дарталія","темне пиво шіндіґера"},ang={["race:Human"]="Убивство полонених селян отруєним пивом показує моторошну, безжальну тактику, з якою стикаються рештки живих по всьому Гілсбреду.",["race:Undead"]="Для Королівського Аптекарського Товариства отруєне пиво — практичний етап у створенні біологічної зброї, здатної винищити людство."},sec={{t="Смертоносний урожай",b="Спершу це барильце було барилом Темного Пива Шіндіґера, награбованим у дворфійських стрільців, що окопалися в Дун Ґароку. Замість випити його, Аптекар Лайдон отруїв міцне пиво своїм щойно вдосконаленим Еліксиром Агонії. Отруївши звичайний напій, Відступники створили підступний переносник, що не викликає підозри, — і звична втіха живих стала швидким смертним вироком."},{t="Випробування на приречених",b="На горішньому поверсі таверни Таррен Мілла тримали кількох людських фермерів, схоплених після того, як Верховний Екзекутор Дарталія запідозрила, що серед них ховається військовий стратег зі Стормвінда. Коли надійшла звістка, що стратег загинув деінде, полонені робітники стали непотрібними. Дарталія віддала їх Лайдонові, і той влаштував жорстоке «свято», звелівши поставити отруєне барильце на килим у їхній кімнаті. Спраглі й зневірені, бранці пили вволю — і довели миттєву смертельну силу еліксиру."}},faq={{q="Що в Опоганеному Барильці?",a="У ньому — темне пиво Шіндіґера, міцний дворфський ель, викрадений із Дун Ґарока й змішаний з Еліксиром Агонії, експериментальною отрутою, яку створив Аптекар Лайдон у Таррен Міллі.",al={"вміст барильця","яка отрута в барильці","що в бочці"}},{q="Звідки взялося пиво?",a="Основу забрали в дворфів-горян і стрільців, що тримають Дун Ґарок — добре укріплену дворфську фортецю на південному сході Передгір'я Гілсбреда.",al={"хто зварив пиво","звідки вкрали стаут","джерело стауту шіндіґера"}},{q="Хто п'є з барильця?",a="З барильця п'ють фермери-люди, яких тримають заручниками в кімнаті нагорі корчми Таррен Мілла: випивши отруєного пива, вони падають і майже одразу помирають.",al={"хто п'є з барильця","жертви опоганеного барильця","полонені фермери"}},{q="Чому фермерів тримали в полоні?",a="Верховний Екзекутор Дарталія заарештувала їх, підозрюючи, що серед них ховається військовий стратег Альянсу зі Стормвінда. Коли підтвердилося, що цей стратег загинув у Чумних Землях, полонених фермерів визнали непотрібними й віддали аптекарям.",al={"чому фермери в полоні","чому дарталія захопила фермерів","чому фермери в таррен міллі"}}},fp="11,292,16.408.0,24.504.1,31.171.0,39.169.0,24.165.1,41.264.0"}
P.entries["item:tainted-letter"] = {n="Опоганений Лист",s="Опоганений Лист — потай доставлений виклик із печаткою Друзілли Ла Салль, наставниці чорнокнижників, що ховається на околиці Абатства Нортшира. Він велить майбутнім людям-практикам темних мистецтв з'явитися до неї по особливу науку подалі від пильних очей.",h="Опоганений Лист — потай доставлений виклик із печаткою Друзілли Ла Салль, наставниці чорнокнижників, що...",kw={"опоганений лист","друзілла ла салль","чорнокнижник","абатство нортшира","виклик","скверна"},ang={["class:Warlock"]="Опоганений Лист знаменує ваше офіційне знайомство з тіньовим ремеслом у Королівстві Стормвінд і встановлює, що влада над Безоднею вимагає постійної пильності й обачності.",["race:Human"]="Людське суспільство загалом сповідує Святе Світло, тож практикам темної магії доводиться проводити свої посвяти й навчання потай, на узбіччі таких місць, як Абатство Нортшира."},sec={{t="Таємний виклик",b="Поки жерці, паладини й звичайні солдати відкрито навчаються на доглянутих галявинах Абатства Нортшира, практикам магії скверни доводиться діяти значно обережніше. Цей лист, що його вручають новачкам, які повертаються з сусідніх виноградників і копалень, повних шкідників, несе особистий знак Друзілли Ла Салль. Позначене ледь відчутними слідами темного ремесла, послання велить чорнокнижникам-початківцям непомітно розшукати свою наставницю біля земель абатства, перш ніж тутешня варта й клірики запідозрять їхній заборонений шлях."},{t="Ціна амбіцій",b="Зустріч із Друзіллою пояснює потребу в такій потайності. Простий люд Елвінну дивиться на чорнокнижників із глибокою недовірою, тож наставники мусять триматися околиць і уникати цікавих вартових. Друзілла використовує доставлений лист, щоб розпочати важливий урок дисципліни: таємна магія й магія Безодні ваблять невпинне розбещення, і практикам доводиться гамувати свої бурхливі амбіції терплячим самовладанням, спілкуючись із мешканцями Викривленого Нижнього Світу."}},faq={{q="Хто надіслав Опоганений Лист?",a="Лист написала й запечатала Друзілла Ла Салль, місцева наставниця чорнокнижників, що стоїть просто біля головної зали Абатства Нортшира.",al={"хто написав опоганений лист","лист друзілли","відправник опоганеного листа"}},{q="Чому лист вважають опоганеним?",a="Від листа віє скверною, а печатка на ньому — знак того, хто практикує демонічне мистецтво. Аура темної магії відрізняє його від звичайного листування.",al={"чому лист опоганений","що робить лист опоганеним","опоганена печатка"}},{q="Чому вартові Нортшира стежать за Друзіллою Ла Салль?",a="Вартові й жерці Абатства Нортшира не довіряють магії скверни й виклику демонів. Друзілла мусить триматися непомітно на околиці абатства, щоб не дратувати світську владу, яка пильно стежить за підозрюваними чорнокнижниками.",al={"чому вартові стежать за друзіллою","вартові друзілла","чорнокнижник ховається в нортширі"}},{q="Яку пораду дає Друзілла, прочитавши лист?",a="Друзілла застерігає новачка, що справи із сутностями з Викривленого Нижнього Світу несуть сильну спокусу й загрозу зіпсуття. Вона навчає учнів самовладання й розсудливості, але так, щоб обережність не загасила їхніх амбіцій.",al={"порада друзілли","що каже друзілла","навчання друзілли"}}},fp="14,279,16.546.0,21.480.0,28.139.0,37.185.0,53.234.0,55.252.0"}
P.entries["item:tainted-memorandum"] = {n="Осквернений Меморандум",s="Осквернений Меморандум — непомітна записка, яку вручають гномам-чорнокнижникам-новачкам, що починають шлях у Долині Холодного Хребта. Написана наставником чорнокнижників Аламаром Гріммом, вона закликає читача відкинути традиційні шляхи й шукати справжньої сили, яку дають темні мистецтва.",h="Осквернений Меморандум — непомітна записка, яку вручають гномам-чорнокнижникам-новачкам, що починають шлях у...",kw={"осквернений меморандум","чорнокнижник","аламар грімм","гноми","анвілмар","гномреґан","скверна"},ang={["class:Warlock"]="Записка — ваше офіційне представлення наставникові чорнокнижників Аламару Грімму, який подає темний призов як необхідне прагнення до влади й контролю.",["race:Gnome"]="Послання Грімма грає на гномському обуренні через утрату Гномреґану та їхнє становище залежних біженців на дворфійських землях."},sec={{t="Непомітний виклик",b="У холодній дворфійській заставі Анвілмар тих, хто практикує магію скверни, не вітають і не надто їм довіряють. Для молодих гномів, що бавляться забороненими мистецтвами, Осквернений Меморандум — запрошення від Аламара Грімма. Послання відкидає опору на Святе Світло чи звичайну бойову сталь, натомість вказуючи на падіння Гномреґану як доказ того, що звичні методи й винахідництво підвели їхній народ. Для Грімма покладатися на дворфійську милостиню — глухий кут: гноми мусять здобути незаперечну силу й прикликати беззаперечно покірних поплічників, якщо сподіваються забезпечити собі майбутнє."}},faq={{q="Хто написав Осквернений Меморандум?",a="Меморандум написав Аламар Грімм, гном — наставник чорнокнижників в Анвілмарі в Долині Холодного Хребта.",al={"автор оскверненого меморандуму","хто надіслав осквернений меморандум","записка аламара грімма"}},{q="Чому меморандум названо оскверненим?",a="Він стосується забороненої магії чорнокнижників. Назва відбиває недовіру й осуд, що оточують демонічну силу й силу скверни в Дун Мороґу, де господарі-дворфи тримають чорнокнижників на відстані.",al={"чому осквернений","лор оскверненого листа"}},{q="Що Аламар Грімм каже про Гномреґан?",a="Грімм гірко переживає падіння столиці гномів і звинувачує традиційну тайну магію та безтурботне майстрування в тому, що гноми опинилися на межі вимирання. Він вважає, що дворфи мають гномів за другосортних, і закликає чорнокнижників шукати власну абсолютну силу, а не чекати допомоги від Альянсу.",al={"аламар грімм гномереґан","погляди аламара грімма"}}},fp="18,257,18.580.0,33.116.0,43.208.0,44.304.0"}
P.entries["item:talisman-of-corruption"] = {n="Талісман Псування",s="Талісман Псування — мерзенна демонічна дрібничка, якою сатир Ксабраксіс отруює розум фурболгів Чорнолісся на Темному Узбережжі. Сатир носить його в особистій торбині, і талісман служить магічним провідником, що прив'язує плем'я до божевілля Скверни.",h="Талісман Псування — мерзенна демонічна дрібничка, якою сатир Ксабраксіс отруює розум фурболгів Чорнолісся на...",kw={"талісман псування","ксабраксіс","сатири","фурболги чорнолісся","тундріс віндвівер","обердайн"},ang={["class:Druid"]="Друїди вважають пристрої на кшталт цього талісмана прямим збоченням природного ладу: вони перетворюють священних звірів на здичавілих пішаків посіпак, що лишилися від Палаючого Легіону.",["race:NightElf"]="Для калдореїв Обердайна здобути талісман — важливий крок, щоб звільнити давніх союзників-фурболгів від демонічного занепаду й зцілити землю."},sec={{t="Провідник божевілля",b="Нічні ельфи Обердайна довго не могли зрозуміти, чому фурболги Чорнолісся так люто обернулися проти своїх колишніх союзників. Тундріс Віндвівер з'ясував, що занепад племені не був природним — це навмисна диверсія, яку влаштували сатири. За допомогою таких талісманів демонічні посланці поширюють нетрями чари порчі, отруюють запаси їжі й обертають мирних лісових духів на скажених звірів. Спрямовуючи магію Скверни просто через ці пристрої, сатири тримають розум і волю місцевих племен у непохитних лещатах."},{t="Розірвати лещата",b="Щоб виманити винного сатира, шукачі пригод мусять очистити зразки їжі фурболгів благословенною водою з місячного колодязя — так табір на якийсь час очищується, і це розлючує наглядача. Убивство Ксабраксіса розриває його безпосередню владу, а в його демонічній торбі знаходиться талісман. Коли талісман приносять Тундрісові Віндвіверу в Обердайн, калдореї можуть знешкодити його мерзенні випромінювання й з'ясувати, як назавжди зняти демонічну недугу, що вразила ліс."}},faq={{q="Що таке Талісман Псування?",a="Це демонічний пристрій, яким сатир Ксабраксіс спрямовує мерзенну магію, щоб псувати розум і їжу фурболгів Чорнолісся на Темному Узбережжі.",al={"що таке талісман псування","призначення талісмана","що робить талісман"}},{q="Хто носить талісман?",a="Він лежить у демонічній торбі Ксабраксіса — сатира, що наглядає за північним табором фурболгів Чорнолісся біля Річки Скельного Джерела.",al={"хто дропає талісман псування","де знайти талісман псування","як отримати талісман"}},{q="Як виманити власника талісмана?",a="Треба зібрати зразки фруктів, зерна й горіхів фурболгів, змішати їх із водою з місячного колодязя в очисній чаші й поставити підношення біля вогнища коло річки. Очищення фурболгів доводить Ксабраксіса до сказу, і він нападає.",al={"як викликати хабраксіса","як знайти хабраксіса","викликати сатира на темному узбережжі"}},{q="Що стається з талісманом, коли його здобуто?",a="Його віддають Тундрісові Віндвіверу в Обердайні. Він бере артефакт під охорону, щоб знищити, і вивчає його, аби дізнатися, як назавжди звільнити фурболгів від демонічної скверни.",al={"кому віддати талісман","здати талісман псування","талісман тундріса віндвівера"}}},fp="22,246,20.589.0,17.468.1,35.151.0,25.138.0,46.240.0,51.181.0"}
P.entries["item:tallonkai-s-jewel"] = {n="Самоцвіт Таллонкая",s="Самоцвіт Таллонкая — світний смарагд, украдений із зачарованого друїдського талісмана на Тельдрассилі. Ним дорожить містик фурболгів Фероцитас, Пожирач Снів, і саме він — ключове осердя, потрібне, щоб полагодити Смарагдовий Ловець Снів.",h="Самоцвіт Таллонкая — світний смарагд, украдений із зачарованого друїдського талісмана на Тельдрассилі.",kw={"самоцвіт таллонкая","смарагд","фероцитас","пожирач снів","смарагдовий ловець снів","таллонкай свіфтрут","вузлошкіри"},ang={["class:Druid"]="Смарагд — настроєна друїдська складова, створена резонувати зі Смарагдовим Сном, тож зловживання ним споганеними фурболгами — образа рівновазі.",["race:NightElf"]="Повернення самоцвіта допомагає відновити лад на Тельдрассилі, вирвавши священний виріб із рук напосідливої Вузлошкірів."},sec={{t="Украдене осердя",b="Таллонкай Свіфтрут створив Смарагдовий Ловець Снів як могутній осередок, настроєний на природу й царство сну. Коли талісман пошкодили, центральний сяйливий смарагд вийняли й понесли в нетрі східного Тельдрассила. Самоцвіт потрапив у лапи Фероцитаса, Пожирача Снів, — споганеного ватажка Вузлошкірів, який зробив із блискучого каменя власне намисто. Хоч зелений камінь кидав моторошне світло в лісовому присмерку, його справжній гармонійний відгук був фурболгові геть ні до чого, і доки самоцвіт не повернули, він лишався простим трофеєм."}},faq={{q="Що таке Самоцвіт Таллонкая?",a="Це зачарований сяйливий смарагд — серцевина Смарагдового Ловця Снів, друїдського фокусу, який виготовив Таллонкай Свіфтрут у Доланаарі.",al={"що за самоцвіт","лор самоцвіту таллонкая"}},{q="Хто викрав Самоцвіт Таллонкая?",a="Його викрав Фероцитас, Пожирач Снів, — один із ватажків осквернених містиків-Вузлошкірів, що живуть на північ від Села Зоряного Вітерця.",al={"у кого самоцвіт","хто викрав","хто забрав самоцвіт таллонкая"}},{q="Чи можуть фурболги-Вузлошкіри скористатися силою самоцвіту?",a="Ні. Хоч Фероцитас і носив смарагд на шиї як сяйливу прикрасу, Таллонкай зауважує, що друїдська сила каменя для оскверненого фурболга цілком марна.",al={"чи фурболги можуть використати сили","сила смарагду ґнарлпайнів"}},{q="Куди самоцвіт потрапляє, коли його повернуто?",a="Камінь повертають Таллонкаєві Свіфтруту на верхньому ярусі Доланаара, і той за його допомогою повністю відновлює пошкодженого Смарагдового Ловця Снів.",al={"що буде з самоцвітом","лагодження ловця снів"}}},fp="17,232,13.559.0,26.155.0,28.128.0,49.173.0,46.152.0"}
P.entries["item:taming-rod"] = {n="Жезл Приборкання",s="Жезл Приборкання — навчальне знаряддя, яке наставники довіряють мисливцям-новачкам. Наділений простою зв'язувальною магією, він дає учневі тимчасово втихомирити тутешню звірину й керувати нею, щоб опанувати основи поводження зі звірами.",h="Жезл Приборкання — навчальне знаряддя, яке наставники довіряють мисливцям-новачкам.",kw={"жезл приборкання","мисливець","приборкання","тотар","гострий пагорб","звір","улюбленець"},ang={["class:Hunter"]="Жезл Приборкання — наріжний камінь обряду переходу кожного молодого мисливця, свого роду підпірка, доки ви не матимете природженої сили волі, щоб творити довічні зв'язки з дикими звірами.",["faction:Horde"]="У Дуроторі й Малгорі наставники на кшталт Тотара вживають ці жезли, щоб перевірити, чи мають молоді новобранці дисципліну, потрібну, щоб опанувати сувору звірину Калімдору."},sec={{t="Навчальне знаряддя наставника",b="Мисливці-новачки не можуть одразу прикласти силу волі, потрібну, щоб назавжди прив'язати дике створіння. Щоб здолати цей розрив, досвідчені наставники видають особливі Жезли Приборкання. У місцях на кшталт Гострого Пагорба наставники, як-от Тотар, дають майбутнім оркам і тролям-мисливцям ці зачаровані знаряддя, щоб приборкати тутешніх хижаків — лютих плямистих вепрів чи броньованих скорпідів. Жезл тимчасово втихомирює звіра, і приборкувач може вправлятися в командах і битися пліч-о-пліч із тваринним супутником без ризику, що передчасно виникне нерозривний первісний зв'язок."},{t="Крок до майстерності",b="Влада, яку дає Жезл Приборкання, швидкоплинна: зазвичай вона тримається недовго, доки магія не згасне. Кожен жезл налаштований на певні види диких звірів і слугує сходинкою в низці випробувань. Щойно новачок доводить, що здатен керувати різними дикими вдачами — від сумирних шукачів поживи до агресивних отруйних мисливців, — жезл повертають наставнику. Довівши правильну техніку, учень нарешті опановує природжене мистецтво приборкувати, прикликати й відпускати довічних супутників без будь-якого артефакту."}},faq={{q="Для чого потрібен Жезл Приборкання?",a="Жезл Приборкання — навчальне знаряддя, яке наставники дають молодим мисливцям. Він на час утихомирює й зачаровує обраного звіра, щоб учень міг повправлятися керувати твариною в бою.",al={"що робить жезл приборкання","використання жезла приборкання","чому в мене жезл приборкання"}},{q="Чи лишиться в мене звір, якого я приборкаю жезлом?",a="Ні. Істоти, приборкані Жезлом Приборкання, лише тимчасово підкоряються для навчання. Щойно чари жезла вичерпаються або ви повернете жезл наставникові, зв'язок обірветься. Приборкати власного супутника назавжди ви навчитеся тільки після всіх випробувань.",al={"чи лишиться звір","чи залишу вепра","чи залишу скорпіда"}},{q="Чи можна будь-яким жезлом приборкати будь-яку тварину?",a="Ні. Кожен жезл зачаровано для певного етапу навчання й налаштовано на певну істоту, як-от лютий плямистий вепр чи броньований скорпід.",al={"чи діє жезл на будь-кого","цілі жезла приборкання"}},{q="Чи можна лишити Жезл Приборкання собі після навчання?",a="Ні. Виконавши доручення, жезл треба повернути наставникові мисливців. Коли ви повернете його після останнього випробування, наставник навчить вас самостійно приборкувати, викликати й відпускати звірів.",al={"залишити жезл приборкання","чи можна зберегти жезл"}}},fp="10,234,28.580.0,21.545.0,30.196.0,38.275.0,39.170.0,56.214.0"}
P.entries["item:taragaman-the-hungerer-s-heart"] = {n="Серце Тарагамана Голодаря",s="Серце Тараґамана Голодного — моторошний трофей, здобутий у вартового скверни, що панує в глибинах Провалля Лютого Вогню. Ніру Файрблейд вимагає цей мерзенний орган як доказ того, що демонічну присутність під Оргріммаром викорінено.",h="Серце Тараґамана Голодного — моторошний трофей, здобутий у вартового скверни, що панує в глибинах Провалля...",kw={"серце тараґамана","тараґаман голодний","ніру файрблейд","провалля лютого вогню","вартовий скверни","оргріммар"},ang={["class:Warlock"]="Справи з Ніру Файрблейдом і поводження з добутими демонічними рештками — знайома царина для чорнокнижників, які розуміють тонке павутиння тіней та обману, що плететься в Тіньовій Розколині.",["faction:Horde"]="Очищення тунелів під Оргріммаром оберігає молоду столицю від зіпсуття зсередини, тож відтяте серце звіра стає символом пильності Орди."},sec={{t="Трофей обману",b="Це паруюче демонічне серце, вирізане з грудей Тараґамана Голодного, — речовий доказ загибелі звірюки. Ніру Файрблейд запевняє і Тралла, і завзятих шукачів пригод, що саме Тараґаман стоїть за культистами Пекучого Клинка, які ховаються в Проваллі Лютого Вогню. Принесене Ніру серце нібито виконує наказ Вождя вберегти Оргріммар від демонічної скверни, але оголосити грубого вартового скверни справжнім творцем культу — дуже зручний спосіб приховати глибші мережі смертних, що діють під містом."}},faq={{q="Кому потрібне Серце Тарагамана Голодаря?",a="Ніру Файрблейд, орк-чорнокнижник із Тіньової Розколини в Оргріммарі, просить шукачів пригод принести йому серце як доказ того, що демона вбито.",al={"хто бере серце тарагамана","здати серце тарагамана","кому потрібне серце"}},{q="Де здобути це серце?",a="Серце забирають просто з тіла Тараґамана Голодного — грізного вартового скверни, що перебуває в центральних магмових залах Провалля Лютого Вогню під Оргріммаром.",al={"як отримати серце тарагамана","де падає серце тарагамана","місце серця тарагамана"}},{q="Чи бачить Тралл це серце?",a="Ні. Ви віддаєте серце просто Ніру Файрблейду, який запевняє, що як слід розпорядиться демонічними рештками й сам повідомить Вождя Тралла про перемогу від вашого імені.",al={"чи тралл отримає серце","віддати серце траллу","тралл серце тарагамана"}},{q="Чи справді Тараґаман був ватажком Пекучого Клинка?",a="Ніру Файрблейд називає цього вартового скверни ватажком Пекучого Клинка й наполягає, що смерть демона та його серце вдовольнять Тралла.",al={"чи тарагаман ватажок","хто очолює пекучий клинок","справжній бос тарагаман"}}},fp="30,231,18.544.1,41.162.0,29.167.0,31.167.0,52.142.1"}
P.entries["item:tattered-manuscript"] = {n="Подертий Манускрипт",s="Подертий Манускрипт — розрізнені понівечені аркуші, вирвані з єдиного примірника Фоліанта Кабали. Захована в курних глибинах південного Калімдору, ця пошарпана частина тексту містить таємні знання, вкрай потрібні чорнокнижникам, що прагнуть влади над мисливцями Скверни.",h="Подертий Манускрипт — розрізнені понівечені аркуші, вирвані з єдиного примірника Фоліанта Кабали.",kw={"подертий манускрипт","фоліант кабали","запліснявілий фоліант","твердиня розщепленого копита","мисливець Скверни","чорнокнижник","кентаври ґалак"},ang={["class:Warlock"]="Здобути манускрипт — важливий обряд посвяти для молодих чорнокнижників: він дає знання, потрібні, щоб підкорити своїй волі хижих мисливців Скверни."},sec={{t="Понівечений гримуар",b="Колись Фоліант Кабали був цілим, єдиним у своєму роді томом, що зберігався в занепалому королівстві Лордерон. Та одного дня невідомий осквернитель вирвав майже половину трактату просто з палітурки. Уцілілий корінець і решту книги — тепер відому як Запліснявілий Фоліант — повезли морем на південь, до Каз Модану, і вони загинули в морі, а ці вирвані пергаментні аркуші занесло через Велике Море аж до Калімдору, де вони зрештою потрапили до рук кентаврів Ґалак у Твердині Розщепленого Копита."},{t="Повернення слів",b="Захований у пошарпаній скрині глибоко в лабіринтових печерах Твердині Розщепленого Копита, манускрипт пережив суворі сухі вітри Тисячі Голок. Попри крихкий, подертий стан, послідовники темних мистецтв — і чорнокнижники Альянсу, що працюють із Кромом Стаутармом в Айронфорджі, і чорнокнижники Орди, яких наставляє Джора Аннісон в Андерсіті, — кидають виклик агресивним кентаврам, щоб з'єднати ці загублені аркуші із Запліснявілим Фоліантом. Зібраний докупи трактат містить темні обряди, потрібні, щоб викликати й підкорити демонічного мисливця Скверни."}},faq={{q="Що таке Подертий Манускрипт?",a="Це збірка подертих пергаментних аркушів — приблизно половина Фоліанта Кабали, легендарного й єдиного у своєму роді гримуара з демонології.",al={"лор подертого манускрипту","що таке манускрипт","сторінки тому кабали"}},{q="Як ці сторінки опинилися в Тисячі Голок?",a="Коли гримуар понівечили в Лордероні, вирвані сторінки якимось чином перетнули море й потрапили до кентаврів Ґалак, які сховали їх у скрині у Твердині Розщепленого Копита.",al={"чому в сплітгуф","том кентаврів","манускрипт тисяча голок"}},{q="Для чого потрібен манускрипт?",a="Чорнокнижники мають поєднати Подертий Манускрипт із розмоклим Запліснявілим Фоліантом, щоб відновити повний текст Фоліанта Кабали й відкрити ритуал виклику мисливця Скверни.",al={"навіщо мені манускрипт","сторінки завдання ловця скверни"}},{q="Хто розірвав первісну книгу?",a="Винуватець досі невідомий. І Кром Стаутарм в Айронфорджі, і Джора Аннісон в Андерсіті нарікають на цю наругу й не можуть збагнути, хто міг так учинити з неповторною науковою працею.",al={"хто розірвав том","хто зіпсував том кабали"}}},fp="19,273,21.495.0,20.540.0,32.140.0,47.190.0,32.178.0,56.197.0"}
P.entries["item:tazan-s-satchel"] = {n="Сумка Тазана",s="Сумка Тазана — замкнена торба троля Тазана, що діє разом із піратами біля Раджета. У ній — таємні відомості, яких прагне Розтрощена Рука, потайна гільдія розбійників з осідком під Оргріммаром.",h="Сумка Тазана — замкнена торба троля Тазана, що діє разом із піратами біля Раджета.",kw={"сумка тазана","тазан","ґамон","терзок","розтрощена рука","раджет","пірати"},ang={["class:Rogue"]="Здобути сумку й визволити ключ із кишені Ґамона — справжній обряд посвяти для розбійників Орди, що заслуговують на місце в Розтрощеній Руці.",["faction:Horde"]="Пошуки сумки показують напругу в Оргріммарі: Розтрощена Рука шукає таємної переваги, тоді як Вождь Тралл тримається виваженішого курсу."},sec={{t="Таємниці Пусток",b="Серед випалених сонцем просторів Пусток троль на ім'я Тазан проворачує темні оборудки з піратами, що отаборилися на узбережжі біля Раджета. Ці підкилимні домовленості привернули пильний погляд Терзока — майстра гільдії Розтрощеної Руки, що сидить у підземному мороці Тіньової Розколини. Прагнучи здобути таємну силу осторонь обережної дипломатії Вождя Тралла, Розтрощена Рука прирекла Тазана на смерть, щоб заволодіти цінними відомостями з його сумки."},{t="Хитрий замок",b="Здобути сумку — лише половина випробування для розбійника-початківця. Вона замкнена хитромудрим замком, і в полі її так просто не відкрити. Ключ Тазан довірив своєму спільникові Ґамонові — п'яничці, що днює й ночує в таверні Оргріммара. Посвяченим доведеться випробувати спритність рук: непомітно витягти ключ просто з кишені Ґамона, не здійнявши тривоги, і нарешті прочитати журнал Тазана."}},faq={{q="Кому належить ця сумка?",a="Сумка належить Тазанові — тролеві з Пусток, що веде таємні справи з піратами біля Раджета.",al={"хто такий тазан","власник тазана","власник сумки"}},{q="Навіщо Розтрощеній Руці Сумка Тазана?",a="Терзок і Розтрощена Рука прагнуть розширити свою мережу розвідки й повернути собі бойову гордість, діючи з тіні. Справи Тазана з прибережними піратами — цінні відомості, якими розбійники хочуть скористатися.",al={"навіщо тезрок сумка","сумка розтрощеної руки","навіщо красти сумку"}},{q="Де ключ, щоб відкрити сумку?",a="Тазан не носив ключа при собі, а лишив його на зберігання своєму спільникові — п'яному завсідникові таверни в Оргріммарі на ім'я Ґамон.",al={"як відкрити сумку","ключ тазана","де ключ"}},{q="Що в Сумці Тазана?",a="У замкненій сумці лежить журнал Тазана, де описано його таємні оборудки й зв'язки з прибережними корсарами.",al={"вміст сумки","що в сумці","журнал тазана"}}},fp="15,217,22.496.0,14.425.1,32.125.0,49.213.0,37.154.1,31.127.1"}
P.entries["item:tear-of-the-moons"] = {n="Сльоза Місяців",s="Сльоза Місяців — загадковий сяйливий кристал, який дворфи-копачі розкопали в Бель Модані на півдні Пусток. Дворфійська експедиція дуже ним дорожила, але кристал таїть мінливу, згубну силу, що прямо призвела до одержимості, вигнання й кровопролиття.",h="Сльоза Місяців — загадковий сяйливий кристал, який дворфи-копачі розкопали в Бель Модані на півдні Пусток.",kw={"сльоза місяців","фіґлі","бель модан","генерал твінбрейд","фортеця бел'дун","трог"},ang={["faction:Horde"]="Проникнувши до Фортеці Бел'дун по реліквію, ви завдаєте дошкульного удару військовій присутності Айронфорджа, що підступає до родових земель тауренів.",["race:Dwarf"]="Трагічна доля Фіґлі — похмуре застереження про підземні жахіття й прокляття-мутації, які Ліга Дослідників ризикує пробудити глибоко під Калімдором."},sec={{t="Відкопана реліквія",b="Кристал знайшли під час перших розкопок у Бель Модані, і його святкували як перший великий успіх експедиції. Дивне сяйво заворожувало копачів, але найбільше — Фіґлі. Запевняючи, що реліквія дарує йому неймовірну силу, Фіґлі потрапив під її владу. Побоюючись темного впливу артефакту — і стривожений дедалі химернішою поведінкою Фіґлі щодо товаришів, — командувач експедиції Генерал Твінбрейд оголосив камінь проклятим. Твінбрейд забрав реліквію, надійно замкнув її у своїй особистій скрині у Фортеці Бел'дун, а Фіґлі вигнав у безлюдні Пустки."},{t="Ціна одержимості",b="Не в змозі побороти жагу до сили кристала, вигнанець Фіґлі просить мандрівників з Орди пробратися до дворфійської фортеці й забрати Сльозу зі сховища Твінбрейда. Отримавши кристал і потерши його, Фіґлі починає дивно рохкати. Сльоза випадає з його рук і розбивається об землю, а сам він перетворюється на трога й невдовзі гине."}},faq={{q="Звідки взялася Сльоза Місяців?",a="Кристал викопали дворфи-шукачі й копачі на археологічних розкопках Бель Модану на півдні Пусток.",al={"походження сльози","де знайшли сльозу","історія сльози місяців"}},{q="Чому кристал замкнули у Фортеці Бел'дун?",a="Генерал Твінбрейд визнав артефакт проклятим, коли Фіґлі став одержимий ним і почав ворогувати з товаришами-копачами. Щоб уберегти експедицію, Твінбрейд замкнув кристал у своїй скрині.",al={"чому замкнули","скринька твінбрейда сльоза","чому твінбрейд взяв"}},{q="Що стається, коли Фіґлі отримує Сльозу назад?",a="Фіґлі жадібно хапає кристал і починає його терти. Що буде далі — фінал його історії, описаний у розділі, захищеному від спойлерів.",al={"фіґлі перетворюється на трога","що буде з фіґлі","перетворення фіґлі на трога"}},{q="Чи можна врятувати або полагодити Сльозу Місяців?",a="Остаточна доля реліквії з'ясовується, коли Фіґлі отримує її. Про те, щоб хтось потім її полагодив, у завданні не йдеться.",al={"чи можна зберегти сльозу","розбита сльоза","полагодити сльозу місяців"}}},fp="17,263,17.615.0,22.376.1,42.162.0,48.201.0,44.143.1,47.124.1"}
P.entries["item:tear-of-tilloa"] = {n="Сльоза Тіллоа",s="Сльоза Тіллоа — ніжна бліда квітка, що росте в тіні Сутінколісся. Її цінують за сильні алхімічні властивості, а тихо проростає вона на зарослих землях маєтку Містмантлів поблизу Даркширу.",h="Сльоза Тіллоа — ніжна бліда квітка, що росте в тіні Сутінколісся.",kw={"сльоза тіллоа","сталван містмантл","сутінколісся","зардет із чорного кігтя","лорд вішок","мускусний корінь"},ang={["class:Warlock"]="Цю невинну на вигляд квітку цінують окультисти під столицею: вона — дорогоцінний реагент для отрут, що змушують замовкнути надто допитливих вельмож.",["profession:Herbalism"]="Сльоза Тіллоа — рідкісна ботанічна дивовижа, що виживає лише в зачумленому мікрокліматі Сутінколісся, а не на звичайних пишних луках."},sec={{t="Сад у мороці",b="Серед зачумлених лісів, що підступають до Даркширу, Сльоза Тіллоа пускає коріння на землях маєтку Сталвана Містмантла. Хоч ґрунт Сутінколісся став ворожим до здорової рослинності, ця маленька біла квітка вперто тримається на затінених ділянках. Вона рідкісна й росте у відлюдному місці, тож привертає увагу тих, хто шукає реагентів, яких не знайти на законних ринках."},{t="Зілля для вельмож",b="Під гамірними вулицями Стормвінда Сльоза Тіллоа служить значно таємнішій меті. Зардет із Чорного Кігтя шукає цю квітку, щоб зварити особливий трунок для Лорда Вішока — члена Дому Вельмож, що погрожує розслідувати темні справи під столицею. Разом із Мускусним Коренем з-під Каменетесної Греблі з рослини готують зілля, яке має відвернути увагу Вішока й вивести його з ладу, перш ніж почнеться офіційне розслідування."}},faq={{q="Де росте Сльоза Тіллоа?",a="Цю квітку можна знайти на околиці Даркширу в Сутінколіссі, у зарослому саду маєтку родини Містмантл.",al={"місце сльози тіллоа","де сльоза тіллоа","місце тіллоа"}},{q="Кому потрібна Сльоза Тіллоа?",a="Зардет із Чорного Кігтя, що таємно діє під Стормвіндом, потребує квітку, щоб зварити особливе зілля.",al={"кому потрібна сльоза тіллоа","видавець завдання на сльозу тіллоа","хто її хоче"}},{q="Для чого потрібна квітка?",a="Це важливий алхімічний інгредієнт, який використовують разом із Мускусним Коренем. Разом вони дають сильне зілля, щоб знешкодити Лорда Вішока й заглушити його заклики розслідувати темні справи під столицею.",al={"призначення сльози тіллоа","що робить сльоза тіллоа","квітка благородного напою"}},{q="Хто такий Лорд Вішок?",a="Лорд Вішок — шляхтич із Дому Вельмож Стормвінда, який прочув про підривну діяльність під містом і почав домагатися від ради повного розслідування.",al={"вішок","хто такий вішок","лорд вішок"}}},fp="14,209,21.412.0,27.484.1,35.141.0,29.119.0,28.212.1,20.179.0"}
P.entries["item:techbot-s-memory-core"] = {n="Ядро Пам'яті Техбота",s="Ядро Пам'яті Техбота — поляризоване центральне сховище даних Техбота, механічного помічника Тінкмайстра Оверспарка. Вийняте з несправного автоматона в зіпсованих глибинах Гномреґана, воно містить вкрай важливі дані, за допомогою яких Оверспарк сподівається виправити зворотну, негатронну поведінку машини.",h="Ядро Пам'яті Техбота — поляризоване центральне сховище даних Техбота, механічного помічника Тінкмайстра...",kw={"ядро пам'яті техбота","техбот","тінкмайстер оверспарк","гномреґан","автоматон","негатронний"},ang={["profession:Engineering"]="Інженери оцінять химерні небезпеки позитронної поляризації, коли одне-єдине коротке замикання повністю перевертає логічні програми автоматона.",["race:Gnome"]="Для гномів Техбот — ще одна трагічна жертва падіння Гномреґана, що уособлює втрату блискучої мирної інженерії в хаосі руїни."},sec={{t="Поляризований мозок",b="До катастрофи, що вигнала гномів, Техбот служив Тінкмайстрові Оверспарку та його колегам-винахідникам незамінним помічником, напханим пристроями й енциклопедичними даними. Коли Гномреґан упав, випадковий електричний розряд ударив автоматона й перевернув його позитронний мозок у вороже негатронне становище. Збожеволілий від цієї зміни, Техбот тепер блукає зараженими залами міста й нападає на кожного, хто трапиться. Повернути ядро його пам'яті — єдина надія Оверспарка розібратися в несправності й повернути своєму улюбленому творінню розум."}},faq={{q="Що таке Ядро Пам'яті Техбота?",a="Це головне сховище даних і обчислювальний центр Техбота — автоматона, якого збудував Тінкмайстер Оверспарк. У ядрі зберігаються знання машини й записано електричний збій, що спотворив її поведінку під час падіння Гномреґану.",al={"ядро пам'яті техбота","мозок техбота","що таке ядро техбота"}},{q="Кому потрібне Ядро Пам'яті Техбота?",a="Ядро шукає Тінкмайстер Оверспарк. Знайшовши притулок у Містечку Майстрів в Айронфорджі разом з іншими гномами-вигнанцями, він просить сміливих шукачів пригод спуститися в Гномреґан, вимкнути Техбота й принести ядро, щоб спробувати його полагодити.",al={"кому потрібне ядро пам'яті техбота","хто бере ядро техбота","куди нести ядро техбота"}},{q="Чому Техбот збожеволів?",a="Під час падіння Гномреґану випадкова електрична іскра вдарила в позитронний мозок Техбота. Раптовий стрибок напруги змінив полярність механізму, зробивши його негатронним, і геть перевернув особистість і протоколи автоматона: з помічника він став шаленим нападником.",al={"чому техбот ворожий","що сталося з техботом","техбот збожеволів"}},{q="Де здобути ядро?",a="Ядро знімають із самого Техбота, що блукає верхніми механічними коридорами й входами занепалого Гномреґану в Дун Мороґу.",al={"де взяти ядро пам'яті","місце техбота","як отримати мозок техбота"}}},fp="21,310,17.566.0,30.241.0,32.237.0,27.257.0,27.155.0"}
P.entries["item:telescopic-lens"] = {n="Телескопічна Лінза",s="Телескопічна лінза — точна оптична деталь, яку Ґазлоу замовив здалеку, щоб добудувати обсерваторію Раджета. Біля узбережжя її перехопили пірати Південних морів, тож тендітне скло треба відбити в їхньому таборі на південь від містечка, перш ніж великий телескоп порту зможе оглядати небо.",h="Телескопічна лінза — точна оптична деталь, яку Ґазлоу замовив здалеку, щоб добудувати обсерваторію Раджета.",kw={"телескопічна лінза","ґазлоу","обсерваторія","раджет","флібустьєри південних морів","інженерія"},ang={["profession:Engineering"]="Для інженера ця точна лінза — зразок тонкого оптичного ремесла: без неї не сфокусувати далекоглядні механізми без сферичної аберації.",["race:Gnome"]="Гномські майстри можуть кепкувати з гоблінських ракет, але відданість Ґазлоу оптичній астрономії доводить: гоблінська інженерія — це не лише потужна вибухівка."},sec={{t="Очі, звернені до неба",b="Раджет відомий передусім як порт безжальної торгівлі, але його головний інженер і очільник Ґазлоу плекає й величніші механічні задуми. Його обсерваторію, що гордо здіймається над гаванню, збудували для потужного телескопа, який стежитиме і за морським рухом, і за небесними явищами. Більша лінза безпечно прибула суходолом із караваном із Дуротару, але важливу меншу лінзу відправили морем — і вона стала легкою здобиччю для Флібустьєрів Південних морів, що дошкуляють купецьким шляхам біля узбережжя Пусток."},{t="Піратська здобич",b="Коли транспортний корабель пішов на дно, пірати забрали все цінне, а тендітну оптику спакували в ящик із написом «Крихке — не кидати». Не здатні оцінити тонку роботу — чи просто не знаючи, кому її збути, — морські розбійники залишили лінзу серед мотлоху свого пляжного табору на південь від Раджета. Ґазлоу покладається на відважних шукачів пригод, які кинуть виклик головорізам, здобудуть неушкоджене скло й нарешті наведуть його оглядовий майданчик на різкість."}},faq={{q="Навіщо Ґазлоу ця лінза?",a="Вона потрібна Ґазлоу, щоб добудувати телескоп в обсерваторії Раджета. Обсерваторії потрібні дві лінзи: більша благополучно прибула суходолом із Дуротару, а менша, телескопічна, загубилася в морі.",al={"лінза ґазлоу","навіщо лінза","чому телескопічна лінза"}},{q="Хто викрав Телескопічну Лінзу?",a="Її пограбували Флібустьєри Південних морів — ватага пронирливих піратів-людей і гоблінів, що полюють на торгові судна біля Узбережжя Крамарів. Вони тримають лінзу в позначеному ящику у своєму прибережному таборі на південь від Раджета.",al={"хто взяв лінзу","у кого лінза","місце телескопічної лінзи"}},{q="Звідки лінза взагалі?",a="Її везли до Раджета морем, на відміну від її пари, що прибула суходолом із Дуротару. Вантажі до цього порту часто прибувають з-за Великого Моря або з південних гоблінських володінь на кшталт Буті Бей.",al={"де зробили лінзу","походження лінзи","де ґазлоу замовив лінзу"}},{q="Чи вціліла лінза, хоч її й викрали?",a="Дивом так. Лінза лежала в ящику з написом «Крихке — не кидати», який уберіг точне скло від грубого поводження піратів Південних морів.",al={"чи лінза розбита","крихкий ящик не кидати"}}},fp="15,304,15.515.0,14.467.0,32.224.0,30.230.0,40.211.0,43.171.0"}
P.entries["item:teronis-journal"] = {n="Щоденник Тероніса",s="Щоденник Тероніса — польовий записник, знайдений біля решток розвідника нічних ельфів в Ашенвалі. Він лежав поруч із загиблим дослідником, описує його пошуки таємничого самоцвіту й стає важливим доказом для вартових в Астранаарі.",h="Щоденник Тероніса — польовий записник, знайдений біля решток розвідника нічних ельфів в Ашенвалі.",kw={"щоденник тероніса","тероніс","рейн вульфраннер","самоцвіт","розвідник","астранаар"},ang={["faction:Alliance"]="Принесіть польові записи Тероніса до Астранаару — так гарнізон зможе організувати допомогу й повернути рештки свого загиблого розвідника.",["race:NightElf"]="Щоденник уособлює небезпечну службу розвідників нічних ельфів, які намагаються вберегти прадавні ліси Ашенвалю від порчі, що наступає."},sec={{t="Останній запис розвідника",b="Давній друг Рейн Вульфраннер, що допомагав вартовим, Тероніс вирушив у глушину Ашенвалю на пошуки самоцвіту для жезла, який, як він вірив, міг стримати напади фурболгів на його народ. Його справа раптово урвалася: він загинув у дорозі, оточений лютими істотами біля берега. Щоденник, знайдений серед його речей, напрочуд добре зберігся, попри жорстоку смерть власника. У ньому описано знахідки про сяйливий самоцвіт, що колись був частиною того жезла, — і захисники Астранаару отримують важливий слід, щоб довести його незавершену справу до кінця."}},faq={{q="Кому належав цей щоденник?",a="Щоденник належав Теронісові — нічному ельфу, другові Рейна Вульфраннера з Астранаару, який шукав в Ашенвалі спосіб стримати напади фурболгів. Його вбили в глушині, перш ніж він устиг повернутися зі своїми знахідками.",al={"хто написав щоденник","хто такий тероніс","лор тероніса"}},{q="Де знайти щоденник?",a="Щоденник знаходять серед речей Тероніса біля його тіла в диких краях Ашенвалю, неподалік від берегів, де живуть місцеві мурлоки.",al={"де знайти щоденник","місце щоденника тероніса","як отримати щоденник"}},{q="Навіщо нести щоденник до Астранаару?",a="Повернувши щоденник Рейнові Вульфраннеру, ви повідомляєте Астранаар про смерть Тероніса й передаєте Вартовим нотатки, потрібні, щоб продовжити його пошуки жезла, яким він сподівався стримати напади фурболгів.",al={"чому нести рейн","кому віддати щоденник","здати щоденник"}},{q="Який предмет шукав Теронис?",a="Теронис шукав сяйливий самоцвіт — одну з частин жезла, створеного покійним чарівником Дартолом. Його розслідування вказувало, що артефакт могли підібрати місцеві мурлоки.",al={"що шукав тероніс","який самоцвіт","самоцвіт тероніса"}}},fp="16,244,22.597.0,31.225.0,27.172.0,57.204.0,59.184.0"}
P.entries["item:tharil-zun-s-head"] = {n="Голова Таріл'зуна",s="Цей моторошний трофей — відрубана голова Таріл'зуна, ватажка скороходів Блекрок, що засіли в Кам'яній Варті. Маршал Марріс вимагає її як незаперечний доказ того, що командира, який тероризував підступи до Редріджу, вбито.",h="Цей моторошний трофей — відрубана голова Таріл'зуна, ватажка скороходів Блекрок, що засіли в Кам'яній Варті.",kw={"голова таріл'зуна","таріл'зун","блекрок","фортеця кам'яної варти","маршал марріс","лейкшир"},ang={["faction:Alliance"]="Кожен убитий ватажок Блекрок полегшує становище обложеного Лейкширу, який бореться за виживання без офіційного підкріплення зі Стормвінда."},sec={{t="Трофей Кам'яної Варти",b="Орки Блекрок, що окопалися у Фортеці Кам'яної Варти, нещадно тиснуть на Лейкшир: грабують ферми й влаштовують засідки на подорожніх. У першому ряду цих набігів ішли скороходи Блекрок, якими керував Таріл'зун. Гарнізон Лейкширу не може діяти на підставі чуток чи часткових перемог, тож Маршал Марріс вимагає переконливого доказу загибелі ватажка. Відрубана голова Таріл'зуна засвідчує, що злагоджені засідки з фортеці зазнали тяжкого удару."}},faq={{q="Хто такий Таріл'зун?",a="Таріл'зун був підступним і лютим орком-командиром клану Блекрок у Фортеці Кам'яної Варти. Він очолював розвідників і ренегатів Блекрок, що безупинно влаштовували засідки на шляху між Лейкширом і фортецею.",al={"лор таріл'зуна","хто такий таріл'зун","вожак таріл'зун"}},{q="Навіщо Маршалові Маррісу його голова?",a="Стормвінд не надсилає Редріджу серйозної військової допомоги, тож Маршал Марріс і варта Лейкширу покладаються на найманців, щоб ті усували головні загрози. Маррісові потрібен незаперечний доказ смерті Таріл'зуна, щоб знати напевно, що командування розвідників розгромлено.",al={"чому голова таріл'зуна","доказ голови для марріса","нагорода марріса"}},{q="Де знайти Таріл'зуна?",a="Таріл'зун утримує Фортецю Кам'яної Варти на східних пагорбах Гір Редріджу в оточенні орків Блекрок і гнолів.",al={"місце таріл'зуна","де таріл'зун","знайти таріл'зуна"}},{q="Чи зникне загроза Блекрок, якщо здобути голову Таріл'зуна?",a="Ні. Смерть Таріл'зуна зриває засідки розвідників, але клан Блекрок і далі тримає велике окопане військо у Фортеці Кам'яної Варти й по всіх Горах Редріджу.",al={"чи зникли орки","чи врятували редрідж","після таріл'зуна"}}},fp="17,233,20.525.0,19.209.0,38.254.0,26.117.0,55.177.0"}
P.entries["item:tharnariun-s-hope"] = {n="Надія Тарнаріуна",s="Надія Тарнаріуна — особлива пастка, яку змайстрував нічний ельф Тарнаріун Трітендер на Темному Узбережжі. Вона створена, щоб угамувати хвору звірину, а не скривдити її: пристрій випромінює заспокійливе світло, яке має приборкати скажених будякових ведмедів, щоб їх можна було оглянути й пошукати ліки.",h="Надія Тарнаріуна — особлива пастка, яку змайстрував нічний ельф Тарнаріун Трітендер на Темному Узбережжі.",kw={"надія тарнаріуна","тарнаріун трітендер","будякові ведмеді","пастка","друїд","темне узбережжя"},ang={["class:Druid"]="Пастка втілює ідеал Кола Кенарія — берегти, а не нищити: це відмова вбивати зіпсованих звірів, доки лишається бодай якийсь шанс на порятунок.",["race:NightElf"]="Занепад улюблених будякових ведмедів Темного Узбережжя б'є в саме серце зв'язку калдореїв із природою, тож цей пристрій — щемкий символ відчайдушного співчуття."},sec={{t="Лагідні сильця",b="Поки Темним Узбережжям шириться таємнича недуга, місцеві будякові ведмеді стають дедалі шаленішими й лютішими. Замість того щоб дозволити відстріл уражених звірів, друїд Тарнаріун Трітендер змайстрував цю незвичайну пастку, сподіваючись вивчити й вилікувати хворобу. Покладена на землю, Надія Тарнаріуна випромінює лагідне сяйво. Кожен скажений будяковий ведмідь, що ступить у її світло, на якийсь час утрачає шал і стає достатньо сумирним, щоб піти за шукачем пригод до табору Тарнаріуна на лікування."},{t="Невловні ліки",b="Пастка справді приборкує шалених звірів без жодної краплі крові, але прихована порча виявляється куди лютішою, ніж очікували. Коли Тарнаріун спрямовує в упійманого ведмедя свою цілющу магію, відновлювальна сила жорстоко зіштовхується з підступною заразою, і нещасний звір падає й гине. Попри гірку невдачу першої спроби, Тарнаріун запевняє, що не відступиться, доки не з'ясує справжньої природи лісової хвороби."}},faq={{q="Що робить Надія Тарнаріуна?",a="Це зачарована пастка, яку кладуть на землю, щоб утихомирити скаженого будякового ведмедя. Вона створює на лісовій підстилці поле світла, яке на час заспокоює ведмедя, що ступить у нього, і звіра можна мирно привести до Тарнаріуна Трітендера.",al={"що робить надія тарнаріуна","як працює пастка","що це за пастка"}},{q="Навіщо Тарнаріуну живий ведмідь?",a="Тарнаріун вірить, що хворобу, яка вразила звірів Темного Узбережжя, можна вилікувати, а не викорінювати бійнею. Йому потрібен живий звір, щоб безпосередньо випробувати свої очисні ліки.",al={"навіщо живий ведмідь","чому піймати скаженого ведмедя","чого хоче тарнаріун"}},{q="Чи можна отримати іншу пастку, якщо загубити цю?",a="Так. Тарнаріун запевняє мандрівників, що його надія незгасна. Якщо пастка спрацювала марно чи загубилася в лісі, варто повернутися до нього — і він дасть іншу, щоб довести справу до кінця.",al={"загубив надію тарнаріуна","невдала пастка","пастка зникла"}},{q="Що стається з ведмедем, коли його приведено?",a="Щойно ведмідь прибуває, Тарнаріун накладає цілющі чари, щоб вигнати скверну. На жаль, мерзенна хвороба надто глибоко вкоренилася: магія виявляється звірові не під силу, і він за мить помирає.",al={"чи ведмідь вижив","чи тарнаріун вилікує ведмедя","ведмідь помирає у тарнаріуна"}}},fp="17,267,14.550.0,18.506.1,31.252.0,46.186.0,40.176.0,49.197.1"}
P.entries["item:the-book-of-ur"] = {n="Книга Ура",s="Книга Ура — учений магічний трактат покійного даларанського чарівника Ура, де описано його дослідження дивних позавимірних істот. Залишена у Фортеці Шадовфенг, вона потрапила до рук Архімага Аруґала, а згодом привернула пильну увагу дослідників-Відступників в Андерсіті.",h="Книга Ура — учений магічний трактат покійного даларанського чарівника Ура, де описано його дослідження дивних...",kw={"книга ура","ур","даларан","кірін-тор","архімаг аруґал","фортеця шадовфенг","бел'дуґур"},ang={["class:Mage"]="Записи Ура — суворе нагадування про те, як далеко даларанська наука сягала в інші світи, — і про смертельні наслідки, коли честолюбні маги на кшталт Аруґала зловживають цим забороненим знанням.",["race:Undead"]="Здобувши працю Ура, ви прямо допомагаєте вченим Темної Леді в Апотекаріумі: обережні дослідження загиблого людського чарівника стануть для Відступників практичною силою."},sec={{t="Маг із Даларана",b="До того як Даларан упав перед Погибеллю, Ур славився серед Кірін-Тору своїми езотеричними дослідженнями інших площин буття й потойбічних створінь. Попри захоплення позаплощинною магією, Ур керувався обережністю й етичною стриманістю: він записував свої відкриття, а не прорізав необачно завісу між світами. На жаль, коли Погибель напала на фіалкове місто, ні його магічна вправність, ні моральні вагання не врятували його."},{t="Задуми Відступників",b="Після смерті Ура його записи потрапили до Архімага Аруґала, який скористався цими дослідженнями, щоб викликати до Срібнолісся жахливих воргенів. Тепер фоліант лежить на полицях Фортеці Шадовфенг. Звістка про нього привернула увагу Хранителя Бел'дуґура з Апотекаріуму Андерсіті. На відміну від автора книги, Відступники не мають жодних застережень щодо небезпечної, нестримної магії, якщо вона забезпечить їм виживання й завоювання."}},faq={{q="Хто такий Ур?",a="Ур був відомим магом-людиною з Даларана до Третьої війни. Він ґрунтовно досліджував інші виміри й позавимірних істот, але відмовлявся їх викликати через величезну небезпеку, яку вони становили.",al={"хто написав книгу ура","ур маг даларана"}},{q="Де знаходиться Книга Ура?",a="Книга лежить на полиці у Фортеці Шадовфенг у Срібноліссі — саме в покої, де живе величезний звір Фенрус.",al={"місце книги ура","де книга ура"}},{q="Навіщо Хранителеві Бел'дуґуру ця книга?",a="Хранитель Бел'дуґур збирає праці Ура для зацікавлених осіб в Андерсіті. Відступники вважають, що справжньої сили Урові не дало досягти сумління, і прагнуть використати його дослідження інших вимірів без жодних моральних обмежень, щоб зміцнити власну силу.",al={"хранитель бел'дуґур книга ура","навіщо андерсіту книга"}},{q="Як книга опинилася у Фортеці Шадовфенг?",a="Коли Ур загинув під час падіння Даларана, його праці дісталися Архімагові Аруґалу. У відчайдушних пошуках захисту від Погибелі Аруґал привіз нотатки до Срібнолісся й за теоріями виклику Ура закликав воргенів в Азерот.",al={"аруґал і книга ура","як аруґал отримав книгу"}}},fp="14,296,19.475.0,17.463.1,11.205.0,32.142.0,40.276.0,43.252.0"}
P.entries["item:the-collector-s-schedule"] = {n="Розклад Колекціонера",s="Розклад Колекціонера — рукописний графік із датами й часом незаконних перевезень золота, видобутого в копальнях Лісу Елвінн. Здобутий у тутешніх гнолів, документ відкриває, що невловима постать, відома лише як «Колекціонер», керує цією справою з-під Гарбузової Ділянки Брекуеллів.",h="Розклад Колекціонера — рукописний графік із датами й часом незаконних перевезень золота, видобутого в...",kw={"розклад колекціонера","золото","копальні","гарбузова ділянка","маршал дуґан","дефіас"},ang={["faction:Alliance"]="Розклад оголює, якою слабкою стала хватка Стормвінда на рідній землі: несанкціоновані ділки розкрадають природні багатства королівства просто за межами столиці.",["profession:Mining"]="Документ доводить, що попри звістки про бездіяльні копальні Елвінну, багаті жили золота активно спустошують і вивозять."},sec={{t="Крадене золото й таємні перевезення",b="Розклад дає тривожний доказ організованої діяльності просто під носом у гарнізону Стормвінда. Хоч королівство місяцями офіційно не розробляє копальні Елвінну через бандитство й напади чудовиськ, руду й далі планомірно видобувають і вивозять. У записці вказано конкретні дні й години, коли хтось на прізвисько «Колекціонер» приймає вантажі, і вона вказує на табір біля Гарбузової Ділянки Брекуеллів у східному Лісі Елвінн. Побачивши документ, Маршал Дуґан упізнає ім'я Колекціонера, та справжній замовник, що платить за крадене золото, лишається в тіні."}},faq={{q="Що таке Розклад Колекціонера?",a="Це знайдений документ із розкладом перевезень золота з покинутих шахт Лісу Елвінн до агента, якого називають «Колекціонер».",al={"що це за записка","розклад колекціонера","розклад золота"}},{q="Звідки взявся розклад?",a="Записку носять гноли, що заполонили береги річок і схили пагорбів Лісу Елвінн, — отже, вони або перехопили гінця, або якось причетні до перевезення золота.",al={"хто дропає розклад","де знайти розклад"}},{q="Хто такий Колекціонер?",a="The Collector is an agent stationed near the Brackwell Pumpkin Patch in eastern Elwynn Forest. The Classic schedule names the Defias Brotherhood and its headquarters in Westfall, although Marshal Dughan says he does not yet know whom the Collector works for.",al={"хто колекціонер","особа колекціонера"}},{q="Чому цей розклад стривожив Маршала Дуґана?",a="Уже кілька місяців Стормвінд не посилає офіційних шахтарів до шахт Елвінну через небезпеку. Те, що звідти досі вивозять чималі партії золота, свідчить про організований незаконний видобуток просто в межах королівства.",al={"чому дуґан стурбований","золото копалень ельвіна"}}},fp="24,319,32.610.0,33.163.0,33.189.0,21.258.0,47.261.0"}
P.entries["item:the-embalmer-s-heart"] = {n="Серце Бальзамувальника",s="Серце Бальзамувальника — нечестива реліквія, що б'ється в мертвому тілі Елізи, похованої глибоко в Сутінколіссі. Колись воно належало вбитому горем алхімікові, якого звуть Бальзамувальником; темна магія пересадила його, щоб воскресити покійну дружину, і серце стало головною опорою його спотвореної сили.",h="Серце Бальзамувальника — нечестива реліквія, що б'ється в мертвому тілі Елізи, похованої глибоко в...",kw={"серце бальзамувальника","бальзамувальник","еліза","даркшир","некромантія","сутінколісся"},ang={["class:Warlock"]="Пересадити ще живий, прив'язаний до душі орган, щоб утримати некромантичне неживе існування, — амбітний, хоч і хаотичний подвиг ремесла плоті й маніпуляції душами.",["race:Human"]="Трагічне падіння доброго алхіміка — похмура пересторога, яку пошепки переказують одне одному змучені мешканці Сутінколісся."},sec={{t="Кохання, що кинуло виклик смерті",b="За переказами Даркшира, Бальзамувальник колись був лагідним алхіміком, але розум його розколовся, коли померла кохана дружина Еліза. У відчайдушному прагненні повернути її з могили він звернувся до мерзенного чаклунства, вирізав власне серце й уклав його в бездиханні груди Елізи. Нечестива пересадка таки збудила її тіло до неживого існування, але воскресіння спотворило Елізу, обернувши на ненажерливу істоту з невситимим голодом до живої людської плоті, — і нажаханому алхімікові довелося знову поховати її в землі."},{t="Щит для Даркшира",b="Хоч серце й вирване з грудей, воно лишається джерелом незгасної темної сили Бальзамувальника й досі б'ється в гробниці Елізи. Мер Елло Ебонлок розуміє: лише знищивши оживлену наречену й забравши пульсуючий орган, можна позбавити Бальзамувальника чаклунства. Здобувши серце, доки воно ще б'ється, провід Даркшира сподівається обернути зловісну магію некроманта проти нього самого й використати її сутність як оберіг від його жахіть."}},faq={{q="Чому серце Бальзамувальника в Елізи?",a="Убитий горем через смерть дружини Елізи, Бальзамувальник за допомогою забороненої магії вклав власне живе серце в її тіло, щоб воскресити її. Ритуал повернув її до життя, але прокляв ненаситним голодом до людської плоті.",al={"чому серце в елізи","серце бальзамувальника в елізі","хто поклав серце в елізу"}},{q="Навіщо мерові Ебонлоку, щоб серце принесли до Даркширу?",a="Мер Елло Ебонлок хоче використати темну магію, що досі пульсує в серці, щоб звести над Даркширом захисний щит: так сила Бальзамувальника стане оберегом містечка.",al={"навіщо елло серце","план ебонлока з серцем","що даркшир робить із серцем"}},{q="Як Бальзамувальник живе без серця?",a="Темним чаклунством Бальзамувальник прив'язав свою життєву силу й могутність до пересадженого серця, тож він живе, навіть поки воно б'ється в похованому тілі його дружини.",al={"чи бальзамувальник живий","як бальзамувальник живе без серця"}},{q="Де знайти серце?",a="Серце б'ється в грудях Елізи, похованої в прихованій могилі в Сутінколіссі. Здобути його можна, лише здолавши ненажерливу оживлену наречену.",al={"де серце бальзамувальника","могила елізи","як отримати серце"}}},fp="20,293,24.551.0,22.491.1,41.225.0,66.220.0,48.204.0,29.172.0"}
P.entries["item:the-general-s-response"] = {n="Відповідь Генерала",s="Відповідь Генерала — офіційна військова депеша Генерала Маркуса Джонатана, командувача міської варти Стормвінда. Адресована Магістратові Соломону в Лейкширі, вона визнає прохання Редріджу про допомогу, але показує, що столиця не може — чи не хоче — негайно надіслати королівське підкріплення.",h="Відповідь Генерала — офіційна військова депеша Генерала Маркуса Джонатана, командувача міської варти...",kw={"відповідь генерала","генерал маркус джонатан","магістрат соломон","лейкшир","редрідж","стормвінд"},ang={["faction:Alliance"]="Відповідь показує, як розлазиться по краях Великий Альянс: віддалені поселення на кшталт Лейкширу спливають кров'ю, а двір Стормвінда дивно байдужий до їхньої біди.",["race:Human"]="Для людей південних королівств це загальмоване листування показує дедалі глибший розлам між громадянами, що борються за виживання в провінціях, і відгородженою знаттю у Фортеці Стормвінда."},sec={{t="Дипломатичний глухий кут",b="Коли Магістрат Соломон у відчаї звертається до Стормвінда, просячи війська проти кланів орків Блекрок і загонів гнолів, що збираються в Редріджі, він надсилає своє прохання просто верховному командуванню. Письмова відповідь Генерала Маркуса Джонатана — слабка розрада: прохання передали вище, до трону, але жодних солдатів наразі не відрядили. Затиснутий між статутом і політикою, генерал наказує доставити лист назад до Лейкширу, і Соломон лишається стривоженим і підозрює, що провід столиці паралізувала якась глибша недуга."}},faq={{q="Що написано у Відповіді Генерала?",a="Генерал Маркус Джонатан оплакує загиблих і обіцяє повідомити Короля про становище Лейкширу. Він сподівається надіслати підкріплення й довірчо зізнається, що Його Величність останнім часом рідко з'являється й поводиться дивно.",al={"зміст листа","що каже лист","лист генерала"}},{q="Чому Генерал Маркус Джонатан не може надіслати війська до Лейкширу?",a="Генерал Джонатан чекає відповіді від Короля, перш ніж обіцяти підкріплення. Довірчо він каже Соломонові, що Його Величність останнім часом рідко з'являється й поводиться дивно.",al={"чому немає підкріплення","чому стормвінд не допомагає лейкширу","чому немає допомоги"}},{q="Як Магістрат Соломон сприймає лист?",a="Магістрата Соломона лист глибоко стривожив. Повільність Стормвінда за такої страшної загрози Лейкширу здається йому незбагненною; він доходить висновку, що в королівстві коїться щось недобре, і боїться, що ця байдужість віщує ще гірші лиха.",al={"реакція соломона","що думає соломон","відповідь соломона"}}},fp="22,320,21.562.0,42.198.0,59.177.0,48.264.0"}
P.entries["item:the-lich-s-spellbook"] = {n="Книга Заклять Ліча",s="Книга Заклять Ліча — том некромантичних знань, що зберігається в скрині на острові посеред Озера Світлої Води. Здобута для Бетора Айсшарда в Андерсіті, книга розкриває справжню особу й величезну магічну силу ліча-відлюдника, який живе неподалік, на північ від столиці Відступників.",h="Книга Заклять Ліча — том некромантичних знань, що зберігається в скрині на острові посеред Озера Світлої Води.",kw={"книга заклять ліча","ґунтер арканус","бетор айсшард","озеро світлої води","ліч","некромантія","тірісфаль"},ang={["class:Mage"]="Ця книга заклять — незвичайний міст між класичним чарівництвом Даларана й темною некромантією: вона показує, як смертні заклиначі, піддавшись нежиттю, разюче розширили своє мистецтво.",["race:Undead"]="Книга доводить, що не всі, хто вирвався з-під влади Короля-Ліча, одразу пристали до Відступників, — і показує, яка недовіра досі живе серед вільних немертвих, розпорошених Тірісфалем."},sec={{t="Томи самотнього майстра",b="На відлюдному острові посеред Озера Світлої Води стоїть загадковий ліч в оточенні кістяних вартових. Хоча він має власну волю, цей чаклун не довіряє зовнішньому світові: усю іншу нежить він вважає рабами Погибелі й велить своїм слугам знищувати кожного, хто наблизиться. Бетор Айсшард, що шукає обдарованих некромантів, аби зміцнити лави Відступників під проводом королеви Сильвани Віндраннер, доручив посланцеві пробратися до табору на острові й забрати книгу заклять ліча. Вивчивши її, Бетор сподівався оцінити магічний хист майстра й дізнатися, ким той був до того, як смерть забрала Лордерон."},{t="Ґунтер Арканус без маски",b="Розгорнувши сяйливі сторінки здобутої книги, Бетор Айсшард зробив приголомшливе відкриття: самітник виявився його давнім другом і бойовим побратимом ще з часів до Третьої війни — Ґунтером Арканусом. Ґунтер і за життя був обдарованим некромантом, а його записи свідчили, що в нежитті його мистецтво стало ще грізнішим. Бетор зрозумів: якщо здобути вірність Ґунтера, Відступники отримають неоціненного майстра темних мистецтв — аби лише хтось переконав підозріливого ліча, що Відступники справді вільні від влади Короля-Ліча."}},faq={{q="Де знайти Книгу Заклять Ліча?",a="Книга лежить у скрині під назвою «Книги Ґунтера» в таборі на центральному острові Озера Світлої Води на півночі Галявин Тірісфалю.",al={"де книга","місце книги заклять","книги ґунтера"}},{q="Кому належить ця книга заклять?",a="Вона належить відлюдному лічеві з власною волею, що живе на острові посеред Озера Світлої Води. Бетор Айсшард сподівається, що її сторінки розкриють, хто такий власник і на що він здатен.",al={"чия це книга","особа ліча","хто написав книгу заклять"}},{q="Навіщо Беторові Айсшарду ця книга?",a="Бетор Айсшард хотів за книгою з'ясувати, хто такий таємничий ліч, і оцінити його майстерність у некромантії, сподіваючись залучити відлюдника на службу Леді Сильвані й Відступникам.",al={"навіщо книга","причина завдання бетора","навіщо андерсіту ця книга"}},{q="Чому ліч нападає на тих, хто приходить на його острів?",a="Ліч вважає, що вся інша нежить у краї досі лишається безвольними рабами Погибелі. Скутий підозріливістю, він велить своїм прислужникам нападати на кожного, хто наблизиться до його притулку.",al={"чому ґунтер ворожий","чому прислужники нападають","озеро брайтвотер ворожа"}},{q="Що Бетор сподівається дізнатися про автора?",a="Бетор сподівається з'ясувати, ким був відлюдний ліч за життя і чи можуть його знання некромантії допомогти Відступникам.",al={"що бетор дізнається","дослідження автора ліча","вивчення книги заклять бетором"}}},fp="20,288,26.593.0,25.555.1,36.159.0,24.167.1,39.194.0,48.187.0,48.121.1"}
P.entries["item:the-state-of-lakeshire"] = {n="Становище Лейкширу",s="Становище Лейкширу — термінова письмова доповідь Магістрата Соломона про відчайдушну військову кризу, що охопила містечко. Адресований безпосередньо Генералові Маркусу Джонатану в Стормвінді, документ благає столицю відрядити королівське військо, перш ніж поселення в Редріджі впаде.",h="Становище Лейкширу — термінова письмова доповідь Магістрата Соломона про відчайдушну військову кризу, що...",kw={"становище лейкширу","магістрат соломон","генерал маркус джонатан","стормвінд","лейкшир","болвар фордрагон"},ang={["faction:Alliance"]="Доповідь показує, наскільки вразливі віддалені поселення, і висвітлює політичну інертність, яка нині гальмує військову допомогу зі столиці.",["race:Human"]="Для людей королівства ця депеша підкреслює, як слабшають зв'язки між простим людом Редріджу й далекою короною в Стормвінді."},sec={{t="Крик про допомогу",b="У «Становищі Лейкширу», написаному Магістратом Соломоном під час безперервних нападів на Редрідж, змальовано тяжке становище містечка. Обложений ворожими орками Блекрок і гнолами, Лейкшир не має досить людей, щоб довго тримати кордони. Цю депешу, довірену надійним гінцям, що йдуть дорогою на захід до Лісу Елвінн, Соломон надсилає як офіційне прохання до війська Стормвінда втрутитися й зберегти східні землі королівства."},{t="Бюрократія і глухий кут",b="Коли доповідь доставляють Генералові Маркусу Джонатану біля брами Стормвінда, генерал визнає шляхетне становище Соломона й серйозність донесення. Проте Джонатан не може сам рушити військо. Для будь-якого походу потрібна явна згода корони, тож нагальне прохання Лейкширу мусить чекати наради на найвищому рівні — з юним королем і регентом Болваром Фордрагоном."}},faq={{q="Що таке Становище Лейкширу?",a="Це офіційне письмове донесення Магістрата Соломона, де описано військову небезпеку, що загрожує Лейкширу, і благання до Стормвінда надіслати підкріплення.",al={"документ становище лейкширу","що це за донесення","послання соломона"}},{q="Хто має отримати це донесення?",a="Звіт адресовано просто Генералові Маркусу Джонатану — командувачеві міської варти Стормвінда й королівських військ, що стоїть біля брами Стормвінда.",al={"хто отримує донесення","кому доставити","донесення маркуса джонатана"}},{q="Навіщо Лейкширу королівське підкріплення?",a="Містечко постійно атакують орки Блекрок, гноли Тіньової Шкури й місцеві мурлоки, і міська варта вже ледве тримається.",al={"чому лейкшир у небезпеці","що загрожує редріджу"}},{q="Чи надсилає Генерал Маркус Джонатан допомогу одразу?",a="Ні. Генерал погоджується, що криза серйозна, але не може вислати армію без офіційного схвалення Короля, тож прохання спершу має розглянути корона.",al={"чи стормвінд допоможе","чи джонатан надішле війська"}}},fp="22,321,13.466.0,24.381.0,31.159.0,41.153.0,45.142.0,51.179.0"}
P.entries["item:theramore-medal"] = {n="Медаль Терамора",s="Медаль Терамора — військова відзнака, яку носять бійці гарнізону Альянсу у Твердині Північної Варти. Позначені гербом Терамора, ці жетони засвідчують службу морських піхотинців і офіцерів, що боронять заставу на Узбережжі Крамарів.",h="Медаль Терамора — військова відзнака, яку носять бійці гарнізону Альянсу у Твердині Північної Варти.",kw={"медаль терамора","твердиня північної варти","терамор","тало'тас брайтсан","альянс","раджет"},ang={["faction:Alliance"]="Для прихильників Альянсу медалі Терамора, які збирають як криваву плату, — гірке нагадування про те, наскільки відрізаною від світу й войовничою стала Твердиня Північної Варти на рубежах Калімдору.",["faction:Horde"]="Шукачі пригод з Орди бачать у цих медалях речовий доказ того, що військова присутність Альянсу дедалі більше підступає просто до берегів Пусток."},sec={{t="Жетони Північної Варти",b="Ці карбовані медалі, які носять морські піхотинці, стрільці, командос і офіцери Твердині Північної Варти, засвідчують вірність Тераморові — королівству Леді Джайни Праудмур. Для людських солдатів, що засіли на скелях над Пустками, вони означають законну службу й владу у ворожому прикордонні. Проте для чужинців ці медалі — трофеї надто запопадливого чужоземного гарнізону, який бачить смертельну загрозу в кожному кораблі, що наближається до берега."},{t="Піратська помста",b="Гарматні батареї Твердині Північної Варти — смертельна небезпека для кораблів на Узбережжі Крамарів: вони раз у раз обстрілюють і каперів, і торгові судна. Утративши свої кораблі, капер із Раджета Капітан Тало'тас Брайтсан шукає ці медалі як доказ того, що скорі на постріл вояки Північної Варти заплатили кров'ю за його потоплені судна."}},faq={{q="Що таке Медаль Терамора?",a="Це відзнака військових Терамора, розміщених у Твердині Північної Варти. Вона засвідчує, що власник — морський піхотинець, моряк чи офіцер на дійсній службі в гарнізоні Альянсу в Пустках.",al={"медаль терамора","що таке медалі терамора","медаль північної варти"}},{q="Хто носить ці медалі?",a="Їх носять солдати Твердині Північної Варти на Узбережжі Крамарів: морські піхотинці, влучні стрільці, матроси, командос, а також старші каноніри й офіцери гарнізону.",al={"хто має медалі терамора","хто дропає медалі терамора","звідки медалі терамора"}},{q="Навіщо вони Капітанові Тало'тасу Брайтсану?",a="Гармати Твердині Північної Варти обстрілюють кораблі, що пропливають повз, зокрема судна флоту Капітана Брайтсана. Він вимагає медалей як незаперечного доказу того, що винних солдатів покарано смертю.",al={"навіщо рятчету медалі","медалі брайтсана","навіщо збирати медалі терамора"}},{q="Чому Твердиня Північної Варти обстрілює кораблі?",a="Гарнізон Північної Варти на межі з володіннями Орди охоплений дедалі більшою параноєю. Його канонірам ніби свербить рука на гніті: вони безрозсудно стріляють майже в кожне судно, що наближається до їхньої прибережної твердині.",al={"чому північна варта обстрілює кораблі","агресія північної варти","чому північна варта нападає на рятчет"}}},fp="15,272,20.486.0,16.343.0,26.197.0,25.185.0,48.235.0,47.224.0"}
P.entries["item:thick-bear-fur"] = {n="Густе Ведмеже Хутро",s="Густе Ведмеже Хутро — цінна шкура, зібрана із загартованих холодом ведмедів, що блукають заметами Дун Мороґу. Її цінують за те, як вона тримає тепло, і мандрівні розвідники й воїни часто роблять із неї утеплення й теплу постіль проти лютого гірського морозу.",h="Густе Ведмеже Хутро — цінна шкура, зібрана із загартованих холодом ведмедів, що блукають заметами Дун Мороґу.",kw={"густе ведмеже хутро","ведмідь","шкура","пілот беловфіз","джетстім","склад стілґрила","сиве лігво"},ang={["class:Hunter"]="Похід у холодні хащі на ведмедів Дун Мороґу вчить молодих мисливців давати раду небезпечним гірським звірам і добувати міцні матеріали з дикої природи.",["race:Gnome"]="Гномські пілоти облогових танків, що працюють біля Складу Стілґрила, мусять покладатися на практичне полювання дворфійського краю, щоб їхні машини витримували довгі високогірні розгортання."},sec={{t="Тепло проти гірського морозу",b="Ведмеді, що никають хребтами Дун Мороґу, зносять одні з найсуворіших снігових полів Східних Королівств. Їхні густі, витривалі шуби надійно захищають від заметілей, тож шкура — безцінний ресурс і для місцевих, і для мандрівників. Ці важкі шкури не викидають як непотріб: мисливці регулярно їх збирають, щоб підбивати одяг, утеплювати продувні застави й підкладати під холодні спальні згортки."},{t="Постіль для Облогової Бригади",b="Коли Пілот Беловфіз почав споряджати свій облоговий танк Джетстім на Складі Стілґрила, перед ним постала сувора перспектива провести цілий місяць у полі на довгому завданні Облогової Бригади. Холодне залізо дає мало затишку серед високогірних заметів, тож він доручив місцевим розвідникам зібрати густе ведмеже хутро на снігових полях на південь від Сивого Лігва, щоб зробити теплу постіль для своєї кабіни."}},faq={{q="Звідки береться Густе Ведмеже Хутро?",a="Густе Ведмеже Хутро збирають із місцевих ведмедів Дун Мороґу — передусім молодих чорних ведмедів і ведмедів Крижаний Кіготь. Вони полюють на засніженій тундрі та в соснових гаях на південь від Сивого Лігва.",al={"де взяти густе ведмеже хутро","хто дропає густе ведмеже хутро","місце ведмежого хутра"}},{q="Навіщо Пілотові Беловфізу це хутро?",a="Пілот Беловфіз споряджає свій танк «Реактивна Пара» до довгої, на цілий місяць, місії для Облогової Бригади. Йому потрібне густе хутро, щоб застелити теплу постіль у металевому корпусі й пережити люті гірські ночі.",al={"хутро беловфіза","навіщо беловфізу хутро","запас хутра"}},{q="Які створіння в Дун Мороґу дають таке хутро?",a="І молоді чорні ведмеді, і більші та лютіші ведмеді Крижаний Кіготь, що блукають засніженим нагір'ям, мають густе хутро, потрібне для теплої зимової постелі й утеплення.",al={"які ведмеді дають хутро","типи ведмедів дун морогу"}}},fp="14,263,33.420.0,29.411.0,36.207.0,39.226.0,45.164.0"}
P.entries["item:thistlenettle-s-badge"] = {n="Відзнака Тислнетла",s="Відзнака Тислнетла — офіційний знак дворфійської Ліги Дослідників, який Наглядач Тистлнеттл гордо ніс у глибини Мертвих Копалень. Після жахливого обвалу, навали злодіїв і неспокійних мерців тільки ця відзнака й може підтвердити трагічну долю наглядача його братові, що вцілів і живе в Стормвінді.",h="Відзнака Тислнетла — офіційний знак дворфійської Ліги Дослідників, який Наглядач Тистлнеттл гордо ніс у...",kw={"відзнака тислнетла","наглядач тистлнеттл","ліга дослідників","мертві копальні","дворфи","обвал"},ang={["faction:Alliance"]="Повернена відзнака дає спокій скорботному дворфові, що живе у Дворфійському Кварталі Стормвінда.",["race:Dwarf"]="Наглядач Тистлнеттл приніс до Вестфолу знамено й відзнаку Ліги Дослідників; повернувши її, ви не дасте темряві забрати пам'ять про полеглого сина Айронфорджа."},sec={{t="Ліга Дослідників у Мертвих Копальнях",b="До того як Братство Дефіас узяло під замок Мунбрук і печерні тунелі під ним, дворфійські старателі, пов'язані з Лігою Дослідників з Айронфорджа, вгризалися в старі золоті копальні Вестфолу. Наглядач Тистлнеттл і його бригада працювали глибоко під землею, доки раптовий обвал не розділив загін. Його братові Вайлдеру вдалося дістатися Стормвінда, а наглядач і кілька робітників лишилися замкненими в підземній темряві."},{t="Гірке підтвердження",b="Наглядач Тистлнеттл так і не знайшов ні гідного поховання, ні шляху на волю: він піддався темним силам, що визрівали в розпечатаних тунелях, і повстав бездумною потворою-нежиттю серед завалених шахт неподалік головної ливарні. Відзнака Ліги Дослідників так і лишилася при ньому — і, знайдена та віддана братові, що оплакує його, стала єдиним незаперечним доказом його смерті."}},faq={{q="Кому належить ця відзнака?",a="Відзнака належала Наглядачеві Тистлнеттлу — дворфу-шахтареві й членові Ліги Дослідників, що опинився в пастці глибоко під Вестфолом, коли раптом обвалився тунель.",al={"чия відзнака тислнетла","власник відзнаки тислнетла"}},{q="Де знайти відзнаку?",a="It is carried by Foreman Thistlenettle in the monster-infested upper corridors of the Deadmines, outside the main entrance to the Defias stronghold.",al={"місце відзнаки","як отримати відзнаку тислнетла","де знайти тислнетла"}},{q="Кому потрібна Відзнака Тислнетла?",a="Відзнаку несуть Вайлдерові Тістлнетлу, братові наглядача, що живе в Дворфійському Кварталі Стормвінда й чекає вістей про долю рідного.",al={"хто бере відзнаку тислнетла","хто здає завдання о брате","місце вайлдера тислнетла"}},{q="Що брати робили в Мертвих Копальнях?",a="Брати під егідою Ліги Дослідників обстежували й розвідували розлогі печери під Мунбруком, багаті на руди, доки ворожі злодії й обвали не зруйнували їхню експедицію.",al={"чому дворфи в мертвих копальнях","місія тислнетла в мертвих копальнях"}}},fp="21,348,38.447.0,19.414.1,30.179.0,25.148.0,32.165.0,53.213.0"}
P.entries["item:thresher-eye"] = {n="Око Молотильника",s="Око Молотильника — органічний зразок, здобутий у молотильників, що полюють у прибережних водах Темного Узбережжя. Такі очі шукає ексцентричний гном-інженер Візбанґ Кранктоґґл, щоб обслуговувати свої автоматичні польові пристрої — дзижчалки.",h="Око Молотильника — органічний зразок, здобутий у молотильників, що полюють у прибережних водах Темного...",kw={"око молотильника","молотильники","візбанґ кранктоґґл","дзижчалка","вино з повзунів","темне узбережжя"},ang={["profession:Engineering"]="Те, як Візбанґ латає складні механічні реле сирими частинами тварин, — дивовижний, хоч і кумедний приклад нестандартних гномських пристроїв.",["race:Gnome"]="Візбанґ Кранктоґґл — представник найдикіших околиць гномської винахідливості: він порпається в польових механізмах серед нетрів Калімдору між чарками вина з повзунів."},sec={{t="Екологічні зразки для гномських ґаджетів",b="Біля імлистих берегів Темного Узбережжя в прибої та на дальніх мілинах полюють водяні хижаки, відомі як молотильники Темного Узбережжя. Вони небезпечні для місцевих рибалок і мандрівників, а ще мають великі очні органи, що збудили дивний інтерес Візбанґа Кранктоґґла. Гном-інженер, який працює неподалік і дуже любить вино з повзунів, вимагає ці очі як неодмінні деталі для ремонту Дзижчалки 411 — автоматичного розвідувального апарата на північних пляжах."},{t="Навіщо ті очі",b="Візбанґ так і не пояснює до ладу, як слизькі очі морських тварин лагодять делікатні механізми — чи то як грубі оптичні лінзи, чи як хімічні реагенти, чи як езотеричні біологічні шестерні. Хай яка сумнівна ця інженерна логіка, три здобуті ока, закинуті в технічний люк Дзижчалки 411, успішно відновлюють зв'язок апарата, і Візбанґ може роздавати нагороди крізь трансляції, що потопають у тріску перешкод."}},faq={{q="Звідки беруться Очі Молотильника?",a="Очі Молотильника здобувають із молотильників і старих молотильників, що плавають у морі біля берегів Темного Узбережжя, особливо поблизу Обердайна.",al={"де падають очі молотильника","як отримати око молотильника","джерело очей молотильника"}},{q="Навіщо Візбанґові Кранктоґґлу Очі Молотильника?",a="Візбанґ запевняє, що очі потрібні, щоб полагодити «Дзижчальник 411» — гномську машину на березі на північ від Обердайна. Якщо вкласти їх у люк машини, її системи знову запрацюють.",al={"навіщо очі молотильника","очі дзижчальника 411","для чого очі молотильника"}},{q="Як око може полагодити машину?",a="Гномська інженерія часто кидає виклик звичайній логіці, особливо коли нею керують хмільні задуми Візбанґа Кранктоґґла. Чи то він використовує сітківку для оптичного фокусування, чи то просто вбудовує органічні частини у свої химерні винаходи, але пристрій їх приймає й знову вмикається.",al={"чому очі для машини","біологічні частини гномської машини"}},{q="Що таке «Дзижчальник 411»?",a="«Дзижчальник 411» — один із кількох пристроїв зв'язку й спостереження, які Візбанґ Кранктоґґл розставив по Темному Узбережжю. Коли в нього завантажити потрібні матеріали, Візбанґ може віддалено спілкуватися й видавати припаси.",al={"призначення дзижчальника 411","хто побудував дзижчальник 411"}}},fp="12,238,38.481.0,23.440.0,33.168.0,48.189.0,30.278.0,20.219.0"}
P.entries["item:thule-s-head"] = {n="Голова Тула",s="Голова Тула — моторошний доказ, якого вимагають Відступники, щоб пересвідчитися в загибелі Тула Рейвенклова, командира сил Погибелі на Острові Фенріс. Принесений Верховному Екзекуторові Гадреку в Гробницю, цей жахливий трофей зміцнює владу Відступників над Срібноліссям.",h="Голова Тула — моторошний доказ, якого вимагають Відступники, щоб пересвідчитися в загибелі Тула Рейвенклова...",kw={"голова тула","тул рейвенклов","острів фенріс","фортеця фенріс","верховний екзекутор гадрек","погибель","некромант"},ang={["faction:Horde"]="Знищення Тула Рейвенклова вбезпечує східні кордони Срібнолісся й захищає щойно здобуті землі Орди від вторгнень Погибелі.",["race:Undead"]="Для Відступників відтята голова Тула — водночас воєнна перемога й особиста помста хватці Короля-Ліча над Лордероном."},sec={{t="Трофей Острова Фенріс",b="Острів Фенріс — головний оплот Погибелі Короля-Ліча в Срібноліссі. З глибин Фортеці Фенріс некромант Тул Рейвенклов керує своїми легіонами гнилошкірих і посіпак-нежиті, прямо загрожуючи заставам Відступників на кшталт Гробниці. Верховному Екзекуторові Гадреку потрібна цілковита певність, що цей темний командир упав, і жодних свідчень, окрім відтятої голови Тула, він не приймає. Бурхливий вибух темної магії, коли Рейвенклов загинув, відчули по всьому лісі, але саме його голова — той речовий доказ, якого потребує командування, щоб оголосити Острів Фенріс зламаним."}},faq={{q="Кому потрібна Голова Тула?",a="Верховний Екзекутор Гадрек, що керує військовими операціями Відступників із Гробниці в Срібноліссі, вимагає Голову Тула як підтвердження, що ватажка Погибелі знищено.",al={"кому потрібна голова тула","кому здати голову тула","хто бере голову тула"}},{q="Хто такий Тул Рейвенклов?",a="Тул Рейвенклов — могутній некромант, що командує силами Погибелі на Острові Фенріс. Із серця Фортеці Фенріс він керує нападами на Відступників і володіє зловісними чарами, як-от Прокляття Рейвенклова.",al={"лор тула","хто такий тул","історія тула рейвенклова"}},{q="Чому Відступники вимагають саме його голову?",a="Відступники не можуть дозволити, щоб у Срібноліссі лишалася загроза від Погибелі. Некроманти славляться підступом і темними воскресіннями, тож Верховний Екзекутор Гадрек не прийме нічого, крім відчутного, незаперечного доказу, що Тула знищено остаточно.",al={"чому голова тула","чому хочуть його голову"}},{q="Що стається, коли Тул Рейвенклов гине?",a="Коли Тул падає, краєм прокочується бурхливий сплеск некротичної енергії — такий потужний, що вчені й аптекарі Відступників у Гробниці відчувають магічну хвилю здалеку.",al={"що буде після смерті тула","вивільнена енергія тула"}}},fp="12,275,21.591.0,23.178.0,24.229.0,49.242.0,43.202.1"}
P.entries["item:thunder-lizard-blood"] = {n="Кров Громоящера",s="Кров громоящера — життєдайна рідина, взята з величезних громоящерів, що блукають південними Пустками. Вона — бойовий доказ того, що мисливець вижив у сутичці з одними з найнищівніших наземних звірів Калімдору.",h="Кров громоящера — життєдайна рідина, взята з величезних громоящерів, що блукають південними Пустками.",kw={"кров громоящера","громоящери","табір тауражо","полювання","мисливець","пустки"},ang={["class:Hunter"]="Щоб здолати громоящера, потрібні стійка позиція й спритність; здобута кров доводить вашу владу над найбільшими звірами савани.",["race:Tauren"]="Для тауренських мисливців із Табору Тауражо двобій із громоящерами — давнє випробування на вміння вижити поруч із могутніми велетнями рідного краю."},sec={{t="Мисливський трофей",b="Громоящери, відомі на рівнинах як буреморди, бурешкури й громоголови, — велетенські звірі, від чиєї важкої ходи двигтить земля. Полювання на них — справа слизька: їхня нищівна вага легко розчавлює необачних мисливців. Принесена кров доводить не лише мисливську вправність, а й неабияку витривалість — адже треба вижити в бою під їхніми громовими ногами."}},faq={{q="Які створіння дають цю кров?",a="Кров здобувають із дорослих громоящерів, що блукають саваною довкола Табору Тауражо на півдні Пусток: штормоносів, штормошкірів і громоголовів.",al={"хто дропає кров громоящера","де взяти кров громоящера","які громоящери"}},{q="Навіщо шукають Кров Громоящера?",a="Джорн Скайсір у Таборі Тауражо доручає мисливцям зібрати кров у межах випробувань по всіх Пустках. Повернення з нею доводить, що мисливець здатен протистояти найбільшим тупотливим велетам Калімдору.",al={"хто хоче кров громоящера","призначення крові громоящера"}},{q="Де зазвичай водяться ці громоящери?",a="Вони блукають луками, що простягаються на північ, схід і південь від Табору Тауражо, і пасуться поряд з іншою великою живністю півдня Пусток.",al={"місця громоящерів","де штормморди"}}},fp="20,208,18.395.0,34.176.0,41.200.0,46.152.0"}
P.entries["item:thunder-lizard-horn"] = {n="Ріг Громоящера",s="Ріг громоящера — міцний трофей, здобутий із величезних громоящерів Пусток, що живуть у злагоді з блискавкою. Майстер Броварства Дрон у Раджеті шукає цей незвичний реагент, щоб відтворити легендарний напій, який колись вигадав Чень Бурештоф.",h="Ріг громоящера — міцний трофей, здобутий із величезних громоящерів Пусток, що живуть у злагоді з блискавкою.",kw={"ріг громоящера","громоящери","дрон","раджет","пиво","бурештоф"},ang={["class:Hunter"]="Вистежувати громоящерів на відкритій савані треба обережно: природні розряди блискавки роблять їх куди смертоноснішими за звичайних кодо чи степових довгоступів Пусток.",["profession:Cooking"]="Кулінари-мандрівники часто дивуються незвичному рецептові Майстра Броварства Дрона, у якому органи степових довгоступів, ікла хижаків і ріг звіра разом дають хмільний напій."},sec={{t="Могутній броварський реагент",b="Громоящери бродять посушливими рівнинами Пусток, і з їхніх гребенястих тіл з тріском зриваються розряди дикої блискавки. Мисливці часом полюють на їхні товсті шкури, але Майстер Броварства Дрон у Раджеті цінує їхні роги з зовсім іншої причини. Рецепт пива Бурештофа дістався йому від наставника, який навчився його в мандрівного пандарена, Майстра Броварства Ченя Бурештофа, і вимагає незвичних, міцних місцевих складників. Ріг громоящера додає тієї електричної сили, що дає легендарному трунку вогненний, незабутній присмак."}},faq={{q="Для чого потрібен ріг?",a="Майстер Броварства Дрон у Раджеті використовує ріг як важливий інгредієнт, щоб відтворити знамените пиво «Бурештоф», назване на честь Ченя Штормстаута й славетне своєю міцністю.",al={"використання рогу громоящера","що використовує ріг громоящера","навіщо мені ріг громоящера"}},{q="Які звірі дають ріг громоящера?",a="Ріг можна здобути з будь-якої породи громоящерів у Пустках: громоголовів, штормоносів, громотупів, штормошкірів, а також невловимого звіра Оватанки.",al={"де взяти ріг громоящера","хто дропає ріг громоящера","джерела рогу громоящера"}},{q="Хто такий Майстер Броварства Дрон?",a="Майстер Броварства Дрон — бровар, що працює в гоблінському порту Раджет. Його колишній наставник дізнався рецепт «Бурештофу» від самого славетного мандрівника Ченя Штормстаута й передав його Дронові.",al={"хто такий дрон","лор броваря дрона","дрон рятчет"}},{q="Чи небезпечно полювати на громоящерів заради рогів?",a="Громоящери — грізні звірі, які, коли їх роздратувати, від природи розряджають блискавки й гупають так, що аж гримить, тож добувати їхні роги — ризикована справа для самотнього мандрівника.",al={"наскільки міцні громоящери","полювання на громоящерів"}}},fp="19,253,24.552.0,26.153.0,41.165.0,24.197.0,54.192.0"}
P.entries["item:thunderhawk-saliva-gland"] = {n="Слинна Залоза Громояструба",s="Слинна залоза громояструба — могутній біологічний реагент, який добувають із великих громояструбів, що ширяють над Пустками. Майстер Броварства Дрон у Раджеті цінує її як головний складник, щоб відтворити вогненне Трогське пиво Ченя Бурештофа.",h="Слинна залоза громояструба — могутній біологічний реагент, який добувають із великих громояструбів, що...",kw={"слинна залоза громояструба","громояструби","трогське пиво","дрон","раджет","бурештоф"},ang={["faction:Horde"]="Полювання на лютих громояструбів у Пустках — випробувальний полігон для молодих воїнів, що мандрують Калімдором.",["profession:Cooking"]="Кулінарні пуристи можуть скривитися від слинних залоз, але винахідливі бровари вважають дивні тваринні екстракти певним шляхом до неперевершеного смаку й міцності."},sec={{t="Дикий складник",b="Посушливі савани Пусток — дім громояструбів, крилатих змієподібних істот, що славляться вмінням приборкувати саму бурю. Серед них старші й небезпечніші великі громояструби мають слинну залозу, сповнену первісної природної сили. Звичайні мандрівники тримаються від цих смертоносних звірів подалі, але вправні бровари знають рідкісні властивості цього органу й бачать у ньому надзвичайну основу для екзотичних напоїв."},{t="Таємні рецепти Ченя",b="Після того як легендарний бровар-мандрівник Чень Бурештоф пройшов Калімдором, Майстер Броварства Дрон оселився неподалік від Раджета, щоб опанувати дивовижні пандаренські способи бродіння. Щоб зварити Трогське пиво — вогненний трунок із неабияким ударом, що має загартувати витривалих шукачів пригод, — Дронові потрібні свіжа слинна залоза громояструба, блискавкові залози бурешкурів і печінка кодо."}},faq={{q="Де знайти Слинну Залозу Громояструба?",a="Її здобувають із великих громояструбів, що полюють над відкритими саванами Пусток.",al={"дроп слинної залози громояструба","де взяти слинну залозу","місце залози громояструба"}},{q="Для чого потрібна слинна залоза?",a="Її приносять Майстрові Броварства Дрону біля Раджета як ключовий складник для Трогського Пива — міцного напою за рецептом, який лишив Чень Штормстаут.",al={"використання слинної залози","призначення слинної залози громояструба","для чого слинна залоза"}},{q="Хто такий Майстер Броварства Дрон?",a="Дрон — майстер броварства, що живе біля порту Раджет. Навчившись мистецтва екзотичного пивоваріння в мандрівника Ченя Штормстаута, Дрон продає міцні елі шукачам пригод, які наважуються добувати інгредієнти серед місцевих звірів.",al={"дрон рятчет","хто такий дрон","лор броваря дрона"}},{q="Що таке Трогське Пиво?",a="Трогське Пиво — надзвичайно міцний напій, вигаданий Ченем Штормстаутом. Майстер Броварства Дрон варить його, поєднуючи слинну залозу великого громояструба, залози блискавки й печінку кодо в бадьорий трунок.",al={"лор трогського пива","що таке трогське пиво","трогське пиво чена"}}},fp="24,240,17.417.0,21.389.0,45.99.0,34.140.0,24.237.0,18.214.0"}
P.entries["item:thunderhawk-wings"] = {n="Крила Громояструба",s="Крила громояструба — пернаті трофеї, здобуті з лютих вітряних зміїв, що ширяють над центральними й південними Пустками. Принесені Джорнові Скайсіру в Табір Тауражо, вони остаточно доводять силу, хитрість і витривалість мисливця, який вистежив одного з найвеличніших хижаків савани.",h="Крила громояструба — пернаті трофеї, здобуті з лютих вітряних зміїв, що ширяють над центральними й південними...",kw={"крила громояструба","громояструби","вітряні змії","джорн скайсір","табір тауражо","мисливець"},ang={["class:Hunter"]="Здобуття крил громояструба — обряд посвяти, що підтверджує ваше вміння вистежувати, терпіння й влучність у боротьбі з прудкими повітряними звірами.",["race:Tauren"]="Для мисливців Тауражо здобуття цих крил — шана духові савани й вияв поваги до лютих створінь Земної Матері."},sec={{t="Мисливський трофей",b="Вітряні змії, яких місцеві мисливці звуть громояструбами, — грізні крилаті плазуни, що вміють блискавично атакувати згори. Для мисливців Табору Тауражо здобути пару цілих крил громояструба — щось набагато більше, ніж зібрати рештки здобичі: це вінець виснажливих мисливських випробувань у Пустках. Вистеживши повітряного хижака на відкритих рівнинах і здобувши його крила в бою, новачок доводить, що готовий ступити на довічний шлях справжнього мисливця."}},faq={{q="Де знайти Крила Громояструба?",a="Крила Громояструба здобувають із громояструбів, що ширяють над хребтами й рівнинами центральних і південних Пусток, особливо довкола Табору Тауражо.",al={"де взяти крила","місце крил громояструба","як отримати крила громояструба"}},{q="Кому потрібні ці крила?",a="Їх просить Джорн Скайсір, досвідчений мисливець-таурен із Табору Тауражо, як доказ того, що новачок опанував мисливські обряди савани.",al={"хто бере крила громояструба","здати крила громояструба","крила джорна скайсіра"}},{q="Що означає здобуття крил?",a="Принісши крила Джорнові Скайсіру, мисливець завершує складний обряд посвяти й доводить, що має досить сили, відваги й терпіння, щоб протистояти найгрізнішим хижакам неба.",al={"чому полювати на громояструба","призначення крил","значення полювання на громояструба"}}},fp="17,308,18.514.0,34.181.0,22.152.0,37.209.0"}
P.entries["item:thunderhorn-cleansing-totem"] = {n="Очисний Тотем Громорога",s="Очисний Тотем Громорога — освячене ритуальне знаряддя, виготовлене Маллом Тандергорном у Селі Бладгуф. Воно наснажене магією предків, щоб очистити осквернені води Водяної Криниці Тандергорнів.",h="Очисний Тотем Громорога — освячене ритуальне знаряддя, виготовлене Маллом Тандергорном у Селі Бладгуф.",kw={"очисний тотем","громоріг","тандергорн","малл тандергорн","криниця","очищення","шаман"},ang={["class:Shaman"]="Шамани знають, що очисні тотеми — провідники, які втихомирюють стривожених духів природи й відновлюють рівновагу там, де сили стихій озлобилися.",["race:Tauren"]="Для тауренів очищення прабатьківських криниць — не буденна робота, а священний обов'язок перед Матір'ю-Землею та предками клану, що пильнують Малгор."},sec={{t="Очищення криниці Тандергорнів",b="По хвилястих рівнинах Малгору життєдайну кров землі забруднює незрима скверна. Прабатьківські криниці, викопані племенами тауренів, живлять стада й мисливські угіддя, та підлі речовини отруїли воду. За дорученням старійшини Малла Тандергорна шукачі пригод несуть цей підготовлений тотем на північ від Села Бладгуф, щоб вигнати забруднення, яке осіло над священним джерелом клану Тандергорнів. Через ритуальне закликання тотем заспокоює стривожених духів води й очищає прабатьківське місце."}},faq={{q="Для чого потрібен Очисний Тотем Громорога?",a="Тотем виготовлено саме для того, щоб очистити осквернені води Водяної Криниці Тандергорнів на північ від Села Бладгуф. Він проганяє мерзенну силу, що отруює криницю, і тішить духів предків, які її оберігають.",al={"що робить тотем","навіщо тотем громорога","призначення очисного тотема"}},{q="Хто виготовив тотем?",a="Тотем виготовляє й дарує Малл Тандергорн — старійшина із Села Бладгуф, який дбає про здоров'я землі й спілкується з предками.",al={"хто зробив тотем","хто дає тотем громорога","тотем мулла тандергорна"}},{q="Де треба використати тотем?",a="Тотем треба використати просто біля Водяної Криниці Тандергорнів на північ від Села Бладгуф, у центрі Малгору.",al={"де використати тотем","місце тотема","де колодязь тандергорна"}},{q="Що стається після обряду?",a="Очищення криниці дарує спокій духам предків клану Тандергорн. Малл Тандергорн бачить уві сні їхню вдячність: предки славлять того, хто очистив їхні землі, і посилають йому дари.",al={"після очищення колодязя","результат обряду","реакція предків"}}},fp="27,211,30.543.0,55.239.0,22.170.0,29.115.0,43.221.1"}
P.entries["item:thurman-s-remains"] = {n="Рештки Турмана",s="Рештки Турмана — тілесні останки Турмана Аґаманда, здобуті на зруйнованих родинних млинах на півночі Галявин Тірісфалю. Колись заможний власник млинів, що переконав своїх робітників стати проти Погибелі, Турман піддався Чумі й никає колишнім маєтком рабом-нежиттю.",h="Рештки Турмана — тілесні останки Турмана Аґаманда, здобуті на зруйнованих родинних млинах на півночі Галявин...",kw={"рештки турмана","турман аґаманд","млини аґаманда","коулмен фартінґ","погибель","помста"},ang={["race:Undead"]="Для Відступників повернути ці рештки — похмуре зведення рахунків з аристократами-господарями, чия пиха привела їхніх робітників просто в лабети Погибелі."},sec={{t="Спадщина руїни",b="До Третьої війни родина Аґамандів була найзаможнішими землевласниками Галявин Тірісфалю: вона тримала великі млини й наймала десятки місцевих робітників. Коли Погибель прокотилася Лордероном, Турман Аґаманд із ріднею укріпив маєток замість тікати. Переконані, що багатство й укріплені млини витримають натиск, вони вмовили вірних робітників узятися за зброю поруч із ними. Оборона провалилася дощенту. Аґамандів і їхніх робітників вирізали й перетворили на безтямних слуг, якими володіє Король-Ліч. Нині Коулмен Фартінґ — колишній працівник, що повстав одним із Відступників, — вимагає знищити своїх колишніх господарів і хоче отримати рештки Турмана як доказ того, що нерозумний патріарх заплатив за загибель свого дому."}},faq={{q="Хто такий Турман Аґаманд?",a="Турман Аґаманд був помітним членом заможного роду Аґамандів, що володів Млинами Аґаманда на півночі Галявин Тірісфалю. Коли Погибель ударила по Лордерону, гордість штовхнула його переконати своїх робітників лишитися й битися — і через цей вибір усіх у маєтку вбили й підняли з мертвих.",al={"турман аґаманд","хто такий турман","ким був турман"}},{q="Навіщо Коулменові Фартінґу рештки Турмана?",a="Коулмен Фартінґ був робітником на млинах, довіряв Аґамандам і загинув, захищаючи їхній маєток. Тепер він серед Відступників і глибоко ненавидить колишніх господарів за те, що ті прирекли своїх робітників на нежиття, тож рештки Турмана для нього — помста.",al={"чому коулмен хоче рештки","мотив коулмена фартінґа","чому вбивати турмана"}},{q="Чи мав Турман власну волю, коли його знищили?",a="Ні. На відміну від Відступників з Андерсіті, Турман Аґаманд після смерті лишився під владою Погибелі й був бездумним прислужником, доки його не знищили на млинах.",al={"чи мав турман вільну волю","чи турман погибель","чи турман відступник"}},{q="Кого ще з роду Аґамандів переслідують?",a="Окрім Турмана, Коулмен Фартінґ прагне знищити Ґреґора Аґаманда й Ніссу Аґаманд і здобути їхні рештки, щоб покласти край роду, який колись володів млинами.",al={"інші аґаманди","члени родини аґаманд","цілі в родині мертвих"}}},fp="17,299,16.762.0,24.303.0,49.262.0,49.184.0,51.164.0"}
P.entries["item:thurman-s-sewing-kit"] = {n="Швацький Набір Турмана",s="Швацький Набір Турмана — маленька торбинка з голками й ножицями, потрібними учневі кравця в Стормвінді. Він належить Турманові Шнайдеру, який «випадково» залишив його вдома, біля каналів, щоб відкараскатися від довгого дня нудної кравецької роботи.",h="Швацький Набір Турмана — маленька торбинка з голками й ножицями, потрібними учневі кравця в Стормвінді.",kw={"швацький набір турмана","турман шнайдер","рема шнайдер","кравецтво","квартал магів","канали"},ang={["profession:Tailoring"]="Кожен кравець пам'ятає нудну рутину перших років учнівства, хоча мало хто доходив до того, щоб «загубити» ножиці, як юний Турман Шнайдер."},sec={{t="Знаряддя неохочого учня",b="У швацькому наборі — звичайне знаряддя учня кравця: голки, ножиці й нитки. Він належить юному Турманові Шнайдеру, який навчається кравецтва в майстерні Ларсонів углибині стормвіндського Кварталу магів, поблизу Вежі магів. Знаючи, що син не зможе працювати без своїх інструментів, його мати, Рема Шнайдер, просить чуйних перехожих біля Каналів віднести набір до майстерні. Реакція Турмана, коли він отримує набір, показує, що забув він ножиці й голки зовсім не випадково: це була невдала спроба вислизнути від шиття й погуляти."}},faq={{q="Що в Швацькому Наборі Турмана?",a="У наборі — найпотрібніші кравецькі інструменти, зокрема ножиці й голки, без яких Турман Шнайдер не впорається зі щоденними учнівськими обов'язками в кравецькій крамниці Ларсонів.",al={"що в наборі","вміст швацького набору","ножиці турмана"}},{q="Кому належить цей швацький набір?",a="Він належить Турманові Шнайдеру — юному учневі, що працює в Ларсонів у Кварталі магів Стормвінда.",al={"чий набір","власник турмана","хто такий турман"}},{q="Чому набір залишився вдома в Турмана?",a="Його мати Рема думала, що він просто поспіхом вибіг із дому, але Турман залишив набір навмисно: сподівався, що без нього його звільнять на день від роботи в Ларсонів.",al={"чому турман забув набір","чи турман забув навмисно","чому лишили швацький набір"}},{q="Куди треба доставити цей набір?",a="Його треба віднести до кравецької крамниці Ларсонів у глибині Кварталу магів Стормвінда, неподалік від Вежі магів.",al={"куди нести набір","місце швацької ларсона","місце турмана"}}},fp="20,275,30.575.0,36.187.0,35.106.0,46.192.0,41.133.0"}
P.entries["item:timberling-seed"] = {n="Насінина Деревляника",s="Насінини Деревляника — рослинні зерна, здобуті зі збурених рослинних елементалів, що населяють Тельдрассил. Природознавці й друїди вивчають ці насінини, щоб зрозуміти, чому лісова рослинність стала незвично напасливою.",h="Насінини Деревляника — рослинні зерна, здобуті зі збурених рослинних елементалів, що населяють Тельдрассил.",kw={"насінина деревляника","деревляник","елементалі","деналан","релліан ґрінспайр","озеро ал'амет","скверна"},ang={["class:Druid"]="Споганене насіння — ранні застережні знаки неприродної скверни, що розповзається рослинними елементалями Тельдрассила, і важлива турбота для захисників Ценаріонського Анклаву.",["profession:Herbalism"]="Для ботаніків і збирачів трав вивчення насінин показує, як сильно стан ґрунту й розлита скверна впливають на дику рослинність."},sec={{t="Насіння неспокійного лісу",b="Деревляники Тельдрассила — природні елементалі, чия вдача відбиває рівновагу Світового Дерева. Останнім часом ці створіння стали ворожими й гнівними, тривожачи нічних ельфів, що доглядають віття. Травники на кшталт Деналана біля Озера Ал'Амет гадають, що корінь лиха — у ґрунті, і збирають насінини диких деревляників у надії, що вирощені в контрольованих, очищених умовах, вони дадуть лагідне потомство."},{t="Укорінена скверна",b="Спроби виростити лагідних деревляників наштовхуються на похмуру дійсність. Коли зразки насіння оглядають учені Кола Кенарія, як-от Релліан Ґрінспайр у Дарнасусі, виринають глибші проблеми. Насіння несе скверну споганеного батьківського роду, а отже, неспокій рослинних духів Тельдрассила — не просто поганий ріст, а глибинна скверна, що охоплює живий світ усього великого дерева."}},faq={{q="Що таке Насінина Деревляника?",a="Насінина деревляника — зародок деревляника, рослиноподібного елементаля природи, що водиться по всьому Тельдрассилу. Натуралісти збирають це насіння, щоб вивчати ріст і спосіб життя деревляників.",al={"насіння деревляників","що таке насіння деревляників","насінина деревляника"}},{q="Де збирають це насіння?",a="Його збирають із диких деревляників і болотяних звірів, що блукають берегами й мілинами Озера Ал'Амет на Тельдрассилі.",al={"де взяти насіння","дроп насіння деревляника","хто дропає насіння деревляника"}},{q="Навіщо Деналанові насіння деревляників?",a="Деналан підозрює, що деревляники лютують через поганий ґрунт. Він хоче посадити дике насіння в особливо підготовлений ґрунт і перевірити, чи виростуть з нього лагідні, неосквернені деревляники.",al={"мета деналана","навіщо збирати насіння","план деналана"}},{q="Що Релліан Ґрінспайр з'ясовує про насіння?",a="Релліан з'ясовує, що в деревляниках укорінилася скверна і насіння несе в собі пошесть батьків. Він визнає, що зцілити його не в змозі, тож уся надія — на садівничі досліди Деналана.",al={"дослідження насіння релліана","що знайшов релліан","чи насіння опоганене"}}},fp="15,221,26.434.0,19.399.1,26.181.0,31.121.0,39.179.0,54.213.1"}
P.entries["item:timberling-sprout"] = {n="Паросток Деревляника",s="Паростки Деревляника — молоді, щойно народжені рослинні елементалі, що вкорінюються біля берегів Озера Ал'Амет на Тельдрассилі. Навіть у найпершому зростанні ці паростки виявляють ознаки скверни, тож наглядачі — нічні ельфи виривають їх, перш ніж вони визріють у напасливих деревляників.",h="Паростки Деревляника — молоді, щойно народжені рослинні елементалі, що вкорінюються біля берегів Озера...",kw={"паросток деревляника","деревляник","сіянці","озеро ал'амет","скверна","тельдрассил","елементалі"},ang={["class:Druid"]="Для друїдів, настроєних на рослинність та елементалів Калімдору, бачити природних лісових духів, що проростають із ґрунту вже споганеними, — похмуре знамення для майбутнього Тельдрассила.",["race:NightElf"]="Молодим нічним ельфам, що починають навчання в Тінедолі, доручають вичищати ці паростки, щоб уберегти свій новий лісовий дім."},sec={{t="Уражені сіянці",b="Деревляники — рослинні духи, тісно пов'язані з природною життєвою силою Тельдрассила, та сіянці, що проростають уздовж Озера Ал'Амет, стривожили тутешніх нічних ельфів. Замість сходити здоровими і в злагоді з дикою природою, вони проростають уже споганеними й напасливими. Оскільки ці немовлята-паростки, схоже, не піддаються ні очищенню, ні природному зціленню, доглядачі біля Озера Ал'Амет мусять збирати й знищувати їх, щоб запобігти нестримному поширенню ворожих деревляників крихким віттям новопосадженого Світового Дерева."}},faq={{q="Де знайти Паростки Деревляника?",a="Паростки Деревляника ростуть біля самої води на берегах Озера Ал'Амет, на південь від Доланаара на Тельдрассилі.",al={"місце паростків","де паростки деревляника","знайти паростки"}},{q="Чому нічні ельфи виривають Паростки Деревляника?",a="Паростки опоганені від самого початку. Якщо їх не чіпати, з них виростуть люті деревляники, що загрожуватимуть безпеці й рівновазі Тельдрассила. Оскільки зарадити їм уже не можна, доглядачі виривають їх, поки ті ще малі.",al={"чому вбивати паростки","призначення паростка деревляника","чому нищити паростки"}},{q="Чому паростки стають опоганеними?",a="Таємнича хвороба почала вражати звірів і рослинних елементалів Тельдрассила. Звідки береться пошесть, для ботаніка Деналана досі нерозгадана загадка, але вона вражає молодих деревляників із тієї миті, як вони пускають коріння.",al={"чому деревляники опоганені","що їх оскверняє","хвороба паростків"}},{q="Хто просить зібрати Паростки Деревляника?",a="Деналан, ботанік, що доглядає Озеро Ал'Амет, просить шукачів пригод зібрати й вирвати паростки з берега, щоб уберегти землю чистою.",al={"хто хоче паростки","видавець завдання на паростки","здати паростки деревляника"}}},fp="17,274,18.514.0,35.117.0,63.257.0,46.243.0,48.135.0"}
P.entries["item:tirisfal-pumpkin"] = {n="Гарбуз із Тірісфалу",s="Гарбузи з Тірісфалю ростуть на зораних грядках, що їх тримає Хутір Соллідена — господарство вцілілих живих людей, які силкуються вижити на уражених галявинах. Відступники регулярно вчиняють набіги на ці поля, щоб постачати Королівському Аптекарському Товариству органічну сировину для його безнастанних хімічних варив.",h="Гарбузи з Тірісфалю ростуть на зораних грядках, що їх тримає Хутір Соллідена — господарство вцілілих живих...",kw={"гарбуз із тірісфалу","хутір соллідена","фермери","вартовий смерті сіммер","аптекар йогаан","реагенти"},ang={["faction:Alliance"]="Гарбузи, вирощені на Хуторі Соллідена, — відчайдушні зусилля вцілілого люду Лордерону прогодуватися серед постійних наскоків Відступників.",["race:Undead"]="Набіг на городи Соллідена слугує двом цілям: позбавити решту живих смертних харчу й дати Аптекареві Йогаану матеріал для темних досліджень Відступників."},sec={{t="Урожай на ураженій землі",b="Попри зіпсуття, що осіло на Лордероні, на полях на захід від Брілла все ж якось сходять посіви. На Хуторі Соллідена живі фермери-люди чіпляються за свою землю й вирощують величезні помаранчеві гарбузи, а неподалік пильнує Багряний Хрестовий Похід. Для цих смертних урожай — життєво важливий харч. Для Відступників із сусіднього Брілла гарбузи — водночас і злостива ціль для саботажу, і запас сирих органічних реагентів, потрібних Аптекареві Йогаану."},{t="Реагенти для аптекаря",b="Вартовий Смерті Сіммер посилає молодих Відступників на спірні поля цупити гарбузи просто з-під носа у фермерів. Замість годувати мертвих, ці овочі потрапляють у киплячі казани Королівського Аптекарського Товариства. Аптекарі раз у раз перевіряють, як природна флора реагує на їхні чуми й дослідні суміші, обертаючи рештки землеробства Лордерону проти живих."}},faq={{q="Де знайти Гарбузи з Тірісфалю?",a="Вони ростуть на грядках Хутора Соллідена на захід від Брілла й трохи на північ від Похоронного Подзвону на Галявинах Тірісфалю.",al={"місце гарбузів","де гарбузи","гарбузи ферми соллідена"}},{q="Навіщо Відступникам ці гарбузи?",a="Вартовий Смерті Сіммер наказує їх викрасти, щоб позбавити припасів уцілілих людей і Багряний Хрестовий Похід, а також доставити Аптекареві Йогаану в Брілл як сирі органічні реагенти для аптекарських досліджень.",al={"навіщо красти гарбузи","гарбуз йогаана","для чого гарбузи"}},{q="Чи можна їсти Гарбузи з Тірісфалю або щось із них готувати?",a="Ні. Їх збирають лише як реагент завдання для Королівського Аптекарського Товариства, і в кулінарії вони шукачам пригод не знадобляться.",al={"чи можна їсти гарбузи тирисфалю","гарбуз для готування"}},{q="Хто їх зараз вирощує?",a="Живі фермери-люди досі обробляють землю на Хуторі Соллідена під слабким захистом Багряного Хрестового Походу з сусідньої дозорної вежі.",al={"хто власник ферми","фермери соллідена"}}},fp="16,289,26.481.0,19.421.0,37.123.0,42.202.0,47.129.0,30.144.0"}
P.entries["item:token-of-thievery"] = {n="Жетон Злодійства",s="Жетон Злодійства — доказ майстерності, який здобувають розбійники-новачки під час навчання в Горах Редріджу. Схований у замкненій скрині біля Млина Альтера, якому загрожують орки, він є останнім випробуванням від досвідченого злодія Луціуса, що перевіряє, чи опанували учні відмикання замків.",h="Жетон Злодійства — доказ майстерності, який здобувають розбійники-новачки під час навчання в Горах Редріджу.",kw={"жетон злодійства","луціус","млин альтера","розбійник","сертифікат злодійства","відмикання замків"},ang={["class:Rogue"]="Жетон Злодійства — важливий обряд посвяти для розбійників Альянсу: він доводить, що ви вмієте вправно орудувати відмичками й лишатися непоміченими в руїнах, де патрулює ворог."},sec={{t="Випробування спритності",b="Не кожен пройдисвіт має вроджений хист до того, щоб непомітно повертати штифти й відкидати засувки. У Лейкширі наставник розбійників Луціус перевіряє здібних учнів у справжній справі, випробовуючи їхню кмітливість і знаряддя. Замість того щоб проводити випробування в тихих завулках, Луціус ховає Жетон Злодійства в міцну скриньку серед руїн Млина Альтера — просто на шляху орків Блекрок, що наступають. Здобувши жетон, учень доводить, що здатен відімкнути надійний замок під загрозою смерті, і отримує офіційний Сертифікат Злодійства."}},faq={{q="Що таке Жетон Злодійства?",a="Це навчальний жетон, який Луціус замкнув у скрині біля Млина Альтера. Новачки-розбійники мають зламати замок і дістати його, довівши, що вже досить вправні, щоб відмикати замки в небезпечних умовах.",al={"використання жетона злодійства","що таке жетон злодійства","жетон луція"}},{q="Хто кладе жетон у скриньку?",a="Луціус, досвідчений наставник розбійників із Лейкширу, поклав його туди в межах своєї давньої програми навчання молодих розбійників.",al={"чий жетон","власник скриньки луція","хто сховав жетон"}},{q="Чому скриню поставили біля Млина Альтера?",a="Млин Альтера стоїть вище дорогою від Лейкширу, і там стало небезпечно через орків Блекрок, що никають довкола. Луціус обрав це місце, щоб учні вчилися швидко й тихо відмикати замки на ворожій території.",al={"чому млин альтера","причина скриньки в млині","небезпека біля млина"}},{q="Що дають в обмін на жетон?",a="Повернувши жетон Луціусу, розбійник отримує Сертифікат Злодійства на знак того, що опанував основи відмикання замків.",al={"нагорода за жетон","що дає луцій","сертифікат злодійства"}}},fp="17,290,17.606.0,30.219.0,34.142.0,41.226.0,46.134.0"}
P.entries["item:tome-of-the-cabal-quest-item"] = {n="Фоліант Кабали (предмет завдання)",s="Фоліант Кабали — гримуар, який Страгад Фарсан довіряє чорнокнижникам на кручах над Раджетом. Він містить небезпечні заклинання, потрібні, щоб витягти ненажерливого мисливця Скверни крізь Викривлений Нижній Світ і підкорити його волі заклинача.",h="Фоліант Кабали — гримуар, який Страгад Фарсан довіряє чорнокнижникам на кручах над Раджетом.",kw={"фоліант кабали","страгад фарсан","мисливець скверни","чорнокнижник","раджет","обряд виклику"},ang={["class:Warlock"]="Кожен, хто практикує темні мистецтва й прагне влади над демонічною магією, мусить опанувати цей фоліант, щоб здобути собі мисливця Скверни."},sec={{t="Ворота в Нижній Світ",b="Мисливці Скверни — люті звірі, що пожирають ману; їхня батьківщина — хаотичні простори Викривленого Нижнього Світу. Підкорити такого — обряд посвяти для досвідчених чорнокнижників, а обряди, що прорубують шлях для подібного звіра, записано на сторінках Фоліанта Кабали. Страгад Фарсан, досвідчений заклинач, який працює в Раджеті, дає фоліант лише тому, хто довів, що здатен зібрати рідкісні й небезпечні складники для його чарів."},{t="Обряд виклику",b="Виклик за фоліантом — аж ніяк не справа одинака. Страгад креслить у своєму святилищі головне коло виклику, а його учні за допомогою жезлів каналізування зводять довкола більшу захисну межу. Тоді чорнокнижник мусить точно прочитати заклинання з фоліанта, щоб затягти мисливця Скверни в наш світ, — і одразу ж битися з ненажерливим демоном, щоб підкорити його й утвердити над ним свою владу."}},faq={{q="Для чого потрібен Фоліант Кабали?",a="У фоліанті — ритуальні заклинання, якими викликають мисливця Скверни з Викривленого Нижнього Світу в особливо підготоване коло в Раджеті, щоб чорнокнижник міг зійтися з демоном і підкорити його.",al={"що робить фоліант кабали","призначення фоліанта кабали","фоліант ловця скверни"}},{q="Хто дає Фоліант Кабали?",a="Страгад Фарсан, наставник чорнокнижників, що живе на пагорбах над Раджетом у Пустках, дає книгу, коли учень виконає всі виснажливі підготовчі доручення.",al={"хто дає фоліант кабали","де взяти фоліант кабали","книга страгада"}},{q="Чи лишається фоліант у вас після ритуалу?",a="Ні. Коли викликаного мисливця Скверни переможено й вашу майстерність доведено, ви повертаєте Фоліант Кабали Страгадові Фарсану як доказ успіху.",al={"чи лишиться фоліант","нагорода фоліанта кабали","залишити фоліант кабали"}},{q="Чи можна викликати мисливця Скверни будь-де у світі?",a="Ні. Заклинання треба прочитати у святилищі Страгада Фарсана над Раджетом, де він і його послідовники підтримують велике й мале кола виклику, потрібні, щоб стримати звіра, щойно той з'явиться.",al={"викликати ловця скверни будь-де","де читати том","місце ритуалу фоліанта"}}},fp="30,247,23.478.0,20.392.0,39.189.0,35.165.0,49.148.0,51.202.0"}
P.entries["item:top-of-gelkak-s-key"] = {n="Верхівка Ключа Ґелкака",s="Верхівка Ключа Ґелкака — один із трьох уламків механічного ключа, що належав гномові Ґелкаку Джайромасту, який зазнав корабельної аварії. Коли його судно загинуло біля берегів Темного Узбережжя, цю зазубрену латунну частину вхопив велетенський лісовий довгоступ, що блукав сусідніми лісами.",h="Верхівка Ключа Ґелкака — один із трьох уламків механічного ключа, що належав гномові Ґелкаку Джайромасту...",kw={"верхівка ключа ґелкака","ґелкак джайромаст","лісовий довгоступ","темне узбережжя","механічний помічник","гном-пірат"},ang={["profession:Engineering"]="Ключ призначено, щоб заводити й запускати годинниковий автомат, — це взірець винахідливої й міцної механічної роботи, типової для гномських майстрів.",["race:Gnome"]="Бачити, як побратим-гном пережив страшну корабельну аварію завдяки чистій ексцентричності й годинниковим пристроям, — знайоме й зворушливе видовище."},sec={{t="Розбитий механізм",b="Коли ненажерливі трешадони напали на корабель Ґелкака Джайромаста біля Темного Узбережжя й потопили його, гнома викинуло на берег із заводним ключем для механічного першого помічника в руках. Від удару об прибережне каміння пристрій розлетівся на три частини. Не встиг приголомшений пірат отямитися, як місцеві звірі розтягли уламки, а велетенський лісовий довгоступ поніс цю оздоблену верхню частину в імлистий ліс."},{t="Відновити першого помічника",b="Ключ потрібен, щоб завести й запустити механічного першого помічника Ґелкака — автомат, за допомогою якого застряглий на березі гном хоче помститися місцевим звірам. Повернувши цей уламок разом із середньою й нижньою частинами, які поцупили прибережні мурлоки й рифові повзуни, Джайромаст зможе скласти пристрій і оживити свою конструкцію."}},faq={{q="Для чого потрібна Верхівка Ключа Ґелкака?",a="Це один із трьох уламків, які потрібні гномові-пірату Ґелкаку Джайромасту, що зазнав корабельної аварії, щоб полагодити свій механічний заводний ключ. Зібраним ключем він знову запускає свого механічного першого помічника.",al={"що відчиняє ключ ґелкака","використання верхівки ключа ґелкака","призначення ключа ґелкака"}},{q="Як ця частина ключа дісталася лісовому довгоступу?",a="Коли корабель Ґелкака розбився і його викинуло на пляжі Темного Узбережжя, ключ розтрощився об скелі. Цікаві звірі одразу ж кинулися нишпорити в уламках, і величезний лісовий довгоступ проковтнув або відніс верхню латунну частину до лісу на північний схід від берега.",al={"чому довгоступи мають ключ","хто взяв верхівку ключа ґелкака","як лісовий довгоступ отримав ключ"}},{q="Де інші частини ключа?",a="Середню частину вхопили мурлоки з племені Сірої Імли, що товчуться біля сусіднього затонулого корабля, а нижню забрали краби, що нишпорять уздовж лінії прибою.",al={"де інші частини ключа","середина й низ ключа ґелкака","уламки ключа ґелкака"}},{q="Хто такий Ґелкак Джайромаст?",a="Ґелкак Джайромаст — дивакуватий гном-пірат, що опинився на березі Темного Узбережжя, коли трешадони розтрощили його корабель. Застряглий і розлючений, він плекає помсту створінням узбережжя.",al={"хто такий ґелкак","лор ґелкака джайромаста"}}},fp="19,278,21.450.0,24.362.1,41.202.0,50.262.0,38.159.0,23.214.0"}
P.entries["item:torch-of-the-dormant-flame"] = {n="Смолоскип Сплячого Полум'я",s="Смолоскип Сплячого Полум'я — обрядове знаряддя, яке молоді шамани Орди несуть під час єднання з вогнем у Дуроторі. Він чекає на перемогу над проявом полум'я на вершині гори і слугує посудиною, що має вловити первісний стихійний вогонь у Святилищі Вічного Полум'я.",h="Смолоскип Сплячого Полум'я — обрядове знаряддя, яке молоді шамани Орди несуть під час єднання з вогнем у...",kw={"смолоскип","спляче полум'я","шаман","вогонь","святилище вічного полум'я","прояв вогню","дуротар"},ang={["class:Shaman"]="Сплячий смолоскип утілює ще не доведений стан посвячуваного; лише здолавши живий прояв полум'я, шаман може запалити його й заслужити право прикликати Вогняний Тотем."},sec={{t="Посудина пробудження",b="Шаману, що шукає прихильності вогню, довіряють незапалений Смолоскип Сплячого Полум'я, перш ніж він зійде на вершини над Дуротаром. Випивши вогняну сапту, що відкриває духів, шаман бачить Малий Прояв Вогню на вершині гори й кидає йому виклик. Перемога над цим духом стихії дає сяйливий жар, який кладуть у вивітрену жаровню Святилища Вічного Полум'я. Дотик головки сплячого смолоскипа до білого полум'я, що спалахує, пробуджує дерево й перетворює його на палаючий знак влади над стихіями."}},faq={{q="Для чого потрібен Смолоскип Сплячого Полум'я?",a="Це незапалений обрядовий смолоскип, який дають шаманам, що проходять випробування «Поклик Вогню». Коли прояв вогню переможено, а його жарину покладено в жаровню святилища, смолоскип занурюють у розпечене до білого полум'я, і він спалахує стихійною силою.",al={"що таке смолоскип сплячого полум'я","чому в мене незапалений смолоскип","що робить смолоскип"}},{q="Де запалюють цей смолоскип?",a="Його запалюють на вершині гори неподалік від Телфа Джулама в Дуротарі — у жаровні Святилища Вічного Полум'я, одразу після перемоги над Малим Проявом Вогню.",al={"де запалити смолоскип сплячого полум'я","святиня вічного полум'я смолоскип","як запалити смолоскип"}},{q="Хто дає незапалений смолоскип?",a="Шаман-відлюдник Телф Джулам дає смолоскип новачкам, які зібрали потрібні ритуальні реагенти, щоб приготувати вогняну сапту.",al={"хто дає смолоскип сплячого полум'я","джерело смолоскипа","видавець смолоскипа поклик вогню"}}},fp="26,290,19.554.0,54.251.0,30.187.0,29.134.0"}
P.entries["item:torn-fin-eye"] = {n="Око Подертого Плавця",s="Очі Подертих Плавців — органи зору, вирізані з мурлоків Подертих Плавців, що нишпорять берегами Передгір'я Гілсбреда. Для похмурих алхімічних досліджень Королівського Аптекарського Товариства над новими чумами вони — важливий реактивний складник.",h="Очі Подертих Плавців — органи зору, вирізані з мурлоків Подертих Плавців, що нишпорять берегами Передгір'я...",kw={"око подертого плавця","мурлоки","західне узмор'я","передгір'я гілсбреда","аптекар лайдон","еліксир агонії","таррен мілл"},ang={["faction:Horde"]="Збираючи ці прибережні реагенти, ви допомагаєте воєнним зусиллям Орди в Передгір'ї Гілсбреда й зміцнюєте позиції Відступників проти ворожих наступів Альянсу із Саутшора.",["race:Undead"]="Здобуваючи органічні каталізатори на кшталт Очей Подертих Плавців, ви прямо наближаєте найвищу мету Королівського Аптекарського Товариства — досконалу чуму, що зітре з лиця землі і Погибель, і живих."},sec={{t="Реагент для загибелі",b="Прагнучи створити Нову Чуму Відступників, Королівське Аптекарське Товариство рідко дає пропасти бодай якомусь мерзенному біологічному складникові. Очі Подертих Плавців, вирізані з укритих сіллю мурлоків, що нишпорять Західним Узмор'ям у Передгір'ї Гілсбреда, мають особливі органічні властивості, потрібні, щоб пробудити нестійкі алхімічні сполуки. У поєднанні з лускою наг Кинджалоспинних, тролячими еліксирами відновлення й гнолячим мулом ці зорові тканини допомагають стабілізувати й запустити отруйні суміші, створені, щоб сіяти смерть на ворожих землях."},{t="Варячи агонію",b="В Апотекаріумі Андерсіті майстри-алхіміки з'ясували, що для поєднання колоїдів розкладу з порошком багнорила потрібні каталізатори, які трапляються лише на узбережжі Гілсбреда. Аптекар Лайдон у Таррен Міллі покладається на ці очі, щоб каталізувати свій горезвісний Еліксир Агонії. Це вариво — один із невпинних дослідів Відступників зі створення нищівної біологічної зброї просто під носом у сусідніх людських поселень."}},faq={{q="Для чого потрібне Око Подертих Плавців?",a="Очі Подертих Плавців — алхімічний каталізатор, який шукає Королівське Аптекарське Товариство. Аптекар Лайдон у Таррен Міллі використовує їх разом із лускою Кинджалоспинів і Сильним Еліксиром Тролячої Крові, щоб активувати заразні речовини в нестійкій Суміші Багнорила й просунути свої дослідження нових смертоносних чум.",al={"використання ока подертих плавців","навіщо очі подертих плавців","призначення ока подертих плавців"}},{q="Де знайти Очі Подертих Плавців?",a="Їх здобувають із мурлоків Подертих Плавців, що живуть на Західному Узмор'ї Передгір'я Гілсбреда, просто вздовж узбережжя на захід від людського містечка Саутшор.",al={"де взяти очі подертих плавців","місце ока подертих плавців","хто дропає око подертих плавців"}},{q="Хто наказує збирати ці очі?",a="Дослідникам-Відступникам в Андерсіті й Аптекареві Лайдону в Таррен Міллі вони потрібні, щоб завершити зілля під назвою Еліксир Агонії.",al={"хто потребує очі подертих плавців","видавець завдання на очі"}},{q="Навіщо Королівському Аптекарському Товариству частини мурлоків?",a="Дослідники товариства безупинно експериментують із дивною місцевою живністю, шукаючи речовини, що активують або посилюють отруйні домішки. З очей мурлоків Подертих Плавців добувають рідину, здатну пришвидшувати дію нестійких зразків чуми.",al={"чому очі мурлоків","аптекарі мурлоки"}}},fp="12,233,18.538.0,13.450.1,32.304.0,32.169.0,39.153.0,56.250.0"}
P.entries["item:torn-murloc-fin"] = {n="Подертий Плавець Мурлока",s="Подерті Плавці Мурлоків слугують доказом виконаної роботи за постійною винагородою війська Стормвінда за ворожих земноводних у східному Лісі Елвінн. Здобуті в збирачів і причаєних на берегах річки, вони засвідчують, що тутешні водойми планомірно очищають.",h="Подерті Плавці Мурлоків слугують доказом виконаної роботи за постійною винагородою війська Стормвінда за...",kw={"плавець мурлока","мурлоки","вартовий томас","винагорода","річка","елвінн"},ang={["faction:Alliance"]="Очищення водойм східного Елвінну убезпечує життєво важливі шляхи між Ґолдширом, Лейкширом і Стормвіндом.",["race:Human"]="Тутешня людська влада дедалі більше покладається на найманців, щоб захистити садиби й береги річок від агресивних поселень мурлоків."},sec={{t="Загроза під винагородою",b="Коли кількість мурлоків на струмках і озерах східного Елвінну різко зросла, військо Стормвінда дозволило пряму винагороду, щоб прорідити їхні лави. Вартовий Томас, що стоїть на мосту через східну річку, збирає ці відтяті плавці, щоб підтвердити вбивства. Поки військо Стормвінда розтягнуте між внутрішніми заворушеннями й загрозами в краї, тутешня влада значною мірою покладається на мандрівних шукачів пригод, які приносять речові докази очищених таборів."}},faq={{q="Хто купує або збирає Подерті Плавці Мурлока?",a="Їх збирає Вартовий Томас біля східного мосту в Лісі Елвінн від імені Маршала Дуґана й армії Стормвінда.",al={"хто хоче плавці","здати плавці","плавці вартового томаса"}},{q="Де мурлоки, що мають ці плавці?",a="Їх здобувають із мурлоків-збирачів і мурлоків-причаєнців, що скупчилися довкола Озера Кам'яного Кургану на півночі та біля південного розгалуження струмка поблизу східного кордону Елвінну.",al={"де фармити плавці","місця плавців мурлока","дроп плавців"}},{q="Чому Стормвінд вимагає плавці як доказ?",a="Плавці — безпомилковий і зручний для перенесення речовий доказ того, що мурлока вбито, тож мисливці за нагородою гарантовано отримують заслужене від армії.",al={"чому плавці","доказ вбивства мурлоків","доказ нагороди"}},{q="Чому армія Стормвінда платить за мертвих мурлоків?",a="Поселення мурлоків швидко розрослися вздовж річок і загрожують мандрівникам, рибалкам і місцевим спорудам, а сили армії тим часом зайняті деінде.",al={"чому нагорода за мурлоків","проблема мурлоків ельвін"}}},fp="15,258,17.457.0,38.117.0,50.154.0,41.154.0,50.165.0"}
P.entries["item:totem-of-hawkwind"] = {n="Тотем Гоквінда",s="Тотем Гоквінда — різьблений знак, який носять молоді таурени, що покидають Табір Нарачі. Поданий Бейну Бладгуфу в Селі Бладгуф, він доводить, що його власник завершив перші випробування й готовий пройти решту Обрядів Матері-Землі.",h="Тотем Гоквінда — різьблений знак, який носять молоді таурени, що покидають Табір Нарачі.",kw={"тотем гоквінда","вождь гоквінд","бейн бладгуф","табір нарачі","обряди","малгор"},ang={["race:Tauren"]="Нести цей тотем — означає остаточно пройти обряд переходу від дитинства на Плато Червоної Хмари до ширших племінних земель Малгору."},sec={{t="Схвалення вождя",b="Вирізьблений рукою Вождя Гоквінда на Плато Червоної Хмари, цей дерев'яний тотем слугує рекомендацією й доказом пройденого шляху для молоді, що входить у зрілість. У традиції тауренів офіційні грамоти майже не вживають; натомість волю ватажка несуть значущі символи й знайоме племінне ремесло. Коли юнак, що прагне визнання, завершує попередні випробування, Табір Нарачі проводжає його в дорогу: Гоквінд вирізьблює цей знак, щоб послати його далі, у широкі простори Малгору. Прикметне різьблення засвідчує перед Бейном Бладгуфом, що його власник має дух і силу, потрібні для наступних випробувань і майбутнього благословення Тандер Блафу."}},faq={{q="Для чого потрібен Тотем Гоквінда?",a="Це знак переходу. Молоді таурени несуть його з Табору Нарачі до Села Бладгуф, щоб показати Бейнові Бладгуфу: Вождь Гоквінд визнав їх готовими продовжити Обряди Земної Матері.",al={"що робить тотем гоквінда","призначення тотема гоквінда","чому в мене цей тотем"}},{q="Хто зробив тотем?",a="Тотем власноруч вирізьбив Вождь Гоквінд, провідник поселення на Плато Червоної Хмари. Його особливу різьбу одразу впізнають вожді-союзники по всьому Малгору.",al={"хто вирізьбив тотем","майстер тотема","походження тотема гоквінда"}},{q="Хто отримує Тотем Гоквінда?",a="Його несуть Бейнові Бладгуфу, синові Кайрна Бладгуфа, що керує Селом Бладгуф на схід від Плато Червоної Хмари.",al={"кому віддати тотем","одержувач тотема","куди тотем"}},{q="Чому тотем, а не лист?",a="Культура тауренів тримається на усних переказах, рукотворному мистецтві й символах предків. Вирізьблений тотем несе дотик і дух вождя, що його створив, і для провідників племен важить куди більше, ніж чорнило на пергаменті.",al={"чому тотем а не лист","традиції жетонів тауренів"}}},fp="17,282,25.648.0,39.201.0,19.179.0,35.120.0,36.242.0"}
P.entries["item:tough-wolf-meat"] = {n="Жорстке М'ясо Вовка",s="Жорстке М'ясо Вовка — сира дичина, здобута з хижих лісових вовків і молодих вовків, що нишпорять Долиною Нортширу й Долиною Холодного Хребта. Хоч воно грубе й жилаве, це основний харч для голодних мешканців на кшталт Іґана Пелтскіннера в Лісі Елвінн і дворфівських постачальників у Дун Мороґу.",h="Жорстке М'ясо Вовка — сира дичина, здобута з хижих лісових вовків і молодих вовків, що нишпорять Долиною...",kw={"м'ясо вовка","вовки","іґан пелтскіннер","нортшир","долина холодного хребта","пайок"},ang={["race:Dwarf"]="Дворфи Долини Холодного Хребта часто винищують обшарпаних лісових вовків заради м'яса, щоб забезпечити тутешніх постачальників, перш ніж вирушити через Дун Мороґ.",["race:Human"]="Для новобранців у Долині Нортширу збирання вовчого м'яса для Іґана Пелтскіннера — одне з найперших завдань на виживання поза тихими стінами абатства."},sec={{t="Прикордонний пайок",b="Вовки, що блукають околицями Долини Нортширу й Дун Мороґу, становлять постійну загрозу тутешнім поселенням, та водночас дають грубе джерело харчу. Жорстке М'ясо Вовка сумнозвісно жилаве й тверде порівняно з добірною дичиною, та нужденні мешканці рубежу однаково його цінують. Біля Абатства Нортшира Іґан Пелтскіннер ненавидить цих звірів за лютість, але залюбки смажить їхнє м'ясо на сільські стейки й охоче міняє основні припаси та спорядження кожному, хто готовий проріджувати зграї."}},faq={{q="Звідки береться Жорстке М'ясо Вовка?",a="Його здобувають, полюючи на молодих і лісових вовків у Долині Нортширу в Лісі Елвінн, а також на обшарпаних вовків у Долині Холодного Хребта в Дун Мороґу.",al={"джерело жорсткого м'яса вовка","як отримати жорстке м'ясо вовка","де фармити жорстке м'ясо вовка"}},{q="Хто збирає це м'ясо в Лісі Елвінн?",a="Його збирає Іґан Пелтскіннер, що стоїть просто біля Абатства Нортшира. Хоч він і ненавидить вовків, але обожнює вовчі стейки на грилі й віддає зайве спорядження новобранцям, які принесуть йому вісім шматків.",al={"кому потрібне м'ясо вовка","м'ясо вовка іґана пелтскіннера","здати м'ясо вовка"}},{q="Чи знадобиться це м'ясо поза людськими землями?",a="Так. У морозному Дун Мороґу дворфські постачальники теж приймають жорстке вовче м'ясо з обшарпаних вовків Долини Холодного Хребта, щоб поповнювати запаси.",al={"м'ясо вовка дун морог","дворфське м'ясо вовка","дворфські постачальники м'ясо"}},{q="Чи використовують Жорстке М'ясо Вовка у звичайних кулінарних рецептах?",a="Ні. Жорстке М'ясо Вовка — лише здобич для завдань місцевих жителів прикордоння, як-от Іґана Пелтскіннера чи постачальників Холодного Хребта, а не інгредієнт для звичайних похідних страв.",al={"чи можна приготувати жорстке м'ясо вовка","рецепти з жорсткого м'яса вовка"}}},fp="15,293,16.506.0,37.167.0,48.198.0,43.163.0,50.192.0"}
P.entries["item:tourmaline-phial"] = {n="Турмалінова Фіала",s="Турмалінова Фіала — особлива самоцвітна посудина, яку мандрівникам у Тельдрассилі дає Корітрас Мунрейдж. Нею набирають благословенну воду з місячного колодязя біля Озерець Арлітрієну в межах тривалих обрядів нагляду за віттям Світового Дерева та його заспокоєння.",h="Турмалінова Фіала — особлива самоцвітна посудина, яку мандрівникам у Тельдрассилі дає Корітрас Мунрейдж.",kw={"турмалінова фіала","місячний колодязь","озерця арлітрієну","корітрас мунрейдж","доланаар","дарнасус","вузлошкіри"},ang={["class:Druid"]="Носити особливі самоцвітні фіали по воду місячних колодязів — неодмінний обрядовий обов'язок молодих друїдів — нічних ельфів, що вчаться доглядати крихкий живий світ Тельдрассила.",["race:NightElf"]="Вода, зібрана в посудини на кшталт Турмалінової Фіали, уособлює опору нічних ельфів на ласку Елуни й друїдську пильність, поки Тельдрассил бореться зі скверною."},sec={{t="Посудина Арлітрієну",b="Корітрас Мунрейдж дає Турмалінову Фіалу на допомогу обрядам довкола Світового Дерева. Друїди в Доланаарі послуговуються такими особливими самоцвітними посудинами, щоб безпечно збирати чисту воду місячних колодязів з усього Тельдрассила. Цю фіалу призначено для місячного колодязя на берегах Озерець Арлітрієну, на південний схід від дороги до Дарнасуса, — у місцевості, яку дедалі дужче облягають ворожі фурболги Вузлошкірів."}},faq={{q="Для чого потрібна Турмалінова Фіала?",a="У фіалу набирають священну воду з місячного колодязя біля Озерець Арлітрієну. Наповнену, її треба повернути Корітрасові Мунрейджу в Доланаарі — це частина обрядів «Корони Землі».",al={"що робить турмалінова фіала","призначення турмалінової фіали","використання турмалінової фіали"}},{q="Хто дає Турмалінову Фіалу?",a="Корітрас Мунрейдж, друїд нічних ельфів із містечка Доланаар, довіряє шукачам пригод порожню фіалу.",al={"хто дає турмалінову фіалу","де взяти турмалінову фіалу"}},{q="Де місячний колодязь для цієї фіали?",a="Місячний колодязь стоїть на березі Озерець Арлітрієну, на південний схід від головної брами до Дарнасуса.",al={"басейни арлітрієна колодязь","де наповнити турмалінову фіалу"}}},fp="16,274,20.421.0,38.205.0,34.115.0,37.117.0"}
P.entries["item:toxic-fogger"] = {n="Розпилювач Токсинів",s="Розпилювач Токсинів — особливий пристрій для розпорошування, наповнений смертельною отрутою, створений Королівським Аптекарським Товариством Відступників. Він має отруїти повітряні перевезення Венчурної Компанії в Горах Кам'яного Кігтя.",h="Розпилювач Токсинів — особливий пристрій для розпорошування, наповнений смертельною отрутою, створений...",kw={"розпилювач токсинів","аптекарка замах","венчурна компанія","озеро скельної заводі","отрута","відступники"},ang={["race:Tauren"]="Смертельні випари можуть випробовувати традиційні тауренські уявлення про честь, але нищівна промислова шкода від Венчурної Компанії змушує багатьох у Тандер Блафі терпіти суворі заходи Замах.",["race:Undead"]="Розпилювач Токсинів — класична польова стратегія Королівського Аптекарського Товариства: зривати ворожі ланцюги постачання розпиленою отрутою й показувати союзникам, що темні методи дають незаперечні результати."},sec={{t="Рішення Відступників",b="Розроблений Аптекаркою Замах у Тандер Блафі, Розпилювач Токсинів — біологічна диверсія, спрямована просто проти хижацького видобутку Венчурної Компанії. Підозрюючи, що гобліни покладаються на поштові літальні машини, щоб перевозити повідомлення й легкі вантажі між Горами Кам'яного Кігтя та своїм штабом, Замах сконструювала розпилювач, що випускає отруту в повітря саме там, де машини сідають і заправляються. Замість затяжних сутичок із нескінченними загонами найманців метод Відступників б'є по хребту постачання, і отрута мандрує просто до корпоративної верхівки."},{t="Диверсія біля Озера Скельної Заводі",b="Ціль Розпилювача Токсинів — відлюдний майданчик для коптерів біля Озера Скельної Заводі. Розташований високо над вирубаними пагорбами й охоронюваний корпоративними громилами, майданчик — повітряний зв'язок між віддаленими бригадами й зовнішніми вузлами. Увімкнений розпилювач напускає на збірний пункт клуби отруйної пари, заскочуючи зненацька пілотів, що повертаються. Хоч декого в Орді й відштовхує вдаватися до отрути, Замах закликає своїх агентів відкинути докори сумління: жоден шлях не надто темний, якщо він веде до перемоги над визискувачами."}},faq={{q="Для чого потрібен Розпилювач Токсинів?",a="Розпилювачем Токсинів отруюють повітряний порт Венчурної Компанії біля Озера Скельної Заводі в Горах Кам'яного Кігтя, заражаючи легкі вантажі й кур'єрів, що вирушають назад до штаб-квартири.",al={"що робить розпилювач токсинів","призначення розпилювача","навіщо розпилювач токсинів"}},{q="Хто створив Розпилювач Токсинів?",a="Його створила Аптекарка Замах, посланниця Королівського Аптекарського Товариства, що перебуває біля Ставків Видінь під Тандер Блафом.",al={"хто створив розпилювач","творець розпилювача токсинів","отрута аптекаря замаха"}},{q="Де треба встановити Розпилювач Токсинів?",a="Його треба поставити на піднятий майданчик для гвинтокрилів Венчурної Компанії біля Озера Скельної Заводі в Горах Кам'яного Кігтя, на південь від великого водяного колеса.",al={"де поставити розпилювач","місце майданчика коптерів","місце небесного порту"}},{q="Чому Орда вдається до отрути проти Венчурної Компанії?",a="Лісозаготівлі й копальні Венчурної Компанії нещадно плюндрують землі Кам'яного Кігтя. Аптекарка Замах вважає звичайну боротьбу надто повільною й переконує, що Орда мусить діяти безжально, щоб викорінити гоблінів, доки шкода не стала непоправною.",al={"чому орда використовує отруту","чи дозволена отрута в орді","методи відступників у стоунталоні"}}},fp="12,233,19.608.0,25.548.1,34.185.0,29.132.0,46.150.0,70.249.0"}
P.entries["item:translated-letter"] = {n="Перекладений Лист",s="Перекладений Лист — розшифроване послання, написане відлюдником Аберкромбі й перекладене Сіррою Вон'Інді в Даркширі для мера Елло Ебонлока.",h="Перекладений Лист — розшифроване послання, написане відлюдником Аберкромбі й перекладене Сіррою Вон'Інді в...",kw={"перекладений лист","аберкромбі","бальзамувальник","стітчес","сірра вон'інді","елло ебонлок"},ang={["faction:Alliance"]="Це послання — нищівна мить прозріння для мандрівників Альянсу в Сутінколіссі: навіть найчистіші наміри можна обернути на зброю проти крихких захисників Даркшира."},sec={{t="Моторошне викриття",b="Те, що починалося як милосердні доручення для начебто безпорадного відлюдника з Воронячого Пагорба, із цим пергаментом набуває темного повороту. Послання Аберкромбі до мера Елло Ебонлока, написане незрозумілим письмом, лишалося загадкою, доки його не віднесли на переклад Сіррі Вон'Інді. Розшифрований текст викриває справжню сутність відлюдника: він і є Бальзамувальник. Аберкромбі зовсім не жив у безневинній самоті — з принесених йому припасів він створив жахливу потвору на ім'я Стітчес і випустив цю громаддю топтати й різати мешканців Даркшира."},{t="Ціна добрих намірів",b="Коли Лорд Елло Ебонлок читає перекладене послання, з обличчя мера збігає вся барва. Мандрівник допомагав щиро, з добрих намірів, але записка доводить: Аберкромбі пошив його в дурні й обернув його працю на знаряддя нещадної різанини. Поки міська рада квапливо збирає Нічну Варту, розшифрована записка лишається моторошним свідченням того, як легко милосердя обертається на руїну на проклятих шляхах Сутінколісся."}},faq={{q="Що сказано в Перекладеному Листі?",a="У ньому — тривожне послання від Аберкромбі для Лорда Елло Ебонлока. Повністю його зміст розкривається, коли перекладену записку доставляють у Даркшир.",al={"текст листа","що написав аберкромбі","що в листі"}},{q="Хто перекладає лист?",a="Сірра Вон'Інді, учена з Даркширу, розшифровує заплутаний почерк Аберкромбі й застерігає вас якнайшвидше повернутися до Лорда Елло з тривожною новиною.",al={"хто перекладає лист","хто розшифрував лист","лист сірри фон інді"}},{q="Що стається, коли Елло читає лист?",a="Переклад глибоко стривожує Елло. Віднесіть лист йому, щоб дізнатися, що це означає для Даркширу.",al={"реакція елло","здати перекладений лист","що буде після перекладу"}},{q="Чи можна викинути Перекладений Лист після завдання?",a="Так. Щойно Лорд Елло огляне пергамент і зміцнить оборону містечка, лист лишається у вашій торбі як пам'ятка й більше ні для чого не потрібен.",al={"чи можна видалити перекладений лист","чи можна знищити перекладений лист","залишити перекладений лист"}}},fp="17,150,21.549.1,28.489.1,36.156.2,26.158.0,40.96.1,55.163.0"}
P.entries["item:treshala-s-pendant"] = {n="Амулет Трешали",s="Амулет Трешали — заповітна сімейна реліквія Трешали Феллоубрук, нічної ельфійки з Дарнасуса, символ подружнього зв'язку. Її чоловік Гералат узяв його з собою на південь Калімдору, і шипогриви в Рейзорфен Краулі зірвали амулет із нього, коли він помирав.",h="Амулет Трешали — заповітна сімейна реліквія Трешали Феллоубрук, нічної ельфійки з Дарнасуса, символ...",kw={"амулет трешали","трешала феллоубрук","гералат фелловбрук","дарнасус","рейзорфен краул","нічні ельфи"},ang={["faction:Alliance"]="Донісши цей знак до Дарнасуса, ви даруєте сумне, але остаточне знання вдові з Альянсу, що оплакує полеглого дослідника.",["race:NightElf"]="Повернувши амулет, ви вшановуєте трагічні останні хвилини побратима-калдорея, що загинув далеко від безпечного віття Тельдрассила."},sec={{t="Знак відданості",b="Амулет — символ глибокої подружньої відданості між Трешалою й Гералатом Фелловбруком. Вирушаючи в небезпечні мандри далеко від Тельдрассила, Гералат носив це намисто подружнього зв'язку при собі як нагадування про дім і кохану."},{t="Загублений серед колючок",b="Коли Гералат спустився в колючі глибини Рейзорфен Краулу, дикі шипогриви напали на його загін. В останні болісні хвилини амулет зірвали з нього, і його забрав один з іклатих охоронців. Відходячи, Гералат мав останнє бажання: щоб якийсь шукач пригод вирвав пам'ятку з рук убивць і доніс до Дарнасуса і її, і гірку звістку про його долю."}},faq={{q="Що таке Амулет Трешали?",a="Це особистий шлюбний амулет Трешали Феллоубрук, який її чоловік Гералат носив як пам'ятку про їхній союз, доки не знайшов свою смерть у Рейзорфен Краулі.",al={"що це за річ","амулет зв'язку","чий амулет"}},{q="Як амулет опинився в Рейзорфен Краулі?",a="Гералат Фелловбрук мав його при собі під час експедиції до Рейзорфен Краулу. Коли шипогриви влаштували засідку й смертельно поранили його, один зі звірів зірвав намисто з його тіла.",al={"чому в рейзорфен краулі","як його загубили"}},{q="Хто просить повернути амулет?",a="Сам Гералат Фелловбрук, помираючи в Рейзорфен Краулі, благає шукачів пригод знайти викрадений амулет і повернути його дружині в Дарнасус разом зі звісткою про його смерть.",al={"хто дає завдання","хто хоче амулет назад"}},{q="Хто отримує амулет, коли його повернуто?",a="Амулет віддають засмученій вдові Гералата, Трешалі Феллоубрук, що живе в Дарнасусі, столиці нічних ельфів на Тельдрассилі.",al={"куди віднести амулет","хто така трешала"}}},fp="18,250,17.245.0,18.395.1,27.169.0,45.175.0,41.203.0,46.143.0"}
P.entries["item:trogg-stone-tooth"] = {n="Кам'яний Зуб Трога",s="Кам'яний Зуб Трога — грубий, скам'янілий зуб, вирваний у трогів Кам'яного Уламка, що заполонили пагорби Лох Модану. Дворфійські оборонці приймають ці зуби як речовий доказ того, що мандрівні шукачі пригод проріджують трогів на південному порубіжжі.",h="Кам'яний Зуб Трога — грубий, скам'янілий зуб, вирваний у трогів Кам'яного Уламка, що заполонили пагорби Лох...",kw={"кам'яний зуб трога","троги","капітан руґелфусс","лох модан","винагорода","кам'яний уламок"},ang={["faction:Alliance"]="Відгукнувшись на заклик Капітана Руґелфусса, ви прямо послаблюєте тиск на важливі торгові шляхи, що з'єднують дворфійські королівства з рештою Альянсу.",["race:Dwarf"]="Кожен здобутий зуб допомагає вберегти Каз Модан, поки більша частина війська Айронфорджа служить Альянсові далеко за кордоном."},sec={{t="Винагорода Південної брами",b="Резерв Айронфорджа пішов на фронт Альянсу, і місцевих дворфійських залог по всьому Каз Модану ледве вистачає. На сторожовій вежі біля південної брами Лох Модану Капітан Руґелфусс не може зняти вояків з постів, щоб ходити в наступальні патрулі проти трогів Кам'яного Уламка, які чатують довкола. Натомість він постійно кличе добровольців полювати на цих створінь у сусідніх пагорбах. Щоб пересвідчитися, що загрозу відкидають, Руґелфусс вимагає Кам'яних Зубів Трога — грубого, незаперечного доказу кожної вбитої потвори."}},faq={{q="Кому потрібні ці кам'яні зуби трогів?",a="Капітан Руґелфусс, що стоїть на південній вартовій вежі на кордоні Лох Модану, збирає їх як доказ того, що мандрівники полюють на трогів Кам'яного Уламка.",al={"кому потрібні кам'яні зуби трогів","зуби ругельфусса","кому потрібні кам'яні зуби"}},{q="Чому зуби кам'яні?",a="Троги мають землисту, підземну будову тіла, що віддзеркалює їхнє давнє кам'яне походження, тож їхні ікла й зуби важкі, мінералізовані й схожі на сирий камінь.",al={"чому зуби кам'яні","анатомія зубів трогів","чи зуби трогів каміння"}},{q="Чому дворфський гарнізон не може сам полювати на трогів?",a="Резерв Айронфорджа мобілізовано для ширших воєнних зусиль Альянсу, і місцевим заставам бракує людей. Загін Капітана Руґелфусса прикутий до охорони південної брами й не може ризикнути залишити укріплення без захисту.",al={"чому ругельфусс потребує допомоги","чому дворфи не б'ються з трогами","резерв айронфорджа"}},{q="Які троги мають ці зуби?",a="Їх збирають із будь-яких трогів Кам'яного Уламка, що никають пагорбами й розкопками Лох Модану, — від звичайних копачів і розвідників до кістоломів-воїнів і геомантів.",al={"де взяти кам'яні зуби трогів","хто дропає кам'яні зуби"}}},fp="17,261,27.529.0,34.164.0,32.174.0,58.236.0,31.190.0"}
P.entries["item:troll-charm"] = {n="Тролячий Оберіг",s="Тролячі обереги — священні духовні амулети, які носять тролі Темного Спису. Нещодавно ворожі фурболги Будякохутрі пограбували цілу їх купу після засідки на півночі Ашенвалю.",h="Тролячі обереги — священні духовні амулети, які носять тролі Темного Спису.",kw={"тролячий оберіг","тролі","темний спис","фурболги","міцува","застава зорам'гар"},ang={["faction:Horde"]="Повернувши ці викрадені речі, ви послабите агресивне плем'я Будякохутрих і помститеся за мандрівників Орди, полеглих на підступних стежках Ашенвалю.",["race:Troll"]="Для тролів Темного Спису лишити священні обереги в лапах диких фурболгів — нестерпна образа пам'яті й духу полеглих родичів."},sec={{t="Священні дрібнички Темного Спису",b="Для тролів Орди духовні обереги — значно більше, ніж прикраса. Як пояснює розвідник Міцува, троль без свого оберега вважається таким самим неповноцінним, як орк без бойових шрамів. Коли загін тролів Темного Спису йшов густими хащами Ашенвалю до Застави Зорам'гар, на нього напали й вирізали зіпсовані фурболги Будякохутрі. Духів полеглих провели до потойбіччя, а фурболги обібрали мертвих і забрали священні обереги як трофеї, сховавши їх у скринях глибоко у Твердині Будякохутрих."}},faq={{q="Для чого потрібні Тролячі Обереги?",a="Тролячі Обереги — священні культурні й духовні захисні знаки тролів Темного Спису. Носити такі талісмани для цього народу — неодмінна ознака особистої й духовної гідності.",al={"призначення тролячого оберега","лор тролячого оберега","чому тролі носять обереги"}},{q="Де знайти ці обереги?",a="Вони замкнені в скринях, розкиданих Твердинею Будякохутрих — печерами за Селом Будякохутрих на півночі Ашенвалю.",al={"де тролячі обереги","як знайти тролячий оберіг","місце тролячої скрині"}},{q="Звідки в фурболгів ці обереги?",a="Клан Будякохутрих влаштував засідку на групу мандрівників із Темного Спису й перебив їх, перш ніж ті дісталися Застави Зорам'гар. Фурболги пограбували їхні речі й забрали обереги собі.",al={"чому фурболги мають обереги","хто вкрав обереги"}},{q="Хто хоче повернути обереги?",a="Міцува, троль Темного Спису із Застави Зорам'гар на Зорамському Узмор'ї, шукає їх, щоб повернути честь своїм загиблим родичам.",al={"хто бере обереги","завдання міцува"}}},fp="11,203,32.562.0,31.178.0,29.141.0,38.189.0,26.134.0"}
P.entries["item:trophy-swoop-quill"] = {n="Трофейне Перо Стрімкокрила",s="Трофейне Перо Стрімкокрила — цінний мисливський знак, вискубаний у великих хижих птахів, що кружляють над рівнинами Малгору. Серед тауренів зібрані пера доводять гостре око, терпіння й мисливську вправність.",h="Трофейне Перо Стрімкокрила — цінний мисливський знак, вискубаний у великих хижих птахів, що кружляють над...",kw={"трофейне перо стрімкокрила","стрімкокрил","перо","гаркен віндтотем","мисливець","село бладгуф","малгор"},ang={["class:Hunter"]="Вистежувати крилату здобич над відкритими рівнинами — перевірка основ слідопитства, терпіння й влучності.",["race:Tauren"]="Полювати на стрімкокрила й приносити додому його пера — традиційне заняття, що вимагає терпіння й кмітливості по всьому Малгору й шанує і мисливця, і клан."},sec={{t="Знак полювання",b="Стрімкокрили — хитрі пернаті хижаки, рідні для Малгору: вони ширяють на високих висхідних потоках, і вистежити їх над луками непросто. Для молодих мисливців-тауренів і мандрівників, що прагнуть довести себе в Селі Бладгуф, здобути трофейне перо цих птахів — традиційний обряд кмітливості й рішучості. Подані старійшинам на кшталт Гаркена Віндтотема, ці пера шанують клан мисливця й засвідчують, що він має гострі чуття, потрібні, щоб процвітати на рівнинах."}},faq={{q="Для чого потрібне Трофейне Перо Стрімкокрила?",a="Трофейні Пера Стрімкокрила збирають як доказ мисливської звитяги для Гаркена Віндтотема в Селі Бладгуф. Принесені йому, вони свідчать про вашу рішучість і пильне око та підносять вашу шану серед місцевих тауренів.",al={"для чого пера стрімкокрила","хто хоче пера стрімкокрила","використання пера стрімкокрила"}},{q="Звідки беруться Трофейні Пера Стрімкокрила?",a="Ці пера здобувають із різних стрімкокрилів — звичайних, жилавих і кігтистих, — що ширяють над розлогими рівнинами всього Малгору.",al={"де взяти пера стрімкокрила","хто дропає трофейне перо стрімкокрила","місця стрімкокрилів"}},{q="Чому на стрімкокрилів важко полювати?",a="За словами Гаркена Віндтотема, стрімкокрили — хитрі птахи, що кружляють високо над травою й швидко перелітають з місця на місце, тож, щоб їх помітити й наздогнати, потрібні гостре око й прудкі ноги.",al={"чому важко полювати на стрімкокрилів","чи важко вбити стрімкокрилів"}}},fp="18,223,17.498.0,38.219.0,39.163.0,44.191.0"}
P.entries["item:twilight-pendant"] = {n="Сутінковий Амулет",s="Сутінковий амулет — знак, який носять сектанти Молота Присмерку глибоко в Чорноглибинних Печерах. Для Срібного Світанку ці темні талісмани — остаточний доказ підривної діяльності культу на узбережжі Ашенвалю.",h="Сутінковий амулет — знак, який носять сектанти Молота Присмерку глибоко в Чорноглибинних Печерах.",kw={"сутінковий амулет","молот присмерку","срібний світанок","манадос","чорноглибинні печери","сектанти"},ang={["faction:Alliance"]="Принесені Срібному Вартовому Манадосу в Дарнасус, ці трофеї показують, що Альянс діяльно підтримує похід Срібного Світанку проти прихованого зла на півночі Калімдору.",["race:NightElf"]="Осквернення Чорноглибинних Печер — колись осердя шанованого й могутнього місячного колодязя — робить повернення цих символів скверни глибоко священною справою для калдореїв."},sec={{t="Знаки Древніх Богів",b="У затоплених руїнах Чорноглибинних Печер члени Молота Присмерку збираються разом із нагами, щоб правити мерзенні обряди на честь хаотичних Древніх Богів. Сектанти — від магів тіней і аквамантів до грабіжників і шукачів знань — носять ці амулети як знаки відданості своїм темним покровителям. Оскільки культ діє таємно під колишнім храмом нічних ельфів, здобуття цих прикрас — один із небагатьох способів для сторонніх оцінити чисельність культу й зірвати його підступи."},{t="Варта Срібного Світанку",b="Срібний Вартовий Манадос у Дарнасусі шукає ці амулети як доказ успішного очищення від темряви, що насувається. Колись у Чорноглибинних Печерах був незайманий місячний колодязь, і його осквернення злостивими прислужниками Порожнечі — тяжка загроза для Калімдору. Зібрані амулети підтверджують, що опорний пункт сектантів в Ашенвалі руйнують, перш ніж їхні темні покровителі накоять іще більшого жаху."}},faq={{q="Що таке Сутінковий Амулет?",a="Сутінковий Амулет — розпізнавальний знак членів культу Молота Присмерку, що діє в Чорноглибинних Печерах. Він відчутно засвідчує відданість Древнім Богам і їхнім темним обрядам.",al={"інфо про сутінковий амулет","що таке сутінкові амулети"}},{q="Навіщо Срібному Вартовому Манадосу ці амулети?",a="Срібний Вартовий Манадос, що служить у Дарнасусі від імені Срібного світанку, збирає їх як доказ того, що Молот Присмерку в Чорноглибинних Печерах громлять, перш ніж його лихі задуми встигнуть визріти.",al={"хто хоче сутінковий амулет","навіщо збирати сутінкові амулети"}},{q="Хто носить ці амулети?",a="Їх носять різні культисти в затопленому храмі Чорноглибинних Печер: послушники, акваманти, маги тіні, шукачі знань, елементалісти й розорювачі Присмерку.",al={"хто дропає сутінковий амулет","звідки сутінкові амулети"}},{q="Чим загрожує Молот Присмерку в Чорноглибинних Печерах?",a="У союзі з нагами Молот Присмерку прагне відродити поклоніння Древнім Богам: він оскверняє давній місячний колодязь нічних ельфів і готує ритуали, що можуть посіяти жах по всьому Калімдору.",al={"що робить молот присмерку в чорноглибинних печерах","чому культисти в ашенвейлі"}}},fp="16,236,22.518.0,24.414.0,27.203.0,50.208.0,25.182.0,65.193.0"}
P.entries["item:twilight-whisker"] = {n="Сутінковий Вус",s="Сутінкові Вуси здобувають у сутінкових бігунів, що нишпорять північними висотами Гір Кам'яного Кігтя. У поселенні Малака'джин Знахар Джин'Зіл жадає їх як складник для жорстокого отруйного зілля, яке глузливо називає лісовою магією.",h="Сутінкові Вуси здобувають у сутінкових бігунів, що нишпорять північними висотами Гір Кам'яного Кігтя.",kw={"сутінковий вус","сутінкові бігуни","знахар джин'зіл","малака'джин","пік кам'яного кігтя","вуду"},ang={["race:NightElf"]="Осквернення священних лісових створінь — сутінкових бігунів і чарівних драконів — заради отрути для полонених нічних ельфів утілює жорстоку війну, що вирує в лісах Калімдору.",["race:Troll"]="Те, як Джин'Зіл використовує реагенти місцевих звірів, відбиває класичні традиції вуду Темного Списа, що обертають природну сутність лісу проти ворогів."},sec={{t="Реагент знахаря",b="Високі скелі біля Піку Кам'яного Кігтя — домівка сутінкових бігунів, хижих котів, що зрослися з глибокими тінями давніх гаїв. Мисливці цінують їхні шкури, а Знахар Джин'Зіл із Малака'джина шукає їхні жорсткі вуса для куди темнішої мети. Прагнучи помсти полоненим нічним ельфам, які колись боронили ці ліси, Джин'Зіл збирає дари лісу — смолисту живицю, безліч очей, луску чарівних драконів і сутінкові вуса, — щоб зварити смертельний напій, який має поглумитися з бранців і отруїти їх."}},faq={{q="Де знайти Сутінкові Вуса?",a="Їх збирають із сутінкових бігунів, що крадуться схилами довкола Піку Кам'яного Кігтя на півночі Гір Кам'яного Кігтя.",al={"місце сутінкового вуса","хто дропає сутінкові вуса","де взяти сутінкові вуса"}},{q="Навіщо вони Знахареві Джин'Зілу?",a="Знахар Джин'Зіл використовує їх разом із соком, очима скакунів і лускою феєвого дракона, щоб зварити смертоносне зілля, яким труїть полонених нічних ельфів у Малака'джині.",al={"вуса для джин'зіла","навіщо джин'зілу сутінкові вуса","інгредієнти лісової магії джин'зіла"}},{q="Що стається, коли Джин'Зіл отримує вуса?",a="Отримавши інгредієнти, Джин'Зіл випускає своє зілля в печері. Суміш швидко вбиває ув'язнених у клітках нічних ельфів, і їхні духи відлітають вогниками.",al={"результат лісової магії","що буде з в'язнями"}}},fp="16,260,24.517.0,34.120.0,40.161.0,49.186.1"}
P.entries["item:twitching-antenna"] = {n="Сіпливе Вусико",s="Сіпливі вусики — відтяті органи чуття силітидів-загарбників, що кишать на півдні Пусток. Їх шукає тауренський воїн Руґа Рейджтотем у Таборі Тауражо: принесені, поки нерви ще не перестали сіпатися, вони доводять прудкість і бойову вправність молодого воїна.",h="Сіпливі вусики — відтяті органи чуття силітидів-загарбників, що кишать на півдні Пусток.",kw={"сіпливе вусико","силітиди","руґа рейджтотем","табір тауражо","поле велетнів","воїн"},ang={["class:Hunter"]="Вистежити, вбити й обробити щойно вбитих силітидів за суворо обмежений час — класична перевірка мисливської швидкості, вміння читати сліди й смертоносності в полі.",["race:Tauren"]="Мисливці Табору Тауражо вважають раптову появу силітидів глибоким порушенням природної рівноваги рівнин, тож молоді воїни мусять бути пильними."},sec={{t="Мисливський доказ",b="Ці вусики, зрізані просто з голів личинок, роїльників і збирачів-силітидів, зберігають залишкові нервові рефлекси навіть після того, як їх відділено. Та шалене сіпання триває недовго, відколи вусики втратили зв'язок із комахою-господарем. Через це коротке вікно життя принести вусики, що ще сіпаються, — суворе випробування на швидкість: треба вполювати звірів на південних пустищах і щодуху мчати назад через чагарники, поки сіпання не вщухло."},{t="Загроза з півдня",b="Ці вусики — не лише обряд посвяти, а й тривожні провісники. Силітиди не з Пусток, і їхні нові кучугури на Полі Велетнів неабияк непокоять мисливців Табору Тауражо. Руґа Рейджтотем вимагає ці зразки, щоб вивчити нову загрозу й водночас загартувати воїнів Орди проти чужинської напасті, що наступає."}},faq={{q="Які створіння залишають Сіпливі Вусики?",a="Їх здобувають із комах-силітидів, що заполонили південь Пусток: личинок, збирачів, ройовиків і плазунів, які живуть довкола величезних скам'янілих кісток на Полі Велетнів.",al={"де падають сіпливі вусики","хто дропає сіпливе вусико","джерело вусиків силітидів"}},{q="Чому вусики мають сіпатися?",a="Безупинне сіпання доводить, що зразки зібрано щойно. Руґа Рейджтотем користується тим, що вони швидко завмирають, щоб перевірити бойову вправність і прудкість претендента на диких теренах.",al={"чому сіпається","чому поспіх із вусиками","випробування поля велетнів таймер"}},{q="Хто шукає ці вусики?",a="Руґа Рейджтотем, таурен-воїн із Табору Тауражо на півдні Пусток, вимагає їх у межах Випробування на Полі Велетнів.",al={"хто хоче сіпливі вусики","хто здає вусики"}},{q="Де Поле Велетнів?",a="Поле Велетнів лежить просто на південь від Табору Тауражо в Пустках. Його легко впізнати за величезними кістяками, що стирчать із землі, і дивними вуликами силітидів, які виростають довкола них.",al={"де поле велетнів","місце поля велетнів"}}},fp="17,291,17.472.0,23.365.0,39.204.0,41.189.0,34.142.0,29.196.0"}
P.entries["item:ukor-s-burden"] = {n="Тягар Укора",s="Тягар Укора — важкий пакунок харчів, який добродушний орк-пеон виніс із Гострого Пагорба. Призначені голодним новачкам у Долині Випробувань, непотрібні припаси треба віднести назад, доки пустельні скорпіди та раптори не вчули запаху.",h="Тягар Укора — важкий пакунок харчів, який добродушний орк-пеон виніс із Гострого Пагорба.",kw={"тягар укора","укор","пеон","припаси","гострий пагорб","ґроск","долина випробувань"},ang={["faction:Horde"]="Це доручення показує сувору культуру виживання, яку Орда Тралла насаджує в Дуроторі: навіть проста доброта має поступитися суворим випробуванням, що гартують нових солдатів."},sec={{t="Помилка з добрими намірами",b="Орки-пеони рідко діють з власної волі, тож доручення Укора незвичайне. Навантажившись харчами з корчми в Гострому Пагорбі, він пройшов крізь червоний пил і агресивну звірину Дуротару, щоб допомогти молодим новобранцям у Долині Випробувань. На його жаль, наглядачі й наставники відіслали його геть: вони вірять, що справжніх воїнів гартують злигодні й порожні животи. Застрягши біля входу в каньйон і боячись звірів, що чигають на зворотній стежці, Укор довірив мішок перехожим мандрівникам, щоб ті повернули його Корчмарю Ґроску."}},faq={{q="Що в Тягарі Укора?",a="Це важкий мішок з їжею та припасами з корчми в Гострому Пагорбі. Укор зібрав харчі, сподіваючись нагодувати молодих орків і тролів, що проходять посвяту, і не знав, що на навчальних теренах навмисно обмежують будь-які вигоди ззовні.",al={"що в пакунку","вміст тягаря укора","яка це їжа"}},{q="Чому в Долині Випробувань відмовилися від їжі?",a="Наглядачі Долини Випробувань вірять, що витривалість і нестатки гартують характер молодих воїнів. Як каже Корчмар Ґроск, голод під час навчання гартує дух, тож доброчинність ззовні тут не вітають.",al={"чому долина випробувань відмовилася від їжі","чому не хотіли їжу","чому їжа не потрібна"}},{q="Куди треба віднести вантаж?",a="Припасам місце на полицях корчми в Гострому Пагорбі. Віднесіть мішок просто Корчмареві Ґроску: він поверне харчі на місце й пригостить чаркою того, хто доправив їх додому.",al={"куди нести тягар укора","хто хоче тягар укора","доставка тягаря укора"}}},fp="13,258,26.548.0,29.242.0,45.227.0,33.198.0"}
P.entries["item:uncloven-satyr-hoof"] = {n="Нерозколоте Копито Сатира",s="Нерозколоте Копито Сатира — набрякле, суцільне копито, здобуте із сатирів, що причаїлися в Ашенвалі. Просякнуті спотвореною магічною енергією, висмоктаною з давнього лісу, ці похмурі трофеї — потужні складники для ремесла зброярів-тролів Темного Списа.",h="Нерозколоте Копито Сатира — набрякле, суцільне копито, здобуте із сатирів, що причаїлися в Ашенвалі.",kw={"копито сатира","сатири","ашенваль","ула'елек","сен'джин","рукавиці","скверна"},ang={["class:Warrior"]="Молодих воїнів, що шукають слави, наставники Орди спрямовують замовити особливі обладунки в Селі Сен'джин, а щоб довести бойову вправність — вистежити сатирів Ашенвалю.",["race:Troll"]="Ремісники Темного Списа на кшталт Ула'елека майстерно обертають темні чи ворожі енергії на корисне спорядження, висмоктуючи силу з демонічних ворогів, а не даючи їй пропасти марно."},sec={{t="Висмоктана сила",b="Сатири блукають оскверненими гаями північно-східного Ашенвалю, живлячись просто магічною чистотою давнього лісу. Поки вони жеруть цю сутність, скверна спотворює їхню демонічну будову: копита набрякають і втрачають природну розколину. Ці суцільні, нерозколоті копита стають щільними сховищами поглинутої енергії — летючої сили, яку вмілі шамани й шкіряники можуть видобути."},{t="Виготовлення жорстоких обладунків",b="На узбережжі Дуротару, в Селі Сен'джин, троль-зброяр Ула'елек знає, як обернути демонічну скверну на силу для чемпіонів Орди. Забираючи копита цих переситених сатирів, він висмоктує з них ув'язнену лісову магію і спрямовує викрадену силу в кування жорстоких латних рукавиць, покликаних захистити молодих воїнів від суворих випробувань Калімдору."}},faq={{q="Чому ці копита сатирів нерозколоті?",a="Сатири Ашенвалю безупинно живляться священною магією лісу, оскверняючи її й висмоктуючи силу. У найненажерливіших сатирів копита так набрякають, що втрачають розщеп і замикають усередині густу вкрадену енергію.",al={"чому копита нерозколоті","значення нерозколотого копита","набряклі копита"}},{q="Де знайти Нерозколоті Копита Сатира?",a="Їх збирають із сатирів, що живуть в осквернених руїнах і опоганених гаях на північному сході Ашенвалю, як-от у Сатирнаарі й Нічному Потоці.",al={"де фармити копита","місце копита сатира","які сатири дропають копита"}},{q="Кому в Дуротарі потрібні ці копита?",a="Ула'елек, майстер із Села Сен'джин на південному узбережжі Дуротару, просить сім копит, щоб видобути з них накопичену магію.",al={"кому потрібні копита сатирів","видавець завдання на копита сатира","що робити з копитами"}},{q="Що виготовляють із копит?",a="Ула'елек витягає з копит осквернену силу лісу, щоб зачарувати й викувати пару міцних, насичених магією грізних рукавиць.",al={"для чого копита","нагорода за виготовлення з копит","матеріали жорстоких рукавиць"}}},fp="19,252,13.428.0,25.365.0,36.241.0,41.140.0,34.140.0,34.128.0"}
P.entries["item:underbelly-whelp-scale"] = {n="Луска з Пуза Дракончика",s="Луску з Пуза Дракончика добувають із молодих виводків Чорного драконячого роду, що нишпорять Горами Редріджу. Ремісники цінують її за міцність і водночас гнучкість, тож вона правує за цінний товар для обміну серед місцевих майстрів.",h="Луску з Пуза Дракончика добувають із молодих виводків Чорного драконячого роду, що нишпорять Горами Редріджу.",kw={"луска з пуза дракончика","чорні дракончики","вернер осґуд","коваль арґус","озеро незрушне","редрідж"},ang={["faction:Alliance"]="Відрізані захисники Лейкширу тримаються на обміні з Лісом Елвінн, тож небезпечні місцеві замовлення, як-от драконяча луска, вкрай важливі для поповнення міських запасів.",["profession:Blacksmithing"]="Майстри на кшталт Арґуса цінують цю луску, бо з екзотичних плазунячих пластин можна зробити підкладки, руків'я й особливі захисні деталі, значно міцніші за звичайну шкіру."},sec={{t="Рідкісний товар",b="Драконяча шкіра й луска славляться легендарною міцністю, але дорослі чорні дракони для простих людей смертельно небезпечні. Тож кмітливі прикордонні жителі й ремісники поглядають у небо на південь від Озера Незрушного, де серед скель гніздяться молоді чорні дракончики. Спинні пластини дракончика крихкі або грубі, а от луска вздовж м'якшого черева — ідеальне поєднання гнучкості й захисту. Тому луска з пуза дракончиків дуже цінується в місцевій торгівлі: це і добірний матеріал для ремесла, і надійна застава за борги."},{t="Борг Вернера",b="У Лейкширі, коли монет бракує чи торговельні шляхи під загрозою, ремісникам часто доводиться вдаватися до обміну. Вернер Осґуд, місцевий шкіряник і постачальник ковалів, заборгував чималу суму ковалеві Арґусу за партію підків, привезену з Ґолдширу. Знаючи, як Арґус любить рідкісні товари, Вернер покладається на мандрівних шукачів пригод: хай здобудуть луску з пуза дракончиків, щоб покрити борг і зберегти добре ім'я майстерні."}},faq={{q="Звідки береться Луска з Пуза Дракончика?",a="Її збирають із чорних дракончиків і дорослих дракончиків на кшталт Снарлфлера, що гніздяться на скелястих кручах і пагорбах на південь від Лейкширу в Горах Редріджу.",al={"хто дропає луску з пуза дракончика","де взяти луску дракончика","як знайти луску дракончика"}},{q="Навіщо Вернерові Осґуду ця луска?",a="Вернер заборгував Арґусові, ковалеві з Ґолдширу, за партію привізних підків. Арґус приймає драконячу луску як плату, а з решти Вернер може зробити міцне захисне спорядження.",al={"навіщо вернеру луска","луска з пуза вернера осґуда"}},{q="Чому луска з пуза краща за звичайну драконячу?",a="Луска з пуза молодого дракона досить гнучка, щоб її різати, формувати й пришивати до практичних обладунків чи посиленого спорядження, тоді як луска зі спини часто надто тверда, товста чи покручена для звичайних прийомів шкірництва й ковальства.",al={"чому луска з пуза","чим особлива луска з пуза"}},{q="Звідки взагалі чорні дракончики в Редріджі?",a="Чорний драконячий рід давно тримається серед палаючих вершин і скель на межі Палаючих Степів і Редріджу: на високих, неприступних кручах дракони висиджують і ростять своїх малят.",al={"чому дракони в редріджі","чорні дракончики редріджа"}}},fp="22,247,22.599.0,13.466.0,43.165.0,41.223.0,63.240.0,47.194.0"}
P.entries["item:unidentified-ore"] = {n="Невпізнана Руда",s="Невпізнана Руда — дивний зразок мінералу, який відкопали під час робіт Венчурної Компанії в скелях Гір Кам'яного Кігтя. Знайдений незадоволеним робітником Пізніком, він потай потрапив до гоблінського винахідника Зіза Фіззікса для дослідження, а звідти мав вирушити до інженерів Андермайна.",h="Невпізнана Руда — дивний зразок мінералу, який відкопали під час робіт Венчурної Компанії в скелях Гір...",kw={"невпізнана руда","пізнік","зіз фіззікс","венчурна компанія","круча вітрорізу","андермайн"},ang={["profession:Engineering"]="Гоблінське ремесло тримається на пошуку сирих сполук з особливими активними властивостями, тож невідомі руди з диких скель — чудовий матеріал для досліджень винахідливих майстрів.",["profession:Mining"]="Рудокопи на Кручі Вітрорізу знайдуть звичайні жили на кожному кроці, але цей дивний мінерал не вкладається в жодне ремісниче знання й цікавить навіть найкращих оцінювачів Андермайна."},sec={{t="Дивна знахідка на Кручі Вітрорізу",b="Невпинна суцільна вирубка й відкритий видобуток Венчурної Компанії на Кручі Вітрорізу глибоко вгризлися в скелі Гір Кам'яного Кігтя й оголили незвичні мінеральні пласти. Серед уламків гоблін-робітник Пізнік натрапив на дивний, нікому не відомий зразок. Розуміючи, що той може бути цінним — чи принаймні стати козирем, — Пізнік притримав зразок, поки замишляв утечу з лісозаготівельної артілі. Переданий мандрівникові, що прямував до західного кряжу кручі, зразок потрапив до рук Зіза Фіззікса, який збирався відіслати знахідку до Андермайна на дослідження, а шматочок завбільшки з кишеню лишити собі на прибуток."}},faq={{q="Що таке Невпізнана Руда?",a="Це некласифікований геологічний зразок, викопаний під час робіт Венчурної Компанії на Кручі Вітрорізу. Його склад такий загадковий, що зацікавив і майстра Зіза Фіззікса, і гірничих інженерів в Андермайні.",al={"що за руда","лор невпізнаної руди","що за камінь"}},{q="Хто знайшов руду?",a="Зразок підібрав Пізнік, гоблін Венчурної Компанії з Кручі Вітрорізу. Побоюючись кари від начальства після недавніх невдач, він скористався каменем як нагодою втекти й знайти нову роботу.",al={"хто викопав","хто дає руду","руда пізника"}},{q="Хто намагається вивчити цей зразок?",a="Мінерал отримує Зіз Фіззікс, заповзятливий гоблін, що отаборився на західному краю Кручі Вітрорізу. Більшу частину він збирається передати інженерам в Андермайн, а шматочок відколоти собі.",al={"хто хоче руду","хто аналізує","руда зіза фіззікса"}},{q="Чому Андермайн цікавить цей камінь?",a="Гобліни завжди шукають нові вибухові, металургійні чи горючі матеріали. Дивний мінерал, видобутий у прадавніх горах Калімдору, обіцяє торговим картелям величезну промислову й комерційну вигоду.",al={"інтерес андермайну","чому гобліни хочуть"}}},fp="16,278,29.627.0,29.239.0,18.219.0,35.228.0,41.225.0"}
P.entries["item:unrefined-ore-sample"] = {n="Необроблений Зразок Руди",s="Необроблений зразок руди — шматок незвичного сирого мінералу, який видобувають кобольди Ґравелснаутів в Тисячі Голок. Головний зброяр Табору Тауражо, Таттернак Стілфордж, шукає його, щоб з'ясувати, чи можна викувати з цього металу кращу зброю для армій Вождя Тралла.",h="Необроблений зразок руди — шматок незвичного сирого мінералу, який видобувають кобольди Ґравелснаутів в...",kw={"необроблений зразок руди","таттернак стілфордж","табір тауражо","кобольди","тисяча голок","ковальство"},ang={["faction:Horde"]="Кожна нова рудна жила на півдні Калімдору — крок до військової самодостатності молодої держави Тралла, яка зміцнює свої кордони.",["profession:Blacksmithing"]="Ковалі розуміють досаду Таттернака: вивчення нових руд на гарт і міцність — запорука того, що воїни отримають клинки, які не розлетяться в бою."},sec={{t="Видобуто шкідниками",b="На південь від Пусток, серед стрімких стін каньйону Тисячі Голок, клан кобольдів, відомий як Ґравелснаутів, без упину риє камінь і землю. Мандрівники, що поверталися на північ через Пустки, принесли звістку про дивний мінерал, знайдений у вбитих шкідників, — неочищену руду, не схожу на звичайні жили Калімдору. Мандрівники відмовилися віддати свою знахідку Орді, але підземні копачі й розвідники Тисячі Голок носять сирі шматки цього каменю просто зі своїх розкопок."},{t="Кування для Вождя",b="У Таборі Тауражо зброяр Таттернак Стілфордж за прямим наказом Вождя Тралла працює над міцнішою зброєю для Орди. Таттернака розлютили мандрівники, які приховали відомості про поклад: він вважав це образою для воєнних зусиль Орди. Здобувши сирий зразок мінералу, Стілфордж хоче перевірити його міцність і гарт, сподіваючись переплавити його й викувати дослідний клинок, гідний схвалення Оргріммара."}},faq={{q="Звідки цей Необроблений Зразок Руди?",a="Руду носять кобольди Ґравелснаутів — копачі, розвідники та їхній ватажок Ґібблснік, — що живуть у глибинах каньйонів Тисячі Голок на південь від Пусток.",al={"місце руди","де взяти необроблений зразок руди","хто дропає необроблену руду"}},{q="Навіщо Таттернакові Стілфорджу зразок?",a="Таттернак виконує наказ Вождя вдосконалити зброю Орди. Він хоче оглянути й переплавити руду, щоб з'ясувати, чи досить вона міцна для нової зброї Орди.",al={"чому таттернаку руда","призначення руди тауражо","для чого руда"}},{q="Чому мандрівники не хотіли з нею розлучатися?",a="Мандрівники Орди, що прийшли з Тисячі Голок, знайшли руду в кобольда й лишили собі як трофей чи дивовижу — і не продавали її, навіть коли їх просили допомогти ковальським зусиллям Орди.",al={"хто були мандрівники","мандрівники руда пустища"}},{q="Чи трапляється ця руда в Пустках?",a="Ні. Хоч прохання надходить із Табору Тауражо на півдні Пусток, саму руду треба здобути в кобольдів далі на південь, у Тисячі Голок.",al={"руда в пустищі","чи можна видобути в пустищі"}}},fp="20,287,19.522.0,24.459.0,40.173.0,45.186.0,49.201.0,42.155.0"}
P.entries["item:ur-s-treatise-on-shadow-magic"] = {n="Трактат Ура про Магію Тіні",s="Трактат Ура про Магію Тіні — небезпечний чарівний фоліант, написаний славетним чарівником Уром із Даларану. Спершу його оберігали маги Стормвінда, але чаклун-ренегат Морґант викрав зачаровану книгу й сховав її у Вежі Ілґалара.",h="Трактат Ура про Магію Тіні — небезпечний чарівний фоліант, написаний славетним чарівником Уром із Даларану.",kw={"трактат ура про магію тіні","ур із даларану","морґант","вежа ілґалара","верховний чаклун андромат","святилище чародія"},ang={["class:Mage"]="Для магів Стормвінда повернення трактату Ура — питання стримування: після того як один із них піддався темним спокусам, треба вберегти Святилище.",["faction:Alliance"]="Присутність Морґанта в Редріджі загрожує східному прикордонню королівства, тож повернення цього могутнього артефакту вкрай важливе для безпеки Стормвінда."},sec={{t="Небезпечна спадщина",b="У цьому трактаті даларанський учений Ур досліджує тонку й руйнівну природу тіньової магії. Заглиблення в такі мистецтва кличе загибель і руїну на необачних, тож маги Святилища Чародія в Стормвінді наклали на книгу захисні печаті, щоб ніхто не міг прочитати її зміст. Проте коли чаклун Морґант піддався темним мистецтвам і був вигнаний із магічного кола міста, він прихопив фоліант і поніс його на схід, у Гори Редріджу, до своєї твердині у Вежі Ілґалара."},{t="Захищені таємниці",b="Побоюючись, що Морґант опанує темні знання, збережені Уром, Верховний Чаклун Андромат послав шукачів пригод прорватися до Вежі Ілґалара й повернути викрадену працю. Попри амбіції Морґанта й глибоке падіння в заборонену магію, захисні печаті стормвіндського кола виявилися досить міцними, щоб йому не піддатися, тож до повернення трактат так і лишився нерозкритим."}},faq={{q="Хто такий Ур?",a="Ур був шанованим чарівником і вченим із Даларана, що присвятив значну частину своїх досліджень позавимірним істотам, темним мистецтвам і таємній магії, зокрема магії Тіні.",al={"хто написав книгу","ур з даларана","хто такий ур"}},{q="Чому трактат такий небезпечний?",a="Як застерігає Верховний Чаклун Андромат, таємниці магії Тіні не для необізнаних. Хто зазирає в її заборонені глибини, легко зазнає зіпсуття й накликає на себе загибель і руїну.",al={"чому книга небезпечна","що робить книга","небезпека магії тіні"}},{q="Хто викрав Трактат Ура про Магію Тіні?",a="Морґант, колишній член ордену чарівників Стормвінда, якого вигнали, коли він піддався спокусі темної магії, викрав фоліант і сховався у Вежі Ілґалара в Редріджі.",al={"хто вкрав книгу","вкрадена книга морґанта","хто взяв трактат"}},{q="Чи вдалося Морґанту прочитати трактат?",a="Ні. Захисні печаті, накладені на фоліант магами Стормвінда, встояли, і Морґант не зміг його відкрити, доки трактат не повернули.",al={"чи морґант прочитав","чи печатки витримали","чи відкрили книгу"}},{q="Чи це та сама праця, що й Книга Ура?",a="Це тісно пов'язані праці одного автора. Книга Ура — ширший гримуар, що зберігається в руїнах Фортеці Шадовфенг, а Трактат про Магію Тіні, схоже, — уривок або окремий том, цілком присвячений мистецтву Тіні.",al={"різниця з книгою ура","книга ура шедоуфенґ","чи це книга ура"}}},fp="29,255,18.533.0,18.387.1,11.183.0,33.187.0,40.180.0,41.146.1,40.240.0"}
P.entries["item:urgent-message"] = {n="Термінове Послання",s="Термінове Послання — запечатане донесення, яке Сміливець Мунгорн пише на Заставу Вільного Вітру, попереджаючи про дедалі запеклішу жорстокість кентаврів у Тисячі Голок. Мандрівники, що спускаються в каньйон, несуть цей лист, і він сповіщає гарнізон тауренів, що їхнім шляхам постачання й розвідувальним загонам загрожує безпосередня небезпека.",h="Термінове Послання — запечатане донесення, яке Сміливець Мунгорн пише на Заставу Вільного Вітру, попереджаючи...",kw={"термінове послання","сміливець мунгорн","скельний вартовий лонггорн","застава вільного вітру","кентаври","тисяча голок"},ang={["faction:Horde"]="Послання показує, які хиткі шляхи постачання Орди на півдні Калімдору, де відрізані застави виживають на ворожій землі лише завдяки гінцям і сміливцям.",["race:Tauren"]="Для тауренів цей лист — болюче нагадування про давню кровну ворожнечу з кентаврами, а також про дедалі більшу тривогу через їхніх родичів-Ґрімтотемів."},sec={{t="Попередження з висоти",b="Термінове Послання, яке Сміливець Мунгорн написав біля великого підйомника, що спускається з Пусток у Тисячу Голок, — перша лінія оборони для мандрівників, які перетинають кордон. Мунгорн стежить за зубчастими каньйонами внизу, де войовничі племена кентаврів знову взялися за нещадні набіги на мандрівників Орди. Лист адресовано Скельному Вартовому Лонггорну на вершині Застави Вільного Вітру: він б'є на сполох через зухвалих нападників, що вдаряють небезпечно близько до важливих доріг, і закликає місцевий гарнізон готуватися до затяжної боротьби та остерігатися інших загроз, як-от непередбачуваного клану Ґрімтотем."},{t="Кров на дні каньйону",b="Коли лист потрапляє до Скельного Вартового Лонггорна на вершині високої столової гори Застави Вільного Вітру, він підтверджує найгірші побоювання поселення. Напад кентаврів давно переріс прикордонні сутички: розбійники влаштували засідку на важливий караван із припасами, що йшов дном каньйону, і вирізали весь обоз. Донесення змушує провідників тауренів негайно перейти від оборонної пильності до рішучої відплати й завдати злагоджених зустрічних ударів, щоб приборкати племена грабіжників, поки Заставу Вільного Вітру зовсім не відрізали від решти Калімдору."}},faq={{q="Що написано в Терміновому Посланні?",a="У посланні повідомлено про різке почастішання набігів кентаврів по всій Тисячі Голок: мандрівні загони й дороги в безпосередній небезпеці, а Заставі Вільного Вітру радять готуватися до війни.",al={"що каже лист","зміст термінового послання","про що послання"}},{q="Хто написав це послання і хто його отримує?",a="Його склав Сміливець Мунгорн, що стоїть біля Великого Підйомника з Пусток, і адресував просто Скельному Вартовому Лонггорну, командирові Застави Вільного Вітру.",al={"хто написав термінове послання","відправник термінового послання","хто отримує термінове послання"}},{q="Чому кентаври нападають на каравани з припасами?",a="Племена кентаврів здавна змагаються з тауренами за посушливі землі центрального Калімдору. Вони грабують каравани на дні каньйону, щоб забрати життєво важливі припаси й не дати Орді безпечно проходити Тисячею Голок.",al={"чому кентаври нападають","мотив кентаврів тисяча голок","чому кентаври грабують"}},{q="Про що розвідник застерігає щодо Ґрімтотемів?",a="Сміливець Мунгорн радить кожному гінцеві з посланням триматися подалі від сусіднього клану Ґрімтотем: його воїни поводяться дедалі відчуженіше й підозріліше щодо решти тауренів.",al={"застереження про ґрімтотемів","чому уникати ґрімтотемів","ґрімтотеми діють дивно"}}},fp="14,302,26.615.0,29.548.1,38.187.0,43.160.0,46.218.0,57.211.0"}
P.entries["item:valdred-s-hands"] = {n="Руки Валдреда",s="Руки Валдреда — відрубані кисті Валдреда Морея, забрані після його смерті на півдні Срібнолісся. Їх вимагає Ралей Андреан в Андерсіті як моторошний трофей і доказ помсти за вбивство своєї дружини.",h="Руки Валдреда — відрубані кисті Валдреда Морея, забрані після його смерті на півдні Срібнолісся.",kw={"руки валдреда","валдред морей","ралей андреан","помста","срібнолісся","стіна ґреймейна","андерсіті"},ang={["race:Undead"]="Вимога принести руки Валдреда — взірець холодної, мстивої вдачі Відступників: нездатність відчувати звичайний смуток вони часто перетворюють на затяжну, нав'язливу ворожнечу."},sec={{t="Моторошний трофей зради",b="Доки чума не поглинула Лордерон, Валдред Морей і Ралей Андреан були близькими друзями. Ця дружба розбилася, коли Валдред убив Ралеєву дружину, Делайю. Хоча Ралей помер і повстав одним із Відступників — і запевняє, що вже не здатен по-справжньому сумувати, — жага відплати так і не полишила його. Коли Валдред спробував утекти на південь, за Стіну Ґреймейна, до Ґілнеасу, Ралей відрядив посланця, щоб обірвати втечу колишнього друга, і зажадав його відрубаних рук як остаточного доказу, що справу зроблено."},{t="Гірка пам'ять",b="Отримавши відрубані руки, Ралей віддає гравірований перстень покійної дружини, відмахнувшись від нього як від нікчемної дрібнички. Делайя давно для нього мертва, тож сентиментальні пам'ятки минулого не дають йому жодної розради. Натомість руки Валдреда він зберігає як незмінне, холодне нагадування про зраду й звершену помсту."}},faq={{q="Хто такий Валдред Морей?",a="За життя Валдред Морей був близьким другом Ралея Андреана. Він зрадив цю дружбу, вбивши дружину Ралея, Делію, а згодом спробував утекти на південь, до Ґілнеаса.",al={"хто такий валдред","лор валдреда морея","історія валдреда"}},{q="Чому Ралей Андреан хоче саме руки Валдреда?",a="Ралей хоче руки, бо саме ними задушили чи вбили його дружину. На манер Відступників він тримає їх як відчутний трофей — пам'ятку про зраду друга й про помсту, яку він здійснив.",al={"чому руки","чому руки валдреда","трофей рук ралея"}},{q="Де знайти Валдреда Морея?",a="Валдред перебуває на півдні Срібнолісся, біля високої брами Стіни Ґреймейна, сподіваючись утекти до замкненого королівства Ґілнеас.",al={"де валдред","місце валдреда","поява валдреда морея"}},{q="Що стається з руками, коли їх принесено до Андерсіті?",a="Ралей лишає руки в Андерсіті як вічну пам'ятку про завершену помсту, а перстень убитої дружини викидає як непотрібну дрібничку.",al={"що ралей робить з руками","здати руки валдреда"}}},fp="15,232,29.545.0,20.336.1,22.189.0,59.208.0,29.169.0,59.162.1"}
P.entries["item:velinde-s-journal"] = {n="Щоденник Велінде",s="Щоденник Велінде — особисті записи жриці нічних ельфів Велінде Старсонг, що зберігаються в казармі Вартових у Дарнасусі. У ньому — важливі свідчення про її обов'язки й про загадкові обставини, за яких вона покинула місто.",h="Щоденник Велінде — особисті записи жриці нічних ельфів Велінде Старсонг, що зберігаються в казармі Вартових у...",kw={"щоденник велінде","велінде старсонг","жриця","вартові","тераса ремісників","дарнасус","сестринство елуни"},ang={["class:Priest"]="Велінде Старсонг була досвідченою жрицею, і її прихований обов'язок та подальше зникнення відкривають тяжкі випробування, що постали перед Сестринством Елуни.",["race:NightElf"]="Загадкове зникнення шанованої Сестри Елуни зачіпає саму верхівку Дарнасуса й непокоїть Вартових, що стережуть столицю калдореїв."},sec={{t="Записи жриці",b="Коли Жриця Велінде Старсонг покинула Дарнасус, її особисті речі замкнули в скрині в казармі Вартових на Терасі Ремісників. Серед збережених речей лежить і її щоденник, де вона описувала свої обов'язки й справи, перш ніж тихо зникнути. Вартові високо шанують Велінде й гадали, що в неї просто якісь особисті справи, але записи в щоденнику свідчать: її нез'ясована відсутність куди тривожніша, ніж здавалося спершу."}},faq={{q="Де знайти Щоденник Велінде?",a="Щоденник лежить у скрині Велінде в казармі Вартових на Терасі Ремісників у Дарнасусі. Щоб потрапити до будівлі, треба перейти верхнім мостом, що веде від крамниці кольчуг.",al={"місце щоденника","де щоденник велінде","місце скриньки велінде"}},{q="Хто така Велінде Старсонг?",a="Велінде Старсонг була шанованою жрицею нічних ельфів, якій глибоко довіряли Вартові. Вона раптово й тихо покинула Дарнасус, залишивши свою скриню й речі.",al={"хто така велінде","лор велінде"}},{q="Чому Вартових цікавить її щоденник?",a="Спершу Вартові вважали, що Велінде покинула Дарнасус із власних поважних причин і повернеться. Але її записи дають підказки, які свідчать, що за її зникненням криється щось темніше і це треба розслідувати.",al={"чому вартових цікавить щоденник","що в щоденнику"}},{q="Хто просить вас дістати щоденник?",a="Вартова Тин'тел Блейдвівер у Дарнасусі дає дозвіл і ключ від скрині Велінде, коли до неї звертаються зі знаннями з Фоліанта Мел'Тандріс.",al={"хто дає завдання","хто такий тінтел блейдвівер"}}},fp="17,254,20.498.0,33.213.0,25.183.0,44.260.0,37.182.0"}
P.entries["item:velinde-s-key"] = {n="Ключ Велінде",s="Ключ Велінде — невеликий ключ, який Тин'тел Блейдвівер у Дарнасусі довіряє шукачам пригод. Він відмикає особисту скриню в казармі Вартових, де зберігаються записи, залишені Жрицею Велінде Старсонг перед її загадковим зникненням.",h="Ключ Велінде — невеликий ключ, який Тин'тел Блейдвівер у Дарнасусі довіряє шукачам пригод.",kw={"ключ велінде","тин'тел блейдвівер","велінде старсонг","казарма вартових","тераса ремісників","фоліант мел'тандріс"},ang={["class:Priest"]="Жерці, що досліджують речі Велінде, йдуть слідами відданої сестри Елуни, чий шлях зробив самотній і тривожний поворот.",["race:NightElf"]="Для нічних ельфів речі Велінде — делікатна справа: вона була шанованою жрицею, чия вірність Елуні та своєму народові не викликала сумнівів."},sec={{t="Знак довіри",b="Цей простий ключ, який зберігає в Дарнасусі Тин'тел Блейдвівер, береже особисті речі Жриці Велінде Старсонг. Її земне майно відклали в скриню в казармі Вартових над Терасою Ремісників, коли вона без попередження покинула землі нічних ельфів. Блейдвівер віддає ключ лише тим, хто наведе вагомі докази — як-от відкриття з Фоліанта Мел'Тандріс, — що їх справді цікавить доля жриці."},{t="Ключ до минулого",b="Ключ відмикає скриню Велінде, де зберігається щоденник із записами про її обов'язки й тривожні думки. Вартові довго вважали, що Велінде просто пішла у своїх справах і колись повернеться, та записи за цим замком починають розплутувати значно темнішу й заплутанішу таємницю її фатальної мандрівки."}},faq={{q="Що відмикає Ключ Велінде?",a="Він відмикає скриню Велінде в казармі Вартових у Дарнасусі — на верхньому поверсі, за мостом на Терасі Ремісників.",al={"де використати ключ велінде","скринька велінде","яку скриню відчиняє"}},{q="Хто дає вам ключ?",a="Тин'тел Блейдвівер, Вартова з Дарнасуса, довіряє вам ключ під час розслідування зникнення Велінде.",al={"у кого ключ велінде","де взяти ключ велінде"}},{q="Хто така Велінде Старсонг?",a="Велінде Старсонг була шанованою жрицею нічних ельфів, якій довіряли Вартові. Вона раптово поїхала у власних справах, залишивши свої речі в Дарнасусі.",al={"хто така велінде","історія велінде"}},{q="Що лежить у її замкненій скрині?",a="У скрині лежить Щоденник Велінде — особистий запис про її обов'язки, що проливає світло на те, чому вона покинула землі нічних ельфів.",al={"що в скрині велінде","вміст скрині велінде"}}},fp="13,262,15.516.0,18.353.1,29.151.0,22.137.0,24.166.0,38.139.0"}
P.entries["item:venomtail-antidote"] = {n="Протиотрута Отрутохвоста",s="Протиотрута Отрутохвоста — особливе вариво, створене, щоб нейтралізувати смертельні токсини отрутохвостих скорпідів Дуротару. Приготована Кор'ґаном в Оргріммарі, вона слугує невідкладними ліками для Рінаґа — ураженого троля-розвідника, що застряг біля північно-західного кордону Дуротару.",h="Протиотрута Отрутохвоста — особливе вариво, створене, щоб нейтралізувати смертельні токсини отрутохвостих...",kw={"протиотрута","отрутохвіст","скорпід","кор'ґан","рінаґ","тіньова розколина","оргріммар"},ang={["faction:Horde"]="Навіть у серці Дуротару безжальна пустеля випробовує молодих шукачів пригод Орди і вимагає швидкої злагодженості між розвідниками в нетрях і міськими аптекарями.",["race:Troll"]="Троляча гордість глибока: Рінаґ радше ризикне померти на самоті в пустці, ніж стерпить відверті глузи Села Сен'джин через те, що його здолав скорпід."},sec={{t="Перегони з отрутою",b="Посушливі простори Дуротару кишать небезпечною звіриною, та для необережних мандрівників немає нічого небезпечнішого за тутешніх скорпідів. Глибокий укол отрутохвоста впорскує заразну отруту, здатну вбити дорослого воїна за годину. Коли троль Рінаґ дістав отруту далеко від допомоги біля північно-західного кордону, його єдиним порятунком були особливі ліки від Кор'ґана — аптекаря, що усамітнився глибоко в підземній Тіньовій Розколині Оргріммара."},{t="Ліки Кор'ґана",b="Щоб дістати протиотруту, треба пройти підземеллям Оргріммара й знайти Кор'ґана. Обізнаний у пустельних токсинах і суворих ліках, Кор'ґан готує флакон, щоб вигнати отруту, доки вона не стала смертельною. Доставлене вариво зупиняє дію отрути й рятує Рінаґа від принизливої смерті в нетрях, хоча Кор'ґан вимагає від розвідника подальших випробувань і полювань, аби спокутувати необережність."}},faq={{q="Для чого потрібна Протиотрута Отрутохвоста?",a="Протиотрута знешкоджує смертельну отруту скорпідів-отрутохвостів. Її шукають саме для того, щоб вилікувати Рінаґа — отруєного троля, що застряг на північно-західному кордоні Дуротару, і жити йому лишилося недовго.",al={"призначення протиотрути","кому потрібна протиотрута отрутохвоста","що робить протиотрута отрутохвоста"}},{q="Хто варить Протиотруту Отрутохвоста?",a="Протиотруту готує Кор'ґан, що живе в Тіньовій Розколині під Оргріммаром. Він знає силу скорпідів Дуротару й уміє протидіяти їхнім укусам.",al={"хто варить протиотруту","де взяти протиотруту отрутохвоста","протиотрута кор'ґана"}},{q="Чому з протиотрутою треба поспішати?",a="Отрута отрутохвоста швидко шириться кров'ю, і від укусу Рінаґу лишається жити менше години. Здобути протиотруту й щодуху принести її через Дуротар — єдиний спосіб уберегти його від смерті.",al={"чому поспішати з протиотрутою","скільки часу має рінаґ","таймер отрути отрутохвоста"}},{q="Чому Рінаґ не хоче шукати допомоги в Селі Сен'джин?",a="Рінаґ зізнається, що стати жертвою звичайного скорпіда — страшенно соромно. Він боїться повернутися до Села Сен'джин таким знесиленим, бо певен, що родичі глузуватимуть із його недбалості й дурості.",al={"чому не йти до сен'джина","гордість рінаґа","чому ховатися в дуротарі"}}},fp="18,270,24.475.0,15.418.0,40.225.0,33.182.0,52.214.0,55.199.0"}
P.entries["item:venomtail-poison-sac"] = {n="Отруйний Мішечок Отрутохвоста",s="Отруйний Мішечок Отрутохвоста — орган, здобутий зі скорпідів, що водяться в посушливих просторах Дуротару. Хоч він містить заразний токсин, здатний знесилити необережного мисливця, це також ключовий складник дієвої протиотрути.",h="Отруйний Мішечок Отрутохвоста — орган, здобутий зі скорпідів, що водяться в посушливих просторах Дуротару.",kw={"отруйний мішечок","отрутохвіст","скорпід","отрута","рінаґ","протиотрута","дуротар"},ang={["class:Hunter"]="Біда Рінаґа — наочний урок для мисливців: переслідувати небезпечних звірів, не знаючи їхньої отрути й не маючи при собі належних ліків, може легко коштувати слідопиту життя.",["faction:Horde"]="Молоді шукачі пригод Орди, пізнаючи сувору дійсність Дуротару, швидко з'ясовують: виживання вимагає розуміння звірини, бо тутешні токсини легко вбивають тих, хто кидається в червону пустку непідготованим."},sec={{t="Смертельний токсин і ліки від нього",b="Скорпіди, що нишпорять червоними скелями Дуротару — насамперед Отрутохвостий Скорпід, а також мутовані різновиди на кшталт Спотвореного Скорпіда й горезвісного Смертоздирача, — виробляють швидкодійну знесилювальну отруту. Збережена в особливих мішечках у хвості, ця отрута без лікування може швидко здолати навіть досвідчених воїнів. За іронією, ті самі мішечки, що завдають смертельного уколу, містять головні сполуки для синтезу протиотрути. Коли мисливець Рінаґ став жертвою уколу біля Оргріммара, місцевим алхімікам знадобилося чотири свіжі отруйні мішечки, щоб приготувати ліки й нейтралізувати отруту в його жилах."}},faq={{q="Які створіння мають ці отруйні мішечки?",a="Їх здобувають зі скорпідів Дуротару — передусім зі скорпідів-отрутохвостів, що никають на околицях Оргріммара, а також з осквернених скорпідів і рідкісного Смертоздирача.",al={"хто дропає мішечок отрутохвоста","де взяти мішечок отрутохвоста","які скорпіди мають мішечки"}},{q="Для чого потрібен отруйний мішечок?",a="Мішечки несуть Кор'ґанові в Оргріммар, щоб той виготовив особливу протиотруту. Ці ліки терміново потрібні мисливцеві Рінаґу, якого вжалили й отруїли, коли він полював без належної підготовки.",al={"використання мішечка отрутохвоста","навіщо мені мішечок"}},{q="Хто може зварити протиотруту з цих мішечків?",a="Кор'ґан з Оргріммара знає, як перетворити сиру отруту з чотирьох цілих мішечків на цілюще зілля, перш ніж отрута стане смертельною.",al={"хто зварить протиотруту","куди здати мішечки отрутохвоста","кор'ґан отрутохвіст"}}},fp="20,263,29.642.0,39.181.0,32.206.0,42.159.0"}
P.entries["item:venture-co-documents"] = {n="Документи Венчурної Компанії",s="Ці туго перев'язані папери знайдено в ящику серед решток розгромленого каравану на сході Малгору. Вони описують діяльність Венчурної Компанії й підтверджують, що хижий картель незаконно веде відкриті розробки на батьківщині тауренів.",h="Ці туго перев'язані папери знайдено в ящику серед решток розгромленого каравану на сході Малгору.",kw={"документи венчурної компанії","венчурна компанія","гобліни","морін клаудсталкер","розкопки","малгор"},ang={["profession:Mining"]="Папери знайдено разом із зразками сирих мінералів — доказ того, що передгір'я приховують багаті, ще не займані жили, готові до розробки.",["race:Tauren"]="Священну землю Матері-Землі оскверняють гоблінські машини. Доставлені папери допомагають старійшинам підтвердити розмах наруги й завдати удару у відповідь."},sec={{t="Докази визискування",b="Знайдені поверх видобутої руди й мінералів у рештках пограбованого воза, ці документи викривають розмах вторгнення Венчурної Компанії в Малгор. Відомий по всьому Калімдору безжальним вирубуванням лісів і нестримними розкопками, очолюваний гоблінами картель тихцем влаштував бурові й копальні застави у східних передгір'ях. Морін Клаудсталкер і таурени-скороходи спираються на ці захоплені реєстри, щоб оцінити загрозу своїм священним прабатьківським рівнинам і зібрати мисливців, аби вигнати зайд."}},faq={{q="Що містять Документи Венчурної Компанії?",a="У пачці паперів описано роботи Венчурної Компанії з видобутку на сході Малгору: з них видно, що гоблінське підприємство активно видобуває й вивозить природні мінеральні багатства краю.",al={"зміст документів венчурної компанії","що за документи венчур","що написано в документах"}},{q="Де знайшли ці документи?",a="Їх дістають із запечатаного ящика Венчурної Компанії серед уламків пограбованого воза на місці Сплюндрованого Каравану, на схід від Села Бладгуф.",al={"де знайти документи","місце документів венчур","ящик зруйнованого каравану"}},{q="Кому треба показати ці папери?",a="Їх треба віднести Морінові Клаудсталкеру — тауренові-мисливцю, що стоїть на головній стежці на схід від Села Бладгуф і пильнує безпеку Малгору.",al={"кому віднести документи","здати документи венчур","документи моріна клаудстокера"}},{q="Чому Венчурна Компанія веде видобуток у Малгорі?",a="Венчурна Компанія діє лише заради зиску: шукає багаті рудні жили й незаймані землі, щоб вичищати з них цінні руди, геть не зважаючи ні на угоди з корінними народами, ні на духовні звичаї, ні на довкілля.",al={"чому гобліни в малгорі","мета венчурної компанії в малгорі","чому венчур копає"}}},fp="21,241,24.514.0,42.214.0,38.157.0,30.158.0,46.205.0"}
P.entries["item:venture-co-engineering-plans"] = {n="Інженерні Креслення Венчурної Компанії",s="Інженерні Креслення Венчурної Компанії — механічні схеми, що зберігаються на гоблінській лісопильні на Кручі Вітрорізу. Здобуті агентами Альянсу, вони описують будову важких машин, що спустошують Гори Кам'яного Кігтя.",h="Інженерні Креслення Венчурної Компанії — механічні схеми, що зберігаються на гоблінській лісопильні на Кручі...",kw={"інженерні креслення венчурної компанії","венчурна компанія","круча вітрорізу","ґаксим растфіззл","креслення","лісопильня"},ang={["profession:Engineering"]="Жорстоким, ненажерливим машинам Венчурної Компанії, може, й бракує витонченості, але їхні механічні креслення приховують цінні знання про важку промислову техніку.",["race:Gnome"]="Для гномів-винахідників здобути креслення суперників-гоблінів — і перемога розуму, і скарбниця промислових ідей, які тільки й чекають, щоб їх пристосували."},sec={{t="Промислові таємниці",b="Круча Вітрорізу задихається від диму й лісорубних машин, поки Венчурна Компанія оголює ліси Гір Кам'яного Кігтя. Заховані на їхній лісопильні на південь від Озера Скельної Заводі, ці інженерні креслення докладно викладають будову, сильні й слабкі сторони їхніх особливих лісозаготівельних механізмів."},{t="Гномське шпигунство",b="Гном-інженер Ґаксим Растфіззл задумав таємну операцію, щоб зірвати лісозаготівлі Венчурної Компанії й водночас здобути ці документи. Закладена вибухівка дає негайну шкоду, а креслення дозволяють майстрам Альянсу методично використовувати вади будови гоблінських машин і перейняти їхні винахідливі рішення для власних задумів Альянсу."}},faq={{q="Де зберігаються Інженерні Креслення Венчурної Компанії?",a="Креслення лежать на головній лісопильні Венчурної Компанії на Кручі Вітрорізу, на південь від Озера Скельної Заводі в Горах Кам'яного Кігтя.",al={"де знайти інженерні креслення","місце креслень стоунталон","де креслення"}},{q="Кому потрібні ці інженерні креслення?",a="Ґаксим Растфіззл, гном з Альянсу, що координує таємні операції в Горах Кам'яного Кігтя, посилає агентів їх дістати.",al={"кому потрібні креслення","хто бере інженерні креслення","креслення ґаксіма растфізла"}},{q="Чому ці креслення важливі для Альянсу?",a="Креслення розкривають серйозні вади конструкції лісорубних машин Венчурної Компанії, тож агенти можуть ефективніше їх нищити, а гноми Альянсу отримують промислові розробки, які можна використати у власних винаходах.",al={"чому красти креслення","що роблять креслення"}},{q="З якою операцією пов'язана крадіжка креслень?",a="Здобути ці креслення — головна мета таємної операції «Альфа». Хоча завдання передбачає й закладання детонаторів по всьому об'єкту, справжній успіх операції — повернутися з кресленнями.",al={"операція прихованих дій альфа","для якого завдання"}}},fp="29,240,18.305.0,17.378.1,52.146.0,34.122.0,51.253.0,47.203.0"}
P.entries["item:venture-co-letters"] = {n="Листи Венчурної Компанії",s="Листи Венчурної Компанії — внутрішнє листування, здобуте в Шахті Зрізаного Вітру в Горах Кам'яного Кігтя. Викрадені під прикриттям вибухів-відволікань, вони дають вартовим нічних ельфів важливі відомості про гоблінський промисел у краї.",h="Листи Венчурної Компанії — внутрішнє листування, здобуте в Шахті Зрізаного Вітру в Горах Кам'яного Кігтя.",kw={"листи венчурної компанії","шахта зрізаного вітру","круча вітрорізу","каела шедовспір","вартові","венчурна компанія"},ang={["faction:Alliance"]="Розвідники Альянсу налагоджують таємні вилазки проти Венчурної Компанії, щоб захистити володіння нічних ельфів у Горах Кам'яного Кігтя від хижацького промислового визиску.",["race:NightElf"]="Осквернення Гір Кам'яного Кігтя гоблінськими лісорубними машинами б'є в самісіньке серце дикої природи Калімдору, тож відомості про задуми Венчурної Компанії вкрай важливі для вартових."},sec={{t="Промислова розвідка",b="Кручу Вітрорізу заполонила Венчурна Компанія, чиї лісорубні машини й відкритий видобуток роздирають давній ліс. Щоб з'ясувати весь розмах задумів картелю, агенти Альянсу вдалися до таємної диверсії: улаштували відволікання й пробралися в Шахту Зрізаного Вітру. Ці здобуті листи містять приватне листування й записи про постачання, що описують місцеві справи компанії, і дають верхівці вартових уявлення про те, як плюндрувальники організовують своїх робітників і шляхи постачання."},{t="Доставка вартовим",b="Щойно листи винесено з глибин шахти, їх поспіхом доставляють командирці вартових Каелі Шедовспір. Під тиском і гоблінів-плюндрувальників, і вторгнень Орди в Гори Кам'яного Кігтя, вартові покладаються на це викрадене листування, щоб передбачити наступні кроки Венчурної Компанії й зберегти те, що лишилося від священних гір."}},faq={{q="Що таке Листи Венчурної Компанії?",a="Це внутрішні робочі документи й листування, які Венчурна Компанія тримає в Шахті Зрізаного Вітру в Горах Кам'яного Кігтя.",al={"листи венчурної компанії","що за листи","листи стоунталон"}},{q="Де знайти листи?",a="Вони лежать серед Документів Венчурної Компанії в Шахті Зрізаного Вітру на східному краю Кручі Вітрорізу.",al={"де листи","місце листів","листи шахти віндширу"}},{q="Кому потрібні ці листи?",a="Таємною операцією з їх викрадення керує гном-агент Ґаксим Растфіззл, а зрештою листи доставляють Каелі Шедовспір, що очолює місцевих Вартових нічних ельфів.",al={"кому потрібні листи","хто хоче листи","здати листи"}},{q="Навіщо Вартовим це листування?",a="Вартові борються, щоб зупинити нестримну вирубку й розкопки в Горах Кам'яного Кігтя. Листи розкривають логістичні плани й робочі пріоритети Венчурної Компанії, допомагаючи захисникам планувати боротьбу з нею.",al={"навіщо вартовим листи","інтерес вартових"}}},fp="19,266,23.513.0,25.336.1,33.129.0,28.122.0,24.174.0,46.220.0"}
P.entries["item:verdant-note"] = {n="Зелена Записка",s="Зелена Записка — виклик, який вручають друїдам-новачкам із тауренів у Таборі Нарачі. Надіслана від імені наставника друїдів Ґарта Містраннера, вона наказує молодим посвяченим з'явитися на навчання й почати осягати обряди Матері-Землі.",h="Зелена Записка — виклик, який вручають друїдам-новачкам із тауренів у Таборі Нарачі.",kw={"зелена записка","друїд","ґарт містраннер","табір нарачі","мати-земля","таурени"},ang={["class:Druid"]="Цей пергамент знаменує ваше офіційне прийняття до друїдичної науки серед тауренів і початок довічної подорожі в єднанні з Матір'ю-Землею.",["race:Tauren"]="Для шу'гало друїдизм — прабатьківське покликання, безпосередньо пов'язане зі зціленням рівноваги їхніх священних мисливських угідь у Малгорі."},sec={{t="Поклик на шлях",b="Молоді таурени, що виявляють духовну спорідненість із природою, отримують Зелену Записку невдовзі після початку своїх випробувань на Плато Червоної Хмари. Коротке послання приносить гонець від Ґарта Містраннера, і воно велить посвяченому стати перед наставником там, де стоїть Табір Нарачі. Неспокійні духи й мінливі стихії почали тривожити Малгор, тож навчання нових друїдів стало для старійшин нагальним обов'язком."},{t="Науки Матері-Землі",b="Відгукнувшись на записку, посвячені вступають у глибші таємниці єднання з природою. Ґарт Містраннер застерігає молодих друїдів: хоч нічні ельфи поділяють той самий зв'язок із дикою природою, їхня прадавня гордість тримає їх на відстані й робить непривітними. Друїдизм тауренів зосереджений суто на шані до Матері-Землі: він учить посвячених слухати неспокійні голоси предків у землі й бути її живими знаряддями."}},faq={{q="Що таке Зелена Записка?",a="Це письмове запрошення для тауренів — друїдів-початківців у Таборі Нарачі: воно велить їм розшукати свого наставника, Ґарта Містраннера, щоб офіційно розпочати духовне навчання.",al={"предмет зелена записка","що це за записка"}},{q="Хто надсилає Зелену Записку?",a="Записку передає гонець від імені Ґарта Містраннера, наставника друїдів у Таборі Нарачі на Плато Червоної Хмари.",al={"хто надіслав зелену записку","хто написав зелену записку"}},{q="Чому Ґарт Містраннер скликає новачків-друїдів?",a="Духи предків по всьому Малгору й сусідніх краях стали незвично неспокійними. Ґартові треба швидко навчити новопосвячених друїдів, щоб ті могли спілкуватися з дикими духами й зцілювати стривожену землю.",al={"чому ґарт хоче мене","причина ґарта містраннера"}},{q="Що Ґарт каже друїдам про нічних ельфів?",a="Ґарт застерігає, що хоч нічні ельфи й мають священний зв'язок із природою, вони горді й навряд чи радо приймуть тауренів у свої кола. Він радить новачкам зосередитися натомість на вченні Земної Матері.",al={"нічні ельфи й таурени друїди","що про нічних ельфів"}}},fp="12,233,18.422.0,28.421.0,25.189.0,27.128.0,51.207.0,53.233.0"}
P.entries["item:verdant-sigil"] = {n="Зелений Сигіл",s="Зелений Сигіл — вирізьблений друїдський знак, який вручають молодим друїдам — нічним ельфам, що починають навчання в Тінедолі. Принесений як виклик від наставника друїдів Марданта Стронґоука, він позначає офіційний вступ новачка до науки Кола Кенарія під гілками Алдрассила.",h="Зелений Сигіл — вирізьблений друїдський знак, який вручають молодим друїдам — нічним ельфам, що починають...",kw={"зелений сигіл","друїд","мардант стронґоук","консерватор ілталайн","тінедол","алдрассил","смарагдовий сон"},ang={["class:Druid"]="Для молодих друїдів — нічних ельфів дістати Зелений Сигіл — традиційний перший обряд посвяти, що з'єднує простий догляд за лісом із дисциплінованою наукою Кола Кенарія.",["race:NightElf"]="Вручений під шатром Алдрассила, сигіл уособлює тривку традицію калдореїв настроювати свій дух на природний світ і охоронців Тельдрассила."},sec={{t="Поклик на шлях",b="У затишному вітті Тінедолу молоді нічні ельфи, що відчувають поклик дикої природи, дістають Зелений Сигіл від Консерватора Ілталайна. Надісланий посланцем від наставника Марданта Стронґоука, знак велить новачкам піднятися у віття великого дерева Алдрассил. Носити сигіл — офіційне запрошення залишити прості клопоти й розпочати серйозне навчання єднання з духами природи та глибоких таємниць Смарагдового Сну."},{t="Перший крок у Сон",b="Піднесений Мардантові Стронґоуку, сигіл посвячує молодого друїда в його довічне ремесло. Хоч новачки ще не готові ходити сонним трансом Смарагдового Сну, прийняття сигіла позначає початок їхнього наставництва. Під проводом Марданта посвячені вчаться тлумачити шепіт дикого краю й опановують перші мистецтва перевтілення й зцілення на службі Тельдрассилу."}},faq={{q="Для чого потрібен Зелений Сигіл?",a="Зелений Сигіл — вступний знак для нічних ельфів — друїдів-початківців у Тінедолі. Це офіційне запрошення від наставника Марданта Стронґоука: воно велить новим друїдам знайти його всередині дерева Алдрассил, щоб розпочати справжнє навчання.",al={"що робить зелений сигіл","чому в мене зелений сигіл","використання зеленого сигіла"}},{q="Хто видає Зелений Сигіл?",a="Консерватор Ілталайн вручає сигіл молодим друїдам невдовзі після того, як вони починають допомагати йому в Тінедолі, передаючи послання від Марданта Стронґоука.",al={"хто дає зелений сигіл","де взяти зелений сигіл"}},{q="Куди нести сигіл, коли я його отримаю?",a="Ви несете сигіл Мардантові Стронґоуку — наставникові друїдів, що перебуває в центральних покоях великого дерева Алдрассил у серці Тінедолу.",al={"куди нести зелений сигіл","хто бере зелений сигіл","здати зелений сигіл"}},{q="Що стається, коли показати сигіл Мардантові Стронґоуку?",a="Мардант приймає сигіл і офіційно вітає вас як свого учня. Він стає вашим провідником у єднанні з природою й обіцяє, що в міру того, як ви міцнітимете, підготує вас до таїн Смарагдового Сну.",al={"що мардант робить з сигілом","після зеленого сигіла"}}},fp="13,283,21.462.0,29.403.0,41.250.0,32.163.0,44.161.0,61.229.0"}
P.entries["item:verna-s-westfall-stew-recipe"] = {n="Рецепт Вестфоллського Рагу від Верни",s="«Рецепт Вестфоллського Рагу від Верни» — рукописний кулінарний посібник, який Верна Фурлброу записала, готуючись тікати з Вестфолу. Довірений мандрівникам, що прямують до Салми Салдін, він зберігає ситну страву краю посеред занепаду сільських земель.",h="«Рецепт Вестфоллського Рагу від Верни» — рукописний кулінарний посібник, який Верна Фурлброу записала...",kw={"рецепт вестфоллського рагу","верна фурлброу","салма салдін","вестфоллське рагу","кулінарія","вестфол"},ang={["faction:Alliance"]="Рецепт уособлює трагічне вигнання вірних господарів Альянсу, яких витіснило беззаконня, поки Стормвінд насилу утверджує свою владу.",["profession:Cooking"]="Для кулінарів цей рукописний аркуш — дорогоцінна частка місцевих переказів, що береже кулінарну спадщину Вестфолу, навіть коли його ферми занепадають."},sec={{t="Прощальний подарунок",b="Поки Братство Дефіас і здичавілі жнивні големи хазяйнують у Вестфолі, давні господарі на кшталт Верни й Фермера Фурлброу мусять покинути свою землю. Чекаючи, доки полагодять їхній віз, щоб утекти до Стормвінда, Верна нашвидкуруч записує свій улюблений рецепт Вестфоллського Рагу. Щоб рецепт не зник разом із ними, вона довіряє його перехожим мандрівникам і просить передати сусідці й подрузі, Салмі Салдін, — аби для тих, хто лишається, зберігся теплий, знайомий затишок."}},faq={{q="Чому Верна віддає свій рецепт рагу?",a="Верна з чоловіком тікають із Вестфолу, бо їхні поля заполонили бандити й здичавілі машини. Знаючи, що мусить покинути ферму, вона хоче, щоб її подруга Салма Салдін і далі варила це рагу для тих, хто лишається.",al={"чому верна віддає рецепт","рецепт вестфоллського рагу","призначення рецепта верни"}},{q="Кому призначено рецепт?",a="Рецепт адресовано Салмі Салдін, що живе одразу за роздоріжжям, на Фермі Салдина.",al={"кому рецепт","кому віднести рецепт","куди рецепт рагу"}},{q="Куди збираються Фурлброу?",a="Подружжя Фурлброу чекає, поки полагодять віз, щоб утекти в безпечний Стормвінд, подалі від хаосу й розбою, що загрожують сільському краю.",al={"куди фурлброу їдуть","куди йде верна","куди прямують фурлброу"}},{q="Чим Вестфоллське Рагу славиться в краї?",a="Вестфоллське Рагу — основна місцева страва, що тримається на здобутках фермерів і мисливців. У скрутні часи, коли їжі бракує, а ферми спорожніли, поживні рецепти, якими діляться одне з одним, допомагають уцілілим фермерським родинам вистояти.",al={"що таке вестфоллське рагу","чим славиться вестфоллське рагу","лор вестфоллського рагу"}}},fp="28,245,15.539.0,41.238.0,28.105.0,39.159.0,47.208.0"}
P.entries["item:verner-s-note"] = {n="Записка Вернера",s="Записка Вернера — письмова заявка, яку коваль Лейкширу Вернер Осґуд надіслав Ковалеві Арґусу в Ґолдшир. У ній ідеться про гостру нестачу заліза в Редріджі й міститься прохання до елвіннського коваля терміново надіслати підкови.",h="Записка Вернера — письмова заявка, яку коваль Лейкширу Вернер Осґуд надіслав Ковалеві Арґусу в Ґолдшир.",kw={"записка вернера","вернер осґуд","коваль арґус","підкови","ґолдшир","лейкшир"},ang={["faction:Alliance"]="Записка підкреслює, як напружено працює сільське господарство Стормвінда: прикордонні містечка на кшталт Лейкширу мусять домовлятися з селами в серці королівства, аби просто втримати постачання.",["profession:Blacksmithing"]="Записка показує логістику прикордонної війни: коли зброя й обладунки поглинають кожен зливок, звичайні речі на кшталт підків доводиться завозити з безпечніших поселень, як-от Ґолдшир."},sec={{t="Прохання про залізо",b="Оборона Лейкширу поглинає силу-силенну обробленого металу. Варта Стормвінда, що стоїть у містечку, ледве стримує гнолів-загарбників та інші місцеві небезпеки, і Вернер Осґуд витратив майже всі запаси заліза, щоб озброїти й одягти в обладунки солдатів. Через це стайні Лейкширу занедбані: там бракує навіть звичайних підків для коней. Цей лист — знак того, що Вернер поступився гордістю й просить Коваля Арґуса з Ґолдширу прислати готові підкови, щоб міські коні знову могли ходити в дорогу."}},faq={{q="Що написано в Записці Вернера?",a="У записці Вернер пояснює Ковалеві Арґусу, що витратив увесь свій метал на зброю для Вартових Стормвінда в Лейкширі. Заліза, щоб кувати підкови для місцевих коней, у нього вже не лишилося, тож він просить надіслати партію підків просто з Ґолдширу.",al={"зміст записки вернера","що каже записка","повідомлення записки вернера"}},{q="Хто такий Вернер Осґуд?",a="Вернер Осґуд — місцевий коваль із Лейкширу в Горах Редріджу. Він споряджає захисників містечка й дбає, щоб робоче знаряддя було справне, а тварини підковані.",al={"хто такий вернер","вернер осґуд редрідж"}},{q="Хто отримує цю записку?",a="Записку несуть дорогою на захід Ковалеві Арґусу — міському ковалеві, що гупає молотом біля кузні в Ґолдширі в Лісі Елвінн.",al={"хто отримує записку вернера","куди нести записку","хто коваль арґус"}},{q="Чому Вернер не може сам викувати підкови?",a="Лейкшир переживає скруту через гнолів та інші загрози краю. Увесь свій час і все залізо Вернер віддає на зброю та ремонт для Вартових Стормвінда, тож для стайні нічого не лишається.",al={"чому лейкшир потребує підків","чому слати в ґолдшир по підкови"}}},fp="13,230,15.533.0,33.243.0,21.187.0,23.142.0,45.223.0"}
P.entries["item:verog-s-head"] = {n="Голова Вероґа",s="Голова Вероґа — моторошний трофей, здобутий у Вероґа Дервіша, знаного ватажка кентаврів-Колкарів, що командує загонами довкола Застояної Оази. Її шукає орк Реґтар Дезґейт — як доказ смерті вождя і щоб зламати дух войовничих племен Колкарів, які загрожують Пусткам.",h="Голова Вероґа — моторошний трофей, здобутий у Вероґа Дервіша, знаного ватажка кентаврів-Колкарів, що командує...",kw={"голова вероґа","вероґ дервіш","колкари","кентаври","реґтар дезґейт","застояна оаза"},ang={["faction:Horde"]="Знищивши Вероґа й здобувши його голову, ви вбезпечуєте шляхи Орди між Перехрестям і південними околицями Пусток від нахабних набігів кентаврів.",["race:Tauren"]="Поразка вождів Колкарів має для тауренів глибоко особисте значення: їхній народ поколіннями терпів жорстокі війни з кентаврськими племенами Калімдору."},sec={{t="Трофей оази",b="Кентаври-Колкари — невідступна загроза для мандрівників і шляхів постачання Орди на півночі Пусток. Вероґ Дервіш, відомий своїми кочовими звичками, блукає посушливими чагарниками й лишає свій командний намет біля Застояної Оази без захисту. Щоб виманити його, бійці Орди атакують його загони довкола шатра, доки не здійметься тривога. Щойно Вероґ мчить назад боронити табір, його вбивають і відтинають йому голову. Доставлена Реґтарові Дезґейту, голова — важливий доказ того, що ще одного небезпечного вождя Колкарів знищено; вона займе місце поруч із виставленою головою Барака Кодобейна."}},faq={{q="Хто такий Вероґ Дервіш?",a="Вероґ Дервіш був рухливим воєначальником кентаврів Колкар, що базувалися в Застояній оазі в Пустках. Відомий тим, що мандрував посушливими рівнинами вздовж і впоперек, він керував ворожими загонами кентаврів, які стояли довкола командного намету в оазі.",al={"хто такий вероґ","лор вероґа","вероґ дервіш"}},{q="Кому потрібна голова Вероґа?",a="Голову забирає Реґтар Дезґейт, орк-ветеран із табору на захід від Перехрестя. Реґтар збирає трофеї з убитих ватажків Колкарів, щоб зламати силу й бойовий дух їхніх загонів.",al={"хто бере голову вероґа","реґтар деткейт вероґ","здати голову вероґа"}},{q="Де знайти Вероґа?",a="Табір і командний намет Вероґа — у Застояній оазі, на південний схід від Перехрестя. Вероґ не чекає без діла біля свого шатра: щоб виманити його, треба перебити кентаврів, що стережуть пост, доки тривога не покличе його назад.",al={"де вероґ","місце вероґа","намет застійного оазису"}},{q="Що стається з головою, коли її здано?",a="Реґтар Дезґейт ставить голову Вероґа поряд із головою Барака Кодобейна: похмурі трофеї позначають планомірний похід Орди проти ватажків Колкарів.",al={"що реґтар робить з головою","виставка голів кентаврів"}}},fp="12,295,21.616.0,26.234.0,23.210.0,21.242.0,47.177.0"}
P.entries["item:vial-of-innocent-blood"] = {n="Фіал Невинної Крові",s="Фіал Невинної Крові — моторошний алхімічний реактив, який збирають тіньові маги Синдикату, що ховаються в руїнах Твердині Дурнгольд. Його шукає Королівське Аптекарське Товариство в Таррен Міллі: він слугує ключовим каталізатором для приготування експериментальних отрут.",h="Фіал Невинної Крові — моторошний алхімічний реактив, який збирають тіньові маги Синдикату, що ховаються в...",kw={"фіал невинної крові","синдикат","твердиня дурнгольд","аптекар лайдон","королівське аптекарське товариство","таррен мілл","відступники"},ang={["faction:Horde"]="Здобувши цей реактив, ви допомагаєте Орді в ширшій боротьбі за землі проти вирубки лісів Венчурною Компанією в Горах Кам'яного Кігтя.",["race:Undead"]="Королівське Аптекарське Товариство рідко гидує морально сумнівними складниками й охоче поживляється в людей-розбійників, аби просунути свої алхімічні досягнення."},sec={{t="Жахливий реактив",b="У зруйнованих мурах Твердині Дурнгольд занепалі людські шляхтичі з Синдикату вдаються до темних і мерзенних мистецтв. Серед них є тіньові маги, які систематично збирають кров невинних для своїх окультних ритуалів. Ця моторошна практика привернула пильну увагу Аптекаря Лайдона в Таррен Міллі. Йому потрібна незаплямована кров, щоб зварити експериментальний «заспокійливий» засіб, покликаний знешкодити Венчурну Компанію в Горах Кам'яного Кігтя, тож аптекар-Відступник бачить у похмурих запасах Синдикату зручний спосіб скоротити собі роботу."}},faq={{q="Для чого потрібен Фіал Невинної Крові?",a="Аптекар Лайдон у Таррен Міллі варить із цієї крові особливу отруту, яка має приборкати агресію операторів Венчурної Компанії, що завдають клопоту Орді в Горах Кам'яного Кігтя.",al={"використання невинної крові","для чого фіал невинної крові","кров невинних"}},{q="Хто носить ці фіали?",a="Їх носять маги тіні Синдикату, що стоять довкола зруйнованої Твердині Дурнгольд на південному сході Передгір'я Гілсбреда.",al={"хто дропає фіал невинної крові","де взяти невинну кров","маги тіні синдикату"}},{q="Звідки в магів тіні Синдикату невинна кров?",a="Розбійники й занепала знать Синдикату тримають тіньових чаклунів, які збирають і зберігають кров невинних для власних темних, мерзенних магічних дослідів.",al={"чому в синдикату кров","кров'яні ритуали синдикату"}},{q="Навіщо Аптекареві Лайдону кров невинних?",a="Лайдон зауважує, що кров невинних має особливі, рідкісні властивості, потрібні для зілля, яке витягає зі своїх жертв жорстокість і робить їх покірними.",al={"навіщо невинна кров","кров аптекаря лайдона"}}},fp="22,249,18.538.0,44.198.0,24.138.0,50.173.0,52.184.0"}
P.entries["item:vial-of-phlogiston"] = {n="Фіал Флогістону",s="Фіал Флогістону — алхімічна речовина, якою майстри-бронярі гартують надзвичайно міцні кольчуги. Його стережуть у твердині шипогривів Рейзорфен Краул, і його прагнуть здобути ковалі і Альянсу, і Орди, що кують особливі бойові обладунки для перспективних воїнів.",h="Фіал Флогістону — алхімічна речовина, якою майстри-бронярі гартують надзвичайно міцні кольчуги.",kw={"фіал флогістону","флогістон","рейзорфен краул","фурен лонґбірд","тун'ґрім файрґейз","рооґуґ"},ang={["class:Warrior"]="Здобути Фіал Флогістону — важливий рубіж на шляху до знаменитих загартованих обладунків, що доводить вашу здатність прорватися до Рейзорфен Краулу.",["profession:Blacksmithing"]="Флогістон — вершина особливої металургії: він слугує життєво важливим флюсом для гартування легендарної кольчуги."},sec={{t="Есенція горна",b="Флогістон — надзвичайно непередбачувана вогненосна речовина, яку цінують у таємничій металургії. І дворфійський коваль Фурен Лонґбірд у Стормвінді, і майже сліпий орк-броняр Тун'ґрім Файрґейз у Пустках вважають його незамінним складником, щоб загартувати обладунки воїна понад звичайні фізичні межі. Без цього алхімічного засобу неможливо завершити особливе кування загартованої вогнем кольчуги чи лютого обладунку Орди."},{t="Здобутий серед терну",b="Щоб здобути Фіал Флогістону, доведеться вирушити в заплутані хащі Рейзорфен Краулу на південному краю Пусток. Флогістон зберігає глибоко в цій колючій твердині геомант Рооґуґ. Чи для Фурена в Стормвінді, чи для ковадла Тун'ґріма за запорошеними рівнинами — по цю речовину доведеться спуститися на небезпечну ворожу землю шипогривів."}},faq={{q="Для чого потрібен флогістон?",a="Майстри-ковалі використовують флогістон як алхімічний каталізатор гартування. Він дає надзвичайно сильний зосереджений жар, щоб загартувати сиру кольчугу й залізо на неймовірно міцні обладунки воїна.",al={"використання флогістону","що робить флогістон","навіщо мені флогістон"}},{q="Хто носить Фіал Флогістону?",a="Фіал носить Рооґуґ, геомант-шипогрив, що живе глибоко в колючих тунелях Рейзорфен Краулу на півдні Пусток.",al={"хто дропає фіал флогістону","дроп фіала флогістону","де взяти фіал флогістону"}},{q="Яким ковалям потрібен цей матеріал?",a="І Фурену Лонґбірду в Стормвінді, і Тун'ґрімові Файрґейзу в Пустках потрібен Фіал Флогістону, щоб викувати неповторні загартовані обладунки для досвідчених воїнів.",al={"яким ковалям потрібен фіал флогістону","завдання флогістону","які завдання потребують флогістону"}}},fp="18,276,20.454.0,27.384.0,28.187.0,35.135.0,35.161.0"}
P.entries["item:vial-of-purest-water"] = {n="Фіал Найчистішої Води",s="Фіал найчистішої води — священна посудина, яку благословила самітниця Брайн на південному узбережжі Пусток. Його вручають новачкові-шаману, і очищений вміст фіала необхідний, щоб приготувати напій, який дає змогу бачити невловимих духів стихій.",h="Фіал найчистішої води — священна посудина, яку благословила самітниця Брайн на південному узбережжі Пусток.",kw={"фіал найчистішої води","брайн","іслен вотерсір","тотем води","шаман","сапта"},ang={["class:Shaman"]="Здобувши й доставивши цю очищену воду, ви робите останні кроки до єднання з духами води й здобуття Тотема Води.",["faction:Horde"]="Випробування довкола фіала ведуть молодих шаманів Орди і Калімдором, і Східними Королівствами, поглиблюючи їхній зв'язок зі стихіями."},sec={{t="Очищена пожертва",b="Вода, запечатана в цьому фіалі, здобута у випробуваннях терпіння й очищення під наглядом Брайн, — це рідина в її неоскверненій стихійній суті. Її несуть через посушливі пустища Пусток назад на самотній берег, де чатує Іслен Вотерсір, і там фіал стає головним складником для водяної сапти. Без його незайманої чистоти шаман не зможе розмовляти з духами-охоронцями, що живуть далеко від випалених сонцем рівнин."},{t="Шлях до Тотема Води",b="Іслен використовує благословенну рідину не лише щоб перевірити відданість учня, а й щоб відкрити його чуття до прихованих стихій. Частину води додають у сапту, щоб побачити духів, які чатують біля далекого святилища в Срібноліссі, а решту крапель зберігають, щоб зустріти й очистити некеровану стихійну сутність деінде. Цей фіал — поворотна мить, коли молодий містик переходить від скромних доручень до прямої зустрічі зі стихійною дійсністю."}},faq={{q="Для чого потрібен Фіал Найчистішої Води?",a="У фіалі — ретельно очищена й благословенна вода, яку дають новачкові-шаману. Іслен Вотерсір варить із неї водяну сапту — еліксир, що дарує духовний зір, аби бачити водяних елементалів, — і використовує її для подальших обрядових випробувань, без яких не здобути Тотем Води.",al={"призначення фіала найчистішої води","що робить фіал","використання найчистішої води"}},{q="Хто готує воду у фіалі?",a="Воду збирає сам шаман під наглядом Брайна — елементаля-відлюдника, що живе біля південного узбережжя Пусток. Коли воду зібрано через низку випробувань, Брайн благословляє очищену воду й запечатує її у фіалі для перенесення.",al={"хто зробив фіал","хто наповнює фіал","вода брайн"}},{q="Куди треба віднести фіал?",a="Фіал треба повернути Іслен Вотерсір, що живе на східному березі Пусток, трохи на південь від Раджета, з видом на Велике Море.",al={"кому віддати фіал","куди доставити фіал","здати найчистішу воду"}},{q="Куди веде обряд, коли фіал доставлено?",a="Отримавши фіал і зваривши сапту, Іслен Вотерсір посилає шамана через море до Східних Королівств — до святилища в Срібноліссі на південь від Андерсіті.",al={"куди йти далі","наступний крок після фіала","святиня води сільверпайну"}}},fp="20,260,19.479.0,23.491.1,42.287.0,39.244.0,37.147.0,53.198.0"}
P.entries["item:vial-of-spider-venom"] = {n="Фіал Павучої Отрути",s="Фіал Павучої Отрути містить сильну мертвотну отруту павуків, що заполонили темні ліси Сутінколісся. Мадам Єва з Даркшира поєднує цю небезпечну витяжку з рештками нежиті, щоб виготовляти обереги від лиха.",h="Фіал Павучої Отрути містить сильну мертвотну отруту павуків, що заполонили темні ліси Сутінколісся.",kw={"фіал павучої отрути","павуки","нараксіс","мадам єва","тотем покари","сутінколісся"},ang={["class:Rogue"]="Розбійники вміють варити тонкі отрути й змащувати ними клинки, але ця сира, неочищена павуча отрута призначена для містичного захисту, а не для прямого вбивства.",["faction:Alliance"]="Для шукачів пригод з Альянсу, що мандрують темними шляхами Сутінколісся, допомога Мадам Єві з її захисними тотемами — це спосіб уберегти подорожніх від жахіть лісу."},sec={{t="Отруйна загроза Сутінколісся",b="Темні хащі Сутінколісся ховають жахливих павуків — від метушливих карликових отруйних тенетників і зелених самітників до чорних вдів і сумнозвісного Нараксіса. Ці створіння впорскують через ікла бридку, сильну отруту, здатну паралізувати подорожнього й розкласти плоть. Шукачі пригод, яким вистачить сміливості вбити цих потвор, можуть набрати цілі фіали в'язкої рідини."},{t="Як виготовити Тотем Покари",b="У Даркширі ворожка Мадам Єва бачить зловісні знамення для подорожніх, що виходять у темний світ. Щоб створити оберіг відплати, їй потрібні п'ять фіалів цієї сирої отрути разом з іклами гулів і пальцями кістяків. Пройшовши крізь її чари, хижа, кусюча природа отрути обертається навиворіт і стає Тотемом Покари, що повертає лихо кожному, хто нападе на його власника."}},faq={{q="Звідки береться ця павуча отрута?",a="Її здобувають із різних хижих павуків, що чатують по всьому Сутінколіссю: павуків Отруйних Тенет, трупних відлюдників, зелених відлюдників, малят чорної вдови й велетенської матки Нараксіс.",al={"джерело павучої отрути","хто дропає павучу отруту","де взяти павучу отруту сутінколісся"}},{q="Кому потрібні Фіали Павучої Отрути?",a="Мадам Єва, віщунка з Даркширу, просить п'ять фіалів павучої отрути, а також пальці кістяків та ікла гулів, щоб виготовити магічний оберіг.",al={"кому потрібна павуча отрута","здати павучу отруту сутінколісся","отрута мадам єви"}},{q="Що виготовляють з отрути?",a="Мадам Єва змішує отруту з рештками нежиті, щоб зачарувати Тотем Покари — захисний талісман, що магічно завдає шкоди нападникам.",al={"що робить єва","матеріали тотема страждання","навіщо збирати павучу отруту"}},{q="Навіщо Мадам Єві небезпечна отрута для захисного оберегу?",a="Ремесло Єви часто спирається на симпатичну магію: смертоносні, мстиві властивості лісових хижаків і нежиті вона обертає на оберіг, що повертає насильство тому, хто напав.",al={"навіщо отрута для оберегу","лор інгредієнтів тотема єви"}}},fp="20,258,26.368.0,32.405.0,39.205.0,32.150.0,32.155.0,63.187.0"}
P.entries["item:vicious-night-web-spider-venom"] = {n="Отрута Лютого Павука Нічної Павутини",s="Отрута Лютого Павука Нічної Павутини — потужний природний токсин, добутий із павуків, що никають східною частиною Галявин Тірісфалю. Королівське Аптекарське Товариство цінує її за дивовижну здатність нести й зберігати давні штами хвороб, що робить її ключовим реагентом у розробці Нової Чуми Відступників.",h="Отрута Лютого Павука Нічної Павутини — потужний природний токсин, добутий із павуків, що никають східною...",kw={"отрута павука","нічна павутина","аптекар йогаан","брілл","нова чума","королівське аптекарське товариство"},ang={["class:Rogue"]="Розбійники, знайомі з природними нейротоксинами, оцінять, як Королівське Аптекарське Товариство обертає небезпечні дикі отрути на сконструйовану біологічну зброю.",["race:Undead"]="Для Відступників добування цієї отрути — прямий внесок у найвищий наказ Леді Сильвани: створити чуму, достатньо потужну, щоб звалити Артаса і його Погибель."},sec={{t="Збережена зараза",b="Згідно з дослідженням Аптекаря Йогаана у Бріллі, давні тексти описують спустошливу чуму, що колись скосила тисячі жертв на півночі Лордерону. Дивним чином збудник того забутого мору зумів пережити століття, оселившись в отруті місцевих павуків Нічної Павутини. Полюючи на лютий різновид, що чаїться в Долині Отруйного Павутиння на південь від Багряного Монастиря, аптекарі добувають цю збережену заразність як життєво важливий каталізатор для своїх алхімічних дослідів."},{t="Пальне для Нової Чуми",b="Відступники шукають зброю проти Погибелі й живих. Йогаан додає отруту як останню складову свого дослідного варива, сподіваючись, що збережена в ній зараза добре поєднається із сумішшю."}},faq={{q="Чим ця отрута відрізняється від звичайної павучої?",a="Учені фоліанти, які вивчає Королівське Аптекарське Товариство, свідчать, що збудник давньої чуми зберігся в отруйних залозах роду нічних тенетників, тож їхня отрута стала природним сховищем зарази.",al={"чому ця отрута","лор отрути нічної павутини","павуча отрута чуми"}},{q="Де шукати павуків із цією отрутою?",a="Люті нічні тенетники живуть здебільшого в Долині Отруйного Павутиння — затканому павутиною каньйоні на сході Галявин Тірісфалю, на південь від Багряного Монастиря.",al={"де шукати павуків","де павуки нічної павутини","павуки долини отруйної павутини"}},{q="Кому в Бріллі потрібна ця отрута?",a="Аптекар Йогаан, алхімік зі східного краю Брілла, просить кілька зразків, щоб завершити дослідження нового збудника зарази для Відступників.",al={"кому потрібна павуча отрута","аптекар йогаан отрута","хто використовує отруту"}},{q="Яку роль відіграє отрута в дослідженнях Відступників?",a="Йогаан просить отруту як останню складову свого досліду. Його старі тексти описують давню чуму, що збереглася в отруті Нічних Павуків-тенетників, і він хоче перевірити, чи поєднається ця зараза з його новим варивом.",al={"дослідження аптекарів отрута","новий компонент чуми","павуча отрута відступників"}}},fp="30,310,21.557.0,22.212.1,63.252.0,51.151.0,30.166.0,52.237.0"}
P.entries["item:vile-familiar-head"] = {n="Голова Підлого Фаміліара",s="Голова Підлого Фаміліара — моторошний трофей, зібраний із диких бісівських створінь, що мешкають біля Ковену Палаючого Клинка в Долині Випробувань. Молоді чорнокнижники Орди збирають їх під проводом Рузана як доказ бойової готовності, перш ніж навчитися прив'язувати перших демонічних прислужників. Голови слугують похмурою перевіркою дисципліни і показують, що учень розуміє смертоносність істот, яких збирається прикликати.",h="Голова Підлого Фаміліара — моторошний трофей, зібраний із диких бісівських створінь, що мешкають біля Ковену...",kw={"голова фаміліара","фамільяр","біс","чорнокнижник","рузан","ковен палаючого клинка","долина випробувань"},ang={["class:Warlock"]="Збирання цих голів — найперший крок чорнокнижника до влади над Безоднею, що дає право прикликати біса й прив'язати його до служби.",["faction:Horde"]="Навіть на тренувальних землях Дуротару чорнокнижники практикують своє мистецтво на узбіччі, пам'ятаючи, що Орда стежить за їхніми демонічними пошуками з невигаслою підозрою."},sec={{t="Моторошний урок демонології",b="У випаленому сонцем каньйоні Долини Випробувань наставник чорнокнижників Рузан вимагає від новачків, що хочуть опанувати мистецтво прикликання, шість таких голів. Мерзенні фамільяри, що вештаються біля Ковену Палаючого Клинка, — злі вогняні біси, чий дрібний зріст приховує небезпечну стихійну хитрість. Рузан вимагає, щоб майбутні прикликачі зустріли цих бісів у бою й відрубали їм голови на доказ того, що здатні підкорити демонічне життя й керувати ним, а не бути подоланими. Оскільки чорнокнижників в Орді Тралла ледве терплять, вишкіл потребує надзвичайної обережності: безрозсудні новачки, що гинуть від власних заклять, лише поглиблюють ганьбу й підозру до тих, хто практикує темні мистецтва."}},faq={{q="Для чого потрібні Голови Підлого Фаміліара?",a="Вони — доказ бойової вправності для новачків-чорнокнижників у Долині Випробувань. Наставник Рузан вимагає шість відрубаних голів, перш ніж навчить учня ритуалу виклику першого прислужника-беса.",al={"призначення голів підлого фаміліара","навіщо ці голови","предмет завдання рузана"}},{q="Звідки беруться мерзенні фамільяри?",a="Вони збираються біля входу й усередині печери на північному сході Долини Випробувань — схованки таємничого й лиховісного Ковену Палаючого Клинка.",al={"де мерзенні фамільяри","де шукати мерзенних фамільярів","печера ковену палаючого клинка"}},{q="Навіщо Рузан змушує молодих чорнокнижників збирати ці голови?",a="Рузан вважає, що ніхто не повинен викликати створіння, якого не здолає в бою. Біси підступні й жбурляються нестійким вогнем, тож перемога над ними віч-на-віч дає майбутньому чорнокнижникові зрозуміти, яку загрозу несуть демонічні сутності, якими він прагне керувати.",al={"навіщо збирати голови","мотив рузана","чому спершу вбивати фамільярів"}},{q="Як Орда ставиться до чорнокнижників, що збирають такі трофеї?",a="Сучасна Орда чорнокнижників радше терпить, ніж приймає. Давні зради, пов'язані з магією скверни, лишили по собі глибоку недовіру, тож наставники на кшталт Рузана мусять пильнувати, щоб учні були дисципліновані й не галасували про свої студії.",al={"чи приймають чорнокнижників","репутація чорнокнижників орди","недовіра до чорнокнижників"}}},fp="18,431,31.717.0,38.226.0,34.171.0,55.268.0,59.230.0"}
P.entries["item:vile-fin-scale"] = {n="Луска Темного Плавця",s="Луску Темного Плавця здобувають із племен мурлоків, що никають водними шляхами й північними берегами Галявин Тірісфалю. У Бріллі Королівське Аптекарське Товариство використовує ці витривалі біологічні зразки у своїх дослідженнях зі створення нищівної нової чуми.",h="Луску Темного Плавця здобувають із племен мурлоків, що никають водними шляхами й північними берегами Галявин...",kw={"луска темного плавця","мурлоки","королівське аптекарське товариство","аптекар йогаан","узбережжя","брілл"},ang={["faction:Horde"]="Очищення узбережжя від агресивних поселень мурлоків допомагає убезпечити околиці Галявин Тірісфалю для гінців і мандрівників Орди.",["race:Undead"]="Кожна зібрана луска темного плавця безпосередньо допомагає священному обов'язку Королівського Аптекарського Товариства — створити зброю, що забезпечить виживання Відступників проти живих і Погибелі."},sec={{t="Реагенти для аптекаря",b="Королівське Аптекарське Товариство невпинно працює над лютою пошестю, здатною винищити і живих, і Погибель. Прості отрути зварити легко, та щоб створити заразу, яка без зусиль ширитиметься серед населення, потрібні особливі алхімічні властивості. Аптекар Йогаан у Бріллі вивчає луску Темного Плавця саме для того, щоб зрозуміти, як її природна витривалість і слизові оболонки можуть допомогти стабілізувати й передавати його дослідну заразу."},{t="Загроза з узбережжя",b="Плем'я Темного Плавця заполонило північні береги й західні мілини Галявин Тірісфалю: воно загрожує мандрівникам і зазіхає на землі Відступників. Збирання їхньої луски слугує Андерсіті двом цілям: тримати здичавілих мурлоків у шорах і постачати лабораторії Йогаана свіжі органічні складники для випробувань біохімічної зброї."}},faq={{q="Навіщо Аптекареві Йогаану ця луска?",a="Аптекар Йогаан розробляє нову чуму для Королівського Аптекарського Товариства. Він виявив, що звичайним отрутам бракує заразності, тож використовує особливі біологічні властивості луски мурлоків, щоб його дослідне зілля ширилося як слід.",al={"що йогаан робить з лускою","навіщо луска темного плавця","луска чуми йогаана"}},{q="Де шукати мурлоків-Темноплавців?",a="Мурлоки-Темноплавці живуть на узбережжях Галявин Тірісфалю — здебільшого вздовж північного берега й у західних водах біля Озера Світлої Води та моря.",al={"де темноплавці","місце мурлоків тирисфалю","де взяти луску"}},{q="Чому задум Нової Чуми такий важливий для Відступників?",a="Відступники прагнуть зброї, здатної винищити їхніх запеклих ворогів — і бездумну Погибель, і живі раси, що вважають їх чудовиськами. Праця Йогаана в Бріллі — перші скромні досліди на шляху до цієї мети, що охоплює все королівство.",al={"чому нова чума","мета чуми відступників","що досліджує аптекар йогаан"}},{q="Які саме створіння мають цю луску?",a="Її здобувають із членів племені Темноплавців у Тірісфалі: молодших оракулів, муложивів і калюжострибців.",al={"хто дропає луску темного плавця","які мурлоки дропають луску"}}},fp="14,262,19.488.0,20.357.0,45.252.0,36.168.0,60.249.0,44.132.0"}
P.entries["item:voodoo-charm"] = {n="Вудуйський Талісман",s="Вудуйський Талісман — містичний оберіг, яким у курганах Тельдрассила розривають лиховісні чари. Переданий шукачам пригод духом Обена Рейджклова, він дає змогу назавжди звільнити його споганене, кероване мов лялька тіло, щоб його душа спочила у Смарагдовому Сні.",h="Вудуйський Талісман — містичний оберіг, яким у курганах Тельдрассила розривають лиховісні чари.",kw={"вудуйський талісман","обен рейджклов","друїд пазура","вузлошкіри","фурболги","смарагдовий сон","кургани"},ang={["class:Druid"]="Для молодих друїдів, що навчаються на Тельдрассилі, вжити оберіг, щоб із милосердя вбити й звільнити брата, Друїда Пазура, — підкреслення трагічної вразливості того, хто лишає тілесну оболонку, мандруючи Смарагдовим Сном.",["race:NightElf"]="Існування цього оберега показує, як глибоко виродилися фурболги Вузлошкірів, обернувши священні курганні лігва калдореїв на місця потворного духовного ув'язнення."},sec={{t="Розрив темних пут",b="У глибинах курганних лігв Вузлошкірів на Тельдрассилі фурболги вдалися до огидної магії, щоб керувати сплячими тілами священних захисників калдореїв. Друїд Обен Рейджклов виявив, що його дух відділено від плоті, а тілесна оболонка поневолена чаклунством Вузлошкірів. Дослідивши цей зачарований оберіг, Обен розуміє: темну прив'язь, що тримає його живу посудину, не розвіяти простими традиційними молитвами. Натомість оберіг стає знаряддям остаточного звільнення: щойно його бездушне тіло буде повалене, магію оберега треба спрямувати на полеглу оболонку, щоб цілком вигнати владу фурболгів і відпустити його мандрівний дух у Смарагдовий Сон назавжди."}},faq={{q="Для чого потрібен Вудуйський Талісман?",a="Талісман розриває магічну владу фурболгів-Вузлошкірів над Обеном Рейджкловом. Коли бездушне, зачароване тіло Обена переможено, талісман треба використати просто на його рештках, щоб розірвати темні чари й звільнити його душу.",al={"що робить вудуйський талісман","використання вудуйського талісмана","як використати вудуйський талісман"}},{q="Хто дає вам Вудуйський Талісман?",a="Талісман дає дух Обена Рейджклова в завданні «Друїд Пазура». Оглянувши талісман, він пояснює, як ним скористатися, щоб звільнити його від чаклунства племені Вузлошкірів.",al={"де взяти вудуйський талісман","хто дає талісман","талісман обена"}},{q="Чому в краю нічних ельфів він зветься вудуйським талісманом?",a="Відтоді як у Велике Древо почала просочуватися скверна, фурболги-Вузлошкіри з Тельдрассила піддалися зіпсуттю й дивній племінній магії. Талісман уособлює чуже чи спотворене чаклунство, яким плем'я фурболгів заманює в пастку тіла сплячих друїдів і керує ними, мов ляльками.",al={"чому вуду в тельдрассилі","чи це тролячий вуду"}},{q="Що стається, коли талісман використано?",a="Щойно талісман розриває чари над його тілом, Обен Рейджклов нарешті звільняється з лабет Вузлошкірів. Його тілесна оболонка спочиває, а дух покидає Тельдрассил, щоб навіки мирно жити в Смарагдовому Сні.",al={"що буде з обеном","чи обен виживе"}}},fp="12,282,24.705.1,40.248.0,31.200.0,51.283.0,37.241.1"}
P.entries["item:wailing-essence"] = {n="Скорботна Сутність",s="Скорботна Сутність — дивна концентрована речовина, яку знаходять в ектоплазмах, що блукають глибоко в Печерах Стогонів. Її підозрюють у тому, що вона живить химерні мутації, які поширюються рослинним і тваринним світом Пусток, тож нею зацікавилися спритні алхіміки, охочі розлити її потужні властивості по пляшках.",h="Скорботна Сутність — дивна концентрована речовина, яку знаходять в ектоплазмах, що блукають глибоко в Печерах...",kw={"скорботна сутність","печери стогонів","мебок міззірікс","ектоплазми","раджет","розумні напої"},ang={["class:Druid"]="Існування цієї сутності прямо вказує на спотворювальний вплив глибоко в Печерах Стогонів і нагадує, як нагально треба очистити скверну Сну."},sec={{t="Вибухове вариво",b="Підземні печери під центральними Пустками налилися неприродною силою, що спотворює звірів і породжує драглисті ектоплазми. Ці слизькі істоти зосереджують у собі в'язку речовину, відому як Скорботна Сутність. Поки місцеві друїди з дедалі більшим жахом спостерігають за цими водами, гоблінські підприємці бачать лише сиру комерційну нагоду. У портовому містечку Раджеті дивакуватий алхімік Мебок Міззірікс вірить, що ця сутність — той самий бракуючий активний складник для прибуткової лінійки «розумних напоїв», що мають підносити розум покупців. Йому геть байдуже, яку кошмарну скверну вона насправді може нести."}},faq={{q="Звідки береться Скорботна Сутність?",a="Її збирають із ектоплазмових слизів у Печерах Стогонів: ненажерливих, мінливих і жахітних ектоплазм.",al={"дроп скорботної сутності","де взяти скорботну сутність","що дропає скорботну сутність"}},{q="Кому потрібна ця сутність?",a="Мебок Міззірікс, гоблін-експериментатор із Раджета, шукає сутність, щоб зварити нову формулу своїх «розумних напоїв», які нібито підсилюють інтелект.",al={"кому потрібна скорботна сутність","хто купує скорботну сутність","здати скорботну сутність"}},{q="Що, на думку дослідників, ця сутність робить із Пустками?",a="Мебок підозрює, що саме сутність — першопричина того, що звірі Пусток швидко мутують, а рослини неприродно буяють по всьому краю.",al={"що робить скорботна сутність","чи небезпечна скорботна сутність","лор скорботної сутності"}},{q="Чи справді безпечно пити Скорботну Сутність?",a="Якщо зважити, що її добувають з осквернених, уражених жахіттям ектоплазм глибоко в проклятій печері, то додавати її до напою на продаж — щонайменше безрозсудно, хоча для гоблінських підприємців цілком звично.",al={"чи можна пити скорботну сутність","чи розумний напій безпечний"}}},fp="15,312,21.630.0,37.149.0,23.139.0,54.156.0,42.206.0"}
P.entries["item:warsong-axe-shipment"] = {n="Постачання Сокир Бойової Пісні",s="Постачання сокир Бойової Пісні — важка скриня новокованих сокир, що чекає на пристанях Буті Бей у Долині Стренглторну. Замовлена Дозорцями Пісні Війни, щоб підтримувати лісозаготівлі в Ашенвалі, вона — важлива ланка заморського ланцюга постачання Орди.",h="Постачання сокир Бойової Пісні — важка скриня новокованих сокир, що чекає на пристанях Буті Бей у Долині...",kw={"постачання сокир","бойова пісня","буті бей","лозґіл","лісозаготівля","застава розщепленого дерева"},ang={["faction:Horde"]="Здобути цю скриню вкрай важливо, щоб Лісозаготівельний Табір Бойової Пісні мав знаряддя й працював, попри невпинний тиск ворожих сил в Ашенвалі.",["race:Orc"]="Для клану Бойової Пісні гострі сокири — це більше деревини для підвалин Оргріммара й Дуротару, що розбудовуються."},sec={{t="Довга мандрівка через моря",b="Щоб Лісозаготівельний Табір Бойової Пісні працював, потрібен безперервний потік міцних знарядь, які не завжди вдається викувати на передовій. Аби лісоруби не лишалися без інструменту, замовлення посилають через Велике Море до нейтрального гоблінського порту Буті Бей. Ця скриня, що стоїть біля Начальника Пристані Лозґіла, повна нагострених сокир, які мають відплисти назад до Застави Розщепленого Дерева, — і вона добре показує, як важко Орді забезпечувати свої далекі прикордонні табори."}},faq={{q="Де знаходиться Постачання Сокир Бойової Пісні?",a="Ящик стоїть просто на причалах гоблінського порту Буті Бей на південному краю Долини Стренглторну.",al={"місце сокир","де постачання сокир","ящик сокир у буті бей"}},{q="Чому вантаж для Ашенвалю опинився аж у Буті Бей?",a="Нападники Чорної Води й картель Стімвідл займаються торговими перевезеннями через Велике Море. Буті Бей — великий торговий вузол, що сполучає далекі краї, тож саме тут перевантажують інструменти й знаряддя, які Орда замовляє гуртом.",al={"чому буті бей","чому в стренглторні","сокири бойової пісні в буті бей"}},{q="Кому потрібні ці сокири?",a="Вони потрібні Локові Окарру, вершникові із Застави Розщепленого Дерева в Ашенвалі, щоб поповнити запаси Лісозаготівельного Табору Бойової Пісні, які дедалі меншають.",al={"кому потрібні сокири","для кого постачання","сокири лока окарра"}},{q="Хто пильнує доставку в Буті Бей?",a="Начальник Пристані Лозґіл наглядає за морськими вантажами на гамірних причалах Буті Бей, де вантаж чекає на відправлення до Калімдору.",al={"хто має постачання","управитель пристані лозґіл","управитель пристані буті бей"}}},fp="20,271,29.490.0,42.120.0,62.239.0,21.145.0,39.140.0"}
P.entries["item:warsong-oil"] = {n="Олія Бойової Пісні",s="Олія Бойової Пісні — важливе промислове мастило для машин Лісозаготівельного Табору Бойової Пісні в Ашенвалі. Місцеві сатири перехопили важливий вантаж у дорозі й забрали олію до своїх осквернених лісових святилищ для мерзенних обрядів.",h="Олія Бойової Пісні — важливе промислове мастило для машин Лісозаготівельного Табору Бойової Пісні в Ашенвалі.",kw={"олія бойової пісні","сатири","лісозаготівля","подрібнювачі","ашенваль","застава розщепленого дерева"},ang={["faction:Horde"]="Усі опори Орди в Дуротарі та Пустках тримаються на деревині Ашенвалю; втратити машинну олію через сатирів-демонопоклонників — значить поставити під загрозу будівництво її молодих міст.",["profession:Engineering"]="Інженери добре знають: без постійного змащування тендітні шарніри гоблінських подрібнювачів і циркулярні пилки згоряють за кілька годин рубання лісу."},sec={{t="Викрадене пальне для машин",b="Лісозаготівлі клану Бойової Пісні в Ашенвалі тримаються на важких машинах, гоблінських подрібнювачах і величезних лісопилках. Щоб це промислове обладнання працювало, потрібне постійне постачання особливої олії. Без неї заготівля деревини може раптом зупинитися — а з нею й потік колод, яких так бракує для будівництва Оргріммара й укріплення поселень Орди в Дуротарі та Пустках."},{t="Обряди сатирів",b="Нещодавній вантаж Олії Бойової Пісні так і не дійшов до Застави Розщепленого Дерева й лісозаготівельних таборів: на нього напали сатири, що кишать у лісі. Демонічні посіпаки не викинули очищену рідину, а віднесли бідони до своїх зіпсованих осередків — зокрема Нічного Потоку, Сатирнаару та Ксавіана, — щоб використати горюче мастило у своїх темних, огидних обрядах."}},faq={{q="Для чого потрібна Олія Бойової Пісні?",a="Це промислове мастило, щоб важкі подрібнювачі, пили й лісорубні машини Лісозаготівельного Табору Бойової Пісні працювали безперебійно.",al={"призначення олії бойової пісні","навіщо олія","для чого це"}},{q="Звідки в сатирів ця олія?",a="На дорогах Ашенвалю влаштували засідку на обоз із припасами, що прямував до Застави Розщепленого Дерева. Сатири забрали олію й пустили її на свої мерзенні темні ритуали в зруйнованих поселеннях.",al={"хто вкрав олію","чому сатири мають олію","куди зникла олія"}},{q="Де знайти Олію Бойової Пісні?",a="Посудини з олією розкидані по місцях, які контролюють сатири в Ашенвалі, — передусім у Нічному Потоці, Сатирнаарі й Ксавіані.",al={"місце олії бойової пісні","де знайти олію бойової пісні","місця олії"}},{q="Хто просить повернути олію?",a="Лок Окарр із Застави Розщепленого Дерева потребує олію, а також пилки, мотузки й сокири, щоб поповнити припаси лісозаготівлі Бойової Пісні, яка ледве тримається.",al={"хто хоче олію","видавець завдання на олію бойової пісні"}}},fp="11,254,21.418.0,20.371.0,29.135.0,31.192.0,31.137.0,28.139.0"}
P.entries["item:warsong-outrider-update"] = {n="Оновлене Донесення Вершника Бойової Пісні",s="Оновлене донесення вершника Бойової Пісні — військовий розвідувальний звіт, який написав вершник Бойової Пісні, що несе службу на східному прикордонні Ашенвалю. Його довіряють гінцям Орди, і він містить спостереження з передової, життєво важливі для того, щоб убезпечити шлях до Азшари й зміцнити оркські позиції проти опору нічних ельфів.",h="Оновлене донесення вершника Бойової Пісні — військовий розвідувальний звіт, який написав вершник Бойової...",kw={"донесення вершника","бойова пісня","ашенваль","кадрак","застава розщепленого дерева","азшара"},ang={["faction:Horde"]="Кожна дрібка розвідданих із передової захищає життєво важливі шляхи постачання між Пустками й Ашенвалем і прямо забезпечує деревину, потрібну для розбудови Оргріммара.",["race:Orc"]="Клан Бойової Пісні покладається на пильних розвідників і прудких гінців, щоб відстояти честь і землі перед лютими Вартовими нічних ельфів, які оскаржують його права на ліс."},sec={{t="Розвідка з рубежу",b="Уздовж східної дороги повз Заставу Розщепленого Дерева до прадавніх руїн Азшари тягнеться кордон Ашенвалю — неспокійний рубіж. Донесення вершника Бойової Пісні збирає докупи тактичні спостереження, пересування патрулів і оцінки ресурсів від оркських передових вершників, що об'їжджають цей периметр. Ці польові нотатки відсилають Кадракові до північної сторожової вежі на кордоні Пусток, і вони дають командирам Орди чітку картину скупчень ворожих військ і загроз, що чигають під лісовим наметом."}},faq={{q="Для чого це донесення?",a="Це звіт про дії нічних ельфів і становище на прикордонні вздовж східної дороги Ашенвалю до Азшари. Кадрак покладається на ці відомості, щоб розставляти війська Орди й зміцнювати оборонні рубежі на північному кордоні Пусток.",al={"призначення донесення вершника","навіщо донесення вершника","що це за звіт"}},{q="Хто несе й доставляє це донесення?",a="Передовий Вершник Бойової Пісні, що патрулює шлях між Заставою Розщепленого Дерева й кордоном Азшари, передає документ в обмін на нові стратегічні накази від Кадрака.",al={"хто пише донесення вершника","звідки донесення вершника"}},{q="Куди треба доставити цей звіт?",a="Донесення треба віднести просто Кадракові, що командує північною дозорною вежею між Пустками й південним входом до Ашенвалю.",al={"куди нести донесення вершника","хто хоче донесення вершника"}},{q="Чому Бойова Пісня так держиться за Ашенваль?",a="Клан Бойової Пісні масово вирубує прадавні ліси Ашенвалю, щоб забезпечити Орду деревиною й будівельними матеріалами для Оргріммара. Це хижацьке добування ресурсів втягує клан у безупинну боротьбу з нічними ельфами-захисниками й Вартовими Срібнокрилих.",al={"чому орки в ашенвалі","інтерес бойової пісні до ашенвалю"}}},fp="23,337,21.528.0,35.266.0,39.169.0,34.144.0,45.256.0"}
P.entries["item:warsong-runner-update"] = {n="Оновлене Донесення Гінця Бойової Пісні",s="Оновлене донесення гінця Бойової Пісні — військове повідомлення з даними про становище на Заставі Зорам'гар на західному узбережжі Ашенвалю. Його доставляють командирові Орди Кадракові на кордоні Пусток, і воно допомагає узгоджувати кампанію клану Бойової Пісні проти нічних ельфів.",h="Оновлене донесення гінця Бойової Пісні — військове повідомлення з даними про становище на Заставі Зорам'гар...",kw={"донесення гінця","бойова пісня","застава зорам'гар","ашенваль","кадрак","вал мор'шан"},ang={["faction:Horde"]="Донесення показує, як важко утримувати далекі застави на ворожій землі нічних ельфів, де зв'язок між Ашенвалем і Пустками тримається лише на гінцях.",["race:Orc"]="Розвідники й гінці Бойової Пісні ризикують життям у густих лісах, щоб доставляти тактичні дані просто Кадракові й посилювати права клану на ці землі."},sec={{t="Очі на західному фронті",b="Гонець Бойової Пісні на Заставі Зорам'гар, що стоїть на краю Зорамського Берега, стежить за прибережними водами й навколишніми загрозами на заході Ашенвалю. Це донесення містить важливі розвідувальні дані від передових розвідників застави — про те, що діється в окрузі, і про захист шляхів постачання. Доставлене до Валу Мор'шан на кордоні Пусток, воно дає проводові Орди ясність, потрібну, щоб зміцнити позиції й спланувати подальші кроки глибоко в прадавніх ельфійських лісах."}},faq={{q="Що таке Оновлене Донесення Гінця Бойової Пісні?",a="Це письмове військове донесення, яке склав гонець Бойової Пісні із Застави Зорам'гар на заході Ашенвалю: у ньому — спостереження з передової для командування Орди на кордоні Пусток.",al={"донесення гінця","що таке донесення гінця бойової пісні","звіт бойової пісні зорам"}},{q="Звідки береться це донесення?",a="Його отримують від гінця Бойової Пісні із Застави Зорам'гар, що на далекому західному узбережжі Ашенвалю, біля Зорамського Узмор'я.",al={"місце гінця","де гінець бойової пісні","хто дає донесення гінця"}},{q="Хто отримує це донесення?",a="Донесення несуть Кадракові — командирові Бойової Пісні, що стоїть на дозорній вежі вздовж північного кордону Пусток і захищає Вал Мор'шан.",al={"кому віддати це","донесення кадрака","доставити донесення гінця"}},{q="Навіщо Кадракові це донесення?",a="Кадрак керує військовими пересуваннями клану Бойової Пісні в Ашенвалі. Донесення із застав на кшталт Зорам'гару повідомляють його про опір ворога, наближення з моря й про те, хто тримає місцеві землі.",al={"навіщо донесення гінця","призначення звітів бойової пісні"}}},fp="21,291,25.519.0,34.196.0,35.139.0,25.148.0,35.204.0"}
P.entries["item:warsong-saw-blades"] = {n="Пиляльні Леза Бойової Пісні",s="Пиляльні леза Бойової Пісні — спеціальні промислові різальні знаряддя, замовлені для суцільних вирубок Орди в Ашенвалі. Їх доставляють гоблінськими торговими каналами, і без них не обійтися машинам Лісозаготівельного Табору Бойової Пісні.",h="Пиляльні леза Бойової Пісні — спеціальні промислові різальні знаряддя, замовлені для суцільних вирубок Орди в...",kw={"пиляльні леза","бойова пісня","лісопилка","гобліни","лок окарр","ашенваль"},ang={["faction:Horde"]="Усе просування Орди в центральний Калімдор залежить від деревини Ашенвалю, тож збереження й обслуговування лісопильного обладнання Бойової Пісні — стратегічне першочергове завдання.",["race:NightElf"]="Кожна скриня викуваних гоблінами пиляльних лез означає подальше осквернення прадавнього лісового покрову Ашенвалю й нищення священних лісових духів."},sec={{t="Промислове лісорубство",b="Лісозаготівлі клану Бойової Пісні в Ашенвалі тримаються на потужних машинах, які постачають і обслуговують гобліни-інженери. Самими сокирами величезного апетиту Орди на деревину Калімдору не вгамувати — потрібні парові двигуни й циркулярні пилки, що безупинно вгризаються в сирі стовбури. Прадавня тверда деревина Ашенвалю швидко тупить і ламає звичайні леза, тож без постійного постачання змінних пиляльних лез лісопилки Лісозаготівельного Табору Бойової Пісні просто зупинилися б."},{t="Як уберегти вантаж",b="Діставати механічні деталі глибоко на спірній території — постійний клопіт. Інші лісорубські припаси раз у раз перехоплюють ворожі фурболги чи сатири, а пиляльні леза доставляють через гоблінських посередників, як-от гоблінку Піксель на Заставі Розщепленого Дерева. Збираючи ці леза разом із линвами, олією й сокирами, майстер лісозаготівель Лок Окарр підтримує роботу табору, попри безупинні диверсії споконвічних захисників лісу."}},faq={{q="Для чого потрібні Пиляльні Леза Бойової Пісні?",a="Це змінні диски циркулярних пил для важких механічних подрібнювачів і лісопилок Лісозаготівельного Табору Бойової Пісні на південному сході Ашенвалю.",al={"призначення пиляльних лез","використання пиляльних лез","для чого вони"}},{q="Хто постачає ці леза Орді?",a="Лезами займаються гоблінські торговці й постачальники. Піксель, гоблінка із Застави Розщепленого Дерева, пильнує прибуття цього механічного вантажу для вершників Бойової Пісні.",al={"хто зробив леза","звідки леза","постачальник пиляльних лез"}},{q="Навіщо Орді стільки пиляльних лез?",a="Густі прадавні дерева Ашенвалю швидко туплять леза, а Орді потрібна сила-силенна деревини, щоб будувати поселення на посушливих рівнинах Дуротару й Пусток. Безупинна вирубка зношує машини швидше, ніж місцеві ковалі встигають їх перекувати.",al={"навіщо так багато лез","потреба лісозаготівлі бойової пісні","навіщо потрібні пили"}},{q="Хто збирає припаси для лісозаготівлі?",a="Лок Окарр, орк, що керує доставками із Застави Розщепленого Дерева, організовує повернення пиляльних лез разом з олією, мотузками й сокирами, щоб доправити їх до лісозаготівельного табору.",al={"хто хоче леза","хто бере пиляльні леза","завдання лока окарра"}}},fp="18,253,19.486.0,21.436.0,41.166.0,43.184.0,43.272.0,39.174.0"}
P.entries["item:warsong-scout-update"] = {n="Оновлене Донесення Розвідника Бойової Пісні",s="Оновлене донесення розвідника Бойової Пісні — письмовий звіт із бойовою розвідкою із Застави Розщепленого Дерева в Ашенвалі. Його зібрав передовий розвідник клану Бойової Пісні, і він дає командирові Кадракові важливі відомості, потрібні, щоб утримати позиції Орди проти опору нічних ельфів.",h="Оновлене донесення розвідника Бойової Пісні — письмовий звіт із бойовою розвідкою із Застави Розщепленого...",kw={"донесення розвідника","бойова пісня","застава розщепленого дерева","ашенваль","кадрак","нічні ельфи"},ang={["faction:Horde"]="Донесення Бойової Пісні — кровоносні судини просування Орди в Ашенваль: вони підтримують зв'язок передових таборів із базами постачання в Пустках.",["race:Orc"]="Клан Бойової Пісні несе основний тягар лісозаготівельної кампанії в Ашенвалі й покладається на прудких розвідників, щоб утримати важко здобуті лісові застави."},sec={{t="Очі в прадавньому лісі",b="Поки Орда намагається здобути деревину й прокласти шляхи постачання через Ашенваль, розвідники клану Бойової Пісні ходять дозором глибоко в тилу ворога. Донесення розвідника Бойової Пісні збирає місцеві спостереження з укріпленого табору на Заставі Розщепленого Дерева — про Вартових нічних ельфів і пересування на спірних землях. Передане гінцям, що розносять буденні накази, воно дає Кадракові на кордоні Пусток і Ашенвалю змогу оцінити готовність військ і налагодити постачання в спірних лісах."}},faq={{q="Що таке Оновлене Донесення Розвідника Бойової Пісні?",a="Це польовий звіт, який склав Розвідник Бойової Пісні із Застави Розщепленого Дерева в центрі Ашенвалю: у ньому підсумовано місцеві спостереження для командирів на кордоні.",al={"донесення розвідника","звіт розвідника","депеша розвідника бойової пісні"}},{q="Кому потрібне це донесення?",a="Воно потрібне Кадракові, офіцерові Орди на дозорній вежі, що стереже кордон між північчю Пусток і Ашенвалем, щоб планувати військові маневри Орди.",al={"хто це хоче","звіт кадрака","хто отримує донесення"}},{q="Де знайти Розвідника Бойової Пісні?",a="Розвідник стоїть у Заставі Розщепленого Дерева — головній твердині Орди на основній дорозі через центр Ашенвалю.",al={"де розвідник","місце розвідника","знайти розвідника бойової пісні"}},{q="Чому ці донесення такі важливі для Орди?",a="Нічні ельфи запекло боронять Ашенваль. Письмові донесення розвідників попереджають командування Орди про ворожі засідки й пересування військ, тож шляхи постачання й лісозаготівельні табори лишаються в безпеці.",al={"чому це важливо","логістика бойової пісні","розвідка ашенвалю"}}},fp="20,294,26.490.0,33.162.0,25.169.0,35.140.0,51.192.0"}
P.entries["item:water-of-the-seers"] = {n="Вода Провидців",s="Вода Провидців — священний напій, який дають молодим тауренам, що проходять племінні випробування в Селі Бладгуф. Випита біля племінного вогню свята вода відкриває розум світові духів і прикликає примарне Видіння Рівнин, що веде прочанина його духовною дорогою.",h="Вода Провидців — священний напій, який дають молодим тауренам, що проходять племінні випробування в Селі...",kw={"вода провидців","обряд видіння","видіння рівнин","віщун вайзраннер","село бладгуф","таурени"},ang={["class:Shaman"]="Дія цього напою дає ранній досвід спілкування зі світом духів і показує, як ритуальні речовини можуть стоншити завісу між тілесним світом і світом предків.",["race:Tauren"]="Вода Провидців — засадниче священне вариво в науці молодих шу'гало, що поєднує стародавні шаманські звичаї з племінним переходом у доросле життя."},sec={{t="Посудина для духу",b="Приготована племінними містиками, Вода Провидців — неодмінна частина стародавнього Обряду Видіння. Щоб прорвати завісу між тілесною дійсністю й настановами предків, прохач має випити святу воду перед центральним племінним вогнем у Селі Бладгуф. Могутній напій дарує духовний зір: з жарин постає примарний провідник, відомий як Видіння Рівнин, і веде до Віщуна Вайзраннера."}},faq={{q="Що стається, коли випити Воду Провидців?",a="Священна вода, випита біля племінного вогнища в селі, відкриває ваші духовні чуття. За мить із полум'я виходить дух предків у подобі примарного вовка — Видіння Рівнин, — щоб вести вас Малгором.",al={"що робить вода провидців","пити воду провидців","видіння рівнин"}},{q="Де треба випити воду?",a="Трунок треба випити просто перед великим племінним вогнищем у Селі Бладгуф, трохи на північ від місцевих старійшин-шаманів.",al={"де пити воду провидців","місце води провидців","місце племінного вогню"}},{q="До кого веде видіння?",a="Примарне Видіння Рівнин веде паломника на північний захід, у передгір'я Малгору, до печери, де на нього чекає Віщун Вайзраннер, щоб розтлумачити його подорож.",al={"куди веде вовк","куди веде видіння","хто провидець"}}},fp="18,280,23.448.0,51.242.0,35.134.0,33.162.0"}
P.entries["item:water-pitcher"] = {n="Глек для Води",s="Простий посуд, у якому носять свіжу джерельну воду з місцевої криниці на Плато Червоної Хмари. Прамати Гоквінд велить молодим тауренам віднести його до Табору Нарачі, щоб прищепити їм цінності смирення, служіння й поваги до старійшин племені.",h="Простий посуд, у якому носять свіжу джерельну воду з місцевої криниці на Плато Червоної Хмари.",kw={"глек для води","прамати гоквінд","вождь гоквінд","криниця","смирення","табір нарачі"},ang={["race:Tauren"]="Для молодих тауренів, що входять у зрілість на Плато Червоної Хмари, нести глек — ранній урок: шана до старійшин і допомога громаді — справжні підвалини сили."},sec={{t="Урок смирення",b="Хоч глек для води скромний на вигляд, для молоді він — важливе знаряддя науки, і Табір Нарачі користується ним не одне покоління. Глек стоїть біля водяної криниці на рівнинах на південний схід від табору й уособлює щоденну працю, потрібну, щоб підтримувати громаду. Просячи новачка наповнити важку посудину й віднести її Вождю Гоквінду, Прамати Гоквінд випробовує його вдачу. Ця робота показує, що жоден обов'язок не нижчий за гідність захисника племені, і нагадує молодим сміливцям: дбати про щоденні потреби родичів так само важливо, як тримати зброю на полюванні."}},faq={{q="Для чого потрібен Глек для Води?",a="У ньому носять свіжу воду з криниці до Табору Нарачі. Тягати глек через рівнину — традиційний обов'язок, що перевіряє, чи готовий молодий шукач пригод до буденної праці на благо племені.",al={"призначення глека","навіщо носити глек","скромне завдання глек"}},{q="Де знайти глек для води?",a="Глек стоїть біля самої криниці на південний схід від Табору Нарачі на Плато Червоної Хмари, неподалік від місця, де порається Прамати Гоквінд.",al={"місце глека","де глек для води","знайти глек малгор"}},{q="Хто просить принести глек?",a="Прамати Гоквінд просить молодих мандрівників принести його. Старим ногам важко долати такий шлях, тож вона доручає цю справу завзятій молоді, щоб перевірити її снагу й смирення.",al={"хто дає завдання на глек","велика матір глек"}},{q="Хто отримує наповнений глек?",a="Його несуть просто Вождеві Гоквінду в Табір Нарачі, і той бачить у цьому вчинку доказ, що носій має серце й відданість, потрібні, щоб служити племені.",al={"хто отримує глек","доставити глек","куди нести глек"}}},fp="13,240,20.548.0,35.211.0,36.150.0,40.172.0,49.162.0"}
P.entries["item:webwood-egg"] = {n="Яйце Павука Вебвуда",s="Яйце Павука Вебвуда — невилуплений зразок, зібраний із гнізд у Печері Тіньової Нитки в Тінедолі. Природознавці, що вивчають скверну на Тельдрассилі, шукають ці життєздатні яйця, щоб досліджувати щойно вилуплених павуків у безпечних умовах.",h="Яйце Павука Вебвуда — невилуплений зразок, зібраний із гнізд у Печері Тіньової Нитки в Тінедолі.",kw={"яйце павука вебвуда","вебвуд","павуки","печера тіньової нитки","ґілшалан віндвокер","тінедол","дарнасус"},ang={["class:Druid"]="Розуміння того, як розмножуються й поводяться споганені павуки Вебвуда, дає друїдам важливі підказки для зцілення порушеної природної рівноваги Тельдрассила.",["race:NightElf"]="Для молодих калдореїв, що захищають священне віття Тельдрассила, здобуття цих яєць допомагає вченим дослідити неприродну скверну, що розповзається корінною звіриною Світового Дерева."},sec={{t="Безпечний зразок",b="Приборкати чи вгамувати дорослого отруйного павука Вебвуда — небезпечна справа, непосильна для самотніх дослідників. Замість боротися зі зрілими хижаками, вчені на кшталт Ґілшалана Віндвокера покладаються на невилуплені яйця, зібрані просто з кладок у темних закутках Печери Тіньової Нитки. Здобуте невилуплене яйце дає змогу природознавцям безпечно перевезти створіння й утримати павученят, щойно ті вилупляться, — живі зразки для вивчення без зустрічі зі смертоносними іклами дорослих звірів."},{t="Призначено для Дарнасуса",b="Неприродна лють і скверна, що вразили корінну звірину Тельдрассила, стривожили вчених по всьому вітті. Зібрані яйця й здобуту отруту, щойно їх доставлять до Алдрассила, мають відправити вниз, до столиці — Дарнасуса. Дослідники сподіваються, що вирощування й вивчення павуків у контрольованих умовах дасть цінне розуміння темної недуги, що повзе віттям Світового Дерева."}},faq={{q="Де знайти Яйця Павука Вебвуда?",a="Яйця Павука Вебвуда лежать кладками глибоко у вологих тунелях Печери Тіньової Нитки на північному заході Тінедолу.",al={"місце яйця вебвуда","де яйце вебвуда","знайти яйце вебвуда"}},{q="Кому потрібне Яйце Павука Вебвуда?",a="Дослідник Ґілшалан Віндвокер біля Алдрассила просить яйце, щоб продовжити наукове вивчення агресивних павуків, що непокоять Тінедол.",al={"кому потрібне яйце вебвуда","здати яйце","яйце гілшалана"}},{q="Чому треба брати яйце, а не ловити павука?",a="Дорослий павук Вебвуда надто великий і небезпечний, щоб його легко спіймати й утримати. Невилуплене яйце — живий зразок, який можна безпечно перенести й помістити в надійну загорожу, перш ніж з нього щось вилупиться.",al={"чому яйце","чому не піймати живого павука"}},{q="Що стається з яйцем, коли його зібрано?",a="Ґілшалан влаштовує, щоб яйце й видобуту павучу отруту доставили до Дарнасуса, де вчені зможуть ґрунтовно вивчити цих створінь подалі від небезпек дикого лісу.",al={"куди йде яйце","призначення яйця"}}},fp="11,258,20.523.0,22.438.0,29.144.0,26.150.0,49.225.0,46.195.0"}
P.entries["item:webwood-ichor"] = {n="Іхор Павука Вебвуда",s="Іхор Павука Вебвуда — рідина, яку добувають із павуків Вебвуда, що нишпорять Тельдрассилом. Діранії Сілвершайн він потрібен разом із Гіацинтовими Грибами й Лілеями Місячна Пелюстка, щоб зварити протиотруту для отруєного Іверрона.",h="Іхор Павука Вебвуда — рідина, яку добувають із павуків Вебвуда, що нишпорять Тельдрассилом.",kw={"іхор","павуки вебвуда","тельдрассил","тінедол","іверрон","протиотрута"},ang={["race:NightElf"]="Для молодих нічних ельфів, що захищають Алдрассил, збирання іхору Вебвуда — урок суворої рівноваги природи: найсмертоносніші отрути Тельдрассила часто ховають у собі власні ліки."},sec={{t="Отруйні ліки",b="Павуки Вебвуда, що облюбували Тінедол, носять отруту, досить небезпечну, щоб Іверрон тяжко занедужав. Діранія Сілвершайн просить принести іхор цих павуків, а також Гіацинтові Гриби й Лілеї Місячна Пелюстка, щоб приготувати протиотруту."}},faq={{q="Для чого потрібен Іхор Павука Вебвуда?",a="Діранії Сілвершайн у Тінедолі потрібні Іхор Павука Вебвуда, Гіацинтові Гриби й Лілеї Місячна Пелюстка, щоб приготувати протиотруту для отруєного нічного ельфа Іверрона.",al={"використання іхору вебвуда","що робить іхор вебвуда","навіщо іхор"}},{q="Звідки береться Іхор Павука Вебвуда?",a="Його збирають із тіл павуків Вебвуда, що живуть на північному заході Тінедолу, особливо довкола й усередині Печери Тіньової Нитки.",al={"де взяти іхор вебвуда","як отримати іхор вебвуда","дроп іхору вебвуда"}},{q="Навіщо лікувати павучий укус павучою рідиною?",a="Діранія просить Іхор Павука Вебвуда як одну зі складових протиотрути для Іверрона. Як саме іхор діє в суміші, вона не пояснює.",al={"лікування павучої отрути","чому отрута для протиотрути"}}},fp="13,203,12.232.0,31.153.0,35.153.0,43.137.0"}
P.entries["item:webwood-spider-silk"] = {n="Павутинний Шовк Вебвуда",s="Павутинний Шовк Вебвуда — тонка липка нитка, здобута з вебвудських чигачів, що нишпорять лісами Тельдрассила. Павутинний шовк має багато ремісничих застосувань, та саме ці клапті шукають підозрілі постаті у вітті Світового Дерева.",h="Павутинний Шовк Вебвуда — тонка липка нитка, здобута з вебвудських чигачів, що нишпорять лісами Тельдрассила.",kw={"павутинний шовк вебвуда","вебвуд","павуки","шовк","зенн фаулгуф","сатир","доланаар"},ang={["profession:Tailoring"]="Хоч прядильники часто шукають павучі нитки, саме ці клапті вплутані в темні оборудки сатира, а не у звичне ткацьке ремесло.",["race:NightElf"]="Молодих нічних ельфів, що покидають Тінедол, застерігають зважати на створінь, на яких вони полюють, — надто коли їх підбурює самотній сатир, що чигає біля самого їхнього серця."},sec={{t="Сумнівний складник",b="Спрядений величезними вебвудськими чигачами, що гніздяться довкола Доланаара, Павутинний Шовк Вебвуда легкий, напрочуд міцний і небезпечний у здобуванні. Сатир Зенн Фаулгуф, який чигає біля лісової дороги, наймає молодих шукачів пригод збирати клапті цього шовку разом з іклами нічних шаблезубів і перами стригідних сов. Запевняючи, що це просто рідкісні складники для його лісової справи, він розраховує на наївність новачків, які збиратимуть дикі складники, не ставлячи питань про його споганену природу чи справжні наміри."}},faq={{q="Де знайти Павутинний Шовк Вебвуда?",a="Павутинний Шовк Вебвуда збирають із причаєнців Плетива Лісу та споріднених павуків, що живуть у диких краях Тельдрассила, особливо довкола поселення Доланаар.",al={"місце шовку вебвуда","хто дропає шовк вебвуда","де взяти шовк вебвуда"}},{q="Кому потрібен цей шовк?",a="Сатир Зенн Фаулгуф, що потай веде свої справи трохи на північ від стежки між Тінедолом і Доланааром, просить клапті шовку, а також совине пір'я та ікла хижаків.",al={"кому потрібен шовк вебвуда","видавець завдання на шовк вебвуда","шовк зенна фаулгуфа"}},{q="Навіщо Зеннові Фаулгуфу Павутинний Шовк Вебвуда?",a="Zenn claims to need the silk as a reagent for his forest business, but keeps the details of that business to himself.",al={"мотив зенна фаулгуфа","навіщо зенну шовк"}},{q="Чи можна використати Павутинний Шовк Вебвуда в кравецтві?",a="Ні. Хоч це й справжній павучий шовк, саме ця зібрана нитка — реагент для завдання, а не звичайна тканина для кравців.",al={"чи шовк вебвуда для кравецтва","крафт із шовку вебвуда"}}},fp="19,244,17.509.0,39.163.0,20.179.0,48.117.1,50.133.0"}
P.entries["item:webwood-venom-sac"] = {n="Отруйний Мішок Павука Вебвуда",s="Отруйний Мішок Павука Вебвуда — орган, здобутий із величезних павуків, що населяють Тінедол на Тельдрассилі. Природознавці шукають ці зразки, щоб з'ясувати, як неприродне зростання нового Світового Дерева змінило тутешню звірину.",h="Отруйний Мішок Павука Вебвуда — орган, здобутий із величезних павуків, що населяють Тінедол на Тельдрассилі.",kw={"отруйний мішок павука вебвуда","вебвуд","павуки","отрута","ґілшалан віндвокер","печера тіньової нитки","тінедол"},ang={["class:Druid"]="Для друїдів, настроєних на рівновагу природи, споганена сила цих отруйних мішків — тривожний речовий доказ того, що на вітті Тельдрассила не все гаразд.",["race:NightElf"]="Молодим нічним ельфам — шукачам пригод у Тінедолі доручають збирати ці зразки на допомогу вченим, які намагаються зрозуміти дивну нову природу їхньої батьківщини на верхівці віття."},sec={{t="Симптом зростання Тельдрассила",b="Павуки Вебвуда, що мешкають довкола й усередині Печери Тіньової Нитки, — родичі значно меншої породи павуків, яка водиться деінде. Їхнє раптове збільшення й хижа лють стривожили дослідників — нічних ельфів. Природознавці на кшталт Ґілшалана Віндвокера вивчають отруту в цих мішках, щоб проаналізувати її силу й склад, сподіваючись зрозуміти, як стрімке, неблагословенне зростання Тельдрассила спотворює створінь, що живуть на його вітті."}},faq={{q="Де знайти Отруйні Мішки Павука Вебвуда?",a="Їх збирають із павуків Вебвуда, що заполонили північ Тінедолу, особливо всередині й довкола Печери Тіньової Нитки.",al={"де вони падають","місце отруйного мішка вебвуда","місце павучої отрути"}},{q="Кому потрібні ці отруйні мішки?",a="Ґілшалан Віндвокер, дослідник із нічних ельфів, що стоїть біля Алдрассила в Тінедолі, збирає їх, щоб вивчити будову павуків, перш ніж повернутися до Дарнасуса.",al={"кому потрібні отруйні мішки","завдання гілшалана віндволкера"}},{q="Чому павуки Вебвуда такі великі?",a="Дослідники вважають, що поява й стрімкий ріст нового Світового Древа, Тельдрассила, глибоко й спотворено вплинули на місцеву живність, і звичайні павуки виросли на величезних агресивних хижаків.",al={"чому павуки вебвуда великі","розмір павуків вебвуда"}},{q="Чи роблять із цієї отрути протиотруту?",a="Ґілшалан збирає ці мішки лише для порівняльного дослідження. Утім, павуча отрута цього краю відома своєю небезпекою, і щоб урятувати покусаних у лісі, потрібні окремі ліки, як-от протиотрута для Іверрона.",al={"чи це для ліків","інгредієнт протиотрути"}}},fp="17,226,32.467.0,35.132.0,27.168.0,37.228.0,39.218.0"}
P.entries["item:well-stone"] = {n="Камінь Криниці",s="Камені Криниці — невеликі мінеральні камінці, зібрані на берегах і довкола водяних криниць Малгору. Багаті на тонкі енергії землі, вони слугують важливим складником у приготуванні Води Провидців під час традиційних обрядів посвяти тауренів.",h="Камені Криниці — невеликі мінеральні камінці, зібрані на берегах і довкола водяних криниць Малгору.",kw={"камінь криниці","вода провидців","зарлман ту-мунс","обряд видіння","криниця","шаман","малгор"},ang={["class:Shaman"]="Шамани розуміють Камені Криниці як природні якорі магії землі й води, що стягують приховані духи в перетворювальну церемоніальну суміш.",["race:Tauren"]="Збирання Каменів Криниці — важливий крок у вияві єднання з землею, що вчить кожного молодого таурена, як тілесні стихії землі сприяють духовному просвітленню."},sec={{t="Посудина енергій землі",b="Лежачи в м'якій землі на берегах криниць Малгору, Камені Криниці вбирають духовний відгук рівнин і вод під ними. Шамани й провидці на кшталт Зарлмана Ту-Мунса бачать у цих каменях не буденну річкову гальку, а вмістилища життєвої магії. У поєднанні з бурштиновими шишками, зібраними під могутніми деревами рівнин, їхні мінеральні властивості гартують вариво, потрібне, щоб пробудити провидчий транс у молодих тауренів, які проходять священний Обряд Видіння."}},faq={{q="Для чого потрібні Камені Криниці?",a="Камені Криниці разом із бурштиновими жолудями використовують, щоб зварити Воду Провидців. Випите біля племінного вогнища, це зілля посилає провідне видіння новачкам, які прагнуть довести свою духовну зрілість.",al={"призначення каменів криниці","для чого камінь криниці","навіщо збирати камені криниці"}},{q="Де знайти Камені Криниці?",a="Вони лежать на землі довкола спільних криниць, розкиданих по Малгору, там, де життєдайна волога рівнин торкається ґрунту.",al={"де знайти камені криниці","місця каменів криниці","камінь криниці малгор"}},{q="Хто просить ці камені?",a="Зарлман Ту-Мунс, шанований містик із Села Бладгуф, посилає новачків зібрати їх у межах Обряду Видіння.",al={"хто потребує камені","камені зарлмана","камені обряду видіння"}}},fp="10,249,26.492.0,30.200.0,28.143.0,26.132.0"}
P.entries["item:wendigo-mane"] = {n="Грива Вендіго",s="Гриви Вендиґо — густі кошлаті шуби, зняті з диких вендиґо, що блукають замерзлими скелями Дун Мороґу. Їх цінують за надійне утеплення від пронизливого гірського холоду: ці грубі шкури досить міцні, щоб устилати підлогу хатин чи залізні кабіни дворфійських бойових машин.",h="Гриви Вендиґо — густі кошлаті шуби, зняті з диких вендиґо, що блукають замерзлими скелями Дун Мороґу.",kw={"грива вендиґо","вендиґо","хутро","пілот стоунґір","сиве лігво","троллплоу","харанос"},ang={["profession:Engineering"]="Керувати дворфійською технікою в Дун Мороґу — означає миритися з крижаними металевими кабінами, тож утеплювальна підкладка з хутра вендиґо — практичне поліпшення для затишку.",["race:Dwarf"]="Полювання на вендиґо Сивого Лігва — перевірене часом випробування для молодих дворфів, які хочуть довести свою твердість ветеранам Хараноса."},sec={{t="Тепло для залізяччя",b="Гори Дун Мороґу суворі й непоступливі, тож місцеві вміють дати раду верховним звірам, що никають заметами. Грубе хутро вендиґо щільно захищає від лютих морозних протягів. Пілот Стоунґір, що стоїть біля Хараноса, посилає шукачів пригод до сусіднього Сивого Лігва по ці важкі гриви. Але ексцентричний пілот не збирається шити зимові шуби чи плащі: він має намір сплести з них пухнастий утеплювальний килим на внутрішню палубу своєї дорогоцінної дворфійської облогової машини Троллплоу."}},faq={{q="Які створіння дають Гриву Вендіго?",a="Гриви можна зібрати з будь-якого вендіго, що живе в снігах Дун Мороґу: зі звичайних молодих вендіго, дорослих вендіго й відомих ватажків на кшталт Ваґаша, Едана Вивуна та Старого Айсбірда.",al={"де падають гриви вендіго","хто дропає гриву вендіго","джерела гриви вендіго"}},{q="Навіщо Пілотові Стоунґіру ці гриви?",a="Пілот Стоунґір хоче зробити з грив теплий килим для кабіни своєї облогової машини «Тролеплуг». Коли ведеш величезну залізну машину по замерзлій землі, стає страшенно холодно, а густе хутро зберігає місце пілота теплим і затишним.",al={"чому стоунґір хоче гриви","килим пілота стоунґіра","для чого гриви"}},{q="Де найкраще шукати вендіго заради грив?",a="Пілот Стоунґір радить передусім Сиве Лігво — печери, видовбані в горах просто на захід від Хараноса. У печері та на схилах довкола аж кишить вендіго.",al={"місце сивого лігва","де полювати на вендіго","печера вендіго дун морог"}},{q="Чи небезпечно полювати на вендіго?",a="Так. Вендіго — дикі хижаки, що люто стережуть свої володіння, мають страхітливу силу й товсту шкуру. Дворфські наставники вважають вилазку до їхніх лігв першим обрядом посвяти, що доводить відвагу й бойову загартованість горянина.",al={"чи важко вбити вендіго","бій з вендіго"}}},fp="12,286,24.529.0,36.207.0,42.256.0,57.190.0,31.221.0"}
P.entries["item:whitestone-oak-lumber"] = {n="Дубова Деревина Вайтстоуну",s="Дубова Деревина Вайтстоуну — міцна ремісницька деревина з підземних верфей під Мунбруком. Її цінують за міцність, і вона слугує важливим матеріалом для руків'їв священного озброєння, яке кують майстри-ковалі Альянсу.",h="Дубова Деревина Вайтстоуну — міцна ремісницька деревина з підземних верфей під Мунбруком.",kw={"дубова деревина вайтстоуну","деревина","мертві копальні","братство дефіас","джордан стілвелл","випробування праведності","паладин"},ang={["class:Paladin"]="Здобути цю деревину з підземних доків Дефіас — ключова вимога Випробування праведності Джордана Стілвелла, що дає священний молот, викуваний для захисників Світла.",["profession:Blacksmithing"]="У кресленнях зброї Стілвелла щільний дуб Вайтстоуну поєднано з очищеною рудою та самоцвітом, щоб урівноважити вагу, міцність і метафізичний відгук."},sec={{t="Деревина підземних доків",b="Дуб Вайтстоуну, який знаходять глибоко в заплутаних Мертвих Копальнях Вестфолу, обробляють ґоблінські різьбярі, що будують таємний бойовий флот Братства Дефіас. Щільне, пружне волокно робить його ідеальним для конструкцій, що мають витримувати навантаження й сильні удари, і це привертає увагу досвідчених зброярів, яким для церемоніального й бойового ремесла потрібне щось більше за звичайний ясен чи сосну."},{t="Священне руків'я",b="Біля Айронфорджа коваль Джордан Стілвелл вимагає Дубову Деревину Вайтстоуну, щоб створити зброю, гідну справжнього захисника Світла. Поєднана з очищеним самоцвітом Кор і очищеними металами, ця деревина дає врівноважене, непохитне руків'я, здатне витримати святі енергії, які спрямовують під час Випробування праведності."}},faq={{q="Де знайти Дубову Деревину Вайтстоуну?",a="Її забирають у гоблінів-різьбярів, що працюють глибоко в Мертвих Копальнях під Мунбруком у Вестфолі, де Братство Дефіас будує свій потаємний велетенський корабель.",al={"де взяти дубову деревину вайтстоуну","місце дубу вайтстоуну","хто дропає дубову деревину вайтстоуну"}},{q="Хто використовує цю деревину?",a="Джордан Стілвелл, умілий коваль, що працює біля брами Айронфорджа в Дун Мороґу, потребує її, щоб виготовити особливу зброю для паладинів, які набирають сили.",al={"хто потребує дуб вайтстоуну","здати дуб вайтстоуну"}},{q="Що роблять із цієї деревини?",a="З міцної деревини Джордан Стілвелл робить держак майстерного дворучного святого молота, який кує як нагороду за проходження Випробування Праведності.",al={"призначення дуба вайтстоуну","що кує джордан стілвелл"}},{q="Чому гоблінська деревина годиться для святої зброї?",a="Братство Дефіас добуває щільну, найякіснішу деревину, здатну витримати бойові кораблі. Джордан Стілвелл розуміє, що таке міцне будівельне дерево має досить витривалості, щоб витримати потужну божественну силу.",al={"чому гоблінська деревина","чому деревина мертвих копалень"}}},fp="21,227,25.381.0,13.320.1,37.168.0,21.161.0,30.158.0,48.215.0"}
P.entries["item:wildmane-cleansing-totem"] = {n="Тотем Очищення Вайлдмейн",s="Тотем Очищення Вайлдмейн — освячене ритуальне знаряддя, виготовлене, щоб очистити північну водяну криницю Малгору. Довірений молодим захисникам землі, він стає останнім знаряддям у вигнанні отруйної скверни, залишеної загарбницькими підприємствами гоблінів.",h="Тотем Очищення Вайлдмейн — освячене ритуальне знаряддя, виготовлене, щоб очистити північну водяну криницю...",kw={"тотем очищення вайлдмейн","вайлдмейн","криниця","малл тандергорн","очищення","гобліни","тандер блаф"},ang={["class:Shaman"]="Спрямовувати духовне очищення через різьблені тотеми — основа зцілення поранених духів води, осквернених безоглядною промисловістю.",["race:Tauren"]="Відновити криницю Вайлдмейнів — урочистий обов'язок перед Матір'ю-Землею: вигнати чужі промислові отрути, щоб зберегти вашу прабатьківську домівку."},sec={{t="Очищення священних криниць",b="Коли підприємства гоблінів почали труїти землю й забруднювати бідні запаси води Малгору, таурени звернулися до священного ритуалу, щоб повернути лихо назад. Очистивши водяні криниці Вінтергуфів і Тандергорнів, Малл Тандергорн виготовляє цей останній тотем, аби вигнати решту скверни з Водяної Криниці Вайлдмейнів на північ від Тандер Блафу. Наснажений духами природи, тотем очищає смердючі води, щоб чисте життя знову могло живити рівнини."}},faq={{q="Для чого потрібен Тотем Очищення Вайлдмейн?",a="Тотем використовують у тауренському обряді очищення, щоб знешкодити отрути й брудні стоки, які забруднюють Водяну Криницю Вайлдмейнів на північ від Тандер Блафа, і повернути землі чистоту.",al={"що робить тотем","використання тотема вайлдмейн","навіщо очищати криницю"}},{q="Хто створює Тотем Очищення Вайлдмейн?",a="Малл Тандергорн дає тотем, коли ви допоможете йому зібрати потрібні складники й очистити інші отруєні криниці Малгору.",al={"хто дав мені тотем","тотем мулла тандергорна","де взяти тотем очищення"}},{q="Чому отруєні криниці Малгору?",a="Гобліни-зайди принесли шкідливі отрути й руйнівні промислові стоки в місцеві ґрунтові води, загрожуючи племенам тауренів і природній рівновазі рівнин.",al={"хто отруїв криниці","чому криниця отруйна","гоблінські отрути малгору"}},{q="Де треба використати цей тотем?",a="Його треба віднести до Водяної Криниці Вайлдмейнів на хвилястих рівнинах на північ від великих скель Тандер Блафа.",al={"місце криниці вайлдмейн","де криниця води вайлдмейн","куди нести тотем"}}},fp="24,265,26.452.0,52.187.0,41.152.0,44.182.0,38.119.0"}
P.entries["item:wiley-s-note"] = {n="Записка Вайлі",s="«Записка Вайлі» — таємне послання, яке написав пройдисвіт із Лейкширу Вайлі Чорний, щоб сплатити борг Ґраянові Стаутмантлу. Її зміст викриває тривожні союзи Братства Дефіас і втягує в розслідування розвідку Стормвінда.",h="«Записка Вайлі» — таємне послання, яке написав пройдисвіт із Лейкширу Вайлі Чорний, щоб сплатити борг...",kw={"записка вайлі","вайлі чорний","братство дефіас","гільдія каменярів","матіас шоу","si:7"},ang={["class:Rogue"]="Послання проходить через руки двох знаних постатей вашого ремесла: Вайлі Чорного, вуличного пройдисвіта, і Майстра Матіаса Шоу, очільника таємної SI:7.",["faction:Alliance"]="Ця записка — переломний момент, коли прикордонний розбій у Вестфолі визнають організованою змовою, що загрожує стабільності самого Стормвінда."},sec={{t="Небезпечні записи",b="Цю нашкрябану звістку написав у Редріджі темний пройдисвіт Вайлі Чорний і передав, щоб віддячити Ґраянові Стаутмантлу за давню послугу. У ній Вайлі викладає все, що знає про таємні задуми Братства Дефіас. З його відомостей випливає, що братство діє не саме: воно уклало союзи з місцевими гнолами, кобольдами й гоблінськими агентами, щоб поширити свої справи на все королівство."},{t="Слід каменярів",b="Окрім згадок про угоди з найманцями, Вайлі ненароком обмовляється про важливу річ — зв'язок угруповання Дефіас із Гільдією Каменярів, яка відбудувала Стормвінд після Другої війни. Відчуваючи вибухові політичні наслідки цієї подробиці, Стаутмантл пересилає записку просто до рук Майстра Матіаса Шоу, очільника шпигунів SI:7, — і втягує в розслідування всю розвідку Стормвінда."}},faq={{q="Хто написав Записку Вайлі?",a="Її написав Вайлі Чорний, сумнівної моралі ділок із Лейкширу в Редріджі. Він дав записку, щоб віддячити за давню послугу Ґраянові Стаутмантлу з Народного ополчення.",al={"автор записки вайлі","хто такий вайлі","записка вайлі чорного"}},{q="Які відомості містить записка?",a="Записка попереджає, що Братство Дефіас замишляє щось грандіозне й уклало союзи з гнолами, кобольдами й гоблінами. Щодо делікатнішої частини її змісту Стаутмантл шукає подальшої поради.",al={"зміст записки вайлі","що каже записка","інформація записки дефіас"}},{q="Куди треба доставити записку?",a="Спершу її несуть Ґраянові Стаутмантлу в Сентінел Гілл у Вестфолі. Прочитавши її, Стаутмантл велить доставити записку Майстрові Матіасу Шоу в штаб-квартиру SI:7 у Стормвінді.",al={"хто отримує записку вайлі","здати записку вайлі","куди нести записку"}},{q="Чому Ґраян Стаутмантл надсилає записку до SI:7?",a="Ґраян підозрює, що записка вказує на глибшу змову, ніж звичайний розбій. Він надсилає її Матіасу Шоу, очільникові розвідки Стормвінда, щоб той розібрався.",al={"чому показати матіасу шоу","чому дати записку шоу","записка вайлі сі7"}}},fp="12,260,18.433.0,25.402.1,23.206.0,39.197.0,41.193.0,49.161.0"}
P.entries["item:william-s-shipment"] = {n="Вантаж Вільяма",s="Вантаж Вільяма — дбайливо запакована партія свічок, здобутих у клопітних кобольдів Лісу Елвінн. Спакований Вільямом Пестлом у Ґолдширі, він призначений для алхімічної справи його брата Морґана в Торговому Кварталі Стормвінда.",h="Вантаж Вільяма — дбайливо запакована партія свічок, здобутих у клопітних кобольдів Лісу Елвінн.",kw={"вантаж вільяма","свічки","вільям пестл","аптека пестлів","торговий квартал","кобольди"},ang={["faction:Alliance"]="Очищення копалень Елвінну від кобольдів служить Альянсу подвійно: захищає місцеве господарство й постачає крамницям столиці сировину для алхімії.",["race:Human"]="Ця доставка показує тісні господарські зв'язки, що єднають сільські містечка на кшталт Ґолдширу зі столицею Стормвінд."},sec={{t="Родинна торгівля",b="Брати Пестли тримають сталий торговий зв'язок між Ґолдширом і столицею. Поки Вільям працює в Лісі Елвінн, збираючи матеріали в тутешніх ділків і шукачів пригод, Морґан порядкує в родинній крамниці — Аптеці Пестлів у Торговому Кварталі Стормвінда. Оскільки Вільям не може покинути власні обов'язки й поїхати на північ, він покладається на гінців, щоб доправити цей надійно запакований пакунок воску й свічок до міста."},{t="Кобольдовий віск",b="The contents of the shipment are kobold candles, salvaged from the creatures infesting Elwynn's mines. William gathers the large candles for their wax and packs them for his brother Morgan at Pestle's Apothecary. Through William's enterprise, these reclaimed mining scavenges become useful stock for the capital's alchemical trade."}},faq={{q="Що у Вантажі Вільяма?",a="У вантажі — свічки, зібрані в кобольдів із шахт Лісу Елвінн. Вільям Пестл скуповує їх у мандрівних шукачів пригод і пакує як сировину для родинної алхімічної крамниці.",al={"вміст вантажу","що в коробці","що вільям надсилає"}},{q="Кому Вільям надсилає цей пакунок?",a="Його адресовано братові Вільяма, Морґанові Пестлу, що тримає аптеку Пестлів у Торговому Кварталі Стормвінда.",al={"кому вантаж","для кого доставка","пункт призначення вантажу"}},{q="Навіщо аптекареві стільки свічок?",a="William says that he and his brother need the large candles for their wax. He does not describe the particular preparations they will use it for.",al={"навіщо свічки для алхімії","що пестл робить зі свічками","використання свічок"}},{q="Чому Вільям сам не доставляє пакунок?",a="Вільям зайнятий своїми справами й закупівлями в Ґолдширі й не має часу на подорож до Стормвінда, тож наймає мандрівників, що прямують до столиці.",al={"чому вільям не може піти","чому вільяму потрібен кур'єр"}}},fp="18,246,16.436.0,10.331.0,34.211.0,39.126.0,44.145.0,48.195.0"}
P.entries["item:wine-ticket"] = {n="Талон на Вино",s="Талон на Вино — рекламний купон, який роздають у Стормвінді, щоб привабити покупців до виноробні «Галліна». Пред'явивши його Сюзетті Галліні в родинній крамниці, власник талона отримує безкоштовну пляшку піно нуар.",h="Талон на Вино — рекламний купон, який роздають у Стормвінді, щоб привабити покупців до виноробні «Галліна».",kw={"талон на вино","сюзетта галліна","ренато галліна","піно нуар","вино","торговий квартал"},ang={["profession:Cooking"]="Добра пляшка піно нуар, отримана за цей талон, чудово пасує до ситного м'яса й сирів, зібраних по всіх Східних Королівствах."},sec={{t="Реклама родинного вина",b="Щоб тримати вишукану винну крамницю в гамірному місті на кшталт Стормвінда, потрібна кмітлива реклама. Ренато Галліна роздає ці друковані талони біля Торгового Кварталу, щоб привабити спраглих відвідувачів до виноробні «Галліна», що стоїть неподалік, над каналами. Обіцяючи безкоштовну пробу славетного піно нуар, родина Галліна сподівається перетворити цікавих перехожих і щойно прибулих шукачів пригод на вірних покупців на все життя."}},faq={{q="Що робити з Талоном на Вино?",a="Віднесіть талон Сюзетті Галліні у виноробню Галліни біля каналів у Торговому Кварталі Стормвінда. Вона залюбки обміняє його на безплатну пляшку піно нуар.",al={"використання талона на вино","як використати талон на вино","куди нести талон на вино"}},{q="Хто роздає ці талони?",a="Ренато Галліна роздає їх як рекламні купони, щоб заманити покупців із гамірних вулиць Торгового Кварталу до родинної винної крамниці.",al={"хто дає талон на вино","де взяти талон на вино"}},{q="Яке вино можна отримати за талон?",a="За купон дають пляшку піно нуар — славетного вина, яким родина Галліна гордо торгує як одним із найкращих у королівстві.",al={"нагорода за талон на вино","яке вино отримаю"}}},fp="11,214,28.432.0,34.182.0,28.160.0,41.164.0"}
P.entries["item:winterhoof-cleansing-totem"] = {n="Тотем Очищення Вінтергуф",s="Тотем Очищення Вінтергуф — освячене ритуальне знаряддя, виготовлене Маллом Тандергорном у Селі Бладгуф. Вирізьблений, щоб звести нанівець отруйне лихо, яке поширили зайди з Венчурної Компанії, він спрямовує силу Матері-Землі на очищення забрудненої Водяної Криниці Вінтергуфів.",h="Тотем Очищення Вінтергуф — освячене ритуальне знаряддя, виготовлене Маллом Тандергорном у Селі Бладгуф.",kw={"тотем очищення вінтергуф","вінтергуф","криниця","малл тандергорн","венчурна компанія","очищення","малгор"},ang={["class:Shaman"]="Використання очисного тотема відображає основні засади шаманізму: гармонією стихій землі й води вигнати штучну скверну.",["race:Tauren"]="Осквернення джерел прісної води б'є в саме серце зв'язку тауренів із Матір'ю-Землею, тож ритуал тотема — неодмінний захист батьківщини."},sec={{t="Очищення джерела",b="Коли гоблінські інженери Венчурної Компанії вдерлися на рівнини Малгору, їхні промислові роботи швидко отруїли дорогоцінні підземні води краю. У відповідь Малл Тандергорн підготував Тотем Очищення Вінтергуф, наснаживши різьблене дерево захисною магією, що має вимити чужі отрути. Пронесений повз ворожих гоблінських вартових до краю Водяної Криниці Вінтергуфів, тотем розсіює забруднення зосередженим ритуалом і повертає чисту питну воду мандрівним стадам і корінним племенам рівнин."}},faq={{q="Для чого потрібен Тотем Очищення Вінтергуф?",a="Його несуть до Водяної Криниці Вінтергуфів на південний схід від Села Бладгуф, щоб провести обряд очищення й змити промислове забруднення, яке гобліни Венчурної Компанії скинули в підземні води.",al={"призначення очисного тотема","використання тотема вінтергуф","що робить тотем"}},{q="Хто виготовив цей тотем?",a="Малл Тандергорн, шанований таурен із Села Бладгуф, вирізьбив і підготував тотем саме для того, щоб виправити шкоду, завдану Водяній Криниці Вінтергуфів.",al={"хто зробив тотем вінтергуф","творець очисного тотема","тотем мулла"}},{q="Чому Водяна Криниця Вінтергуфів забруднена?",a="Венчурна Компанія розбила табір довкола джерела й споганила природний водопій стоками, відходами й хімічним мулом від своїх лісорубних і гірничих машин.",al={"хто отруїв колодязь вінтергуфів","причина забруднення колодязя","чому колодязь брудний"}},{q="Що стається, коли обряд очищення завершено?",a="Каламутна, отруєна вода знову стає чистою й здоровою, і місцеві звірі рівнин та мандрівні стада тауренів можуть знову безпечно пити з криниці.",al={"після використання тотема","результат очищення колодязя","чи колодязь виправиться"}}},fp="26,266,20.564.0,48.199.0,23.164.0,43.182.0,51.159.0"}
P.entries["item:witchwing-talon"] = {n="Кіготь Відьмокрила",s="Кіготь відьмокрила — відтятий пазур войовничих гарпій, що живуть у північно-західних каньйонах Пусток. Розвідники Орди на Перехресті збирають ці кігті як кривавий доказ загибелі нападниць, прагнучи вбезпечити важливі караванні шляхи.",h="Кіготь відьмокрила — відтятий пазур войовничих гарпій, що живуть у північно-західних каньйонах Пусток.",kw={"кіготь відьмокрила","гарпії","відьмокрили","дарсок свіфтдаґґер","перехрестя","каравани"},ang={["class:Rogue"]="Дарсок Свіфтдаґґер цінує тиху точність ножа біля горла й вважає ці гострі кігті знаком фахової розправи над повітряними хижачками.",["faction:Horde"]="Каравани — кровоносні судини, що поєднують розкидані застави Орди в Калімдорі, тож криваве винищення гнізд гарпій — необхідна умова безпеки прикордоння."},sec={{t="Трофеї з гнізд",b="Гарпії-Відьмокрили гніздяться серед скель і ярів на північний захід від Перехрестя й раз у раз налітають, щоб грабувати каравани Орди з припасами, які перетинають посушливі рівнини. Щоб відбити цю загрозу, розвідник Дарсок Свіфтдаґґер організовує удари по верхівці зграї. Звичайним доповідям він не вірить і вимагає речового доказу смерті кожної мародерки. Ці гострі як бритва кігті — певне свідчення, що ще одній нападниці перерізано горлянку; так розвідники проріджують рядових гарпій, перш ніж наважитися вдарити вище по ланцюжку командування."}},faq={{q="Кому й навіщо потрібні Кігті Відьмокрила?",a="Їх збирає Дарсок Свіфтдаґґер, орк-розвідник із Перехрестя. Він задумав планомірно винищити виводок Відьмокрилих і вимагає вісім кігтів як доказ того, що їхніх передових нападниць убито.",al={"кому потрібні кігті відьмокрила","видавець завдання на кігті відьмокрила","кігті дарсока свіфтдаґґера"}},{q="Які гарпії мають ці кігті?",a="Їх можна відрубати майже в будь-якої гарпії-Відьмокрилої на північному заході Пусток — особливо у звичайних гарпій і дикоперих Відьмокрилих, що гніздяться вздовж круч і сухих хребтів.",al={"що дропає кігті відьмокрила","які гарпії мають кігті"}},{q="Чому полюють на гарпій-Відьмокрилих?",a="Зграя Відьмокрилих дедалі зухваліє й постійно налітає на шляхи постачання Орди й торгові каравани, що перетинають Пустки. Наступ Дарсока має прорідити їхні нижчі ряди, перш ніж узятися за їхніх поручниць і матріарху.",al={"чому вбивати гарпій відьмокрилих","призначення гарпій-грабіжниць"}}},fp="15,253,24.566.0,35.222.0,33.180.0,45.254.0"}
P.entries["item:wolf-heart-sample"] = {n="Зразок Вовчого Серця",s="Зразок вовчого серця — законсервований пакунок ураженої хворобою вовчатини, який перевозять зі сплюндрованих лісів Лордерону до Калімдору. Його доправляють на замовлення Королівського Аптекарського Товариства, і він дає цінний матеріал для вивчення того, як північні чуми впливають на звірів Пусток.",h="Зразок вовчого серця — законсервований пакунок ураженої хворобою вовчатини, який перевозять зі сплюндрованих...",kw={"зразок вовчого серця","аптекар гелбрім","королівське аптекарське товариство","відступники","андерсіті","перехрестя"},ang={["faction:Horde"]="Перевезення дослідницьких реагентів через море показує, як постачання й наука поєднують Андерсіті із заставами Орди в Пустках.",["race:Undead"]="Доставка цього зразка показує, як розширюється наукова досяжність Королівського Аптекарського Товариства, яке випробовує північні суміші на чужій природі Калімдору."},sec={{t="Отруйний експорт",b="Цей зразок серця взято із заражених чумою вовків, що блукають руїнами Лордерону; спершу його зібрав Аптекар Ренферрел, а тоді спакували для перевезення через Велике море. Королівське Аптекарське Товариство Відступників невтомно прагне поглибити свою владу над отрутами, поморами й біологічними реагентами. Відправлений із гінцем на Перехрестя в Пустках, пакунок показує, як далеко сягають хімічні задуми Андерсіті: досліди в понівечених Східних Королівствах тепер прямо пов'язані з прикордонними заставами Калімдору."},{t="Дослідження Гелбріма",b="На Перехресті зразок вручають Аптекареві Гелбріму. Його польові дослідження зосереджені на тому, як могутні отрути, народжені в сплюндрованому Погибеллю Лордероні, впливають на місцеву звірину Калімдору чи пристосовуються до неї. Вивчаючи отруйність, збережену в цих вовчих серцях, Гелбрім сподівається відкрити нові властивості, щоб удосконалити й посилити отрути й еліксири Відступників далеко від дому."}},faq={{q="Що таке Зразок Вовчого Серця?",a="Це законсервований зразок тканини уражених пошестю вовків Лордерона. Він досі несе отруйність північних чум, і Королівське Аптекарське Товариство використовує його, щоб вивчати смертоносні отрути.",al={"зразок вовчого серця","що за зразок","що в пакунку"}},{q="Хто надіслав цей зразок до Пусток?",a="Зразок надійшов від мережі аптекарів-Відступників у Східних Королівствах — із зразків, які зібрав Аптекар Ренферрел у Срібноліссі, — і вже звідти його переслали до Калімдору.",al={"хто надіслав вовче серце","хто дав мені це","походження зразка вовчого серця"}},{q="Навіщо він Аптекареві Гелбріму?",a="Гелбрім досліджує, як отрути з Лордерона діють на корінних звірів Калімдору. Він хоче проаналізувати отруйні властивості зразка, щоб удосконалити алхімічні й отруйні суміші Відступників.",al={"навіщо гелбріму зразок","дослідження гелбріма","призначення вовчого серця"}},{q="Куди треба доставити зразок?",a="Його треба віднести Аптекареві Гелбріму на Перехрестя — велике поселення Орди в самому серці Пусток.",al={"куди нести вовче серце","де гелбрім","місце доставки"}}},fp="17,284,14.570.0,18.428.0,30.205.0,36.197.0,36.199.0,43.121.0"}
P.entries["item:wolf-heart-samples"] = {n="Зразки Вовчого Серця",s="Зразки Вовчого Серця — незвичайні шматки органічної тканини, зібрані з покручених вовків Срібнолісся. Хоч ці серця смертельно отруйні, вони б'ються в живих звірах, не вбиваючи їх, — і це викликає палкий науковий інтерес Королівського Аптекарського Товариства.",h="Зразки Вовчого Серця — незвичайні шматки органічної тканини, зібрані з покручених вовків Срібнолісся.",kw={"зразки вовчого серця","аптекар ренферрел","аптекар зінґе","вовки","отрута","срібнолісся","аптекаріум"},ang={["race:Undead"]="Невпинні пошуки смертоносних реагентів, які веде Королівське Аптекарське Товариство, живлять виживання й оборону Відступників — і проти живих, і проти немертвих ворогів."},sec={{t="Отруйний парадокс",b="Оглядаючи туші в Срібноліссі, Аптекар Ренферрел виявив, що серця деяких вовків містять смертоносну сполуку. Дивно, але отрути в їхній тканині досить, щоб легко вбити самих вовків. Розуміючи, яка цінна фізіологія, що процвітає, попри те що просякнута смертельною отрутою, Ренферрел відклав зразки тканин, щоб відіслати їх просто до Андерсіті. Для Відступників вивчення природно стійких чи отруйних організмів — важливий крок до опанування біологічної війни й створення нових реагентів."},{t="Вантаж до Андерсіті",b="Зразки довіряють гінцям, що прямують глибоко під руїни Лордерона, і ті доставляють їх Аптекареві Зінґе до осідку Королівського Аптекарського Товариства в Апотекаріумі. Зінґе та її колеги понад усе цінують нові отрути. Розтинаючи ці отруєні тканини й експериментуючи з ними, Товариство прагне виокремити заразні сполуки й розгадати, як звірі їх витримували, — щоб застосувати ці закономірності у власних алхімічних задумах."}},faq={{q="Чим ці вовчі серця важливі для Відступників?",a="Зразки мають сильну, незбагненну отруйність, яка мала б убити вовків-носіїв. Королівське Аптекарське Товариство захоплене і самою смертоносною отрутою, і біологічним механізмом, що дає звірам її пережити.",al={"чому вовчі серця важливі","що робить серця особливими","навіщо аптекарям вовчі серця"}},{q="Хто замовляє ці зразки?",a="Аптекар Ренферрел зібрав зразки, вивчаючи вовків у Срібноліссі. Він доручив гінцеві доставити їх просто його колезі, Аптекареві Зінґе, у штаб-квартиру Товариства в Андерсіті.",al={"хто хоче вовчі серця","хто надіслав зразки","хто отримує зразки"}},{q="Що Аптекар Зінґе з ними робитиме?",a="Аптекар Зінґе проводить на зразках алхімічні досліди й розтини. Королівське Аптекарське Товариство постійно описує нові отрути й обертає їх на зброю, щоб створювати нові чуми й зілля для Королеви Сильвани.",al={"що зінґе робить із серцями","досліди зінґе","дослідження аптекаря зінґе"}},{q="Звідки ці вовки?",a="На вовків полювали в опоганених хащах Срібнолісся — краю, тяжко враженого темною магією, тлінням і дивною скверною, що змінює місцевих звірів.",al={"звідки вовки","вовки сільверпайну","місце вовків"}}},fp="18,272,15.552.0,24.468.0,54.246.0,27.215.0,40.216.0,31.165.0"}
P.entries["item:wood-pulp"] = {n="Деревна Маса",s="Деревна маса — волокниста речовина, яку носять при собі дворфи, що стоять у Бель Модані на півдні Пусток. Сама собою вона нешкідлива, але для експедиції з Бел'дуна це головна вбирна основа, що робить рідку вибухівку стійкою.",h="Деревна маса — волокниста речовина, яку носять при собі дворфи, що стоять у Бель Модані на півдні Пусток.",kw={"деревна маса","бель модан","ґанн стоунспайр","нітрогліцерин","вибухівка","дворфи"},ang={["profession:Engineering"]="Будь-який інженер упізнає цю суміш: тирса чи деревна маса з нітрогліцерином і нітратним окисником — класичний спосіб перетворити нестійку рідку сполуку на надійний динаміт.",["race:Tauren"]="Для племені Стоунспайр обернути промислову вибухівку загарбників проти Бель Модану — справжня поетична справедливість за руйнування родового краю."},sec={{t="Вибухонебезпечний рецепт",b="Дворфи з Айронфорджа в Бель Модані важкою землерийною технікою й хімічною вибухівкою роздирають землю на родових мисливських угіддях тауренів. Рідкий нітрогліцерин сам собою славиться своєю нестійкістю; щоб зробити його придатним для розкопок і бою, дворфійські інженери вбирають рідину в пористу деревну масу разом із нітратом натрію й пакують стійкі заряди. Дворфійські стрільці, солдати й офіцери тримають в'язки цієї волокнистої маси під рукою для підкопів і польових боєприпасів."},{t="Обернене проти фортеці",b="Коли загинув Шукач Хазґорм, вигнаний зі своїх земель тауренський воїн Ґанн Стоунспайр роздобув дворфійські креслення підривних робіт. Не бажаючи, щоб розкопки й далі вгризалися в землі його племені, Ґанн обертає ці самі інженерні прийоми проти загарбників. Відібравши в гарнізону Бел'дуна деревну масу, нітрогліцерин і нітрати, Ґанн поєднує їх в особливий вибуховий заряд, щоб знищити літальну машину дворфів у Бель Модані."}},faq={{q="Для чого в Бель Модані потрібна деревна маса?",a="У дворфських боєприпасах деревна маса править за вбирну основу. Чистий нітрогліцерин нестійкий і може вибухнути від випадкового поштовху, але, просочивши ним органічну речовину на кшталт деревної маси, сапери можуть безпечно перевозити й використовувати потужні підривні заряди.",al={"чому дворфи мають деревну масу","призначення деревної маси","що робить деревна маса"}},{q="Хто в Пустках має деревну масу?",a="Деревну масу носять дворфські війська в Бель Модані на півдні Пусток: солдати, стрільці, офіцери Бел'дуну та їхній командувач, лорд Сайрік Блекфордж.",al={"де взяти деревну масу","хто дропає деревну масу","місце деревної маси"}},{q="Навіщо Ґаннові Стоунспайру ця деревна маса?",a="Ґанн Стоунспайр хоче обернути руйнівні прийоми дворфів проти них самих. За дворфськими підривними кресленнями він змішує деревну масу з добутим нітрогліцерином і нітратом натрію, щоб зробити заряд, здатний знищити літальну машину дворфів у Бель Модані.",al={"хто хоче деревну масу","деревна маса ґанна стоунспайра","навіщо збирати деревну масу"}},{q="Чи вибухає деревна маса сама по собі?",a="Ні. Сира деревна маса — це просто подрібнене деревне волокно. Небезпечною вона стає лише в поєднанні з нестійкими речовинами, як-от нітрогліцерин, і окисниками, як-от нітрат натрію.",al={"чи вибухонебезпечна деревна маса","чи може деревна маса вибухнути"}}},fp="9,239,17.498.0,23.460.1,41.254.0,37.185.0,45.290.0,33.166.0"}
P.entries["item:wooden-key"] = {n="Дерев'яний Ключ",s="Дерев'яний Ключ — простий різьблений ключ, який носять збожеволілі прадавні, що блукають на півночі Ашенвалю біля кордону зі Скверноліссям. Він відмикає заховану скриню, де лежить частина Жезла Дартола — прадавньої реліквії нічних ельфів.",h="Дерев'яний Ключ — простий різьблений ключ, який носять збожеволілі прадавні, що блукають на півночі Ашенвалю...",kw={"дерев'яний ключ","прадавні","жезл дартола","залізне древко","шаель'дрін","сквернолісся"},ang={["class:Druid"]="Спотворені прадавні, що тримають цей ключ, показують, як далеко сягає трагічна демонічна порча, що отруює кенарійські гаї між Ашенвалем і Скверноліссям.",["race:NightElf"]="Бачити, як улюблені прадавні Калімдору божеволіють і стискають утрачені реліквії при дорозі до Сквернолісся, — сумне видовище для кожного дитяти зірок."},sec={{t="Ключ у божевільних руках",b="The Wooden Key is held by the Crazed and Withered Ancients wandering the shaded trails north of Raynewood Retreat. Shael'dryn once knew the local treants, but now describes their nature as twisted by corruption. One of them carries the key to a chest holding a piece of Dartol's Rod."},{t="Як відімкнути жезл",b="Дріада Шаель'дрін доручає шукачам пригод здобути цей ключ, щоб відімкнути заховану стару скриню на невеликій галявині на захід від дороги до Сквернолісся. Усередині лежить Залізне Древко — одна з важливих частин, потрібних, щоб відновити Жезл Дартола й боротися з порчею, яка отруює священні ліси."}},faq={{q="Що відмикає Дерев'яний Ключ?",a="Дерев'яний Ключ відмикає стару скриню, сховану на невеликій галявині на захід від головної дороги, що веде на північ до Сквернолісся. У скрині лежить Залізне Древко — частина, потрібна, щоб відновити Жезл Дартола.",al={"що відчиняє дерев'яний ключ","скриня дерев'яного ключа","де використати дерев'яний ключ"}},{q="Хто носить Дерев'яний Ключ?",a="Ключ носять божевільні й зів'ялі древні, що блукають лісами на північ від Притулку Рейнвуд біля кордону зі Скверноліссям.",al={"хто дропає дерев'яний ключ","де знайти дерев'яний ключ","дроп дерев'яного ключа"}},{q="Звідки в древніх цей ключ?",a="Shael'dryn says that one of the corrupted treants near Felwood carries the key. She does not explain how it came into the treant's possession.",al={"чому деревники мають ключ","лор давнього ключа"}},{q="Хто посилає вас по Дерев'яний Ключ?",a="Shael'dryn, a dryad tending the Moonwell of Purity in Ashenvale, directs adventurers to recover the key as part of the effort to reassemble Dartol's Rod.",al={"видавець завдання дерев'яного ключа","хто хоче дерев'яний ключ"}}},fp="10,219,18.283.0,17.302.1,32.190.0,27.131.0,34.142.0,41.153.0"}
P.entries["item:worn-parchment"] = {n="Зношений Пергамент",s="Зношені Пергаменти — уривки обрядових записів, які носять культисти, що отаборилися довкола Вежі Альталакса на півночі Темного Узбережжя. Зібрані розвідниками, ці пошарпані клаптики дають перші відчутні підказки про те, яка зловісна секта збирається в руїнах.",h="Зношені Пергаменти — уривки обрядових записів, які носять культисти, що отаборилися довкола Вежі Альталакса...",kw={"зношений пергамент","культ темного берега","вежа альталакса","балтул шедовстрайк","делґрен очищувач","ковен"},ang={["class:Warlock"]="Записи Темного Берега викривають організований ковен, який таємно діє на землях нічних ельфів і орудує Скверною й тінню подалі від очей і Альянсу, і Орди.",["race:NightElf"]="Темні чаклуни й демонічна порча біля давніх руїн на кшталт Альталакса — тяжке осквернення священних нетрів Темного Узбережжя."},sec={{t="Уривки зловісної змови",b="На півночі оповитого імлою Темного Узбережжя темні чаклуни та їхні ревні послідовники захопили зруйновану Вежу Альталакса. Рядові вояки, що патрулюють довкола, — фанатики Темного Берега — носять серед особистих речей клаптики зношеного пергаменту. Окремий клаптик видається лише уривком каракуль і езотеричних символів, але, склавши кілька уламків докупи, можна виявити досі невідому організацію — Культ Темного Берега."},{t="Зірвати маску з культу",b="Балтул Шедовстрайк, розвідник, що стежить за вежею з сусіднього пагорба, за цими зібраними пергаментами оцінює загрозу для Делґрена Очищувача й Вартових в Обердайні. Складені докупи тексти підтверджують: чорнокнижники у вежі — не самотні вигнанці, а організований ковен, що йде до продуманої, лиховісної мети."}},faq={{q="Хто носить ці зношені пергаменти?",a="Пергаменти носять фанатики Темного Берега — рядові культисти, що стоять табором по периметру Вежі Альталакса на півночі Темного Узбережжя.",al={"хто дропає зношені пергаменти","де взяти зношений пергамент","джерело зношеного пергаменту"}},{q="Що написано на пергаментах?",a="Поодинці це загадкові уривки ритуальних нотаток і наказів. Але коли їх зібрати й розшифрувати, Балтул Шедовстрайк дізнається з них назву й саме існування Культу Темного Берега.",al={"що написано на зношеному пергаменті","текст зношеного пергаменту","значення пергаменту"}},{q="Навіщо Балтул Шедовстрайк їх збирає?",a="Делґрен Очищувач доручив Балтулові стежити за Вежею Альталакса. Йому потрібні ці записи, щоб з'ясувати, чому в руїнах зібралися чорнокнижники, і оцінити загрозу для Темного Узбережжя, перш ніж доповісти.",al={"хто хоче зношений пергамент","завдання балтул","навіщо збирати пергаменти"}},{q="Що таке Культ Темного Берега?",a="Це таємне угруповання культистів і чорнокнижників, що діє з руїн Альталакса. Навіть досвідчені розвідники на кшталт Балтула Шедовстрайка ніколи не стикалися з цим орденом, доки не знайшли цих записів.",al={"культ темного берега","хто такі темний берег","культ темного берега лор"}}},fp="14,257,28.497.0,18.355.1,34.164.0,34.199.0,45.208.0,36.210.0"}
P.entries["item:worn-stone-token"] = {n="Стертий Кам'яний Жетон",s="Стерті Кам'яні Жетони — маленькі магічні талісмани, які носять служителі й маги, пов'язані з Далараном, у Горах Альтерак. Хоча їхня магія здебільшого вивітрилася, їх створили, щоб допомагати Кірін-Тору підкоряти елементалів-слуг і командувати ними.",h="Стерті Кам'яні Жетони — маленькі магічні талісмани, які носять служителі й маги, пов'язані з Далараном, у...",kw={"стертий кам'яний жетон","жетони","кірін-тор","елементалі","хранитель бел'варіл","таррен мілл"},ang={["class:Mage"]="Маги впізнають у цих жетонах практичні фокусувальні предмети, якими Кірін-Тор тримає закликаних елементалів стабільними й слухняними в полі.",["faction:Horde"]="Здобуття цих жетонів допомагає Відступникам у Таррен Міллі вивчати таємну оборону й практики ворожого Кірін-Тору в Альтераку."},sec={{t="Жетони влади над стихіями",b="Маги Даларана здавна мають грізну владу над стихійними сутностями, підкоряючи цих істот з інших вимірів своїй волі за допомогою особливих талісманів. Стерті Кам'яні Жетони — це виснажені, відпрацьовані зразки таких знарядь. Їх носять не лише теурги й закликачі, а навіть даларанські робітники й вартові, розставлені довкола руїн і таборів інтернування в Альтераку, — і це показує, наскільки глибоко підкорення елементалів вплетене в щоденну роботу Даларана."},{t="Цікавість Відступників",b="Зі своєї застави в Таррен Міллі Відступники пильно стежать за сусідніми чарівниками. Маг Войдґлер прагнув роздобути зразки цих жетонів, щоб розгадати даларанські способи поневолення елементалів. Хранитель Бел'варіл посилає агентів спершу зібрати стерті, бездіяльні жетони, щоб Маг міг безпечно вивчити основні прийоми зачарування, перш ніж братися за могутніші й нестійкіші провідники."}},faq={{q="Для чого використовували ці жетони?",a="Чарівники Даларана використовують ці магічні кам'яні жетони, щоб керувати елементалями, викликаними з інших світів, і підкоряти їх як робітників, вартових і захисників.",al={"призначення стертого каменя жетона","що таке кам'яні жетони","чому даларан носить жетони"}},{q="Чому ці жетони називають стертими?",a="Їхні чари з часом і від частого вжитку вивітрилися. Хранитель Бел'варіл вважає такі неактивні зразки безпечнішими для перших досліджень Мага Войдґлера щодо даларанських ритуалів підкорення.",al={"чому жетони стерті","чи жетони магічні","інертні жетони"}},{q="Хто носить ці жетони?",a="Їх знаходять у різних людей Даларана, що діють на півдні Гір Альтерак, — від високопоставлених закликачів і теургів до звичайних робітників, щитоносців і Наглядача Беламура в таборі для інтернованих.",al={"хто дропає стерті кам'яні жетони","де взяти жетони","дроп жетонів даларана"}},{q="Навіщо вони Відступникам?",a="Маг Войдґлер хоче вивчити даларанські тайні прийоми керування елементалями, щоб розгадати секрети їхнього мистецтва виклику й підкорення.",al={"чому бельварил хоче жетони","жетони мага войдґлера"}}},fp="16,249,27.487.0,18.398.0,32.151.0,37.187.0,25.221.0,32.163.0"}
P.entries["item:woven-wand"] = {n="Плетена Чарівна Паличка",s="Плетена Чарівна Паличка — унікальна зачарована реліквія, яку колись створили троє учнів-магів Даларана на знак братерства. Після падіння Лордерона й гірких зрад між її творцями паличку сховали у Фортеці Фенріс, а згодом вона знову спливла — вже в руках Відступників.",h="Плетена Чарівна Паличка — унікальна зачарована реліквія, яку колись створили троє учнів-магів Даларана на...",kw={"плетена чарівна паличка","бетор айсшард","ґунтер арканус","тул рейвенклов","фортеця фенріс","даларан","аларік"},ang={["class:Mage"]="Плетена Чарівна Паличка показує давні традиції учнів Даларана, які часто експериментували, поєднуючи особисті провідники, щоб зосередити спільну магічну силу.",["race:Undead"]="Цей артефакт — гірко-солодке нагадування про смертні життя, забрані Погибеллю: він єднає спогади двох уцілілих Відступників проти безумства їхнього занепалого колишнього товариша."},sec={{t="Розірвані узи",b="У ті часи, коли Даларан ще навчав молодих магів півночі, троє честолюбних чарівників — Бетор Айсшард, Ґунтер Арканус і Тул Рейвенклов — сплели свої учнівські чарівні палички в єдиний талісман. Ця Плетена Чарівна Паличка стала і провідником їхньої спільної магічної сили, і символом міцної дружби. Та братерство безповоротно розпалося, коли Погибель пронеслася Лордероном. Тул Рейвенклов присягнув на вірність Королю-Лічу й звернувся до мерзенної некромантії. А Бетора й Ґунтера забрала Чума Нежиття, і зрештою їхні зв'язки з Далараном обірвалися остаточно."},{t="Схована ніша",b="Хоч, звернувши до темряви, Тул зненавидів сентиментальність палички, він так і не наважився ні знищити її, ні віддати колишнім товаришам. Натомість він відніс артефакт у Срібнолісся й сховав глибоко в ніші у Фортеці Фенріс. Минули роки; лігво Тула було взято, а його слуга Аларік вказав агентам Орди на схованку — і реліквію знайшли цілою. Некромант жодного разу не пробуджував її приспаних чарів, і врешті паличку доставили Беторові Айсшарду в Магічний Квартал Андерсіті."}},faq={{q="Хто створив Плетену Чарівну Паличку?",a="Паличку спільно виготовили троє учнів-магів із Даларана: Бетор Айсшард, Ґунтер Арканус і Тул Рейвенклов. Вони сплели свої три учнівські палички в один спільний артефакт на знак дружби.",al={"хто створив плетену чарівну паличку","творці плетеної палички","творці палички"}},{q="Чому паличку сховали у Фортеці Фенріс?",a="Коли Тул зрадив товаришів, щоб служити Королю-Лічу, він зненавидів артефакт і дружбу, яку той уособлював. Проте розлучитися з ним чи знищити його так і не зміг, тож сховав у потаємній ніші свого лігва у Фортеці Фенріс.",al={"чому тул сховав паличку","де знайшли плетену паличку","чому фенріс"}},{q="Чому Бетор Айсшард вважав паличку втраченою?",a="Бетор вважав, що паличку втрачено назавжди, коли їхня дружба розпалася, а чума спустошила край. Він також зауважив, що Тул ніколи не наважувався пробудити її магічну силу: якби Тул нею скористався, Бетор відчув би сплеск через їхній досі живий магічний зв'язок.",al={"що каже бетор про паличку","реакція бетора на паличку"}},{q="Як паличку повернули?",a="Шукачі пригод з Орди вдерлися до Фортеці Фенріс, щоб здолати Тула Рейвенклова. Їх вела відрубана, але й досі мовна голова Аларіка, колишнього слуги Рейвенклова, і вони знайшли потаємну нішу з паличкою та винесли її з руїн.",al={"хто знайшов паличку","як отримати плетену паличку"}}},fp="10,282,15.609.0,17.578.1,27.226.0,39.242.0,48.275.0,27.229.1"}
P.entries["item:xavian-water-sample"] = {n="Зразок Води Зав'яну",s="Флакон чистої, наповненої магією води, набраної біля підніжжя найвищого водоспаду в прадавніх ельфійських руїнах Ксавіана. Маги Орди в Оргріммарі шукають її, щоб розгадати приховані таємні сили, що збереглися в найдавніших святинях Ашенвалю.",h="Флакон чистої, наповненої магією води, набраної біля підніжжя найвищого водоспаду в прадавніх ельфійських...",kw={"зразок води","ксавіан","дейно","маг","сатири","ашенваль"},ang={["class:Mage"]="Здобути зразок — важливе польове випробування для магів Орди: воно перевіряє, чи вміють вони черпати силу з природних таємних джерел і пробиратися ворожими землями, оскверненими демонами.",["faction:Horde"]="Поки Орда міцніше закріплюється в Ашенвалі довкола Застави Розщепленого Дерева, прадавні таємні багатства Ксавіана дають ученим Оргріммара цінні знання."},sec={{t="Води прадавнього міста",b="До Великого Розколу Ксавіан був славетним ельфійським поселенням, відомим своїми вченими-чародіями й прадавніми знаннями. Навіть після тисячоліть руйнації й занедбання його води, як вірять, зберігають могутні магічні властивості. Дейно, наставниця таємної магії в Оргріммарі, доручає молодим магам вирушити глибоко в Ашенваль і набрати свіжий зразок просто з озерця під найвищим водоспадом Ксавіана. Це небезпечна справа: руїни тепер люто стережуть зіпсовані сатири, ворожі до кожного чаклуна, що пхає туди свого носа."}},faq={{q="Де набирають зразок води?",a="Його набирають у Пляшку Дейно з водойми під найвищим водоспадом у руїнах Ксавіану. Це місце на північному сході Ашенвалю, на північ за озерами, що лежать за Заставою Розщепленого Дерева й Сатирнааром.",al={"де взяти зразок води зав'яну","водоспад зав'яну","як отримати зразок води зав'яну"}},{q="Навіщо Дейно ця вода?",a="Дейно — наставниця тайної магії з Долини Духів в Оргріммарі. Вона вивчає потужні й незвичні джерела магії, щоб навчати молодих чарівників Орди, і шукає давню магічну сутність, що зберігається в незайманих водах Ксавіану.",al={"хто хоче воду зав'яну","навіщо збирати воду з зав'яну","мета дейно"}},{q="Які загрози чатують біля вод Ксавіану?",a="У давніх ельфійських руїнах живуть сатири — демонічні створіння, що ненавидять чужинців і люто боронять свої володіння від цікавих магів. А в довколишніх водах водяться агресивні звірі, як-от річкові кроколіски.",al={"вороги зав'яну","хто живе в зав'яні","небезпеки зав'яну"}},{q="Що стається, коли зразок повертають до Оргріммара?",a="Дейно одразу береться вивчати тайні властивості зразка: зібрана магія допомагає їй у дослідженнях і в навчанні магів Орди.",al={"здати воду зав'яну","навіщо вода"}}},fp="19,245,26.558.0,36.226.0,31.238.0,40.228.0,54.167.0"}
P.entries["item:young-crocolisk-skin"] = {n="Шкіра Молодого Кроколіска",s="Шкіра молодого кроколіска — гнучка шкура плазуна, здобута з молодих кроколісків по всьому Багнокраю. Її цінують місцеві чинбарі, як-от Джеймс Галлоран із Гавані Менетіл: ці м'якші шкури вичиняють і вивозять до портів по всьому Азероту.",h="Шкіра молодого кроколіска — гнучка шкура плазуна, здобута з молодих кроколісків по всьому Багнокраю.",kw={"шкіра молодого кроколіска","кроколіски","джеймс галлоран","гавань менетіл","чинбарство","багнокрай"},ang={["class:Hunter"]="Вистежувати кроколісків на грузьких берегах Багнокраю — звична справа для слідопитів, що постачають шкіру жвавому ринку Гавані Менетіл."},sec={{t="Чинбарство й торгівля на болотах",b="Гавань Менетіл — жвавий торговий вузол на західному узбережжі Каз Модану, що вивозить болотяні товари до далеких портів. Серед найприбутковіших товарів містечка — вичинені шкури, які обробляє місцевий чинбар Джеймс Галлоран. Дорослі кроколіски дають товсту, цупку луску, а от їхні малята — м'якшу й куди податливішу шкіру. Оскільки ці молоді шкури делікатні й мають великий попит, Галлоран покладається на місцевих мисливців і мандрівників, що прочісують багнисті болота під самим містечком, аби його сушильні рами не порожніли."}},faq={{q="Чому Джеймсові Галлорану потрібні шкури саме молодих кроколісків?",a="Шкіра молодих кроколісків значно м'якша, ніж у дорослих. Дорослі звірі мають товсту, тверду луску, а шкури молодняку куди легше обробляти й вичиняти на м'які вироби, що мають великий попит на морських торгових шляхах.",al={"чому молоді кроколіски","шкури галлорана","чому м'які шкури"}},{q="Де шукати молодих кроколісків?",a="Молоді кроколіски Багнокраю живуть у протоках, трясовинах і болотах одразу за Гаванню Менетіл на заході Багнокраю.",al={"де молоді кроколіски","де шукати молодих кроколісків","кроколіски болот"}},{q="Хто ще полює на цих кроколісків для гавані?",a="Місцевий мисливець на ім'я Ейнар регулярно приносить шкури кроколісків для шкірницької справи Джеймса Галлорана, але попит часто випереджає те, що може добути один слідопит.",al={"хто ще полює на кроколісків","ейнар мисливець","мисливці менетіла шкіряр"}},{q="Куди відправляють ці вичинені шкури?",a="Готові вироби Галлорана вантажать на торгові судна, що відпливають із Гавані Менетіл до великих портів і ринків по всіх Східних Королівствах і далі.",al={"торгівля шкірою кроколіска","експорт шкір менетіла","куди йдуть шкури"}}},fp="20,237,32.560.0,70.259.0,36.126.0,47.182.0,36.157.0"}
P.entries["item:yowler-s-paw"] = {n="Лапа Виглядайла",s="Лапа Виглядайла — моторошний трофей, відрубана лапа Йоулера, лютого ватажка зграї гнолів, що тероризують пагорби над Лейкширом. Принесена місцевому майстрові Вернерові Осґуду, вона незаперечно доводить, що звіра, який вів місцеві зграї гнолів, знищено.",h="Лапа Виглядайла — моторошний трофей, відрубана лапа Йоулера, лютого ватажка зграї гнолів, що тероризують...",kw={"лапа виглядайла","йоулер","гноли","вернер осґуд","лейкшир","редрідж"},ang={["class:Hunter"]="Вистежити ватажка гнолів Редріджу й здобути його лапу — справжнє випробування ваших навичок слідопита й знавця звірів у двобої з небезпечним хижаком.",["faction:Alliance"]="Перемога над Йоулером допомагає втихомирити Гори Редріджу в час, коли військо Стормвінда надто розпорошене, щоб захистити власний східний кордон."},sec={{t="Трофей ватажка зграї",b="Гноли Редріджу давно тероризують висоти довкола Озера Незрушного, і їхнє моторошне виття долинає аж до Лейкширу. Серед них ніхто не наганяє такого страху, як Йоулер — безжальний ватажок, що веде їх уперед. Вуха й лапи гнолів у людських землях здавна правлять за доказ при виплаті нагород, тож Вернер Осґуд просить сміливців принести лапу Йоулера. Відрубати її — означає не лише покінчити з незвично хитрим хижаком, а й навмисно зламати ланцюг командування серед його безладних послідовників."},{t="Містечко, покинуте напризволяще",b="Лапа Йоулера нагадує, наскільки скрутно живеться Лейкширу. Військо Стормвінда цілком поглинуте загрозою орків Блекрок, що окопалися довкола Фортеці Кам'яної Варти, тож міська влада й мешканці змушені наймати мандрівних найманців для оборони. Без регулярних королівських гарнізонів такі докази, як лапа Йоулера, — єдиний спосіб для поселенців на кшталт Вернера Осґуда переконатися, що місцеві дороги хоч трохи безпечні для торгівлі й подорожей."}},faq={{q="Хто просить лапу Йоулера?",a="Лапу просить Вернер Осґуд, відомий ремісник і житель Лейкширу. Він хоче мати доказ, що небезпечного гнола-ватажка, який тероризує пагорби, знешкоджено назавжди.",al={"хто хоче лапу йоулера","завдання лапи йоулера вернера осґуда","здати лапу йоулера"}},{q="Хто такий Йоулер?",a="Йоулер — лютий ватажок гнолівських зграй Редріджу. На відміну від звичайних гнолів-дворняг, він має досить сили й хитрощів, щоб згуртувати кілька зграй, і тому становить нагальну небезпеку для мешканців довколишніх містечок.",al={"хто такий йоулер","лор йоулера","вожак гнолів редріджа"}},{q="Чому Лейкшир покладається на нагороди, а не на солдатів Стормвінда?",a="Армія Стормвінда вибивається з сил у боротьбі з орками Блекрок, що укріпилися у Фортеці Кам'яної Варти на сході Редріджу. Підкріплень немає, тож містяни на кшталт Вернера Осґуда мусять покладатися на вільних шукачів пригод, щоб полювати на такі загрози, як Йоулер.",al={"чому лейкшир покладається на нагороди","де армія стормвінда","чому вернер наймає найманців"}},{q="Що стається, коли Йоулера вбито?",a="Смерть Йоулера руйнує проводирство, що тримало лютих гнолів купи: його зграя розбігається по глушині, а мешканці Лейкширу отримують тимчасовий перепочинок.",al={"що буде після смерті йоулера","гноли після йоулера","кінець завдання виття в пагорбах"}}},fp="12,265,25.557.0,22.456.0,26.182.0,14.217.0,66.248.0,35.195.0"}
P.entries["item:zalazane-s-head"] = {n="Голова Залазана",s="Голова Залазана — похмурий трофей, який приносять Майстру Ґадріну на підтвердження загибелі зрадливого відьмака Залазана. Її здобуття — важливий крок до звільнення Островів Відлуння від темної магії, що тримає в заручниках дім племені Темного Списа.",h="Голова Залазана — похмурий трофей, який приносять Майстру Ґадріну на підтвердження загибелі зрадливого...",kw={"голова залазана","залазан","відьмак","ґадрін","острови відлуння","сен'джин","темний спис"},ang={["faction:Horde"]="Знищення Залазана убезпечує південне узбережжя Дуротару для Орди й не дає темній магії підточувати щойно засновані землі Тралла.",["race:Troll"]="Для тролів Темного Списа здобути голову Залазана — глибоко особистий акт помсти й справедливості щодо зрадника, який вигнав їхній народ і поневолив їхніх братів."},sec={{t="Доказ кінця зрадника",b="Коли відьмак Залазан зрадив плем'я Темного Списа, він удався до проклять, що поневолюють розум, аби захопити їхній острівний дім і вигнати народ Вол'джина на материкові береги Дуротару. З Островів Відлуння Залазан і далі посилав через воду зачаклованих рабів, щоб хапати нових жертв. Аби запевнити стривожених біженців у Селі Сен'джин, що панування тирана скінчилося, Майстер Ґадрін зажадав беззаперечного речового доказу його смерті. Повернення відрубаної голови не лише підтверджує поразку Залазана в бою, а й дарує вигнаному племені рідкісну дещицю спокою та надію колись повернути вкрадені острови."}},faq={{q="Хто просить Голову Залазана?",a="Майстер Ґадрін, знахар із Села Сен'джин на південному узбережжі Дуротару, просить шукачів пригод принести йому голову як доказ того, що Залазана вбито.",al={"хто хоче голову залазана","видавець завдання на голову залазана","ґадрін залазан"}},{q="Чому на Залазана полювали?",a="Колись Залазан був шанованим чаклуном серед Темного Спису, але жага влади штовхнула його поневолити родичів магією, що підкоряє розум. Він вигнав плем'я з Островів Відлуння й далі робив набіги на материк, щоб захопити більше тролів Темного Спису до своєї армії невільників.",al={"чому полювали на залазана","що накоїв залазан","лор залазана"}},{q="Де знайти Залазана?",a="Залазан живе на найбільшому з Островів Відлуння біля південно-східного узбережжя Дуротару в оточенні зачаклованих тролів і тролів-вудуїстів, прив'язаних до служби йому.",al={"де залазан","місце залазана","залазан острови відлуння"}},{q="Чи повертає здобута голова Острови Відлуння?",a="Смерть Залазана усуває безпосередню загрозу його набігів і приносить полегшення Селу Сен'джин, але Острови Відлуння лишаються небезпечними й повними його невільників-вудуїстів, тож Темний Спис і далі живе здебільшого на материку.",al={"чи тролі повернуть острови відлуння","чи острови відлуння звільнені","чи острови відлуння безпечні"}}},fp="15,245,26.634.0,29.171.0,26.264.0,24.152.0,46.241.0"}
P.entries["item:zamah-s-note"] = {n="Записка Замаха",s="Записка Замаха — письмове послання, яке Замах із Тандер Блафа надсилає через Велике Море Аптекареві Лайдону в Таррен Мілл. У ньому викладено нагальне прохання про алхімічне вариво, здатне впоратися з Венчурною Компанією в Горах Кам'яного Кігтя без прямого кровопролиття.",h="Записка Замаха — письмове послання, яке Замах із Тандер Блафа надсилає через Велике Море Аптекареві Лайдону в...",kw={"записка замаха","аптекарка замах","аптекар лайдон","таррен мілл","королівське аптекарське товариство","венчурна компанія","гори кам'яного кігтя"},ang={["faction:Horde"]="Доставка записки показує, як співпраця в постачанні та спільні ресурси пов'язують далекі столиці Орди в Калімдорі та Східних Королівствах.",["race:Undead"]="Це послання підкреслює, що союзники дедалі більше покладаються на особливі хімічні знання Королівського Аптекарського Товариства, коли треба розв'язати складну кризу."},sec={{t="Благання через Велике Море",b="Гоблінські підприємства Венчурної Компанії глибоко вкоренилися в Горах Кам'яного Кігтя: вони вирубують ліси й плюндрують священну землю. Замах шукає особливого способу вигнати їх, не вчиняючи відвертої різанини, і звертається до знавців із Королівського Аптекарського Товариства Відступників. Записка — офіційний лист, у якому вона описує тяжке становище в Горах Кам'яного Кігтя своєму колезі, Аптекареві Лайдону, що служить далеко в Таррен Міллі, у Передгір'ї Гілсбреда в Лордероні."},{t="Зв'язки аптекарів",b="Щоб доставити запечатане послання, мандрівникам із Калімдору доводиться здолати довгий шлях між континентами: цепеліном до Андерсіті, а звідти через Срібнолісся до Гілсбреда. Отримавши послання від Замах, Лайдон одразу зацікавлюється її особливими вимогами, пишається, що звістка про нього долетіла аж із-за океану, і береться готувати алхімічну відповідь на гоблінську проблему."}},faq={{q="Що таке Записка Замаха?",a="Це запечатаний лист, який Замах написала в Тандер Блафі Аптекареві Лайдону в Таррен Міллі: вона просить алхімічну формулу, щоб вигнати Венчурну Компанію з Гір Кам'яного Кігтя.",al={"що це за річ","записка замаха","лист до лайдона"}},{q="Чому Замах потрібна допомога з Таррен Мілла?",a="Замах шукає незвичного й безкровного способу вигнати гоблінів, що плюндрують Гори Кам'яного Кігтя. Вона звертається до Аптекаря Лайдона, бо алхіміки-Відступники мають особливі хімічні суміші саме для таких тонких диверсій.",al={"чому слати до гілсбреда","чому звертатися до лайдона","чому таррен мілл"}},{q="Куди треба доставити записку?",a="Її треба віднести Аптекареві Лайдону, що живе в містечку Таррен Мілл, яке тримають Відступники, у Передгір'ї Гілсбреда в Лордероні.",al={"хто отримує записку","здати записку замаха","куди нести записку"}},{q="Що це за Венчурна Компанія, згадана в записці?",a="Венчурна Компанія — безжальний гоблінський гірничий і лісорубний синдикат, горезвісний суцільними вирубками, хижацьким видобутком природних багатств і забрудненням земель по всьому Калімдору, зокрема священних вершин Гір Кам'яного Кігтя.",al={"венчурна компанія стоунталон","хто такі венчур","венчур"}}},fp="12,292,27.506.0,22.397.0,21.181.0,42.251.0,41.137.0,49.233.0"}
P.entries["item:zargh-s-meats"] = {n="М'ясо Зарга",s="М'ясо Зарга — пакунок добірних сирих шматків, які приготував орк Зарг на Перехресті. Це особистий подарунок для Корчмарки Гришки в Оргріммарі, а заразом — спосіб познайомити молодих мандрівників Орди з мережею перельотів на вітрокрилах.",h="М'ясо Зарга — пакунок добірних сирих шматків, які приготував орк Зарг на Перехресті.",kw={"м'ясо зарга","зарг","корчмарка гришка","оргріммар","вітрокрили","перехрестя"},ang={["profession:Cooking"]="Корчмарка Гришка цінує ці свіжі шматки — вони показують, що орки найбільше люблять ледь підсмажене червоне м'ясо, здобуте просто з диких звірів Пусток.",["race:Orc"]="Доставляючи Гришці добірне м'ясо від Зарга, молоді орки знайомляться з серцем своєї столиці в Долині Сили й дізнаються, наскільки потрібні перельоти на вивернах."},sec={{t="Вантаж гінця",b="Цей пакунок приготував Зарг, різник і мисливець із Перехрестя в Пустках; у ньому — добірні шматки свіжого м'яса для Гришки, корчмарки з Долини Сили в Оргріммарі. Свіжа дичина швидко псується в сухій спеці саван, тож Зарг довіряє пакунок гінцям, що прямують до сідала вітрокрилів на Перехресті. Там Господар Вітрокрилів Деврак влаштовує швидкий переліт на виверні просто до Небесної Вежі Оргріммара — і мандрівникам не доводиться виснажливо брести суходолом через Дуротар."},{t="Шлях до серця",b="На позір це звичайна доставка харчів, але в посилці є й тепле особисте почуття. Отримавши пакунок, Гришка охоче визнає, що Зарг уміє завоювати прихильність жінки добірною дичиною, і радо береться підсмажити ці ласі шматки для відвідувачів і гостей своєї корчми. Для новоприбулих орків і тролів-шукачів пригод ця доставка — важливе знайомство з далекими перельотами між поселеннями Орди в Калімдорі."}},faq={{q="Хто приготував М'ясо Зарга?",a="М'ясо зібрав і запакував Зарг — орк із застави Перехрестя в Пустках.",al={"хто приготував м'ясо зарга","хто такий зарг","звідки м'ясо"}},{q="Хто отримувач м'яса?",a="Шматки надсилають Гришці — корчмарці, що тримає головну таверну в Долині Сили в Оргріммарі.",al={"хто отримує м'ясо","хто така ґришка","куди доставити м'ясо зарга"}},{q="Чому м'ясо треба везти на вітрокрилі?",a="Свіже м'ясо швидко псується в пекельній спеці Пусток і Дуротару. Зарг посилає гінців до Деврака, господаря вітрокрилів на Перехресті, щоб віверна доставила пакунок до Оргріммара, перш ніж м'ясо зіпсується.",al={"чому м'ясо летить","вітрокрил дерака м'ясо"}},{q="Чому цей пакунок можуть доставити лише певні раси?",a="Доручення Зарга до Оргріммара отримують мандрівники-орки й тролі, тоді як шукачів пригод тауренів посилають до Тандер Блафа зі звірячими шкурами, а гінці-Відступники везуть припаси до Гробниці.",al={"чому таурени не мають цього завдання","нежить м'ясо зарга","хто може доставити м'ясо зарга"}}},fp="13,236,17.517.0,18.455.0,27.100.0,34.104.0,41.207.0,48.206.0"}
P.entries["item:zhevra-hooves"] = {n="Копита Жеври",s="Копита жеври — міцні частини диких копитних, що бродять посушливими рівнинами Пусток. Їх приносять на Перехрестя як мисливські трофеї, щоб довести свою вправність у боротьбі зі звірами, які куди сильніші, ніж здаються на перший погляд.",h="Копита жеври — міцні частини диких копитних, що бродять посушливими рівнинами Пусток.",kw={"копита жеври","жеври","серґра даркторн","перехрестя","полювання","мисливець"},ang={["class:Hunter"]="Вистежування жевр на савані вчить стрільців і ловців давати раду прудким, спритним стадним тваринам, які вміють миттю розвернутися й ударити нищівним копитом.",["faction:Horde"]="Для новобранців, що прибувають у Пустки, зібрати копита для Серґри Даркторн — один із перших обрядів випробування, що доводить їхню придатність боронити Перехрестя."},sec={{t="Мисливські трофеї",b="Жеври можуть здатися звичайними смугастими травоїдами, але їхні короткі м'язисті ноги неабияк небезпечні. Серґра Даркторн, досвідчена мисливиця з Перехрестя, випробовує молодих розвідників Орди, посилаючи їх по копита прудких жевр. Ця вправа має відточити чуття й витривалість мисливця-початківця, адже добрий удар переляканої жеври може збити з ніг навіть кремезного таурена. Принесені цілі копита підтверджують, що мисливець дає раду прудкій здобичі, яка вміє хвицятися, і готовий до найсмертоносніших хижаків Калімдору."}},faq={{q="Кому потрібні Копита Жеври?",a="Серґра Даркторн, оркиня-мисливиця з Перехрестя в Пустках, просить мисливців принести їй чотири Копита Жеври, щоб довести, що вони готові до серйознішої здобичі.",al={"кому потрібні копита","хто бере копита жеври","копита серґри"}},{q="Звідки беруться Копита Жеври?",a="Їх збирають із жевр-бігунів, що пасуться на відкритих саванах на північ і на південь від Перехрестя.",al={"де взяти копита","місце бігуна жеври","знайти жевру"}},{q="Чому полювати на жевр небезпечно?",a="Жеври не такі агресивні, як раптори чи нишпорки, але мають неймовірну силу удару задніми ногами. Прямий удар жеври на бігу може збити з ніг навіть дорослого таурена.",al={"чи жеври сильні","сила удару жеври","небезпека жеври"}},{q="Чому Серґра посилає мисливців на жевр, а не на лютіших звірів?",a="Серґра вважає жевр наступним щаблем після степових довгоступів: це безпечне, але серйозне випробування, де новачки можуть нагострити зуби, перш ніж зустрітися з по-справжньому смертоносними створіннями.",al={"чому полювати на жевр","призначення навчання серґри"}}},fp="13,258,20.578.0,24.163.0,33.130.0,33.201.0,69.175.0"}
P.entries["npc:abercrombie"] = {n="Аберкромбі",s="Аберкромбі здається немічним, дивакуватим відлюдником, що живе в напіврозваленій халупі на заході Сутінколісся, біля Цвинтаря Воронячого Пагорба. Видаючи себе за безневинного самітника, якого мучать жахи лісу, він охоче просить співчутливих мандрівників зібрати для нього дивні реагенти й припаси.",h="Аберкромбі здається немічним, дивакуватим відлюдником, що живе в напіврозваленій халупі на заході...",kw={"аберкромбі","бальзамувальник","стітчес","некромантія","воронячий пагорб","сутінколісся","еліза"},ang={["class:Paladin"]="Аберкромбі — втілення підступної некромантської скверни, що ховається під личиною звичайного, нешкідливого містянина, який потребує милосердя.",["class:Warlock"]="Аберкромбі віддав власне серце, щоб оживити труп, — і це показує, на які крайні, саморуйнівні кроки здатні смертні заради темної магії.",["faction:Alliance"]="Герої Альянсу, що простодушно допомагають нещасному відлюдникові, самі того не знаючи, постачають усе потрібне для нападу на Даркшир."},sec={{t="Самітник Воронячого Пагорба",b="Захований у гнилих тінях біля Цвинтаря Воронячого Пагорба, Аберкромбі має жалюгідний вигляд. Він видає себе за старого, який лише намагається пережити жахи Сутінколісся, і просить мандрівників збігати в Даркшир по дрібниці — припаси, трави й нитки. Тим, хто не знає історії краю, він здається ще однією нещасною душею, покинутою напризволяще, коли край занепав."},{t="Божевілля Бальзамувальника",b="Доки горе не поглинуло його розум, Аберкромбі був шанованим і добрим алхіміком із Воронячого Пагорба. Коли померла його кохана дружина Еліза, скорбота зламала його. Звернувшись до заборонених некромантських мистецтв, він вирізав власне серце й уклав його в мертві груди Елізи, щоб повернути її до життя. Обряд породив лише чудовисько: Еліза повернулася, проклята ненаситним голодом до живої плоті, і збожеволілий алхімік мусив тримати її похованою на цвинтарі."},{t="Жахливий обман",b="У темних переказах його знають просто як «Бальзамувальника». Аберкромбі плекає глибоку, безумну злобу на містечко Даркшир і його очільників. Начебто невинні доручення, які він дає послужливим шукачам пригод, — принести ребра гулів, особливі нитки та їдкі відвари, — насправді є останніми складниками для Стітчеса, колосальної, зшитої з плоті потвори, створеної, щоб вирізати Нічну Варту й спалити місто."}},faq={{q="Хто такий Аберкромбі?",a="Аберкромбі — відлюдник, що живе біля Цвинтаря Воронячого Пагорба в Сутінколіссі. Колись умілий алхімік, він збожеволів після смерті дружини й потай є тим самим некромантом, якого знають як Бальзамувальника.",al={"хто відлюдник","лор аберкромбі","хто такий аберкромбі"}},{q="Навіщо Аберкромбі припаси з Даркширу?",a="Аберкромбі запевняє, що йому потрібні домашні припаси й нитки, щоб вижити в глушині, але насправді він обдурює шукачів пригод, змушуючи їх збирати частини, з яких складе жахливу гидоту Стітчеса.",al={"навіщо аберкромбі нитка","припаси аберкромбі","що будує аберкромбі"}},{q="Хто така Еліза?",a="Еліза — дружина Аберкромбі. Коли вона померла, Аберкромбі спробував воскресити її темною магією, пересадивши власне серце в її тіло. Вона повернулася ненажерливим неживим чудовиськом, і йому довелося тримати її похованою на Цвинтарі Воронячого Пагорба.",al={"еліза аберкромбі","дружина аберкромбі","наречена бальзамувальника"}},{q="Що стається, коли віддати записку мерові?",a="Записка викриває справжню особу Аберкромбі — Бальзамувальника — і його мстиву ненависть до Даркширу. Щойно лист доставлено, Стітчес вирушає дорогою на штурм містечка.",al={"записка мерові","що написано в записці","лист аберкромбі"}},{q="Чому Аберкромбі ненавидить Даркшир?",a="Геть збожеволілий від горя й темної магії, Аберкромбі звинувачує містечко та його провідників у трагічних подіях Сутінколісся й прагне знищити їх дощенту руками свого жахливого творіння.",al={"чому аберкромбі нападає на даркшир","мотив бальзамувальника","помста аберкромбі"}},{q="Чи Аберкромбі в союзі з Погибеллю?",a="Ні. Аберкромбі — незалежний алхімік і некромант-відщепенець, що вдався до заборонених мистецтв через власне божевілля, народжене горем, і з військами Короля-Ліча не пов'язаний.",al={"чи аберкромбі погибель","на кого працює аберкромбі"}}},fp="11,298,25.408.0,22.461.2,21.431.1,19.207.2,50.211.1,14.240.1,52.187.2,36.190.1,39.166.0"}
P.entries["npc:aelthalyste"] = {n="Елталіста",s="Елталіста — баньші, наставниця жерців і помітна постать Культу Забутої Тіні; її місце — у Воєнному Кварталі Андерсіті. Вона опікується духовною дисципліною послушників-Відступників і вчить їх володіти темною силою Тіні. Вона також співпрацює з іншими духовними провідниками Орди й посилає послушників-тролів до їхніх старійшин в Оргріммарі.",h="Елталіста — баньші, наставниця жерців і помітна постать Культу Забутої Тіні; її місце — у Воєнному Кварталі...",kw={"елталіста","баньші","культ забутої тіні","андерсіті","відступники","жрець","ур'кьо"},ang={["class:Priest"]="Для жерців-Відступників Елталіста — осердя їхнього вчення: вона навчає особливих темних заклять і веде їх шляхом Культу Забутої Тіні.",["faction:Horde"]="Її співпраця з наставниками Калімдору, як-от Ур'кьо, показує, як релігійна повага допомагає долати культурні прірви в молодому союзі Орди.",["race:Troll"]="Замість навертати посвячених тролів до обрядів Відступників, Елталіста з поваги відсилає жерців Темного Спису назад до Ур'кьо в Оргріммар.",["race:Undead"]="Елталіста втілює шлях Відступників: від Святого Світла їхнього колишнього життя — до прагматичної сили Тіні."},sec={{t="Голос Забутої Тіні",b="На відміну від багатьох жерців Азероту, що шанують Святе Світло, Елталіста веде Відступників шляхом учення Культу Забутої Тіні. Безтілесна баньші, вона втілює примарну муку й непохитну рішучість послідовників Сильвани Віндраннер. Зі своїх покоїв у Воєнному Кварталі Андерсіті вона кличе жерців-початківців із далеких застав, щоб ті опанували темніші сторони свого вчення й навчилися обертати страждання на смертоносну зброю."},{t="Зв'язки з Ордою",b="Хоч Елталіста зосереджена передусім на своїй пастві Відступників, вона підтримує взаємну повагу з іншими духовними провідниками Орди. Визнаючи самобутність духовних практик Темного Спису, вона не навертає посвячених тролів до власного вчення про Тінь, а посилає їх за море, до Ур'кьо в Оргріммарі. Цей жест поваги дає змогу заклиначам Орди зростати у своїх культурних традиціях і зміцнює союз між Калімдором і Лордероном."}},faq={{q="Хто така Елталіста?",a="Елталіста — банші, наставниця жерців у Воєнному Кварталі Андерсіті. Вона одна з провідних наставниць Культу Забутих Тіней і навчає Відступників магії Тіні.",al={"лор елталісти","хто жриця банші","елталіста нпс"}},{q="Де знайти Елталісту?",a="Вона перебуває у Воєнному Кварталі Андерсіті під руїнами Столиці, в оточенні інших наставників-Відступників.",al={"місце елталісти","де елталіста","знайти елталісту"}},{q="Що таке Культ Забутих Тіней?",a="Культ Забутих Тіней — панівне духовне вчення серед Відступників. Народжене з травми нежиття й відчуття, що Святе Світло їх покинуло, воно вивчає рівновагу між Світлом і Тінню та схиляється до темряви, сили волі й особистої дисципліни.",al={"забуті тіні","релігія відступників жерців","культ забутих тіней"}},{q="Чому Елталіста посилає жерців-тролів до Оргріммара?",a="Елталіста розуміє, що стосунки тролів із духами й тінню дуже відрізняються від учення Відступників. На знак поваги вона посилає послушників-тролів навчатися в Ур'кьо, наставника жерців Темного Спису в Долині Духів.",al={"ур'кйо елталіста","чому відсилати тролів","завдання тролів елталісти"}},{q="Чого навчає Елталіста?",a="Вона дає Відступникам основи жрецької науки, а досвідченіших послушників навчає особливих ритуалів нежиті, зокрема закляттям Дотик Слабкості й Ненажерлива Чума.",al={"навчання жерців елталісти","які закляття дає елталіста","здібності елталісти"}},{q="Чи вірна Елталіста Сильвані?",a="Так. Як банші з Андерсіті, вона служить Сильвані Віндраннер і завзято зміцнює Відступників, навчаючи їх темної магії.",al={"фракція елталісти","чи вона вірна андерсіту","вірність банші"}}},fp="11,369,29.476.0,19.465.0,19.203.0,29.128.0,38.269.0,53.243.0,28.182.0,33.151.0"}
P.entries["npc:agathelos-the-raging"] = {n="Аґателос Лютий",s="Аґателос Лютий — велетенський броньований вепр, замкнений у колючих тунелях Рейзорфен Краула. Шипогриви Мертвої Голови виростили його як живу облогову машину й утілення свого давнього бога, і його довели до лютого, неприродного шалу. Завдяки самій своїй масі й силі він — один із найнебезпечніших звірів, що ховаються під південними Пустками.",h="Аґателос Лютий — велетенський броньований вепр, замкнений у колючих тунелях Рейзорфен Краула.",kw={"аґателос лютий","вепр","рейзорфен краул","мертва голова","аґамаґґан","шипогриви"},ang={["class:Druid"]="Друїди глибоко шанують Аґамаґґана як одного з великих Прадавніх, що полягли у Війні Прадавніх; бачити, як священного вепра труять кажанячою отрутою, щоб зробити з нього облогову зброю, — образа для дикої рівноваги Кенарія.",["class:Hunter"]="Мисливець оцінить саму хижу міць Аґателоса, хоча його спотворене, підживлене хімією божевілля робить його трагічним викривленням природних звірів.",["race:Tauren"]="Таурени, що відчувають землю, добре знають легенди про Аґамаґґана й бачать у тому, як шипогриви оскверняють споріднених із ним звірів, ще одну ознаку гнилі, що вразила Пустки."},sec={{t="Утілення Великого Вепра",b="Шипогриви шанують усіх свиней як нащадків свого покровителя й праотця — бога Аґамаґґана. Для них вепри надзвичайного розміру й витривалості — пряме благословення від полеглого бога. Звір завбільшки з Аґателоса — а він удвічі вищий за громоящера з Пусток — має для племен Рейзорфен величезне духовне й обрядове значення."},{t="Зброя Мертвої Голови",b="Плем'я Мертвої Голови не вдовольнилося тим, щоб лишити Аґателоса просто священним символом, — воно перетворило його на бойову зброю. Силоміць згодовуючи йому отруйний кажанячий послід, зібраний зі склепінь печер Краула, доглядачі довели його до шаленого, нескінченного марення. Ця мерзенна суміш різко посилила витривалість і лють велетенського звіра, перетворивши його на нестримну навалу, що лише чекає, щоб її випустили на суперників племені."},{t="У кайданах",b="Аґателос цілком збожеволів від люті, тож навіть доглядачі не можуть пустити його вільно блукати Краулом. Його тримають у глухому тунелі за енергетичним бар'єром, який підтримують шамани й вартові шипогривів. Якщо загарбники прорвуться крізь бар'єр, вони зустрінуться зі звіром, що цілком здичавів від хімічного божевілля й стає ще страшнішим і могутнішим, коли його ранять."}},faq={{q="Чому Аґателос такий величезний?",a="Аґателос від природи велетенський вепр, і шипогриви шанують його як божественне благословення Аґамаґґана. Його неприродну масу й набряклу силу ще збільшило плем'я Мертвої Голови, згодовуючи йому сильнодійний кажанячий послід, щоб довести до стану здоровенного берсерка.",al={"чому аґателос великий","розмір аґателоса","гігантський вепр пустища"}},{q="Чому шипогриви тримають його за бар'єром?",a="Кажанячий послід, яким годували Аґателоса, довів його до цілковитого шаленства. Він не відрізняє друзів від ворогів, тож шипогриви-наглядачі мусять тримати його замкненим в укріпленому глухому куті за магічними полями, доки не будуть готові спрямувати його лють на ворогів.",al={"бар'єр аґателоса","чому аґателос у клітці","силове поле аґателоса"}},{q="Що пов'язує його з Аґамаґґаном?",a="Аґамаґґан — великий Древній вепр і праотець роду шипогривів. Через це шипогриви вважають усіх вепрів священними, а велетенських, як-от Аґателос, шанують як живе втілення й божественний дар нескінченного роду Аґамаґґана.",al={"аґателос аґамаґґан","чи аґателос бог","син аґамаґґана"}},{q="Яке плем'я створило Аґателоса?",a="Шипогриви Мертвої Голови — некромантська й фанатична каста всередині Рейзорфенів — спіймали й виростили Аґателоса. Вони збиралися випустити його як живий таран проти кожного, хто посміє кинути виклик їхній владі над Пустками.",al={"хто створив аґателоса","хто годує аґателоса","плем'я аґателоса"}},{q="Навіщо його годували кажанячим послідом?",a="Послід кажанів, що гніздяться в Рейзорфен Краулі, має властивості, які викликають видіння й доводять до безуму. Для Аґателоса він став збудником, що різко посилив його витривалість, лютість і нечутливість до болю ціною розуму.",al={"кажаний послід вепр","чому годувати послідом","послід кажанів краулів"}},{q="Чи можуть мисливці приборкати Аґателоса?",a="Ні. Аґателос — елітне, важкоброньоване чудовисько, чия лють надто глибоко вкорінена в божевіллі й темному чаклунстві, щоб підкоритися мисливцеві.",al={"приборкати аґателоса","чи можна приборкати аґателоса","мисливець аґателос"}}},fp="20,353,25.376.0,28.428.0,14.391.0,25.265.0,53.266.0,36.257.0,29.245.0,25.255.0,27.150.0"}
P.entries["npc:aggem-thorncurse"] = {n="Аґґем Торнкерс",ang={["faction:Horde"]="Шипогриви постійно загрожують Пусткам, тож знищення таких затятих захисників, як Аґґем Торнкерс, допомагає вберегти землі Дуротара й Малгору."},sec={{t="The Death's Head Prophet",b="Aggem guards a part of Razorfen Kraul occupied by the Death's Head tribe. His shamanic powers include summoning a boar spirit, reflecting the quilboar's reverence for Agamaggan."}},faq={{q="Хто такий Аґґем Торнкерс?",a="Aggem is a quilboar shaman and Death's Head Prophet in Razorfen Kraul.",al={"аґґем торнкерс","хто такий аґґем","аґґем краули"}},{q="Де знайти Аґґема Торнкерса?",a="He is found inside Razorfen Kraul in the southern Barrens.",al={"місце аґґема","де аґґем","де знайти аґґема торнкерса"}},{q="What spirit does Aggem call upon?",a="Aggem summons a boar spirit to fight beside him.",al={"aggem spirit","aggem boar spirit"}},{q="Як Аґґем б'ється?",a="Aggem uses shamanic magic and summons a boar spirit to fight beside him.",al={"aggem abilities","how does aggem fight"}},{q="Чи належить Аґґем Торнкерс до певного племені шипогривів?",a="He belongs to the Death's Head tribe.",al={"плем'я аґґема","яке плем'я аґґем","квілборги разорфену"}}},fp="16,154,24.177.0,24.70.0,36.58.0,33.48.0,31.72.0,62.37.0"}
P.entries["npc:ahanu"] = {n="Агану",s="Агану — таурен-торговець, що працює в Зброярні Геви на нижньому узвишші Тандер Блафа. Він виготовляє шкіряні обладунки й продає їх мандрівникам і молодим воїнам, які вирушають у мандри Малгором і широкими рівнинами. А ще він допомагає новоприбулим гінцям зорієнтуватися на кручах, коли ті приносять послання із сусідніх поселень.",h="Агану — таурен-торговець, що працює в Зброярні Геви на нижньому узвишші Тандер Блафа.",kw={"агану","зброярня геви","тандер блаф","шкіряні обладунки","торговець","джахан гоквінг","варґ віндвіспер"},ang={["race:Tauren"]="Для молодих воїнів-тауренів, що вперше вирушають у дорогу з Села Бладгуф, Агану пропонує і звичну гостинність, і необхідні в дорозі шкури."},sec={{t="Торговець зі Зброярні Геви",b="Серед шкіряних ятей і зброярень нижнього узвишшя Тандер Блафа Агану забезпечує необхідним спорядженням тих, хто заробляє на життя на луках Калімдору. Разом із товаришами, як-от Джахан Гоквінг і Варґ Віндвіспер, він уособлює звичайних ремісників і торговців, завдяки яким столиця тауренів завжди має міцне спорядження з вичиненої й дубленої шкіри. Для мандрівників, що щойно зійшли з вітрокрила з Перехрестя, Агану нерідко стає першим знайомим у великому місті: він приймає доставки й підказує гінцям дорогу до місцевих гніздовищ вітрокрилів."}},faq={{q="Хто такий Агану?",a="Агану — таурен-торговець, що живе на нижньому ярусі Тандер Блафа в Зброярні Геви. Він продає шкіряні обладунки й допомагає гінцям, які прибувають до столиці з Перехрестя.",al={"агану нпс","лор агану","хто такий агану"}},{q="Що продає Агану?",a="Він продає різні прості речі з вичиненої й дубленої шкіри — куртки, пояси, чоботи й наручі — для мисливців, розбійників і молодих шукачів пригод.",al={"товари агану","крам агану","торговець агану"}},{q="Де в Тандер Блафі його знайти?",a="Агану перебуває в Зброярні Геви на нижньому ярусі Тандер Блафа, поряд з іншими майстрами обладунків, шкірниками й зброярами.",al={"місце агану","де агану","агану на мапі"}},{q="Які завдання пов'язані з Агану?",a="Молодих шукачів пригод з Орди посилають до нього на вітрокрилі з вантажем у завданні «Політ до Тандер Блафа», а він потім відсилає їх назад до Тала, господаря вітрокрилів у місті.",al={"завдання агану","політ до тандер блафа агану"}}},fp="5,314,25.567.0,13.181.0,21.162.0,38.124.0,26.169.0"}
P.entries["npc:aku-mai"] = {n="Аку'май",s="Аку'май — потворна триголова гідра, що живе в затонулих руїнах Чорноглибинних Печер на Зорамському Узмор'ї. Просякнуту первісною тінню й обрану Древніми Богами, цю звірюку шанують як провісницю загибелі світу. Культ Молота Присмерку доглядає її в затопленому лігві, приносячи живі жертви, щоб угамувати її вічний голод.",h="Аку'май — потворна триголова гідра, що живе в затонулих руїнах Чорноглибинних Печер на Зорамському Узмор'ї.",kw={"аку'май","гідра","чорноглибинні печери","молот присмерку","древні боги","келріс"},ang={["class:Druid"]="Неприродна скверна Аку'май спотворює прибережні води Ашенвалю, і їх треба очистити, щоб повернути природну рівновагу.",["class:Priest"]="Мерзенна присутність Аку'май і Молота Присмерку — пряме осквернення Порожнечею, що суперечить ученню Святого Світла й Елуни.",["race:NightElf"]="Аку'май осквернила найглибше святилище зруйнованого храму, колись присвяченого місячній богині Елуні, перетворивши святе місце на яму для жертвоприношень."},sec={{t="Бич Зорамського Узмор'я",b="Задовго до того, як культисти заволоділи затонулим храмом під морем, Аку'май наводила жах на узбережжя Ашенвалю, наче жива пошесть на Зорамському Узмор'ї. Створіння глибоких вод і темніших сил, ця велетенська гідра несе у своїх трьох ненажерливих головах частку давньої злоби Древніх Богів. Аку'май — не звичайний мешканець припливів, а давній жах, що чатує в затоплених руїнах відтоді, як упав храм нічних ельфів на честь Елуни, і отруює води злобою, просякнутою Порожнечею."},{t="Улюблениця первісної темряви",b="Мерзенна аура Аку'май зрештою привабила Молот Присмерку глибоко в підземні печери. Вважаючи гідру помазаною улюбленицею й провісницею своїх грізних володарів, культ облаштував святилище довкола її гнізда. Сутінкового Володаря Келріса цілком поглинула ця істота: він переконаний, що, доглядаючи Аку'май і вдовольняючи її невситимий голод, наблизить повернення Древніх Богів і здобуде вічне життя. І культистів, і полонених регулярно кидають у ставок гідри, щоб живити її мерзенне зростання."}},faq={{q="Що таке Аку'май?",a="Аку'май — давня триголова гідра, насичена темною енергією Порожнечі. Колись улюблениця Древніх Богів, вона століттями наводить жах на Зорамське Узмор'я й затоплені зали Чорноглибинних Печер.",al={"хто такий аку'май","лор аку'май","що за монстр аку'май"}},{q="Де живе Аку'май?",a="Аку'май живе в найглибших затоплених гротах Чорноглибинних Печер — зруйнованого храмового комплексу, присвяченого Елуні, на узбережжі Зорамського Узмор'я на північному заході Ашенвалю.",al={"місце аку'май","де аку'май","де знайти аку'май"}},{q="Чому Молот Присмерку годує Аку'май?",a="Молот Присмерку вважає Аку'май посланницею й вісницею своїх господарів — Древніх Богів. На чолі із сутінковим володарем Келрісом культисти приносять живі жертви, щоб угамувати голод чудовиська, вірячи, що, годуючи його, наблизять повернення Древніх Богів і отримають темні благословення.",al={"чому культисти годують аку'май","келріс аку'май","молот присмерку аку'май"}},{q="Якою силою володіє Аку'май?",a="Окрім величезних розмірів і кількох голів, що клацають щелепами, Аку'май спрямовує енергію тіні й Порожнечі — дар Древніх Богів. Сама її присутність оскверняє довколишні води й насилає безум на тих, хто наближається.",al={"сили аку'май","чи аку'май магічна","гідра порожнечі"}},{q="Чи Аку'май — Древній Бог?",a="Ні. Аку'май не Древній Бог, а первісна гідра — їхня улюблениця й провідниця їхньої сили. Вона має лише крихітну частку їхньої давньої темної могутності, але й цього досить, щоб культисти їй поклонялися.",al={"чи аку'май древній бог","чи аку'май бог"}},{q="Чому шукачі пригод спускаються в глибини, щоб її вбити?",a="Якщо її не зупинити, нескінченний голод Аку'май і жертвоприношення культу можуть випустити згубне зло на Ашенваль і весь Калімдор. І Альянс, і Орда прагнуть покласти край Молоту Присмерку й убити жахіття, що чатує в серці храму.",al={"чому вбивати аку'май","чорноглибинні печери аку'май","загроза аку'май"}}},fp="7,364,27.512.0,32.537.1,16.214.0,24.185.0,45.286.0,33.211.0,22.200.0,53.271.0"}
P.entries["npc:alamar-grimm"] = {n="Аламар Грімм",s="Аламар Грімм — гном, наставник чорнокнижників, що служить в Анвілмарі в Долині Холодного Хребта. Озлоблений трагічною втратою Гномреґану, він не довіряє чужинцям і зосереджується на тому, щоб навчати новачків-чорнокнижників опановувати темні мистецтва й прикликати перших демонічних поплічників.",h="Аламар Грімм — гном, наставник чорнокнижників, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"аламар грімм","чорнокнижник","наставник","гном","анвілмар","гномреґан","біс","талісман з пера"},ang={["class:Warlock"]="Для гномів-чорнокнижників, що починають шлях у Долині Холодного Хребта, Грімм дає ваші найперші закляття й доручає довести свою вартість, щоб здобути першого поплічника-біса.",["race:Gnome"]="Грімм утілює тиху гіркоту вигнанців, які почуваються покинутими союзниками, поки Гномреґан лишається в руках трогів."},sec={{t="Озлоблений вигнанець",b="Поки більшість гномів у Долині Холодного Хребта спрямовують сили на відновлення й винахідництво, Аламар Грімм плекає глибоку образу через падіння Гномреґану. Він цинічно дивиться на звичайних шукачів пригод і навіть на дворфів-господарів з Айронфорджа, бурчачи, що союзникам більше залежить на дипломатії з людьми, ніж на поверненні полеглого техноміста. Працюючи з Анвілмара, він шукає споріднені душі, які розуміють: безжальна сила — можливо, саме те, чого насправді потребує його народ."},{t="Майстер темних мистецтв",b="Для молодих гномів, що ступають на шлях магії скверни, Грімм — перший провідник. Коли йому показують осквернений меморандум, він виявляє рідкісну теплоту й починає навчати новобранців базових заклять. Та перш ніж дати новачкові небезпечне знання, потрібне, щоб прив'язати демонічного біса, він вимагає доказу магічної та фізичної витривалості, посилаючи їх по дивні талісмани з пера, які носять місцеві новачки тролів Морозогривів."}},faq={{q="Хто такий Аламар Грімм?",a="Аламар Грімм — гном, наставник чорнокнижників в Анвілмарі в Долині Холодного Хребта. Він навчає гномів-чорнокнижників-початківців основ магії скверни й того, як викликати першого беса.",al={"аламар грімм","хто такий аламар","гномський вчитель чорнокнижників анвілмар"}},{q="Чому Аламар Грімм сердиться на дворфів?",a="Аламарові здається, що хоч дворфи Айронфорджа й прихистили гномів-вигнанців, насправді повернення Гномреґану для них не головне. Його обурює, що інтереси дворфів хиляться радше до союзу з людьми, ніж до визволення батьківщини його народу.",al={"чому аламар ненавидить дворфів","думка аламара про дворфів","чому сердитий"}},{q="Що Аламар Грімм доручає новим чорнокнижникам?",a="Щоб довести, що мають досить витривалості й магічної сили, аби керувати демоном, Грімм посилає новачків полювати на молодих тролів-Морозогривів і збирати їхні обереги з пір'я. З цими оберегами він випробовує новобранця, перш ніж навчити його ритуалу виклику беса.",al={"завдання аламара грімма біс","завдання талісманів з пера","талісмани морозогривів чорнокнижник"}}},fp="12,256,14.471.0,23.450.0,20.204.0,41.264.0,46.276.0"}
P.entries["npc:alanndarian-nightsong"] = {n="Аланндаріан Найтсонг",s="Аланндаріан Найтсонг — нічна ельфійка з Обердайна на Темному Узбережжі, яка присвятила себе догляду за знедоленими звірами краю. Разом із мандрівниками вона шукає ліки від пошестей, що вражають місцевих тварин, зокрема довгоступів і лісових створінь, осквернених темними силами.",h="Аланндаріан Найтсонг — нічна ельфійка з Обердайна на Темному Узбережжі, яка присвятила себе догляду за...",kw={"аланндаріан найтсонг","обердайн","довгоступи","ліки","звірі","темне узбережжя"},ang={["class:Druid"]="Друїди знайдуть споріднену душу в Аланндаріан, яка шукає отрути у воді й власноруч лікує отруєних створінь по всьому Темному Узбережжю.",["class:Hunter"]="Мисливці, що розуміють поведінку звірів, тісно співпрацюють з Аланндаріан, вистежуючи диких довгоступів і стривожену дичину.",["faction:Alliance"]="Аланндаріан — важлива помічниця для мандрівників Альянсу, що прибувають до Обердайна: вона допомагає новачкам зрозуміти, в якому крихкому стані перебуває дика природа північного Калімдору.",["race:NightElf"]="Її шана до лісу й відданість очищенню осквернених звірів відображають найглибші переконання калдореїв: природу треба берегти."},sec={{t="Доглядачка з Обердайна",b="Аланндаріан Найтсонг, що живе в приморському поселенні Обердайн, пильнує крихку природну рівновагу Темного Узбережжя. Таємнича скверна просочується в ґрунт і води, і створіння давніх лісів почали хворіти й ставати неприродно агресивними. Аланндаріан — охоронниця й дослідниця природи, що шукає дієвих засобів полегшити їхні страждання й повернути їм природну силу."},{t="Ліки для хворих звірів",b="Здебільшого Аланндаріан намагається з'ясувати першопричини недуг, що ширяться серед місцевих звірів. Ретельно збираючи рослинні інгредієнти й досліджуючи головні джерела води в краї, вона готує мазі й цілющі відвари. Вона просить мандрівних шукачів пригод нести ці ліки просто до хворих лісових створінь, щоб стримати скверну, перш ніж та остаточно поглине звірів Темного Узбережжя."}},faq={{q="Хто така Аланндаріан Найтсонг?",a="Аланндаріан Найтсонг — натуралістка з нічних ельфів у портовому містечку Обердайн на Темному Узбережжі. Вона доглядає уражених хворобою місцевих звірів і шукає трав'яні ліки від неприродних недуг, що мучать узбережжя.",al={"аланндаріан","хто така аланндаріан найтсонг","лор аланндаріан найтсонг"}},{q="Де знайти Аланндаріан Найтсонг?",a="Вона живе в Обердайні — головному поселенні нічних ельфів на туманному узбережжі Темного Узбережжя.",al={"місце аланндаріан","де аланндаріан","знайти аланндаріан найтсонг"}},{q="Що вона доручає шукачам пригод?",a="Аланндаріан просить шукачів пригод вистежити джерела хвороби, що вражає створінь Темного Узбережжя, зібрати в глушині важливі цілющі складники й напоїти ліками хворих звірів, як-от оленів і довгоступів.",al={"завдання аланндаріан","завдання хворих тварин обердайна","чого хоче аланндаріан"}},{q="Чи вона родичка інших Найтсонгів?",a="Прізвище пов'язує її з іншими відомими нічними ельфами з роду Найтсонгів, як-от Майстер Найтсонг у Дарнасусі чи Фалара Найтсонг, але щодня вона дбає передусім про дикі краї Темного Узбережжя.",al={"родина найтсонгів","зв'язок з майстром найтсонгом","фалара найтсонг"}},{q="Чому хворіють створіння на Темному Узбережжі?",a="Ліси й води Темного Узбережжя потерпають від повзучої скверни, що просочується з давніх руїн і від осквернених елементалів, доводячи місцевих звірів до божевілля й виснажливої хвороби.",al={"чому хворіють тварини темного узбережжя","зіпсовані довгоступи темного узбережжя","пошесть темного узбережжя"}},{q="Чи може вона навчити приручених високих довгоступів?",a="Подейкують, що вона чимало знає про довгоступів, але приручених звірів мисливців у полі не навчає: її турбота — дикі популяції.",al={"вчитель довгоступів","навчання довгоступа обердайн","навчити мого довгоступа"}}},fp="21,288,24.406.0,27.470.0,29.224.0,41.98.0,47.231.0,35.225.0,40.188.0,31.167.0"}
P.entries["npc:althea-ebonlocke"] = {n="Алтея Ебонлок",s="Командир Алтея Ебонлок очолює Нічну Варту — знесилену міську сторожу, що захищає Даркшир від жахів Сутінколісся. Родичка мера Елло Ебонлока, вона тримає оборону відрізаного краю, який покинуло регулярне військо Стормвінда. Вона організовує патрулі, доручає шукачам пригод винищувати місцевих потвор і дбає, щоб місто вистояло під безупинними нападами чудовиськ.",h="Командир Алтея Ебонлок очолює Нічну Варту — знесилену міську сторожу, що захищає Даркшир від жахів...",kw={"алтея ебонлок","нічна варта","даркшир","сутінколісся","командир","оборона"},ang={["class:Paladin"]="Паладини, що мандрують похмурими дорогами Сутінколісся, можуть допомогти Алтеї впокоїти неприкаяні душі й зняти частину духовного жаху, що гнітить її ополчення.",["class:Warrior"]="Воїни знайдуть в Алтеї суворого й практичного командира, що шанує бойову дисципліну й цінує бійців, готових тримати лінію проти переважних сил.",["faction:Alliance"]="Алтея — втілення похмурої рішучості забутих рубежів Альянсу: вона тримає королівство вкупі там, звідки пішли армії корони."},sec={{t="Командир Варти",b="Поки її родич, мер Елло Ебонлок, порядкує цивільними справами в ратуші, командир Алтея керує тонкою лінією оборони Даркшира. Коли Стормвінд так і не прислав королівських військ, щоб захистити Сутінколісся від повзучих жахів, містяни створили Нічну Варту. Під незмінно твердою рукою Алтеї ці добровольці патрулюють оповиті туманом дороги, не даючи скелетам-нежиті, лютим вовкам і павукам прорватися до міста."},{t="Місто на краю прірви",b="Алтея прагматична й знає межі свого ополчення. Її загону бракує людей, і він постійно втрачає новобранців, тож вона охоче наймає перехожих найманців і мандрівників, щоб проріджувати загрози біля самого порога Даркшира. Вона спрямовує походи проти гулів і скелетів на тихих і скорботних лісових цвинтарях, водночас пильно прислухаючись до темніших чуток із лісової гущавини."},{t="Трагедії лісу",b="Окрім звичайної лісової наволочі, Алтея керує розслідуванням і знищенням найстрашніших лих Сутінколісся. Вона допомагає розплутати похмуру долю Сталвана Містмантла й шукає відповідей на неспокійні блукання Мор'Ладіма — полеглого лицаря Моргана Ладімора. А коли Аберкромбі випускає на головну дорогу жахливу потвору Стітчеса, саме Алтея скликає Варту на відчайдушний останній бій за Даркшир."}},faq={{q="Хто така Алтея Ебонлок?",a="Командир Алтея Ебонлок очолює Нічну Варту — міське ополчення Даркширу в Сутінколіссі. Вона відповідає за оборону краю від нежиті та звірів, що чатують у тінях.",al={"хто така алтея","командир ебонлок","хто командир нічної варти"}},{q="Що таке Нічна Варта?",a="Нічна Варта — добровольче ополчення, яке зібрали жителі Даркширу. Стормвінд майже не надає Сутінколіссю військової підтримки, тож місцеві об'єдналися під проводом Алтеї, щоб патрулювати дороги й давати відсіч жахіттям лісу.",al={"що таке нічна варта","хто нічна варта","міліція даркшира"}},{q="Ким Алтея доводиться мерові Елло Ебонлоку?",a="Алтея — родичка Лорда Елло Ебонлока, мера Даркширу. Мер керує справами містечка з ратуші, а Алтея командує ополченням у полі.",al={"родич елло ебонлока","чи алтея дочка елло","родина алтеї"}},{q="Чому Стормвінд не допомагає Алтеї захищати Даркшир?",a="Король Варіан Рінн зник, сили Стормвінда напружені до краю, і Дім Вельмож здебільшого занедбав віддалені землі королівства. Даркшир майже не отримує ні солдатів, ні допомоги, тож Алтея мусить покладатися на місцевих добровольців і вільних шукачів пригод.",al={"чому стормвінд не допомагає","вартові стормвінда сутінколісся","де солдати"}},{q="Які завдання дає Командир Алтея?",a="Алтея дає основний ланцюжок завдань Нічної Варти, посилаючи шукачів пригод полювати на вовків, скелетів-виродків і гулів по всьому Сутінколіссю. Вона також допомагає розслідувати «Легенду про Сталвана» й упоратися з мандрівним жахіттям Мор'Ладімом.",al={"завдання алтеї","лінійка завдань нічної варти"}},{q="Що робить Алтея, коли Стітчес нападає на Даркшир?",a="Коли зшита гидота, створена Аберкромбі, рушає на Даркшир, Алтея б'є на сполох і веде вцілілих вартових Нічної Варти в запеклий, кривавий бій, щоб зупинити чудовисько, перш ніж воно ввійде на міську площу.",al={"алтея стітчес","хто б'ється зі стітчесом","напад на даркшир"}}},fp="16,395,22.466.0,19.393.0,21.423.1,24.219.0,24.274.0,46.167.0,53.265.0,40.235.0,52.228.1"}
P.entries["npc:altsoba-ragetotem"] = {n="Алтсоба Рейджтотем",s="Алтсоба Рейджтотем — таурен-зброяр, що служить на Заставі Кривавої Отрути в Скверноліссі. На цій віддаленій заставі Орди він забезпечує героїв, що проходять повз, надійними булавами, посохами й сокирами, щоб ті могли протистояти зачумленим жахіттям лісу.",h="Алтсоба Рейджтотем — таурен-зброяр, що служить на Заставі Кривавої Отрути в Скверноліссі.",kw={"алтсоба рейджтотем","таурен","зброяр","застава кривавої отрути","сквернолісся","орда"},ang={["faction:Horde"]="Алтсоба постачає необхідне бойове спорядження загонам Орди, які тримають позиції в одному з найбільш осквернених країв Калімдору.",["race:Tauren"]="Як член племені Рейджтотем, Алтсоба приносить традиційну тауренську незламність у край, що тяжко страждає від демонічної зарази."},sec={{t="Бронник Застави Кривавої Отрути",b="Застава Кривавої Отрути — небезпечне місце в самому серці Сквернолісся, посеред демонічної скверни й зараженої звірини. Підтримувати тут постачання — сувора необхідність, і Алтсоба Рейджтотем робить свою частку, споряджаючи розвідників і мандрівників Орди. Чи потрібна комусь міцна сокира-півмісяць, чи важкий бойовий молот, Алтсоба дбає, щоб воїни, які вирушають у сплюндровані ліси, не йшли в бій беззбройними."}},faq={{q="Хто такий Алтсоба Рейджтотем?",a="Алтсоба Рейджтотем — таурен-торговець із Застави Кривавої Отрути, табору Орди в Скверноліссі. Він продає просту важку зброю мандрівникам і захисникам, що наважуються ступити в отруєну долину.",al={"хто такий алтсоба","алтсоба рейджтотем","таурен біля застави кривавої отрути"}},{q="Що продає Алтсоба?",a="Він продає різну звичайну зброю ближнього бою — бойові палиці, моргенштерни, бойові молоти й сокири, — надійну сталь для шукачів пригод, що вирушають у глиб Сквернолісся.",al={"товари алтсоби","предмети торговця алтсоби","яку зброю продає алтсоба"}},{q="Де знайти Алтсобу Рейджтотема?",a="Він відпочиває в Заставі Кривавої Отрути, що примостилася на кручах над смердючими водами й опоганеними галявинами Сквернолісся.",al={"місце алтсоби","де алтсоба","торговець застави кривавої отрути"}}},fp="17,229,26.419.0,25.188.0,23.177.0,35.131.0"}
P.entries["npc:alyissia"] = {n="Алііссія",s="Алііссія — калдорейська наставниця воїнів, що перебуває в порожнистому вітті Алдрассила в Тінедолі. Вона навчає щойно пробуджених воїнів — нічних ельфів основ бойового мистецтва, допомагаючи їм приборкати сиру силу й дисципліну для захисту їхнього молодого світового дерева.",h="Алііссія — калдорейська наставниця воїнів, що перебуває в порожнистому вітті Алдрассила в Тінедолі.",kw={"алііссія","воїн","наставниця","алдрассил","тінедол","тельдрассил","калдореї"},ang={["class:Warrior"]="Для молодих воїнів — нічних ельфів Алііссія — найперша наставниця, що дає ранню науку стійок і бойової дисципліни, перш ніж вони заглибляться в нетрі Тельдрассила.",["race:NightElf"]="Алііссія уособлює бойову дисципліну передової калдореїв і готує захисників боронити коріння Алдрассила від скверни."},sec={{t="Бойова наставниця Тінедолу",b="У затишному прихистку Алдрассила Алііссія навчає молодих нічних ельфів, яких вабить шлях криці й щита, а не магії природи чи жрецтва. Хоч військо калдореїв здавна славиться Вартовими й потайними лучниками, небезпечне становище сьогоднішнього Калімдору потребує рішучих бійців передової. Алііссія викладає основи, щоб свіжі новобранці вміли спрямовувати бойову лють, опановували стійки й витримували натиск напасливої звірини та споганених ґреллів, що зазіхають на Тінедол."}},faq={{q="Хто така Алііссія?",a="Алііссія — наставниця воїнів із нічних ельфів в Алдрассилі, головному святилищі Тінедолу. Вона дає перші настанови, навчання й прості бойові вправи молодим воїнам, що починають свій шлях на Тельдрассилі.",al={"хто така алііссія","алііссія нпс","чим займається алііссія"}},{q="Де знайти Алііссію?",a="Вона стоїть на нижньому ярусі у великому порожнистому стовбурі Алдрассила в самому серці Тінедолу на Тельдрассилі.",al={"місце алііссії","де алііссія","знайти алііссію"}},{q="Які завдання дає Алііссія?",a="Alyissia receives the Simple Sigil carried by new night elf warriors. It introduces them to her as their warrior trainer in Aldrassil.",al={"завдання алііссії","завдання від алііссії"}}},fp="8,270,28.560.0,16.229.0,26.131.0,32.134.0"}
P.entries["npc:amber-kearnen"] = {n="Ембер Кірнен",s="Ембер Кірнен — пильна агентка SI:7, що несе службу в самому серці Вестфолу. Зі свого прихованого спостережного пункту над рівнинами вона стежить за незаконними справами Братства Дефіас на доручення Майстра Матіаса Шоу.",h="Ембер Кірнен — пильна агентка SI:7, що несе службу в самому серці Вестфолу.",kw={"ембер кірнен","агент кірнен","si:7","клавен мортвейк","вестфол","братство дефіас"},ang={["class:Rogue"]="Для розбійників Альянсу, що доводять свою майстерність, Агент Кірнен — ваш головний зв'язковий у полі, який допомагає злагодити проникнення до Вежі Клавена.",["faction:Alliance"]="Кірнен уособлює дієве таємне крило Стормвінда, що діє в тилу ворога у Вестфолі, підриваючи Братство Дефіас і не сполохуючи населення."},sec={{t="Очі на вежі",b="Агентка SI:7 Ембер Кірнен — одна з польових розвідниць Стормвінда. Замість того щоб ходити залами Фортеці Стормвінда, вона працює під відкритим небом Вестфолу, наглядаючи за покинутою сторожовою вежею, яку захопило Братство Дефіас. Під безпосереднім проводом Майстра Матіаса Шоу Кірнен стежить за ситуацією й інструктує таємних агентів, яких посилають знешкоджувати загрози від Дефіас і збирати відомості в краї, за який точиться боротьба."},{t="Смертельно небезпечне доручення",b="Її пильність зосереджена на Клавенові Мортвейку — члені Братства Дефіас, що засів у сторожовій вежі на південний схід від Сентінел Гілл. Тижнями стежачи за вежею, Кірнен розповідає розбійникам-лазутчикам про дивних нелюдських вартових, що прибули з вантажем із Сутінколісся, і посилає їх викрасти ключ від вежі, пробратися всередину й дізнатися, що в скрині із Сутінколісся, — зокрема забрати щоденник Клавена. Її терплячість і ретельні записи роблять її незамінною для таємних операцій Корони проти Дефіас."}},faq={{q="Хто така Ембер Кірнен?",a="Ембер Кірнен — агентка SI:7, елітної розвідувальної служби Стормвінда. Вона працює польовим агентом і розвідницею, а нині стежить за діями Дефіасу у Вестфолі.",al={"ембер кірнен","хто такий кірнен","агент кірнен"}},{q="Де знайти Ембер Кірнен?",a="Вона перебуває в диких краях Вестфолу й пильнує покинуту дозорну вежу Альянсу, яку захопило Братство Дефіас.",al={"місце ембер кірнен","де кірнен","де ембер кірнен"}},{q="Що пов'язує її з Матіасом Шоу?",a="Вона підзвітна безпосередньо Майстрові Матіасу Шоу, очільникові SI:7. Шоу посилає до неї у Вестфол інших агентів, щоб вона розповіла їм про дії Дефіасу там.",al={"кірнен матіас шоу","на кого працює кірнен"}},{q="Яку роль вона відіграє в завданні «Вежа Клавена»?",a="Кірнен стежить за дозорною вежею, яку тримає Клавен Мортвейк. Вона інструктує розбійників Альянсу, яких посилає SI:7, і дає їм тактичні вказівки, щоб прослизнути всередину, оминути вартових Дефіасу й викрасти щоденник Клавена.",al={"вежа клавена","ембер кірнен вежа клавена","що вона робить у вежі"}}},fp="13,228,17.463.0,19.502.1,21.180.0,33.132.0,39.149.0,42.212.0"}
P.entries["npc:anastasia-hartwell"] = {n="Анастасія Гартвелл",s="Анастасія Гартвелл — відома наставниця магів із Відступників, що живе в Магічному Кварталі Андерсіті. Вона допомагає молодим і досвідченішим заклиначам опановувати чародійне мистецтво й керує важливими магічними дослідженнями та виправами по всьому Лордерона й поза ним.",h="Анастасія Гартвелл — відома наставниця магів із Відступників, що живе в Магічному Кварталі Андерсіті.",kw={"анастасія гартвелл","маг","андерсіті","магічний квартал","відступники","тірісфаль"},ang={["class:Mage"]="Анастасія Гартвелл — незамінна наставниця для магів Орди в Андерсіті: вона навчає вищих рангів заклять і дає важливі класові завдання.",["faction:Horde"]="Завдяки співпраці з наставниками, як-от Дейно в Оргріммарі, Анастасія поєднує чародійну спадщину Лордерона з ширшими магічними починаннями Орди.",["race:Undead"]="Вона уособлює тяглість славетних чародійних традицій Даларана й Лордерона серед Відступників, збережених навіть крізь трагедію нежиття."},sec={{t="Чародійна майстерність серед руїн",b="У темних, відлунних покоях Магічного Кварталу Андерсіті Анастасія Гартвелл навчає магів Відступників і Орди спрямовувати чародійну енергію. Хоч королівство Лордерон лежить у руїнах, колишні люди-чародії, як-от Анастасія, зберегли свої вчені традиції й після смерті. Вона наполягає, що магія вимагає суворої дисципліни, і застерігає кожного зустрічного мандрівника: необачні закляття швидко поглинуть невмілого."},{t="Польові дослідження й реліквії",b="Окрім основ заклять, Анастасія скеровує здібних учнів на важливі польові розвідки. Вона посилає магів до Галявин Тірісфалю — зокрема на сплюндровані землі Хутора Балнірів і до зруйнованих алхімічних майстерень, — щоб повернути втрачені реагенти й урятувати рештки забутих чародійних знань. Виконуючи її доручення, учні переконуються: щоб здобути магічну перевагу, треба не боятися небезпечних руїн своєї колишньої батьківщини."},{t="Союзники по ремеслу",b="Зв'язки Анастасії сягають далеко за межі Тірісфалю. Коли заклиначі Орди набираються вправності, вона узгоджує їхнє навчання з наставниками в далеких краях, як-от Дейно в Оргріммарі, і скеровує досвідчених учнів до відлюдних майстрів, як-от Табета в болотах Багна Пилоброду. Завдяки її проводу маги Відступників лишаються вплетеними в ширше полотно магічних пошуків Орди."}},faq={{q="Хто така Анастасія Гартвелл?",a="Анастасія Гартвелл — наставниця магів із Відступників у Магічному Кварталі Андерсіті. Вона навчає заклять молодих магів і дає особливі доручення: розшукувати тайні артефакти й реагенти по всьому Лордерону.",al={"анастасія гартвелл","хто така анастасія","гартвелл андерсіт"}},{q="Де знайти Анастасію Гартвелл?",a="Вона перебуває в Магічному Кварталі Андерсіті серед інших знавців тайної магії й наставників під склепінчастими підземними стелями міста.",al={"місце анастасії гартвелл","де анастасія гартвелл","вчитель магів андерсіту місце"}},{q="Що Анастасія каже тим, хто не є магом?",a="Відвідувачам, що не є магами, вона радить обережність: застерігає, щоб під час мандрів світом вони остерігалися магії, бо та охоче обпікає необізнаних.",al={"плітки анастасії","діалог анастасії","порада гартвелл"}},{q="Які завдання дає Анастасія Гартвелл?",a="Анастасія дає магам різні навчальні доручення: обстежити Хутір Балнірів, пошукати припаси у зруйнованих алхімічних крамницях і зв'язатися з далекими наставниками — Дейно в Оргріммарі й Табетою в Багні Пилоброду.",al={"завдання анастасії","завдання гартвелл","завдання магів андерсіту"}},{q="Чи родичка Анастасія Гартвелл інших Гартвеллів із Тірісфалю?",a="Вона має те саме прізвище, що й Ендрю Гартвелл і Джеффрі Гартвелл, але чи вони родичі, невідомо.",al={"родина гартвеллів","ендрю гартвелл","джеффрі гартвелл"}},{q="Навіщо Анастасія посилає магів на Хутір Балнірів?",a="Вона просить магів зібрати Ротики Балніра, щоб оцінити, як шириться чума на Галявинах Тірісфалю, і передати квіти аптекарям.",al={"завдання хутір балнірів","чому хутір балнірів","гартвелл балнір"}}},fp="18,265,27.449.0,25.445.0,19.409.0,26.228.0,36.156.0,37.159.0,42.244.0,61.110.0,54.148.0"}
P.entries["npc:andron-gant"] = {n="Андрон Ґант",s="Андрон Ґант — відлюдькуватий Відступник, що частенько буває напідпитку й живе в каламутних глибинах Апотекаріуму в Андерсіті. Час від часу він бере дослідницькі замовлення й шукає реліквії для місцевих учених.",h="Андрон Ґант — відлюдькуватий Відступник, що частенько буває напідпитку й живе в каламутних глибинах...",kw={"андрон ґант","синдикат","скрадачі смерті","астор гадрен","варіматрас","аптекаріум","скрижаль маркрі"},ang={["class:Rogue"]="Розбійники-Відступники, що піднімаються в лавах скрадачів смерті, на прикладі Ґанта на власні очі бачать, як пияцтво й безтурботність можуть розплутати навіть найретельніше шпигунське плетиво.",["race:Undead"]="Ґант — суворе нагадування про те, що вірність серед Відступників ніколи не гарантована, а людські злочинні угруповання на кшталт Синдикату мають очі навіть у катакомбах Лордерона."},sec={{t="Інформатор, що заплітається язиком",b="Розвалившись серед отруйних випарів Апотекаріуму, Андрон Ґант рідко виходить за безпечні кам'яні мури Андерсіті. Сторонньому оку він здається просто п'яним ученим, який зрідка наймає відчайдушних гінців, щоб ті принесли з далеких берегів якусь маловідому реліквію, як-от Скрижаль Маркрі, для місцевих магів."},{t="Викритий скрадачами смерті",b="Зрадницькі оборудки Ґанта не сховалися від розвідувальної мережі Андерсіті. Коли Синдикат відрядив гінця на ім'я Астор Гадрен забрати гросбух із викраденими відомостями, молоді агенти скрадачів смерті перехопили посланця. Перевдягнений Гадреном, агент зумів ошукати п'яного Ґанта, і той, оком не моргнувши, віддав свій викривальний гросбух — а з ним лорд Варіматрас отримав незаперечний доказ зради Ґанта супроти Відступників."}},faq={{q="Де знайти Андрона Ґанта?",a="Андрон Ґант перебуває в Андерсіті — на нижніх ярусах кварталу Апотекаріуму.",al={"місце андрона ґанта","де андрон ґант","ґант місце андерсіт"}},{q="Чому Андрона Ґанта цікавлять скрижалі з Азшари?",a="Ґант — посередник для певних магів Андерсіті: він платить мародерам і зв'язковим, як-от Джедіґа, щоб ті добували давні реліквії з руїн Азшари.",al={"андрон ґант азшара","скрижаль маркрі андрон ґант","чому ґант хоче скрижалі"}},{q="Чому скрадачі смерті розслідують справи Андрона Ґанта?",a="Скрадачі смерті розслідують його зв'язки з людьми ззовні й збирають відомості про дослідження, які він замовляє.",al={"розслідування ґанта","контакти андрона ґанта","на кого працює андрон ґант"}},{q="Хто керує розслідуванням щодо Андрона Ґанта?",a="Скрадачі смерті стежать за Ґантом за дорученням Лорда Варіматраса, збираючи відомості про його зв'язки й дослідження.",al={"хто розслідує андрона ґанта","скрадачі смерті андрон ґант","варіматрас андрон ґант"}}},fp="11,208,20.349.0,29.477.1,29.104.0,49.168.0,49.118.1,47.119.1"}
P.entries["npc:anduin-wrynn"] = {n="Андуїн Рінн",s="Андуїн Ллейн Рінн — десятирічний коронований Король Стормвінда, що править за відсутності свого зниклого батька, короля Варіана Рінна. Через юний вік справжнє врядування королівством лежить у руках Верховного Лорда Болвара Фордрагона й королівського двору.",h="Андуїн Ллейн Рінн — десятирічний коронований Король Стормвінда, що править за відсутності свого зниклого...",kw={"андуїн рінн","король стормвінда","варіан рінн","болвар фордрагон","катрана престор","стормвінд"},ang={["faction:Alliance"]="Для громадян і вояків Альянсу король Андуїн — невинний символ стійкості королівства, хоча чимало хто непокоїться, що через його юність трон беззахисний перед темними двірськими інтригами.",["race:Human"]="Для людей Стормвінда хлопчик-король — запорука того, що династія Ріннів живе: він несе пам'ять про загиблу матір Тіффін і зниклого батька Варіана."},sec={{t="Хлопчик на троні",b="Принц Андуїн народився в мирний проміжок після Другої війни, і його назвали на честь діда, короля Ллейна, і легендарного лицаря сера Андуїна Лотара. Після смерті його матері, королеви Тіффін, і загадкового зникнення батька дорогою на дипломатичну зустріч у Тераморі дитину раптово коронували, щоб зберегти спокій у королівстві. Хоч десятирічний монарх розумний і чуйний не на свої роки, він майже не має голосу в державних справах, а влада в королівстві поділена між Верховним Лордом Болваром Фордрагоном і королівською радницею Леді Катраною Престор."},{t="Пішак при дворі",b="У позолочених стінах Фортеці Стормвінда юного Андуїна оточує дедалі гостріша політична напруга. Верховний Лорд Болвар опікується військовою обороною й силкується зберегти цілісність королівства, а шляхтянка Катрана Престор безупинно нашіптує двору свої поради й навмисно зриває відправлення військ до віддалених людських поселень. Андуїн відчуває, як хитко все при його дворі, і дуже сумує за батьком, але поки що лишається лише символом влади серед підступних вельмож і пильних охоронців."}},faq={{q="Чому Стормвіндом править дитина?",a="Король Варіан Рінн за загадкових обставин зник дорогою на дипломатичну зустріч у Тераморі. Щоб уникнути кризи престолонаслідування й зберегти лад у королівстві, десятирічного принца Андуїна офіційно коронували, а правити замість нього регентом призначили Верховного Лорда Болвара Фордрагона.",al={"чому андуїн король","де варіан","хто дитина-король"}},{q="Хто насправді зараз керує королівством?",a="Верховний Лорд Болвар Фордрагон — регент Стормвінда: він командує військами королівства й має найвищу виконавчу владу, доки Андуїн не досягне повноліття. Проте шляхтянка Леді Катрана Престор — старша радниця, що має чималий вплив на королівський двір і Дім Вельмож.",al={"хто править стормвіндом","хто за головного","регент стормвінда"}},{q="На честь кого названо Андуїна?",a="Його названо на честь двох героїв історії Стормвінда: діда, полеглого Короля Ллейна Рінна, і сера Андуїна Лотара, Лева Азероту, що вів Альянс у Першій і Другій війнах.",al={"походження імені андуїна","на честь кого андуїн","чому названий андуїном"}},{q="Де в місті знайти Андуїна?",a="Короля Андуїна можна знайти в тронній залі Фортеці Стормвінда: він сидить на королівському троні, а обабіч нього — Верховний Лорд Болвар Фордрагон і Леді Катрана Престор.",al={"де андуїн","місце андуїна","місце андуїна рінна"}}},fp="12,261,19.614.0,19.525.0,32.303.0,40.300.0,26.196.0,36.160.0"}
P.entries["npc:apothecary-helbrim"] = {n="Аптекар Гелбрім",s="Аптекар Гелбрім — посланець Королівського Аптекарського Товариства, що несе службу в запорошеному серці Перехрестя. Його відправили аж до Калімдору збирати незнайомі реагенти, і він вивчає місцеву флору й дивну природу Пусток на користь Відступників.",h="Аптекар Гелбрім — посланець Королівського Аптекарського Товариства, що несе службу в запорошеному серці...",kw={"аптекар гелбрім","королівське аптекарське товариство","відступники","перехрестя","спори","андерсіті"},ang={["faction:Horde"]="Хоч Гелбрім служить пліч-о-пліч з оркськими вартовими й тауренськими мандрівниками, його невтомна одержимість спорами й отрутами змушує навіть союзників трохи нервуватися.",["race:Undead"]="Гелбрім — практичний внесок вашого народу в справи Орди на заході: він перетворює дику природу Калімдору на сировину для безупинних досліджень Товариства."},sec={{t="Аптекар серед пилу",b="Більшість Королівського Аптекарського Товариства сидить у вогких підземеллях Андерсіті, а Гелбрім працює під пекучим сонцем на висохлій червоній землі Перехрестя. Його послали далеко за Велике море, до Калімдору, і його доручення просте, але вкрай важливе: знаходити й добувати корисні рослини, гриби та природні зразки в Пустках. Для цього він покладається на мандрівних шукачів пригод, які збирають для нього зразки, як-от спори місцевих грибів, і підтримує прямий зв'язок зі своєю колегою, Аптекаркою Замах у Тандер Блафі. Сама його присутність нагадує мандрівникам, що руки алхіміків Сильвани сягають далеко за зруйновані кордони Лордерону."}},faq={{q="Хто такий Аптекар Гелбрім?",a="Гелбрім — алхімік-Відступник і агент Королівського Аптекарського Товариства. Він стоїть на Перехресті, щоб збирати й досліджувати особливі природні реагенти Пусток.",al={"хто такий гелбрім","лор гелбріма","аптекар перехрестя"}},{q="Чому аптекар-Відступник стоїть у Пустках?",a="Королівське Аптекарське Товариство постійно шукає нові речовини, отрути й реагенти для своїх алхімічних досліджень. Гелбріма відправили до центрального Калімдору вивчати місцеві зразки, як-от дивні спори грибів, що проростають по всій савані й не мають відповідників на спустошених чумою землях Лордерона.",al={"чому він на перехресті","що гелбрім тут робить","чому відступники в пустищі"}},{q="Що він робить зі спорами грибів, які йому приносять?",a="Гелбрім досліджує спори, щоб визначити їхню отруйність, лікувальну цінність і біохімічні властивості. Часто він пакує ці зразки й посилає гінців доставити їх Аптекарці Замах у Тандер Блаф для подальших алхімічних дослідів.",al={"спори гриба гелбрім","для чого спори","завдання грибних спор"}},{q="З ким працює Гелбрім?",a="Гелбрім підзвітний Королівському Аптекарському Товариству з Андерсіті. У Калімдорі він працює просто з Аптекаркою Замах біля Ставків Видінь у Тандер Блафі, а іноді веде справи через гоблінів-посередників, як-от Начальник Пристані Діззівіг у Раджеті.",al={"союзники гелбріма","кому підпорядковується гелбрім"}}},fp="18,264,22.646.0,26.184.0,54.317.0,57.252.0,27.274.0"}
P.entries["npc:apothecary-johaan"] = {n="Аптекар Йогаан",s="Аптекар Йогаан — алхімік і дослідник Королівського Аптекарського Товариства в Бріллі. За дорученням свого ордену та Леді Сильвани він проводить смертельні досліди над місцевою флорою та фауною, розробляючи нову чуму Відступників.",h="Аптекар Йогаан — алхімік і дослідник Королівського Аптекарського Товариства в Бріллі.",kw={"аптекар йогаан","алхімік","королівське аптекарське товариство","брілл","нова чума","відступники","тірісфаль"},ang={["faction:Horde"]="Хоч орки й таурени можуть сахатися алхімічних пошестей, смертоносні суміші Йогаана служать стратегічній безпеці плацдарму Орди в Східних Королівствах.",["race:Undead"]="Дослідження Йогаана — осердя справи Відступників: він розробляє саме ту зброю, що потрібна, щоб вибороти постійну батьківщину, вільну від Погибелі й загроз з боку живих."},sec={{t="Слуга Товариства",b="Відкрито працюючи в поселенні Відступників Брілл у Галявинах Тірісфалю, Аптекар Йогаан утілює наукові амбіції новоствореного Королівського Аптекарського Товариства. Як і його колеги по всьому Лордерону, Йогаан діє за прямим наказом — створювати біологічну й алхімічну зброю, здатну убезпечити хистке майбутнє Відступників і від живих, і від Погибелі."},{t="Варіння Нової Чуми",b="Йогаан керує першими польовими випробуваннями того, що Товариство називає «Новою Чумою». З сировини, зібраної з зіпсутої живності Тірісфалю та хворих посівів — як-от сутінь-зілля й отруєний ґрунт сусідніх хуторів, — він випробовує суміші отрут і оцінює їхню силу на живих піддослідних, а тоді відсилає результати на південь, у Срібнолісся."}},faq={{q="Хто такий Аптекар Йогаан?",a="Аптекар Йогаан — дослідник-алхімік, що працює в Бріллі. Він належить до Королівського Аптекарського Товариства й посилає молодих звитяжців-Відступників збирати мерзенні реагенти по всіх Галявинах Тірісфалю.",al={"аптекар йогаан","хто такий йогаан","йогаан брилл"}},{q="Де знайти Аптекаря Йогаана?",a="Він стоїть просто неба біля шибениці й алхімічного приладдя в містечку Брілл, трохи на північ від Андерсіті на Галявинах Тірісфалю.",al={"місце йогаана","де йогаан","знайти йогаана"}},{q="Над чим працює Йогаан?",a="Йогаан розробляє й удосконалює ранні штами Нової Чуми, випробовуючи біологічні збудники й отруйні витяжки з уражених полів і звірів Тірісфалю.",al={"досліди йогаана","що робить йогаан","чума йогаана"}},{q="Що він робить зі зразками чуми?",a="Коли дослідні суміші зварено й перевірено, наскільки вони смертоносні, Йогаан пакує зразки й посилає гінців доставити їх союзним аптекарям у Срібнолісся.",al={"доставка в сільверпайн","куди йдуть зразки чуми"}},{q="До якої організації належить Йогаан?",a="Він діяльний член Королівського Аптекарського Товариства — алхімічної гільдії, що служить Леді Сильвані Віндраннер і Відступникам в Андерсіті.",al={"фракція йогаана","на кого працює йогаан"}},{q="Чому його цікавлять місцеві ферми?",a="На людських фермах, як-от Хутір Соллідена, і на сусідніх гарбузових грядках ростуть гриби й уражені посіви — ключова хімічна сировина для його дослідних отрут.",al={"поля скорботи йогаан","чому слати на ферми"}}},fp="17,233,24.383.0,22.368.1,25.193.0,35.144.0,26.159.0,40.180.0,40.144.0,40.178.0"}
P.entries["npc:apothecary-renferrel"] = {n="Аптекар Ренферрел",s="Аптекар Ренферрел — знаний член Королівського Аптекарського Товариства, що працює в Гробниці в Срібноліссі. Йому доручено просувати алхімічні справи Відступників, і він керує широкими польовими дослідженнями осквернених звірів краю та загроз нежиті. Мандрівники Срібноліссям часто допомагають йому збирати неспокійні інгредієнти й розслідувати небезпечні рештки Погибелі.",h="Аптекар Ренферрел — знаний член Королівського Аптекарського Товариства, що працює в Гробниці в Срібноліссі.",kw={"аптекар ренферрел","королівське аптекарське товариство","гробниця","гнилошкірі гноли","тул рейвенклов","срібнолісся"},ang={["faction:Horde"]="Хоч орків і тауренів може відвертати моторошна природа його біологічних дослідів, розвідка Ренферрела проти Погибелі допомагає вберегти землі Орди від вторгнень із півночі.",["race:Undead"]="Ренферрел уособлює прагматичне, безжальне мислення Відступників, що прагнуть вижити: він обертає місцеві рослини й тварин Лордерона на зброю, щоб збудувати безпечне майбутнє для вільної нежиті."},sec={{t="Алхімік Гробниці",b="Ренферрел, що працює в Гробниці, — один із головних польових дослідників Королівського Аптекарського Товариства в Срібноліссі. Поки в Андерсіті містяться великі лабораторії й найвищий провід товариства, Ренферрел виконує практичну, брудну роботу: здобуває місцеві біологічні зразки, вдосконалює могутні зілля й вивчає похмуру природу західного прикордоння Лордерона."},{t="Розслідування гнилошкірих і Погибелі",b="Ренферрел спрямовує чимало сил на гнилошкірих гнолів і некерованих мерців, що заполонили край. Досліджуючи зразки крові й тканин, він намагається зрозуміти, як досі діє дотик чуми й некромантичні сили, що тримають місцевих потвор. Його розслідування зводять його в пряме протистояння з Тулом Рейвенкловом — могутнім некромантом Погибелі, що діє поблизу руїн на Острові Фенріс."}},faq={{q="Хто такий Аптекар Ренферрел?",a="Аптекар Ренферрел — алхімік Королівського Аптекарського Товариства, що працює в Гробниці, головній заставі Відступників у Срібноліссі. Він вивчає місцевих звірів, різновиди чуми й ворожі сили, щоб варити зілля й утримувати край для Королеви Сильвани.",al={"ренферрел","хто такий ренферрел","лор аптекаря ренферрела"}},{q="Що Ренферрел досліджує в Срібноліссі?",a="Він зосереджений на створенні нових чум і отруйних сумішей — того, що загалом зветься «Рецептом Смерті». Він доручає шукачам пригод збирати серця ведмедів-грізлі, іхор гнилошкірих гнолів та інші біологічні складники, щоб випробовувати й удосконалювати смертоносні зілля.",al={"дослідження ренферрела","досліди ренферрела","рецепт смерті"}},{q="Що пов'язує його з гнилошкірими гнолами?",a="Renferrel studies the Rot Hide gnolls' corrupted ichor. His initial tests detect warlock and necromantic magic, so he sends a sample to Bethor Iceshard in Undercity for further study.",al={"сукровиця гнилошкірих","походження гнилошкірих","гноли сільверпайну"}},{q="Чому Ренферрел полює на Тула Рейвенклова?",a="Renferrel investigates the magic behind the Rot Hide gnolls and seeks Bethor Iceshard's help in identifying its source. The investigation leads toward the threats on Fenris Isle.",al={"завдання тула рейвенклова","хто такий тул рейвенклов","некромант фенріс"}},{q="Куди Ренферрел посилає шукачів пригод після Срібнолісся?",a="Коли перші дослідження завершено, а місцеві загрози усунуто, Ренферрел посилає досвідчених мандрівників на південний схід, до Передгір'я Гілсбреда, пов'язуючи прикордонну роботу Гробниці з ширшими операціями Відступників у Лордероні.",al={"після склепу","доставка в гілсбред","подорож до гілсбреда"}},{q="Що таке Королівське Аптекарське Товариство?",a="Королівське Аптекарське Товариство — наукова й алхімічна гілка Відступників, заснована за Леді Сильвани Віндраннер. Його дослідники, що працюють у штаб-квартирі в Андерсіті, невтомно розробляють нові отрути, способи опиратися природному тлінню й чуму, здатну викорінити Погибель.",al={"королівське аптекарське товариство","ркт","аптекарі відступників"}}},fp="20,409,25.393.0,34.389.1,28.263.0,43.249.0,46.183.0,42.178.1,55.224.0,37.286.0"}
P.entries["npc:apothecary-zinge"] = {n="Аптекар Зінґе",s="Аптекар Зінґе — алхімікиня й дослідниця Королівського Аптекарського Товариства, що працює в Апотекаріумі під руїнами Лордерону. Служачи Відступникам, вона вивчає біологічні зразки й налагоджує пересилання дослідницьких вантажів по землях Орди.",h="Аптекар Зінґе — алхімікиня й дослідниця Королівського Аптекарського Товариства, що працює в Апотекаріумі під...",kw={"аптекар зінґе","королівське аптекарське товариство","апотекаріум","андерсіті","відступники","алхімія"},ang={["faction:Horde"]="Її дослідження тримаються на відкритих шляхах постачання й надійних гінцях, що снують морем між Калімдором і Східними Королівствами, — так передова Орди не лишається без припасів.",["race:Undead"]="Для Відступників такі дослідники, як Зінґе, — передовий загін наукової незалежності: вони невтомно створюють сполуки, що мають забезпечити виживання й зверхність їхнього народу."},sec={{t="На службі Товариства",b="Аптекарка Зінґе проводить досліди глибоко в похмурих покоях Апотекаріуму в Андерсіті. Як і її колеги під началом Головного Аптекаря Фаранелла, вона шукає хімічні й біологічні сполуки, що можуть наблизити Відступників до їхніх цілей. Дослідження часто зводять її з польовими вченими й розвідниками далеко за межами Галявин Тірісфалю — аж до обміну з віддаленими заставами в Калімдорі."},{t="Досліди через континенти",b="Щоб удосконалити свої формули й відкрити нові реагенти, Зінґе покладається на гінців і шукачів пригод, які переправляють матеріали для дослідів через моря. Вона постійно листується з колегами, як-от з Аптекарем Гелбрімом на Перехресті в Пустках, і отримує від них екзотичні отрути та природні зразки з посушливих рівнин, щоб ретельно дослідити їх в алхімічних лабораторіях Андерсіті."}},faq={{q="Де знайти Аптекаря Зінґе?",a="Аптекар Зінґе перебуває в Апотекаріумі — алхімічному кварталі на південно-східному ярусі Андерсіті.",al={"місце зінґе","де аптекар зінґе","місце аптекаря зінґе"}},{q="До якої організації вона належить?",a="Вона членкиня Королівського Аптекарського Товариства — ордену алхіміків-Відступників, що створюють нові зілля, чуми й протиотрути на службі Леді Сильвані Віндраннер.",al={"фракція зінґе","на кого працює зінґе"}},{q="Навіщо їй зразки з Пусток?",a="Зінґе часто досліджує екзотичних звірів, отрути й рослини, що не ростуть у Лордероні. Вона співпрацює з Аптекарем Гелбрімом на Перехресті, вивчаючи корінну флору й фауну калімдорського прикордоння.",al={"чому зразки пустища","зразок гелбріма","доставка зінґе пустище"}}},fp="16,276,25.424.0,29.381.0,36.127.0,37.182.0,43.227.0"}
P.entries["npc:aramis-hammerhand"] = {n="Араміс Гаммергенд",s="Араміс Гаммергенд — святий воїн з-поміж нежиті, що перебуває в оскверненій каплиці Похоронного Подзвону. Як наставник паладинів Відступників він навчає щойно воскреслих мерців, що прагнуть відновити свій зв'язок зі Святим Світлом. Іти цим шляхом у нежитті потребує величезної дисципліни: володіння такою променистою силою завдає їхній зотлілій плоті нестерпного болю.",h="Араміс Гаммергенд — святий воїн з-поміж нежиті, що перебуває в оскверненій каплиці Похоронного Подзвону.",kw={"араміс гаммергенд","паладин","наставник","святе світло","похоронний подзвін","відступники","нежить"},ang={["class:Paladin"]="Для паладинів Відступників Араміс — перший наставник, якого вони зустрічають; він проводить їх через муку й духовну дисципліну, потрібні, щоб володіти Святим Світлом у тілі нежиті.",["race:Undead"]="Араміс доводить, що повстати нежиттю не означає зректися гордої спадщини Лордерона — священної війни, навіть якщо це коштує величезних особистих страждань."},sec={{t="Маяк у Похоронному Подзвоні",b="Стоячи в похмурих стінах каплиці Похоронного Подзвону, Араміс Гаммергенд — виняток серед нещодавно пробуджених Відступників. За життя чимало громадян Лордерона відгукнулися на поклик Срібної Длані — і загинули, коли Погибель прокотилася північчю. Араміс пережив падіння лише для того, щоб повстати нежиттю, та він вирішив не зрікатися бойових і духовних настанов свого колишнього існування. Тепер він наставляє інших, хто відмовляється зректися своєї відданості."},{t="Мука Святого Світла",b="Для істоти з нежиті спрямовувати Святе Світло — випробування найвищої сили волі. Ця сила пече мертву плоть і будить давно вмерлі нерви нестерпним болем. Араміс навчає своїх посвячених, що триматися цієї віри означає терпіти безперервну муку. Через такі завдання, як «Важкий шлях» і «Віднайти Світло», він вимагає від молодих паладинів усвідомити тілесну й духовну ціну володіння силою, за своєю суттю ворожою їхній теперішній природі."}},faq={{q="Хто такий Араміс Гаммергенд?",a="Араміс Гаммергенд — наставник паладинів із Відступників у каплиці Похоронного Подзвону на Галявинах Тірісфалю. Він допомагає новопіднятій нежиті, що прагне ступити на шлях святого бою.",al={"лор араміса","хто такий гаммергенд","вчитель паладинів смертельного дзвону"}},{q="Чи справді Відступники можуть користуватися Святим Світлом?",a="Так, силою волі й переконань Відступники можуть закликати Святе Світло. Проте це завдає їм страшного фізичного болю: сяйлива енергія пече й роз'їдає їхню гнилу плоть, навіть коли зцілює чи зміцнює їх.",al={"чи може нежить бути паладином","як нежить використовує світло","світло відступників"}},{q="Де знайти Араміса Гаммергенда?",a="Він стоїть у каплиці Похоронного Подзвону — першого поселення Відступників на Галявинах Тірісфалю.",al={"де араміс","місце гаммергенда","вчитель паладинів смертельний дзвін"}},{q="Які завдання дає Араміс Гаммергенд?",a="Араміс дає новопіднятим паладинам кілька класових завдань, зокрема «Важкий шлях», «Відкрити Світло наново», «Світло в темряві», «Примиритися» та «Продовжуйте навчання».",al={"завдання араміса","завдання паладинів смертельного дзвону"}},{q="Чому наставник паладинів працює на Відступників?",a="До чуми Лордерон був колискою Лицарів Срібної Длані. Чимало щойно звільнених Відступників пам'ятають свої обітниці й не хочуть зрікатися священного покликання, хоч би й стали нежиттю.",al={"чому вчитель паладинів в відступників","срібна рука відступників"}},{q="Чи зцілює Світло нежить у звичний спосіб?",a="Світло може загоїти їхні тіла й дати бойову силу, але це нестерпно боляче. Воно знову пробуджує їхні чуття, змушуючи відчувати, як гниють їхні власні тіла.",al={"чи світло шкодить нежиті","лор зцілення світлом нежиті"}}},fp="17,349,22.484.0,27.466.0,25.181.0,47.225.0,35.122.0,41.202.0,50.214.0,55.193.0"}
P.entries["npc:arcanist-doan"] = {n="Арканіст Доан",s="Арканіст Доан — майстер-маг із людей, що мешкає в Атенеумі, у крилі Бібліотеки Багряного Монастиря. Колись він був соратником Срібної Длані й допомагав викувати легендарний Ешбрінгер, а нині служить Багряному Хрестовому Походу як один із його найнебезпечніших знавців таємної магії й охоронець ключових архівів походу.",h="Арканіст Доан — майстер-маг із людей, що мешкає в Атенеумі, у крилі Бібліотеки Багряного Монастиря.",kw={"арканіст доан","багряний монастир","бібліотека","атенеум","ешбрінгер","багряний ключ","маг"},ang={["class:Mage"]="Майстерність Доана в захисній таємній магії робить його захисну сферу яскравим прикладом магічного обереження.",["class:Paladin"]="Доан бився пліч-о-пліч із засновниками Срібної Длані й особисто очищав кристал, з якого постав Ешбрінгер, перш ніж разом із Хрестовим Походом скотитися у фанатизм.",["faction:Alliance"]="Для сил Альянсу Доан уособлює рештки гордих захисників Лордерону з Кірін-Тору й Срібної Длані, які зреклися розуму заради жорстокої параної Хрестового Походу.",["faction:Horde"]="Відступники та їхні союзники з Орди бачать у Доанові небезпечного багряного командира, чия бібліотека ховає важливі відомості й ключі, потрібні, щоб пробитися до внутрішніх святилищ Хрестового Походу."},sec={{t="Маг серед паладинів",b="Ще до того, як Багряний Хрестовий Похід замкнувся в собі й ударився у фанатизм, арканіст Доан ходив серед Лицарів Срібної Длані. Під час Третьої війни він зустрівся в Саутшорі з верховним лордом Александросом Моґрейном та іншими засновниками. Коли Моґрейн показав темний кристал, відібраний в орка-чорнокнижника ще в Другій війні, Доан помітив його неприродну здатність поглинати святу енергію. Поєднавши своє знання таємної магії зі святою магією соратників, Доан допоміг очистити кристал Порожнечі й обернути його на сяйливе світло — серце зброї, відомої як Ешбрінгер."},{t="Оборона Гартглена",b="Коли Погибель накотилася на Лордерон, Доан обстоював повне стримування чуми. А тоді, як нежить штурмувала укріплення Гартглена, він тримав мури поруч із верховним інквізитором Ісілліеном. Інші квапили його негайно вдарити магією, але Доан неспішно збирав сили й обрушив нищівну хуртовину саме тієї миті, коли вона могла розтрощити лави нежиті. Його холоднокровне терпіння довело смертоносну майстерність у бойовій магії."},{t="Хранитель Атенеуму",b="Поки фанатичні лави Багряного Хрестового Походу покладаються переважно на бойову лють і святий запал, Доан лишався переконаним, що без чистої таємної магії Погибель із Лордерону не викорінити. Його поставили в глибині Атенеуму, бібліотеки Монастиря, і він став і хранителем знань, і вартовим брами: йому довірили Багряний Ключ, що відмикає святилища походу в північних королівствах."}},faq={{q="Чому маг служить у Багряному Хрестовому Поході?",a="Хоча в Поході переважають фанатичні паладини й жерці, Доан був союзником його засновників ще з часів Срібної Длані. Він твердо вірить, що майстерна тайна магія — незамінна зброя, без якої не очистити Лордерон від Погибелі.",al={"чому доан маг","маг хрестового походу","магія доана"}},{q="Що пов'язує Арканіста Доана з Ешбрінгером?",a="На раді в Саутшорі під час Третьої війни Александрос Моґрейн показав сферу темряви, відібрану в орка-чорнокнижника. Доан допомагав керувати магічним дослідом, у якому Срібна Длань влила свою силу в реліквію й очистила її, перетворивши на сяйливе осердя, з якого викували Ешбрінгер.",al={"доан ешбрінґер","чи доан створив ешбрінґер","кристал ешбрінґера"}},{q="Що Доан стереже в Бібліотеці?",a="Доан стереже сховище книжок і літописів Монастиря в Атенеумі. За ним стоїть скринька з Багряним Ключем — важливим ключем, що відмикає ворота до Зброярні й Собору Монастиря.",al={"що доан дропає","багряний ключ","чому вбивати доана"}},{q="Якою магією Доан б'ється?",a="Доан поєднує захисну й руйнівну магію. Він славиться тим, що накладає Тайну Сферу, яка робить його невразливим, поки він готує потужне закляття Детонація, що накриває всю залу. Ще він змушує заклиначів замовкнути закляттям по площі й перетворює небезпечних супротивників на овець.",al={"закляття доана","здібності доана","бульбашка арканіста доана"}},{q="Де Доан бився під час Третьої війни?",a="Окрім участі у вирішальних воєнних радах у Саутшорі, Доан бився на передовій у Гартглені: з мурів він насилав нищівні хуртовини, щоб розбивати величезні хвилі нападу нежиті.",al={"історія війни доана","доан гартгленн","де був доан"}},{q="Чи має Доан якісь особисті таємниці?",a="Доан служить арканістом Багряного Хрестового Походу. Про його особисті сердечні прихильності в джерелах Класики нічого не сказано.",al={"фонтан даларана доан","доан аббендіс","лор доана"}}},fp="13,315,21.533.0,21.467.0,23.418.0,37.253.0,53.299.0,36.244.0,35.261.0,42.194.0,38.122.0"}
P.entries["npc:archaeologist-flagongut"] = {n="Археолог Флеґонґат",s="Археолог Флеґонґат — дворфський учений, представник Ліги Дослідників, що перебуває в Таверні «Глибока Вода» в Гавані Менетіл. Хоча спершу він прямував до Місця Розкопок Велґара, він стає важливим посередником для польових звітів, що приходять через море з Темного Узбережжя.",h="Археолог Флеґонґат — дворфський учений, представник Ліги Дослідників, що перебуває в Таверні «Глибока Вода» в...",kw={"археолог флеґонґат","ліга дослідників","таверна глибока вода","гавань менетіл","багнокрай","айронфордж"},ang={["faction:Alliance"]="Флеґонґат — ланка постачання між землями нічних ельфів на Темному Узбережжі та східними твердинями Альянсу в Каз Модані.",["race:Dwarf"]="Флеґонґат втілює далекосяжні амбіції Ліги Дослідників і доводить, що навіть таверна біля моря може стати заставою, де складають докупи таємниці титанів."},sec={{t="Учений у порту",b="Археолога Флеґонґата можна застати з кухлем у руці в Таверні «Глибока Вода» в Гавані Менетіл. Як і багато членів Ліги Дослідників з Айронфорджа, він подався на захід через Каз Модан, щоб допомогти з відкриттями біля Місця Розкопок Велґара в Багнокраї. Хоч він і далеко від високих зал бібліотеки, Флеґонґат підтримує важливі зв'язки з польовими дослідниками й допомагає опрацьовувати загублені реліквії та звіти, які переправляють через Велике Море з далеких експедицій."},{t="Зв'язки з польовими дослідниками",b="Дворфська цікавість рідко обмежується одним континентом, і Флеґонґат розбирає безладні польові дослідження неуважних колег, що працюють на берегах Калімдору. Коли до гавані надходять реліквії чи нотатки з розкопок на Темному Узбережжі, Флеґонґат стежить, щоб знахідки занесли до каталогу й переслали далі — до старших очільників Ліги в Айронфорджі."}},faq={{q="Хто такий Археолог Флеґонґат?",a="Флеґонґат — дворф-дослідник із Ліги Дослідників. Він сидить у Таверні «Глибока Вода» в Гавані Менетіл, де переглядає звіти з розкопок і листується з місцями робіт.",al={"хто такий флеґонґат","флеґонґат нпс","лор археолога флеґонґата"}},{q="Що Флеґонґат робить у Таверні «Глибока Вода»?",a="Спершу він прибув до Гавані Менетіл, щоб дістатися Місця Розкопок Велґара в Багнокраї. Поки він у порту, таверна править йому за базу для пошти, артефактів, що надходять, і листування з далеких країв.",al={"чому флеґонґат у менетілі","місце флеґонґата","що флеґонґат тут робить"}},{q="Що пов'язує Флеґонґата з Темним Узбережжям?",a="Флеґонґат — зв'язковий у Багнокраї для давнього ланцюжка досліджень, який почав Шукач Ремтревел на Темному Узбережжі. Шукачі пригод, що перепливають з Обердайна до Менетіла, приносять знахідки Ремтревела просто Флеґонґатові, щоб той переслав їх до Айронфорджа.",al={"зв'язок флеґонґата з темним узбережжям","чому завдання темного узбережжя в болотах"}},{q="До якої організації він належить?",a="Він належить до Ліги Дослідників — королівського товариства Короля Маґні Бронзбірда, що розкриває давнє походження, реліквії та історію дворфського народу по всьому Азероту.",al={"фракція флеґонґата","флеґонґат ліга дослідників"}}},fp="23,305,17.474.0,17.399.0,31.188.0,41.206.0,40.252.0,36.176.0"}
P.entries["npc:archaeologist-hollee"] = {n="Археолог Голлі",s="Археолог Голлі — дворфська дослідниця, що працює в прибережному поселенні Обердайн. Представляючи інтереси дворфських розкопок, вона стежить за археологічними знахідками й обстеженнями в давніх, оповитих туманом нетрях Темного Узбережжя й часто координує роботу шукачів, які прочісують край у пошуках реліквій і геологічних дивовиж.",h="Археолог Голлі — дворфська дослідниця, що працює в прибережному поселенні Обердайн.",kw={"археолог голлі","ліга дослідників","шукач ремтревел","обердайн","темне узбережжя","дворфи"},ang={["faction:Alliance"]="Голлі втілює співпрацю Східних Королівств і нічних ельфів: Обердайн для неї — база для вивчення далекого минулого Калімдору.",["race:Dwarf"]="Зустріти співвітчизницю так далеко за морем, в імлистих лісах Темного Узбережжя, — нагадування про безмежну спрагу Айронфорджа розкривати давню історію."},sec={{t="Дворфська вчена на землях калдореїв",b="Хоча Темне Узбережжя здебільшого заселяють і стережуть нічні ельфи, присутність дворфських учених на кшталт археолога Голлі свідчить про дедалі більшу цікавість Айронфорджа до Калімдору. Ліга Дослідників посилає своїх представників далеко за моря, щоб шукати сліди давньої історії, а руїни Темного Узбережжя — спокусливе поле для досліджень. Голлі облаштувала тимчасову базу в Обердайні й стала в краї посередницею для мандрівних дослідників і експедицій."},{t="Нагляд за Ремтревелом",b="Чимала частина щоденної роботи Голлі — стежити за колегами в полі, передусім за неуважним шукачем Ремтревелом. Йому доручено важливі обстеження на дикому узбережжі, але Ремтревел часто забрідає далеко й не звітує вчасно. Голлі часто просить мандрівників, що проходять через Обердайн, розшукати його, повернути загублені дані обстежень і подбати, щоб польові дослідження не стали здобиччю місцевих звірів чи нових загроз."}},faq={{q="Хто така Археолог Голлі?",a="Археолог Голлі — дворфійка, що працює в Обердайні на Темному Узбережжі. Вона веде й наглядає польові дослідження в краї від імені дворфських археологів на західному континенті.",al={"хто така голлі","голлі темне узбережжя","дворф в обердайні"}},{q="Де знайти Голлі?",a="Вона перебуває в прибережному портовому містечку Обердайн на західному узбережжі Темного Узбережжя.",al={"місце голлі","де археолог голлі"}},{q="Чому дворфи ведуть дослідження на Темному Узбережжі?",a="Після Третьої війни, коли союз Айронфорджа з нічними ельфами поглибився, дворфські дослідники вирушили до Калімдору вивчати давні реліквії, геологічні утворення й давно поховану історію, що може пролити світло на їхнє власне походження.",al={"чому дворфи на темному узбережжі","айронфордж у калімдорі"}},{q="У якій біді їй потрібна допомога?",a="Голлі найбільше непокоїться за Шукача Ремтревела — неуважного розвідника, що забрів на південь Темного Узбережжя й так і не повернувся зі звітом про свої знахідки.",al={"завдання голлі","завдання розсіяного рудознавця"}},{q="Що пов'язує Голлі з Шукачем Ремтревелом?",a="Вони колеги, що працюють над тими самими розкопками й розвідками на Темному Узбережжі. Ремтревел виконує практичну польову роботу серед руїн, а Голлі збирає звіти й підтримує зв'язок із мандрівниками з Обердайна.",al={"хто такий ремтревел","ремтревел і голлі"}},{q="Чи належить Голлі до Ліги Дослідників?",a="Вона представляє дворфські археологічні й розвідувальні експедиції, союзні Айронфорджу, які зазвичай організовує Ліга Дослідників зі Східних Королівств.",al={"ліга дослідників голлі","фракція голлі"}}},fp="20,362,35.468.0,25.485.1,28.188.0,26.97.0,49.252.0,37.183.0,65.219.0,44.198.0"}
P.entries["npc:archbishop-benedictus"] = {n="Архієпископ Бенедиктус",s="Архієпископ Бенедиктус — верховний духовний провідник Церкви Святого Світла, що очолює вірних із Собору Світла в Стормвінді. Колись відданий учень архієпископа Алонсуса Фаола, нині він веде моральне й релігійне серце Альянсу крізь часи великої непевності.",h="Архієпископ Бенедиктус — верховний духовний провідник Церкви Святого Світла, що очолює вірних із Собору...",kw={"архієпископ бенедиктус","церква святого світла","собор світла","стормвінд","алонсус фаол","жерці"},ang={["class:Priest"]="Як верховний пастир Церкви Святого Світла, Бенедиктус — головна постать, що наглядає за навчанням, доктринами й обітницями всіх жерців Альянсу.",["faction:Alliance"]="Бенедиктус — моральний компас Стормвінда й усього Альянсу: він дарує духовну розраду біженцям і наставляє високопоставлених паладинів і командирів."},sec={{t="Пастир Святого Світла",b="Бенедиктус став провідником після смерті свого шанованого наставника, архієпископа Алонсуса Фаола. Побачивши спустошення Першої й Другої воєн, Бенедиктус допомагав наглядати за будівництвом величного Собору Світла в Стормвінді й присягнув берегти чесноти віри. Коли під час Третьої війни впав Лордерон і постала Погибель, тягар духовного проводу людських королівств ліг саме на його плечі. Від свого вівтаря він радить королівському двору, навчає новопосвячених жерців і спрямовує святі походи проти нежиті й демонічних сил, що загрожують Азероту."},{t="Обтяжена віра",b="Хоча по всьому Альянсу Бенедиктуса вважають лагідним, мудрим і доброзичливим патріархом, він несе глибоку скорботу від Третьої війни. Різанина народу Лордерона й трагічне падіння принца Артаса Менетіла тяжко випробували розуміння Церквою божественного захисту. Попри ці приховані духовні випробування, Бенедиктус для людей — незламний маяк надії: він згуртовує героїв на боротьбу з темними загрозами на кшталт Амненнара Хладоносця в Калімдорі й допомагає очищати прокляті реліквії, які приносять вірні шукачі пригод."}},faq={{q="Хто такий Архієпископ Бенедиктус?",a="Він — нинішній предстоятель Церкви Святого Світла й найвищий духовний авторитет Великого Альянсу. Із Собору Світла в Стормвінді він наставляє вірян і радить провідникам королівства.",al={"бенедиктус","архієпископ стормвінда","голова церкви світла"}},{q="Що пов'язує його з Алонсусом Фаолом?",a="Бенедиктус був найкращим учнем легендарного Архієпископа Алонсуса Фаола, засновника Лицарів Срібної Длані. Після смерті Фаола Бенедиктус очолив Церкву, щоб продовжити справу свого наставника.",al={"учень фаола","алонсус фаол бенедиктус"}},{q="Які доручення Бенедиктус дає шукачам пригод?",a="Бенедиктус посилає героїв Альянсу на боротьбу з Погибеллю, зокрема благословляє походи до Рейзорфен Даунс, щоб убити ліча Амненнара Хладоносця. Своєю святою силою він також очищує могутні осквернені артефакти, як-от Прокляте Око Палета.",al={"завдання бенедиктуса","що робить архієпископ бенедиктус"}},{q="Як він ставиться до нежиті?",a="Бенедиктус вважає нежить нечестивою трагедією. Він проповідує милосердя, але його послідовники розуміють це як дарування неспокійним мерцям — і Відступникам, і Погибелі — милості швидкого й остаточного спочинку через смерть.",al={"бенедиктус відступники","погляди бенедиктуса на погибель"}}},fp="21,312,26.632.0,21.542.0,29.225.0,41.229.0,51.269.0,33.227.0"}
P.entries["npc:archmage-ansirem-runeweaver"] = {n="Верховний Маг Ансірем Рунотвор",s="Верховний Маг Ансірем Рунотвор — досвідчений чарівник-людина, один із правителів Даларану, член Ради Шести. Він пережив знищення Даларану Погибеллю в Третю війну й тепер із Фіолетової Цитаделі керує справами Кірін-Тору, поки місто відбудовують. Хоч Ансірем і відданий відбудові рідного міста, він потай пильнує й справи далеко за його межами — зокрема не спускає ока з власної доньки-піратки.",h="Верховний Маг Ансірем Рунотвор — досвідчений чарівник-людина, один із правителів Даларану, член Ради Шести.",kw={"ансірем","рунотвор","даларан","кірін-тор","рада шести","верховний маг","кетлін"},ang={["class:Mage"]="Ансірем — шанований член Ради Шести, тож він незмінний авторитет у суворій науці тайної магії.",["faction:Alliance"]="Як один з очільників Кірін-Тору, що осів у Лордероні, Ансірем лишається на боці Альянсу, поки чарівники-люди силкуються відвоювати свої землі в недобитків Погибелі."},sec={{t="Опора Кірін-Тору",b="Ветеран-маг, що десятиліттями боронив Даларан, Ансірем Рунотвор засідає в Раді Шести — правлячій магократії Кірін-Тору. Він пережив спустошення, коли на місто рушили Артас Менетіл і Погибель, а згодом було викликано Архімонда. Після падіння Даларану Ансірем допомагає відбудовувати чародійне місто, з якого рано зняли захисний щит, і тепер працює у Фіолетовій Цитаделі."},{t="Справи далеко від дому",b="Попри вчені обов'язки й суворий чарівничий норов, Ансірем має особисті зв'язки далеко за Горами Альтерак. Його бунтівна донька Кетлін відцуралася чародійства й вийшла в море шибайголовою з Нападниками Чорної Води. Ансірем не зрікся її: він платить золотом кільком друзям у Буті Бей, щоб ті доносили йому про її пригоди, і вже мав справи з тамтешнім Бароном Ревілґазом. А ще він вивчав тролячі старожитності за допомогою тайної магії й підтримує дипломатичні зв'язки з далекими краями."}},faq={{q="Хто такий Верховний Маг Ансірем Рунотвор?",a="Він — досвідчений чарівник-людина й один із шести верховних магів, що правлять у Раді Шести Кірін-Тору. Десятиліттями він захищав Даларан, а нині наглядає за справами довкола відбудованого міста та його магічного периметра.",al={"хто такий ансірем","лор ансірема рунотвора","хто верховний маг"}},{q="Що сталося з його донькою?",a="Його донька Кетлін занудьгувала від магічних студій і обрала натомість піратське життя, плаваючи з Нападниками Чорної Води в Долині Стренглторну. Хоч Ансірем і хотів би, щоб вона обрала звичайніший шлях, він і далі підтримує її здалеку й платить зв'язковим у Буті Бей, щоб ті повідомляли, чи вона в безпеці.",al={"донька ансірема","кейтелін клинок","кейтелін рунотвор"}},{q="Яка його роль у Даларані?",a="Ансірем — одна з ключових постатей Кірін-Тору у Фіолетовій Цитаделі: він координує дослідження, магічний захист і зв'язок із союзниками, поки місто відбудовують після руйнувань Третьої війни.",al={"чому ансірем в альтераку","ансірем даларан","що він тут робить"}},{q="Чи бився Ансірем у Третій війні?",a="Так. Коли Артас і Погибель обложили Даларан, щоб Кел'Тузад зміг викликати Архімонда, Ансірем був серед магів, що билися з ними під містом, і пережив його знищення.",al={"ансірем погибель","чи ансірем бився з артасом"}}},fp="27,403,25.428.0,19.515.0,35.233.0,30.316.0,28.213.0,35.192.0"}
P.entries["npc:archmage-malin"] = {n="Архімаг Малін",s="Архімаг Малін — досвідчений чарівник-людина, що стоїть просто біля Святилища Чародія в Кварталі магів Стормвінда. Колишній учень Архімага Трелейна, Малін опікується таємними справами й польовими агентами, яких посилають по магічні артефакти й рідкісні реагенти по всіх Східних Королівствах.",h="Архімаг Малін — досвідчений чарівник-людина, що стоїть просто біля Святилища Чародія в Кварталі магів...",kw={"архімаг малін","святилище чародія","архімаг трелейн","аратійське нагір'я","скуерто","учень крайтен"},ang={["class:Mage"]="Для магів Альянсу, що відвідують Святилище Чародія, Малін — міст між академічним навчанням у Стормвінді й небезпечною дійсністю пошуку загублених реліквій у дикій глушині.",["faction:Alliance"]="Агенти Маліна в Араті намагаються вберегти могутні артефакти, перш ніж ті потраплять до рук Синдикату, огрів Каменекулаків чи Орди."},sec={{t="Вартовий Святилища Чародія",b="Стоячи на варті під височенною спіраллю Святилища Чародія, Архімаг Малін слугує головною сполучною ланкою для знавців таємної магії Стормвінда. Він опанував ремесло під проводом Архімага Трелейна — славетного мага, чию розпорошену спадщину Малін нині намагається вберегти. Поки молодші послушники вивчають теорію серед вихрястих синіх порталів вежі, Малін пильнує справи по всьому королівству, що потребують магічного нагляду."},{t="Очі в нагір'ї",b="Багато уваги Малін приділяє небезпечним руїнам Аратійського нагір'я на півночі. Щоб повернути загублені речі Архімага Трелейна й убезпечити тендітні складники для заклять, Малін послав туди своїх надійних помічників — Скуерто й Учня Крайтена. Керуючи цими далекими операціями зі столиці, Малін покладається на вправних мандрівників Альянсу, які доставляють його агентам на ворожій території вказівки, припаси й відомості."}},faq={{q="Хто такий Архімаг Малін?",a="Архімаг Малін — високопоставлений маг-людина зі Стормвінда. Він стоїть біля входу до Святилища Чародія в Кварталі магів, наглядає за дослідженнями, посилає учнів у поле й допомагає підтримувати лад серед магів столиці.",al={"лор архімага маліна","хто такий малін","малін стормвінд"}},{q="Що пов'язує Маліна з Архімагом Трелейном?",a="Архімаг Трелейн був першим учителем і наставником Маліна. Малін і досі глибоко відданий Трелейнові й завзято організовує пошуки та повернення особистих речей і магічних реліквій свого колишнього вчителя, розкиданих по Аратійському нагір'ю.",al={"малін і трелейн","хто був учителем маліна","зв'язок з архімагом трелейном"}},{q="Навіщо Малін посилає шукачів пригод до Аратійського нагір'я?",a="У Маліна на Аратійському нагір'ї двоє агентів: Скуерто й Учень Крайтен. Дорога туди небезпечна, а зв'язок складний, тож Малін просить мандрівних шукачів пригод доставити його польовим агентам важливі доручення, магічні припаси й вказівки щодо пошуку артефактів Трелейна.",al={"завдання маліна","чому аратійське нагір'я","завдання скуерто"}},{q="Де знайти Архімага Маліна?",a="Він стоїть біля підніжжя вежі Святилища Чародія в серці Кварталу магів у Стормвінді, звідки видно пандуси, що ведуть до зали порталів святилища.",al={"де малін","місце архімага маліна","малін на мапі"}}},fp="14,294,31.469.0,21.458.0,22.271.0,47.245.0,56.317.0,34.179.0"}
P.entries["npc:archmage-xylem"] = {n="Архімаг Ксилем",s="Архімаг Ксилем — дивакуватий і відлюдний чарівник-людина, що живе у відокремленій вежі на кручах північної Азшари. Відомий мінливим норовом і небезпечними дослідами, він відсторонився від мирських справ заради езотеричних тайних студій. Дістатися до нього можна лише магічним телепортом, і він приймає тільки тих шукачів пригод, що можуть допомогти в його дивних дослідженнях чи в особистій помсті.",h="Архімаг Ксилем — дивакуватий і відлюдний чарівник-людина, що живе у відокремленій вежі на кручах північної...",kw={"архімаг ксилем","азшара","санат лім-йо","морфаз","гори кам'яного кігтя","маги","відлюдник"},ang={["class:Mage"]="Для знавців тайної магії Ксилем — і взірець найвищої майстерності, і тривожний приклад того, до чого призводить цілковита самотність у гонитві за магічною силою.",["faction:Horde"]="Ветерани Орди можуть пам'ятати, як разом із Ґроммашем Хеллскрімом штурмували оборону Ксилема в Горах Кам'яного Кігтя, та нині відлюдний чарівник напрочуд охоче веде перемовини з героями Орди.",["race:Human"]="На відміну від статечних чарівників Даларану чи Стормвінда, Ксилем цілком покинув людське суспільство, щоб жити собі без клопоту серед диких просторів Азшари."},sec={{t="Відлюдник над узбережжям",b="Архімаг Ксилем живе у відокремленому шпилі високо на зубчастих кручах північної Азшари, звідки видно зруйноване ельфійське узбережжя. Замість прокласти дорогу чи стежку, чарівник цілком відрізав своє пристановище від світу й покладається на слугу Саната Лім-йо, який магією переносить схвалених гостей на вершину скелі. По всьому Калімдору його вважають великим диваком, з яким небезпечно мати справу; навіть колеги-вчені ставляться до нього з великою обережністю, зауважуючи, що він поводиться не так, як майже будь-який інший людський маг."},{t="Відлуння Третьої війни",b="Перш ніж усамітнитися в Азшарі, Архімаг Ксилем брав участь у Третій війні разом із людськими експедиційними силами в Калімдорі. Під час походів у Горах Кам'яного Кігтя на його укріплений табір жорстоко напав клан Пісні Війни під проводом Ґроммаша Хеллскріма. Хоч оборону Ксилема розбили, він пережив війну, а згодом відвернувся від великих воєн, щоб у диких краях континенту осягати тайну магію наодинці."},{t="Рахунки з Морфазом",b="Відлюддя Ксилема не таке вже й мирне: він плекає люту ненависть до зеленого драконячого роду, а надто до дракона на ім'я Морфаз. Колись цей звір проковтнув живцем одного з нещасних учнів Ксилема — разом із тайним уламком неймовірної сили, який той мав при собі. Мстивий архімаг не оплакує учня — він одержимий тим, щоб вистежити Морфаза й витягти цінний артефакт із драконового черева."}},faq={{q="Як дістатися вежі Архімага Ксилема?",a="Вежа Архімага Ксилема стоїть на неприступній кручі на півночі Азшари, і пішої стежки туди немає. Щоб потрапити до нього, треба знайти його слугу Саната Лім-йо: той стоїть біля підніжжя круч і може магією перенести мандрівників до вежі.",al={"як дістатися ксилема","дійти до ксилема","телепорт до ксилема","місце ксилема"}},{q="Хто такий Архімаг Ксилем?",a="Це дивакуватий архімаг-людина, що воював у Третій війні в Горах Кам'яного Кігтя. Після війни він усамітнився у вежі на вершині кручі на півночі Азшари, щоб подалі від цивілізації проводити небезпечні магічні досліди.",al={"хто такий ксилем","лор архімага ксилема","минуле ксилема"}},{q="Що сталося з Ксилемом у Третій війні?",a="Під час Третьої війни Ксилем командував людською базою в Горах Кам'яного Кігтя. На його заставу напали й захопили її Ґроммаш Хеллскрім і охоплений кривавим шалом клан Бойової Пісні, але архімаг уцілів.",al={"ксилем третя війна","ксилем стоунталон","ксилем вц3"}},{q="Чому Ксилем хоче смерті дракона Морфаза?",a="Зелений дракон Морфаз напав на послідовників Ксилема й проковтнув цілком одного з його учнів. Учень ніс уламок величезної магічної сили, тож Ксилем прагне смерті дракона, щоб дістати реліквію з його шлунка.",al={"ксилем морфаз","чому вбити морфаза","уламок морфаза"}},{q="Чому кажуть, що Ксилем небезпечний?",a="Місцеві знайомі, як-от Джедіґа, застерігають мандрівників, що Ксилем непередбачуваний, відчужений і помітно дивний, як на людину.",al={"чи ксилем небезпечний","ксилем божевільний","характер ксилема"}},{q="Ксилем належить до Альянсу чи до Кірін-Тору?",a="Хоч колись Ксилем і був у людській експедиції під час Третьої війни, тепер він цілком незалежний відлюдник. Він не служить війську Альянсу й охоче матиме справу з будь-яким шукачем пригод, готовим виконати його волю, хоч би з якої той фракції.",al={"фракція ксилема","чи ксилем альянс","ксилем кірін-тор"}}},fp="14,410,25.521.0,23.495.0,24.442.1,40.269.0,22.240.0,40.218.0,44.235.0,37.125.0,51.259.0"}
P.entries["npc:argent-guard-manados"] = {n="Срібний Вартовий Манадос",s="Срібний Вартовий Манадос — нічний ельф-вартовий, що стоїть у Дарнасусі від імені Срібного Світанку. Перебуваючи на Терасі Ремісників, він стежить за поширенням скверни в Калімдорі й скеровує шукачів пригод до лиховісних сил, що чигають у Чорноглибинних Печерах.",h="Срібний Вартовий Манадос — нічний ельф-вартовий, що стоїть у Дарнасусі від імені Срібного Світанку.",kw={"срібний вартовий манадос","срібний світанок","дарнасус","тераса ремісників","чорноглибинні печери","нічні ельфи"},ang={["faction:Alliance"]="Для звитяжців Альянсу, що відвідують Дарнасус, Манадос — важлива ланка між далекими походами в Лордероні й підступною загрозою сектантів на півночі Калімдору.",["race:NightElf"]="Манадос показує, що не всі нічні ельфи обмежують свій обов'язок Колом Кенарія чи Вартовими: дехто присвячує життя нейтральним орденам, що стоять понад фракціями, як-от Срібному Світанку, щоб зберегти Азерот."},sec={{t="Вартовий Світанку",b="Більшість Срібного Світанку зосереджує пильність на сплюндрованих землях Лордерону й Погибелі, а Срібний Вартовий Манадос — їхні пильні очі в столиці нічних ельфів, Дарнасусі. Стоячи серед ремісників і торговців Тераси Ремісників, Манадос стежить за новими загрозами, що порушують рівновагу півночі Калімдору. Коли до нього доходять чутки, що культ Молота Присмерку облаштував мерзенний опорний пункт під хвилями Ашенвалю, Манадос кличе вправних героїв ударити по Чорноглибинних Печерах і повернути артефакти їхнього темного культу."}},faq={{q="Хто такий Срібний Вартовий Манадос?",a="Манадос — нічний ельф, агент Срібного світанку в Дарнасусі. Замість того щоб битися з Погибеллю у Східних Королівствах, він лишається в Калімдорі, щоб стежити за темними культами й потойбічною скверною.",al={"хто такий манадос","роль срібного вартового манадоса","манадос дарнасус"}},{q="Де знайти Срібного Вартового Манадоса?",a="Він стоїть на Терасі Ремісників у Дарнасусі, пильнує місто й співпрацює з місцевими шукачами пригод.",al={"місце манадоса","де срібний вартовий манадос","манадос тераса майстрів"}},{q="Які завдання дає Срібний Вартовий Манадос?",a="Він дає завдання «Падіння Присмерку», посилаючи шукачів пригод до Чорноглибинних Печер в Ашенвалі, щоб забрати Сутінкові Амулети в культистів, які там ховаються.",al={"завдання манадоса","видавець сутінкового падіння","завдання срібного світанку чорноглибинні печери"}},{q="Чому Срібний Світанок цікавиться Чорноглибинними Печерами?",a="Срібний Світанок бореться з лихими силами, що загрожують Азероту. Раптова поява культу Молота Присмерку, який поклоняється давнім зіпсованим сутностям у затоплених руїнах Ашенвалю, — небезпека, яку не можна оминути увагою.",al={"чому срібний світанок чорноглибинні печери","срібний світанок сутінковий культ"}}},fp="20,262,22.565.0,28.214.0,38.133.0,43.162.0,55.225.0"}
P.entries["npc:argos-nightwhisper"] = {n="Арґос Найтвіспер",s="Арґос Найтвіспер — нічноельфійський посланець, якого можна зустріти в Парку Стормвінда. Він — зв'язковий Альянсу, що спрямовує шукачів пригод до Тельдрассилу, щоб допомогти його народові протистояти зіпсуттю, яке дедалі ширшає.",h="Арґос Найтвіспер — нічноельфійський посланець, якого можна зустріти в Парку Стормвінда.",kw={"арґос найтвіспер","нічні ельфи","калдореї","тельдрассил","дарнасус","стормвінд"},ang={["faction:Alliance"]="Арґос — одна з перших ланок між Східними Королівствами й Калімдором: він заохочує юних героїв Альянсу перетнути море й допомогти нічним ельфам.",["race:NightElf"]="Для калдореїв, що мандрують далеко від Калімдору, Арґос — знайоме обличчя: він допомагає повернутися до Тельдрассилу й стежить за загрозами рідним гілкам."},sec={{t="Калдорей у людській столиці",b="Арґос Найтвіспер живе серед дедалі численніших нічних ельфів у Стормвінді й часто проводить час у пишному відлюдному Парку, створеному, щоб нагадувати калдореям про ліси їхніх предків. Як і багато його родичів, що оселилися в людському королівстві, Арґос є мостом між новими союзниками з різних берегів Великого Моря. Глибоко стривожений звістками, що долинають з-за океану, він закликає вправних звитяжців Альянсу вирушити на захід, до Дарнасуса, й допомогти очистити темну скверну, що повзе корінням Тельдрассилу."}},faq={{q="Хто такий Арґос Найтвіспер?",a="Арґос Найтвіспер — нічний ельф, що живе в Стормвінді. Він представляє інтереси Дарнасуса в східній столиці Альянсу: допомагає мандрівникам і направляє шукачів пригод пливти до Калімдору.",al={"арґос найтвіспер","хто такий арґос","арґос стормвінд"}},{q="Де знайти Арґоса Найтвіспера?",a="У Стормвінді нічні ельфи зазвичай збираються в Парку — куточку з місячними колодязями й зеленню, облаштованому за звичаями калдореїв.",al={"місце арґоса","де арґос","знайти арґоса найтвіспера"}},{q="Що Арґос доручає шукачам пригод?",a="Арґос посилає шукачів пригод з Альянсу за море, на Тельдрассил. Він застерігає про скверну, що шириться лісами Калімдору, і направляє вправних бійців з'явитися до провідників нічних ельфів у Дарнасусі.",al={"завдання скверни за кордоном","завдання арґоса","чому до дарнасуса"}},{q="Чи родич Арґос інших Найтвісперів?",a="Хоч він і має те саме родове ім'я, що й інші нічні ельфи, як-от Фалорн та Евелл Найтвіспер, Арґос зосереджений на своїх обов'язках — зв'язку між Стормвіндом і Дарнасусом.",al={"родина найтвісперів","родичі арґоса"}}},fp="18,209,31.516.0,26.217.0,38.126.0,38.213.0,40.169.0"}
P.entries["npc:arugal"] = {n="Аруґал",s="Архімаг Аруґал — колишній чарівник Даларана й Ґілнеаса, що випустив диких воргенів на Лордерон. Охоплений божевіллям і горем, він тепер править із висот Фортеці Шадовфенг, вважаючи лютих звірів своїми любими дітьми й погрожуючи всьому Срібноліссю.",h="Архімаг Аруґал — колишній чарівник Даларана й Ґілнеаса, що випустив диких воргенів на Лордерон.",kw={"архімаг аруґал","воргени","фортеця шадовфенг","срібнолісся","кірін-тор","ґілнеас"},ang={["class:Mage"]="Аруґал уособлює катастрофічну небезпеку безрозсудних викликів, що перетворили глибокі дослідження Кірін-Тору на некерований кошмар.",["faction:Horde"]="Воргени Аруґала заполонили дорогу на південь від Гробниці, і Леді Сильвана наказала стратити його, щоб убезпечити Срібнолісся для Відступників.",["race:Undead"]="Звірі Аруґала вбили кількох скрадачів смерті й аптекарів; покласти край його божевіллю — нагальна справа для Королівського Аптекарського Товариства."},sec={{t="Відчайдушний виклик",b="До падіння Лордерона Аруґал був членом Кірін-Тору, хоча деякі колеги, як-от Далар Донвівер, зневажливо вважали його шарлатаном, чия слабка магія трималася здебільшого на зачарованих дрібничках. Коли під час Третьої війни Погибель прокотилася північчю, Аруґал шукав зброю, достатньо могутню, щоб стримати навалу. Спираючись на езотеричні дослідження покійного даларанського мага Ура, Аруґал прорвав завісу між світами й викликав воргенів у світ смертних. Ненажерливі звірі, як і задумувалося, розтерзали легіони нежиті, але їхню дику лютість не вдалося стримати, і їхній звірячий голод швидко обернувся проти невинних смертних."},{t="Падіння в божевілля",b="Викликані жахіття перебили ґілнеаських вояків, що стояли за Стіною Ґреймейна, і поширили своє страшне прокляття Ґілнеасом. Частина звірів узяла в облогу родовий маєток Барона Сільверлейна, і фортеця швидко впала під кігтями й іклами, а її господаря й челядь було вбито в різанині. Замість утекти від свого жахливого творіння, Аруґал утратив розум під тягарем провини й прийняв звірів як власних нащадків. Перейменувавши фортецю на Фортецю Шадовфенг, Аруґал окопався за її мурами в оточенні примарних жертв і вірних зграй."},{t="Бич Срібнолісся",b="Зі свого високого гнізда у Фортеці Шадовфенг Аруґал поширює спотворену владу на довколишні землі. Його темне чаклунство огортає Село Пайрвуд, мешканці якого живуть під нічним прокляттям, і наповнює Шахту Глибокого Елему ненажерливими звірами-Мунрейджами. Він плете складні чари, що дозволяють обраним слугам зберігати людський розум, цілком підкоряючись його волі. Відступники вважають його нестерпною загрозою: скрадачі смерті й аптекарі Сильвани Віндраннер готують страту божевільного архімага, щоб убезпечити кордони свого молодого королівства."}},faq={{q="Хто такий Аруґал?",a="Аруґал — колишній архімаг-людина з Кірін-Тору та Ґілнеаса. Під час Третьої війни він закликав жахливих воргенів, щоб боротися з Погибеллю. Приголомшений наслідками своїх дій, він сховався у Фортеці Шадовфенг, де тепер верховодить зграями воргенів як їхній самозваний батько.",al={"хто такий аруґал","історія аруґала","бос шедоуфенґ лор"}},{q="Навіщо Аруґал закликав воргенів?",a="Під час Третьої війни Погибель загрожувала заполонити північ Лордерону й Ґілнеас. У відчаї шукаючи зброю проти нежиті, Аруґал скористався дослідженнями інших вимірів даларанського мага Ура. Він вірив, що люті звірі знищать Погибель, але, закликавши їх, утратив над ними владу.",al={"чому воргени","чому прикликав звірів","мотив аруґала воргени"}},{q="Де зараз живе Аруґал?",a="Лігво Аруґала — на вершині Фортеці Шадовфенг, давньої твердині на морських кручах над Селом Пайрвуд на півдні Срібнолісся. Його стереже жахливий вовк Фенрус, а також зграї вірних воргенів і неспокійні духи.",al={"де аруґал","місце аруґала","знайти аруґала"}},{q="Що сталося з Бароном Сільверлейном?",a="Барон Сільверлейн був шляхетним лордом, що колись правив фортецею й селом Пайрвуд. Коли воргени Аруґала взяли замок в облогу, Сільверлейна та його двір жорстоко вирізали. Тепер їхні мстиві, змучені привиди блукають заплямованими кров'ю залами фортеці.",al={"доля барона сільверлейна","хто володів шедоуфенґ","історія фортеці"}},{q="Чому Відступники хочуть смерті Аруґала?",a="Зграї Аруґала тероризують Срібнолісся: нападають на розвідників-Відступників, влаштовують засідки на патрулі й навіть заражають вірних слуг Королівського Аптекарського Товариства. Сильвана Віндраннер вважає божевільного архімага прямою загрозою безпеці й розширенню кордонів Андерсіті.",al={"відступники проти аруґала","завдання аруґал мусить померти","чому вбити аруґала"}},{q="Що за прокляття лежить на Селі Пайрвуд?",a="Аруґал наклав на край мерзенні чари, що прирекли людей Села Пайрвуд на прокляття воргенів. Удень селяни мають звичайний людський вигляд, але з настанням ночі перетворюються на лютих звірів, змушених боронити володіння Аруґала.",al={"прокляття пайрвуда","чому селяни пайрвуда вовки","пайрвуд аруґал"}}},fp="6,277,19.644.0,17.593.0,25.587.1,14.272.0,33.304.0,35.262.0,35.273.0,37.277.0,38.277.0"}
P.entries["npc:ashlan-stonesmirk"] = {n="Ешлан Стоунсмерк",s="Ешлан Стоунсмерк — дворфійський знавець вибухівки з полку, що охороняє Дун Модр і Міст Тандол на півночі Багнокраю. Звідти він пильно стежить за небезпеками краю, які загрожують королівству Айронфордж.",h="Ешлан Стоунсмерк — дворфійський знавець вибухівки з полку, що охороняє Дун Модр і Міст Тандол на півночі...",ang={["faction:Alliance"]="Допомагаючи Ешланові, ви захищаєте стратегічний коридор, що з'єднує Лох Модан з Багнокраєм і північними землями Альянсу."},sec={{t="An Expert on the Border",b="Positioned at Dun Modr in the northern Wetlands, Ashlan Stonesmirk serves the regiment guarding the Thandol Span. His expertise with explosives makes him a useful contact when suspicious materials threaten dwarven defenses."},{t="Насувається темна загроза",b="When Chief Engineer Hinderweir finds a suspicious powder near the Stonewrought Dam, he sends it to Ashlan for examination. Ashlan identifies the powder as Seaforium and advises how to neutralize it."}},faq={{q="Де знайти Ешлана Стоунсмерка?",a="У цю епоху Ешлан Стоунсмерк служить у Дун Модрі на півночі Багнокраю, біля Мосту Тандол.",al={"місце ешлана","де ешлан стоунсмерк","ешлан стоунсмерк місце"}},{q="Яка роль Ешлана Стоунсмерка?",a="He is a dwarven explosives expert stationed with the regiment guarding Dun Modr and the Thandol Span. Hinderweir turns to him to identify a suspicious powder found near the Stonewrought Dam.",al={"хто такий ешлан стоунсмерк","призначення ешлана","що робить ешлан"}},{q="Які завдання дає Ешлан?",a="He assists adventurers during 'A Dark Threat Looms', examining suspicious powder sent by Chief Engineer Hinderweir.",al={"завдання ешлана","завдання від ешлана стоунсмерка"}}},fp="17,230,23.223.0,19.198.1,35.104.0,33.190.0,30.115.0"}
P.entries["npc:asterion"] = {n="Астеріон",s="Астеріон — давній дух із Високородних, прикутий до руїн Башал'Арану на Темному Узбережжі. Десять тисячоліть тому він був довіреною правою рукою правителя Атрікуса Нарассіна, але за загадкових обставин його ув'язнили в магічній печатці з місячного каменю, що тримала його і за життя, і після смерті. Сьогодні його примара досі прикута до зруйнованої святині, оточена демонічними звірами, і мріє про звільнення.",h="Астеріон — давній дух із Високородних, прикутий до руїн Башал'Арану на Темному Узбережжі.",kw={"астеріон","високородні","башал'аран","атрікус нарассін","печатка з місячного каменю","темне узбережжя"},ang={["class:Mage"]="За життя Астеріон славився майстерністю в таємній магії поряд із бойовою вправністю, тож він — цікавий приклад раннього чарівництва калдореїв.",["faction:Alliance"]="Астеріон — один із рідкісних духів Високородних, готових довіритися шукачам пригод з Альянсу: він просить їхньої допомоги, щоб зламати свою десятитисячолітню в'язницю.",["race:NightElf"]="Астеріон — трагічна реліквія часів до Розколу, що показує жорстоку внутрішню політику, яка поглинала Високородних іще до того, як Азшара покликала на їхні землі Палаючий Легіон."},sec={{t="Слуга давньої величі",b="До того як Великий Розкол зруйнував давній Калімдор, Башал'Аран і Амет'Аран були містами-сестрами, які благословила сама королева Азшара. Азшара призначила Атрікуса Нарассіна правити двома поселеннями, а Астеріон був його правою рукою. Шанований і за бойову вправність, і за володіння таємною магією, Астеріон жив серед мешканців Башал'Арану й часто подорожував між містами-сестрами, дбаючи про потреби їхніх громадян."},{t="В'язниця з місячного каменю",b="З причин, які загубилися в часі, Астеріон утратив прихильність свого володаря. Атрікус створив могутню печатку з місячного каменю — непроникну магічну клітку, що тримала Астеріона в Башал'Арані. Ув'язнення тягнулося століттями болісної неволі; гірше того, коли Астеріон нарешті помер, то з'ясував, що смерть не дає звільнення. Його дух лишився прикутим до зруйнованої святині — покинутий, коли світ розколовся, а давнє поселення заполонили демони."},{t="Помста з-за могили",b="Хоч мерзенні сатири й грелли блукають руїнами Башал'Арану, живлячись залишками таємної сили, святиню, де бродить привид Астеріона, вони оминають. Якщо шукач пригод з Альянсу відбере в сатирів печатку з місячного каменю й розіб'є її в Амет'Арані, примарні кайдани Астеріона нарешті спадуть. Та свобода не приносить йому спокою: відчуваючи, що Атрікус Нарассін досі існує, давній маг обертає думки від десяти тисяч років розпачу до помсти."}},faq={{q="Хто такий Астеріон?",a="Астеріон — привид давнього Високородного, що блукає руїнами Башал'Арана на Темному Узбережжі. До Розколу він був умілим магом і заступником правителя Атрікуса Нарассіна.",al={"лор астеріона","привид у башал'арані","привид ельф темне узбережжя"}},{q="Чому Астеріон ув'язнений?",a="Атрікус Нарассін скував Астеріона магічною печаттю з місячного каменю. Чому вони розсварилися, невідомо, але чари були такі сильні, що навіть смерть Астеріона не розірвала їх, і його дух на тисячоліття опинився в пастці.",al={"чому астеріон ув'язнений","в'язниця астеріона","чому атрікус ув'язнив астеріона"}},{q="Чому сатири в Башал'Арані на нього не нападають?",a="Сатири й грелли в руїнах ласують залишками тайної енергії Башал'Арана, але тримаються подалі від святилища, де скутий Астеріон. Вони заволоділи печаттю з місячного каменю, що тримає його в полоні, але самого духа не чіпають.",al={"чи сатири нападають на астеріона","чому демони лишають астеріона"}},{q="Де Астеріон жив за життя?",a="Астеріон жив серед народу Башал'Арана й часто їздив на південь, до міста-близнюка Амет'Арана, щоб вершити громадські справи під владою намісника Королеви Азшари.",al={"дім астеріона","звідки астеріон"}},{q="Що стається, коли його звільнити?",a="Asterion hopes that breaking the moonstone seal will end the imprisonment that continued beyond his death. The outcome of that attempt is described in the spoiler section.",al={"що буде з астеріоном","чи астеріон піде далі","помста астеріона"}},{q="Чи ворожий Астеріон до сучасних нічних ельфів?",a="Ні. Хоч він і давній Високородний із двору Королеви Азшари, Астеріон мирно ставиться до мандрівників Альянсу й просить їхньої допомоги, щоб розірвати давні магічні кайдани.",al={"чи астеріон дружній","союз астеріона"}}},fp="8,392,29.462.0,20.478.0,24.463.1,16.193.0,27.244.0,47.278.0,32.187.0,32.171.1,42.181.0"}
P.entries["npc:athridas-bearmantle"] = {n="Атрідас Бермантл",s="Атрідас Бермантл — друїд нічних ельфів, що мешкає в Доланаарі серед гілля Тельдрассила. Йому доручено берегти місцеве поселення, тож він посилає молодих шукачів пригод розслідувати скверну, що насувається на тутешню живність і сусідніх фурболгів-Вузлошкірів.",h="Атрідас Бермантл — друїд нічних ельфів, що мешкає в Доланаарі серед гілля Тельдрассила.",kw={"атрідас бермантл","друїд","доланаар","тельдрассил","фурболги","вузлошкіри","скверна"},ang={["class:Druid"]="Завдання Атрідаса проти зіпсутих Вузлошкірів і його турбота про давні реліквії безпосередньо торкаються рівноваги природи, яку друїди поклялися відновлювати.",["race:NightElf"]="Для молодих калдореїв, що залишають Тінедол, Атрідас — тверезе нагадування про біди Тельдрассила: вашій новій домівці вже загрожують зсередини."},sec={{t="Хранитель Доланаара",b="Атрідас Бермантл у Доланаарі — перша лінія оборони для нічних ельфів, що виходять із Тінедолу. Поки гілля новорослого Світового Дерева Тельдрассила виказує неприродні ознаки занепаду й неспокою, Атрідас невтомно керує місцевою розвідкою й захищає мирне містечко від довколишніх загроз."},{t="Недуга фурболгів",b="Чимало тривог Атрідаса пов'язано з сусіднім племенем фурболгів — Вузлошкірами. Колись мирні сусіди, Вузлошкіри піддалися божевіллю та скверні, що ширяться й отруюють їхніх шаманів і вождів, штовхаючи їх у шалену лють проти калдореїв. Атрідас гуртує охочих звитяжців, щоб стримати загрозу й викрити глибшу заразу, що пускає коріння в хащах."}},faq={{q="Хто такий Атрідас Бермантл?",a="Атрідас Бермантл — нічний ельф із Доланаара на острові Тельдрассил. Він організовує місцеву оборону й залучає шукачів пригод до боротьби з темними силами, що прокрадаються гілками Світового Древа.",al={"хто такий атрідас","лор атрідаса бермантла","атрідас доланаар"}},{q="Де знайти Атрідаса Бермантла?",a="Атрідас перебуває в Доланаарі — першому великому містечку, до якого доходять шукачі пригод із нічних ельфів, покинувши Тінедол на Тельдрассилі.",al={"місце атрідаса","де атрідас","знайти атрідаса бермантла"}},{q="На яких загрозах зосереджений Атрідас?",a="Атрідас зосереджений передусім на агресивних фурболгах-Вузлошкірах, що піддалися згубному впливу: він посилає мандрівників приборкати їхні напади, розслідувати їхнє божевілля й повернути важливі реліквії.",al={"завдання атрідаса","чого хоче атрідас","завдання атрідаса бермантла"}},{q="Чи родич Атрідас Броллові Бермантлу?",a="Атрідас має відоме прізвище Бермантл, як і славетні нічні ельфи на кшталт Бролла Бермантла, але яка саме між ними спорідненість, ніде прямо не сказано.",al={"чи родич броллу","зв'язок з броллом бермантлом","атрідас і брол"}},{q="Чому фурболги-Вузлошкіри нападають на Доланаар?",a="Плем'я Вузлошкірів стало жертвою темної, неприродної скверни, що просочується крізь Тельдрассил і довела їхніх шаманів і воїнів до шаленої ворожості до нічних ельфів.",al={"чому ґнарлпайни шалені","скверна ґнарлпайнів","ворожість фурболгів тельдрассил"}},{q="Яку роль Атрідас відіграє в захисті Тельдрассила?",a="Атрідас — один із перших охоронців і організаторів: він дбає, щоб скверні, яка шириться серед звірів і фурболгів Тельдрассила, дали відсіч, перш ніж вона заполонить Доланаар.",al={"роль атрідаса","важливість атрідаса"}}},fp="19,276,20.350.0,22.391.0,27.225.0,37.121.0,36.208.0,40.190.0,50.184.0,52.196.0"}
P.entries["npc:auntie-bernice-stonefield"] = {n="\"Тітонька\" Берніс Стоунфілд",s="«Тітонька» Берніс Стоунфілд — старша в родині Стоунфілдів, що живе на їхній садибі в південно-центральній частині Лісу Елвінн. Вона овдовіла, коли її чоловік загинув у військових походах королівства, і на всю долину славиться своїми пирогами зі свинячою грудинкою. Її можна знайти біля фермерського будинку разом із Ма Стоунфілд: вона пильно стежить за околицею і глибоко не довіряє суперникам-Маклурам.",h="«Тітонька» Берніс Стоунфілд — старша в родині Стоунфілдів, що живе на їхній садибі в південно-центральній...",kw={"берніс","тітонька","стоунфілд","маклур","намисто","пиріг зі свинячою грудинкою"},ang={["profession:Cooking"]="Пиріг зі свинячою грудинкою від Берніс славиться на весь Ліс Елвінн як класична страва ситної кухні людей-поселенців.",["race:Human"]="Берніс — втілення витривалості сільського люду Стормвінда: втративши чоловіка у війнах королівства, вона й далі тримає господарство й береже честь родини."},sec={{t="Життя в нестатках",b="Як і багато простих людей королівства Стормвінд, Берніс сповна заплатила за нескінченну війну. Втративши чоловіка у військових походах, вона доживає вік на родинній садибі серед рідні й допомагає матріархині Ма Стоунфілд у щоденних справах ферми. Попри втрату, вона годує родину й тримає господарство на ходу, а її пироги зі свинячою грудинкою знають по всій окрузі."},{t="Ворожнеча і зникле намисто",b="Давня неприязнь між Стоунфілдами й Маклурами — невіддільна частина світу Берніс. Коли її цінне родинне намисто зникло, вона одразу запідозрила малого Біллі Маклура. Та повернути пам'ятку виявляється складніше, ніж покарати сусідського шибеника за витівку: Біллі запевняє, що впустив його, коли тікав від грізного кобольда Золотозуба біля Копальні Фарґодіп."}},faq={{q="Хто така Тітонька Берніс Стоунфілд?",a="Вона — старійшина родини Стоунфілдів, що живе на Фермі Стоунфілдів на півдні Лісу Елвінн. Вдова війни, вона днює на фермі разом із Ма Стоунфілд і пече свої славетні пироги з грудинкою.",al={"хто така тітонька берніс","лор берніс стоунфілд","тітонька стоунфілд"}},{q="Що сталося з чоловіком Тітоньки Берніс?",a="Берніс овдовіла, коли її чоловік загинув у військовому поході за Королівство Стормвінд.",al={"чоловік тітоньки берніс","з ким була одружена берніс","вдова стоунфілд"}},{q="Чим славиться Тітонька Берніс?",a="Вона відома на всю околицю своїми ситними пирогами з грудинкою — такими смачними, що навіть пустотливі сусіди не можуть утриматися, щоб не виторгувати шматочок.",al={"пиріг берніс стоунфілд","пиріг зі свинячою грудинкою ельвін"}},{q="Чому Тітонька Берніс сердиться на Біллі Маклура?",a="Берніс підозрювала, що Біллі Маклур украв її дороге родинне намисто, і це підлило оливи у вогонь давньої ворожнечі між Стоунфілдами й Маклурами.",al={"ворожнеча з біллі маклуром","злодій намиста берніс","чому берніс ненавидить біллі"}},{q="Чи справді Біллі Маклур украв намисто?",a="Біллі знайшов намисто, але, коли ніс його, за ним погнався горезвісний кобольд Золотозуб біля Копальні Фарґодіп, і хлопець, тікаючи, загубив його. Згодом намистом заволодів Золотозуб.",al={"чи біллі вкрав намисто","у кого намисто стоунфілд","намисто золотозуба"}},{q="Де знайти Тітоньку Берніс?",a="Вона стоїть просто біля головного будинку на Фермі Стоунфілдів, на південь від дороги між Ґолдширом і Вестфолом, поряд із Ма Стоунфілд.",al={"місце тітоньки берніс","де берніс стоунфілд"}}},fp="27,445,18.404.0,33.426.1,33.214.0,42.114.0,34.177.0,47.161.0,46.200.1,32.171.0"}
P.entries["npc:austil-de-mon"] = {n="Остіл Де Мон",s="Остіл Де Мон — наставник воїнів-Відступників, що перебуває в Бріллі на Галявинах Тірісфалю. Його місце — у Таверні «Шибеничний Кінець», де він навчає щойно повсталих воїнів, які прагнуть відточити бойову майстерність на службі Темній Леді.",h="Остіл Де Мон — наставник воїнів-Відступників, що перебуває в Бріллі на Галявинах Тірісфалю.",kw={"остіл де мон","наставник воїнів","брілл","шибеничний кінець","похоронний подзвін","галявини тірісфалю","воїн"},ang={["class:Warrior"]="Для воїнів-Відступників, які покидають Похоронний Подзвін, Остіл Де Мон — один із головних наставників на Галявинах Тірісфалю: він дає поради й навчає нових умінь.",["race:Undead"]="Остіл гартує щойно повсталих немертвих, перетворюючи їх на грізних бійців передової, готових боронити Лордерон від Погибелі й Багряного Хрестового Походу."},sec={{t="Ветеран із Брілла",b="Остіл Де Мон, якого можна знайти в Таверні «Шибеничний Кінець» у Бріллі, — один із перших наставників для воїнів-Відступників, що виходять із Похоронного Подзвону. Колись у цій корчмі пили й відпочивали живі, а тепер Остіл використовує похмурий притулок, щоб навчати щойно визволених немертвих сирої бойової дисципліни й безжальних прийомів бою проти ворогів, що оточують королівство."}},faq={{q="Хто такий Остіл Де Мон?",a="Остіл Де Мон — наставник воїнів із нежиті в Бріллі на Галявинах Тірісфалю, що навчає бійців-Відступників.",al={"остіл де мон","остіл","хто такий остіл"}},{q="Де знайти Остіла Де Мона?",a="Він перебуває в Таверні «Шибеничний Кінець» у Бріллі на Галявинах Тірісфалю, трохи на північ від Андерсіті.",al={"місце остіла де мона","де остіл","остіл де мон на мапі"}},{q="Яку роль він відіграє в Бріллі?",a="Він навчає новачків-воїнів бойових прийомів, стійок і вмінь, щоб зміцнити військо Відступників проти місцевих загроз.",al={"що робить остіл","остіл вчитель","роль остіла"}}},fp="13,225,25.387.0,21.134.0,31.109.0,32.147.0"}
P.entries["npc:ayanna-everstride"] = {n="Аянна Еверстрайд",s="Аянна Еверстрайд — калдорейська наставниця мисливців, що перебуває в Алдрассилі, у Тінедолі на Тельдрассилі. Вона навчає молодих рейнджерів — нічних ельфів основ влучної стрільби, вистежування й виживання в дикому краю. Молоді мисливці, роблячи перші кроки під віттям Світового Дерева, шукають її проводу, щоб відточити лісову дисципліну.",h="Аянна Еверстрайд — калдорейська наставниця мисливців, що перебуває в Алдрассилі, у Тінедолі на Тельдрассилі.",kw={"аянна еверстрайд","мисливець","наставниця","алдрассил","тінедол","тельдрассил","вистежування"},ang={["class:Hunter"]="Для молодих мисливців — нічних ельфів, що починають шлях у Тінедолі, Аянна Еверстрайд — найперша наставниця з володіння зброєю, вистежування й виживання в неприборканих нетрях.",["race:NightElf"]="Перебуваючи у священних порожнинах Алдрассила, Аянна допомагає берегти молоде Світове Дерево, готуючи новобранців захищати навколишній ліс від скверни, що насувається."},sec={{t="Наставниця в Тінедолі",b="Умостившись усередині Алдрассила в самому серці Тінедолу, Аянна Еверстрайд готова навчати щойно пробуджених калдореїв звичаїв дикої природи. Для нічних ельфів мисливець — не просто ловець чи влучний стрілець, а незамінний охоронець священних лісів. Аянна дає настанови з ранніх бойових прийомів, допомагаючи новачкам опанувати дальній бій і вижити в небезпечних лісах Тельдрассила."}},faq={{q="Хто така Аянна Еверстрайд?",a="Аянна Еверстрайд — наставниця мисливців із нічних ельфів в Алдрассилі, у початковому краї Тінедолу на Тельдрассилі. Вона навчає мисливців-початківців основ бою й виживання в дикій природі.",al={"аянна еверстрайд","хто така аянна","вчитель мисливців алдрассілу"}},{q="Де знайти Аянну Еверстрайд?",a="Вона перебуває всередині Алдрассила — величезного порожнистого дерева-поселення в Тінедолі, у самому серці Тельдрассила.",al={"місце аянни","де аянна","знайти аянну еверстрайд"}},{q="Які завдання пов'язані з Аянною Еверстрайд?",a="Нових мисливців із нічних ельфів направляють до Аянни першими навчальними завданнями, як-от отримання Гравірованого Сигіла від перших наставників, після чого вона дає вступне навчання майбутнім лісовим слідопитам.",al={"завдання аянни","завдання гравірованого сигіла","видавець завдання аянни"}}},fp="17,354,22.416.0,25.214.0,35.133.0,38.207.0"}
P.entries["npc:ayessa-dawnsinger"] = {n="Аєсса Донсінґер",s="Аєсса Донсінґер — провідниця Небороджених у Валанаарі на Острові Зефрас. Вона очолює Вітротворців і веде Небороджених, що стали на бік Орди, крізь випробування й політичні чвари.",h="Аєсса Донсінґер — провідниця Небороджених у Валанаарі на Острові Зефрас.",kw={"аєсса донсінґер","вітротворці","небороджені","валанаар","острів зефрас","орда"},ang={["faction:Horde"]="Для Орди Аєсса Донсінґер — головна союзниця серед Небороджених, що тримає її присутність і дипломатичні зв'язки на Острові Зефрас.",["race:Skyborne"]="Як провідниця Вітротворців, Аєсса втілює бачення тих Небороджених, що обирають солідарність з Ордою, аби вберегти своє майбутнє."},sec={{t="Провідниця Вітротворців",b="У поселенні Валанаар на Острові Зефрас Аєсса Донсінґер — верховна провідниця Вітротворців, тієї частини Небороджених, що пристала до Орди. Звідси вона керує важливими справами по всьому острову: протистоїть зовнішнім загрозам, гамує внутрішні розколи й дбає про виживання свого народу, що шукає союзів у Калімдорі й далі."},{t="Боротьба за Зефрас",b="Аєсса відіграє ключову роль у розв'язанні конфліктів на острові: вона посилає довірених героїв на боротьбу з некерованими конструктами, з ворожими постатями на кшталт Лортуни й з долею, що чекає на Небороджених. Її влада веде Вітротворців крізь напружені політичні й збройні протистояння, щоб їхній голос і сила й далі важили в Орді."}},faq={{q="Хто така Аєсса Донсінґер?",a="Аєсса Донсінґер — помітна постать серед Небороджених, що очолює Вітротворців — угруповання Небороджених на Острові Зефрас, союзне Орді.",al={"лор аєсси","хто така аєсса","історія аєсси донсінґер"}},{q="Де знайти Аєссу Донсінґер?",a="Вона перебуває в поселенні Валанаар на Острові Зефрас.",al={"де аєсса","місце аєсси","аєсса донсінґер на мапі"}},{q="Хто такі Вітротворці?",a="Вітротворці — угруповання Небороджених, союзне Орді, яке веде Аєсса Донсінґер зі своєї бази у Валанаарі.",al={"фракція вітротворців","хто такі вітротворці"}},{q="Яку роль Аєсса відіграє в місцевих завданнях?",a="Аєсса дає кілька важливих завдань щодо оборони острова: розслідувати бешкет здичавілих механізмів, протистояти Лортуні й вирішити подальшу долю Зефраса.",al={"завдання аєсси","ланцюжок завдань аєсси"}}},fp="17,179,25.385.0,24.356.1,25.138.0,37.61.0,25.121.0,38.174.0"}
P.entries["npc:azar-stronghammer"] = {n="Азар Стронгхаммер",s="Азар Стронгхаммер — дворфійський паладин, що служить у Ґуральні Тандербрю в Хараносі. Сам пройшовши навчання святих мистецтв, він наставляє новонавернених дворфійських звитяжців Святого Світла й скеровує найздібніших новобранців на вищу науку до Айронфорджа.",h="Азар Стронгхаммер — дворфійський паладин, що служить у Ґуральні Тандербрю в Хараносі.",kw={"азар стронгхаммер","паладин","ґуральня тандербрю","харанос","дун мороґ","тіза баттлфордж","фоліант божественності"},ang={["class:Paladin"]="Для дворфійських паладинів, що починають шлях у Дун Мороґу, Азар — важливий перший наставник, який згодом скерує вас до Айронфорджа здобувати священний Фоліант Божественності.",["race:Dwarf"]="Азар — взірець того, як дворфи прийняли Святе Світло: відданість святій праведності чудово уживається з теплим вогнищем і кухлем «Тандербрю»."},sec={{t="Провідник серед холоду",b="Паладинів частіше пов'язують із величними соборами людей, але дворфи Каз Модану щиро прийняли чесноти Святого Світла. У Ґуральні Тандербрю в Хараносі Азар Стронгхаммер наглядає за щойно висвяченими дворфійськими паладинами, що стають на ноги серед крижаних схилів Дун Мороґа. Опанувавши власні бойові й духовні обітниці, він став приступним наставником. Коли новачок виявляє досить відданості й духовної зрілості, Азар скеровує його гірською стежкою до Айронфорджа — навчатися в досвідчених звитяжців на кшталт Тізи Баттлфордж."}},faq={{q="Хто такий Азар Стронгхаммер?",a="Азар Стронгхаммер — дворф, наставник паладинів у Ґуральні Тандербрю в Хараносі. Він наглядає за першими кроками молодих дворфських святих воїнів, перш ніж відправити їх далі до столиці.",al={"хто такий азар","роль азара стронгхаммера","вчитель паладинів хараноса"}},{q="Де знайти Азара Стронгхаммера?",a="Він перебуває в Ґуральні Тандербрю в селищі Харанос серед засніжених пагорбів у центрі Дун Мороґу.",al={"місце азара стронгхаммера","де азар","знайти азара стронгхаммера"}},{q="Чого він навчає молодих паладинів?",a="Азар навчає новачків основ бойового мистецтва й заклять паладина. Коли учень готовий пройти випробування Фоліанта Божественності, щоб опанувати священні обряди воскресіння, Азар посилає його до Тізи Баттлфордж в Айронфорджі.",al={"що робить азар","завдання азара","завдання паладинів азара"}},{q="Чому наставник паладинів сидить у ґуральні?",a="У культурі дворфів громадське життя, товариськість і міцне пиво переплетені. Ґуральня Тандербрю — серце суспільного життя й оборони Хараноса, тож це природне місце збору для місцевих захисників і наставників.",al={"чому паладин у ґуральні","паладин у барі","вчитель в ґуральні"}}},fp="17,275,19.596.0,25.207.0,37.125.0,48.237.0,51.222.0"}
P.entries["npc:azuregos"] = {n="Азурегос",s="Азурегос — ексцентричний синій дракон, що стоїть на сторожі узбережжя Азшари й оберігає прадавні реліквії Високороджених. Ткач Чарів Малігос доручив йому берегти величезну магічну силу; Азурегос більше любить тихі студії, ніж насильство, але без вагань відмахнеться від будь-якого шукача пригод, якому стане дурості порушити його варту.",h="Азурегос — ексцентричний синій дракон, що стоїть на сторожі узбережжя Азшари й оберігає прадавні реліквії...",kw={"азурегос","синій дракон","малігос","елдарат","синя скалка скіпетра","моз","азшара"},ang={["class:Mage"]="Як посланець синього драконячого роду, Азурегос утілює майстерність і лад у тайній магії та вважає смертних чародіїв необачними дітьми, що бавляться силами, яких не розуміють.",["race:NightElf"]="Азурегос блукає серед уламків Елдарата й пильно стереже ті самі чари Високороджених, що під час Розколу мало не розірвали Калімдор на шматки."},sec={{t="Вартовий Елдарата",b="Азурегоса вабили насичені магією береги Азшари, і своїм прихистком він обрав прадавні руїни Елдарата. На цих розтрощених узбережжях Великий Розкол пережило безліч реліквій, і Азурегос як слуга Малігоса вважає своїм священним обов'язком тримати такі могутні артефакти подалі від необачних смертних. Замість ховатися в темній печері, він вільно блукає скелями й пляжами, гордо величаючи себе володарем усієї магії в цьому краї. Попри уїдливе почуття гумору, він люто боронить скарби Азшари від нескінченного потоку шукачів пригод, що жадають слави чи здобичі."},{t="Мимовільний охоронець",b="Після Війни Мінливих Пісків на Азурегоса поклали обов'язок берегти Синю Скалку Скіпетра — частину ключа, потрібного, щоб зламати бар'єр біля Муру Скарабея. Утомившись від постійного клопоту, шукачів скарбів і самозваних героїв, яких вабив артефакт, хитрий дракон зрештою позбувся реліквії в найбезцеремонніший спосіб, який тільки можна уявити: згодував її зачарованій рибці на ім'я Моз. Тож тепер кожному, хто хоче здобути скалку, доведеться нишпорити в глибинах, а не дошкуляти йому."}},faq={{q="Хто такий Азурегос?",a="Азурегос — могутній синій дракон, якого Аспект драконів Малігос послав пильнувати руїни Азшари. Багато драконів похмурі чи гнівливі, а Азурегос помітно дивакуватий і дотепний, проте нещадно розчавить смертних, що заважають його магічним студіям або зазіхають на скарби Елдарата.",al={"лор азурегоса","синій дракон в азшарі","історія азурегоса"}},{q="Що Азурегос робить в Азшарі?",a="Він прибув вивчати й берегти могутні магічні артефакти, які лишила давня цивілізація Високородних після Великого Розколу. Він стереже руїни Елдарата від безрозсудних грабіжників, що шукають небезпечної магії.",al={"чому азурегос тут","що азурегос робить в азшарі","призначення азурегоса"}},{q="Що пов'язує його зі Стіною Скарабея?",a="Azuregos was entrusted with the Blue Scepter Shard, part of the key that can reopen the Scarab Wall. Finding out what became of it requires speaking with the dragon.",al={"уламок скіпетра азурегоса","азурегос рухливі піски","уламок рухливих пісків"}},{q="Чому в Азшарі з'являється його дух?",a="На Азурегоса часто нападають загони шукачів пригод, що полюють на магічні скарби чи драконячу луску. Коли його вбито, його дух лишається біля берегів і невимушено розмовляє з перехожими, чекаючи, поки відродиться його тіло.",al={"дух азурегоса","привид азурегоса","чому азурегос привид"}}},fp="8,310,24.599.0,21.501.1,16.296.0,27.217.0,42.165.1,38.248.0"}
P.entries["npc:bailiff-conacher"] = {n="Пристав Конакер",s="Пристав Конакер служить у Ратуші Лейкшира головним виконавцем вироків при Магістратові Соломоні. Йому доручено підтримувати громадський порядок і втілювати місцеві постанови, тож він звертається до незалежних звитяжців, щоб утверджувати закони Стормвінда в охоплених війною Горах Редріджу.",h="Пристав Конакер служить у Ратуші Лейкшира головним виконавцем вироків при Магістратові Соломоні.",kw={"пристав конакер","магістрат соломон","закон соломона","ратуша лейкшира","гноли Тіньової Шкури","морґант"},ang={["faction:Alliance"]="Пристав Конакер уособлює хиткий вплив стормвіндського правосуддя в прикордонному місті, яке здебільшого покинули напризволяще."},sec={{t="Правосуддя в Лейкширі",b="У Ратуші Лейкшира Пристав Конакер пліч-о-пліч із Магістратом Соломоном підтримує законну владу в Горах Редріджу. Містечко з усіх боків облягають орки Блекрок і місцеві гноли, тож Конакер не може покладатися ні на звичні громадські процедури, ні на королівські гарнізони. Натомість він видає постанови, які дають мандрівникам право чинити найвищу кару від імені королівства."},{t="Закон Соломона в дії",b="Коли темний маг Морґант захопив Вежу Ілґалара й підкорив своїй волі місцевих гнолів Тіньової Шкури, суд Лейкширу визнав цих тварюк співучасниками державної зради. Допомога втікачеві й злочинцеві королівства Стормвінд карається смертю, тож Конакер застосовує Закон Соломона. Він посилає шукачів пригод прочісувати хребти в пошуках гнолів Тіньової Шкури і вимагає їхні амулети як законний доказ того, що закон корони виконано."}},faq={{q="Хто такий Пристав Конакер?",a="Пристав Конакер — посадовець Суду Лейкширу, що допомагає Магістратові Соломону підтримувати цивільну владу й закони Стормвінда в Горах Редріджу.",al={"роль пристава конакера","хто такий конакер","лор конакера"}},{q="Де знайти Пристава Конакера?",a="Він перебуває в Ратуші Лейкшира на північному боці мосту в Горах Редріджу.",al={"місце пристава конакера","де конакер","конакер редрідж"}},{q="Що таке Закон Соломона?",a="Це судове застосування законів Стормвінда за указом Магістрата Соломона. Згідно з ним, допомога відомим злочинцям, як-от чаклунові-відщепенцю Морґанту, карається смертю, тож союзні йому гноли Тіньової Шкури за законом приречені на страту.",al={"що таке закон соломона","закон соломона гноли","закон тіньової шкури"}},{q="Навіщо Конакерові амулети Тіньової Шкури?",a="Амулети — перевірний доказ того, що гнола Тіньової Шкури вбито на виконання вироку Лейкширу тим, хто допомагає Морґантові.",al={"чому збирати амулети","навіщо амулети тіньової шкури"}}},fp="16,286,20.413.0,22.456.0,24.161.0,36.103.0,22.240.0,46.153.0"}
P.entries["npc:bailor-stonehand"] = {n="Бейлор Стоунгенд",s="Бейлор Стоунгенд — вправний дворфійський коваль, що живе в Телсамарі, у Лох Модані. Знаний своїм умінням працювати з металом, він колись навчав людського зброяра Джордана Стілвелла й виплавляє особливий сплав, без якого не обходиться жодна майстерна зброя. Нині його кузня потерпає, бо огри Мо'ґрош з місцевих пагорбів напали на його вантажі руди й пограбували їх.",h="Бейлор Стоунгенд — вправний дворфійський коваль, що живе в Телсамарі, у Лох Модані.",kw={"бейлор стоунгенд","телсамар","коваль","сплав","джордан стілвелл","кулак верігана","огри"},ang={["class:Paladin"]="Паладини, які прагнуть викувати легендарний Кулак Верігана, йдуть слідами Бейлора: рецепт свого особливого сплаву він передав просто Джорданові Стілвеллу, щоб той викував священний молот.",["profession:Blacksmithing"]="Як майстер-металург, чиї особливі сплави славляться по всьому Каз Модану, Бейлор утілює давнє дворфійське прагнення довести до досконалості рідкісні й міцні метали."},sec={{t="Майстер кузні",b="Бейлор Стоунгенд працює в дворфійському поселенні Телсамар і уособлює незмінне ремесло ковалів Лох Модану. Він славиться пильним оком на сировину й умінням виплавляти особливі сплави, а його знання сягають далеко за межі Каз Модану. Бейлор був наставником славетного людського коваля Джордана Стілвелла: навчив його основ металургії й поділився рецептами, які згодом стали незамінними для кування освяченої паладинської зброї — як-от Кулака Верігана."},{t="Огряча засідка",b="Попри тиху майстерність, ремесло Бейлора не вберігається від загроз, що наростають у Лох Модані. Вантажі добірної руди, що прямували до його кузні, стали здобиччю огрів Мо'ґрош, які окопалися в пагорбах на північному сході. Без сировини Бейлор не може виплавляти свої рідкісні сплави, тож мусить покладатися на мандрівників і союзників, які відберуть украдені припаси з таборів звірюк."}},faq={{q="Хто такий Бейлор Стоунгенд?",a="Бейлор Стоунгенд — дворф, досвідчений коваль із Телсамара в Лох Модані. Він відомий тим, що виплавляє рідкісні металеві сплави, а колись навчав зброярського ремесла Джордана Стілвелла.",al={"бейлор стоунгенд","хто такий бейлор","коваль телсамара"}},{q="Що пов'язує Бейлора з Джорданом Стілвеллом?",a="Колись Бейлор був учителем Джордана Стілвелла, коваля-людини, що працює біля Айронфорджа. Стілвелл казав, що саме Бейлор відкрив йому секрети роботи з очищеною рудою, зокрема особливий сплав, з якого кують святий бойовий молот Кулак Верігана.",al={"бейлор і джордан","вчитель джордана стілвелла","коваль кулака веригана"}},{q="Що сталося з рудою Бейлора?",a="Партію сирої руди Бейлора перехопили й пограбували огри Мо'ґрош, що живуть на пагорбах північного сходу Лох Модану, і він лишився без матеріалів для своєї особливої металургії.",al={"руда бейлора","хто вкрав руду бейлора","постачання огрів"}},{q="Де знайти Бейлора Стоунгенда?",a="Бейлора можна знайти неподалік від центру Телсамара — головного дворфського містечка на основній дорозі Лох Модану.",al={"місце бейлора","де бейлор стоунгенд","бейлор телсамар"}}},fp="16,354,19.487.0,11.412.0,24.204.0,47.240.0,30.198.0,36.121.0"}
P.entries["npc:baine-bloodhoof"] = {n="Бейн Бладгуф",s="Бейн Бладгуф — син Верховного Вождя Кайрна Бладгуфа й чинний захисник Села Бладгуф у Малгорі. Поки його батько править племенами з високих плато Тандер Блафу, Бейн безпосередньо керує місцевою обороною: розслідує промислове визискування, що насувається, і боронить край від здичавілих хижаків. Він — важлива ланка між юними тауренськими хоробрими та прадавньою мудрістю свого клану.",h="Бейн Бладгуф — син Верховного Вождя Кайрна Бладгуфа й чинний захисник Села Бладгуф у Малгорі.",kw={"бейн бладгуф","таурен","село бладгуф","малгор","кайрн","захисник","кентаври"},ang={["class:Shaman"]="Бейн понад усе шанує духів: він посилає мандрівників змусити замовкнути дворфські машини й безоглядних копачів, перш ніж вирветься на волю лють земляних елементалів.",["faction:Horde"]="Бейн утілює спокійну мудрість і тиху військову силу, що закріплюють тауренів в Орді Тралла, і дає настанови тим, хто проходить через центральний Малгор.",["race:Tauren"]="Бейн утілює і почесний рід Верховного Вождя Кайрна, і живу надію молодих племен, зібраних по рівнинах Малгору."},sec={{t="Син Верховного Вождя",b="Народжений від Кайрна й покійної Тамаали, Бейн провів юність у мандрах зі своїм кочовим народом, перш ніж той здобув багаті луки Малгору. Його ранні роки позначила повсякчасна загроза від кланів кентаврів. Невдовзі після Третьої війни бойовий загін кентаврів під проводом Хіраґґа захопив юного Бейна, і Кайрн поринув у скорботне заціпеніння, яке ледь не знищило щойно засновані поселення. Лише завдяки відвазі захисника Рекссара Бейна визволили з полону. Той порятунок повернув Кайрнові дух, і таурени змогли стати поруч з Ордою Тралла проти загарбників із Кул Тірасу й закріпитися на континенті."},{t="Охоронець Села Бладгуф",b="Замість лишатися у відносному затишку столичних плато, Бейн воліє жити серед рідні в Селі Бладгуф. Що старшим стає Кайрн, то більший тягар опікунства несе Бейн, уособлюючи наступне покоління тауренського проводу. Він скеровує хоробрих і союзників, що навідуються, на боротьбу з неспокійними гнолами Блідоманами, які дошкуляють кордонам, і пильно стежить за підозрілими сторонніми впливами, що загрожують природній рівновазі Малгору. Щоразу, як Кайрн залишає столицю в державних справах, Бейн виступає чинним провідником об'єднаних племен."},{t="На захист Матері-Землі",b="Окрім прикордонних сутичок, Бейн має справу з новітніми зайдами, яким байдужа духовна рівновага. На сході гоблінська Венчурна Компанія глибоко врізається у священний край, а дворфські шукачі з Бель Модану копають прадавню землю на Розкопках Бел'дуну. Бейн обстоює тверду, але виважену відповідь: спробувати застерегти копачів і знищити їхнє руйнівне обладнання, а не кидатися в безглузде кровопролиття. Він попереджає, що жорстоке копання дворфів ранить духів землі, та копачі не бажають слухати."}},faq={{q="Хто такий Бейн Бладгуф?",a="Бейн — єдиний син Кайрна Бладгуфа, Верховного Вождя тауренських племен. Він опікується обороною й племінними справами в Селі Бладгуф: веде місцевих сміливців і захищає Малгор, поки його батько править із Тандер Блафа.",al={"лор бейна","хто такий бейн","син кайрна"}},{q="Де зараз знайти Бейна?",a="Бейн стоїть у Селі Бладгуф у центрі Малгору, трохи на південь від Тандер Блафа. Його можна знайти біля середмістя: він роздає доручення новоприбулим шукачам пригод.",al={"місце бейна","де бейн","де бейн бладгуф"}},{q="Як Бейна врятували від кентаврів?",a="Після Третьої війни ватажок кентаврів на ім'я Хірагг захопив Бейна в полон, і Кайрн поринув у гнітючий відчай. Звіролов Рекссар розшукав вигнанців Бована Віндтотема, вистежив кентаврів до їхнього табору, вбив викрадачів і цілим повернув Бейна батькові.",al={"бейна викрали","рексар рятує бейна","бейн у полоні"}},{q="З якими клопотами Бейн дає раду в Селі Бладгуф?",a="Бейн організовує боротьбу з агресивними гнолами Пейлмейн, що не дають спокою місцевим стадам, і пильно стежить за чужинцями-загарбниками, як-от гоблінська Венчурна Компанія та дворфи-копачі Альянсу, що тривожать землю.",al={"завдання бейна","що робить бейн","клопоти села бладгуф"}},{q="Як Бейн ставиться до дворфських розкопок Бел'дуну?",a="Бейн вважає, що жорстокі підриви копачів Бел'дуну шкодять духам землі. Він хоче вивести з ладу їхні промислові знаряддя й налякати їх, перш ніж безрозсудне копання накличе на край відплату стихій.",al={"бейн і дворфи","розкопки бел'дуна","дворфські розкопки малгор"}},{q="Чи стане Бейн Верховним Вождем після Кайрна?",a="Як улюблений син Кайрна і його права рука, Бейн уже тимчасово править, коли Кайрна немає в Тандер Блафі. Його загалом вважають природним спадкоємцем, що в майбутньому поведе об'єднані племена тауренів.",al={"чи бейн стане вождем","майбутній верховний вождь","спадкоємець кайрна"}}},fp="15,429,25.664.0,29.574.0,26.551.0,23.242.0,35.176.0,39.276.0,53.220.0,55.239.0,44.219.0"}
P.entries["npc:balir-frosthammer"] = {n="Балір Фростгаммер",s="Балір Фростгаммер — дворфійський захисник, що служить у Долині Холодного Хребта в Дун Мороґу. Стривожений раптовими й зухвалими вторгненнями трогів Кам'янощелепів на дворфійські землі, він набирає новачків-шукачів пригод, щоб зупинити навалу, перш ніж долину буде захоплено.",h="Балір Фростгаммер — дворфійський захисник, що служить у Долині Холодного Хребта в Дун Мороґу.",kw={"балір фростгаммер","захисник","троги","скелещелепи","долина холодного хребта","таннок фростгаммер","дун мороґ"},ang={["faction:Alliance"]="Зусилля Баліра зберігають Долину Холодного Хребта безпечною — важливим плацдармом для новобранців Альянсу, які починають вишкіл у Каз Модані.",["race:Dwarf"]="Для молодих дворфів Балір Фростгаммер утілює передову оборону батьківщини, даючи їм найперші нагоди захистити Дун Мороґ від підземних загроз."},sec={{t="Утримати Долину Холодного Хребта",b="Із засніженого закутка Долини Холодного Хребта Балір Фростгаммер стежить за периметром проти небезпек, що насуваються. Долина довго була безпечним притулком і навчальним майданчиком для дворфійських і гномських новачків, але недавні заворушення під землею випустили на поверхню лютих трогів Кам'янощелепів. Балір одним із перших б'є на сполох, згуртовуючи новоприбулих новобранців, щоб вибити трогів, перш ніж ті прорвуться глибше в Дун Мороґ."},{t="Рід Фростгаммерів",b="Носячи горде прізвище Фростгаммер, Балір, можливо, споріднений із Танноком Фростгаммером із Хараноса. Їхня родина непохитно стоїть на службі Айронфорджу, пильнуючи, щоб холодні гірські перевали лишалися безпечними для подорожніх, шахтарів і горян, навіть коли загроз у краї стає дедалі більше."}},faq={{q="Хто такий Балір Фростгаммер?",a="Балір Фростгаммер — дворф із Долини Холодного Хребта в Дун Мороґу. Він доручає новоприбулим шукачам пригод прорідити ворожих Кам'янощелепих трогів, що загрожують обороні долини.",al={"хто такий балір","балір фростгаммер хто це"}},{q="Чому Балір непокоїться через трогів?",a="Кам'янощелепі троги нещодавно вилізли на поверхню чималою силою, порушили спокій Долини Холодного Хребта й нападають на дворфські поселення. Балір бачить у них дедалі більшу загрозу, яку треба стримати якнайраніше.",al={"чому троґи","проблема з троґами холодний хребет"}},{q="Чи родич Балір Таннокові Фростгаммеру?",a="Можливо. Балір має те саме прізвище Фростгаммер, що й Таннок Фростгаммер із Хараноса, а це натякає на родинний зв'язок, хоч його й не підтверджено.",al={"родич таннока","родина фростгаммерів"}}},fp="17,255,24.445.0,23.286.0,25.182.0,40.203.0,39.136.0"}
P.entries["npc:balthule-shadowstrike"] = {n="Балтул Шедовстрайк",s="Балтул Шедовстрайк — розвідник нічних ельфів, що несе службу на півночі Темного Узбережжя поблизу Вежі Альталакса. Як передовий агент Делґрена Очищувача, він стежить за зловісними культистами й темними чаклунами, що засіли в давніх ельфійських руїнах. Шукачів пригод, що мандрують північним узбережжям, часто посилають до нього, щоб допомогти розкрити й зірвати темні ритуали у вежі.",h="Балтул Шедовстрайк — розвідник нічних ельфів, що несе службу на півночі Темного Узбережжя поблизу Вежі...",kw={"балтул шедовстрайк","розвідник","вежа альталакса","культ темного берега","делґрен очищувач","темне узбережжя"},ang={["class:Rogue"]="Діючи глибоко у ворожому краї просто під носом у небезпечних чаклунів, Балтул утілює терпіння й пильність справжнього ельфійського розвідника.",["faction:Alliance"]="Балтул — важлива передова ланка для бійців Альянсу, яких посилають з Обердайна на північ, щоб викорінити темних культистів довкола Вежі Альталакса.",["race:NightElf"]="Для нічних ельфів осквернення давніх руїн Калімдору мерзенними культистами — обурлива кривда, за яку Балтул прагне помститися, поки скверна не поширилася їхніми землями."},sec={{t="Розвідник у тінях",b="Причаївшись у нетрях трохи на захід від Вежі Альталакса, Балтул Шедовстрайк несе самотню й небезпечну варту. Північ Темного Узбережжя повна неспокійних духів і затінених руїн, але те, що коїться довкола вежі, — особливо гостра загроза. Балтул діє за вказівками Делґрена Очищувача, стежачи за пересуваннями темних чаклунів, що прокралися до давніх решток Високородних."},{t="Викриття культу",b="Чаклуни й культисти, що захопили Вежу Альталакса, займаються темною забороненою магією, видобуваючи артефакти й душі з довколишніх руїн. Балтул покладається на мандрівних героїв Альянсу: вони мають проникнути до вежі, знищити ватажків культу й добути пергаменти й талісмани, що розкривають справжні масштаби їхніх викликів."}},faq={{q="Хто такий Балтул Шедовстрайк?",a="Балтул Шедовстрайк — розвідник із нічних ельфів на півночі Темного Узбережжя. Він передовий розвідник і агент, що разом із Делґреном Очищувачем стежить за лихими справами культистів у краї.",al={"хто такий балтул","роль балтула","балтул шедовстрайк нпс"}},{q="Де перебуває Балтул Шедовстрайк?",a="Він стоїть на півночі Темного Узбережжя, трохи на захід від зловісної Вежі Альталакса неподалік від берега.",al={"де балтул","місце балтула","знайти балтула шедовстрайка"}},{q="Яке в нього завдання біля Вежі Альталакса?",a="Його послали стежити за темними заклиначами й культистами, що оселилися у Вежі Альталакса: він збирає відомості й допомагає готувати удари, щоб зірвати їхні мерзенні ритуали.",al={"чому балтул тут","чого хоче балтул","завдання біля вежі альталакса"}},{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — паладин Срібного світанку з Поста Маестри в Ашенвалі, що керує боротьбою з темними силами, які мучать північ Темного Узбережжя. Балтул — його передові очі й вуха.",al={"хто такий делґрен","начальник балтула","зв'язок з делґреном"}},{q="Які вороги захопили Вежу Альталакса?",a="Вежу й землі довкола заполонили темні культисти, чаклуни й викликані демонічні чи тіньові прислужники, що прагнуть використати давню силу Високородних для лихих цілей.",al={"хто у вежі","вороги альталакса","культисти вежі альталакса"}},{q="Чому Альянс цікавиться цими руїнами?",a="Вежа Альталакса — давня ельфійська споруда. Мерзенне чаклунство й демонічна діяльність так близько від ельфійських земель — пряма загроза безпеці Темного Узбережжя й нічних ельфів Дарнасуса.",al={"чому альянсу ці руїни","присутність альянсу на темному узбережжі"}}},fp="21,409,22.428.0,19.373.1,29.206.0,39.113.0,46.201.0,28.215.0,51.179.0,46.215.0"}
P.entries["npc:barithras-moonshade"] = {n="Барітрас Муншейд",s="Барітрас Муншейд — нічний ельф, мешканець Обердайна на Темному Узбережжі. У прибережному поселенні він звертається до мандрівників, готових досліджувати темні нетрі й збирати рідкісні підземні рослини.",h="Барітрас Муншейд — нічний ельф, мешканець Обердайна на Темному Узбережжі.",kw={"барітрас муншейд","обердайн","бліда поганка","ону","гриби","темне узбережжя"},ang={["profession:Herbalism"]="Ті, хто відчуває рослинний світ, оцінять інтерес Барітраса до незвичайних печерних грибів Темного Узбережжя.",["race:NightElf"]="Барітрас допомагає своїм родичам в Обердайні берегти Темне Узбережжя: стежить за його рослинами й підтримує зв'язок із давніми охоронцями лісу на кшталт Ону."},sec={{t="Мешканець Обердайна",b="Барітрас Муншейд, що стоїть на варті в селищі Обердайн, долучається до зусиль нічних ельфів вивчати неспокійну землю Темного Узбережжя й дбати про неї. Він посилає мандрівників у сусідні підземні печери збирати певні гриби, як-от бліді поганки, для досліджень і вжитку."},{t="Зв'язки з Прадавніми",b="Окрім місцевих рослин, Барітрас допомагає скеровувати здібних шукачів пригод на південь, щоб ті зустрілися з Ону — одним із шанованих прадавніх, що прагнуть зцілити отруєну землю Темного Узбережжя й заспокоїти її неспокійних духів природи."}},faq={{q="Хто такий Барітрас Муншейд?",a="Барітрас Муншейд — нічний ельф з Обердайна на туманному узбережжі Темного Узбережжя. Він доручає шукачам пригод досліджувати місцеві рослини й зв'язуватися з охоронцями краю.",al={"хто такий барітрас","барітрас муншейд","хто цей нічний ельф"}},{q="Де знайти Барітраса Муншейда?",a="Він стоїть у портовому поселенні Обердайн на березі Темного Узбережжя.",al={"місце барітраса","де барітрас","місце барітраса муншейда"}},{q="Які доручення дає Барітрас?",a="Барітрас посилає мандрівників до сусідніх печер по гриби, як-от небезпечна Бліда Поганка, а згодом скеровує шукачів пригод на південь, на зустріч із прадавнім Ону.",al={"завдання барітраса","які завдання дає барітрас","завдання про гриби в печері"}},{q="Чи родич Барітрас інших Муншейдів?",a="Прізвище Муншейд мають ще кілька нічних ельфів по всьому Калімдору, зокрема Вартові й Хранителі, що натякає на спільний рід.",al={"родина муншейдів","інші муншейди","чи барітрас родич вартового муншейда"}}},fp="19,223,21.300.0,20.217.0,27.190.0,37.88.0,31.178.0,45.151.0"}
P.entries["npc:barkeep-daniels"] = {n="Шинкар Деніелс",s="Шинкар Деніелс стоїть за шинквасом Корчми Лейкшира й обслуговує втомлених вартових, місцевих рибалок і подорожніх. Клан Блекрок чинить набіги по всіх Горах Редріджу й перерізає шляхи постачання, тож утримувати таверну в достатку стало справжньою боротьбою.",h="Шинкар Деніелс стоїть за шинквасом Корчми Лейкшира й обслуговує втомлених вартових, місцевих рибалок і...",kw={"шинкар деніелс","корчма лейкшира","таверна","трунки","лейкшир","редрідж"},ang={["faction:Alliance"]="Підтримувати бойовий дух Лейкширу для Альянсу вкрай важливо, адже це поселення — побитий заслін королівства проти твердині Блекрок на півночі."},sec={{t="Щоб не занепав дух Лейкширу",b="За шинквасом Корчми Лейкшира стоїть Шинкар Деніелс: наливає напої й вітає кожного, хто заходить з мосту. Лейкшир уже кілька місяців під постійним тиском гнолів і орків Блекрок, і захисники міста розраховують на таверну, щоб перевести подих після похмурих патрулів. На біду Деніелса, перерізані дороги й безперервні напади зруйнували торгівлю в усьому краї. Тепер, коли місту найбільше потрібна розрада, трунків у нього небезпечно мало, тож він радо прийме допомогу будь-якого мандрівного шукача пригод, готового привезти вантаж із безпечніших поселень."}},faq={{q="Хто такий Шинкар Деніелс?",a="Шинкар Деніелс — людина, господар таверни, що стоїть за шинквасом Корчми Лейкшира. Він наливає місцевим жителям, мандрівним шукачам пригод і змученій міській варті.",al={"деніелс редрідж","шинкар лейкширу","хто такий деніелс"}},{q="Чому в нього закінчуються напої?",a="Безупинні набіги орків Блекрок і сусідніх племен гнолів перекрили каравани з припасами й торгові шляхи до Гір Редріджу. Постачання обірвалося, а знервовані захисники випивають те, що є, тож Деніелс ледве встигає поповнювати полиці.",al={"чому закінчилася випивка","лор завдання сухі часи","чому немає алкоголю"}},{q="З чим йому треба допомогти?",a="У завданні «Сухі часи» Деніелс шукає охочих мандрівників, які принесуть свіжі запаси випивки з-за меж Редріджу, щоб відвідувачі корчми були вдоволені.",al={"завдання шинкаря деніелса","чого він хоче","доручення деніелса"}}},fp="15,278,33.583.0,23.184.0,32.270.0,28.179.0"}
P.entries["npc:baron-aquanis"] = {n="Барон Аквеніс",s="Барон Аквеніс — могутній водяний елементаль затоплених Руїн Місячної Святині в Чорноглибинних Печерах, де влаштував собі лігво Молот Присмерку. Він здіймається з глибини, коли хтось потривожить Глибинний Камінь у руїнах. Шамани Земляного Кільця давно вважають його оскверненою стихійною силою і підозрюють, що за цим стоїть культ.",h="Барон Аквеніс — могутній водяний елементаль затоплених Руїн Місячної Святині в Чорноглибинних Печерах, де...",kw={"барон аквеніс","водяний елементаль","глибинний камінь","земляне кільце","дже'ню санкреа","чорноглибинні печери"},ang={["class:Shaman"]="Для шаманів Земляного Кільця Барон Аквеніс — трагічний приклад спотворення стихій, а його осквернені рештки дають важливі підказки, як очищати спотворених духів.",["faction:Horde"]="Дже'ню Санкреа співпрацює з Ордою на узбережжі Ашенвалю, а глибинне ядро, яке здобувають його помічники з Орди, має показати, що коїть зі стихіями Молот Присмерку."},sec={{t="Охоронець Глибинного Каменю",b="Глибинний Камінь лежить у затоплених залах Руїн Місячної Святині, просто під носом у культистів Молота Присмерку, які тепер займають руїни. Усередині каменю — глибинне ядро, пристрій, що, коли його правильно прочитати, розповідає історію всієї стихійної діяльності довкола. Дже'ню Санкреа із Земляного Кільця посилає шукачів пригод з Орди здобути ядро, і потривожений камінь викликає Барона Аквеніса з глибин."},{t="Скверна глибин",b="Земляне Кільце давно вважає Барона Аквеніса оскверненою стихійною силою. Загинувши, він лишає по собі Дивну Водяну Кулю — непроникну сферу з гнилою, хлюпотливою водою, яка, схоже, живила його енергією. Дже'ню Санкреа вірить, що куля доведе, що саме осквернило барона і як. Він анітрохи не здивується, якщо винним виявиться Молот Присмерку."}},faq={{q="Де знайти Барона Аквеніса?",a="Барон Аквеніс живе в затоплених Руїнах Місячної Святині глибоко в Чорноглибинних Печерах. Залами він не блукає: він здіймається з води, коли хтось потривожить підводний Глибинний Камінь руїн, — а це роблять шукачі пригод з Орди, здобуваючи для Дже'ню Санкреа його Глибинне Ядро.",al={"місце аквеніса","де барон аквеніс","як викликати барона аквеніса"}},{q="Що таке Дивна Водяна Куля?",a="Дивна Водяна Куля — те, що лишається від Барона Аквеніса, коли його знищено: сфера, яку не розбити жодною фізичною силою, а всередині хлюпає смердюча вода. Схоже, вона живила його стихійну енергію. Дже'ню Санкреа із Земляного Кільця хоче її дослідити, вірячи, що вона покаже, що саме зіпсувало барона і як.",al={"дивна водяна куля","куля аквеніса","для чого водяна куля"}},{q="Чому Земляне Кільце цікавиться Бароном Аквенісом?",a="Земляне Кільце пильнує рівновагу стихій. Дже'ню Санкреа й товариші давно вважали Барона Аквеніса зіпсованою стихійною силою, а тепер, коли в Руїнах Місячної Святині засів Молот Присмерку, бояться, що культ змушує стихії діяти проти Орди. Рештки барона й Глибинне Ядро руїн можуть показати, що замислив культ.",al={"чому земляне кільце аквеніс","дже'неу санкреа аквеніс"}},{q="Що таке Глибинне Ядро?",a="Глибинне Ядро — стихійний артефакт, що зберігається в затопленому Глибинному Камені. Вправний шаман може прочитати з нього всю історію стихійної активності в краї й викрити темні ритуали, які проводить у руїнах Молот Присмерку.",al={"лор глибинного ядра","що робить глибинне ядро"}},{q="Чи Барон Аквеніс у союзі з Молотом Присмерку?",a="Наскільки відомо, не з власної волі. Земляне Кільце вважає його зіпсованим елементалем, а не охочим слугою, і перші підозрювані — культисти Молота Присмерку, що тримають Руїни Місячної Святині. Дже'ню Санкреа каже, що не здивувався б, якби за цим стояли вони, але хоче доказів, перш ніж стверджувати напевно.",al={"чи аквеніс молот присмерку","культ аквеніса"}},{q="Чи має Альянс справи з Бароном Аквенісом?",a="Не безпосередньо. Глибинний Камінь, а з ним і Барон Аквеніс, — турбота Дже'ню Санкреа: він шаман Земляного Кільця, що співпрацює з Ордою на узбережжі Ашенвалю, і по Глибинне Ядро посилає саме шукачів пригод з Орди. У дослідників з Альянсу в Чорноглибинних Печерах свої доручення.",al={"чи може альянс вбити аквеніса","завдання альянсу аквеніс"}}},fp="13,343,28.422.0,24.380.1,31.268.0,32.324.0,52.368.0,24.268.0,51.328.0,51.293.0"}
P.entries["npc:baron-revilgaz"] = {n="Барон Ревілґаз",s="Барон Ревілґаз — хитрий гоблін, ватажок Буті Бею й Нападників Чорної Води, що править цим піратським притулком від імені картелю Стімвідл. З високого балкона таверни «Солоний моряк» він тримає хитку рівновагу між торговельним нейтралітетом і безжальною вигодою. Він наймає мандрівних найманців, щоб убезпечити свої вкладення, підкопатися під суперників на кшталт Буканірів Кривавого Вітрила й здобути прадавні реліквії джунглів.",h="Барон Ревілґаз — хитрий гоблін, ватажок Буті Бею й Нападників Чорної Води, що править цим піратським...",kw={"барон ревілґаз","буті бей","нападники чорної води","картель стімвідл","камінь припливів","гоблін"},ang={["class:Rogue"]="Ревілґаз поважає злодіїв, шпигунів і пристосуванців. Він часто наймає розбійників для ризикованих крадіжок, диверсій проти картелів-суперників і потаємного видобутку рідкісних артефактів джунглів.",["faction:Alliance"]="Буті Бей стоїть на руїнах Бухти Чорної Води — поселення Стормвінда, що існувало ще до Першої війни, і Ревілґаз охоче співпрацює з людськими вченими й бібліотекарями Стормвінда, коли прадавні знання обіцяють прибуток.",["profession:Engineering"]="Ревілґаз не стоїть осторонь суперництва гоблінських інженерів і вдається до підступних прийомів, щоб роздобути у Венчурної Компанії передові креслення й регулятори палива."},sec={{t="Господар Буті Бею",b="Зі свого спостережного місця нагорі таверни «Солоний моряк» Барон Ревілґаз крізь особливу зачаровану підзорну трубу стежить за гамірними доками Бухти Чорної Води. Поруч стоїть його довірений радник, таурен Флотоводець Сігорн, а сам Ревілґаз міцно тримає в руках місцевих кишенькових злодіїв, купців і каперів. Колись тут було людське поселення, яке ще до Першої війни заполонили тролі; згодом порт прибрали до рук і укріпили гобліни, і з часом він став торговим осередком Нападників Чорної Води з неабияким піратським присмаком. Ревілґаз стежить, щоб порт офіційно лишався відкритим для мандрівників і з Альянсу, і з Орди, і суворо тримає нейтралітет у межах гавані, щоб торгівля не спинялася ні на мить."},{t="Павутина амбіцій",b="Вплив Ревілґаза сягає далеко за межі портових доків. Коли після недавніх воєн деінде в Азероті торгівля завмерла, він ухопився за відкриття смакориби й започаткував Рибальський Фестиваль Стренглторну, знову привабивши натовпи до своїх берегів. По всій Долині Стренглторну він пильно стежить за конкурентами й можливими загрозами: замовляє диверсії проти Венчурної Компанії біля Озера Назферіті, уважно наглядає за мисливською експедицією Несінґварі та за ренегатськими людськими військовими таборами на півночі, а ще підтримує пов'язані з перегонами торговельні зв'язки з Монте Ґазлоу й Поззіком на Перегонах Міражу."},{t="Камінь Припливів",b="За торговим фасадом Ревілґаза ховається одержимість прадавньою силою й багатством. Перевіряючи чутки про острів із привидами біля узбережжя, Ревілґаз посилає шукачів пригод розшукати легендарний Камінь Припливів. Для цього доведеться звіритися з прадавніми фоліантами в Бібліотеці Стормвінда, вивчити стихійні рештки разом із Верховним Магом Ансіремом Рунотвором і відібрати в Буканірів Кривавого Вітрила прадавній тролячий кинджал, щоб розбити прибережний вівтар, який захищає камінь. Так Ревілґаз знімає смертоносне стихійне прокляття й забирає безцінну реліквію до власних скарбниць."}},faq={{q="Хто такий Барон Ревілґаз?",a="Барон Ревілґаз — правитель Буті Бей і ватажок Нападників Чорної Води. Діючи від імені нейтрального картелю Стімвідл, він керує цим піратським притулком, поєднуючи безжальну жадібність і дипломатичну розважливість.",al={"хто такий ревілґаз","історія ревілґаза","бос буті бей","лідер буті бей"}},{q="Де знайти Барона Ревілґаза?",a="Він стоїть на верхньому балконі Таверни «Солоний Моряк» у Буті Бей, звідки видно всю бухту, разом зі своїм першим помічником, Флотоводцем Сігорном.",al={"де ревілґаз","місце ревілґаза","як знайти ревілґаза"}},{q="Які в Ревілґаза стосунки з Буканірами Кривавого Вітрила?",a="Вони запеклі вороги. Буканіри Кривавого Вітрила не визнають правил картелю Стімвідл і грабують кораблі Буті Бей. Ба більше, провідники Кривавого Вітрила раз у раз замишляють убити Ревілґаза й Сігорна.",al={"ревілґаз кривавого вітрила","кривава вітрила проти ревілґаза","чому ненавидіти кривавих вітрил"}},{q="Що Ревілґаз має з Перегонів Міражу?",a="Ревілґаз спонсорує гоблінську команду перегонників під проводом Поззіка, що змагається з гномами на Мерехтливих Низинах. Він посилає шукачів пригод викрасти в Венчурної Компанії біля Озера Назферіті запатентовані креслення регулятора пального й передає їх на перегони.",al={"гонки ревілґаза","ревілґаз мерехтливі рівнини","ревілґаз поззік"}},{q="Що таке Рибальський Фестиваль Стренглторну?",a="Коли через війни в інших куточках Азероту торгівля підупала, Ревілґаз, покуштувавши місцевої «смакориби», підтримав рибалку на ім'я Ріґґл Бассбейт. Ревілґаз перетворив цей улов на щотижневі змагання вздовж узбережжя Стренглторну, щоб пожвавити господарство Буті Бей.",al={"лор рибальського турніру","хто почав рибальське змагання","ревілґаз смачнорибка"}},{q="Що таке Камінь Припливів?",a="Це давній проклятий магічний камінь, схований на Мерзенному Рифі. Ревілґаз відшукує легенду про нього в записах Стормвінда й наймає даларанського вченого, Верховного Мага Ансірема Рунотвора, щоб той допоміг шукачам пригод зламати стихійний захист каменю й здобути реліквію.",al={"завдання каменя припливів","мерзенний риф камінь","вівтар припливів"}}},fp="14,425,19.682.0,17.589.0,22.572.1,22.222.0,34.138.0,62.231.0,47.242.0,47.274.0,31.245.1"}
P.entries["npc:baron-silverlaine"] = {n="Барон Сільверлейн",s="Барон Сільверлейн був законним людським володарем фортеці, колись відомої як Фортеця Сільверлейн, що височіє над Селом Пайрвуд. Коли Архімаг Аруґал випустив лютих воргенів на цей край, барона й усю його челядь нещадно вирізали. Тепер його змучений дух блукає зруйнованою бенкетною залою, прикутий нежиттям до захисту того самого лігва, що стало його гробницею.",h="Барон Сільверлейн був законним людським володарем фортеці, колись відомої як Фортеця Сільверлейн, що височіє...",kw={"барон сільверлейн","фортеця шадовфенг","привид","аруґал","воргени","срібнолісся"},ang={["class:Mage"]="Доля Сільверлейна — похмуре застереження від магічної безрозсудності: мистецтво виклику, якщо поводитися з ним так, як Архімаг Аруґал, нищить невинні життя й лишає незагойні шрами.",["race:Human"]="Сільверлейн — гірке свідчення занепаду людської шляхетської влади на кордонах Ґілнеаса: його родину знищила магічна гординя чарівника, вишколеного в Даларані.",["race:Undead"]="Для Відступників, що просуваються Срібноліссям, примара Сільверлейна — лише ще один залишок старої ґілнеаської аристократії, який треба прибрати, щоб зламати владу Аруґала над фортецею."},sec={{t="Падіння Фортеці Сільверлейн",b="Доки тінь вовкоподібних звірів не огорнула південні пагорби Срібнолісся, Барон Сільверлейн правив гордим шляхетським маєтком. Його фортеця давала безпеку й нагляд довколишнім ґілнеаським землям. Цей мир розбився, коли Архімаг Аруґал, шукаючи зброю проти Погибелі, що лютувала довкола, випустив у край викликаних воргенів. Диких потвор не вдалося приборкати: вони штурмом узяли твердиню, здолали варту й порубали барона разом з усією його родиною."},{t="Змучена примара",b="Смерть не принесла Баронові Сільверлейну звільнення. Прикутий до давнього Великого Залу фортеці, його неспокійний привид тепер блукає між розтрощеними столами, за якими колись бенкетував. Проклятий володар кидається на загарбників, що вдираються до його зруйнованої домівки."}},faq={{q="Хто такий Барон Сільверлейн?",a="Це шляхетний ґілнеаський володар фортеці, що спершу звалася Фортеця Сільверлейн і стояла над Селом Пайрвуд. Його вбили разом із родиною, коли воргени заполонили фортецю.",al={"лор барона сільверлейна","хто такий сільверлейн","хто правив шедоуфенґ"}},{q="Чому він блукає Фортецею Шадовфенг?",a="Сільверлейна вбили в його власному домі під час навали воргенів, яку розв'язав Архімаг Аруґал. Проклятий і по смерті, його привид прикутий до бенкетної зали його зруйнованої фортеці й не може відійти.",al={"чому сільверлейн привид","чи сільверлейн мертвий","дух сільверлейна"}},{q="Чому Сільверлейн нападає на чужинців?",a="Його проклятий дух лишається у своєму колишньому домі й нападає на непроханих гостей у Великому Залі.",al={"чому сільверлейн нападає","привид сільверлейн","сільверлейн чужинці"}},{q="Де у фортеці його знайти?",a="Барон Сільверлейн блукає Великим Залом, що колись був розкішною бенкетною залою фортеці, доки його не сплюндрували під час падіння маєтку.",al={"де сільверлейн","місце барона сільверлейна","їдальня сільверлейна"}},{q="Як звалася Фортеця Шадовфенг до нападу воргенів?",a="Спершу вона звалася Фортеця Сільверлейн — на честь шляхетної родини барона, що володіла нею, доки владу не захопив Аруґал.",al={"початкова назва шедоуфенґ","лор фортеці сільверлейна","стара назва шедоуфенґ"}},{q="Чи хтось із родини Сільверлейна вцілів?",a="Ні. Історичні свідчення підтверджують, що Барона Сільверлейна та всю його родину вирізали у фортеці, коли туди вдерлися люті воргени.",al={"родина сільверлейна","чи вижили сільверлейни","спадкоємці сільверлейна"}}},fp="17,378,28.494.0,19.233.0,26.189.0,35.203.0,40.97.0,34.139.0,57.133.0,43.140.0"}
P.entries["npc:baros-alexston"] = {n="Барос Алекстон",s="Барос Алекстон — Головний Архітектор Стормвінда, що працює в Ратуші над Соборною Площею. Колишній член Гільдії Каменярів, що допомагав відбудовувати столицю після Першої війни, він обрав офіційну посаду замість того, щоб піти за своїм давнім другом Едвіном Венкліфом у відкритий бунт.",h="Барос Алекстон — Головний Архітектор Стормвінда, що працює в Ратуші над Соборною Площею.",kw={"барос алекстон","архітектор","гільдія каменярів","венкліф","стормвінд","ратуша"},ang={["class:Rogue"]="Для розбійників, що діють у тінях столиці, Барос — ниточка до Майстра Матіаса Шоу й SI:7, які мають перед архітектором тихі борги, попри його колишній зв'язок із Венкліфом.",["faction:Alliance"]="Барос Алекстон уособлює болісні компроміси всередині Альянсу й показує, як зрада Гільдії Каменярів розколола майстрів, що віддали життя відбудові столиці.",["race:Human"]="Людські шукачі пригод із Вестфолу впізнають прізвище Бароса — так зветься зарослий, зруйнований хутір, який тепер заполонили злодії й гноли."},sec={{t="Від хутора до риштувань",b="Барос виріс на Хуторі Алекстона серед пологих луків Вестфолу. Коли він був юнаком, злодії напали на родинну садибу й підпалили її, тож його батько мусив поспіхом поховати найцінніші родинні реліквії по всьому обійстю, перш ніж утекти. Згодом Барос подався до столиці й вступив до Гільдії Каменярів, роками віддаючи виснажливу працю поряд із головою гільдії Едвіном Венкліфом, щоб підняти Стормвінд із попелу Першої війни."},{t="Гірке розставання",b="Коли відбудова добігала кінця, Дім Вельмож відмовився від обіцяної плати, що спричинило люті протести, розпуск Гільдії Каменярів і смертельні вуличні заворушення. Поки Венкліф вів знедолених ремісників у вигнання, щоб заснувати Братство Дефіас, вельможі запропонували Баросові почесну посаду Міського Архітектора за умови, що він зречеться повстання. Не поділяючи прагнення гільдії вдатися до жорстокого розбою, Барос погодився — і між ним та колишніми товаришами пролягла трагічна прірва."},{t="Привид у Мертвих Копальнях",b="З-за свого столу в Ратуші Барос і далі наглядає за утриманням столиці; серед його політичних зв'язків — делікатна послуга, яку йому винен Матіас Шоу з SI:7. Та минуле не хоче лежати в землі. Після загибелі Венкліфа в глибинах Мертвих Копалень на тілі ватажка Дефіас знаходять ненадісланого листа, адресованого особисто Баросові, — свідчення дружби, розірваної політикою, зрадою й кров'ю, пролитою на наріжні камені Стормвінда."}},faq={{q="Де знайти Бароса Алекстона?",a="Барос Алекстон перебуває в Ратуші Стормвінда, просто на північному боці Соборної Площі в Стормвінді.",al={"місце бароса алекстона","де барос алекстон","барос стормвінд"}},{q="Яка роль Бароса Алекстона в Стормвінді?",a="Він Головний Архітектор Стормвінда: керує будівництвом, міським господарством і архітектурним плануванням столиці.",al={"робота бароса","посада бароса","що робить барос"}},{q="Звідки Барос знає Едвіна Венкліфа?",a="Вони були близькими колегами в Гільдії Каменярів і пліч-о-пліч відбудовували Стормвінд після Першої війни. Коли Дім Вельмож відмовився платити робітникам, Венкліф очолив бунт, а Барос лишився й прийняв посаду Міського Архітектора.",al={"барос і ванкліф","чи барос знав едвіна","барос каменярі"}},{q="Чому Барос не приєднався до Братства Дефіас?",a="Барос не поділяв переконань гільдії, що скотилася до жорстокого бунту. Коли Дім Вельмож запропонував йому посаду Міського Архітектора за відмову йти за Венкліфом, Барос обрав громадський лад, а не життя поза законом.",al={"чому барос не приєднався","розкол барос дефіас","чому барос зрадив каменярів"}},{q="Що за невідправлений лист знаходять при Едвіні Венкліфі?",a="Коли Едвін Венкліф гине в Мертвих Копальнях, шукачі пригод знаходять невідправлений лист, написаний просто Баросові Алекстону: він свідчить про давню особисту образу й неврегульоване минуле між двома колишніми майстрами.",al={"завдання невідправлений лист","невідправлений лист ванкліфа","лист до бароса"}},{q="Що пов'язує Бароса Алекстона з Вестфолом?",a="Барос виріс на Хуторі Алекстона у Вестфолі. Його родина втекла, коли злодії спалили обійстя, і згодом Барос наймає шукачів пригод, щоб повернути речі з його дитинства, зокрема його найпершого компаса.",al={"хутір алекстона","барос вестфолл","дитинство бароса"}}},fp="14,316,34.457.0,24.559.1,27.475.1,32.133.0,43.149.0,35.263.0,45.229.0,50.215.1,48.212.0"}
P.entries["npc:bartleby"] = {n="Бартлбі",s="Бартлбі — задиркуватий пияк, що вештається в таверні «Свиня і Свисток» у Старому Місті Стормвінда. Відомий тим, що мертвою хваткою тримає свій ель, він стає першим бойовим випробуванням для воїнів-початківців, які хочуть довести свою звитягу в старій добрій бійці в таверні.",h="Бартлбі — задиркуватий пияк, що вештається в таверні «Свиня і Свисток» у Старому Місті Стормвінда.",kw={"бартлбі","свиня і свисток","старе місто","гаррі барлґард","воїн","бійка"},ang={["class:Warrior"]="Кожен юний воїн, що навчався в Стормвінді, пам'ятає свій двобій із Бартлбі. Відібрати кухоль в упертого пияка — незабутній обряд посвяти в рукопашному бою.",["race:Human"]="Бартлбі уособлює суворий робітничий бік стормвіндського Старого Міста, де місцеві суперечки вирішують перекинутими табуретами, а не королівськими указами."},sec={{t="Завсідник «Свині і Свистка»",b="Таверна «Свиня і Свисток», що сховалася у вузьких брукованих завулках Старого Міста, приваблює грубішу й загартованішу публіку, ніж охайні шинки Соборної Площі. Бартлбі — один із її найпостійніших завсідників. Міцно стискаючи свій улюблений кухоль і підживлюючись дешевим елем, він днями плекає образи й чіпляється до кожного, кому не пощастить потурбувати його за чаркою."},{t="Обряд посвяти воїна",b="Хоч Бартлбі схожий на будь-якого іншого пияка з околиці, стормвіндські наставники воїнів бачать у ньому практичну користь. Гаррі Барлґард раз у раз посилає бійців-початківців розшукати Бартлбі й забрати в нього кухоль. Щоб повернути цю реліквію, доведеться обмінятися ударами голих кулаків із п'яним забіякою — так з'ясовується, чи має воїн-новачок досить витримки, щоб упоратися з буйним супротивником віч-на-віч."}},faq={{q="Хто такий Бартлбі?",a="Бартлбі — буйний завсідник Таверни «Свиня і Свисток» у Старому Місті Стормвінда. Він відомий тим, що напивається до нестями й не віддає свого кухля без бійки.",al={"лор бартлбі","хто такий бартлбі","бартлбі стормвінд"}},{q="Де знайти Бартлбі?",a="Бартлбі пиячить на першому поверсі Таверни «Свиня і Свисток» у кварталі Старе Місто в Стормвінді.",al={"місце бартлбі","де бартлбі","бартлбі порося й свисток"}},{q="Чому воїни мають із ним битися?",a="Гаррі Барлґард, наставник воїнів зі Старого Міста, посилає молодих новобранців до Бартлбі як на випробування бойової вправності. Відібравши в Бартлбі кухоль силою, новобранець доводить, що впорається з несподіваною бійкою й здолає затятого, упертого супротивника.",al={"чому воїни б'ються з ним","завдання воїна бартлбі","призначення бартлбі"}},{q="Що стається, коли кинути йому виклик?",a="Коли в нього вимагають його дорогоцінний кухоль, Бартлбі випиває зілля для витривалості й стає ворожим, починаючи кулачну бійку просто посеред таверни, доки його не поб'ють і він не здасться.",al={"бій з бартлбі","перемогти бартлбі завдання","бійка з бартлбі"}},{q="Чи належить Бартлбі до якоїсь фракції чи організації?",a="Бартлбі — просто мешканець Стормвінда й запеклий пияк. Жодних відомих зв'язків ні зі злочинними угрупованнями на кшталт Братства Дефіас, ні з міською вартою він не має.",al={"чи бартлбі дефіас","фракція бартлбі","бартлбі альянс"}},{q="Чому він просто не віддасть свій кухоль?",a="Бартлбі задиркуватий, добряче п'яний і впертий. Будь-яке прохання віддати напій чи кухоль він сприймає як образу й радше розв'яже справу кулаками, ніж розлучиться з випивкою.",al={"кухоль бартлбі","ель кухоль бартлбі","чому битися за кухоль"}}},fp="8,266,32.399.0,27.397.0,16.206.0,26.128.0,34.252.0,35.202.0,52.176.0,36.198.0"}
P.entries["npc:bashana-runetotem"] = {n="Башана Рунототем",s="Башана Рунтотем — травниця й дослідниця-друїдка, що живе на Узвишші Старійшин у Тандер Блафі. Донька Верховного друїда Гамуула Рунтотема, вона допомагає Колу Кенарія: керує сільськогосподарськими дослідженнями й скеровує шукачів пригод з Орди проти сил скверни.",h="Башана Рунтотем — травниця й дослідниця-друїдка, що живе на Узвишші Старійшин у Тандер Блафі.",kw={"башана рунототем","гамуул рунтотем","узвишшя старійшин","тандер блаф","коло кенарія","друїд"},ang={["class:Druid"]="Для тауренських друїдів, що вчаться ремесла в її батька Гамуула, Башана уособлює діяльну польову роботу, без якої не зрозуміти мінливої природи Калімдору.",["faction:Horde"]="Башана — важлива ланка між представниками Кола Кенарія в Тандер Блафі й звитяжцями Орди, що прагнуть ударити по загрозі сектантів."},sec={{t="Донька Кола",b="Стоячи на вітряних висотах Узвишшя Старійшин, Башана Рунтотем продовжує друїдську спадщину свого батька, Верховного друїда Гамуула Рунтотема. Поки батько веде молодих тауренських друїдів і радить Кайрнові Бладгуфу, Башана зосереджується на практичних дослідженнях рослинних аномалій і місцевих загроз. Вона дає мандрівникам знаряддя на кшталт вічнозелених торбинок, щоб вирощувати загадкові рослини, — зокрема таємниче ранкове зерно, — а також узгоджує зусилля Орди, спрямовані на очищення від мерзенної скверни, що шириться з місць на кшталт Чорноглибинних Печер."}},faq={{q="Хто така Башана Рунтотем?",a="Башана — тауренка-друїдка й дослідниця з Узвишшя Старійшин у Тандер Блафі. Вона дочка Верховного Друїда Гамуула Рунтотема й працює для Кола Кенарія: вивчає дивні рослини й організовує відсіч природним загрозам по всьому Калімдору.",al={"хто така башана","лор башани","хто така башана рунототем"}},{q="Які дослідження вона веде з ранкозерном?",a="Башана залучає шукачів пригод з Орди вирощувати й збирати ранкозерно з пакетиків насіння й ґрунту. Коло Кенарія вивчає цю могутню, загадкову рослину, щоб зрозуміти її незвичні властивості та зв'язок із більшими рослинними таємницями, що розкриваються по всьому Калімдору.",al={"дослідження ранкозерна","що башана робить з ранкозерном","чому ранкозерно"}},{q="What is her connection to Blackfathom Deeps?",a="Bashana receives the report and proof from adventurers sent by Argent Guard Thaelrid to confront the cultists of Blackfathom Deeps. She rewards their help against the corruption threatening Ashenvale.",al={"башана чорноглибинні печери","завдання чорноглибинних печер","чому чорноглибинні печери"}},{q="Де її знайти?",a="Вона перебуває на Узвишші Старійшин у Тандер Блафі — столовій горі, присвяченій шаманам, друїдам і духовним старійшинам міста, біля друїдських наметів.",al={"де башана рунототем","місце башани","як знайти башану"}}},fp="17,273,24.542.0,25.254.0,48.268.0,44.200.0,23.159.0"}
P.entries["npc:bath-rah-the-windwatcher"] = {n="Бат'ра Спостерігач Вітрів",s="Бат'ра Спостерігач Вітрів — самотній троль-шаман із джунглів і зброяр, що живе серед руїн поблизу Мису Студеного Вітру. Далеко від своєї тропічної батьківщини він вивчає бурхливі стихії північних гір і шукає звитяжців, досить сильних, щоб допомогти йому викувати грізну зброю вітру.",h="Бат'ра Спостерігач Вітрів — самотній троль-шаман із джунглів і зброяр, що живе серед руїн поблизу Мису...",kw={"бат'ра спостерігач вітрів","циклоніан","гори альтерак","мис студеного вітру","шаман","троль"},ang={["class:Shaman"]="Як ваш побратим у володінні стихіями, Бат'ра має глибокий духовний зв'язок із шаманами, що прагнуть тіснішого єднання з духами землі, води й повітря.",["class:Warrior"]="Бат'ра славиться серед досвідчених бійців тим, що проводить їх крізь випробування, потрібні, щоб викувати знамениту зброю Вихору із суті елементаля Циклоніана."},sec={{t="Самітник вершин",b="Більшість тролів із джунглів тримається теплих лісів і узбереж півдня, але Бат'ра обрав самотнє життя гірського самітника серед холодних руїн Гір Альтерак. Досвідчений шаман і майстер, він проводить дні, слухаючи завивання вітрів і розмовляючи з духами природи. Його одержимість — не лише філософська: він прагне закувати лють шалених стихійних бур у справжню зброю для тих, хто має силу нею володіти."},{t="Приборкати Циклоніана",b="Найбільша мрія Бат'ри пов'язана з Циклоніаном — жахливим елементалем вітру, що живе серед навколишніх вершин. Не здатний сам подолати таку сутність, Спостерігач Вітрів кличе на допомогу досвідчених воїнів і шаманів, щоб зібрати рідкісні стихійні есенції й викликати чудовисько. Коли Циклоніана вбито, а його стихійне серце здобуто, Бат'ра перетворює дикі бурі на легендарну зброю, відому на весь Азерот."}},faq={{q="Хто такий Бат'ра Спостерігач Вітрів?",a="Бат'ра — дивакуватий троль із джунглів, шаман і майстер обладунків, що живе відлюдником серед руїн у Горах Альтерак біля Мису Студеного Вітру. Він допомагає досвідченим шукачам пригод втілювати сили стихій у могутню зброю.",al={"хто такий бат'ра","хто бат'ра","лор спостерігача вітрів"}},{q="Що троль із джунглів робить в Альтераку?",a="Bath'rah lives as a hermit near Chillwind Point, studying elemental power and helping capable adventurers forge weapons. His reasons for leaving his former homeland are not established.",al={"чому бат'ра в альтераку","троль в альтеракських горах"}},{q="Що таке Циклоніан?",a="Циклоніан — величезний, лютий елементаль вітру, що блукає руїнами довкола притулку Бат'ри. Бат'рі потрібне ядро цього створіння, щоб кувати зброю, насичену стихією вітру.",al={"хто такий циклоніан","кого викликає бат'ра"}},{q="Чому воїни його шукають?",a="Воїни з усього світу приходять до Бат'ри, бо він уміє кувати знамениту зброю Вихору. Здолавши Циклоніана за його вказівками, вони отримують зброю, сповнену виючих вітрів.",al={"завдання воїна бат'ра","хлопець із сокирою вихору"}},{q="Чи допомагає Бат'ра лише Орді?",a="Бат'ра живе відлюдником, осторонь великої політики фракцій. Його турбота — передусім стихійне ремесло, і він допомагатиме вправним воїнам і шаманам, які шанують духів і сприяють його стихійній праці.",al={"чи бат'ра ворожий","бат'ра альянс"}}},fp="24,300,19.475.0,19.409.1,32.218.0,40.185.0,18.178.0,29.192.0,45.218.0"}
P.entries["npc:bazil-thredd"] = {n="Базіл Тредд",s="Базіл Тредд — лейтенант і найдовіреніший помічник Едвіна Венкліфа, ув'язнений у В'язниці Стормвінда від часів бунту каменярів, під час якого загинула королева Тіффін. Тепер в'язниця повстала, і Тредд очолює бунтівних в'язнів Братства Дефіас зі свого східного блоку камер.",h="Базіл Тредд — лейтенант і найдовіреніший помічник Едвіна Венкліфа, ув'язнений у В'язниці Стормвінда від часів...",kw={"базіл тредд","в'язниця стормвінда","дефіас","бунт","венкліф","наглядач телвотер"},ang={["faction:Alliance"]="Бунт Дефіас просто під вулицями Стормвінда — пряма загроза столиці, і Наглядач Телвотер хоче розправитися з його ватажком, доки заколот не поширився.",["race:Human"]="Тредд — живе нагадування про бунт каменярів, що забрав життя королеви Тіффін і налаштував Братство Дефіас проти королівства."},sec={{t="Лейтенант Венкліфа",b="Коли знать Стормвінда відмовилася заплатити Гільдії Каменярів за відбудову міста, Едвін Венкліф відкинув урядові поступки й підняв відкритий бунт. Базіл Тредд стояв поруч із Венкліфом як його головний лейтенант і найдовіреніший помічник. Під час запеклих сутичок, що спалахнули слідом і забрали життя королеви Тіффін Рінн, Тредда схопила міська варта. Поки Венкліф і вцілілі каменярі тікали до Вестфолу, щоб заснувати Братство Дефіас, Тредда кинули в глибини В'язниці Стормвінда."},{t="Бунт у В'язниці",b="Роками Тредд мовчав за залізними ґратами, начебто всіма забутий. Та цю самотність розірвав великий бунт в'язнів: вони здолали вартових, відчинили камери й перетворили В'язницю на збройну фортецю просто під Кварталом магів. Очоливши ув'язнених розбійників Дефіас, бунтарів і їхніх спільників-головорізів, Тредд облаштував свій командний пункт у східному крилі під охороною огра на прізвисько Окіст. Наглядач Телвотер, що відчайдушно прагне навести лад, доки хаос не вихлюпнувся на міські вулиці, вимагає голову Тредда, щоб обезголовити заколот."},{t="Цікавий відвідувач",b="Наглядач Телвотер довго вважав, що Братство покинуло Тредда гнити. Проте за кілька місяців до бунту загадковий чоловік із паперами на ім'я Мейлік почав навідуватися до Тредда раз чи двічі на тиждень. Хоч Телвотер і мав підозри, документи відвідувача виявилися цілком справжніми. Ці таємні зустрічі припинилися саме тоді, коли у в'язниці спалахнуло злагоджене насильство, — а отже, бунт, схоже, організували чиїсь руки в самому місті."}},faq={{q="Хто такий Базіл Тредд?",a="Базіл Тредд був правою рукою Едвіна Венкліфа під час бунту каменярів у Стормвінді. Його схопили під час заворушень, у яких загинула Королева Тіффін, і кинули до в'язниці, де він тепер очолює бунтівних в'язнів.",al={"лор базіла тредда","хто такий тредд","бос в'язниці тредд"}},{q="Де знайти Базіла Тредда?",a="Він перебуває глибоко у В'язниці Стормвінда — тюремному комплексі під Кварталом Каналів біля Кварталу магів. На перехресті головного коридору треба звернути до східного крила камер, пройти повз огра-громилу Окоста, і в середній камері найдальшої зали Тредд віддає накази.",al={"де базіл тредд","місце тредда","знайти базіла тредда"}},{q="Чому у в'язниці бунт?",a="В'язні подолали вартових, відімкнули камери й захопили коридори в'язниці. Базіл Тредд, найважливіший в'язень із Дефіасу, очолив бунтівних бандитів і каторжників, і Наглядач Телвотер ледве стримує заколот, щоб той не вихлюпнувся на вулиці Стормвінда.",al={"чому бунтують","причина бунту у в'язниці","чому в'язні збунтувалися"}},{q="Чому Наглядач Телвотер хоче смерті Тредда?",a="Наглядач Телвотер вважає, що бунт не придушити, доки живий Тредд, який ним керує. Варта не дає ради, в'язні тримають комплекс, тож наглядач наказує стратити Тредда, щоб обезголовити заколот.",al={"чому вбити тредда","нагорода телвотера за тредда","причина голови базіла тредда"}},{q="Хто навідувався до Тредда перед бунтом?",a="Тихий чоловік, що назвався Маеліком, щотижня навідувався до Тредда протягом місяців перед заколотом. Телвотер мав підозри, але відвідувач мав справжні документи, а це вказує, що зустрічам сприяли прихильники Дефіасу чи продажні урядовці в самому Стормвінді.",al={"відвідувач тредда","хто такий маелік","особа цікавого відвідувача"}},{q="Яку роль Тредд відігравав у Гільдії Каменярів?",a="Тредд був головним помічником Едвіна Венкліфа під час відбудови Стормвінда й подальших трудових суперечок: він допомагав організувати опір гільдії, коли Дім Вельмож відмовився заплатити за роботу.",al={"чи тредд був каменярем","тредд каменяр","каменяр тредд"}}},fp="12,268,21.547.0,21.583.0,19.469.1,20.238.0,32.271.0,28.322.0,43.240.0,40.273.1,48.237.0"}
P.entries["npc:bazzalan"] = {n="Баззалан",s="Баззалан — зловісний сатир-розбійник, що ховається у вулканічних глибинах Провалля Лютого Вогню. Разом із Джерґошем Призивачем він керує темними справами культу Пекучого Клинка просто під столицею Орди — Оргріммаром.",h="Баззалан — зловісний сатир-розбійник, що ховається у вулканічних глибинах Провалля Лютого Вогню.",kw={"баззалан","сатир","пекучий клинок","провалля лютого вогню","оргріммар"},ang={["class:Rogue"]="Баззалан демонструє класичні прийоми скритності, підступні удари й клинки, змащені отрутою, тож він — суперник, цікавий вам із професійного погляду.",["faction:Horde"]="Баззалан і його культ — нестерпна небезпека просто під твердинею Тралла, і їх треба негайно знищити.",["race:Orc"]="Орки так тяжко виборювали свободу від демонічних маніпуляцій, що сатир, який керує культистами в самих підвалинах їхньої столиці, для них — обурлива зухвалість."},sec={{t="Змія під містом",b="Поки Тралл працює над тим, щоб збудувати оркам нову домівку в Дуротарі, давнє зло знайшло собі лігво в нього під ногами. Баззалан, хитрий сатир-розбійник, уклав союз із культом Пекучого Клинка у звивистих лавових печерах Провалля Лютого Вогню. Прудкий і смертоносний із двома клинками, він — один із головних польових командирів культу."},{t="Провід культу й підступ",b="Стоячи на темному вулканічному уступі над центральною залою, де Джерґош Призивач править демонічні ритуали, Баззалан наглядає за вартою з культистів. Як і всі сатири, він зрештою вірний демонічним володарям і вдається до отрут, швидких ударів і темної скритності, щоб знищувати кожного розвідника Орди, що підійде надто близько до табору культу."}},faq={{q="Хто такий Баззалан?",a="Баззалан — сатир-розбійник і один із ватажків культу Пекучого Клинка, що діє в Проваллі Лютого Вогню під Оргріммаром.",al={"лор баззалана","хто такий баззалан","бос сатир ркл"}},{q="Де в Проваллі Лютого Вогню знайти Баззалана?",a="Він чатує на верхніх уступах Провалля Лютого Вогню, над Джерґошем Призивачем. Дістатися до нього можна темними пандусами, вирубаними в стінах печери.",al={"місце баззалана","де баззалан","знайти баззалана"}},{q="Що сатир робить під Оргріммаром?",a="Баззалан діє разом із Пекучим Клинком — демонічним культом, що прагне підточити Орду зсередини. Сатири прив'язані до демонічних сил і часто стають підбурювачами й убивцями на службі тіньових рад.",al={"чому сатир в оргріммарі","чому баззалан у провалі"}},{q="Якими вміннями Баззалан б'ється?",a="Баззалан б'ється як класичний розбійник: швидко б'є зброєю ближнього бою, завдає Підступного Удару, а часом уражає супротивників слабкою виснажливою отрутою.",al={"здібності баззалана","атаки баззалана","як б'ється баззалан"}},{q="Що пов'язує його з Джерґошем Призивачем?",a="Баззалан і Джерґош разом очолюють Пекучий Клинок у Проваллі Лютого Вогню. Джерґош зосереджений на закликах і виклику темних сил, а Баззалан відповідає за бій і скритні справи.",al={"джерґош і баззалан","чи баззалан родич джерґоша"}},{q="Чому Орда хоче смерті Баззалана?",a="Його присутність глибоко під столицею — пряма демонічна загроза. Провідники Орди доручають шукачам пригод проникнути до Провалля Лютого Вогню й знищити його, перш ніж задуми Пекучого Клинка поставлять місто під удар.",al={"нагорода за баззалана","відбити вторгнення баззалан"}}},fp="8,226,26.332.0,26.349.0,16.116.0,46.155.0,40.212.0,43.166.0,48.197.0,38.209.0"}
P.entries["npc:beldin-steelgrill"] = {n="Белдін Стілґрілл",s="Белдін Стілґрілл — уславлений дворфійський інженер і головний технік Складу Стілґрила в Дун Мороґу. Його широко вважають одним із найкращих механіків облогових машин у Каз Модані: він наглядає за обслуговуванням важкої броні та гусеничних бойових машин війська Айронфорджа. Щоб ці велетенські пристрої працювали, потрібен нескінченний запас високоякісного спеціального інструменту.",h="Белдін Стілґрілл — уславлений дворфійський інженер і головний технік Складу Стілґрила в Дун Мороґу.",kw={"белдін стілґрілл","інженер","склад стілґрила","облогові машини","парові танки","харанос","каз модан"},ang={["profession:Engineering"]="Для інженерів Белдін — вершина дворфійської транспортної техніки, нагода зблизька побачити найгрізніші механізовані бойові засоби Альянсу.",["race:Dwarf"]="Двір Белдіна показує промислову міць Айронфорджа й доводить, що дворфійська майстерність сягає далеко за ручні молоти й сокири — аж до нищівної облогової артилерії."},sec={{t="Володар гусеничного звіра",b="Розташований трохи далі дорогою від Хараноса, Склад Стілґрила — головний полігон і станція обслуговування дворфійських парових танків та облогових машин. Белдін Стілґрілл — його головний технік, уславлений усюди неперевершеним умінням ремонтувати й налаштовувати броньовані бойові вози. Приборкувати важкий метал і гуркітливі котли — невдячна праця, і Белдін швидко зношує знаряддя. Його постійний попит на важкі гайкові ключі, різаки й точні інструменти раз у раз жене місцевих ковалів на межу, аби лише його верстак не порожнів."}},faq={{q="Хто такий Белдін Стілґрілл?",a="Белдін Стілґрілл — дворф, майстер-механік і власник Складу Стілґрила в Дун Мороґу. Він славиться на весь Каз Модан як найкращий знавець дворфських облогових машин і бойових возів.",al={"белдін стілґрілл","хто такий белдін","механік танків дун морог"}},{q="Що відбувається на Складі Стілґрила?",a="Склад, що стоїть трохи на північний схід від Хараноса, — гамірний ремонтний і випробувальний майданчик для парових танків і важкої механізованої техніки Альянсу.",al={"склад стілґрила","що таке склад стілґрила","призначення складу"}},{q="Чому Белдін так швидко нищить інструменти?",a="Обслуговування важкої бронеобшивки, складних шестерень і парових котлів високого тиску вимагає важкої праці й особливого знаряддя. Белдін працює так важкою рукою, що інструменти зношуються з неймовірною швидкістю, тож він постійно робить вимогливі замовлення в довколишніх ковалів.",al={"навіщо йому інструменти","інструменти стілґрила","інструменти для стілґрила"}}},fp="17,389,27.571.0,25.207.0,35.156.0,41.252.0"}
P.entries["npc:bethor-iceshard"] = {n="Бетор Айсшард",s="Бетор Айсшард — могутній маг із Відступників, що перебуває в Магічному Кварталі Андерсіті. Він очолює знавців чародійної й тіньової магії в Храмі Проклятих і має чималу владу в державі Сильвани. За його крижаною вдачею ховається минуле, сплетене зі старими друзями, яких розлучила Погибель.",h="Бетор Айсшард — могутній маг із Відступників, що перебуває в Магічному Кварталі Андерсіті.",kw={"бетор айсшард","маг","андерсіті","магічний квартал","храм проклятих","ґунтер арканус"},ang={["class:Mage"]="Для магів-Відступників Бетор — вершина стійкості: він доводить, що чародійне мистецтво може квітнути навіть у холодних обіймах нежиття.",["faction:Horde"]="Бетор координує важливі бойові закляття й операції проти некромантів, що захищають позиції Орди в Лордероні.",["race:Undead"]="Особиста трагедія Бетора віддзеркалює долю багатьох Відступників: Погибель відірвала їх від дорогих друзів і домівок, а колишні союзники стали їм запеклими ворогами."},sec={{t="Господар Магічного Кварталу",b="У Храмі Проклятих Бетор Айсшард наглядає за знавцями чародійних мистецтв і тіньової магії Андерсіті. Шанований і страшний своїм розумом та крижаною рішучістю, Бетор має досить політичної й магічної ваги, щоб напряму віддавати накази провінційним магістратам по всьому Лордерона. Він посилає агентів Відступників здобувати цінні гримуари, розслідувати чародійні аномалії й знищувати ворожі сили, що загрожують владі Андерсіті."},{t="Узи учнівства",b="Ще до того, як Третя війна спустошила Лордерон, Бетор був смертним учнем, що вивчав магію разом із двома близькими товаришами — Ґунтером Арканусом і Тулом Рейвенкловом. На знак своєї дружби троє учнів сплели докупи свої навчальні жезли. Погибель розірвала ці узи вщент. Коли смерть і темна магія прокотилися королівством, Тул Рейвенклов добровільно віддав душу Королю-Лічу, Ґунтер загинув і повстав на відлюдному острові посеред Озера Світлої Води, а Бетор упав, щоб згодом вирватися на волю вже Відступником."},{t="Старі друзі й гірко-солодкі зустрічі",b="Бетор не забув колишніх товаришів. Вистежуючи могутніх заклиначів-нежить по всьому Тірісфалю й Срібноліссю, він посилає агентів з'ясувати, чи служать ці свавільні чаклуни Королю-Лічу, чи їх можна схилити на бік Відступників. Виявивши, що Ґунтер Арканус підіймає мерців на Озері Світлої Води, Бетор терпляче намагається привести старого друга під крило Леді Сильвани, але не знає жодної пощади до Тула Рейвенклова, чия добровільна зрада прирекла їхнє давнє братерство."}},faq={{q="Хто такий Бетор Айсшард?",a="Бетор Айсшард — високопоставлений маг-Відступник, що очолює Храм Проклятих у Магічному Кварталі Андерсіті. Він координує магічні дослідження, розвідку щодо відщепенців і таємні магічні операції від імені Темної Леді.",al={"бетор айсшард","хто такий бетор","лор бетора"}},{q="Де знайти Бетора Айсшарда?",a="Бетор перебуває в Храмі Проклятих — головній споруді Магічного Кварталу Андерсіті.",al={"де бетор","місце бетора","знайти бетора айсшарда"}},{q="Що пов'язує Бетора з Ґунтером Арканусом?",a="Бетор і Ґунтер були близькими друзями ще учнями-магами в Лордероні. Обидва загинули під час навали Погибелі, згодом вирвалися з-під влади Короля-Ліча, і Бетор домігся, щоб Ґунтер приєднався до Відступників.",al={"ґунтер і бетор","дружба ґунтера аркануса","звідки бетор знає ґунтера"}},{q="Ким був Тул Рейвенклов для Бетора?",a="Тул Рейвенклов був третім у гуртку учнів, до якого належали Бетор і Ґунтер. На відміну від них, Тул під час навали Погибелі добровільно віддав душу Королю-Лічу й став ненависним некромантом, що засів на Острові Фенріс.",al={"зв'язок тула рейвенклова","тул і бетор","бетор рейвенклов"}},{q="Яка історія Беторової чарівної палички?",a="Замолоду Бетор, Ґунтер і Тул сплели свої учнівські палички докупи на знак вічної дружби. Ця плетена пам'ятка й досі лишається зворушливим артефактом, що пов'язує трьох розлучених чарівників із їхнім смертним минулим.",al={"плетена паличка","паличка до бетора","паличка учня бетора"}},{q="Яку роль Бетор відіграє серед Відступників?",a="Бетор — один із провідних знавців тайної магії в Андерсіті. Він наставляє новопіднятих магів і чорнокнижників, керує військовою розвідкою щодо некромантів-відщепенців і має владу над місцевими цивільними урядовцями Відступників, як-от Магістрат Севрен.",al={"роль бетора","що робить бетор","влада бетора"}}},fp="15,321,27.481.0,23.535.0,36.497.1,23.234.0,35.117.0,46.252.1,34.234.0,39.229.0,47.259.0"}
P.entries["npc:billy-maclure"] = {n="Біллі Маклур",s="Біллі Маклур — бешкетний хлопчисько з людей, що живе на Виноградниках Маклюрів у Лісі Елвінн. Опинившись посеред запеклої ворожнечі між своєю родиною та сусідами Стоунфілдами, Біллі своїми дрібними витівками часто завдає клопоту обом фермам. Його слабкість до свіжої випічки робить його легкою здобиччю для підкупу, коли пустощі заходять надто далеко.",h="Біллі Маклур — бешкетний хлопчисько з людей, що живе на Виноградниках Маклюрів у Лісі Елвінн.",kw={"біллі маклур","хлопчик","виноградники маклюрів","стоунфілди","намисто","пиріг","ліс елвінн"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що щойно прибули з Нортширу, допомога з дурними витівками Біллі стає знайомством із небезпеками, що чаяться в Копальні Фарґодіп.",["profession:Cooking"]="Славетний пиріг зі свинячою грудинкою тітоньки Берніс показує, як проста сільська кухня може залагодити напружені місцеві суперечки й витягти зізнання з мовчазних фермерських хлопчаків.",["race:Human"]="Біллі уособлює приземлені буденні чвари сільського Елвінну: попри політичні потрясіння Стормвінда, місцеві фермерські ворожнечі й дитячі бешкети тривають як завжди."},sec={{t="Хлопчисько з виноградників",b="Біллі Маклура зазвичай можна застати, коли він тиняється біля клуні на Виноградниках Маклюрів, неподалік від фермера Джерарда Тіллера. Вирісши серед нескінченних рядів виноградної лози, Біллі здебільшого ухиляється від хатньої роботи й носиться сільськими луками центрального Лісу Елвінн. Як і вся його рідня, він добре знає про давню ворожнечу між Маклюрами та Стоунфілдами, та для Біллі ця чвара — радше гра в витівки й дрібні крадіжки, ніж серйозний конфлікт."},{t="Украдене намисто",b="Пустощі Біллі перейшли межу, коли він поцупив дороге сімейне намисто тітоньки Берніс Стоунфілд. Бігаючи біля небезпечної Копальні Фарґодіп, наляканий хлопчисько випустив дрібничку з рук. Перш ніж він устиг її підібрати, намисто вхопив особливо здоровий і лютий кобольд на ім'я Золотозуб і зник у підземних тунелях. Боячись і підземної погані, і гніву сусідських старших, Біллі не бажає зізнаватися, доки його не підкуплять смачним хабарем — а саме гарячим пирогом зі свинячою грудинкою, спеченим самою тітонькою Берніс."}},faq={{q="Хто такий Біллі Маклур?",a="Біллі Маклур — хлопчик, що живе на Виноградниках Маклюрів у Лісі Елвінн. Він днями ухиляється від роботи на фермі, бешкетує й дратує сусідів Стоунфілдів.",al={"хто такий біллі","лор біллі маклура","хлопець маклур"}},{q="Де знайти Біллі Маклура?",a="Біллі стоїть просто біля головної стодоли на Виноградниках Маклюрів у центрі Лісу Елвінн, на південний захід від Ферми Стоунфілдів.",al={"місце біллі маклура","де біллі","знайти біллі маклура"}},{q="Що Біллі заподіяв Тітоньці Берніс?",a="Біллі прокрався на Ферму Стоунфілдів і вкрав родинне намисто Тітоньки Берніс Стоунфілд — усе через давню ворожнечу між їхніми родинами.",al={"намисто берніс","що біллі вкрав","вкрадене намисто ельвін"}},{q="Що сталося з намистом, яке вкрав Біллі?",a="Безтурботно граючись біля входу до Копальні Фарґодіп, Біллі впустив намисто. Його швидко підібрав Золотозуб — горезвісний і грізний кобольд, що відніс його глибоко в копальню.",al={"де намисто","загублене намисто ельвін","у кого намисто берніс"}},{q="Як змусити Біллі зізнатися, що сталося з намистом?",a="З упертості й страху перед покаранням Біллі не хоче казати правду, але перед своїм апетитом не встоїть. Варто почастувати його свіжим пирогом із грудинкою від Тітоньки Берніс — і язик у нього розв'яжеться.",al={"пиріг для біллі","як підкупити біллі","підкуп біллі маклура"}},{q="Хто такий Золотозуб?",a="Золотозуб — надзвичайно великий і лютий ватажок кобольдів, що гніздиться в Копальні Фарґодіп. Він ухопив загублене намисто Тітоньки Берніс біля входу до копальні й ховає його в темних тунелях.",al={"хто такий золотозуб","лор золотозуба","кобольд фарґодіп"}}},fp="13,336,22.504.0,19.617.1,21.202.0,33.160.0,36.147.0,42.197.1,62.209.1,17.209.1"}
P.entries["npc:bingles-blastenheimer"] = {n="Бінґлз Бластенгаймер",s="Бінґлз Бластенгаймер — дивакуватий гномський авіатор, що застряг на південно-східному березі озера в Лох Модані. Аварійно посадивши свою експериментальну літальну машину, він опинився посеред місцевих трогів і звірів і відчайдушно намагається врятувати свої дорогоцінні інструменти й деталі.",h="Бінґлз Бластенгаймер — дивакуватий гномський авіатор, що застряг на південно-східному березі озера в Лох...",kw={"бінґлз бластенгаймер","гном","авіатор","гірокоптер","лох модан","троги","аварія"},ang={["profession:Engineering"]="Будь-який винахідник зрозуміє біду того, хто після невдалого пробного польоту втратив незамінні саморобні ключі й пристрої в лапах місцевої звірини.",["race:Gnome"]="Бінґлз утілює суто гномську жагу до повітряних винаходів, де поломки й вибухи — лише дрібні затримки на шляху поступу."},sec={{t="Жорстка посадка",b="Як і багато честолюбних гномських інженерів, Бінґлз Бластенгаймер піднявся в небо на саморобній літальній машині — і з'ясував, що безпечно сісти куди важче, ніж злетіти. Його гірокоптер зламався й розбився об південно-східний берег озера; сам Бінґлз пережив удар без жодної подряпини, а от машина розлетілася на друзки. Застрягши далеко від Айронфорджа, він тулиться біля уламків, остерігаючись голодних кроколісків і ворожих трогів, і благає перехожих зібрати його розкидані інструменти, щоб він міг знову скласти свій винахід докупи."}},faq={{q="Хто такий Бінґлз Бластенгаймер?",a="Бінґлз Бластенгаймер — гном-пілот і майстер, що зазнав страшної аварії на своїй літальній машині на південно-східному березі Озера в Лох Модані.",al={"хто такий бінґлз","лор бінґлза бластенгаймера","хто гном біля озера"}},{q="Що сталося з його літальною машиною?",a="Бінґлз розбив свій гірокоптер на березі. Від удару машина розлетілася, а його головні інструменти, запчастини й деталі двигуна розкидало по довколишній глушині й воді.",al={"чому бінґлз розбився","гіроплан бінґлза","що сталося з літаком бінґлза"}},{q="Чому Бінґлз не повернувся до міста?",a="Бінґлз опинився сам-один в облозі небезпечних хижаків і трогів, що заполонили береги озера. Без загублених інструментів і спорядження він не хоче кидати уламки справи свого життя.",al={"чому бінґлз застряг","чому біля озера"}},{q="Куди Бінґлз подається, коли машину полагоджено?",a="У цю епоху Бінґлз лишається на місці аварії на південно-східному березі Озера й чекає, поки шукачі пригод повернуть йому загублені припаси.",al={"куди йде бінґлз","ложа бінґлза"}}},fp="21,283,15.597.0,29.161.0,36.192.0,36.193.0,51.138.1"}
P.entries["npc:bink"] = {n="Бінк",s="Бінк — гномка, наставниця магів, що мешкає в Залі Таїнств у Кварталі містиків Айронфорджа. Кмітлива й завзята, вона веде майбутніх заклиначів крізь тонкощі таємних мистецтв і зводить їх із видатними чарівниками по всьому Альянсу.",h="Бінк — гномка, наставниця магів, що мешкає в Залі Таїнств у Кварталі містиків Айронфорджа.",kw={"бінк","маг","наставниця","гномка","зала таїнств","містичний квартал","айронфордж"},ang={["class:Mage"]="Для магів Альянсу, що гостюють чи осіли в Айронфорджі, Бінк — важлива наставниця й давачка завдань, яка відправляє учнів навчатися в могутніх наставників по всьому Азероту.",["race:Gnome"]="Бінк утілює невпинне прагнення до таємної майстерності серед гномів-вигнанців, що знайшли прихисток у великих залах своїх дворфійських союзників."},sec={{t="Маяк у Залі Таїнств",b="У Кварталі містиків Айронфорджа Бінк стоїть серед зібраних у Залі Таїнств учених, жерців і чародіїв. Як і багато гномів, вигнаних із Гномреґану, вона пристосувалася до життя в дворфійській гірській твердині, пропонуючи свій гострий розум і знання таємного ремесла тим, хто вчиться на мага. Вона добре знайома з чарівниками по всіх Східних Королівствах і Калімдорі й регулярно скеровує перспективних учнів до визначніших наставників, як-от Верховного Чаклуна Андромата в Стормвінді чи Табети в Багні Пилоброду."}},faq={{q="Хто така Бінк?",a="Бінк — гномка, наставниця магів Альянсу в Залі Таїнств у Кварталі містиків Айронфорджа. Вона навчає тайних заклять і стає наставницею й зв'язковою для молодих магів.",al={"лор бінк","хто така бінк","бінк айронфордж"}},{q="Де знайти Бінк?",a="Вона перебуває в Залі Таїнств, у західному крилі Кварталу містиків в Айронфорджі.",al={"місце бінк","де бінк","знайти бінк"}},{q="Які завдання пов'язані з Бінк?",a="Молодих магів направляють до неї завданнями на кшталт «Поговоріть із Бінк». Вона ж скеровує магів на подальше навчання — до таких авторитетів, як Верховний Чаклун Андромат у Фортеці Стормвінда чи маг-відлюдниця Табета в Багні Пилоброду.",al={"завдання бінк","завдання поговорити з бінк"}},{q="Що Бінк каже тим, хто не є магом?",a="Якщо до неї звертається хтось, хто не володіє тайною магією, вона бадьоро дає практичну пораду: «Заприятелюйте з магом! У нас у рукаві знайдеться фокус-другий, так-так...»",al={"плітки бінк","діалог бінк"}}},fp="4,266,33.549.0,12.201.0,22.122.0,25.246.0,32.170.0"}
P.entries["npc:bishop-delavey"] = {n="Єпископ ДеЛаве",s="Єпископ ДеЛаве — високопоставлений представник Церкви Святого Світла, що служить у Палаті Прохача у Фортеці Стормвінда. Опікуючись справами держави й віри, він тихо наглядає за делікатними справами двору, про які Корона не може говорити відкрито.",h="Єпископ ДеЛаве — високопоставлений представник Церкви Святого Світла, що служить у Палаті Прохача у Фортеці...",kw={"єпископ делаве","палата прохача","церква святого світла","зниклий дипломат","йорґен","еллінг тріас"},ang={["class:Priest"]="ДеЛаве — яскравий приклад глибокої політичної залученості церкви в Стормвінді: віра у Святе Світло часто перетинається з державними справами й таємними оборудками.",["faction:Alliance"]="Його таємне розслідування покликане вберегти хиткий мир між Стормвіндом і Терамором, форпостом Леді Джайни Праудмур."},sec={{t="Єпископ при дворі",b="Поки Архієпископ Бенедиктус опікується Собором Світла, Єпископ ДеЛаве перебуває серед вельмож і прохачів у Фортеці Стормвінда. Він слугує церковним посередником при дворі, поєднуючи духовні поради з політичною дійсністю королівства. Його становище дає змогу чути шепіт чуток і делікатні палацові скарги ще до того, як вони дійдуть до вух Верховного Лорда Болвара Фордрагона чи юного короля Андуїна."},{t="Делікатне розслідування",b="Коли важливий дипломат, якого послали на зустріч із Леді Джайною Праудмур у Терамор, так і не дістався туди, двір тримав зникнення в суворій таємниці, щоб не посіяти паніки. Підозрюючи підступну руку Братства Дефіас, ДеЛаве оминув звичний порядок варти. Натомість він задіяв приватні канали й обачних шукачів пригод, через таких знайомих, як рибалка Йорґен, налагоджуючи зв'язок із таємними інформаторами на кшталт Еллінга Тріаса."}},faq={{q="Де знайти Єпископа ДеЛаве?",a="Єпископ ДеЛаве стоїть у Палаті Прохача у Фортеці Стормвінда, одразу біля головного входу, де піддані збираються, щоб звернутися до королівського двору.",al={"місце деляве","де єпископ деляве","фортеця деляве"}},{q="Яка його роль у Фортеці Стормвінда?",a="Він представляє Церкву Святого Світла при королівському дворі: веде церковні справи, радить знаті й делікатно розв'язує непрості питання королівства.",al={"робота деляве","хто єпископ деляве","що робить деляве"}},{q="Чому він розслідує зникнення дипломата?",a="Дипломат зник дорогою на зустріч із Леді Джайною Праудмур у Тераморі. ДеЛаве підозрює втручання Дефіасу й тихо розслідує справу через надійні канали, перш ніж звістка про кризу посіє паніку серед людей.",al={"зникнення дипломата деляве","чому деляве цікавиться дипломатом"}},{q="Що пов'язує ДеЛаве з Еллінгом Тріасом?",a="ДеЛаве користується мережею посередників, серед яких рибалка Йорґен, щоб передавати повідомлення Еллінгові Тріасу — майстрові сирної справи, що потай збирає відомості для SI:7.",al={"деляве й тріас","контакт деляве сі7"}}},fp="14,256,17.423.0,18.442.1,34.154.0,35.172.0,45.207.0,41.175.1"}
P.entries["npc:blanchy"] = {n="Білявка",s="Стара Білявка — вірна, працьовита кобила Теодора й Верни Фурлброу, що нині відпочиває біля їхнього воза неподалік Хутора Дженсена у Вестфолі. Славна своєю лагідною вдачею й неабияким апетитом, вона лишається надійною супутницею своїх господарів серед негод, що охопили сільський край.",h="Стара Білявка — вірна, працьовита кобила Теодора й Верни Фурлброу, що нині відпочиває біля їхнього воза...",kw={"стара білявка","верна фурлброу","вестфол","кобила","овес","біженці"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що йдуть на південь із Лісу Елвінн до Вестфолу, нагодувати Стару Білявку — часто один з перших тихих добрих учинків для бідолашних місцевих біженців."},sec={{t="Вірна помічниця на фермі",b="Задовго до того, як тягти воза Фурлброу курявою Вестфолу, Білявка зростала в північних стайнях Таррен Мілла в Гілсбреді. Її продали на південь, за море, працювати в житниці Стормвінда, і там вона здобула славу надзвичайно лагідної й чемної кобили. Десятиліття тяжкої праці зробили з неї «Стару Білявку», а виснажлива дорога, коли родина тікала з неспокійного хутора, геть її втомила. Хоч утома й помітна, апетит у неї добрий, і мандрівникам, які принесуть їй жмені поживного вівса, розсипаного навколишніми полями, Верна дарує улюблену Білявчину попону й торбу для корму."}},faq={{q="Чия Білявка?",a="Білявка належить Теодорові й Верні Фурлброу — поселенцям, що мандрують Вестфолом. Вона їхня незмінна тяглова кобила й улюблениця всієї родини.",al={"чия білявка","кому належить білявка","кінь фурлброу"}},{q="Звідки родом Білявка?",a="Вона народилася й виросла далеко на півночі, у Лордероні, у стайні в Таррен Міллі в Передгір'ї Гілсбреда. Ще лошам її перевезли через Саутшор і відправили кораблем на південь через Велике Море, на ферму у Вестфолі.",al={"походження білявки","звідки білявка","молода білявка"}},{q="Навіщо Верні Фурлброу овес для Білявки?",a="Роки праці й довга дорога небезпечними шляхами Вестфолу геть виснажили Стару Білявку. Верна просить мандрівних шукачів пригод назбирати решту мішків вівса на сусідніх фермах, щоб повернути вірній кобилі сили.",al={"овес білявки","чому годувати білявку","кінь фурлброу втомлений"}},{q="Де знайти Білявку?",a="Стара Білявка стоїть запряжена біля воза Фурлброу на головній дорозі поблизу Садиби Джансена в центрі Вестфолу.",al={"місце білявки","де стара білявка","білявка на мапі"}}},fp="7,303,19.643.0,17.160.0,39.223.0,46.237.0,27.115.0"}
P.entries["npc:blind-hunter"] = {n="Сліпий Мисливець",s="Сліпий Мисливець — невловимий кажан-альбінос, що гніздиться глибоко в Рейзорфен Краулі. На відміну від звичайних кажанів, що тримаються біля входів до печер, це рідкісне створіння полює в безсонячних глибинах редуту шипогривів.",h="Сліпий Мисливець — невловимий кажан-альбінос, що гніздиться глибоко в Рейзорфен Краулі.",kw={"сліпий мисливець","кажан","альбінос","рейзорфен краул","рідкісний звір"},ang={["class:Hunter"]="Для приборкувачів звірів, що мандрують Пустками, Сліпий Мисливець — цінна здобич: чи то як рідкісний звір-альбінос, якого можна приручити, чи то як джерело майстерно зроблених луків із підземелля."},sec={{t="Глибини Краула",b="Рейзорфен Краул пронизаний звивистими терновиками й темними підземними печерами. Звичайні кажани Краула гніздяться ближче до поверхні, куди просочується тьмяне світло ззовні, а Сліпий Мисливець цілком пристосувався до найвіддаленіших, найтемніших закутків гущавини. Його бліда шкура альбіноса й каламутний погляд, найімовірніше, — наслідок поколінь, проведених цілком без сонячного світла."},{t="Рідкісна здобич",b="Як і каже його ім'я, учені й розвідники вважають, що створіння втратило більшу частину чи й увесь звичайний зір і натомість покладається на гострий слух і ехолокацію, вистежуючи здобич у мороці. Воно рідко показується, лише зрідка виходячи полювати серед густих хащів, тож зустріч із цим примарним звіром — цінна подія для дослідників печер."}},faq={{q="Що таке Сліпий Мисливець?",a="Сліпий Мисливець — рідкісний кажан-альбінос, що живе в найглибших, непроглядно темних тунелях Рейзорфен Краулу. Він напрочуд блідий і невловимий порівняно зі звичайними печерними кажанами, що водяться ближче до входу.",al={"хто сліпий мисливець","що таке сліпий мисливець","кажан сліпий мисливець"}},{q="Де з'являється Сліпий Мисливець?",a="Він живе в темних внутрішніх ходах Рейзорфен Краулу й гніздиться далеко за тією межею, де денне світло зовсім згасає.",al={"місце сліпого мисливця","де знайти сліпого мисливця","поява сліпого мисливця"}},{q="Чи справді Сліпий Мисливець сліпий?",a="Натуралісти й шукачі пригод підозрюють, що він справді сліпий, бо має молочно-білі очі й живе в глибоких печерах, але полює він бездоганно, покладаючись у темряві на гострий слух і ехолокацію.",al={"чи він сліпий","чи бачить сліпий мисливець"}},{q="Чи можуть мисливці приборкати Сліпого Мисливця?",a="Так, звіролови, що вміють поводитися з крилатими хижаками, можуть приборкати Сліпого Мисливця й отримати незвичного блідого супутника, якщо матимуть терпіння його вистежити.",al={"чи можна приборкати сліпого мисливця","сліпий мисливець приборкується","сліпий мисливець улюбленець"}},{q="Чому Сліпий Мисливець білий?",a="Це альбінос, і його забарвлення, найімовірніше, виникло від життя у вічній темряві, куди не сягає сонце, — на відміну від кажанів, що вилітають до входу в печеру.",al={"чому він альбінос","чому сліпий мисливець білий","кажан-альбінос"}},{q="Чим він відрізняється від звичайних кажанів Краулу?",a="Звичайні кажани Краулу мають темне забарвлення й живуть ближче до входу, куди ще пробивається світло, а Сліпий Мисливець блідий, відлюдний і пристосований лише до глибоких підземних тунелів.",al={"різниця з кажанами краулів","кажан краулів проти сліпого мисливця"}}},fp="12,212,19.390.0,13.376.0,25.200.0,35.134.0,35.203.0,34.163.0,30.169.0,43.209.0"}
P.entries["npc:blind-mary"] = {n="Сліпа Мері",s="Сліпа Мері — змучена банші, що блукає покинутою, зруйнованою хатою на південний схід від Даркшира в Сутінколіссі. Колись вона була марнославною й вродливою смертною жінкою, але насильницька смерть і перетворення довели її до того, що з горя вона скалічила себе.",h="Сліпа Мері — змучена банші, що блукає покинутою, зруйнованою хатою на південний схід від Даркшира в...",kw={"сліпа мері","банші","привид","даркшир","сутінколісся","дзеркальце"},ang={["class:Priest"]="Мері — трагічний приклад душі, яку жахлива травма позбавила спокою: через горе й марнославство вона застрягла на півдорозі між життям і прокляттям.",["faction:Alliance"]="Трагічна доля Сліпої Мері — болюче нагадування захисникам Даркшира, як глибоко прокляття Сутінколісся скалічило життя простих містян.",["profession:Tailoring"]="Майстри ткацтва часом шукають таких примар, як Мері, заради ниток із волосся привидів — тонкого надприродного матеріалу, сплетеного з ефірних решток."},sec={{t="Трагічне марнославство",b="Доки тінь не лягла на Сутінколісся, Мері знали як ефектну жінку, що неабияк пишалася своєю вродою й рідко розлучалася з улюбленим дзеркальцем. Коли нежить заполонила край, Мері загинула разом із багатьма сусідами. Та, на відміну від тих, хто знайшов спокій у землі, її дух лишився серед живих — безтілесною банші, приреченою блукати світом смертних у моторошній, напівпрозорій подобі."},{t="Осліплена відчаєм",b="Прокинувшись нежиттю, Мері знетямилася від скорботи, жаху й люті, побачивши своє потворне відображення. Не в змозі витримати вигляд свого примарного обличчя, вона голими руками видерла собі очі, щоб більше ніколи на себе не дивитися. У муках вона викинула улюблене дзеркальце й відтоді блукає своїм покинутим домом — сліпа, заплакана примара, що чіпляється за бліді спогади про втрачене смертне життя."}},faq={{q="Хто така Сліпа Мері?",a="Сліпа Мері — банші, що блукає зруйнованою садибою на південно-східній околиці Даркширу. За життя вона була вродливою місцевою жінкою, але загинула, коли Сутінколісся поринуло в темряву, і повстала неживим духом.",al={"хто така сліпа мері","історія сліпої мері","лор сліпої мері","сліпа мері сутінколісся"}},{q="Чому її називають Сліпою Мері?",a="Пойнята горем і відчаєм через свою жахливу подобу банші, Мері голими руками видерла собі очі, щоб ніколи більше не бачити свого відображення.",al={"чому вона сліпа","як сліпа мері втратила очі","очі сліпої мері"}},{q="Де живе Сліпа Мері?",a="Вона перебуває в занедбаному фермерському будинку, відомому як Притулок Сліпої Мері, трохи на південний схід від містечка Даркшир на сході Сутінколісся.",al={"місце сліпої мері","де сліпа мері","прихисток сліпої мері"}},{q="Чи ворожа Сліпа Мері до живих мандрівників?",a="На відміну від лютих гулів і скелетів, що блукають довколишніми лісами, Сліпа Мері не нападає на мандрівників одразу. Вона застигла в скорботі, і з нею може поговорити кожен, хто наблизиться до її руїни.",al={"чи ворожа сліпа мері","чи нападає сліпа мері","чи можна говорити зі сліпою мері"}},{q="Що сталося з дзеркалом Мері?",a="Видерши собі очі з жаху перед своєю примарною подобою, Мері викинула своє дороге дзеркало, і воно загубилося десь у моторошних нетрях Сутінколісся.",al={"дзеркало мері","дзеркальце сліпої мері","що сталося з її дзеркалом"}},{q="Чому шукачі пригод навідуються до Сліпої Мері?",a="Мандрівники й місцеві ремісники приходять до Мері, виконуючи доручення в околицях Даркширу: щоб повернути давно загублені речі, як-от її викинуте дзеркало, зібрати примарне волосся для особливого шиття або повернути забуті особисті пам'ятки, щоб заспокоїти її змучений дух.",al={"завдання сліпої мері","чому відвідувати сліпу мері","ланцюжок завдань сліпої мері"}}},fp="10,265,15.415.0,18.434.0,18.232.0,29.171.0,28.141.0,42.210.0,38.165.0,39.262.0"}
P.entries["npc:bloodmage-drazial"] = {n="Маг Крові Дразіал",s="Маг Крові Дразіал — ельф крові, що практикує таємну магію й магію крові та отаборився на півночі Спустошених Земель. Разом із сестрою Ліннор він вивчає місцевих звірів червоних пустирів, щоб готувати для мандрівних шукачів пригод могутні алхімічні зілля.",h="Маг Крові Дразіал — ельф крові, що практикує таємну магію й магію крові та отаборився на півночі Спустошених...",kw={"дразіал","маг крові","ельфи крові","спустошені землі","алхімія","ліннор","зілля"},ang={["class:Mage"]="Дразіал уособлює суперечливий відхід ельфів крові від традицій: він відкрито вдається до магії крові та біологічних реагентів, щоб синтезувати таємні посилення, а не покладається суто на класичне чародійство Кірін-Тору."},sec={{t="Алхімічні студії в червоних пустирях",b="Маг Крові Дразіал, що отаборився біля північного перевалу, де Болото Скорботи переходить у Спустошені Землі, вдається до своєрідної магії. Поки чимало високих ельфів цураються заборонених мистецтв чи впадають у відчай через долю Кель'Таласу, Дразіал і його сестра Ліннор використовують магію крові, щоб черпати силу із суворого довкілля. Спотворена фауна пустирів — скорпоки, гієни-хихоікли й спустошені вепри — вбирає незвичну магічну енергію з їжею та самим виживанням на багряному ґрунті. Добуваючи певні органи й тканини цих створінь, Дразіал варить мінливі зілля, що дарують величезні сплески фізичної сили, спритності й витривалості."},{t="Незалежний постачальник",b="На відміну від багатьох фракційних посланців у Спустошених Землях, Дразіал тримається практичної відстороненості. Він не присягав ні Альянсу, ні Орді й продає свої алхімічні знання кожному, хто достатньо витривалий, щоб пройти пустирем і зібрати потрібну йому сировину. Доки мандрівники приносять йому органи місцевих хижаків, Дразіал залюбки тримає свої казани на вогні."}},faq={{q="Хто такий Маг Крові Дразіал?",a="Маг Крові Дразіал — маг із кривавих ельфів, що отаборився біля північного входу до Спустошених Земель. Разом зі своєю сестрою Ліннор він вивчає місцевих звірів і варить потужні алхімічні реагенти з частин, зібраних з осквернених створінь краю.",al={"хто такий дразіал","лор дразіала","маг крові дразіал нпс"}},{q="Навіщо Дразіал збирає частини звірів?",a="Створіння Спустошених Земель пристосувалися виживати на отруєній, насиченій магією землі. Дразіал використовує сильнодійні нутрощі вепрів, гієн, скорпіонів і василісків, щоб варити особливі еліксири, які посилюють фізичну міць воїна.",al={"чому дразіал хоче легені вепрів","предмети завдання дразіала","органи звірів дразіала"}},{q="Дразіал працює на Альянс чи на Орду?",a="Дразіал нейтральний до обох фракцій. Він і Ліннор не переймаються війною між Стормвіндом і Ордою й охоче мають справу з будь-яким шукачем пригод, що готовий постачати матеріали для їхніх магічних і алхімічних досліджень.",al={"фракція дразіала","дразіал орда чи альянс","чи альянс може говорити з дразіалом"}},{q="Хто ще з кривавих ельфів отаборився з ним?",a="Поряд із ним — його сестра, Маг Крові Ліннор. Разом брат і сестра практикують магію крові й варять особливі зілля з різних звірів, що блукають Спустошеними Землями.",al={"супутник дразіала","хто з дразіалом","ліннор"}}},fp="17,267,36.648.0,23.431.0,25.255.0,39.255.0,48.220.0,43.177.0"}
P.entries["npc:bloodmage-lynnore"] = {n="Маг Крові Ліннор",s="Маг Крові Ліннор — ельфійка крові, що практикує заборонену магію крові й отаборилася разом із братом Дразіалом біля північного входу до Спустошених Земель. Вона допомагає шукачам пригод, готуючи з органів місцевих звірів могутні алхімічні настої.",h="Маг Крові Ліннор — ельфійка крові, що практикує заборонену магію крові й отаборилася разом із братом...",kw={"ліннор","маг крові","ельфи крові","спустошені землі","еліксири","дразіал"},ang={["class:Mage"]="Для магів, яких захоплює нетрадиційне чародійство, Ліннор уособлює рідкісну й суперечливу гілку таємної філософії, що оперує життєвою сутністю, а не звичною енергією лей-ліній.",["faction:Horde"]="Ліннор — цінний тактичний зв'язок Орди в Спустошених Землях: вона торгує унікальними алхімічними реагентами й ділиться темними таємними знаннями, щоб посилити Орду в боротьбі з місцевими демонічними загрозами."},sec={{t="Майстриня магії крові",b="Маг Крові Ліннор, що отаборилася разом із братом Дразіалом біля північного входу до Спустошених Земель, — одна з надзвичайно рідкісних ельфів у Східних Королівствах, які практикують магію крові. Сувора, згубна природа Спустошених Земель її не бентежить: вона вивчає приховані таємні й життєві енергії, що струменять у тілах місцевих звірів. Мандрівники, які приносять їй мозки й шлунки тутешньої фауни, бачать, як вона перетворює ці моторошні реагенти на особливі еліксири, що значно посилюють інтелект і дух."}},faq={{q="Хто така Маг Крові Ліннор?",a="Маг Крові Ліннор — кривава ельфійка, маг крові, що отаборилася біля північного входу до Спустошених Земель. Вона дає завдання й знається на алхімії: в обмін на частини звірів пропонує потужні зілля, що посилюють характеристики.",al={"хто така ліннор","лор мага крові ліннор","ліннор попелясті землі"}},{q="Де знайти Маг Крові Ліннор?",a="Вона отаборилася разом із братом, Магом Крові Дразіалом, біля північного входу до Спустошених Земель, там, де перевал із Болота Скорботи виходить на пустку.",al={"місце ліннор","де ліннор","як знайти ліннор"}},{q="Які зілля вона варить?",a="Ліннор використовує частини місцевих звірів — мозок василісків, шлунки грифів, щелепи гієн-шкірозубів, — щоб варити рідкісні тоніки на кшталт Суміші Мозкової Кори й Жуйки зі Шлунку, які надовго посилюють інтелект і дух.",al={"баффи ліннор","зілля ліннор попелясті землі","сполука мозкової кори"}}},fp="17,249,21.549.0,25.228.0,37.168.0,31.252.0"}
P.entries["npc:bloodmage-thalnos"] = {n="Маг Крові Талнос",s="Маг крові Талнос — маг-кістяк, що блукає в крилі Кладовища Багряного Монастиря. Колись він був катом-дізнавачем Багряного Хрестового Походу, але й сам піддався чумі нежиття, з якою так фанатично боровся, — і все ж досі тримається в глибині їхніх святих земель.",h="Маг крові Талнос — маг-кістяк, що блукає в крилі Кладовища Багряного Монастиря.",kw={"маг крові талнос","багряний монастир","кладовище","нежить","багряний хрестовий похід","тортури"},ang={["class:Mage"]="Талнос — приклад катастрофічного виродження магічних амбіцій, коли вони сплітаються з фанатичним безумством і чумою.",["class:Priest"]="Талнос серед гробниць — тривожне свідчення того, як легко фанатизм і тортури кличуть пітьму замість божественної благодаті.",["faction:Horde"]="Відступники бачать у Талносі живий доказ лицемірного безумства Багряного Хрестового Походу: потвора, що катувала інших за заразу, зрештою сама стала нежиттю, яку так ненавиділа."},sec={{t="Падіння інквізитора",b="У ревних лавах Багряного Хрестового Походу Талнос зажив темної слави своїми жорстокими тортурами, які чинив під приводом очищення новобранців від зарази. Та попри фанатичну відданість викоріненню зла, маг-садист зрештою сам піддався чумі нежиття. Його не очистили й не знищили назавжди: він повстав зсохлим кістяком, що досі чіпляється за свою вогняну магію й майстерність у таємних мистецтвах."},{t="Володар Кладовища",b="Замкнений у найглибшому куті монастирських гробниць під відкритим небом, Талнос посилає примар і шкутильгаючих мерців на кожного, хто потривожить його володіння. Його присутність — гірка суперечність для Хрестового Походу: нежива потвора ховається просто під їхніми священними залами й уособлює те саме жахіття, яке вони присягнули викорінювати повік."}},faq={{q="Хто такий Маг Крові Талнос?",a="Колись Талнос був жорстоким інквізитором і магом Багряного Хрестового Походу, що жахливими тортурами перевіряв новобранців на зіпсуття. За іронією долі він сам підхопив чуму нежиття й перетворився на скелета-заклинача, що блукає цвинтарем Монастиря.",al={"хто такий талнос","лор талноса","інфо про талноса"}},{q="Чому неживому скелетові дозволено бути в Багряному Монастирі?",a="Хрестовий Похід фанатично страчує всю нежить на місці, тож те, що Талнос досі існує, — дивина. Він засів у дальньому кінці Цвинтаря серед повсталих склепів і духів і блукає своїми опоганеними володіннями, а не ходить вільно серед живих хрестоносців.",al={"чому талнос у монастирі","чому багряний хрестовий похід тримає талноса","нежить-маг багряних"}},{q="Якою силою володіє Талнос?",a="Хоч Талнос і зберіг звання мага крові та повстав скелетом, він володіє вогняними закляттями й магією тіні, а ще викликає мстивих духів і ходячих мерців, щоб здолати непроханих гостей на цвинтарі.",al={"закляття талноса","магія талноса","що робить талнос"}},{q="Чи був Талнос кривавим ельфом?",a="His original mortal lineage is uncertain. The title Bloodmage alone does not establish that he was a blood elf.",al={"чи талнос був високим ельфом","раса талноса","якої раси був талнос"}},{q="Хто хоче смерті Талноса?",a="Thalnos is hostile to intruders in the monastery's graveyard. No specific commission to kill him is established here for this era.",al={"хто хоче смерті талноса","завдання талноса","темна сторона світла талнос"}}},fp="17,283,21.444.0,23.362.0,25.262.0,59.256.0,31.200.0,24.111.0,23.130.0"}
P.entries["npc:bluff-runner-windstrider"] = {n="Скелебіжець Вітроступ",s="Скелебіжець Вітроступ — мандрівний гонець-таурен, що бігає столовими горами Тандер Блафа. Він розносить містом нагальні донесення й скеровує шукачів пригод Орди до далеких рубежів — Ашенвалю, Фераласу й Чумних Земель.",h="Скелебіжець Вітроступ — мандрівний гонець-таурен, що бігає столовими горами Тандер Блафа.",kw={"скелебіжець вітроступ","гонець","тандер блаф","ашенваль","фералас","чумні землі","сенані тандергарт"},ang={["faction:Horde"]="Вітроступ — важливий місток між мирними рівнинами Малгору й кривавими фронтами, де Орда бореться за ресурси й виживання.",["race:Tauren"]="Традиційні гінці, як-от Вітроступ, підтримують зв'язок між розпорошеними племенами й старійшинами в столиці, не покладаючись ні на сучасні механізми, ні на чужоземні поштові мережі."},sec={{t="Гонець на столових горах",b="Високі плато Тандер Блафа потребують прудких ніг, щоб провідники й гості міста завжди знали новини, — і цю важливу роль виконує Скелебіжець Вітроступ. Невтомно бігаючи мотузяними мостами й стежками столиці тауренів, він служить і міським глашатаєм, і посильним. Коли ключовим заставам у Калімдорі чи Східних Королівствах потрібне підкріплення, Вітроступ зупиняє чемпіонів, що проходять повз, щоб ті передали звістку й відгукнулися на заклик до зброї."},{t="Поклики з рубежів",b="Донесення Вітроступа сягають далеко за мирні межі Малгору. Він скеровує шукачів пригод на північ, до Ашенвалю, щоб приєднатися до великого полювання Сенані Тандергарт на Заставі Розщепленого Дерева, відсилає загартованих розвідників на південь, до Табору Моджаче в глибинах Фераласу, і передає грізні застереження про загрозу нежиті в Західних Чумних Землях, що не вщухає. Через нього племінне серце Малгору лишається зв'язаним із ширшими війнами Орди."}},faq={{q="Хто такий Скелебіжець Вітроступ?",a="Скелебіжець Вітроступ — таурен-гонець, що бігає Тандер Блафом. Він розносить новини й закликає вправних мандрівників Орди допомогти в нагальних походах по всьому Азероту.",al={"вітроступ нпс","скелебіжець","хто такий вітроступ"}},{q="Де знайти Скелебіжця Вітроступа?",a="Вітроступ не стоїть на одному місці. Він постійно бігає мостами й терасами Тандер Блафа, часто кружляючи між центральною столовою горою й сусідніми ярусами.",al={"місце вітроступа","де скелебіжець","знайти вітроступа"}},{q="Які завдання дає Вітроступ?",a="Він дає завдання-скерування, що ведуть шукачів пригод, які набираються сили, до далеких спірних країв: на полювання в Ашенвалі, до заснування Табору Моджаче у Фераласі та на заклики до зброї в Чумних Землях.",al={"завдання вітроступа","що він дає","завдання скелебіжця"}},{q="Чому його звуть скелебіжцем?",a="Таурени покладаються на спритних, витривалих бігунів, щоб передавати вісті скелястими столовими горами, кручами й підвісними мостами Тандер Блафа, де верхи їздити незручно чи повільно.",al={"що таке скелебіжець","титул скелебіжця"}}},fp="24,237,24.431.0,21.424.0,32.193.0,42.182.0,35.206.0,34.186.0"}
P.entries["npc:bolvar-fordragon"] = {n="Болвар Фордрагон",s="Верховний Лорд Болвар Фордрагон — регент Стормвінда й верховний командувач його збройних сил після загадкового зникнення короля Варіана Рінна. Стоячи поруч із юним королем Андуїном Рінном у Фортеці Стормвінда, він намагається втримати королівство докупи серед дедалі гірших внутрішніх негараздів. Хоч Болвар — людина незламної честі, його військові рішення часто спрямовує й гальмує королівська радниця Леді Катрана Престор.",h="Верховний Лорд Болвар Фордрагон — регент Стормвінда й верховний командувач його збройних сил після...",kw={"болвар","фордрагон","болвар фордрагон","регент","стормвінд","катрана престор"},ang={["class:Paladin"]="Болвар — взірець бойових паладинів Альянсу: він непохитно відданий Світлу й своєму народові, попри дедалі підступніші політичні інтриги.",["faction:Alliance"]="Як верховний командувач Стормвінда, Болвар очолює військо людей: він придушує місцеві заколоти й водночас виконує ширші зобов'язання перед Альянсом."},sec={{t="Регент королівства",b="Коли король Варіан зник дорогою на мирні перемовини на Острові Терамор, Стормвінд поринув у політичний хаос. Десятирічного принца Андуїна коронували, щоб зберегти тяглість влади, але справжнє правління перейшло до Верховного Лорда Болвара Фордрагона як регента. Болвар — шанований паладин, відданий короні, та тягар на ньому величезний. Військо Стормвінда розпорошене по Вестфолу, Редріджу й Сутінколіссю. А на додачу Болвар часто прислухається до Леді Катрани Престор, чиї зневажливі поради раз у раз не дають йому послати королівські війська до віддалених містечок."},{t="Павутина обману",b="За лаштунками королівського двору руки Болвара зв'язані міцніше, ніж він здогадується. Поки міські магістрати й прикордонні маршали благають про підкріплення проти Братства Дефіас та орків Блекрок, Леді Престор непомітно перекручує королівські укази й применшує кожне донесення про небезпеку. Болвар шанує поради знаті й вагається діяти без незаперечних доказів, тим самим мимоволі паралізуючи корону. Лише коли надходять переконливі свідчення — як-от застереження з Терамора чи зниклі польові офіцери, — регент оминає звичний придворний порядок і наймає вільних шукачів пригод."}},faq={{q="Чому править Болвар, а не Король Варіан?",a="Король Варіан Рінн за підозрілих обставин зник, коли плив кораблем на дипломатичну зустріч на Острові Терамор. За його відсутності десятирічного сина Варіана, Андуїна, коронували, щоб зберегти політичний лад, а Верховного Лорда Болвара призначили регентом, щоб правити королівством і командувати його військами, доки короля не знайдуть.",al={"де король","чому болвар править","хто регент"}},{q="Чому Болвар не посилає солдатів на допомогу Редріджу чи Вестфолу?",a="Постійні війська Стормвінда розтягнуті на охорону серцевинних земель і кордонів. До того ж головна радниця Болвара, Леді Катрана Престор, раз у раз ставить під сумнів нагальність донесень із місць на кшталт Лейкширу, називає їх перебільшеннями й радить не виділяти королівських військ. Не маючи військових доказів, Болвар натомість доручає справу незалежним шукачам пригод.",al={"чому немає армії стормвінда","чому болвар не допоможе","війська лейкширу"}},{q="Які стосунки між Болваром і Леді Катраною Престор?",a="Леді Катрана Престор — перша королівська радниця при троні Стормвінда. Болвар поважає її політичну проникливість і глибоке знання справ знаті. Проте вона постійно використовує свій вплив, щоб радити стриманість і переконувати його відкидати чутки про драконів, орків і змови Дефіасу.",al={"болвар і престор","хто леді престор для болвара"}},{q="Що пов'язує Болвара з юним Андуїном?",a="Болвар Андуїнові не родич, але він — палкий захисник, опікун і наставник юного короля. Болвар стоїть біля трону Андуїна у Фортеці Стормвінда, оберігає хлопця від придворних інтриг і пильнує, щоб династія Ріннів була в безпеці, доки не повернеться Варіан.",al={"андуїн і болвар","чи болвар батько андуїна"}}},fp="16,433,19.604.0,15.612.1,44.334.0,60.380.0,56.284.0,51.271.0"}
P.entries["npc:braelyn-firehand"] = {n="Брейлін Файргенд",s="Брейлін Файргенд — ельфійська чародійка, що тихо живе серед Орди в Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Заявляючи, що прагне усунути містичні перепони на нагір'ї, вона наймає мандрівників ударити по охоронцях нічних ельфів на Піку Кам'яного Кігтя.",h="Брейлін Файргенд — ельфійська чародійка, що тихо живе серед Орди в Притулку Сонячної Скелі в Горах Кам'яного...",kw={"брейлін файргенд","притулок сонячної скелі","хранитель орданус","рада тіней","джеденар","криваві ельфи","пік кам'яного кігтя"},ang={["class:Druid"]="Навмисне вбивство синів Кенарія й осквернення притулків-лігв — огидний злочин проти рівноваги природи.",["class:Mage"]="Брейлін охоче говорить про лей-енергію й містичні перепони, приваблюючи товаришів-чародіїв, які розуміють, як чарівна магія тече крізь землю.",["faction:Horde"]="Брейлін радо наймає мандрівників з Орди для ударів по нічних ельфах, обертаючи тривалі сутички за землі в Калімдорі на прикриття для глибшого, темнішого задуму."},sec={{t="Несподівана гостя",b="Серед тауренських осель і простих орківських наметів Притулку Сонячної Скелі Брейлін Файргенд — рідкісне видовище: кривава ельфійка, що відкрито живе у віддаленому поселенні Орди. Шамани й вожді притулку терплять її присутність, схоже, не здогадуючись про її справжню вірність. Брейлін видає себе за дослідницю, зачаровану потоками магії в краї, і охоче наймає перехожих найманців Орди для небезпечних польових доручень серед скель."},{t="Образа на гай",b="Брейлін спрямовує своїх союзників проти друїдів нічних ельфів і священних нащадків Кенарія, що перебувають високо вгорі, на Піку Кам'яного Кігтя. Вона запевняє, що друїди душать навколишні лей-лінії й заважають чарівній енергії текти вершинами. Та насправді її мета глибоко особиста: вона плекає гіркі спогади про Хранителя Ордануса, пам'ятаючи давню пиху, з якою той ставив себе вище навіть за Високороджених. Вона охоче платить мандрівникам з Орди, щоб вони вистежили Ордануса й принесли його голову."},{t="Зв'язки з Джеденаром",b="Образа Брейлін — не просто давня ненависть, що тліє без діла; її цілі прямо збігаються з цілями секти Ради Тіней, що діє з Джеденара в Скверноліссі. Підбурюючи поборників Орди методично вирізати нічних ельфів і хранителів, які тримають священні вершини, вона розчищає шлях темнішим силам, ховаючи свою зловісну приналежність під личиною звичайних прикордонних сутичок."}},faq={{q="Хто така Брейлін Файргенд?",a="Брейлін Файргенд — ельфійка-маг, що живе в Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Хоч довкола неї Орда, вона переслідує власні магічні цілі проти нічних ельфів, що стережуть Пік Кам'яного Кігтя.",al={"хто така брейлін","лор брейлін файргенд","ельфійка в притулку сонячної скелі"}},{q="Що ельфійка робить у Притулку Сонячної Скелі?",a="Притулок Сонячної Скелі — гамірна, відокремлена прикордонна застава. Брейлін користується тим, що тут терпимо ставляться до чужинців і постійно проходять воїни Орди, щоб наймати їх для своїх особистих ударів по нічних ельфах, не викликаючи одразу підозри в провідників поселення.",al={"чому вона з ордою","чому брейлін у сонячній скелі","кривава ельфійка в стоунталоні"}},{q="Що вона хоче зробити на Піку Кам'яного Кігтя?",a="She asks adventurers to attack the druids and children of Cenarius at Stonetalon Peak, claiming that they stifle the flow of magic. Her later pursuit of Keeper Ordanus leads to Raynewood Retreat in Ashenvale.",al={"цілі брейлін","чому вбити ордануса","завдання брейлін файргенд"}},{q="Що пов'язує її з Хранителем Орданусом?",a="Брейлін твердить, що знала Хранителя Ордануса особисто в далекому минулому. Вона люто його ненавидить і запевняє, що він був неймовірно пихатий і вважав себе вищим навіть за давніх Високородних.",al={"брейлін і орданус","як вона знає ордануса","історія ордануса"}},{q="Що, за її словами, досліджує Брейлін Файргенд?",a="Braelyn claims that the druids and children of Cenarius at Stonetalon Peak are restricting the flow of magic. She wants them removed so that she can draw on that power.",al={"справжня фракція брейлін","брейлін тіньова рада","на кого працює вона"}},{q="Брейлін — маг чи чорнокнижниця?",a="Вона володіє тайною магією й б'ється Вогняними Кулями.",al={"клас брейлін","чи брейлін чорнокнижниця","закляття брейлін файргенд"}}},fp="16,300,17.463.0,26.500.1,16.390.1,24.205.0,42.269.0,43.208.0,40.208.0,51.168.2,31.53.2"}
P.entries["npc:braenna-flintcrag"] = {n="Бренна Флінткреґ",s="Бренна Флінткреґ — дворфійська наставниця жерців у Залі Таїнств, у Кварталі містиків Айронфорджа. Вона навчає побожних послідовників Святого Світла й допомагає дворфійським послушникам розвивати духовну дисципліну та мистецтво зцілення. А ще вона підтримує мандрівних жерців, що повертаються до гірського міста після служби в різних куточках Азероту.",h="Бренна Флінткреґ — дворфійська наставниця жерців у Залі Таїнств, у Кварталі містиків Айронфорджа.",kw={"бренна флінткреґ","наставниця жерців","зала таїнств","айронфордж","святе світло","дворфи"},ang={["class:Priest"]="Для жерців-дворфів і всіх жерців Альянсу Бренна — надійна наставниця в Айронфорджі: до неї ви можете прийти по нові закляття, вдосконалитися у Світлі й відзвітувати після далеких мандрів.",["race:Dwarf"]="Бренна втілює глибоку духовну відданість дворфів Айронфорджа, що поєднують бойову витримку з побожним служінням Святому Світлу."},sec={{t="Провідниця в Залі Таїнств",b="У тихих нішах Зали Таїнств, у Кварталі містиків Айронфорджа, Бренна Флінткреґ служить Альянсу як віддана наставниця жерців. Айронфордж славиться ревучими горнилами й войовничими бійцями, але побожні дворфи на кшталт Бренни дбають про духовний добробут Каз Модану. Вона опікується новачками, що відгукнулися на поклик Святого Світла, і навчає їх двох мистецтв — цілющого відновлення й захисних оберегів, без яких не вижити у світі, що стає дедалі небезпечнішим."}},faq={{q="Хто така Бренна Флінткреґ?",a="Бренна Флінткреґ — дворфійка, наставниця жерців у Залі Таїнств у Кварталі містиків Айронфорджа. Вона навчає жерців нових святих молитов, заклять і духовних практик.",al={"бренна флінткреґ","хто така бренна","вчитель жерців бренна"}},{q="Де знайти Бренну Флінткреґ?",a="Вона перебуває в Залі Таїнств — великому святилищі тайних і божественних мистецтв у Кварталі містиків Айронфорджа.",al={"де бренна","місце бренни флінткреґ","знайти бренну флінткреґ"}},{q="Які послуги вона надає мандрівникам?",a="Вона навчає жерців Альянсу й допомагає їм підвищувати ранги заклять. Також вона — зв'язкова для жерців, яких повертають до Айронфорджа завданнями на кшталт «Повернення додому».",al={"послуги бренни","що робить бренна","чи бренна навчить мене"}},{q="Чи має вона родичів у Каз Модані?",a="Вона має те саме прізвище Флінткреґ, що й Тулман Флінткраґ, тож, схоже, належить до відомого дворфського роду в Каз Модані.",al={"родина флінткреґ","тулман флінткреґ родич","родичі бренни флінткреґ"}}},fp="17,350,32.490.0,25.188.0,35.145.0,44.184.0,44.127.0"}
P.entries["npc:brainwashed-noble"] = {n="Вельможа з Промитими Мізками",s="Вельможа з Промитими Мізками — невловимий полонений аристократ, якого можна зустріти глибоко в підземних печерах біля Мертвих Копалень у Вестфолі. Позбавлений власної волі магічними маніпуляціями, він служить Братству Дефіас поруч із прислужниками-нежиттю, замість того щоб походжати величними залами Стормвінда.",h="Вельможа з Промитими Мізками — невловимий полонений аристократ, якого можна зустріти глибоко в підземних...",kw={"вельможа з промитими мізками","мертві копальні","братство дефіас","дім вельмож","едвін венкліф","вестфол"},ang={["class:Mage"]="Вельможа покладається на магічні палиці й арканні прийоми на кшталт «Перетворення» — схоже, до того як його розум зламали, він здобув у столиці справжню магічну освіту.",["race:Human"]="Бачити, як вельможу королівства перетворено на безвольного вартового глибоко під Вестфолом, — моторошне нагадування про те, якою нутряною ненавистю палає Братство Дефіас до правлячої верхівки Стормвінда."},sec={{t="Пішак Братства",b="Блукаючи каламутними, всіяними кістками проходами, що ведуть до Мертвих Копалень, Вельможа з Промитими Мізками разюче вирізняється серед зневірених розбійників і гнилих трупів довкола. Убраний у рештки шляхетних шат, він майже напевно був членом Дому Вельмож Стормвінда або його нащадком, перш ніж потрапив до рук Едвіна Венкліфа. Замість вимагати за нього викуп, розбійники Дефіасу викривили його розум чарами й перетворили представника правлячого класу на чаклуна-вартового свого таємного сховку. Його трагічна доля красномовно свідчить, як далеко готове зайти Братство, щоб помститися знаті, яка відмовилася йому заплатити."}},faq={{q="Хто такий Вельможа з Промитими Мізками?",a="Це аристократ-людина, імовірно з Дому Вельмож Стормвінда, якого Братство Дефіас схопило й магічно підкорило глибоко в печерах Мертвих Копалень.",al={"хто вельможа з промитими мізками","що це вельможа","вельможа в мертвих копальнях"}},{q="Що вельможа зі Стормвінда робить у печерах Мертвих Копалень?",a="Братство Дефіас плекає запеклу ненависть до знаті Стормвінда через несплачені борги за відбудову міста. Схопити шляхтича, поневолити його й скалічити йому розум — це і корисна магічна праця, і особиста помста.",al={"чому він у мертвих копальнях","чому вельможа в печерах"}},{q="Де знайти Вельможу з Промитими Мізками?",a="Він нечасто трапляється в розлогих печерних тунелях Мунбрука, що ведуть до входу в Мертві Копальні, — зокрема в проходах, де блукає скелетна нежить.",al={"місце вельможі","де він з'являється"}},{q="Як йому промили мізки?",a="Хто саме наклав чари, не сказано, але Дефіас тримає по всьому Вестфолу кількох заклиначів і чарівників-ренегатів, цілком здатних підкорити розум полоненого примусовим чаклунством.",al={"хто промив йому мізки","як ним керують"}}},fp="17,296,25.656.0,29.185.0,52.245.0,41.179.0,23.199.0"}
P.entries["npc:brandur-ironhammer"] = {n="Брандур Айронгаммер",s="Брандур Айронгаммер — дворфійський наставник паладинів, що перебуває в Залі Таїнств в Айронфорджі. Він веде молодих звитяжців Святого Світла крізь перші обряди, випробовує їхню відданість і посилає їх у різні краї Альянсу.",h="Брандур Айронгаммер — дворфійський наставник паладинів, що перебуває в Залі Таїнств в Айронфорджі.",kw={"брандур айронгаммер","паладин","зала таїнств","айронфордж","тіза баттлфордж","фоліант божественності","срібна длань"},ang={["class:Paladin"]="Для паладинів-дворфів і всіх паладинів Альянсу Брандур — ключовий наставник в Айронфорджі: у нього ви отримаєте важливу бойову науку, священні печаті й доручення, що ведуть до вищих святих випробувань.",["race:Dwarf"]="Брандур утілює традицію Каз Модану — дворфійських паладинів, що в самому серці Айронфорджа поєднують бойову сталь із шануванням Святого Світла."},sec={{t="Провідник у Кварталі містиків",b="У тихих нішах Зали Таїнств Брандур Айронгаммер служить Альянсу, навчаючи паладинів-новачків шляхів Святого Світла. Разом зі своєю колегою Тізою Баттлфордж Брандур пильно стежить за молодими дворфійськими звитяжцями й веде їх крізь випробування Фоліанта Божественності. Глибоко відданий своєму святому обов'язку, він, проте, визнав власні вади, прислухавшись до відвертої поради Тізи, і старанно працює над тим, щоб приборкати заздрість і зберегти внутрішню чистоту, якої вимагають від воїна Світла."},{t="Ланка Срібної Длані",b="Брандур — важлива сполучна ланка між Айронфорджем і ширшим братством Альянсу. Коли посвячувані-люди забрідають до дворфійської гори, він скеровує їх назад на південь, до Дуторіана Ралла в Соборі Світла. Коли паладини набираються досвіду в полі, Брандур спрямовує їх на поля битв на кшталт Табору Студеного Вітру в Західних Чумних Землях, а згодом посилає досвідчених хрестоносців до Лорда Ґрейсона Шедовбрейкера — проходити суворі випробування заради бойового скакуна."}},faq={{q="Де перебуває Брандур Айронгаммер?",a="Брандур перебуває в Залі Таїнств у Кварталі містиків на північному боці Айронфорджа.",al={"місце брандура","знайти брандура айронгаммера","де брандур"}},{q="Яку роль Брандур Айронгаммер відіграє для паладинів?",a="Він наставник паладинів: навчає нових заклять і вмінь, веде новачків крізь класові завдання на кшталт Фоліанта Божественності й скеровує досвідчених паладинів на складніші випробування по всьому Альянсу.",al={"вчитель паладинів брандур","що робить брандур","призначення брандура"}},{q="Хто колега Брандура в Залі Таїнств?",a="Брандур працює разом із Тізою Баттлфордж, іншою дворфійкою-наставницею паладинів у Залі Таїнств. Тіза — його відверта наставниця: вона вказала йому, що заздрість — його слабкість, і Брандур поклявся її здолати.",al={"партнер брандура","хто працює з брандуром","зв'язок з тізою баттлфордж"}},{q="Чому Брандур посилає паладинів до Стормвінда?",a="Паладинів-людей, що навчаються в Айронфорджі, Брандур часто скеровує до Дуторіана Ралла чи Лорда Ґрейсона Шедовбрейкера в Соборі Світла в Стормвінді, щоб вони пройшли офіційні обряди, які приписує їхнє власне королівство.",al={"завдання брандура стормвінд","чому до дуторіана ралла","брандур люди паладини"}},{q="Чи пов'язаний Брандур із боротьбою проти Погибелі?",a="Так. Брандур передає нагальні заклики Командира Ашлама Валорфіста й посилає перевірених паладинів, чистих і доблесних, на допомогу хрестовому походу Альянсу до Табору Студеного Вітру на кордоні Західних Чумних Земель.",al={"брандур землі чуми","табір чілвінд брандур","ашлем валорфіст брандур"}}},fp="18,238,26.523.0,26.495.0,36.113.0,52.212.0,47.230.0,49.223.0,63.204.0"}
P.entries["npc:brann-bronzebeard"] = {n="Бранн Бронзбірд",kw={"бранн бронзобород","ліга дослідників","археолог","силітус","стіна скарабея","ґлібб"},ang={["faction:Alliance"]="Експедиції Бранна поповнюють знання й архіви Альянсу, хоча його звичка безслідно зникати часто доводить правителів Айронфорджа до нестями.",["race:Dwarf"]="Наймолодший брат короля Маґні, Бранн уособлює дворфійську пристрасть докопуватися до коренів своєї спадщини титанів."},sec={{t="Королівський мандрівник",b="Поки найстарший брат Маґні правив Айронфорджем з трону, а Мурадін бився на передовій, Бранн подався в дикі краї. Він був ветераном Другої війни: бився під час облоги Айронфорджа й ішов за верховним генералом Андуїном Лотаром і Туральйоном аж до знищення Темного Порталу. Та мирні часи спрямували його неабияку витривалість на пошуки забутого минулого. Очолюючи Лігу Дослідників, Бранн наніс на мапи величезні простори Східних Королівств — від Лісу Елвінн до незайманих джунглів Зул'Ґурубу, — а тоді звернув погляд за Велике Море, до таємниць прадавнього Калімдору."},{t="Лихо в Силітусі",b="Почувши від Кола Кенарія звістки про Древнього Бога К'Туна й дрімотний рій кіражів, Бранн вирушив на південь і разом із побратимами-дослідниками Рутґаром Ґліфшейпером і Франкалом Стоунбриджем заснував Табір Бронзоборода на півдні Силітусу. Та сталося лихо: жриця Наталія Мар'аліт, яку довели до божевілля шепітливі жахіття мінливих пісків, напала на їхній табір. Наталія підстерегла Бранна й оглушила його, але ручна мавпа Ґлібб у шаленому пориві кинулася боронити господаря, і нападниця з вереском утекла до Вулик'Реґала."},{t="За Стіною Скарабея",b="Замість того щоб відступити після жахливого нападу, безстрашний археолог загорівся думкою проникнути в запечатане царство за Стіною Скарабея. Бранн знайшов прихований підземний тунель, що оминав прадавню перепону, і пішов туди сам. Ґлібба він лишив на піклування експедиції з суворими письмовими вказівками: давати мавпі вдосталь їжі, води й ніжних обіймів. Його супутники досі чекають на півдні Силітусу, у відчаї сподіваючись на звістку з глибин вуликів силітидів."}},faq={{q="Хто такий Бранн Бронзбірд?",a="Він наймолодший брат Короля Маґні Бронзбірда з Айронфорджа, один із засновників і рушійна сила дворфської Ліги Дослідників. Замість сидіти в залах ради, Бранн — легендарний археолог і картограф, що мандрує найнебезпечнішими закутками Азероту, розкриваючи артефакти титанів і загублені цивілізації.",al={"хто такий бранн","лор бранна","історія бранна бронзбірда"}},{q="Де зараз Бранн Бронзбірд?",a="His trail leads to Silithus, where Rutgar Glyphshaper and Frankal Stonebridge maintain the Bronzebeard Encampment. They may have information about his latest expedition.",al={"місце бранна","де знайти бранна","де бранн у силітусі"}},{q="Що сталося з його табором у Силітусі?",a="Rutgar Glyphshaper and Frankal Stonebridge have troubling news about the expedition. Speaking with them reveals what happened at the camp.",al={"що сталося з табором бронзбірда","хто напав на табір бранна","напад наталії на бранна"}},{q="Хто такий Ґлібб?",a="Glibb is Brann Bronzebeard's companion ape, staying with the explorers at Bronzebeard Encampment in Silithus.",al={"ґлібб мавпа","мавпа бранна","улюбленець бранна"}},{q="Чи бився Бранн у Другій війні?",a="Так. Бранн бився під час Облоги Айронфорджа, а потім разом із братом Мурадіном під проводом Андуїна Лотара й Туральйона рушив до Гори Блекрок, б'ючись із лісовими тролями й орками аж до Темного Порталу.",al={"бранн друга війна","чи бранн був в армії альянсу","бранн і мурадін війна"}},{q="Чому Бранна цікавить Силітус?",a="До пустелі Бранна привабили чутки від Кола Кенарія про Древнього Бога К'Туна, історію титанів і замкнену імперію кіраджі, тож він шукав спосіб пробратися за запечатану Стіну Скарабея, щоб на власні очі оглянути руїни.",al={"чому бранн в силітусі","мета бранна в силітусі","бранн ктун"}}},fp="17,421,16.635.0,19.524.1,22.520.1,25.329.0,37.169.0,38.138.0,13.109.0,34.209.0,36.225.0"}
P.entries["npc:branstock-khalder"] = {n="Брансток Калдер",s="Брансток Калдер — наставник жерців, що служить в Анвілмарі в Долині Холодного Хребта. Привітний і приземлений, він знайомить дворфійських жерців-новачків зі Святим Світлом, водночас пильнуючи дедалі більшу загрозу трогів надворі.",h="Брансток Калдер — наставник жерців, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"брансток калдер","жрець","наставник","святе світло","анвілмар","максан анвол","долина холодного хребта"},ang={["class:Priest"]="Для дворфійських жерців Брансток Калдер — найперший духовний провідник, якого ви зустрічаєте: він розтлумачує вашу першу священну руну й знайомить вас із захисними й цілющими мистецтвами Святого Світла.",["race:Dwarf"]="Брансток утілює практичну, приземлену побожність, властиву дворфам Айронфорджа, поєднуючи благоговійну віру у Світло зі здоровою стійкістю проти холоду й місцевих набігів трогів."},sec={{t="Провідна рука в Холодному Хребті",b="У людній залі Анвілмара Брансток Калдер терпляче наставляє майбутніх жерців, що вирушають у свою духовну подорож. Лагідний дворф із глибокою відданістю Світлу, він допомагає новим послушникам опанувати перші молитви й священні руни. Хоч головний його обов'язок — духовне навчання, Брансток гостро усвідомлює дедалі більші небезпеки долини, передусім зухвалу навалу трогів, що загрожує місцевим горянам. Щойно новачок достатньо опанує Світло, він скеровує його крізь Перевал Холодного Кряжа по подальші настанови до свого зверхника, Максана Анвола, в Харанос."}},faq={{q="Хто такий Брансток Калдер?",a="Брансток Калдер — дворф, наставник жерців в Анвілмарі, початковій заставі Долини Холодного Хребта. Він навчає жерців-початківців шляхів Святого Світла й дає духовну пораду захисникам, що терплять негаразди долини.",al={"лор бранстока","хто такий брансток","вчитель жерців анвілмара"}},{q="Куди Брансток посилає учнів далі?",a="Коли молоді жерці відточать перші вміння й допоможуть дати раду клопотам Долини Холодного Хребта, Брансток посилає їх через Перевал Холодного Кряжа до Хараноса, до свого старшого, Отця Максана Анвола.",al={"куди йти після бранстока","наступне завдання бранстока","шлях жерця з анвілмара"}},{q="Що непокоїть Бранстока в Долині Холодного Хребта?",a="Окрім духовних обов'язків, Бранстока глибоко тривожить недавнє вторгнення трогів, що розповзаються Долиною Холодного Хребта: він розуміє, що сила Світла нагально потрібна, щоб гоїти рани й зміцнювати оборону долини.",al={"проблеми анвілмара","тривоги бранстока","загроза троґів холодний хребет"}},{q="Що він каже тим, хто не є жерцем?",a="Навіть якщо ви йдете іншим шляхом, Брансток дає скромну пораду: ніколи не відвертайтеся від Світла, — і нагадує перехожим, що віра цілком може колись урятувати їм життя.",al={"цитата бранстока","плітки бранстока"}}},fp="17,226,27.620.0,25.239.0,44.212.0,54.225.0,32.197.0"}
P.entries["npc:brave-moonhorn"] = {n="Сміливець Мунгорн",s="Сміливець Мунгорн — розвідник-таурен, що стоїть на варті нагорі Великого Підйомника на південному кордоні Пусток. З цієї кручі він пильнує вхід до Тисячі Голок і попереджає мандрівників про небезпеки, що чекають попереду.",h="Сміливець Мунгорн — розвідник-таурен, що стоїть на варті нагорі Великого Підйомника на південному кордоні...",kw={"сміливець мунгорн","великий підйомник","тисяча голок","ґрімтотем","кентаври","вартовий"},ang={["faction:Horde"]="Мунгорн — передовий вартовий Орди: він спрямовує новоприбулих у каньйон до безпеки, на укріплені висоти Застави Вільного Вітру.",["race:Tauren"]="Глибока недовіра Мунгорна до Ґрімтотемів відбиває тліючі тертя й підозри між традиційними племенами, вірними Кайрнові Бладгуфу, і потайним кланом Ґрімтотем."},sec={{t="Вартовий Підйомника",b="Сміливець Мунгорн стоїть над прямовисними урвищами Тисячі Голок, там, де північні рівнини сходяться з краєм каньйонів. Його головне завдання — пильно стежити за загрозами, що рухаються дном каньйону внизу, передусім за ворожими кланами кентаврів. Кожен, хто збирається спуститися поміж скельні голки, зазвичай спершу зустрічає його й отримує важливі застереження, перш ніж ступити на величезні платформи Великого Підйомника."},{t="Тривожні тіні",b="Окрім постійної загрози від кочових кентаврів, Мунгорна глибоко непокоять його одноплемінники-таурени з племені Ґрімтотем. Він радить мандрівним союзникам з Орди триматися від них подалі, адже ті поводяться довкола Тисячі Голок дедалі дивніше й підозріліше. Щоб забезпечити оборону краю, він відсилає гінців на Заставу Вільного Вітру з попередженнями для Скельного Вартового Лонггорна."}},faq={{q="Хто такий Сміливець Мунгорн?",a="Сміливець Мунгорн — таурен-воїн і розвідник, що пильнує підходи до Великого Підйомника, який сполучає Пустки з Тисячею Голок. Він стежить за діями ворогів і попереджає мандрівників про небезпеки поблизу.",al={"роль мунгорна","хто такий мунгорн","таурен-вартовий підйомника"}},{q="Чому Мунгорн застерігає щодо Ґрімтотемів?",a="Мунгорн помітив, що клан Ґрімтотем у довколишньому каньйоні поводиться дивно й непередбачувано. Хоч вони й належать до тауренської громади, їхня агресивна відособленість робить їх ненадійними для вартових, що пильнують лад на стежці.",al={"чому застерігати про ґрімтотемів","уникати ґрімтотемів","мунгорн ґрімтотем"}},{q="Яке послання він хоче доставити на Заставу Вільного Вітру?",a="Він має термінові попередження про дедалі частіші набіги кентаврів у Тисячі Голок і просить надійних гінців Орди передати ці відомості Скельному Вартовому Лонггорну на Заставі Вільного Вітру.",al={"послання на заставу вільного вітру","яке послання мунгорна","лор послання застави"}},{q="Де перебуває Сміливець Мунгорн?",a="Він стоїть біля краю плато на вершині Великого Підйомника, просто на межі між Пустками й Тисячею Голок.",al={"де мунгорн","місце сміливця мунгорна","вартовий великого підйомника"}}},fp="14,230,20.436.0,14.403.0,22.214.0,45.239.0,53.188.0,32.139.0"}
P.entries["npc:brewmaster-drohn"] = {n="Майстер Броварства Дрон",s="Майстер Броварства Дрон — орк-бровар, що живе на пагорбі над гамірним портом Раджет. Мистецтва екзотичного бродіння він навчився завдяки зв'язкам із легендарним мандрівним пандареном Ченем Бурештофом і тепер варить міцні напої на посушливому прикордонні Пусток. Шукачі пригод, що натрапляють на покинуті барильця по всьому Калімдору, часто опиняються саме на його ґанку.",h="Майстер Броварства Дрон — орк-бровар, що живе на пагорбі над гамірним портом Раджет.",kw={"майстер броварства дрон","броварство","раджет","чень бурештоф","трогське пиво","пандарен"},ang={["faction:Alliance"]="Хоч Дрон і орк, він живе в Раджеті під захистом картелю Стімвідл; напад на нього швидко накличе гнів місцевої гоблінської влади.",["profession:Cooking"]="Кулінари оцінять, як точно Дрон поєднує рідкісні рослини й тваринні інгредієнти, щоб посеред пустелі варити напої світового рівня.",["race:Orc"]="На відміну від більшості воїнів, що пішли за Траллом на Калімдор будувати фортеці, Дрон спрямовує новоздобутий мир Дуротара й Пусток у вишукане мистецтво броварства."},sec={{t="Майстер своєї справи в Раджеті",b="Над гоблінськими доками Раджета живе Майстер Броварства Дрон — орк, що присвятив себе не простому бою, а науці броварства. Він тримає Ґуральню Дрона у своєму домі на схилі пагорба й мирно працює в нейтральному прихистку, створеному Ґазлоу та картелем Стімвідл. Більшість орків задовольняється грубим ґроґом чи простою горілкою, а Дрон працює з рідкісними інгредієнтами, тонким балансом смаків і техніками, яких серед його родичів майже ніхто не знає."},{t="Пандаренський слід",b="Ремесло Дрона значною мірою сформував Чень Бурештоф — славетний мандрівник-пандарен, що бився пліч-о-пліч із Рекссаром та Ордою, коли засновувався Дуротар. Наставник Дрона навчався безпосередньо в Ченя, опанувавши таємниці напоїв Бурештофів, а згодом сам Чень навчив Дрона варити Трогське Пиво. Коли мандрівники натрапляють у диких краях на характерні покинуті барильця Ченя, лише Дрон у цих краях може розпізнати інгредієнти й відтворити міцні напої мандрівника."}},faq={{q="Хто такий Майстер Броварства Дрон?",a="Майстер Броварства Дрон — орк-бровар, що живе в Раджеті в Пустках. Він славиться майстерністю в екзотичних елях і прямим зв'язком із броварськими традиціями мандрівного пандарена Ченя Штормстаута.",al={"лор дрона","хто такий дрон","броварник рятчета"}},{q="Звідки Дрон знає Ченя Штормстаута?",a="Наставника Дрона навчив варити «Бурештоф» сам Чень Штормстаут, а той передав це знання Дронові. Згодом Чень особисто навчив Дрона рецепта й прийомів, потрібних, щоб варити Трогське Пиво.",al={"зв'язок з ченом","звідки він знає чена","дрон і чен"}},{q="Що робити, якщо я знайду Порожнє Барильце Ченя?",a="Віднесіть барильце Майстрові Броварства Дрону в Раджет. Він одразу впізнає роботу Ченя й попросить вас роздобути рідкісні місцеві інгредієнти, потрібні, щоб відтворити трунок.",al={"порожнє барильце чена","знайшов порожнє барильце","завдання барильця"}},{q="Чи Майстер Броварства Дрон на боці Орди?",a="Дрон — орк, але живе й торгує в нейтральному гоблінському порту Раджет. Шукач пригод з Альянсу, що нападе на нього, зіпсує собі репутацію в Раджеті й картелі Стімвідл.",al={"чи дрон на боці орди","чи дрон нейтральний","фракція дрона"}},{q="Які напої робить Дрон?",a="У Ґуральні Дрона він варить міцні суміші, зокрема Трогське Пиво й різновиди рецептів Ченя Штормстаута, для яких потрібні місцеві рослини й сутності створінь з усього Калімдору.",al={"рецепти дрона","напої гуральні дрона"}},{q="Де саме знайти Дрона?",a="Він стоїть біля свого дому на пагорбі над портовим містечком Раджет, трохи на північний захід від головних причалів у Пустках.",al={"де дрон","місце дрона","знайти броваря дрона"}}},fp="16,393,32.466.0,23.509.0,24.205.0,36.200.0,44.192.0,43.188.0,36.194.0,31.141.0"}
P.entries["npc:brewmeister-bilger"] = {n="Броварник Білґер",s="Броварник Білґер — вічно напідпитку дворф-пивовар, що живе в погребі шинку в Саутшорі, у Передгір'ї Гілсбреда. Колись статечний, тверезий захисник, відомий як Білґер Статечний, він під тягарем виснажливих років і трагедій Лордерона проміняв колишню дисципліну на дно бочки. Нині він гає час, куштуючи міцні трунки й чекаючи на поставки з далеких країв.",h="Броварник Білґер — вічно напідпитку дворф-пивовар, що живе в погребі шинку в Саутшорі, у Передгір'ї Гілсбреда.",kw={"броварник білґер","саутшор","передгір'я гілсбреда","трунки","самогон","лордерон"},ang={["faction:Alliance"]="Тиха пам'ятка минулого Саутшора, Білґер бачив, як містечко з плацдарму для героїв Альянсу перетворилося на обложений прикордонний прихисток.",["race:Dwarf"]="Білґер показує, що навіть найстійкішого дворфа похмурі жахіття, які спіткали північні королівства, можуть довести до надмірного пияцтва."},sec={{t="Від Світла до бочки",b="Задовго до того, як здобути звання броварника, Білґер був відомий у Саутшорі як Білґер Статечний. У часи розквіту Лицарів Срібної Длані й найславетніші дні Лордерона він тримався із суворою, тверезою дисципліною серед відомих постатей, що збиралися в місцевому шинку. Падіння Лордерона, чума Погибелі й утрата стількох товаришів зламали ту сувору твердість. Тепер Білґер днями тиняється прохолодним погребом під шинком Саутшора, гикає й шукає найміцніших трунків, які лише може запропонувати Азерот."},{t="Смак до міцного привізного",b="Попри вічний хміль, Білґер лишається тонким знавцем трунків. Він не втрачає апетиту до міцних дворфійських самогонів і крутих південних наливок і радо приймає особливі партії, що прибувають уздовж узбережжя з далеких портів, як-от Гавані Менетіл у Багнокраї."}},faq={{q="Де знайти Броварника Білґера?",a="Броварник Білґер перебуває внизу, у льоху корчми в Саутшорі — портовому містечку Альянсу в Передгір'ї Гілсбреда.",al={"місце білґера","де білґер","дворф у погребі саутшору"}},{q="Чому в давніх історіях його звуть Білґером Пуританином?",a="Багато років тому, ще до падіння Лордерону, Білґер був тверезим, суворо дисциплінованим дворфом, що водився з паладинами й захисниками Альянсу в Саутшорі. Трагедії й війни, що десятиліттями прокочувалися краєм, підточили його суворість, і він покинув колишню стриманість заради пиятики.",al={"білґер пуританин","історія білґера","білґер паладин"}},{q="Які завдання пов'язані з Броварником Білґером?",a="Білґер отримує рідкісну випивку з Багнокраю, зокрема міцні трунки на кшталт Самогону МакКрила, які везуть на північ до Саутшору.",al={"завдання білґера","завдання самогону маккрила"}}},fp="18,429,28.543.0,26.279.0,36.127.0,60.309.0,39.147.0"}
P.entries["npc:brine"] = {n="Брайн",s="Брайн — орчиха-шаманка, що живе серед посушливих пагорбів Кряжа Чорного Терну на півдні Пусток. Знавчиня духів води, вона веде учнів-шаманів духовним шляхом до єднання з припливами, щоб ті здобули свій Тотем Води.",h="Брайн — орчиха-шаманка, що живе серед посушливих пагорбів Кряжа Чорного Терну на півдні Пусток.",kw={"брайн","шаманка","кряж чорного терну","тотем води","поклик води","пустки"},ang={["class:Shaman"]="Брайн — незамінна провідниця на вашому шляху: вона випробовує вашу витривалість і дух, перш ніж ви зможете поєднатися з водою й здобути свій Тотем Води.",["faction:Horde"]="Ветеранка воєн у Гілсбреді, Брайн служить Орді не на передовій, а передаючи новим поколінням духовну спадщину стихій."},sec={{t="Відлюдниця з кряжа",b="Брайн живе на продуваному вітрами пагорбі в північній частині Кряжа Чорного Терну, далеко від гамірних торгових застав Пусток. Попри сухі савани довкола, вона присвятила життя пізнанню плинної й мінливої стихії води. Шаманів з усієї Орди посилають по її мудрість, щойно вони опанують землю й вогонь, бо вода вимагає терпіння й широкого погляду, які мало хто розуміє так глибоко, як вона."},{t="Спогади про Східні Королівства",b="Замолоду Брайн разом з іншими орками пройшла Передгір'я Гілсбреда, беручи участь у битвах проти людських поселень. Під час того виснажливого походу вона опинилася в Таррен Міллі, де натрапила на скромний колодязь із чистою свіжою джерельною водою. Цей колодязь назавжди лишився в її пам'яті символом життя, що триває серед руїн, і закріпив урок, якого її навчили ще в дитинстві: навіть у найтемніші часи скорботи можна знайти крихту надії."},{t="Поклик Води",b="Брайн випробовує шаманів-початківців, посилаючи їх у паломництва по краплі чистоти з різних джерел, і вчить, що вода може бути лагідною, але незламною. Її обряди завершуються єднанням із духами стихій, і шамани прив'язують цілющу суть води до свого тотема."}},faq={{q="Хто така Брайн?",a="Брайн — досвідчена оркиня-шаманка, що живе відлюдницею на вершині пагорба в північній частині Кряжа Чорного Терну на півдні Пусток. Вона наставляє новачків, що прагнуть єднання з духами води.",al={"лор брайн","хто така брайн","орк на чорнотернистому хребті"}},{q="Чому шаманка води живе в пустелі?",a="Хоч Пустки й сухі, справжня цінність і духовна чистота води найкраще видно саме там, де життя спрагле. Самотність дає їй змогу глибоко спілкуватися зі стихіями, подалі від гамору поселень.",al={"чому в пустищі","чому брайн живе в пустелі"}},{q="Що пов'язує Брайн із Таррен Міллом?",a="Багато років тому Брайн билася разом із воїнами Орди в Передгір'ї Гілсбреда й увійшла до Таррен Мілла. Там вона знайшла маленьку криницю з чистою джерельною водою, що стала для неї незгасним символом життя й надії серед руїн війни.",al={"колодязь таррен мілла","брайн гілсбред","історія брайн"}},{q="Яку роль Брайн відіграє в навчанні шаманів?",a="Брайн наглядає за кількома етапами випробувань «Поклик Води». Вона посилає новачків збирати незаймані зразки води по всьому світу, навчаючи їх смирення й стійкості, перш ніж дарувати прозріння, потрібне для Тотема Води.",al={"завдання шамана брайн","як отримати тотем води","поклик води брайн"}},{q="Де саме перебуває Брайн?",a="Вона сидить на високій скелі на півночі Кряжа Чорного Терну, у південній половині Пусток, трохи на північ від Рейзорфен Краулу.",al={"місце брайн","де брайн","знайти брайн пустище"}},{q="Яка філософія лежить в основі її вчення?",a="Брайн вірить, що навіть у часи страшного болю й скорботи можна знайти крихти надії та чистого оновлення. Вона вчить, що вода уособлює життя й стійкість перед суворими випробуваннями.",al={"філософія брайн","уроки води"}}},fp="5,239,19.431.0,32.489.0,17.313.1,13.211.0,41.204.0,42.221.0,45.229.0,31.147.0,37.178.0"}
P.entries["npc:brock-stoneseeker"] = {n="Брок Стоунсікер",s="Брок Стоунсікер — дворфійський наставник гірничої справи з поселення Телсамар у Лох Модані. Як власник Школи гірництва й розвідки надр Брока, він навчає новачків-рудокопів добувати із землі цінні руди й мінерали.",h="Брок Стоунсікер — дворфійський наставник гірничої справи з поселення Телсамар у Лох Модані.",kw={"брок стоунсікер","телсамар","гірнича справа","наставник","лох модан","руда"},ang={["profession:Mining"]="Рудокопи, що мандрують Лох Моданом, шукають Брока Стоунсікера в Телсамарі, щоб почати чи продовжити навчання видобутку й виплавки місцевих руд.",["race:Dwarf"]="Для дворфів Каз Модану камінь і метал — основа всього, тож наставники на кшталт Брока — важлива ланка, що підтримує глибоко вкорінені ремісничі традиції Айронфорджа."},sec={{t="Майстер гірництва й розвідки надр",b="У Телсамарі Брок Стоунсікер очолює Школу гірництва й розвідки надр Брока. На багатих мінералами пагорбах Лох Модану без досвідченої руки з кайлом і ока, що бачить рудні жили, не обійтися. Брок навчає початківців основ: як розпізнати рудне родовище, як добути сирий метал і як правильно розвідати підземні поклади, — щоб ремісники Альянсу могли живити легендарні кузні Айронфорджа."}},faq={{q="Хто такий Брок Стоунсікер?",a="Брок Стоунсікер — дворф, наставник гірничої справи в Телсамарі в Лох Модані. Він тримає Школу гірництва й розвідки Брока, де навчає ремісників добувати руду й розвідувати поклади мінералів.",al={"брок стоунсікер","хто такий брок","брок телсамар"}},{q="Де знайти Брока Стоунсікера?",a="Брок живе в Телсамарі, головному дворфському містечку Лох Модану, і тримає свою гірничу школу поряд із місцевими ремісниками.",al={"де брок","місце брока стоунсікера","брок на мапі"}},{q="Якого ремесла навчає Брок?",a="Він наставник гірничої справи: навчає мандрівників основ видобутку грубого каменю, міді та інших руд, що трапляються по всьому Каз Модану.",al={"чого навчає брок","тип вчителя брока","вчитель гірництва телсамар"}},{q="Що таке Школа гірництва й розвідки Брока?",a="Це навчальний заклад Брока в Телсамарі, де майбутніх рудошукачів навчають безпечно добувати мінерали й читати підземні жили в горах.",al={"школа брока","школа гірництва телсамар"}}},fp="17,263,30.449.0,25.205.0,37.125.0,33.159.0,47.180.0"}
P.entries["npc:bromos-grummner"] = {n="Бромос Ґруммнер",s="Бромос Ґруммнер — дворфійський наставник паладинів, що служить в Анвілмарі в Долині Холодного Хребта. Він наставляє дворфійських святих воїнів-початківців, проповідуючи непохитну віру у Святе Світло та життєво важливий зв'язок між дворфами й людьми в Лицарях Срібної Длані.",h="Бромос Ґруммнер — дворфійський наставник паладинів, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"бромос ґруммнер","паладин","наставник","срібна длань","святе світло","анвілмар","долина холодного хребта"},ang={["class:Paladin"]="Для дворфійських паладинів Бромос — найперший духовний наставник, який знайомить їх зі священними обов'язками Срібної Длані.",["race:Dwarf"]="Бромос утілює тривалу традицію дворфійських служителів Світла, які б'ються пліч-о-пліч зі своїми союзниками-людьми."},sec={{t="Маяк у Холодному Хребті",b="У міцній кам'яній залі Анвілмара Бромос Ґруммнер вітає дворфійських новачків, яких тягне до дисципліни Святого Світла. Упевнений і рішучий, він навчає молодих паладинів бойових обрядів і священних закликів. Окрім основ бою, Бромос наголошує на єдності, нагадуючи учням, що орден Лицарів Срібної Длані поєднує Айронфордж і людські королівства Альянсу в праведній меті."}},faq={{q="Хто такий Бромос Ґруммнер?",a="Бромос Ґруммнер — наставник паладинів в Анвілмарі, у Долині Холодного Хребта в Дун Мороґу. Він дає новим дворфським паладинам перший вишкіл, закляття й духовні настанови.",al={"хто такий бромос","лор бромоса ґруммнера","вчитель паладинів анвілмара"}},{q="Який орден представляє Бромос?",a="Бромос представляє Лицарів Срібної Длані. Він завжди наголошує на важливості союзу людей і дворфів, викуваного під стягом святого ордену.",al={"бромос срібна рука","чи бромос срібна рука"}},{q="Чого він навчає новобранців?",a="Він навчає новачків основ бойового мистецтва й божественних заклять паладина, дає їм перші випробування, щоб вони довели відданість Світлу й готовність захищати Дун Мороґ.",al={"завдання бромоса","що робить бромос ґруммнер"}}},fp="15,260,21.450.0,23.198.0,33.169.0,32.194.0"}
P.entries["npc:brother-joshua"] = {n="Брат Джошуа",s="Брат Джошуа — жрець-людина з Церкви Святого Світла, що служить у величному Соборі Світла в Стормвінді. Відданий справі напучування вірян, він навчає жерців-новачків спрямовувати Святе Світло, щоб загоювати рани й зміцнювати союзників. Його тиха служба — опора щоденного духовного навчання в самому серці королівства.",h="Брат Джошуа — жрець-людина з Церкви Святого Світла, що служить у величному Соборі Світла в Стормвінді.",kw={"брат джошуа","наставник жерців","собор світла","стормвінд","церква святого світла","жрець"},ang={["class:Priest"]="Брат Джошуа — один із ваших головних наставників у Стормвінді: він спрямовує ваше вивчення Святого Світла й допомагає опановувати нові молитви та вміння, коли ви зростаєте в силі.",["faction:Alliance"]="Джошуа, що служить у Соборі Світла, втілює незламну духовну силу Церкви Святого Світла в самому серці Альянсу."},sec={{t="Наставник у Соборі",b="У спокійних залах Собору Світла Брат Джошуа стоїть біля головного вівтаря, готовий навчати новопокликаних служителів віри. Як наставник жерців Церкви Святого Світла, Джошуа навчає основ зцілення, захисних оберегів і духовного зосередження, без якого не досягти єднання зі Світлом. Для молодих жерців-людей, що починають служити Альянсу, він — один із перших провідників до глибшого єднання з божественним."}},faq={{q="Хто такий Брат Джошуа?",a="Брат Джошуа — жрець-людина й наставник Церкви Святого Світла. Він служить у Соборі Світла в Стормвінді, де навчає майбутніх жерців заклять, обрядів і священних обов'язків.",al={"хто брат джошуа","роль брата джошуа","жрець джошуа"}},{q="Де знайти Брата Джошуа?",a="Він стоїть у глибині Собору Світла на Соборній Площі Стормвінда, біля головного вівтаря.",al={"місце брата джошуа","де брат джошуа","де джошуа"}},{q="Які послуги він надає?",a="Брат Джошуа навчає жерців: допомагає опановувати нові ранги божественних і цілющих заклять, а також дає змогу скинути духовні таланти.",al={"що робить джошуа","навчання брата джошуа","чи джошуа навчить мене"}}},fp="14,358,25.494.0,22.217.0,32.130.0,28.168.0"}
P.entries["npc:brother-kristoff"] = {n="Брат Крістофф",s="Брат Крістофф — служитель Церкви Святого Світла з людей, що несе службу на Соборній Площі Стормвінда. Його можна знайти просто неба біля величної статуї Утера Світлоносця. Заглиблений у богослов'я, він часто шукає практичні книжки, щоб вплітати їх у проповіді про силу духу.",h="Брат Крістофф — служитель Церкви Святого Світла з людей, що несе службу на Соборній Площі Стормвінда.",kw={"брат крістофф","соборна площа","церква святого світла","утер світлоносний","напруги заліза","проповідь"},ang={["class:Priest"]="Жерці, що навчаються на Соборній Площі, оцінять приземлений підхід Крістоффа до літургії: він спирається на відчутні, земні ремесла, щоб навчати глибших таємниць внутрішньої стійкості.",["profession:Blacksmithing"]="Ковалів, мабуть, потішить, що служитель Світла звертається до праць про напругу заліза й металургію, щоб навчати духовенство стійкості."},sec={{t="Проповідник біля статуї",b="Брат Крістофф служить Церкві Святого Світла на відкритому дворі Соборної Площі, затримуючись у тіні величного пам'ятника Утерові Світлоносцеві. На відміну від деяких священиків, що усамітнюються в мармурових галереях Собору Світла, Крістофф працює серед містян і прочан, що проходять площею. Готуючи свої промови — як-от проповіді про Стійкість Духу, — він спирається на приземлені, життєві порівняння. Він славиться тим, що звертається до технічних трактатів на кшталт «Напруг Заліза», щоб пояснити, як смертна душа витримує тиск, порівнюючи внутрішню силу, яку дарує Святе Світло, із загартованою міцністю обробленого металу."}},faq={{q="Хто такий Брат Крістофф?",a="Брат Крістофф — жрець-людина й учений Церкви Святого Світла. Він стоїть біля Собору Світла на Соборній Площі Стормвінда, поряд із величною статуєю Утера Світлоносця.",al={"лор брата крістоффа","хто такий крістофф","крістофф стормвінд"}},{q="Що Брат Крістофф робить на Соборній Площі?",a="Крістофф готує проповіді й промови про Світло й віру. Зокрема, він працює над лекцією про Стійкість Духу й шукає в працях із металургії приклади, щоб унаочнити духовну стійкість.",al={"призначення крістоффа","роль крістоффа","чому брат крістофф стоїть надворі"}},{q="Навіщо Братові Крістоффу книжка про залізо?",a="Крістофф шукає трактат «Напруження заліза», щоб збагатити проповідь про стійкість. Властивості заліза під навантаженням він використовує як земну метафору, щоб пояснити, як відданість Святому Світлу загартовує смертний дух перед лихом.",al={"напруги заліза","книга про стійкість","чому крістоффу металургія"}}},fp="16,318,24.675.0,24.219.0,50.226.0,49.250.0"}
P.entries["npc:brother-neals"] = {n="Брат Нілз",s="Брат Нілз — чернець, що живе в Абатстві Нортшира в Лісі Елвінн. Відповідальний за запаси харчів і напоїв абатства, він проводить більшість часу, наглядаючи за поставками й куштуючи вино з тутешнього виноградника.",h="Брат Нілз — чернець, що живе в Абатстві Нортшира в Лісі Елвінн.",kw={"брат нілз","чернець","абатство нортшира","вино","льох","припаси"},ang={["profession:Cooking"]="Брат Нілз порядкує припасами й трунками монастиря, тож він — споріднена душа для кожного, кого цікавлять кулінарне мистецтво й броварські традиції королівства."},sec={{t="Хранитель льоху",b="Усамітнившись у верхніх покоях дзвіниці Абатства Нортшира, Брат Нілз дбає про харчові припаси й запаси напоїв монастиря. Він виявляє особливий, щирий інтерес до нортширських виноградників: ретельно стежить за описами винограду й пильнує якість уславленого абатського вина, куштуючи його з відданою регулярністю. Попри мирні обов'язки обліку й догляду за льохом, він уважно стежить за поставками, що надходять з довколишніх полів долини."}},faq={{q="Хто такий Брат Нілз?",a="Брат Нілз — член братства Абатства Нортшира, що веде облік їжі, напоїв і вина для духовенства й новобранців у долині.",al={"брат нілз","нілз","хто такий нілз"}},{q="Де знайти Брата Нілза?",a="Він сидить у найвищій кімнаті Абатства Нортшира. Щоб дістатися до нього, піднімайтеся кам'яними сходами всередині головної зали, доки не дійдете до тихої кімнати біля верхівки вежі.",al={"де брат нілз","місце брата нілза","знайти нілза"}},{q="Яка його роль щодо виноградника?",a="Він стежить за збором винограду й постачанням вина з сусідніх Виноградників Нортшира, хоча, кажуть, на дегустацію врожаю витрачає не менше часу, ніж на зведення рахунків.",al={"завдання опису винограду","вино нілза","що робить нілз"}}},fp="13,242,20.492.0,21.163.0,33.176.0,40.195.0"}
P.entries["npc:brother-sarno"] = {n="Брат Сарно",s="Брат Сарно — привітний людський клірик, що стоїть при вході до Собору Світла в Стормвінді. Він першим вітає вірян і відвідувачів, а ще допомагає скерувати відважних мандрівників Альянсу до інженерів в Айронфорджі, яким потрібна допомога, щоб відвоювати Гномреґан.",h="Брат Сарно — привітний людський клірик, що стоїть при вході до Собору Світла в Стормвінді.",kw={"брат сарно","собор світла","стормвінд","клірик","техбот","тінкмайстер оверспарк"},ang={["class:Priest"]="Брат Сарно — привітна рука вашого ордену в Стормвінді, взірець гостинності й лагідної благодаті, що лежать в основі чеснот Святого Світла.",["race:Gnome"]="Хоча Брат Сарно служить у людському храмі, він охоче скеровує небайдужих до Айронфорджа, щоб допомогти відродженню Гномреґана."},sec={{t="Привітний голос Собору",b="Брат Сарно стоїть одразу за арками величного Собору Світла в Стормвінді, і часто саме його обличчя першим бачать прочани й мандрівники. Як відданий брат Церкви Святого Світла, він виконує просту, але важливу роль: щиро вітає кожного, хто входить до священної зали в пошуках розради, молитви чи настанови. Його теплота поширюється навіть на найнесподіваніших гостей, і серед метушні церковного життя міста він — заспокійлива присутність."},{t="Зв'язки з Айронфорджем",b="Окрім пастирських привітань, Брат Сарно підтримує зв'язок із союзниками по всьому Альянсу. Коли Тінкмайстрові Оверспарку в Айронфорджі терміново знадобилася допомога з його збунтованим винаходом, Техботом, глибоко в опромінених залах Гномреґана, Сарно взявся скеровувати вправних шукачів пригод до Дун Мороґу. Хоча він лише скромний брат у рясі, він розуміє, що підтримка гномів-вигнанців — вияв справжнього братерства."}},faq={{q="Де знайти Брата Сарно?",a="Брат Сарно перебуває в Соборі Світла на Соборній Площі Стормвінда. Він стоїть одразу ліворуч від головного входу, готовий привітати кожного, хто заходить у двері.",al={"місце сарно","де брат сарно","той що вітає в соборі"}},{q="Що робить Брат Сарно?",a="Сарно зустрічає відвідувачів і вірян Церкви Святого Світла. Ще він посилає шукачів пригод до Тінкмайстра Оверспарка в Айронфордж, щоб допомогти з бідою, що назріває в Гномреґані.",al={"роль брата сарно","що робить сарно"}},{q="Чому жрець зі Стормвінда посилає людей до Гномреґану?",a="Церква Святого Світла сприяє співпраці й взаємодопомозі в усьому Великому Альянсі. Коли до духовенства дійшла звістка, що Тінкмайстрові Оверспарку потрібна допомога, щоб приборкати збожеволілі механізми на кшталт Техбота, Брат Сарно скерував вправних звитяжців до Айронфорджа.",al={"завдання сарно гномереґан","чому сарно цікавить гноми"}},{q="Чи належить він до якогось ордену?",a="Він висвячений член Церкви Святого Світла й служить під проводом настоятелів собору та Архієпископа Бенедиктуса в Стормвінді.",al={"фракція сарно","орден брата сарно"}}},fp="13,286,34.468.0,17.456.0,31.192.0,27.217.0,54.267.0,37.156.0"}
P.entries["npc:brother-wilhelm"] = {n="Брат Вільгельм",s="Брат Вільгельм — наставник паладинів із людей, що служить у Ґолдширі в Лісі Елвінн. Розташувавшись за сільською кузнею, він навчає юних захисників Святого Світла, які роблять перші кроки за межами Абатства Нортшира.",h="Брат Вільгельм — наставник паладинів із людей, що служить у Ґолдширі в Лісі Елвінн.",kw={"брат вільгельм","паладин","ґолдшир","фоліант божественності","абатство нортшира","святе світло"},ang={["class:Paladin"]="Брат Вільгельм — ваш перший наставник після того, як ви покинете Долину Нортширу: він веде вас до зростання й відкриває священний шлях до опанування Фоліанту Божественності.",["race:Human"]="Знайоме обличчя святої традиції королівства, Брат Вільгельм уособлює незламну віру Церкви Святого Світла, що боронить серце Елвінну."},sec={{t="Провідник у Ґолдширі",b="Долина Нортширу дає перший прихисток молодим поборникам Світла, а ті, хто виходить у ширший світ Лісу Елвінн, часто шукають Брата Вільгельма. Розташувавшись одразу за жвавою кузнею Ґолдширу, він навчає новоспечених паладинів їхніх священних обов'язків, дає поради й уроки, поки вони з послушників абатства стають присягнутими захисниками королівства."},{t="Шлях Фоліанту",b="Вільгельм відіграє важливу роль, спрямовуючи майбутніх паладинів на їхньому святому шляху й допомагаючи їм шукати Фоліант Божественності. Через цей важливий обряд посвячені пізнають вагу жертви й силу божественного спокутування, випробовуючи свою відданість, щоб мати змогу Світлом повертати до життя полеглих товаришів і утверджувати справедливість по всьому королівству Стормвінд."}},faq={{q="Де знайти Брата Вільгельма?",a="Брат Вільгельм перебуває в Ґолдширі в Лісі Елвінн. Він стоїть одразу за сільською кузнею, готовий навчати й наставляти майбутніх паладинів.",al={"місце вільгельма","де брат вільгельм","знайти брата вільгельма"}},{q="Які послуги надає Брат Вільгельм?",a="Він наставник паладинів: навчає нових заклять, бойових благословень і святих прийомів молодих паладинів, що мандрують Лісом Елвінн.",al={"що робить вільгельм","вчитель паладинів ґолдшир","вчитель брат вільгельм"}},{q="Чи належить Брат Вільгельм до Братства Нортшира?",a="Його звання й близькість до Абатства Нортшира натякають на тісні зв'язки зі святими орденами Братства Нортшира, хоча служить він передусім Церкві Святого Світла й Королівству Стормвінд.",al={"чи вільгельм братство нортшира","фракція вільгельма","кому служить брат вільгельм"}},{q="Яка його роль у завданні «Фоліант Божественності»?",a="Вільгельм скеровує паладинів-людей, які набралися сили, на священний пошук Фоліанта Божественності й веде їх крізь випробування, потрібні, щоб заслужити священне благословення воскресіння.",al={"фоліант божественності вільгельм","завдання воскресіння вільгельм","завдання паладинів ґолдшира"}}},fp="15,228,20.384.0,20.362.0,33.156.0,43.150.0,57.217.0,47.193.0"}
P.entries["npc:bruegal-ironknuckle"] = {n="Бруеґал Айроннакл",s="Бруеґал Айроннакл — сумнозвісний дворф-в'язень у В'язниці Стормвінда. На відміну від дрібних злочинців і бунтівного наброду, що заповнюють камери, він — грізний кулачний боєць, і його присутність у глибині коридорів означає безпосередню небезпеку для кожного, хто намагається навести лад.",h="Бруеґал Айроннакл — сумнозвісний дворф-в'язень у В'язниці Стормвінда.",kw={"бруеґал айроннакл","дворф","в'язень","в'язниця стормвінда","бунт"},ang={["class:Warrior"]="Айроннакл б'ється з неприкритою затятістю й важкими кулаками, показуючи бійцям, якою буває нестримна груба сила, позбавлена дисципліни й честі.",["faction:Alliance"]="Міська варта Стормвінда покладається на відважних поборників Альянсу, щоб приборкати таких злочинців, як Айроннакл, — інакше серце столиці назавжди стане фортецею анархії.",["race:Dwarf"]="Дворфам гірко бачити кремезного родича серед кишенькових злодіїв і пройдисвітів Стормвінда — вигнання й беззаконня наздоганяють навіть синів Айронфорджа."},sec={{t="Небезпечний каторжник",b="Коли у В'язниці Стормвінда спалахнув відкритий бунт, чимало найнебезпечніших головорізів міста захопили підземні блоки камер. Серед них — Бруеґал Айроннакл, особливо небезпечний в'язень-дворф, відомий своєю жорстокою силою в бійці. Замість сидіти в одній камері, він никає розтрощеними бунтом коридорами, готовий розквасити пику кожному, хто спробує придушити заколот."},{t="Непокірний злочинець",b="Хоча здебільшого бунт у в'язниці організували Братство Дефіас і його ватажки, такі в'язні, як Бруеґал, показують, що тут сидять найрізноманітніші пройдисвіти й злочинці з усіх східних королівств. Хай би за які злочини його кинули в підземелля під Стормвіндом, люта витривалість робить його невловимою мішенню й одним із найнебезпечніших в'язнів-одинаків, що блукають тюремними коридорами."}},faq={{q="Хто такий Бруеґал Айроннакл?",a="Бруеґал Айроннакл — елітний дворф-каторжник, ув'язнений у В'язниці Стормвінда. Він відомий як невловимий, міцний в'язень, що блукає коридорами під час бунту.",al={"хто такий бруеґал","лор айроннакла","в'язень-дворф у в'язниці"}},{q="Чи належить Бруеґал Айроннакл до Братства Дефіас?",a="Бруеґал — дворф-в'язень у В'язниці. До кого саме він належить, у доступному джерелі не зазначено.",al={"чи бруеґал дефіас","дворф дефіас у в'язниці"}},{q="За що його кинули до В'язниці?",a="Точні звинувачення, через які він опинився у В'язниці, в офіційних наказах не записано, але його жорстока вдача й слава забіяки свідчать про серйозні злочини проти законів Стормвінда.",al={"чому бруеґал ув'язнений","злочин бруеґала"}},{q="Де у В'язниці його знайти?",a="Бруеґал не сидить у певній камері. Він невловимий в'язень, що зрідка блукає внутрішніми проходами й перехрестями в'язниці, заскочуючи тих, хто розправляється з бунтівниками.",al={"поява бруеґала","де бруеґал","рідкісна поява у в'язниці"}},{q="Чи він завжди є у в'язниці?",a="Ні. Бруеґал — рідкісний гість серед бунтівників. Його часто тримають під замком або він ховається, з'являючись лише час від часу під час заворушень.",al={"чи бруеґал може не з'явитися","чому не знайти бруеґала"}},{q="Чим він вирізняється серед в'язнів?",a="Окрім грізної бойової вправності, Бруеґал, кажуть, має при собі цінну контрабанду й спорядження, сховані від вартових, тож він — бажана здобич для шукачів пригод, що наважаться з ним зійтися.",al={"чому шукають бруеґала","значення бруеґала"}}},fp="19,289,19.387.0,13.405.0,27.179.0,54.111.0,37.198.0,42.186.0,35.167.0,43.210.0"}
P.entries["npc:cain-firesong"] = {n="Кейн Файрсонг",kw={"кейн файрсонг","наставник магів","брілл","похоронний подзвін","анастасія гартвелл","галявини тірісфалю","маг"},ang={["class:Mage"]="Для молодих магів-Відступників, що виходять із Похоронного Подзвону, Кейн Файрсонг — ваш головний наставник на Галявинах Тірісфалю, доки вас не покличуть до Андерсіті.",["race:Undead"]="Кейн доводить, що навіть у нежитті магічні традиції колишніх людських магів лишаються потужною зброєю Відступників."},sec={{t="Чарівник у Бріллі",b="While many Forsaken spellcasters delve into shadow or necromancy, Cain Firesong maintains mastery over traditional arcane disciplines. Stationed in Brill, he serves as an early mentor to Forsaken mages venturing forth from Deathknell. The local Deathguards direct visitors to the upstairs landing of the Gallows' End Tavern, joking that he arrived too late to get a room."},{t="Шлях для нових талантів",b="As novice mages under his tutelage advance beyond their preliminary studies in Tirisfal Glades, Cain ensures they do not stagnate. He directs his most capable students to seek out Anastasia Hartwell, a master sorceress residing in the Magic Quarter of the Undercity."}},faq={{q="Хто такий Кейн Файрсонг?",a="Кейн Файрсонг — наставник магів із Відступників у Бріллі на Галявинах Тірісфалю. Він навчає тайних заклять молодих заклиначів Орди й скеровує досвідченіших учнів до Андерсіті.",al={"хто такий кейн файрсонг","лор кейна файрсонга","кейн файрсонг брилл"}},{q="Де Кейн Файрсонг живе в Бріллі?",a="Cain stands on the upstairs landing of the Gallows' End Tavern in Brill. Local Deathguards joke that he checked in too late to get a room.",al={"де кейн файрсонг","місце кейна файрсонга","кімната кейна в таверні"}},{q="Куди Кейн посилає магів після першого навчання?",a="Коли маг під його проводом досить просунеться, Кейн посилає його вниз, до Магічного Кварталу Андерсіті, щоб продовжити навчання в Анастасії Гартвелл.",al={"завдання кейна","кому кейн посилає магів","поговори з анастасією"}}},fp="13,317,23.371.0,18.266.0,21.188.0,39.138.0,56.181.0"}
P.entries["npc:cairne-bloodhoof"] = {n="Кайрн Бладгуф",s="Кайрн Бладгуф — поважний Верховний Вождь об'єднаних тауренських племен і правитель Тандер Блафу. Величезний воїн неосяжної мудрості, він зв'язав долю тауренів з Ордою Тралла після того, як орки допомогли його народові уникнути винищення від рук кентаврів.",h="Кайрн Бладгуф — поважний Верховний Вождь об'єднаних тауренських племен і правитель Тандер Блафу.",kw={"кайрн бладгуф","верховний вождь","таурени","тандер блаф","малгор","тралл","орда"},ang={["faction:Horde"]="Поруч із Траллом Кайрн — батько-засновник сучасної Орди на Калімдорі, опора честі, мудрості та військової сили.",["race:Tauren"]="Кайрн — рятівник вашого народу: він об'єднав розсіяні племена, відбив кентаврів і очолив будівництво Тандер Блафу."},sec={{t="Держава в Малгорі",b="Поколіннями таурени жили мандрівними кочовиками по Пустках, і дикі кентаври-грабіжники без упину полювали на них, штовхаючи до загибелі. Коли Тралл зі своїми орками прибув на береги Калімдору, Кайрн розгледів у них рідкісну шляхетність. Тралл запропонував військовий захист і провів зневірену валку Кайрна через рівнини до безпечного Малгору в обмін на дорогу до Оракула на Піку Кам'яного Кігтя. Оселившись на високих плато Тандер Блафу, Кайрн нарешті заснував постійний, єдиний дім для всіх тауренських племен."},{t="Присяга Орді",b="У боргу перед Траллом, Кайрн пішов за орками до Піку Кам'яного Кігтя й бився пліч-о-пліч з Ордою та людьми Джайни Праудмур проти Палаючого Легіону під час Третьої війни. Пізніше, коли Адмірал Дейлін Праудмур вторгся в Дуротар, Кайрн знову особисто взявся за прадавній рунний спис і бився поруч із Рекссаром, щойно його полоненого сина Бейна благополучно визволили. Нині Кайрн — один із найшанованіших старійшин Орди й найближчий довірений Тралла, що дає спокійну пораду проти безоглядного розпалювання війни."}},faq={{q="Хто такий Кайрн Бладгуф?",a="Кайрн Бладгуф — Верховний Вождь об'єднаних тауренських племен, вождь племені Бладгуф і правитель Тандер Блафа. Це прадавній воїн, чиє проводирство й сила вивели тауренів із кочового вигнання на безпечну батьківщину.",al={"хто такий кайрн","вожак тауренів","верховний вождь"}},{q="Чому таурени в союзі з орками?",a="Під час Третьої війни племена кентаврів-грабіжників полювали на тауренів, щоб винищити їх до ноги. Тралл і його щойно прибулі орки відбили нападників і провели великий караван Кайрна до Малгору. На знак вдячності Кайрн присягнув Орді Тралла на вірність і силу свого народу.",al={"чому таурени з орками","чому таурени в орді","дружба кайрна й тралла"}},{q="Де живе Кайрн?",a="Він править на вершині Тандер Блафа — столиці, збудованої на високих столових горах Малгору, разом із провідниками різних об'єднаних тауренських племен.",al={"де кайрн","місце кайрна","знайти кайрна бладгуфа"}},{q="Ким Бейн Бладгуф доводиться Кайрнові?",a="Бейн — улюблений син і спадкоємець Кайрна. Коли Бейна викрали кентаври-нападники, Кайрн поринув у глибоке горе й відмовлявся воювати, доки Рекссар і його супутники не вистежили Бейна й цілим не повернули його додому.",al={"син кайрна","чи бейн син кайрна","зв'язок з бейном бладгуфом"}}},fp="16,276,19.555.0,19.525.0,24.249.0,40.274.0,25.152.0,33.211.0"}
P.entries["npc:calor"] = {n="Калор",s="Калор — відданий мешканець Даркшира, що допомагає Нічній Варті та родині Каревінів захищати Сутінколісся. Діючи за вказівками Джонатана Каревіна, він організовує полювання на лютих воргенів, які нишпорять похмурими лісами. Шукачі пригод, що прагнуть відігнати ненажерливих звірів, часто отримують завдання саме від нього.",h="Калор — відданий мешканець Даркшира, що допомагає Нічній Варті та родині Каревінів захищати Сутінколісся.",kw={"калор","воргени","даркшир","сутінколісся","каревін","полювання"},ang={["class:Hunter"]="Мисливці матимуть у Калора постійну роботу: вистежувати й винищувати диких, потойбічних звірів, що порушують природний лад лісу.",["faction:Alliance"]="Калор — важливий зв'язковий для поборників Альянсу, готових кинути виклик похмурому лісу, щоб захистити відрізаних від світу мешканців Даркшира."},sec={{t="Вірний у тінях",b="Калор живе в обложеному Даркширі й тісно співпрацює з Джонатаном Каревіном, одним із чільних захисників міста. Серед нескінченного мороку й повзучих жахів Сутінколісся Калор віддає себе справі родини Каревінів: знищити надприродні жахіття, що підступають до околиць міста, доки ті не вирізали решту мешканців."},{t="Загроза воргенів",b="Головний обов'язок Калора — протистояти здичавілим воргенам, що никають лісами, особливо довкола сплюндрованих місць на кшталт Гнилого Саду. Ці люті вовколюди значно агресивніші й небезпечніші за звичайних звірів: вони однаково вбивають і мандрівників, і патрулі. Калор шукає вправних бійців, щоб прорідити їхні лави й з'ясувати, звідки вони взялися, — він відчайдушно прагне зупинити цю кровожерливу навалу."}},faq={{q="Хто такий Калор?",a="Калор — людина, союзник родини Каревінів із Даркширу. Він допомагає обороняти містечко, посилаючи шукачів пригод полювати на небезпечні загрози Сутінколісся.",al={"калор даркшир","хто такий калор","калор сутінколісся"}},{q="Де знайти Калора?",a="Калор перебуває в Даркширі — головному містечку Альянсу серед темних лісів Сутінколісся.",al={"де калор","місце калора","координати калора"}},{q="Що пов'язує Калора з Джонатаном Каревіном?",a="Калор — вірний прибічник родини Каревінів. Він виконує вказівки Джонатана Каревіна й допомагає йому воювати зі смертоносними чудовиськами, що мучать ліс.",al={"калор і каревін","на кого працює калор","родина каревін калор"}},{q="З якими ворогами Калор посилає вас битися?",a="Калор доручає шукачам пригод полювати на кровожерні зграї воргенів, що заполонили ліси, — зокрема б'є по них біля таких місць, як Гнилий Сад.",al={"завдання калора","чого хоче калор","завдання про воргенів"}},{q="Чому загроза воргенів у Сутінколіссі така нагальна?",a="Воргени — люті, ненажерливі хижаки, що нападають на все живе. Без регулярного винищення, яке організовують Калор і Нічна Варта, звірі швидко прорвали б тонкі оборонні лінії Даркширу.",al={"чому вбивати воргенів в сутінколіссі","загроза воргенів сутінколісся"}},{q="Чи належить Калор до Нічної Варти?",a="Хоча Калор тісно співпрацює з захисниками містечка й підтримує Джонатана Каревіна, він передусім безпосередній агент і прибічник походу родини Каревінів проти воргенів.",al={"калор нічна варта","чи калор у нічній варті"}}},fp="5,371,25.388.0,17.389.0,13.172.0,25.103.0,51.168.0,39.174.0,47.215.0,37.191.0"}
P.entries["npc:calvin-montague"] = {n="Келвін Монтеґ'ю",s="Келвін Монтеґ'ю — спритний розбійник із Відступників, що тиняється біля вихідної брами Похоронного Подзвону на Галявинах Тірісфалю. Полюючи на щойно пробуджених мерців, які виходять із цвинтаря, він намагається обманом змусити перехожих виконувати доручення замість нього.",h="Келвін Монтеґ'ю — спритний розбійник із Відступників, що тиняється біля вихідної брами Похоронного Подзвону...",kw={"келвін монтеґ'ю","розбійник","шахрай","похоронний подзвін","лист","відступники"},ang={["class:Rogue"]="Розбійники Відступників швидко розкусять прозорі спроби Келвіна Монтеґ'ю маніпулювати й упізнають у ньому колегу-злодія, що намагається провернути дешеву оборудку з непосвяченими.",["race:Undead"]="Для щойно піднятих, що покидають Похоронний Подзвін, Келвін — ранній урок того, що не всі піддані Сильвани зацікавлені у взаємній підтримці."},sec={{t="Шахрай біля брами",b="Келвін Монтеґ'ю, що влаштувався одразу за брамою, яка веде з Похоронного Подзвону, утілює безжальний прагматизм, властивий неспокійним мертвим Лордерону. Замість займатися власним листуванням чи платити чесну ціну кур'єрам, він намагається солодкими словами підбити мандрівних шукачів пригод доставляти листи під фальшивим приводом. Поки кілька інших помітних мерців із прізвищем Монтеґ'ю керують банківськими справами в Андерсіті, Келвін обрав куди менш поважне ремесло, віддаючи перевагу дрібним оборудкам і обману."},{t="Задум розбійника",b="Пропозиція Келвіна — віднести від його імені запечатане послання, та ті, хто має гострий розум чи вишкіл злочинного світу, швидко бачать за його словами шахрайство. Навіть серед щойно піднятих, які силкуються знайти мету в похмурих руїнах Тірісфалю, Келвін нагадує новачкам, що на службі в Темної Леді довіра — рідкісний товар."}},faq={{q="Хто такий Келвін Монтеґ'ю?",a="Келвін Монтеґ'ю — розбійник-Відступник, що стоїть біля вихідної брами Похоронного Подзвону на Галявинах Тірісфалю. Він полює на новопіднятих мерців, обдурюючи їх, щоб ті безплатно виконали для нього доручення.",al={"келвін монтеґ'ю","хто такий келвін","келвін смертельний дзвін"}},{q="Що Келвін хоче від шукачів пригод?",a="Келвін намагається вмовити перехожих мандрівників доставити для нього листа під облудними приводами, сподіваючись спритними маніпуляціями дістати безплатного посланця.",al={"завдання келвіна","лист келвіна","чого хоче келвін"}},{q="Чи родич Келвін Монтеґ'ю банкірам з Андерсіті?",a="Він має те саме прізвище, що й кілька відомих банкірів Андерсіті — Офелія, Мортімер, Вільям і Рандольф Монтеґю. Родинного зв'язку не підтверджено.",al={"родина монтеґ'ю","банкіри монтеґ'ю андерсіт","чи келвін родич банкірів"}},{q="Де знайти Келвіна Монтеґ'ю?",a="Він чатує на дорозі одразу за дерев'яною брамою на північному виході з Похоронного Подзвону й перестріває шукачів пригод, що вирушають на широкі Галявини Тірісфалю.",al={"місце келвіна","де келвін монтеґ'ю","знайти келвіна"}}},fp="15,242,21.528.0,16.343.1,23.202.0,40.169.0,52.175.0,35.167.0"}
P.entries["npc:canaga-earthcaller"] = {n="Канаґа Ерткаллер",s="Канаґа Ерткаллер — троль-шаман із племені Темного Списа, що стоїть у випаленій сонцем Долині Випробувань. Він навчає шаманів-новачків Орди спілкуватися з духами землі й здобувати перші стихійні тотеми. Окрім настанов в обрядах, він пильнує за пораненими розвідниками та загрозами, що виникають поблизу Лігва.",h="Канаґа Ерткаллер — троль-шаман із племені Темного Списа, що стоїть у випаленій сонцем Долині Випробувань.",kw={"канаґа ерткаллер","шаман","троль","долина випробувань","тотем землі","сапта","гана'зуа"},ang={["class:Shaman"]="Канаґа — ваш найперший духовний наставник у Дуротарі: він готує Земляну Сапту, щоб ви могли поспілкуватися зі стихіями й здобути свій Тотем Землі.",["race:Orc"]="Канаґа працює пліч-о-пліч з орківськими наставниками в долині, допомагаючи молодим оркам зв'язати свій дух із суворою землею нової батьківщини.",["race:Troll"]="Як одна з помітних постатей Темного Списа в Долині Випробувань, Канаґа дбає, щоб тролі-новобранці не лишалися без догляду — зокрема й послані розвідники на кшталт Гана'зуа."},sec={{t="Голос землі",b="На червоних кручах Долини Випробувань Канаґа Ерткаллер є одним із найперших духовних провідників для тролів Темного Списа та орків, що стають на шлях шамана. Поки багато наставників дбають лише про бойову готовність, Канаґа вчить новачків утихомирити розум і прислухатися до гуркоту самого Калімдору, готуючи земляну сапту, потрібну для спілкування з духами."},{t="Перший тотем",b="Перш ніж шаман-початківець зможе по-справжньому спрямовувати стихійну лють землі, він має довести духам свою повагу й рішучість. Канаґа скеровує посвячуваних зібрати священні реагенти й вирушити до місцевого каменя духів у Дуротарі. Під його проводом новачки п'ють земляну сапту, бачать стихійних духів на власні очі й здобувають свій Тотем Землі."},{t="Клопоти в долині",b="Канаґа не живе самими лише потаємними обрядами — він уважний і до нагальних небезпек долини. Коли його друг Гана'зуа вирушає на північ долини, де полюють скорпіди, і не повертається, Канаґа посилає здібних мандрівників на його пошуки, щоб розвідників племені не кидали гинути в глушині."}},faq={{q="Хто такий Канаґа Ерткаллер?",a="Канаґа Ерткаллер — троль-шаман із Темного Спису, що живе в Долині Випробувань. Він наставляє молодих шаманів, які роблять перші кроки в Орді, і допомагає організувати порятунок розвідників, що потрапили в біду поблизу.",al={"лор канаґи","хто такий канаґа","канаґа нпс"}},{q="Чого Канаґа навчає молодих шаманів?",a="Канаґа веде ланцюжок обрядів «Поклик Землі» для шаманів Орди, що починають шлях у Дуротарі. Він варить Земляну Сапту — містичний трунок, що дає новачкам змогу бачити місцевого духа землі й говорити з ним, щоб здобути свій перший тотем.",al={"завдання шамана дуротар","поклик землі дуротар","завдання канаґи"}},{q="Що таке Земляна Сапта, яку готує Канаґа?",a="Земляна Сапта — особливо зварений духовний трунок із місцевих реагентів. Шамани п'ють його, щоб відкрити свої чуття прихованим духам землі й спілкуватися просто з проявами стихій.",al={"що таке земляна сапта","лор сапти"}},{q="Навіщо Канаґа посилає шукачів пригод шукати Гана'зуа?",a="Гана'зуа, добрий друг Канаґи, пішов долиною на північ, туди, де полюють скорпіди, і не повернувся. Духи кажуть Канаґі, що з його другом лихо, тож він просить шукачів пригод розшукати його й допомогти.",al={"канаґа ґана'зуа","навіщо шукати ґана'зуа"}},{q="Чому троль навчає шаманів на орківському полігоні?",a="Після Третьої війни плем'я Темного Спису тісно злилося з Ордою Тралла й оселилося поряд з орками в Дуротарі. Тепер шамани й воїни-тролі навчаються пліч-о-пліч із молодими орками в Долині Випробувань.",al={"чому троль в долині випробувань","дарспір у долині випробувань"}},{q="Де знайти Канаґу Ерткаллера?",a="Канаґа сидить на скелястих плато над східними стежками Долини Випробувань, трохи на південь від головного навчального табору.",al={"місце канаґи","де канаґа"}}},fp="18,311,17.401.0,15.357.0,21.323.0,26.194.0,37.239.0,40.225.0,50.236.0,60.221.0,38.124.0"}
P.entries["npc:captain-danuvin"] = {n="Капітан Данувін",s="Капітан Данувін — офіцер у Сентінел Гіллі у Вестфолі, один із ватажків, на яких тримається оборона прикордоння. Разом із Народним ополченням він скеровує добровольців і новобранців патрулювати шляхи та відкидати гнолів і розбійників, що підступають дедалі ближче. Його накази життєво важливі, щоб шляхи постачання й ниви не потрапили цілком до ворожих рук.",h="Капітан Данувін — офіцер у Сентінел Гіллі у Вестфолі, один із ватажків, на яких тримається оборона...",kw={"капітан данувін","сентінел гілл","народне ополчення","гноли річколапів","патруль","вестфол"},ang={["class:Warrior"]="Данувін шанує бойову дисципліну й рішучі дії на передовій і цінує воїнів, готових кинутися на зграї гнолів і силою розчистити шлях.",["faction:Alliance"]="Капітан Данувін — один із небагатьох кадрових військових, що силкуються підтримувати лад у Вестфолі попри байдужість корони, і він дає новобранцям Альянсу сталу роботу на захисті королівства.",["race:Human"]="Для людей королівства допомога Данувіну — питання виживання рідної землі: так житниця Стормвінда не дістанеться назавжди грабіжникам і звірам."},sec={{t="Утримати пагорб",b="Із укріпленої вежі Сентінел Гілла Капітан Данувін координує піші патрулі по всьому Вестфолу. Відколи звідси відкликали регулярні гарнізонні війська Стормвінда, край поринув у хаос, а місцева оборона геть знесилена. Данувін значною мірою покладається на мандрівних шукачів пригод, місцевих наймитів і добровольців, щоб підтримувати на трав'янистих рівнинах бодай подобу ладу."},{t="Патрулі на прикордонні",b="Найнагальніша турбота Данувіна — безпека шляхів і відкритих земель довкола Сентінел Гілла. Гноли Річколапів дедалі зухваліші й нападають просто біля головних застав, тож він організовує активні патрулі, щоб прорідити їхні зграї й убезпечити околиці. Його накази не дають мародерам і пройдисвітам Вестфолу цілком оточити табір."}},faq={{q="Де знайти Капітана Данувіна?",a="Капітан Данувін служить у Сентінел Гілл — головній заставі Альянсу в центрі Вестфолу. Зазвичай він стоїть біля укріпленої вежі на пагорбі, звідки видно дорогу.",al={"місце данувіна","де капітан данувін","данувін вестфолл"}},{q="Кого представляє Капітан Данувін?",a="Данувін служить Альянсу й безпосередньо підтримує місцеві сили оборони Вестфолу, тісно співпрацюючи з Ґраяном Стаутмантлом і Народним ополченням.",al={"фракція данувіна","кому служить данувін"}},{q="Які обов'язки він покладає на шукачів пригод?",a="Данувін доручає новобранцям наводити лад у сільській місцевості — передусім патрулювати рівнини й відганяти агресивні зграї гнолів Річколапів, що підбираються до Сентінел Гілл.",al={"завдання данувіна","чого хоче капітан данувін","завдання патрулювання вестфолла"}},{q="Чому Данувін покладається на добровольців, а не на армію Стормвінда?",a="Стормвінд покинув Вестфол і не виділив жодного гарнізону на його захист. Данувін та інші провідники Сентінел Гілл змушені покладатися на найманців і новобранців ополчення.",al={"чому немає армії стормвінда","чому ополчення","гарнізон стормвінда у вестфоллі"}},{q="Чи має Данувін зв'язки поза Вестфолом?",a="Данувін пов'язаний із самим Вестфолом. Це його рідний край, і він поклявся не відвертатися від людей, що вирішили лишитися, тож його обов'язки тримають його на рівнинах і дорогах довкола Сентінел Гілл.",al={"данувін редрідж","зв'язки данувіна"}},{q="Яка його роль порівняно з Ґраяном Стаутмантлом?",a="Ґраян Стаутмантл визначає загальну стратегію оборони й очолює Народне ополчення, а Капітан Данувін — польовий офіцер, що опікується тактичними справами, патрулюванням доріг і безпосередньою загрозою гнолів довкола бази.",al={"данувін проти стаутмантла","чи данувін головний"}}},fp="15,400,16.396.0,23.371.0,33.187.0,44.169.0,42.188.0,67.199.0,50.210.0,47.229.0"}
P.entries["npc:captain-grayson"] = {n="Капітан Ґрейсон",s="Капітан Ґрейсон — неспокійний дух піратського капітана, що чатує біля Маяка Вестфолу. Сам загинувши, коли його корабель розбився об темне узбережжя, він тепер стереже маяк, щоб інших мореплавців не спіткала його доля.",h="Капітан Ґрейсон — неспокійний дух піратського капітана, що чатує біля Маяка Вестфолу.",kw={"капітан ґрейсон","привид","маяк вестфолу","старий мутноокий","мурлоки","вестфол"},ang={["class:Paladin"]="Хоча Ґрейсон — неупокоєний дух, його мета безкорислива й захисна. Допомагаючи йому, ви вшановуєте священний обов'язок захищати беззахисних і відбивати вбивчу навалу мурлоків.",["class:Priest"]="Дух Ґрейсона тримають провина й горе, бо він бачив загибель невинної родини. Допомога йому дарує його неспокійній душі бодай трохи розради.",["faction:Alliance"]="Братство Дефіас душить Вестфол, а Стормвінд занедбав свої кордони, тож саме мандрівникам Альянсу випадає відгукнутися на прохання Ґрейсона й зберегти вогонь маяка."},sec={{t="Життя, обірване скелями",b="За життя Ґрейсон водив корабель небезпечними південними морями Східних Королівств. Його плавання жорстоко обірвалося біля зубчастих мілин Вестфолу тієї ночі, коли вогонь маяка згас. Викинутий на скелі, Ґрейсон загинув разом зі своїм кораблем — і прокинувся привидом, прикутим до узбережжя."},{t="Трагедія біля маяка",b="Після смерті Ґрейсона потягло до Маяка Вестфолу, де він сподівався знайти відповіді про потойбічне життя. Натомість він став свідком справжньої трагедії. Сумнозвісний мурлок на прізвисько Старий Мутноокий прогнав доглядача маяка та його родину. Хоча доглядачі відважно повернулися, щоб знову розпалити вогонь, Старий Мутноокий зібрав довколишніх мурлоків для другої, жорстокої різанини. Ґрейсон міг лише безпорадно дивитися, як родину вирізають."},{t="Примарна варта",b="Доглядачі загинули, Вестфол занепадає без догляду, тож Капітан Ґрейсон узяв урочистий тягар маяка на свої примарні плечі. Він просить перехожих шукачів пригод зібрати паливо для великого вогню й помститися за вирізану родину, вистеживши Старого Мутноокого й відкинувши прибережну навалу мурлоків."}},faq={{q="Хто такий Капітан Ґрейсон?",a="Капітан Ґрейсон — привид пірата-людини, що мешкає біля Маяка Вестфолу. Розбившись біля узбережжя, бо маяк згас, його дух узяв на себе обов'язок підтримувати світло й захищати моряків, що пропливають повз.",al={"хто такий ґрейсон","хто привид-пірат","привид маяка"}},{q="Як загинув Капітан Ґрейсон?",a="Він загинув, коли його піратський корабель викинуло на підступні скелі біля берегів Вестфолу. Тієї ночі маяк не світив, тож ні він, ні його команда не мали жодного попередження, перш ніж корабель розтрощило.",al={"смерть ґрейсона","як ґрейсон став привидом","що вбило капітана ґрейсона"}},{q="Що сталося зі справжнім доглядачем маяка?",a="На доглядача й його родину напали прибережні мурлоки. Вони вціліли після першого нападу й повернулися, щоб знову запалити вогонь, але Старий Мурк-Ай зібрав родичів на другий набіг і перебив їх усіх на очах у Ґрейсона.",al={"де доглядач маяка","що сталося з доглядачами","родина маяка"}},{q="Хто такий Старий Мурк-Ай?",a="Старий Мурк-Ай — хитрий і лютий ватажок мурлоків, що никає узбережжям Вестфолу. Він очолив напад, у якому загинула родина доглядача маяка, і постійно загрожує кожному, хто намагається підтримувати вогонь.",al={"лор мурк-ая","старий мурк-ай","вожак мурлоків вестфолл"}},{q="Чому Ґрейсон хоче, щоб маяк світив?",a="Сам потонувши через те, що узбережжя поринуло в непроглядну темряву, Ґрейсон вважає своїм урочистим обов'язком у потойбіччі дбати, щоб жоден інший моряк не спіткав такої ж долі на мілинах.",al={"мотивація ґрейсона","чому запалити маяк"}},{q="Чи ворожий Капітан Ґрейсон до шукачів пригод?",a="Ні. Хоч за життя він і був піратом, Ґрейсон не тримає зла на живих. Він бачив надто багато різанини й прагне лише спокою та допомоги в догляді за вогнем.",al={"чи ґрейсон дружній","чи ґрейсон ворожий"}}},fp="15,252,29.333.0,21.421.0,15.319.0,23.217.0,28.197.0,44.218.0,20.222.0,46.171.0,42.183.0"}
P.entries["npc:captain-greenskin"] = {n="Капітан Ґрінскін",s="Капітан Ґрінскін — елітний гоблін-пірат, що наглядає за будівництвом і командою величезного броненосця Едвіна Венкліфа. Захований глибоко в підземній бухті Мертвих Копалень, він командує піратами, яких найняло Братство Дефіас. Його мета — підготувати бойовий корабель до походу на Стормвінд.",h="Капітан Ґрінскін — елітний гоблін-пірат, що наглядає за будівництвом і командою величезного броненосця Едвіна...",kw={"ґрінскін","капітан","пірат","гоблін","мертві копальні","броненосець","дефіас"},ang={["class:Rogue"]="Ґрінскін стоїть на самій вершині піратської ватаги Дефіас, і просто на палубі бойового корабля його пильно стережуть корсари й громили.",["faction:Alliance"]="Для сил Альянсу капітан Ґрінскін уособлює морську загрозу заколоту Дефіас: якщо його броненосець прорветься до узбережжя, беззахисні береги Вестфолу й Стормвінда опиняться під прямим ударом."},sec={{t="Господар броненосця",b="Походжаючи головною палубою велетенського броненосця, що його будують у бухті Мертвих Копалень, капітан Ґрінскін уособлює морську силу змови Дефіас. Досвідчений гоблін-мореплавець, який раніше орудував із Буті Бей, Ґрінскін увійшов до найближчого кола Едвіна Венкліфа, щоб перетворити підземну печеру на сухий док для бойового корабля."},{t="Піратська команда",b="Ґрінскін командує не звичайною ватагою каменярів чи розбійників. Під його пильним оком служать бувалі головорізи, серед них — грізний старший помічник, таурен Пан Кара, і корабельний кок-мурлок Печивко. Разом вони тримають трапи й верхню палубу, стоячи між непроханими гостями та особистою каютою Венкліфа на капітанському містку."}},faq={{q="Хто такий Капітан Ґрінскін?",a="Капітан Ґрінскін — гоблін, капітан піратів, якого Едвін Венкліф найняв, щоб наглядати за добудовою й керувати таємним бойовим кораблем Братства Дефіас у Мертвих Копальнях.",al={"лор ґрінскіна","хто такий ґрінскін","капітан ґрінскін"}},{q="Звідки прийшов Ґрінскін, перш ніж приєднатися до Дефіасу?",a="Ґрінскін родом із Буті Бей на півдні Долини Стренглторну, де колись командував цілим флотом піратських суден, перш ніж піти на платню до Венкліфа.",al={"походження ґрінскіна","звідки ґрінскін","ґрінскін буті бей"}},{q="Хто служить під началом Капітана Ґрінскіна?",a="Під його началом — перший помічник, таурен Пан Кара, мурлок-кухар Печивко й загін піратів Дефіасу, що патрулюють палубу броненосця.",al={"екіпаж ґрінскіна","перший помічник","поплічники ґрінскіна"}},{q="Яка мета Ґрінскіна в Мертвих Копальнях?",a="Йому доручено підготувати величезний броненосець до плавання, щоб той вийшов із підземного гроту у Велике Море й ударив по королівству Стормвінд.",al={"що ґрінскін робить","чому ґрінскін тут"}},{q="Де знайти Капітана Ґрінскіна?",a="Він походжає головною палубою великого корабля, що стоїть на якорі в останній печері Мертвих Копалень, і стереже підступи до Едвіна Венкліфа.",al={"місце ґрінскіна","де капітан ґрінскін"}},{q="Капітан Ґрінскін — член Братства Дефіас чи найманець?",a="Він найманий капітан піратів на прямій службі в Едвіна Венкліфа й командує морськими силами, що діють у змові з Братством Дефіас.",al={"чи ґрінскін дефіас","фракція ґрінскіна"}}},fp="17,320,24.355.0,15.338.0,25.178.0,56.174.0,35.159.0,45.173.0,37.134.0,67.144.0"}
P.entries["npc:captain-rugelfuss"] = {n="Капітан Руґелфусс",s="Капітан Руґелфусс — суворий дворфійський офіцер, що стоїть на варті біля південної брами в Долині Королів. Йому доручено боронити кордон Лох Модану, і він організовує оборону від раптового й лютого повстання трогів.",h="Капітан Руґелфусс — суворий дворфійський офіцер, що стоїть на варті біля південної брами в Долині Королів.",kw={"капітан руґелфусс","долина королів","лох модан","троги","оборона","горяни"},ang={["class:Warrior"]="Воїни знайдуть спільну мову з Руґелфуссом — з його тверезою тактичністю й простим наказом розчистити передову клинком і щитом.",["faction:Alliance"]="Руґелфусс нагадує мандрівникам Альянсу: поки великі армії воюють деінде, захист рідних земель від диких вторгнень не менш важливий для виживання союзу.",["race:Dwarf"]="Для дворфів Капітан Руґелфусс уособлює непохитну рішучість війська Айронфорджа, що стереже прадідівські гірські перевали від одвічних підземних ворогів."},sec={{t="Утримати південну браму",b="Неподалік велетенських різьблених арок Долини Королів Капітан Руґелфусс наглядає за південним входом до Лох Модану. Сили Альянсу розпорошені по всьому світу, тож Айронфордж покладається на таких досвідчених офіцерів, як він, щоб рідні землі лишалися в безпеці. Руґелфусс не терпить військової пишноти й формальностей і цілком зосереджується на суворій дійсності, з якою стикається кордон."},{t="Навала трогів",b="Головна біда, що вимагає уваги Руґелфусса, — дедалі більша загроза трогів. Ці дикі потвори, вивільнені з давніх печер, ринули на нагір'я, розбили віддалені дворфійські патрулі й облаштували поблизу укріплені плацдарми. Під знаменом захисту королівських земель капітан набирає вправних мандрівників, щоб проріджувати їхні лави й відкинути створінь від дороги."},{t="Розвідка на передовій",b="Обов'язки Руґелфусса не зводяться до грубої сили. Його горяни безперервно розвідують табори трогів."}},faq={{q="Хто такий Капітан Руґелфусс?",a="Капітан Руґелфусс — дворфський військовий командир з Айронфорджа, що стоїть біля південних воріт у Долині Королів у Лох Модані. Він відповідає за оборону краю й безпеку прикордоння.",al={"лор капітана руґелфусса","хто такий руґелфусс","руґелфусс лох модан"}},{q="Де знайти Капітана Руґелфусса?",a="Він стоїть біля Південної Брами в Долині Королів і стереже південний перевал, що веде з Лох Модану до Дун Мороґу.",al={"де руґелфусс","місце капітана руґелфусса"}},{q="Чому Капітан Руґелфусс непокоїться через трогів?",a="Недавнє повстання трогів серйозно загрожує дворфським поселенням і шляхам постачання. Троги підступили просто до південних воріт і нападають на патрулі Айронфорджа, тож, якщо їх не зупинити, вони можуть заполонити королівські землі.",al={"чому битися з троґами","загроза троґів лох модан"}},{q="Чому Руґелфусс відмахується від військових формальностей?",a="Руґелфусс вважає зайві козиряння й церемонії небезпечним відволіканням, коли королівські землі в облозі. Він вимагає негайних практичних дій, а не протоколу.",al={"особистість руґелфусса","вільно раса"}}},fp="17,219,25.389.0,19.402.0,24.99.1,25.198.0,37.132.0,48.241.0,50.172.0"}
P.entries["npc:captain-shatterskull"] = {n="Капітан Шаттерскал",s="Капітан Шаттерскал — досвідчений оркський командир, що несе службу в Базовому Таборі Мор'шан на північному рубежі Пусток. Він — важливий оплот Орди: керує відсіччю силам нічних ельфів, які оскаржують кордон біля Ущелини Бойової Пісні.",h="Капітан Шаттерскал — досвідчений оркський командир, що несе службу в Базовому Таборі Мор'шан на північному...",kw={"капітан шаттерскал","базовий табір мор'шан","ашенваль","кадрак","нічні ельфи","орки"},ang={["faction:Horde"]="Для воїнів Орди, що прибувають із південних Пусток, Капітан Шаттерскал уособлює суворий авангард, що стримує набіги нічних ельфів з Ашенвалю.",["race:Orc"]="Шаттерскал — втілення незламного бойового духу нової Орди: він боронить важко здобуті землі від тих, хто вважає їхню присутність вторгненням."},sec={{t="Вартовий північного кордону",b="У Базовому Таборі Мор'шан на межі з Ашенвалем Капітан Шаттерскал стоїть на передовій територіальних сутичок Орди. Разом з іншими офіцерами, як-от Кадраком, Шаттерскал утримує позиції Орди проти Вартових нічних ельфів і загонів Срібнокрилих, що прагнуть повернути прикордонні землі. Його пост вимагає невсипущої пильності, адже війна за деревину й прадавні землі Ашенвалю щомиті загрожує перекинутися в Пустки."}},faq={{q="Хто такий Капітан Шаттерскал?",a="Капітан Шаттерскал — орк-офіцер із Базового Табору Мор'шан на північному краю Пусток, що керує обороною від нічних ельфів.",al={"особа шаттерскала","хто капітан шаттерскал","нпс шаттерскал"}},{q="Де знайти Капітана Шаттерскала?",a="Він перебуває в Базовому Таборі Мор'шан на далекому північному кордоні Пусток, просто перед входом до Ашенвалю.",al={"місце шаттерскала","де капітан шаттерскал","табір мор'шан шаттерскал"}},{q="Яка його роль у Базовому Таборі Мор'шан?",a="Шаттерскал — польовий командир, що допомагає боронити північне прикордоння Орди й шикує воїнів, щоб відкинути Вартових Срібнокрилих з Альянсу.",al={"що робить шаттерскал","призначення шаттерскала","командир мор'шан"}},{q="З ким працює Капітан Шаттерскал?",a="Він служить поряд з іншими відомими офіцерами передової, як-от Кадрак, координуючи в таборі оборону й набір бійців для прикордонних сутичок.",al={"союзники шаттерскала","кадрак і шаттерскал"}}},fp="20,262,31.469.0,28.168.0,40.120.0,39.177.0,40.142.0"}
P.entries["npc:captain-stoutfist"] = {n="Капітан Стаутфіст",s="Капітан Стаутфіст — дворфійський офіцер, що відповідає за оборону Гавані Менетіл у Багнокраї. Клан Драконячої Пащі дедалі зухваліше висувається зі своїх болотяних твердинь, тож Стаутфіст керує обороною й контрнаступами, щоб важливий порт Альянсу не впав.",h="Капітан Стаутфіст — дворфійський офіцер, що відповідає за оборону Гавані Менетіл у Багнокраї.",kw={"капітан стаутфіст","гавань менетіл","багнокрай","драконяча паща","нек'рош","дворфи"},ang={["class:Warrior"]="Стаутфіст — дворфійський тактик без зайвих церемоній: сміливі бойові удари він цінує вище за обережні укріплення й ставить воїнів на передову, щоб нищити ворожі гармати й ватажків.",["faction:Alliance"]="Капітан Стаутфіст тримає оборону в одному з найважливіших морських вузлів Альянсу, не даючи закрити морські шляхи між Каз Моданом, Стормвіндом і далекими заставами.",["race:Dwarf"]="Стаутфіст уособлює тверду рішучість війська Айронфорджа: йому доручено берегти важливі споруди в низинах, далеко від безпечних гірських вершин."},sec={{t="Захисник Менетіла",b="Гавань Менетіл — головний глибоководний порт, що поєднує Айронфордж і Стормвінд із болотистими низинами Багнокраю й морем за ними. Як комендант міста, Капітан Стаутфіст несе важкий тягар: він мусить уберегти доки, мирних мешканців і гарнізон від довколишніх загроз. Болота славляться своїми небезпеками, але найбільша загроза для поселення — організований наступ орків-ренегатів."},{t="Загроза Драконячої Пащі",b="Клан Драконячої Пащі, що окопався в Багнокраї ще з Другої війни, почав просуватися просто до шляхів і перевалів. Пробравшись у Дун Алґаз, орки загрожують перерізати сухопутну артерію, що з'єднує Лох Модан і Айронфордж із Гаванню Менетіл. Вояків катастрофічно бракує, тож Капітан Стаутфіст покладається на добровольців Альянсу, яких рекомендує горянин Валстаґ Айронджо, щоб зупинити навалу."},{t="Удар по Нек'рошу",b="Не чекаючи облоги, Капітан Стаутфіст очолює рішучий наступ на табори орків. Він посилає союзні сили захопити бойові прапори біля Місця Розкопок Велґара, вивести з ладу катапульти Драконячої Пащі, які готують до штурму, і знищити безжального місцевого вождя клану — Нек'роша Скаллкрашера. Убивши Нек'роша, Стаутфіст сподівається зламати хребет орківському наступу, перш ніж Гавань Менетіл упаде під його натиском."}},faq={{q="Хто такий Капітан Стаутфіст?",a="Капітан Стаутфіст — дворф, військовий командир, якому доручено захищати Гавань Менетіл. Він координує оборону гарнізону, оцінює загрози в краї й набирає добровольців, щоб відкидати ворогів, які зазіхають на порт.",al={"капітан стаутфіст","стаутфіст менетіл","капітан менетіла"}},{q="Де перебуває Капітан Стаутфіст?",a="Він служить у Гавані Менетіл — головному поселенні Альянсу на західному узбережжі Багнокраю.",al={"місце стаутфіста","де капітан стаутфіст","знайти стаутфіста"}},{q="Чому Капітанові Стаутфісту потрібна допомога ззовні?",a="Місцевий гарнізон розпорошений по всьому Багнокраю. Орки Драконячої Пащі захопили гірські проходи біля Дун Алґазу й підбираються до міста, тож Стаутфістові бракує людей, щоб водночас іти в наступ і стерегти гавань.",al={"чому стаутфісту потрібна допомога","проблеми оборони менетіла"}},{q="Хто такий Нек'рош Скаллкрашер?",a="Нек'рош Скаллкрашер — безжальний ватажок орків Драконячої Пащі в Багнокраї. Капітан Стаутфіст наказує вбити його, щоб розладнати дії орків і вберегти Гавань Менетіл від повномасштабного нападу.",al={"хто такий нек'рош","нек'рош черепокрушій","бос драконячої пащі болота"}},{q="Як Дун Алґаз пов'язаний із завданням Капітана Стаутфіста?",a="Дун Алґаз — життєво важливий гірський прохід, що сполучає Лох Модан і Айронфордж із Багнокраєм. Коли орки Драконячої Пащі вдерлися в прохід, Горянин Валстаґ Айронджо попередив, що Менетіл у небезпеці, і скерував шукачів пригод до Стаутфіста, щоб допомогти зміцнити гавань.",al={"дун алґаз стаутфіст","зв'язок з рукавицею алґаза"}},{q="Чим загрожують катапульти Драконячої Пащі?",a="Драконяча Паща зібрала облогові машини, щоб трощити укріплення й узяти Гавань Менетіл в облогу. Стаутфіст посилає звитяжців вивести катапульти з ладу, перш ніж їх підкотять на відстань пострілу.",al={"хитрість нек'роша катапульти","катапульти драконячої пащі"}}},fp="17,302,20.437.0,20.430.0,20.439.1,25.214.0,35.99.0,45.257.0,29.215.0,58.263.0,44.205.0"}
P.entries["npc:captain-thalo-thas-brightsun"] = {n="Капітан Тало'тас Брайтсан",s="Капітан Тало'тас Брайтсан — капер, пов'язаний із картелем Стімвідл, що стоїть на пристанях Раджета. Хоч він і ввічливий з мандрівниками з Альянсу, у душі плекає люту образу на сили Терамора у Твердині Північної Варти, які насмілюються обстрілювати його кораблі.",h="Капітан Тало'тас Брайтсан — капер, пов'язаний із картелем Стімвідл, що стоїть на пристанях Раджета.",kw={"тало'тас брайтсан","капер","раджет","картель стімвідл","твердиня північної варти","терамор"},ang={["faction:Alliance"]="У порту Брайтсан говоритиме з вами ввічливо, але невпинна агресія сил Терамора у Твердині Північної Варти штовхнула його на таємну змову з вашими ворогами.",["faction:Horde"]="Брайтсан дає Орді зручний привід ударити по Твердині Північної Варти й знешкодити морську артилерію Альянсу на узбережжі центрального Калімдору."},sec={{t="Капер із Раджета",b="З гамірного нейтрального порту Раджет Капітан Тало'тас Брайтсан очолює Каперів Тало'дана під широким стягом картелю Стімвідл. Теоретично купці Раджета раді будь-якому прапору, аби лиш монета була справжня, але морська торгівля вздовж узбережжя Пусток повна небезпек. Трохи на південь від порту стоїть Твердиня Північної Варти — войовниче укріплення Альянсу, чия важка артилерія загрожує нейтральним морським шляхам. Брайтсан зовні тримається нейтрально з мандрівниками, але войовничий гарнізон, що обстрілює його флот, остаточно вичерпав його терпіння."},{t="Власна війна з Північною Вартою",b="Відкритий конфлікт поставив би під загрозу нейтралітет Раджета, тож Брайтсан не може кинути на фортецю цілу армаду. Натомість він шукає вправних найманців з Орди, щоб звести рахунки. Він потай влаштовує удари по Твердині Північної Варти, щоб змусити замовкнути гармати фортеці й визволити свою захоплену команду. Наймаючи помічників з Орди, а не накликаючи пряму відплату Альянсу на картель, Брайтсан захищає свої морські інтереси й тримає офіційні книги Раджета в чистоті."}},faq={{q="Хто такий Капітан Тало'тас Брайтсан?",a="Капітан Тало'тас Брайтсан — морський капітан і ватажок каперів Тало'дана, що діє з Раджета на службі картелю Стімвідл.",al={"тало'тас брайтсан","хто такий брайтсан","капітан рятчета"}},{q="Чому він сердиться на Твердиню Північної Варти?",a="Сили Альянсу, що стоять у Твердині Північної Варти, раз у раз обстрілюють із важких гармат його торгові судна й ув'язнюють його моряків, зриваючи торгівлю вздовж узбережжя.",al={"чому нападати на північну варту","проблема брайтсана з північною вартою","чому ненавидить альянс"}},{q="Чому він наймає лише Орду для нападу на Північну Варту?",a="Хоч він і дотримується дипломатичного нейтралітету щодо мандрівників з Альянсу, які навідуються до Раджета, він не може розраховувати, що віддані Альянсу бійці обстрілюватимуть твердиню Альянсу на кшталт Північної Варти. А в Орди є всі стратегічні причини послабити військову заставу Терамора.",al={"чи альянс виконає його завдання","чому лише орда","завдання брайтсана для альянсу"}},{q="Він належить до Альянсу чи до Орди?",a="Ні до тих, ні до інших: він вірний передусім картелю Стімвідл і своїм каперам, хоча через його образи його інтереси нині збігаються з інтересами Орди.",al={"фракція брайтсана","чи брайтсан орда","чи брайтсан нейтральний"}}},fp="28,298,20.594.0,29.519.0,36.149.0,35.172.0,53.271.0,44.167.0"}
P.entries["npc:captured-mountaineer"] = {n="Полонений Горянин",s="Полонений Горянин — дворф з Айронфорджа, якого тримають у підвалі Таверни «Шибеничний Кінець» у Бріллі. Зв'язаний і під охороною Відступників, він слугує мимовільним піддослідним для похмурих дослідів Королівського Аптекарського Товариства.",h="Полонений Горянин — дворф з Айронфорджа, якого тримають у підвалі Таверни «Шибеничний Кінець» у Бріллі.",kw={"полонений горянин","дворф","айронфордж","таверна шибеничний кінець","аптекар йогаан","піддослідний"},ang={["race:Dwarf"]="Бачити гордого брата з Айронфорджа в клітці під таверною Відступників, підданого жахливим алхімічним дослідам, — гірке нагадування про безжальну ворожість Відступників до живих.",["race:Undead"]="Для Відступників живі бранці з Альянсу — життєво важливий ресурс для мети Королівського Аптекарського Товариства: довершити чуму, здатну стерти і Погибель, і живих ворогів."},sec={{t="В'язень у підвалі",b="Захований під мостинами Таверни «Шибеничний Кінець» у Бріллі, цей Айронфорджський Горянин сидить у полоні далеко від безпечного Каз Модану. Поки нагорі п'ють відвідувачі, Королівське Аптекарське Товариство використовує його як мимовільного піддослідного для своїх варив. Аптекар Йогаан і його колеги перевіряють смертоносність своєї чуми на живому організмі Альянсу, вимірюючи на в'язневі, наскільки швидко й болісно їхні токсини несуть живим кінець."}},faq={{q="Хто такий Полонений Горянин?",a="Це розвідник Альянсу з Айронфорджа, що потрапив до рук Відступників. Нині його тримають у підвалі Таверни «Шибеничний Кінець» у Бріллі.",al={"хто цей дворф","дворф у таверні бріллу","дворф-полонений"}},{q="Чому Відступники тримають його живим у підвалі?",a="Королівське Аптекарське Товариство використовує його як живий піддослідний зразок. Замість того щоб одразу стратити, аптекарі на кшталт Йогаана дають йому дослідні суміші, щоб вивчити, як вони діють на живий дворфський організм.",al={"чому тримають живим","чому в таверні","що роблять з дворфом"}},{q="Що з ним стається під час дослідів?",a="У межах досліджень нової чуми його змушують ковтати зілля, зварені аптекарями. Смертоносна суміш швидко доводить свою дієвість, убиваючи в'язня як доказ поступу в розробці отрути.",al={"чи дворф помре","що буде в новій чумі"}},{q="Хто ще має з ним справу тут, унизу?",a="Окрім аптекарів, що проводять досліди, у льоху бувають і місцеві, як-от Рене Лауер: вона розповідає історії скутому дворфові-бранцю.",al={"хто говорить з дворфом","рене лауер"}}},fp="20,235,24.488.0,32.148.0,55.216.0,37.220.1,38.174.0"}
P.entries["npc:captured-scarlet-zealot"] = {n="Полонений Багряний Фанатик",s="Полонений Багряний Фанатик — хрестоносець-бранець, якого тримають у підвалі Таверни «Шибеничний Кінець» у Бріллі. Під наглядом аптекарів Відступників й містян він слугує живим піддослідним для варив, які розробляє Королівське Аптекарське Товариство.",h="Полонений Багряний Фанатик — хрестоносець-бранець, якого тримають у підвалі Таверни «Шибеничний Кінець» у...",kw={"полонений багряний фанатик","багряний хрестовий похід","таверна шибеничний кінець","аптекар йогаан","рене лауер","брілл"},ang={["class:Priest"]="Багряні фанатики заявляють про виняткове право на Святе Світло, та непохитний запал цього в'язня не захищає його від похмурої дійсності полону у Відступників.",["race:Undead"]="Для Відступників з Брілла цей фанатик у кайданах утілює невпинних хрестоносців, що прагнуть їхнього винищення, — і значно кориснішу роль піддослідного кролика аптекаря."},sec={{t="Запеклий бранець у Бріллі",b="Ув'язнений під Таверною «Шибеничний Кінець», цей член ордену, що зветься Багряний Хрестовий Похід, утілює незламний фанатизм своїх побратимів. Навіть у кайданах, в оточенні нежиті, яку він має за гидоту, він не виявляє ні краплі каяття й отруйно таврує кожного, хто з ним заговорить, — як-от Рене Лауер, яку він кляне зрадницею. Для Відступників полонити живого фанатика — не акт милосердя: це цінний людський матеріал, щоб оцінити смертоносність дослідних чум і токсинів, які розробляє Аптекар Йогаан."}},faq={{q="Чому в Бріллі тримають живим Багряного Фанатика?",a="Відступники тримають його в полоні в підвалі таверни як живий зразок для випробування нових отрут і хімічних речовин, які розробляє Королівське Аптекарське Товариство.",al={"чому багряний фанатик у полоні","чому тримають фанатика живим","хто фанатик у погребі бріллу"}},{q="Де знайти цього полоненого?",a="Його ув'язнено в сирому льоху під Таверною «Шибеничний Кінець» у центрі Брілла на Галявинах Тірісфалю.",al={"де полонений багряний фанатик","місце багряного фанатика","фанатик у бріллі"}},{q="Як він ставиться до Відступників довкола?",a="Попри ув'язнення, він і далі фанатично зухвалий: сиплє образами й таврує місцевих, як-от Рене Лауер, зрадниками людства й Світла.",al={"що каже фанатик","діалог фанатика","рене лауер і фанатик"}}},fp="23,259,25.524.0,44.159.0,30.116.0,45.153.0"}
P.entries["npc:carendin-halgar"] = {n="Карендін Галґар",s="Карендін Галґар — відомий наставник чорнокнижників із Відступників, що мешкає в Магічному Кварталі Андерсіті. Гострий на язик і сумнозвісно нетерплячий, він наглядає за вишколом молодих знавців темних мистецтв. Він навчає чорнокнижників підкоряти могутніх демонічних істот із Викривленого Нижнього Світу, зокрема обрядів, що зв'язують блукачів Порожнечі й сукубів.",h="Карендін Галґар — відомий наставник чорнокнижників із Відступників, що мешкає в Магічному Кварталі Андерсіті.",kw={"карендін галґар","чорнокнижник","андерсіті","магічний квартал","демони","блукач порожнечі"},ang={["class:Warlock"]="Карендін Галґар — важливий наставник у Лордероні: він веде чорнокнижників крізь виснажливі випробування, потрібні, щоб підкорити й зв'язати і блукачів Порожнечі, і сукубів.",["faction:Horde"]="Карендін — головна ланка зв'язку для чорнокнижників Орди на сході: він узгоджує навчання з іншими знавцями темних мистецтв за морем, у Калімдорі.",["race:Undead"]="Утілюючи непоступливий дух Відступників, Карендін не знає ні жалю, ні вагань і бачить у демонах лише знаряддя, які треба зламати й використати."},sec={{t="Майстер темних мистецтв",b="У смердючому присмерку Магічного Кварталу Андерсіті Карендін Галґар навчає тих, хто заглиблюється у Викривлений Нижній Світ. Він вимагає зосередженості й послуху і майже не терпить невдач, вагань чи слабкості. Під його пильним оком чорнокнижники переходять від простих заклинань до небезпечного мистецтва прикликання й маніпуляції душами, що лише утверджує безжальний підхід Відступників до служби демонів."},{t="Підкорення Нижнього Світу",b="Головна наука Карендіна — підкоряти волі заклинача дедалі небезпечніших демонів. Він посилає учнів по всьому Лордерона й далі, щоб здобути давні руни, рунічні камені й очищену есенцію смертних для завершення підступних кіл прикликання. Чи то тіньова істота Порожнечі, чи звабниця-сукуб, — Карендін дбає, щоб чорнокнижник підкорив демона, перш ніж той пожере свого господаря."}},faq={{q="Де знайти Карендіна Галґара?",a="Карендін Галґар перебуває в Магічному Кварталі Андерсіті серед інших знавців магії скверни й тіні.",al={"місце карендіна галґара","місце вчителя чорнокнижників андерсіту","де галґар"}},{q="Яку роль Карендін Галґар відіграє для чорнокнижників?",a="Він наставник чорнокнижників Орди й дає їм завдання: навчає ритуалів, потрібних, щоб викликати й назавжди підкорити могутніх демонів, як-от Блукача порожнечі й Сукуба.",al={"що робить карендін","призначення галґара","завдання карендіна"}},{q="Який у Карендіна Галґара характер?",a="Він горезвісно різкий, вимогливий і геть позбавлений терпіння. Від учнів він чекає швидких результатів і зневажає марнування часу та виправдання.",al={"темперамент галґара","чи карендін добрий","лор карендіна галґара"}},{q="Навіщо Карендінові чисті серця для ритуалів виклику?",a="На уроках виклику сукуба Галґар доручає послушникам добути незаплямовані серця чистих: їхня невинність і сутність править за принаду, щоб звабити підступного демона й упіймати його в коло підкорення.",al={"призначення чистих сердець","виклик сукуби карендін","чому чисті серця"}},{q="Чи має Карендін Галґар справи з чорнокнижниками поза Андерсіті?",a="Yes. He sends promising students to Strahad Farsan in the Barrens to continue their studies.",al={"зв'язки карендіна","галґар оргріммар","ґан'рул бладай карендін"}},{q="До кого Карендін посилає досвідчених чорнокнижників?",a="Коли послушник досить опанує простих демонів, Карендін посилає його шукати глибших таємних знань — наприклад, до дивакуватого закликача Страгада Фарсана в Пустках.",al={"пошук страгада","до кого карендін посилає","наступний наставник галґара"}}},fp="15,387,23.421.0,22.456.1,35.129.0,49.183.0,43.160.0,60.214.0,66.92.0,48.217.0"}
P.entries["npc:caretaker-folsom"] = {n="Наглядач Фолсом",s="Наглядач Фолсом — похмурий слуга з людей, якого можна зустріти біля Каналів Стормвінда неподалік від Парку. Колись він був довіреним доглядачем маєтку шляхетної родини Флінтрідж, а тепер має справу з гіркими рештками її трагічного занепаду.",h="Наглядач Фолсом — похмурий слуга з людей, якого можна зустріти біля Каналів Стормвінда неподалік від Парку.",kw={"наглядач фолсом","флінтрідж","сталван містмантл","канали","сутінколісся","стормвінд"},ang={["faction:Alliance"]="Для слідчих Альянсу, що відстежують похмуру долю найсумнозвіснішого вбивці Сутінколісся, Фолсом — незамінний живий зв'язок з останніми днями дому Флінтріджів."},sec={{t="Дім у руїнах",b="Як і його батько, Фолсом присвятив життя служінню родині Флінтрідж як доглядач маєтку. Це тихе служіння скінчилося кривавою різаниною, що спіткала дім Флінтріджів. Рід обірвався, і маєток стояв покинутим, доки не скінчилися всі кошти. Лишившись сам наглядати за рештками господарства, Фолсом несе сумний обов'язок розпродати на аукціоні вцілілі родинні реліквії й майно."},{t="Нитки темної історії",b="Тих, хто розслідує криваву історію Сталвана Містмантла, часто посилають до Фолсома на стормвіндські набережні каналів. Хоч наглядач пригнічений горем і неохоче говорить, у нього є ключові частини цієї трагедії — вцілілі речі й документи з дому Флінтріджів, що розкривають моторошне падіння Сталвана і його зрештою зникнення в тінях Сутінколісся."}},faq={{q="Хто такий Наглядач Фолсом?",a="Це слуга-людина зі Стормвінда, що колись доглядав шляхетний маєток Флінтріджів. Після трагічного вбивства всієї родини Флінтріджів він лишився розпоряджатися рештками їхнього майна.",al={"фолсом","хто такий фолсом","лор наглядача фолсома"}},{q="Де знайти Наглядача Фолсома?",a="Він стоїть на кам'яних набережних Каналів у Стормвінді, неподалік від входу до Парку.",al={"де наглядач фолсом","місце фолсома","наглядач фолсом стормвінд"}},{q="Що сталося з родиною Флінтріджів?",a="Родина загинула в різанині у своєму маєтку багато років тому. Спадкоємців, що претендували б на маєток, не лишилося, тож його зачинили й покинули занепадати, доки не скінчилися кошти.",al={"вбивство флінтріджів","що сталося з флінтріджами","хто вбив флінтріджів"}},{q="Чому Фолсом розпродує родинні реліквії?",a="Після загибелі родини її рештки коштів згодом геть вичерпалися. Фолсомові випав похмурий обов'язок віддати на аукціон те, що лишилося з майна.",al={"чому аукціон","аукціон флінтріджів","аукціон фолсома"}},{q="Яка його роль у «Легенді про Сталвана»?",a="Фолсом допомагає шукачам пригод відтворити трагедію Сталвана Містмантла, даючи доступ до решти особистих речей і підказок, що лишилися з маєтку Флінтріджів.",al={"завдання сталвана фолсом","легенда про сталвана фолсом"}}},fp="16,226,16.468.0,19.389.1,24.205.0,34.102.0,39.174.1,43.180.0,42.180.0"}
P.entries["npc:carolai-anise"] = {n="Каролай Еніс",s="Каролай Еніс — ексцентрична алхімікиня з Відступників, що мешкає в селищі Брілл на Галявинах Тірісфалю. Вона навчає алхіміків-початківців, хоча її небезпечні варива вже не раз викликали тривожне бурмотіння місцевих вартових.",h="Каролай Еніс — ексцентрична алхімікиня з Відступників, що мешкає в селищі Брілл на Галявинах Тірісфалю.",kw={"каролай еніс","алхімія","алхімікиня","брілл","реагенти","відступники"},ang={["profession:Herbalism"]="Збирачі, що добувають дику флору по всьому Тірісфалю, часто приносять Каролай мирноцвіт, срібнолист і земнокорінь, щоб вона переробила їх на потужні суміші.",["race:Undead"]="Для щойно звільнених Відступників, які вчаться працювати з реагентами, Каролай дає основи алхімічного ремесла на Галявинах Тірісфалю."},sec={{t="Вибухове ремесло",b="Працюючи у Бріллі, Каролай Еніс присвячує своє нежиття нестабільному мистецтву алхімії. Поки багато дослідників Відступників працюють під похмурим мандатом Королівського Аптекарського Товариства, Каролай вариться у власних дивних зіллях просто всередині поселення. Її непередбачувані досліди й димучі реторти настільки сумнозвісні, що Вартові Смерті, які пильнують Брілл, відверто бурчать: схоже, вона налаштована підірвати власну хату."}},faq={{q="Хто така Каролай Еніс?",a="Каролай Еніс — наставниця алхімії з нежиті, що живе в поселенні Брілл на Галявинах Тірісфалю. Вона навчає Відступників варити зілля, еліксири й олії.",al={"каролай еніс","алхімік бріллу","хто така каролай"}},{q="Де її знайти?",a="Вона в Бріллі, головному містечку Відступників у центрі Галявин Тірісфалю: порається біля свого алхімічного приладдя в одній із будівель містечка.",al={"де каролай еніс","місце каролай еніс","де вчитель алхімії бріллу"}},{q="Чому Вартові Смерті на неї скаржаться?",a="Місцеві Вартові Смерті застерігають, що нестійкі алхімічні досліди Каролай — нещасний випадок, що лише чекає своєї години, і жартують чи нарікають, що колись вона висадить у повітря весь свій дім.",al={"вартові смерті скаржаться на каролай","підрив будинку","небезпека каролай еніс"}}},fp="13,210,16.427.0,21.166.0,21.152.0,42.177.0"}
P.entries["npc:cazul"] = {n="Казул",s="Казул — старезний сліпий орк-чорнокнижник, що живе в темній печері Тіньової Розколини під Оргріммаром. Хоч він і втратив зір, його окультне прозріння глибоке, і він наставляє молодих адептів темних мистецтв, що прагнуть розширити свою владу над демонами.",h="Казул — старезний сліпий орк-чорнокнижник, що живе в темній печері Тіньової Розколини під Оргріммаром.",kw={"казул","сліпий","чорнокнижник","тіньова розколина","оргріммар","демони"},ang={["class:Warlock"]="Чорнокнижників Орди посилають до Казула в Тіньову Розколину, коли їм потрібні настанови, як скорити глибші сили Нижнього Світу.",["race:Orc"]="Казул утілює незгасну присутність темної магії серед орків: він практикує своє ремесло подалі від пильних очей почесної варти Тралла."},sec={{t="Очі в темряві",b="Ховаючись у печерних глибинах Тіньової Розколини, Казул лишається живою реліквією давніх традицій чорнокнижників. Хоч він зовсім сліпий, його чуття налаштовані на мінливі течії Викривленого Нижнього Світу й шепіт демонічних сутностей. Молодих чорнокнижників часто посилають до нього, коли вони прагнуть поглибити свою майстерність і скорити небезпечніших слуг. Його гостра проникливість і окультна мудрість ясно показують: утративши очі, він не втратив ані дещиці своєї магічної сили."}},faq={{q="Хто такий Казул?",a="Казул — старий сліпий орк-чорнокнижник, що живе в Тіньовій Розколині під Оргріммаром. Він відомий глибоким знанням темного чаклунства й демонології та радить молодим чорнокнижникам.",al={"хто такий казул","лор казула","сліпий казул нпс"}},{q="Чому Казул сліпий?",a="Від чого саме осліп Казул, ніде не записано.",al={"чому казул сліпий","як казул втратив зір"}},{q="Яку роль Казул відіграє для чорнокнижників?",a="Казул відіграє важливу роль, скеровуючи чорнокнижників, що прагнуть удосконалити своє ремесло, особливо тих, хто вчиться викликати й підкоряти сукуба.",al={"завдання казула","чого навчає казул","завдання чорнокнижника казул"}}},fp="5,279,16.468.0,13.200.0,19.51.0,39.139.0"}
P.entries["npc:cerellean-whiteclaw"] = {n="Сереллеан Вайтклоу",s="Сереллеан Вайтклоу — нічний ельф, що відпочиває біля пристані й заїзду Обердайна на Темному Узбережжі. Його переслідує пам'ять про кохану, втрачену під час давнього Розколу, і він ніяк не може дати її неспокійному духові спочинок.",h="Сереллеан Вайтклоу — нічний ельф, що відпочиває біля пристані й заїзду Обердайна на Темному Узбережжі.",kw={"сереллеан вайтклоу","аная донраннер","амет'аран","смарагдовий сон","обердайн","війна прадавніх"},ang={["class:Druid"]="Як і багато друїдів, Сереллеан поринув у довгий сон разом із Малфуріоном Стормрейджем, але Смарагдовий Сон так і не зміг змити його земного горя.",["race:NightElf"]="Трагічна історія Сереллеана відбиває глибокі, незагоєні рани, яких завдали калдореям Війна Прадавніх і Великий Розкол."},sec={{t="Розірване кохання",b="Десять тисяч років тому, ще до Війни Прадавніх, Сереллеан Вайтклоу ділив життя з Анаєю Донраннер. Коли демонічна навала розірвала давній Калімдор, Аная загинула під час руйнування свого міста, Амет'Арана. Убитий горем, Сереллеан пішов за Малфуріоном Стормрейджем у довгий друїдський сон, та Смарагдовий Сон майже не дав йому перепочинку від спогадів про неї. Прокинувшись через тисячоліття, він блукав Темним Узбережжям у тумані горя — і виявив, що привид Анаї досі прикутий до того самого каміння, де вона загинула."},{t="Благання про звільнення",b="Хоч Сереллеан і прагне дати Анаї спокій, він не може знести горя, щоб власноруч здолати її змучену тінь. Він просить мандрівників вирушити на південь, у примарні руїни Амет'Арана, упокоїти її дух і повернути її підвіску. Звільнена, тінь Анаї ненадовго з'являється Сереллеанові на пристані Обердайна, запевняє його у своєму незгасному коханні й обіцяє, що колись вони знову будуть разом у потойбіччі."}},faq={{q="Хто такий Сереллеан Вайтклоу?",a="Сереллеан Вайтклоу — прадавній нічний ельф, що живе біля причалів Обердайна на Темному Узбережжі. Він оплакує своє втрачене кохання, Анаю Донраннер, що загинула під час Війни Прадавніх десять тисяч років тому.",al={"хто такий сереллеан","сереллеан вайтклоу","ельф на доках обердайна"}},{q="Хто така Аная Донраннер?",a="Аная Донраннер — кохана Сереллеана, що жила в давньому місті Амет'Аран. Вона загинула під час Війни Прадавніх, коли місто лягло в руїни, і її змучений дух тисячоліттями блукав серед уламків.",al={"аная донраннер","кохана сереллеана","коханка сереллеана"}},{q="Чому Сереллеан сам не впокоїть дух Анаї?",a="Сереллеан досі так глибоко прив'язаний до неї й так убитий горем, що не має душевних сил зустрітися з її примарною подобою й знищити її власноруч. Він покладається на співчутливих мандрівників, щоб ті дарували їй останнє звільнення.",al={"чому сереллеан не б'ється з анаєю","чому потрібен шукач пригод"}},{q="Де руїни Амет'Арана?",a="Руїни Амет'Арана лежать на півдні Темного Узбережжя, на схід від головної дороги. Там блукають привиди давніх калдореїв, що загинули під час Великого Розколу.",al={"де руїни амет'арана","місце анаї","де аная"}}},fp="19,209,19.553.0,18.434.1,27.200.0,25.235.0,57.204.0,34.164.0"}
P.entries["npc:charlga-razorflank"] = {n="Чарлґа Рейзорфленк",s="Чарлґа Рейзорфленк, широко відома як Стара з Краула, — люта й хитра геомантка-ватажок, що панує над Рейзорфен Краулом. Під її проводом шипогриви Рейзорфен безжальною експансією вигнали тауренів із південних Пусток, стверджуючи, що борються в ім'я свого полеглого бога Аґамаґґана.",h="Чарлґа Рейзорфленк, широко відома як Стара з Краула, — люта й хитра геомантка-ватажок, що панує над Рейзорфен...",kw={"чарлґа рейзорфленк","стара з краула","геомантка","шипогриви","рейзорфен краул","погибель"},ang={["class:Shaman"]="Хоч Чарлґа й володіє могутнім геомантичним мистецтвом, її спотворення стихій — темне осквернення священних первісних традицій.",["faction:Horde"]="Знешкодити Чарлґу вкрай важливо, щоб уберегти караванні шляхи й табори по всьому півдню Пусток від невгамовних бойових загонів шипогривів.",["race:Tauren"]="Агресивна експансія Чарлґи вигнала ваш народ із прадавніх земель на півдні Пусток, тож її поразка — питання виживання племені й повернення своєї землі."},sec={{t="Стара з Краула",b="Серед заплутаних велетенських терновиків Рейзорфен Краула править Чарлґа Рейзорфленк. Її народ шанує її як майстриню геомантії, чия експериментальна магія не має рівних серед шипогривів, і Чарлґа згуртувала своїх свавільних родичів у єдину смертоносну загрозу. Вона підкорила первісну землю й велетенські колючки, що проросли з решток напівбога Аґамаґґана, перетворивши лабіринт Краула на неприступну фортецю."},{t="Експансія й зрада",b="Чарлґа згуртувала шипогривів під прапором відродження їхнього полеглого покровителя, Прадавнього Вепра Аґамаґґана. Стверджуючи, що пролита кров воскресить їхнього бога, вона спрямовувала безперервні жорстокі набіги на південні Пустки й зрештою вигнала тауренів з їхніх споконвічних земель. Проте її справжні амбіції сягають глибше: Чарлґа таємно почала перемовини з посланцями нежиті з Погибелі, виміняючи відданість свого нічого не підозрюючого племені на неприродну силу й підступні союзи."}},faq={{q="Хто така Чарлґа Рейзорфленк?",a="Чарлґа Рейзорфленк — вождиня й верховна геомантка племені шипогривів Рейзорфен, що має лігво глибоко в Рейзорфен Краулі на півдні Пусток.",al={"лор чарлґи","хто відьма краулів","бос разорфену"}},{q="Якою магією користується Чарлґа?",a="Вона надзвичайно обдарована геомантка, що керує стихією землі, магією кристалів і величезними кривавими тернами, народженими від напівбога Аґамаґґана.",al={"здібності чарлґи","сили геоманта"}},{q="Чому шипогриви напали на тауренів у Пустках?",a="Під проводом Чарлґи шипогриви почали війну, щоб витіснити тауренів із півдня Пусток, запевняючи, що ця битва дасть кров, потрібну для воскресіння їхнього дикого бога Аґамаґґана.",al={"чому квілборги напали на тауренів","війна квілборгів пустища"}},{q="Що пов'язує Чарлґу з Рейзорфен Даунс?",a="Чарлґа славиться тим, що сформувала значну частину величезного тернового купола, який захищає Рейзорфен Даунс: своєю глибокою геомантською майстерністю вона зміцнила обидві великі твердині шипогривів.",al={"чарлґа даунс","чарлґа разорфен даунс"}},{q="Чому Орда хоче її смерті?",a="Таурени та їхні союзники з Орди бачать у ній безпосередню загрозу самому існуванню через її безупинні набіги, захоплення їхніх земель і небезпечні зв'язки з темними силами.",al={"завдання відьми краулів","чому вбити чарлґу"}}},fp="18,315,22.410.0,22.497.1,26.157.0,28.152.0,54.188.0,47.169.0,33.177.0"}
P.entries["npc:chef-breanna"] = {n="Шеф-кухарка Бреанна",s="Шеф-кухарка Бреанна — головна куховарка місцевої їдальні Лейкширу в Горах Редріджу. Їй доручено годувати гарнізон стормвіндських солдатів, що захищають обложене прибережне містечко, і вона покладається на ситні місцеві продукти, щоб захисники трималися на ногах.",h="Шеф-кухарка Бреанна — головна куховарка місцевої їдальні Лейкширу в Горах Редріджу.",kw={"шеф-кухарка бреанна","гуляш з редріджу","кулінарія","гарнізон","лейкшир","ґретхен воґел"},ang={["faction:Alliance"]="Якби Шеф-кухарка Бреанна не годувала солдатів, що тримають міст і околиці міста, виснажений гарнізон Лейкширу швидко впав би від утоми під безперервними нападами орків і гнолів.",["profession:Cooking"]="Винахідливий рецепт Гуляшу з Редріджу від Бреанни показує, як прикордонна кухарка може перетворити небезпечних місцевих хижаків — павуків, грифів і кабанів — на ситну страву для цілої військової застави."},sec={{t="Годувати захисників Лейкширу",b="Працюючи в харчевні на північному заході Лейкширу разом зі своїми помічницями Крістал Баумен і Ґретхен Воґел, Шеф-кухарка Бреанна несе нелегкий обов'язок: забезпечувати харчами весь місцевий загін. Лейкшир облягають орки Блекрок, гноли й мурлоки, тож сила й бойовий дух нечисленного стормвіндського гарнізону важать понад усе. Її фірмова страва, Гуляш з Редріджу, готується з дичини й звірів, що бродять довколишніми хребтами: так небезпечні хижаки з диких околиць стають поживою для втомленої міської варти."}},faq={{q="Хто така Шеф-кухарка Бреанна?",a="Шеф-кухарка Бреанна — міська кухарка Лейкширу, що тримає місцеву кухню в північно-західному куточку поселення. Їй доручено годувати солдатів Стормвінда, які захищають Гори Редріджу.",al={"шеф-кухарка бреанна","бреанна лейкшир","хто така бреанна"}},{q="З чим Шеф-кухарці Бреанні треба допомогти?",a="Їй потрібна місцева дичина, щоб зварити Гуляш з Редріджу для гарнізону. Шукачі пригод допомагають їй, добуваючи в околицях Лейкширу кабанячі ребра, павуче м'ясо й м'ясо грифів.",al={"завдання бреанни","інгредієнти гуляшу редріджа","чого вона хоче"}},{q="Хто працює з Шеф-кухаркою Бреанною?",a="У її гамірному закладі працюють Кришталевий Гілляк і Ґретхен Воґел, які допомагають їй вести харчевню й годувати голодних містян і солдатів.",al={"помічники бреанни","крістал боуман","ґретчен фоґель"}}},fp="12,272,29.544.0,20.205.0,38.189.0,28.155.0"}
P.entries["npc:chef-grual"] = {n="Шеф-кухар Ґруал",s="Шеф-кухар Ґруал — кухар Таверни «Багряний Крук» у Даркширі. У відрізаному містечку, яке душать туман і чудовиська, Ґруал щосили намагається нагодувати Нічну Варту й утомлених мандрівників, навіть якщо його вибір інгредієнтів викликає подив.",h="Шеф-кухар Ґруал — кухар Таверни «Багряний Крук» у Даркширі.",kw={"шеф-кухар ґруал","багряний крук","даркшир","кулінарія","крабові котлети","павуки"},ang={["faction:Alliance"]="Працюючи в Таверні «Багряний Крук» у Даркширі, Ґруал годує втомлених захисників Альянсу, хоча регулярних караванів із припасами зі Стормвінда немає.",["profession:Cooking"]="Ґруал — похмурий урок кулінарної імпровізації: у відрізаних краях кухар готує з будь-якої місцевої живності, що ходить чи шурхотить між деревами.",["race:Human"]="Як і чимало мешканців Даркшира, що досі лишаються тут, Ґруал виявляє похмуру, вперту стійкість і по-своєму практично пристосовується до жахіть темного лісу."},sec={{t="Кухня в облозі",b="Тримати харчевню в Даркширі — похмура справа. Шляхи постачання з Вестфолу й Стормвінда безупинно тероризують розбійники, вовки й нежить, тож свіжих харчів майже немає. Ґруал обходиться тим, що дає глушина. Від вовчого стегна до будь-якого м'яса, яке місцеві шукачі пригод затягнуть до дверей, — Ґруал готує з практичністю, народженою з потреби."},{t="Таємні інгредієнти",b="Grual is infamous for his specialty dishes, most notably his famous 'Dusky Crab Cakes' and seasoned wolf kabobs. Given that coastal crabs are nowhere near the gloomy inland woods of Duskwood, his crab cakes rely on a rather revolting substitute: the gooey legs of local Venom Web Spiders. Whether patrons realize they are eating arachnid meat or simply prefer not to ask, Grual keeps the kitchen running without apologies."}},faq={{q="Хто такий Шеф-кухар Ґруал?",a="Шеф-кухар Ґруал — кухар-людина з Таверни «Багряний Крук» у Даркширі. Він готує їжу для захисників містечка, мандрівників і біженців, що ховаються від небезпек Сутінколісся.",al={"шеф-кухар ґруал","ґруал даркшир","кухар даркшира"}},{q="Де знайти Шеф-кухаря Ґруала?",a="Він стоїть у задній кімнаті й на кухні Таверни «Багряний Крук» у центрі Даркширу, на південному боці головної дороги.",al={"місце ґруала","де шеф-кухар ґруал","знайти ґруала"}},{q="З чого насправді зроблені Сутінкові Крабові Котлети?",a="Попри назву, крабів у Сутінколіссі немає. Шеф-кухар Ґруал замінює їх слизькими павучими лапами, добутими з величезних павуків, що заполонили довколишні ліси, і перекручує їх на котлети, що нагадують морепродукти.",al={"склад крабових котлет","павучі крабові котлети","що в сутінкових крабових котлетах"}},{q="Які завдання дає Шеф-кухар Ґруал?",a="Ґруал доручає мандрівникам добувати свіжі інгредієнти в дикому лісі: вовчі боки для Приправлених Вовчих Шашликів і павучі лапи для Сутінкових Крабових Котлет. Він також допомагає приготувати заспокійливу страву, щоб угамувати знервований шлунок Тремтія.",al={"завдання ґруала","рецепти ґруала"}},{q="Чому він годує Тремтія?",a="Тремтій — переляканий відлюдник, що отаборився в лісі, — часто потерпає від розладів шлунка через безупинний страх і недоїдання. До Ґруала звертаються, щоб той зготував щось ситне й заспокоїв його нерви.",al={"їжа тремтія","тремтій ґруал"}},{q="Чи пов'язаний Ґруал із Нічною Вартою?",a="Ґруал — цивільний кухар, а не вояк, але його кухня безпосередньо підтримує Нічну Варту й місцеве ополчення, годуючи Даркшир в умовах постійної облоги.",al={"ґруал нічна варта","чи ґруал воює"}}},fp="10,241,19.377.0,18.422.0,18.202.0,28.158.0,43.210.0,34.243.0,25.206.0,41.188.0"}
P.entries["npc:chef-jessen"] = {n="Шеф-кухар Джессен",s="Шеф-кухар Джессен — м'ясник і кухар Саутшора, що дбає, аби прибережне містечко було нагодоване серед постійної напруги на кордоні. Він славиться запальною вдачею, коли хтось шумить під час готування, а найбільше його пам'ятають за знаменитий черепаховий суп.",h="Шеф-кухар Джессен — м'ясник і кухар Саутшора, що дбає, аби прибережне містечко було нагодоване серед...",kw={"шеф-кухар джессен","кухар","саутшор","заспокійливий черепаховий суп","озеро лордамер","кулінарія"},ang={["faction:Alliance"]="Працюючи в Саутшорі, Джессен допомагає годувати солдатів і шукачів пригод Альянсу, що тримають оборону від північних загроз.",["profession:Cooking"]="Джессен — цінний знайомий для кухарів, що проходять через Гілсбред: його рецепт черепахового супу дає ситну страву для витривалих мандрівників."},sec={{t="Кухар у Саутшорі",b="Працюючи в Саутшорі, на півдні Передгір'я Гілсбреда, Шеф-кухар Джессен постачає харчі й м'ясо і місцевим мешканцям, і заїжджим солдатам Альянсу. Хоч він і бурчить, коли йому заважають працювати, кулінарного хисту йому не позичати. Колись давно, ще до того як чума й війна сколихнули північ Лордерону, він часто ходив на північ, повз Даларан, до берегів Озера Лордамер. Там він добував м'ясо місцевих черепах-клацозубів для свого улюбленого Заспокійливого Черепахового Супу — ситного рецепта, яким охоче ділиться з мандрівниками-початківцями, що допомагають йому зібрати складники."}},faq={{q="Хто такий Шеф-кухар Джессен?",a="Шеф-кухар Джессен — м'ясник і кухар-людина із Саутшору в Передгір'ї Гілсбреда. Він продає м'ясо й ділиться місцевими рецептами з мандрівниками, що підтримують Альянс.",al={"джессен","шеф-кухар джессен саутшор","хто такий джессен"}},{q="Яка знаменита страва Шеф-кухаря Джессена?",a="Його фірмовий рецепт — Заспокійливий Черепаховий Суп. Свого часу він добував свіже черепахове м'ясо з хапозубів, що живуть довкола Озера Лордамер, трохи на північ за Далараном, і варив із нього ситний відвар.",al={"рецепт черепашачого бісквіту","страва джессена","заспокійливий черепашачий бісквіт"}},{q="Чому Шеф-кухар Джессен просить мандрівників про допомогу?",a="Збирати м'ясо черепах-хапозубів довкола Озера Лордамер стало небезпечно через неспокій у краї й присутність Відступників поблизу. Джессен покладається на вправних шукачів пригод, щоб ті приносили черепахове м'ясо для його супу.",al={"завдання джессена","завдання на м'ясо черепахи"}},{q="Чи продає Шеф-кухар Джессен щось незвичайне?",a="Окрім м'яса, яке він продає мешканцям Саутшору, справжня гордість Джессена — Заспокійливий Черепаховий Суп: цього рецепта він навчить кухарів, які допоможуть йому добути м'ясо хапозубів.",al={"страва джессена незвичайна","торговець їжею джессен"}}},fp="11,252,20.595.0,19.182.0,34.194.0,44.219.0,39.174.0"}
P.entries["npc:chief-archaeologist-greywhisker"] = {n="Головний Археолог Ґрейвіскер",s="Головний Археолог Ґрейвіскер — посланець дворфійської Ліги Дослідників, що стоїть у Дарнасусі біля Храму Місяця. Його послали з Айронфорджа через море до північного Калімдору, щоб розкривати давню історію й керувати дворфійськими дослідженнями в цьому краї. Нині він заклопотаний тим, як зібрати звіти з розкопок і розшукати зниклих колег, що працюють на Темному Узбережжі.",h="Головний Археолог Ґрейвіскер — посланець дворфійської Ліги Дослідників, що стоїть у Дарнасусі біля Храму...",kw={"головний археолог ґрейвіскер","ліга дослідників","храм місяця","дарнасус","темне узбережжя","розкопки","археологія"},ang={["faction:Alliance"]="Він — важливий місток, науковий і господарський, між Лігою Дослідників з Айронфорджа та експедиціями на півночі Калімдору.",["race:Dwarf"]="Один із провідних учених Айронфорджа біля Храму Місяця — втішне нагадування про безмежну спрагу вашого народу розкривати давню історію, навіть у далеких закутках Калімдору.",["race:NightElf"]="Ґрейвіскер уособлює новий союз між вашим народом і Східними Королівствами: біля храму Елуни він шанобливо радиться з ученими про минуле континенту."},sec={{t="Дворфійський учений у Дарнасусі",b="Дворф з Айронфорджа високо серед гілля Тельдрассилу — видовище незвичне, але Головний Археолог Ґрейвіскер уособлює далекосяжні задуми Ліги Дослідників. Проміняв лекційні зали й музейні сховища Айронфорджа на польову роботу в Калімдорі, він стоїть біля Храму Місяця в Дарнасусі й радиться з місцевими вченими нічних ельфів, як-от Тарелвіром. Лекції Ґрейвіскера у Східних Королівствах славилися тим, що торкалися давніх переказів і первісних сутностей на кшталт Дикого Бога Аґамаґґана, і тепер йому кортить побачити, які давні таємниці приховують споконвічні землі нічних ельфів."},{t="Погляд на Темне Узбережжя",b="Головна справа Ґрейвіскера в Калімдорі — наглядати за дворфійськими розкопками й стежити за експедиціями, що прочісують давні руїни вздовж узбережжя. На жаль для головного археолога, дослідження в незвіданих землях мають свої небезпеки. Він покладається на мандрівників, щоб налагодити зв'язок зі шукачами, які працюють за морем, на Темному Узбережжі, і з тривогою чекає вістей із розкопок, сподіваючись, що його колеги не стали жертвами небезпек, які чатують серед давніх руїн."}},faq={{q="Хто такий Головний Археолог Ґрейвіскер?",a="Він видатний дворф-учений і представник Ліги Дослідників з Айронфорджа. Стоячи біля Храму Місяця в Дарнасусі, він координує дослідження Ліги на півночі Калімдору й підтримує зв'язок з ученими нічних ельфів.",al={"хто такий ґрейвіскер","лор ґрейвіскера","головний археолог"}},{q="Що дворф з Айронфорджа робить у Дарнасусі?",a="Ліга Дослідників розіслала дослідників по всьому Азероту, щоб розкрити забуту історію й давні артефакти. Ґрейвіскера послали за море, щоб налагодити наукові зв'язки в столиці нічних ельфів і наглядати за дворфськими експедиціями, що досліджують давні узбережжя Калімдору.",al={"чому дворф у дарнасусі","дворф храм місяця"}},{q="Що пов'язує його з Аґамаґґаном?",a="В Айронфорджі Ґрейвіскер був відомий своїми лекціями з давньої історії. Серед іншого він розповідав про велетенського вепра, Дикого Бога Аґамаґґана, чия легенда надихнула молодших дворфів-рудошукачів, як-от Лоунброу, вивчати давні перекази про звірів.",al={"ґрейвіскер аґамаґґан","лекції про аґамаґґана"}},{q="З ким Ґрейвіскер розмовляє біля храму?",a="Ґрейвіскер стоїть у Дарнасусі й розмовляє з Тарелвіром, ученим із нічних ельфів біля Храму Місяця: вони обмінюються думками й координують історичні дослідження двох народів.",al={"ґрейвіскер тарелвір","хто з ґрейвіскером"}},{q="З якою бідою він має справу на Темному Узбережжі?",a="Ґрейвіскер відрядив на Темне Узбережжя інших дворфів-дослідників розкопувати давні руїни, але підтримувати зв'язок із віддаленими експедиціями виявилося важко. Він часто шукає гінців, щоб навідатися до неуважних розвідників і повернути їхні дослідницькі щоденники.",al={"ґрейвіскер темне узбережжя","рудознавці темного узбережжя"}},{q="До якої фракції належить Ґрейвіскер?",a="Ґрейвіскер належить до Ліги Дослідників — археологічної організації Айронфорджа, що розкриває походження дворфів і давню історію та повністю підтримує Альянс.",al={"фракція ґрейвіскера","ліга дослідників дарнасус"}}},fp="31,400,30.641.0,17.488.0,39.245.0,46.286.0,36.261.0,49.184.0,45.273.0,41.179.0"}
P.entries["npc:chief-engineer-hinderweir-vii"] = {n="Головний Інженер Гіндервір VII",s="Головний Інженер Гіндервір VII — досвідчений дворф-інженер, що несе службу на вершині Каменетесної Греблі в Лох Модані. Йому доручено утримувати й обороняти цю монументальну інженерну споруду: він наглядає за її делікатними механізмами й пильнує, щоб не сталося диверсії. Кожен, хто з ним заговорить, швидко дізнається, що цілості великої греблі загрожує серйозна небезпека.",h="Головний Інженер Гіндервір VII — досвідчений дворф-інженер, що несе службу на вершині Каменетесної Греблі в...",kw={"гіндервір","головний інженер","каменетесна гребля","лох модан","диверсія","дворфи"},ang={["faction:Alliance"]="Альянс не може дозволити греблі впасти: катастрофічний прорив зірвав би шляхи постачання й спустошив союзні землі на північ від Лох Модану.",["profession:Engineering"]="Інженери оцінять сам механічний розмах споруди, яку доглядає Гіндервір: Каменетесна Гребля — неперевершене поєднання будівельного мистецтва й механічного керування.",["race:Dwarf"]="Для дворфів Гіндервір уособлює урочистий обов'язок берегти найвеличніші кам'яні творіння Каз Модану від чужої злоби."},sec={{t="Господар греблі",b="Каменетесна Гребля — одне з найвищих досягнень дворфійського каменярства й інженерії: вона стримує величезні води Лоху. На Головному Інженерові Гіндервірі VII лежить величезна відповідальність за її споруду й робочі механізми. Влаштувавшись на гребені греблі, він стежить за водотоками, шлюзами й вразливими місцями конструкції, оберігаючи їх від стихії та місцевих небезпек."},{t="Диверсії й підступи",b="Керувати греблею — це не лише буденне обслуговування: темні сили раз у раз випробовують її оборону. Гіндервір натрапляє на ознаки ретельно спланованої диверсії, яку влаштовують ворожі сили краю. Розуміючи, що катастрофічний прорив затопить низини й завдасть нищівного удару по вразливому господарству Каз Модану, Головний Інженер залучає надійних шукачів пригод з Альянсу, щоб вистежити змовників, знешкодити приховану вибухівку й усунути загрозу, поки камінь іще тримається."}},faq={{q="Хто такий Головний Інженер Гіндервір VII?",a="Головний Інженер Гіндервір VII — дворф-наглядач, що відповідає за обслуговування й оборону Каменетесної Греблі на півночі Лох Модану.",al={"гіндервір","головний інженер","інженер греблі"}},{q="Де знайти Головного Інженера Гіндервіра VII?",a="Він стоїть на верхньому переході Каменетесної Греблі, що тягнеться вздовж північного краю Лох Модану біля кордону з Багнокраєм.",al={"місце гіндервіра","де гіндервір","знайти гіндервіра"}},{q="Що таке Каменетесна Гребля?",a="Каменетесна Гребля — величне диво дворфського будівництва, що стримує води Лох Модану й не дає озеру бурхливо вихлюпнутися в низинні болота на півночі.",al={"що таке гребля","призначення каменетесної греблі","чому гребля важлива"}},{q="Які загрози непокоять Гіндервіра?",a="Гіндервір розслідує диверсії проти греблі й знаходить сліди темних змов і вибухових пристроїв, закладених, щоб розколоти її підвалини.",al={"загрози греблі","темна загроза насувається","хто хоче знищити греблю"}},{q="Чому в його імені є «VII»?",a="VII — це сім, записане римськими цифрами. Чому воно стоїть в імені Гіндервіра, ніде не записано.",al={"ім'я гіндервіра","чому сьомий","значення сьомого в імені"}},{q="Які завдання дає Головний Інженер Гіндервір?",a="Він дає ланцюжок завдань «Нависає темна загроза», що посилає шукачів пригод розслідувати диверсії й уберегти Каменетесну Греблю від руйнування.",al={"завдання гіндервіра","завдання на греблі","завдання темна загроза насувається"}}},fp="29,357,17.405.0,23.461.1,37.139.0,47.148.0,29.186.0,41.147.0,32.93.0,49.150.0"}
P.entries["npc:chief-hawkwind"] = {n="Вождь Гоквінд",s="Вождь Гоквінд — племінний ватажок Табору Нарачі, місця випробувань, що сховалося на Плато Червоної Хмари в Малгорі. Він наставляє молодь Шу'хало й веде новачків-шукачів пригод через традиційні обряди посвяти. Під його пильним оком юні сміливці вчаться смирення, поваги до землі та сили, потрібної, щоб захищати свій народ.",h="Вождь Гоквінд — племінний ватажок Табору Нарачі, місця випробувань, що сховалося на Плато Червоної Хмари в...",kw={"гоквінд","вождь","табір нарачі","плато червоної хмари","малгор","таурени","обряди"},ang={["faction:Horde"]="Наука Гоквінда дбає, щоб нові покоління тауренських сміливців ставали не лише вправними воїнами й заклиначами, а й непохитними та шляхетними союзниками молодої Орди.",["race:Tauren"]="Перший вождь, що веде вас у дорогу, Вождь Гоквінд закладає основи цінностей Шу'хало: шану до Земної Матері, вірність племені та смирення в силі."},sec={{t="Вождь плато",b="Стоячи в серці Табору Нарачі, Вождь Гоквінд несе урочистий обов'язок — готувати нове покоління тауренів до великого світу. Плато Червоної Хмари править за затишний прихисток, де мисливці, шамани, друїди й воїни-початківці проходять прадавні Обряди Земної Матері. Гоквінд наглядає за цими звичаями й дбає, щоб кожен юнак пізнав обов'язок і витривалість, перш ніж ступити за безпечні межі плато."},{t="Провідник обрядів",b="Уроки Гоквінда починаються зі смирення, а не з бойової слави. Він посилає посвячуваних на прості доручення — скажімо, принести чистої джерельної води, — щоб прищепити шану до природи та старших. Лише довівши смиренність серця, сміливці переходять до випробувань бойової майстерності, а вінчають їх сутички з войовничими шипогривами племені Щетиноспинних, які зазіхають на прабатьківські рівнини."},{t="Оборона Табору Нарачі",b="Окрім ролі наставника, Вождь Гоквінд мусить давати раду небезпекам, що зростають просто на порозі його табору. Плем'я Щетиноспинних дедалі зухваліше напирає на околиці Плато Червоної Хмари. Гоквінд керує обороною поселення й доручає щойно випробуваним сміливцям стримувати наскоки шипогривів, аби священні землі навчання лишалися в безпеці."}},faq={{q="Хто такий Вождь Гоквінд?",a="Вождь Гоквінд — вождь Табору Нарачі на Плато Червоної Хмари. Він опікується племінними справами в краї й наставляє молодих тауренів, що готуються зробити перші кроки в широкий світ Малгору й Калімдору.",al={"гоквінд","лор вождя гоквінда","хто вождь у таборі нарачі"}},{q="Що таке Обряди Земної Матері?",a="Обряди Земної Матері — традиційна низка священних випробувань для молодих тауренів, що досягають повноліття. Під проводом старійшин на кшталт Вождя Гоквінда ці обряди перевіряють смирення, силу, відвагу й духовний зв'язок із землею та предками.",al={"обряди тауренів","обряди земної матері","що таке обряди"}},{q="Чому Вождь Гоквінд спершу посилає вас по воду?",a="Гоквінд дає «Скромне доручення», щоб нагадати молодим сміливцям: служіння й повага до громади важать не менше, ніж бойова сила. Носячи свіжу воду для старійшин племені, новачки вчаться терпіння й смирення, перш ніж їх пошлють у бій.",al={"скромне завдання","чому спершу по воду","завдання води гоквінда"}},{q="Яка загроза нависла над Табором Нарачі?",a="На Табір Нарачі постійно тиснуть ворожі шипогриви-Щетиноспини, що живуть на довколишніх пагорбах Плато Червоної Хмари. Вождь Гоквінд мусить організувати оборону плато й посилає новачків прорідити ряди шипогривів.",al={"загрози нарачі","хто нападає на табір нарачі","квілборги табір нарачі"}},{q="Куди Вождь Гоквінд посилає шукачів пригод далі?",a="Коли молодий сміливець завершить перші обряди на плато, Вождь Гоквінд посилає його вниз, у розлогі долини Малгору, до Села Бладгуф, щоб продовжити випробування під проводом старійшин Кайрна Бладгуфа.",al={"куди йти після гоквінда","після табору нарачі","залишити червону хмарну мезу"}},{q="Чи родич Вождь Гоквінд Праматері Гоквінд?",a="Так, Прамати Гоквінд — його мати. Родина Гоквіндів здавна має глибоке коріння й обіймає провідні ролі серед тауренів, що живуть на Плато Червоної Хмари.",al={"родич праматері гоквінд","родина гоквінда","хто така праматір гоквінд"}}},fp="14,371,21.430.0,17.420.0,22.380.0,22.222.0,38.252.0,51.241.0,35.227.0,48.247.0,50.151.0"}
P.entries["npc:christoph-jeffcoat"] = {n="Крістоф Джеффкоут",s="Крістоф Джеффкоут — крамар-Відступник, що торгує в поселенні Таррен Мілл у Передгір'ї Гілсбреда. Він постачає місцевим ремісникам і мандрівникам потрібні товари, приправи для кухні й особливі рецепти. У зоні бойових дій, за яку змагаються Альянс і Синдикат, його буденний крам підтримує військові зусилля Орди на півночі.",h="Крістоф Джеффкоут — крамар-Відступник, що торгує в поселенні Таррен Мілл у Передгір'ї Гілсбреда.",kw={"крістоф джеффкоут","крамар","таррен мілл","заспокійливі прянощі","передгір'я гілсбреда","кулінарія"},ang={["faction:Horde"]="Для поборників Орди, що воюють у Передгір'ї Гілсбреда, Джеффкоут — незамінне джерело ремісничих матеріалів і звичайних інструментів просто в серці Таррен Мілла.",["profession:Cooking"]="Крістоф Джеффкоут — обов'язкова зупинка для кухарів-початківців у Гілсбреді: у нього є Заспокійливі Прянощі, потрібні, щоб приготувати Заспокійливий Черепаховий Суп за рецептом Шеф-кухаря Джессена."},sec={{t="Крамар на передовій",b="Таррен Мілл — військова твердиня Відступників у Передгір'ї Гілсбреда, але гарнізон не може воювати самою лише злобою. Крістоф Джеффкоут опікується тихим, практичним боком окупації: продає солдатам і мандрівним ремісникам складники, інструменти, нитки й прянощі. Від заспокійливих прянощів для місцевих рецептів, як-от черепахового супу, до рідкісних креслень і алхімічних флаконів — Джеффкоут дбає, щоб сили Орди, які проходять південним Лордероном, мали все потрібне для боїв проти Саутшора й місцевих небезпек."}},faq={{q="Де знайти Крістофа Джеффкоута?",a="Крістоф Джеффкоут живе в Таррен Міллі — головній твердині Відступників і Орди в центрі Передгір'я Гілсбреда.",al={"місце джеффкоута","де джеффкоут","торговець таррен мілла"}},{q="Які товари він продає?",a="Він торгує ремісничими припасами: кравецькими нитками, ковальськими молотами, флюсами, колбами для алхімії та кулінарними прянощами, як-от заспокійливі й гострі прянощі, а також кількома особливими рецептами.",al={"що продає джеффкоут","товари крістофа джеффкоута","предмети джеффкоута"}},{q="Чому він важливий для місцевих кухарів?",a="Джеффкоут продає Заспокійливі Прянощі — інгредієнт Заспокійливого Черепахового Супу, — а ще сам навчає кухарів Орди варити цей суп, коли ті приносять йому м'ясо черепах-хапозубів.",al={"торговець заспокійливих спецій гілсбред","інгредієнти заспокійливого черепашачого бісквіту","кулінарія джеффкоута"}}},fp="18,357,29.549.0,36.124.0,33.205.0,36.169.0"}
P.entries["npc:chronormu"] = {n="Хронорму",s="Хронорму, яку смертні знають як Хромі, — бронзова драконка в подобі жвавої гномки. Їй доручено берегти плин часу в Азероті, і вона часто працює пліч-о-пліч зі смертними, а не спостерігає здалеку. У Західних Чумних Землях вона тихо втручається в трагічні наслідки Третьої війни, щоб виправити порушені нитки часу.",h="Хронорму, яку смертні знають як Хромі, — бронзова драконка в подобі жвавої гномки.",kw={"хронорму","хромі","бронзові дракони","ноздорму","час","західні чумні землі","андоргал"},ang={["class:Mage"]="Магам, які вивчають тайну дисципліну хрономантії, недбала легкість, з якою Хронорму керує часом і творить місцеві часові кишені, здасться водночас захопливою і приголомшливою за масштабом.",["race:Gnome"]="Хронорму свідомо обрала подобу гнома, бо захоплювалася невичерпним оптимізмом, винахідливістю й скромністю цього народу серед вищих на зріст рас."},sec={{t="Драконка в малій подобі",b="Хоча смертним вона являється дивакуватою й життєрадісною гномкою на ім'я Хромі, Хронорму належить до бронзового роду драконів і служить Позачасному — Ноздорму. Титани доручили бронзовим драконам охороняти історію й виправляти збої на шляхах часу. Обираючи собі смертну подобу, Хронорму радилася з драконами різних родів, зокрема з Калекґосом із синього роду та Оніксією з чорного. Зрештою, відкинувши думки про силу й панування, вона обрала вигляд гномки, щоб ходити поруч зі смертними як привітна, оптимістична рівня."},{t="Вартова Чумних Земель",b="Хронорму оселилася серед руїн Лордерону й особливо пильно стежить за спустошеними Західними Чумними Землями. Катастрофічне падіння королівства й поширення Погибелі глибоко поранили історію краю, лишивши по собі часові аномалії та рештки минулого, замкнені в часі. Діючи непомітно з таких місць, як руїни Андоргала, вона залучає смертних шукачів пригод, щоб ті розплутували сплутані часові лінії й розслідували збурення, — і без потреби не розкриває всієї грізної величі драконячого роду."}},faq={{q="Чи справді Хромі — гномка?",a="Ні. Хромі — лише смертна личина Хронорму, бронзового дракона. Бронзові дракони приймають смертні подоби, щоб ходити серед молодших рас, не викликаючи зайвого жаху чи підозри.",al={"чи хромі гномка","справжня форма хромі","хто така хромі"}},{q="Чому в Хронорму чоловіче драконяче ім'я?",a="Серед бронзових драконів імена із закінченням «-ормі» зазвичай дають самицям, а з «-орму» — самцям. Хронорму народилася самцем, але під час обряду Дня Личини обрала для себе подобу гномки й пояснила просто: ця подоба їй пасує.",al={"стать хронорму","чому хромі зветься хронорму","стать хромі"}},{q="Що Хромі робить у Західних Чумних Землях?",a="Спустошення, якого Погибель завдала Лордерону, серйозно порушило історію та шляхи часу. Хромі перебуває серед руїн, щоб розслідувати часові аномалії, виправляти порушення в історії й залучати надійних шукачів пригод латати пошкоджені нитки часу.",al={"що хромі тут робить","чому хромі в андорхалі","хромі західні чумні землі"}},{q="Хто такі бронзові дракони?",a="Бронзовий драконячий рід, який очолює Аспект драконів Ноздорму, отримав від титанів дар мандрувати шляхами часу й оберігати їх. Вони дбають, щоб історія йшла так, як належить, і втручаються, коли час змінено чи зіпсовано.",al={"бронзові дракони","що таке бронзовий виводок","виводок нозздорму"}}},fp="9,360,23.592.0,26.516.0,26.180.0,43.298.0,49.274.0,32.245.0"}
P.entries["npc:clarice-foster"] = {n="Кларіс Фостер",s="Кларіс Фостер — жінка з-поміж Відступників, що живе глибоко під кручами Малгору, в Ставках Видінь. Далеко від зачумлених галявин Лордерона вона проводить дні в роздумах серед тауренських провидців і містиків.",h="Кларіс Фостер — жінка з-поміж Відступників, що живе глибоко під кручами Малгору, в Ставках Видінь.",kw={"кларіс фостер","відступники","озерця видінь","тандер блаф","малгор","таурени"},ang={["race:Tauren"]="Прийнята до священних Ставків Видінь під Узвишшям Духів, Кларіс Фостер показує, що таурени готові дати притулок незвичним новачкам Орди.",["race:Undead"]="Кларіс Фостер уособлює зв'язки Відступників із союзниками-тауренами в Калімдорі — вона спочиває далеко від сплюндрованої скверною землі Тірісфалю й Срібнолісся."},sec={{t="Відступниця в Ставках Видінь",b="Більшість Відступників лишається на північних землях Лордерона, відбудовуючи своє королівство під Андерсіті, а от Кларіс Фостер вирушила в серце тауренських земель у Калімдорі. У печерних Ставках Видінь під столовою горою Тандер Блафа вона живе поруч з аптекарями-Відступниками й тауренськими шаманами, що вивчають духовні та стихійні таємниці землі."}},faq={{q="Хто така Кларіс Фостер?",a="Кларіс Фостер — жінка-Відступниця, що перебуває в підземних Ставках Видінь під Тандер Блафом. Вона одна з небагатьох посланців і гостей із нежиті, що живуть серед тауренів Малгору.",al={"хто така кларіс","кларіс фостер нпс","історія кларіс фостер"}},{q="Де знайти Кларіс Фостер?",a="Вона перебуває в Ставках Видінь — печерному комплексі під Узвишшям Духів у Тандер Блафі.",al={"місце кларіс фостер","де кларіс фостер","знайти кларіс фостер"}},{q="Які завдання вона дає?",a="Вона дає завдання «Доки смерть не розлучить нас», посилаючи мандрівників у справах, що пов'язують її тихий пост у Калімдорі з ширшими справами Відступників.",al={"завдання кларіс","завдання поки смерть не розлучить"}}},fp="14,221,33.387.0,22.186.0,32.104.0,27.160.0"}
P.entries["npc:clerk-daltry"] = {n="Писар Долтрі",s="Писар Долтрі — міський архіваріус у Ратуші Даркшира в Сутінколіссі. Оточений книгами обліку й реєстрами, він допомагає розкривати минуле містечка й розшукувати давні записи, хоч його архів і доволі занедбаний та застарілий.",h="Писар Долтрі — міський архіваріус у Ратуші Даркшира в Сутінколіссі.",kw={"писар долтрі","ратуша даркшира","архів","сталван містмантл","даркшир","сутінколісся"},ang={["faction:Alliance"]="Для слідчих Альянсу, що розкривають зловісні таємниці Сутінколісся, Писар Долтрі — незамінний зв'язок у міській управі, коли потрібні давно загублені записи й нерозкриті справи.",["race:Human"]="Долтрі зберігає те, що лишилося від історичної спадщини Великого Селища, — з часів, коли на цей лісовий край ще не впала темрява."},sec={{t="Літописець міста",b="Поки Даркшир бореться з навалою звірів, жахами нежиті й надприродним мороком, буденні міські справи лягають на плечі Писаря Долтрі. Працюючи в Ратуші Даркшира разом із Лордом Елло Ебонлоком і місцевою радою, Долтрі веде історичні книги міста, реєстри майна й переписи. У краї, розколотому лихом, його записи — одна з небагатьох уцілілих ниток, що тягнуться до часів, коли Велике Селище ще не поринув у тінь."},{t="Паперовий слід",b="Даркшир відрізаний від звичного урядування Стормвінда, тож облік Долтрі відомий своєю недосконалістю. Старі документи зникають, книги обліку відстають, а важливі міські справи раз у раз губляться чи псуються. Шукачі пригод, що розплутують давні нерозкриті справи чи шукають давно зниклих мешканців, часто звертаються до нього — лише щоб дізнатися, що правду доведеться шукати в забутих записках або навіть вирушати в небезпечний ліс по загублені папери."},{t="Легенда про Сталвана",b="Долтрі відіграє головну роль у розплутуванні похмурої таємниці Сталвана Містмантла. Коли зловісна родинна легенда приводить шукачів назад до Даркшира, Долтрі перебирає свої архіви в пошуках записів про колишнього вчителя. Записи про Сталвана в міському реєстрі уривчасті, тож Долтрі доводиться відсилати шукачів через усе місто й до забутих садиб по всьому королівству, щоб скласти докупи трагічну й криваву правду."}},faq={{q="Де перебуває Писар Долтрі?",a="Писар Долтрі перебуває в Ратуші Даркшира в центрі містечка Даркшир у Сутінколіссі. Він стоїть серед міських урядовців і членів ради й веде міські записи.",al={"місце долтрі","де долтрі","місце клерка даркшира"}},{q="Яка робота Писаря Долтрі в Даркширі?",a="Він міський писар Даркширу: зберігає документи, списки мешканців і правові реєстри. Він допомагає шукачам пригод, яким потрібні архівні відомості про колишніх мешканців, земельні права чи історичні питання.",al={"що робить долтрі","роль долтрі","хто писар долтрі"}},{q="Чому його записи неповні?",a="Сутінколісся роками терпіло відрізаність, магічну скверну й жорстокі негаразди. Коли все містечко зосереджене на тому, щоб вижити, відбиваючись від ворогів Нічної Варти, на впорядкування книг часто не лишається сил, тож його архіви уривчасті.",al={"чому записи долтрі погані","застарілі записи сутінколісся","зниклі книги долтрі"}},{q="Які ланцюжки завдань починає Писар Долтрі чи в яких бере участь?",a="Долтрі — ключова постать у сюжеті «Легенда про Сталвана»: він допомагає гравцям простежити загадкове минуле Сталвана Містмантла. Він також допомагає в розслідуваннях на кшталт «Родина Каревінів» і «Тіньові пошуки тривають».",al={"завдання долтрі","які завдання від долтрі","ланцюжок завдань писаря долтрі"}},{q="Чи родич Писар Долтрі Землемірові Долтрі?",a="Через спільне прізвище й схожу службу їх загалом вважають родичами, хоча Писар Долтрі цілком зосереджений на своїх міських обов'язках у Даркширі.",al={"родич землеміра долтрі","родина долтрі"}},{q="Чи можуть гравці Орди поговорити з Писарем Долтрі?",a="Ні. Писар Долтрі — міський службовець Альянсу. Даркшир і його ратушу стереже Нічна Варта, і до всіх шукачів пригод з Орди тут ставляться вороже.",al={"чи долтрі дружній до орди","чи може орда говорити з долтрі"}}},fp="12,263,18.441.0,15.465.0,21.414.1,30.199.0,40.224.0,31.267.0,58.232.0,43.172.0,42.158.0"}
P.entries["npc:cliffwatcher-longhorn"] = {n="Скельний Вартовий Лонггорн",s="Скельний Вартовий Лонггорн — незворушний тауренський ватажок, що несе варту високо на Заставі Вільного Вітру в Тисячі Голок. Йому доручено оберігати відрізану від світу заставу Орди: він організовує оборону від кентаврів Ґалак, що підступають, і стежить за підозрілими інтригами племені Ґрімтотем.",h="Скельний Вартовий Лонггорн — незворушний тауренський ватажок, що несе варту високо на Заставі Вільного Вітру...",kw={"лонггорн","застава вільного вітру","тисяча голок","кентаври ґалак","ґрімтотем","таурени"},ang={["faction:Horde"]="Застава Вільного Вітру — важлива ланка, що тримає шляхи постачання через південний Калімдор, і Лонггорн дбає, щоб Орда втримала свою хитку опору посеред ворожих земель кентаврів.",["race:Tauren"]="Для тауренів-мандрівників Лонггорн уособлює прикордонний дух шу'гало: він пильнує спірні священні столові гори, водночас лавіруючи в гіркій, досі не розв'язаній ворожнечі з племенем Ґрімтотем."},sec={{t="Охоронець столових гір",b="Застава Вільного Вітру, що височіє на кам'яних шпилях Тисячі Голок, виживає завдяки пильним очам і твердій руці. Скельний Вартовий Лонггорн щодня дбає про безпеку цього хиткого поселення. Унизу, на дні каньйону, і на сусідніх гребенях збираються ворожі сили, тож саме Лонггорн зводить докупи донесення розвідників і керує обороною."},{t="Ворожнеча кентаврів та інтриги Ґрімтотем",b="Лонггорнові доводиться протистояти загрозам з кількох боків. Унизу, в каньйоні, агресивні кентаври Ґалак раз у раз прощупують периметр, тож він посилає шукачів пригод відкинути їх і проріджувати їхні лави. Та ще більше його тривожать таурени Ґрімтотем. Лонггорн глибоко не довіряє їхньому потаємному табору біля застави й організовує розвідку, щоб викрасти їхні таємні записи, — і так викриває тривожні докази зради всередині племені, зокрема жорстокі злочини Арнака Ґрімтотема."}},faq={{q="Хто такий Скельний Вартовий Лонггорн?",a="Скельний Вартовий Лонггорн — таурен-командир Застави Вільного Вітру, високої застави Орди в Тисячі Голок. Він організовує розвідників, оборонні патрулі й відсіч місцевим загрозам.",al={"інфо про лонггорна","хто такий лонггорн","вождь застави вільного вітру"}},{q="Де знайти Скельного Вартового Лонггорна?",a="Він перебуває на вершині головної столової гори Застави Вільного Вітру в Тисячі Голок: туди можна піднятися підйомником із дна каньйону й перейти дерев'яними мостами.",al={"місце лонггорна","де лонггорн"}},{q="Чому Лонггорн непокоїться через кентаврів?",a="Донесення розвідників, як-от Сміливця Мунгорна, свідчать про тривожне посилення ворожості кентаврів Ґалак. Лонггорн наказує завдавати випереджальних ударів, щоб приборкати клан і не дати йому заполонити підступи до застави.",al={"чому вбивати кентаврів","лор умиротворення кентаврів","загроза кентаврів тисячі голок"}},{q="Чим його цікавить клан Ґрімтотем?",a="Хоч формально клан Ґрімтотем живе серед Орди, він поводиться відверто потайливо й зловмисно. Лонггорн підозрює недобре й доручає шукачам пригод викрасти їхні приховані записи, щоб з'ясувати, що вони замишляють.",al={"лонггорн ґрімтотем","причина шпигунства ґрімтотемів"}},{q="Хто такий Арнак Ґрімтотем і навіщо він Лонггорнові?",a="Арнак Ґрімтотем жорстоко напав на мешканців застави. Лонггорн призначає нагороду за його голову, щоб Арнак відповів за свою зраду.",al={"розшук арнака ґрімтотема","лор нагороди за арнака"}},{q="Чи має Скельний Вартовий Лонггорн родину?",a="Так, його брат Натака Лонггорн служить далеко на заході, на Заставі Духоходів у Пустограї. Поглинутий обов'язками, Скельний Вартовий рідко знаходить нагоду йому написати.",al={"брат лонггорна","брат натака лонггорна"}}},fp="21,279,21.405.0,40.498.1,29.201.0,39.158.0,44.213.0,44.218.0,54.162.0,43.174.0"}
P.entries["npc:coleman-farthing"] = {n="Коулмен Фартінґ",s="Коулмен Фартінґ — озлоблений уцілілий з-поміж Відступників, що мешкає в Таверні «Шибеничний Кінець» у Бріллі. За життя він працював на заможну династію Аґамандів на їхніх великих борошняних млинах у північному Тірісфалі. Умовлений лишитися й боронити маєток від Погибелі, він загинув разом із товаришами-робітниками, а тепер присвячує своє нежиття помсті колишнім господарям.",h="Коулмен Фартінґ — озлоблений уцілілий з-поміж Відступників, що мешкає в Таверні «Шибеничний Кінець» у Бріллі.",kw={"коулмен фартінґ","помста","аґаманди","млини аґаманда","таверна шибеничний кінець","брілл","відступники"},ang={["class:Warrior"]="Коулмен указує майбутнім воїнам просто на Родинний Склеп Аґамандів і закликає їх пограбувати бойові реліквії занепалого аристократичного дому, щоб озброїтися для прийдешніх війн.",["race:Undead"]="Для Відступників Коулмен утілює спільну образу, яку чимало простолюду плекає до старого дворянства Лордерона, чия зарозумілість і гордість нерідко прискорювали загибель їхніх підданих під час чуми."},sec={{t="Озлоблений слуга",b="До Третьої війни Коулмен Фартінґ чесно заробляв на життя робітником на Млинах Аґаманда — найбільшому млинарському й сільському господарстві Галявин Тірісфалю. Коли Погибель ринула на Лордерон, аристократична родина Аґамандів відмовилася тікати зі своїх цінних земель. Натомість вони закликали челядь і робітників узятися за зброю разом із ними, обіцяючи, що хутори вдасться втримати проти орди нежиті. Коулмен і його товариші лишилися, повіривши господарям, — і це рішення коштувало життя кожному з них."},{t="Помста з могили",b="Воскреслий нежиттю лише для того, щоб вирватися на волю під прапором Відступників, Коулмен палає ненавистю до Аґамандів. Він звинувачує не тільки Погибель, а й відверту пиху та жадібність своїх наймачів, що обманом втягнули челядь у безнадійний останній бій. Тепер, тиняючись у таверні Брілла, Коулмен залучає звитяжців Орди, щоб ті вирушили до заражених млинів, порубали воскреслих родичів Аґамандів і розтрощили родинні реліквії в їхньому склепі, аби їхню спадщину було стерто дощенту."}},faq={{q="Де знайти Коулмена Фартінґа?",a="Коулмен Фартінґ днює в Таверні «Шибеничний Кінець» у Бріллі, у центрі Галявин Тірісфалю.",al={"місце коулмена фартінґа","де коулмен фартінґ","коулмен фартінґ брилл"}},{q="Чому Коулмен так ненавидить родину Аґамандів?",a="Коли Погибель вдерлася до Лордерону, глави роду Аґамандів переконали своїх робітників, серед них і Коулмена, лишитися й захищати млини, а не тікати в безпечне місце. Через це всіх робітників перебили. Коулмен вважає їхній бойовий заклик пихатою маніпуляцією, що привела його просто до смерті.",al={"чому коулмен ненавидить аґамандів","мотивація коулмена фартінґа","образа млинів аґаманда"}},{q="Що сталося з Млинами Аґаманда?",a="Розлогий маєток цілком заполонила Погибель. Його вітряки стоять зруйновані й похмурі, а члени родини Аґамандів і їхні вбиті робітники блукають отруєними полями як бездумно ворожа нежить під владою Короля-Ліча.",al={"що сталося з млинами аґаманда","лор млинів аґаманда","хто володіє млинами аґаманда"}},{q="Які доручення Коулмен дає шукачам пригод?",a="Коулмен посилає шукачів пригод на північ, до Млинів Аґаманда, щоб прорідити мандрівну нежить, убити повсталих членів роду Аґамандів і забрати їхні рештки на наругу, а ще пограбувати Родинний Склеп Аґамандів, забравши родову зброю.",al={"завдання коулмена фартінґа","завдання аґаманд брилл"}},{q="Навіщо Коулменові родова зброя Аґамандів?",a="Для Коулмена родова зброя Аґамандів — символ тієї порожньої гордості, що привела його товаришів-робітників до смерті. Він посилає вправних воїнів поцупити ці реліквії з родинного склепу, щоб позбавити рід честі й обернути зброю на користь проти ворогів.",al={"лор реліквій аґаманд","навіщо красти зброю аґаманд"}},{q="Чи родич Коулмен Фартінґ Єпископові Фартінґу?",a="Вони мають спільне прізвище й походять із занепалого Королівства Лордерон, але підтверджених відомостей про їхню спорідненість немає.",al={"зв'язок з єпископом фартінґом","родина коулмена фартінґа"}}},fp="16,371,16.546.0,24.507.0,36.109.0,49.315.0,35.254.0,44.239.0,51.293.0,47.134.0"}
P.entries["npc:collin-mauren"] = {n="Коллін Маурен",s="Коллін Маурен — людина-маг, що живе в Кварталі магів Стормвінда. Учений-дослідник і творець заклинань, він експериментує з екзотичними природними реагентами, щоб вигадувати незвичні прикладні чари. Серед іншого він допомагає своєму знайомому, гномові-інженерові й досліднику Ґаксиму Растфіззлу, особливими чародійними сувоями.",h="Коллін Маурен — людина-маг, що живе в Кварталі магів Стормвінда.",kw={"коллін маурен","маг","квартал магів","заклинання","ґаксим растфіззл","василіски"},ang={["class:Mage"]="Коллін — взірець експериментального творення заклинань: він показує, як земні реагенти на кшталт уламків елементалів і луски василісків можна впрягти в прикладну магію.",["faction:Alliance"]="Коллін сприяє зв'язку й торгівлі в Альянсі, забезпечуючи шукачів пригод прикладною магією — від Вестфолу до Калімдору.",["race:Human"]="Тихо живучи в Кварталі магів Стормвінда, Коллін уособлює вчені пошуки людських чарівників, що вивчають широкий світ із серця столиці."},sec={{t="Знавець таємних мистецтв",b="Оселившись у гомінкому Кварталі магів Стормвінда, Коллін Маурен присвячує дні тихішим, практичнішим застосуванням магії. Замість гонитви за сирою силою стихій він створює чародійні формули, що розв'язують конкретні щоденні задачі. Коллін часто звертається до природних аномалій і сирих складників, зібраних по всьому Азероту, вплітаючи їхні властивості в робочі магічні сувої та реагенти для друзів і мандрівників."},{t="Допомога Ґаксиму Растфіззлу",b="Коллін підтримує тісне листування й дружбу з гномом-майстром Ґаксимом Растфіззлом. Коли Ґаксимові знадобився надійний спосіб спілкуватися на великих відстанях під час мандрів, Коллін розробив особливе заклинання для повідомлень. Щоб закріпити чари, він використовує вихрові уламки, що лишаються по непередбачуваних пилових вихорах Вестфолу: схоплена в них сутність мінливого вітру допомагає далеким посланням дістатися його непосидючого колеги."},{t="Екзотичні дослідження в Горах Кам'яного Кігтя",b="Окрім роботи з місцевими елементалями, дослідження Колліна сягають аж за Велике Море, до скель Калімдору. Його дивно зачарували міцні шкури василісків із Гір Кам'яного Кігтя, і він шукає їхню луску, щоб творити нові заклинання. Мандрівники, що вирушають до Калімдору, часто отримують від нього прохання добути ці рідкісні шкури, живлячи невгасну цікавість Колліна до того, як будова первісних істот може стабілізувати складні чари."}},faq={{q="Де знайти Колліна Маурена?",a="Коллін Маурен перебуває в Кварталі магів у Стормвінді, серед веж і крамниць, де бувають учені знавці тайної магії столиці.",al={"місце колліна маурена","де коллін маурен","коллін маурен стормвінд"}},{q="На якій магії спеціалізується Коллін?",a="Коллін спеціалізується на прикладних чарах і допоміжних закляттях. Замість бойових заклять він експериментує із сирими природними складниками — уламками елементалів і лускою звірів, — щоб створювати сувої для передавання повідомлень на великі відстані й особливі чари.",al={"дослідження колліна маурена","що робить коллін маурен","магія колліна маурена"}},{q="Хто такий Ґаксим Растфіззл і що пов'язує з ним Колліна?",a="Ґаксим Растфіззл — гном-майстер, любитель пригод і друг Колліна. Коллін підтримує далекі мандри Ґаксима, виготовляючи для нього особливі сувої зв'язку.",al={"друг ґаксім растфіззл","коллін і ґаксім","хто такий ґаксім растфіззл"}},{q="Навіщо Коллінові уламки елементалів із Вестфолу?",a="Коллін використовує сутність Пилових Демонів Вестфолу, щоб живити закляття передавання повідомлень. Вітряні уламки цих елементалів несуть гармонійну енергію, потрібну для надійних сувоїв зв'язку.",al={"завдання про демонів вестфолла","навіщо пилові демони","завдання пилових демонів вестфолла"}},{q="Чому Колліна цікавлять Гори Кам'яного Кігтя?",a="Коллін вивчає магічні властивості луски василісків, що водяться в Горах Кам'яного Кігтя в Калімдорі. Їхні міцні, від природи стійкі шкури правлять йому за основу реагентів для нових заклинань.",al={"василіски стоунталон","забір для маурена","луска стоунталон коллін"}},{q="Чи пов'язаний Коллін із Кірін-Тором?",a="Хоч Коллін і живе в Кварталі магів і дотримується традицій, звичних для чарівників Альянсу, він передусім незалежний дослідник і виготовлювач реагентів, а не діяльний представник Даларана.",al={"чи коллін кірін-тор","коллін маурен даларан","квартал магів коллін"}}},fp="13,339,21.458.0,23.439.0,28.460.0,33.142.0,45.245.0,59.174.0,52.200.0,53.201.0,37.218.0"}
P.entries["npc:colonel-kurzen"] = {n="Полковник Курзен",s="Полковник Конрад Курзен колись був шанованим, відзначеним нагородами офіцером армії Стормвінда; його послали на чолі експедиції в північну частину Долини Стренглторну. Раптово поринувши в безумство й тиранію, він обернув свій загін на ренегатське ополчення, що діє в джунглях з укріпленого поселення. Нині його колишні підлеглі з недалекого Табору Повстанців прагнуть його смерті, щоб покласти край його кривавому пануванню.",h="Полковник Конрад Курзен колись був шанованим, відзначеним нагородами офіцером армії Стормвінда; його послали...",kw={"полковник курзен","долина стренглторну","табір повстанців","май'зот","стормвінд","безумство"},ang={["class:Warrior"]="Курзен — застережливий приклад того, як дисциплінована бойова міць цілком перекручується й обертається на зло, коли в неї забирають волю й честь.",["faction:Alliance"]="Курзен — гучний військовий скандал і трагічна втрата військ Стормвінда, тож командування Альянсу й місцеві вірні присязі солдати дали дозвіл його знищити.",["race:Human"]="Для людей Стормвінда Курзен колись був рівнею й шанованим ватажком, тож його жорстоке падіння до ролі маріонетки огра — похмуре нагадування про небезпеки джунглів."},sec={{t="Падіння",b="До свого падіння полковник Конрад Курзен мав у Стормвінді славу надзвичайно здібного й шляхетного офіцера. Правителі королівства довіряли йому й доручили командувати експедиційним загоном, який відрядили на південь, у густі джунглі Долини Стренглторну. Проте глибоко серед вологих нетрів Курзен почав поводитися дивно й виявляти шалену манію величі: він проголосив свою необмежену владу над довколишніми дикими землями й зрікся вірності Стормвіндові."},{t="Повстання",b="Раптова переміна Курзена розколола його лави. Багато солдатів піддалися сліпій відданості чи викривленому фанатизму, але інших нажахали його безумство й жорстокість — зокрема те, що він кинув Емерін Джуніс до в'язниці поселення лише за те, що вона відкинула його залицяння. На чолі з Лейтенантом Дореном гурт солдатів, яким не дало спокою сумління, відколовся й заснував Табір Повстанців біля північного шляху. Ці вірні присязі перебіжчики тепер ведуть відчайдушну війну з Курзеном, щоб зупинити його розлючене військо."},{t="Огр за лаштунками",b="Безумство Курзена породила не тропічна гарячка й не звичайне виснаження. Полковник став жертвою темного чаклунства Май'Зота — хитрого огра-мага з клану Мош'Оґґ. Заволодівши розумом Курзена, Май'Зот обернув дисциплінований загін солдатів Стормвінда на жорстоких пішаків і керував Курзеном, щоб підкорити край, — і ограм не довелося самим вести відкриту війну."}},faq={{q="Чому Полковник Курзен обернувся проти Стормвінда?",a="Під час експедиції до Долини Стренглторну Курзен почав поводитися дивно, у ньому прокинулася манія величі, і він зрікся вірності Стормвінду. Що довело колись шляхетного полковника до безуму — загадка, яку його колишні солдати в Таборі Повстанців досі намагаються розгадати.",al={"чому курзен злий","що сталося з курзеном","історія курзена"}},{q="Де перебуває Полковник Курзен?",a="Він командує своїм ополченням із глибини Поселення Курзена на пагорбах півночі Долини Стренглторну. Сам він сидить в укріпленій будівлі Складу в глибині табору.",al={"де знайти курзена","місце курзена","комплекс полковника курзена"}},{q="Хто такі повстанці з Табору Повстанців?",a="Повстанці — колишні солдати Курзена, що відмовилися йти за ним у безум. Під проводом Лейтенанта Дорена вони лишаються вірними Стормвінду й діють із Табору Повстанців біля північного кордону, прагнучи покласти край свавільному війську Курзена.",al={"лор табору повстанців","хто лейтенант дорен","чому табір повстанців"}},{q="Хто така Емерін Джуніс?",a="Емерін Джуніс — жінка з експедиції, що відкинула небажані залицяння Курзена. Дедалі жорстокіший і засліпленіший, полковник замкнув її в тюремних клітках поселення.",al={"емерін джуніс","в'язень курзена"}},{q="Чи діє Курзен у джунглях сам?",a="Ні. Він командує найманцями-людьми, солдатами й бійцями джунглів, що лишилися йому вірними, коли повстанці відкололися й пішли до Табору Повстанців.",al={"на кого працює курзен","союзники курзена"}},{q="Що стається, якщо Полковника Курзена вбити?",a="Лейтенант Дорен просить шукачів пригод з Альянсу відрубати Курзенові голову, щоб остаточно довести смерть полковника, зламати командування його ополчення й урятувати честь армії Стормвінда.",al={"кінець завдання курзена","голова курзена дорен"}}},fp="14,386,17.474.0,13.497.0,27.387.2,46.275.2,32.195.0,37.261.0,21.190.0,37.141.2,40.194.1"}
P.entries["npc:commander-mar-alith"] = {n="Командир Мар'аліт",s="Командир Мар'аліт — непохитний воєначальник із нічних ельфів, що керує передовим загоном Кола Кенарія в Цитаделі Кенаріуса в Силітусі. Закутий у важкі обладунки, з великою глефою в руках, він очолює збройний опір роям силітидів і культистам Молота Присмерку. За його твердим проводом ховається глибокий особистий сум через загадкову долю коханої дружини Наталії.",h="Командир Мар'аліт — непохитний воєначальник із нічних ельфів, що керує передовим загоном Кола Кенарія в...",kw={"командир мар'аліт","цитадель кенаріуса","коло кенарія","силітиди","наталія","нічні ельфи"},ang={["class:Warrior"]="Закутий у важкі лати, з величезною глефою в руках, Мар'аліт веде справжню польову війну в поселенні, де живуть переважно містики й охоронці природи.",["race:NightElf"]="Мар'аліт уособлює відданість калдорейських вартових і воїнів, які пліч-о-пліч із друїдами боронять Калімдор від прадавніх загроз навіть ціною тяжких особистих утрат."},sec={{t="Командир Цитаделі",b="Командир Мар'аліт, що стоїть у самому серці Цитаделі Кенаріуса, несе величезну відповідальність за захист пустельного бастіону Кола. Поки друїди розгадують прадавні природні й космічні аномалії Силітусу, Мар'аліт бере на себе похмурі практичні потреби війни. Він керує прицільними ударами по кишучих вуликах силітидів — Вулик'Аші, Вулик'Зора й Вулик'Реґал, — щоб безупинні навали комах не захлеснули головну опору експедиції."},{t="Горе в пустелі",b="Попри сувору військову виправку, Мар'аліта помітно гнітить тяжке особисте горе. Його кохана дружина, Наталія Мар'аліт, вирушила в мінливі піски з дорученням від Кола й не повернулася. Розірваний між обов'язком перед експедицією Кола Кенарія та нестерпною тугою, командир дедалі більше втрачає зосередженість: він чіпляється за рештки надії й чекає хоч якоїсь звістки про те, що насправді спіткало її в пустелі."},{t="Трагічна доля",b="Жахлива правда про зникнення Наталії тяжким тягарем лягає на командира. Ті, хто йде її слідами, дізнаються, що вона піддалася божевіллю серед шепотів пустелі, а кристал кіражів підкорив її розум і віддав на службу К'Туну. Звістка про її трагічний кінець глибоко вражає Мар'аліта: командир мусить нести тягар розбитого серця й водночас далі керувати обороною Силітусу від жахіть, що чигають під землею."}},faq={{q="Хто такий Командир Мар'аліт?",a="Командир Мар'аліт — офіцер із нічних ельфів, верховний воєначальник сил Кола Кенарія в Цитаделі Кенаріуса. Він організовує розвідників, оборону й тактичні удари по вуликах силітидів по всьому Силітусу.",al={"мар'аліт","хто командир мар'аліт","нічний ельф командир силітус"}},{q="Де знайти Командира Мар'аліта?",a="Він перебуває в Цитаделі Кенаріуса — головному нейтральному поселенні, яке Коло Кенарія заснувало серед вітряних пісків Силітусу.",al={"місце мар'аліта","де мар'аліт"}},{q="Що сталося з його дружиною Наталією?",a="Наталія Мар'аліт зникла в пустелі під час експедиції й так і не повернулася. Шукачі пригод, що підуть її слідом через Силітус, можуть дізнатися, що з нею сталося.",al={"де наталія","дорога наталія","доля наталії мар'аліт"}},{q="Чому Мар'аліт здається неуважним?",a="Командира мучать скорбота й тривога через зникнення дружини та її долю, і це часто відволікає його, навіть коли він з усіх сил керує обороною фортеці.",al={"чому мар'аліт неуважний","мар'аліт поводиться дивно"}},{q="Які доручення Командир Мар'аліт дає шукачам пригод?",a="Мар'аліт дає бойові доручення: прорідити сили силітидів у Вулик'Аші, Вулик'Зорі й Вулик'Реґалі, протистояти Молоту Присмерку й розслідувати долю своєї зниклої дружини.",al={"завдання мар'аліта","які завдання дає мар'аліт"}},{q="Чи Командир Мар'аліт — друїд?",a="Ні. Хоч він і служить Колу Кенарія, Мар'аліт — закутий в обладунки вартовий і командир-воїн, що керує військовою обороною й тактичними операціями експедиції, а не користується друїдською магією.",al={"чи мар'аліт друїд","клас мар'аліта"}}},fp="19,402,21.489.0,19.443.0,13.455.1,27.236.0,39.137.0,35.163.1,38.186.0,58.197.0,31.204.0"}
P.entries["npc:commander-springvale"] = {n="Командир Спрінґвейл",s="Командир Спрінґвейл колись був відданим паладином і очільником збройної варти Барона Сільверлейна у Фортеці Шадовфенг. Він загинув разом зі своїми вояками під час різанини, яку влаштували дикі воргени, викликані Архімагом Аруґалом, і тепер його мстивий дух блукає залами замку. Навіть після смерті його привид люто стереже фортецю й прагне помститися за свого полеглого пана.",h="Командир Спрінґвейл колись був відданим паладином і очільником збройної варти Барона Сільверлейна у Фортеці...",kw={"командир спрінґвейл","паладин","привид","фортеця шадовфенг","барон сільверлейн"},ang={["class:Paladin"]="Спрінґвейл — тверезе нагадування про те, як обов'язок і святі обітниці можуть обернутися вічними муками, коли шляхетного лицаря прикуто до оскверненої могили.",["faction:Alliance"]="Спрінґвейл уособлює втрачених вояків Лордерона й Ґілнеаса — вірних захисників, що полягли не від самої Погибелі, а від безрозсудних викликів, які мали її зупинити.",["faction:Horde"]="Для Відступників, що відвойовують Срібнолісся, упокоєння тіні командира — ще один крок до того, щоб вичистити рештки трагічної помилки Аруґала."},sec={{t="Полеглий командир",b="До загибелі Фортеці Шадовфенг Командир Спрінґвейл був шляхетним паладином, відданим Святому Світлу, і присяжним захисником Барона Сільверлейна. Очолюючи гарнізон у Срібноліссі, він відповідав за безпеку фортеці в тривожні дні після того, як Лордерон упав під натиском Погибелі."},{t="Безумство Аруґала",b="Коли Архімаг Аруґал викликав воргенів з-за меж світу, щоб відбити нежить Погибелі, що наступала на ґілнеаську землю, дикі звірі швидко вийшли з-під його контролю. Ненажерлива зграя накинулася на фортецю, перебивши Барона Сільверлейна й усю його варту. Спрінґвейл загинув у залах, які присягався захищати, і його службу жорстоко обірвано."},{t="An Endless Vigil",b="Death offered no release to Springvale. His ghost haunts the keep's council room alongside its spectral soldiers. He still wields paladin powers, including Holy Light and Hammer of Justice, against intruders."}},faq={{q="Ким був Командир Спрінґвейл за життя?",a="Командир Спрінґвейл був паладином Святого Світла й командував збройними силами Барона Сільверлейна. Йому доручили обороняти Фортецю Шадовфенг, і він до самої смерті лишався палко відданим баронові.",al={"історія спрінґвейла","хто командир спрінґвейл","чи спрінґвейл паладин"}},{q="Як загинув Командир Спрінґвейл?",a="Він загинув, коли Архімаг Аруґал закликав лютих воргенів на боротьбу з Погибеллю. Неприборкані звірі накинулися на мешканців Фортеці Шадовфенг і вирізали Барона Сільверлейна, Спрінґвейла й гарнізон.",al={"як помер спрінґвейл","хто вбив спрінґвейла","смерть спрінґвейла"}},{q="Чому Командир Спрінґвейл блукає Фортецею Шадовфенг?",a="Спотворений смертю, його дух і досі скутий останніми обітницями. Привид Спрінґвейла блукає залами, щоб боронити руїни й мститися за свого полеглого володаря кожному, хто ввійде.",al={"чому спрінґвейл привид","мотив спрінґвейла","чому спрінґвейл б'ється"}},{q="What powers does Springvale use?",a="Springvale retains paladin abilities in undeath, healing with Holy Light and stunning enemies with Hammer of Justice.",al={"чому нечестива магія","нечестиві здібності спрінґвейла","зіпсований паладин"}},{q="Хто був його паном?",a="Командир Спрінґвейл служив Баронові Сільверлейну — шляхетному правителю й господарю Фортеці Шадовфенг, доки звірі Аруґала не спустошили маєток.",al={"хто його пан","кому служив спрінґвейл","спрінґвейл і сільверлейн"}},{q="Де у фортеці його знайти?",a="Привида Командира Спрінґвейла можна зустріти глибоко у фортеці: він блукає укріпленими покоями біля замкової каплиці й залів ради.",al={"місце спрінґвейла","де спрінґвейл","кімната спрінґвейла в шедоуфенґ"}}},fp="20,361,20.303.0,14.359.0,16.208.0,37.225.0,33.205.0,53.181.0,32.117.0,19.138.0,34.139.0"}
P.entries["npc:cookie"] = {n="Печивко",s="Печивко — елітний мурлок, корабельний кок на броненосці, захованому глибоко в Мертвих Копальнях. Незвичний новобранець Братства Дефіас, він доглядає казани команди під пильним оком капітана Ґрінскіна та Едвіна Венкліфа. Це єдиний цілком необов'язковий бос у підземному сухому доці.",h="Печивко — елітний мурлок, корабельний кок на броненосці, захованому глибоко в Мертвих Копальнях.",kw={"печивко","мурлок","кок","кухар","мертві копальні","дефіас"},ang={["class:Rogue"]="Розбійницька мережа Венкліфа спирається на дивні, нешаблонні ресурси, і Печивко доводить, що навіть у постачанні Братства трапляються несподіванки.",["faction:Alliance"]="Розвідники Стормвінда часто дивуються, коли бачать, що мурлоки не просто кишать на дальніх берегах Вестфолу, а працюють на саму верхівку Дефіас.",["profession:Cooking"]="Мурлок на посаді головного кухаря розбійницького броненосця — красномовне свідчення того, якою відчайдушно невибагливою є піратська кухня."},sec={{t="Шеф-кухар Братства",b="Під палубами височенного броненосця в Бухті Айронклад куховарить не людина-розвідник і не гоблін-інженер, а самотній мурлок, якого звуть просто Печивко. Як він здобув цю посаду, лишається таємницею, яку знає лише сам Едвін Венкліф. Хай які сумніви має решта команди щодо мурлока, що порядкує їхнім пайком, пірати рідко можуть перебирати, а в підземному світі Мунбрука їжа — то їжа."},{t="Гірке вариво",b="Печивко обходить протоки й береги довкола піратського флагмана, орудуючи кухонним начинням та їдкими відварами. Хоч він і відірваний від звичних мурлочих племен, свій казан захищає з дикою люттю, жбурляючи пекучі зілля в кожного, хто забреде до доків. Його кухня стоїть осторонь від головних трапів, тож чимало тих, хто штурмує бухту, минають її зовсім — тому Печивко й лишається єдиним необов'язковим наглядачем на броненосці Дефіас."}},faq={{q="Чому мурлок працює кухарем у Дефіасу?",a="Лише Едвін Венкліф знає, чому Печивко взяли на службу й доручили йому камбуз. Розбійники Дефіасу й гоблінські корабели просто миряться з цим: піратські команди їдять те, що є, і їм байдуже, якої породи кухар.",al={"чому мурлок кухар","чому печивко на кораблі","печивко дефіас лор"}},{q="Де в Мертвих Копальнях знайти Печивка?",a="Печивко перебуває в Бухті Айронклад у самому кінці Мертвих Копалень. Він патрулює мілину й причали біля корми величезного дерев'яного корабля, одразу за пандусом, де вартує Пан Кара.",al={"де печивко","місце печивка в мертвих копальнях","знайти печивко"}},{q="Чи обов'язково вбивати Печивка, щоб пройти Мертві Копальні?",a="Ні, Печивко — єдиний необов'язковий бос підземелля. Нападники можуть одразу піднятися на корабель і зійтися з капітаном Ґрінскіном та Едвіном Венкліфом, навіть не потривоживши кухаря, що патрулює берег.",al={"чи обов'язково вбивати печивко","пропустити печивко","чи можна не вбивати печивка"}},{q="Чи належить Печивко до певного племені мурлоків?",a="Печивко не пов'язаний із жодним відомим місцевим племенем мурлоків, як-от із тими, що живуть на узбережжі Вестфолу. Він живе й працює серед розбійників і негідників Братства Дефіас.",al={"яке плем'я печивка","плем'я мурлоків печивка"}},{q="Якою зброєю чи атаками користується Печивко?",a="Печивко б'ється кухонним начинням і може жбурляти в нападників їдкі бризки кислоти, обпікаючи їх небезпечними кулінарними сумішами.",al={"здібності печивка","як б'ється печивко","атаки печивка"}},{q="Кому Печивко підзвітний на кораблі?",a="Печивко служить безпосередньо морським силам Братства Дефіас під командуванням капітана Ґрінскіна, а зрештою підкоряється самому Едвіну Венкліфу.",al={"бос печивка","хто керує печивком","печивко ґрінскін ванкліф"}}},fp="6,336,22.465.0,13.468.0,49.256.0,43.207.0,43.203.0,46.195.0,40.147.0,44.150.0"}
P.entries["npc:corithras-moonrage"] = {n="Корітрас Мунрейдж",s="Корітрас Мунрейдж — учений нічних ельфів і давач завдань у селищі Доланаар на Тельдрассилі. Він допомагає новоприбулим шукачам пригод збагнути природу великого Світового Дерева й доручає їм дбати про його священні місячні колодязі. Його уроки розкривають і духовну вагу Тельдрассила, і дедалі важчий тягар, що лягає на калдореїв.",h="Корітрас Мунрейдж — учений нічних ельфів і давач завдань у селищі Доланаар на Тельдрассилі.",kw={"корітрас мунрейдж","доланаар","тельдрассил","місячні колодязі","світове дерево","фандрал стаґгелм","безсмертя"},ang={["class:Druid"]="Друїди відчують, що завдання Корітраса тісно пов'язані з їхнім покликанням, адже його обряди біля місячних колодязів напряму відстежують здоров'я Світового Дерева та недуги, що підкрадаються до нього.",["class:Priest"]="Жерці Елуни допомагають Корітрасу переносити благословенні води місячних колодязів, підтримуючи духовну й тілесну гармонію хащ довкола Доланаара.",["race:NightElf"]="Для нічних ельфів розмова з Корітрасом — основоположний урок про реальність після Третьої війни: ви стикаєтеся з утратою давнього безсмертя та суперечливим створенням Тельдрассила."},sec={{t="Учений Доланаара",b="Корітрас Мунрейдж мешкає в тінистому поселенні Доланаар і наставляє мандрівників, що залишають захищені межі Тінедолу. Коли молоді калдореї вирушають у ширше гілля Тельдрассила, Корітрас дбає, щоб вони розуміли історію своєї нової домівки. Він навчає, що вижити в цю мінливу добу можна лише пильністю та шаною до природного ладу."},{t="Корона Землі",b="Значна частина обов'язків Корітраса — збирати воду місячних колодязів для друїдів Дарнасуса. Він посилає шукачів пригод набирати чисту воду з місячних колодязів по всьому Тельдрассилу в особливі фіали й доправляти її Фандралу Стаґгелму. Через ці випробування він стежить за здоров'ям Світового Дерева й прагне зберегти крихку рівновагу дикої природи перед скверною, що підкрадається."},{t="Тягар калдореїв",b="За наукою Корітраса криється гірка правда про створення Тельдрассила. На відміну від прадавнього Нордрассила, це нове Світове Дерево виростили без благословення Аспектів драконів, які відмовили честолюбному задуму Фандрала Стаґгелма. Корітрас розмірковує про втрату безсмертя нічних ельфів і про крихке, непевне майбутнє, що чекає калдореїв під неблагословенним гіллям."}},faq={{q="Хто такий Корітрас Мунрейдж?",a="Корітрас Мунрейдж — нічний ельф-учений із Доланаара. Він знайомить шукачів пригод з історією Тельдрассила й доручає їм доглядати священні місячні колодязі та перевіряти води Світового Древа.",al={"роль корітраса","хто такий корітрас","видавець завдань доланаару"}},{q="Де знайти Корітраса Мунрейджа?",a="Він стоїть просто неба в Доланаарі — центральному селищі на роздоріжжі в південній частині Тельдрассила.",al={"місце корітраса","де корітрас","знайти корітраса"}},{q="Про що ланцюжок завдань «Корона Землі»?",a="Завдання «Корони Землі» полягають у тому, щоб набрати воду з місячних колодязів по всьому Тельдрассилу. Корітрас поєднує зібрану воду, щоб передати її Фандралові Стаґгелму в Дарнасус, де друїдам треба поповнити свій місячний колодязь.",al={"значення корони землі","завдання корітраса","завдання місячних колодязів"}},{q="Чому Корітраса непокоїть походження Тельдрассила?",a="Корітрас розповідає, як після Третьої війни посадили Тельдрассил, щоб повернути нічним ельфам безсмертя. Аспекти драконів відмовилися благословити дерево, тож Корітрас добре усвідомлює, що воно не має божественного захисту, а його народ лишається смертним.",al={"чому тягар калдорей","відмова аспектів","чому немає безсмертя"}},{q="Чого Корітрас навчає нових шукачів пригод?",a="Він розповідає про недавні жертви Третьої війни, заснування Тельдрассила й обов'язок кожного калдорея захищати свій новий лісовий дім.",al={"лор корітраса","історія доланаару","що корітрас розповідає"}},{q="Корітрас пов'язаний із Колом Кенарія чи з Дарнасусом?",a="Він вірний громадянин і вчений Дарнасуса в Доланаарі, що тісно співпрацює і з друїдами, і з жрицями, пильнуючи добробут лісу та його вод.",al={"фракція корітраса","чи корітрас друїд"}}},fp="18,376,19.376.0,18.389.0,26.394.1,26.211.0,38.125.0,47.222.0,54.273.0,42.167.0,59.168.0"}
P.entries["npc:councilman-millstipe"] = {n="Радник Міллстайп",s="Радник Міллстайп — член правлячої ради Даркширу, що засідає в ратуші Сутінколісся. Глибоко ображений байдужістю корони й судовим втручанням столиці, він рішуче прагне покарати злочинців, які загрожують цьому темному краю.",h="Радник Міллстайп — член правлячої ради Даркширу, що засідає в ратуші Сутінколісся.",kw={"радник міллстайп","декстрен ворд","дім вельмож","в'язниця стормвінда","даркшир","сутінколісся"},ang={["class:Rogue"]="Для агента, готового прослизнути до суворо охоронюваної В'язниці й виконати несанкціоновану політичну страту, Міллстайп пропонує роботу, що відкрито кидає виклик Домові Вельмож.",["faction:Alliance"]="Міллстайп уособлює глибокий політичний розлам між захищеною стормвіндською знаттю й доведеними до відчаю прикордонними поселеннями Сутінколісся, які майже не отримують допомоги, зате терплять грубе втручання столиці."},sec={{t="Правосуддя, у якому відмовив Стормвінд",b="Поки Даркшир потерпає під тінню нежиті й від нападів лютих звірів, його місцева рада веде виснажливу боротьбу з бюрократією Стормвінда. Радник Міллстайп уособлює дедалі більшу гіркоту містечка щодо корони. Коли сумнозвісного грабіжника могил Декстрена Ворда спіймали на продажі щойно викопаних трупів некромантові Морбенту Фелу, провід Даркширу засудив його до смерті. Натомість стормвіндський Дім Вельмож утрутився, скасував страту Ворда й надійно замкнув його у В'язниці Стормвінда."},{t="Послання вельможам",b="Не бажаючи, щоб продажні політики столиці ставили себе вище безпеки й правосуддя Сутінколісся, Міллстайп потай доручає шукачам пригод завершити справу. Наказавши стратити Декстрена Ворда без суду просто в його камері у В'язниці, Міллстайп хоче надіслати Домові Вельмож недвозначне послання: якщо Стормвінд відмовляється захищати людей Сутінколісся, люди самі візьмуть правосуддя у свої руки."}},faq={{q="Де знайти Радника Міллстайпа?",a="Радник Міллстайп перебуває в ратуші Даркширу на сході Сутінколісся.",al={"місце міллстайпа","де міллстайп","знайти радника міллстайпа"}},{q="Чому Міллстайп хоче смерті Декстрена Ворда?",a="Декстрен Ворд був гробокопачем, що викопував мерців Сутінколісся й продавав їх некромантові Морбенту Фелу. Даркшир засудив його до шибениці, але Дім Вельмож Стормвінда помилував його й натомість кинув до В'язниці.",al={"чому вбити декстрена ворда","міллстайп декстрен ворд","злочин ворда"}},{q="Яку образу Міллстайп має на Стормвінд?",a="Міллстайп вважає, що Стормвінд покинув Сутінколісся, але при цьому втручається в його місцеве правосуддя. Дім Вельмож скасував справедливий смертний вирок Даркширу для Декстрена Ворда, і змучене містечко почувається забутим і беззахисним перед троном.",al={"чому злий на стормвінд","палата шляхти даркшир","політика міллстайпа"}},{q="Чи має Міллстайп відомих родичів?",a="Родичі Радника Міллстайпа невідомі.",al={"родичі міллстайпа","доротея міллстайп","родина міллстайпа"}}},fp="20,265,27.545.0,23.411.1,40.103.0,42.232.0,45.254.0,37.43.0"}
P.entries["npc:count-remington-ridgewell"] = {n="Граф Ремінгтон Ріджвелл",s="Граф Ремінгтон Ріджвелл — заможний аристократ із людей, якого можна знайти в Палаті Прохача у Фортеці Стормвінда. Член Дому Вельмож, він пишається тим, що зібрав найкращу в королівстві приватну колекцію рідкісних історичних артефактів, родинних реліквій і витворів мистецтва.",h="Граф Ремінгтон Ріджвелл — заможний аристократ із людей, якого можна знайти в Палаті Прохача у Фортеці...",kw={"граф ремінгтон ріджвелл","дім вельмож","палата прохача","реліквії","маяра брайтвінг","музей"},ang={["faction:Alliance"]="Для найманців Альянсу граф Ріджвелл — вигідний покровитель, готовий щедро платити за повернені реліквії занепалих північних королівств і загублених дворфійських міст.",["race:Human"]="Як член стормвіндського Дому Вельмож, Ріджвелл уособлює заможну аристократію, яка ставить культурний престиж і колекціонування мистецтва вище за все, попри політичну нестабільність королівства."},sec={{t="Поціновувач старовини",b="Ремінгтон Ріджвелл уособлює вишукані смаки Дому Вельмож і неабияк пишається родинним музеєм коштовностей і артефактів. Замість того щоб перейматися військовими походами чи місцевими повстаннями, граф витрачає чималі статки на реліквії занепалих цивілізацій і згаслих родів з усього Азероту. Щоб розширити свою престижну галерею, він фінансує відважних шукачів пригод і наймає польових агентів, як-от Маяру Брайтвінг, посилаючи їх по безцінні дивовижі до небезпечних руїн — від гірських твердинь Альтераку до вулканічних пусток Палаючих Степів."}},faq={{q="Хто такий Граф Ремінгтон Ріджвелл?",a="Граф Ремінгтон Ріджвелл — шляхтич-людина й колекціонер старожитностей, що перебуває в Палаті Прохача у Фортеці Стормвінда. На родинні статки він скуповує цінні реліквії, коштовності й витвори мистецтва з усього світу.",al={"хто такий реміґтон ріджвелл","реміґтон ріджвелл","граф ріджвелл"}},{q="Які артефакти шукає Граф Ріджвелл?",a="Ріджвелл наймає шукачів пригод, щоб повертати загублені реліквії для свого музею. Серед помітних надбань — Діадема Переноль із руїн Альтераку та історичні скарби дворфів Темного Заліза з Руїн Тауріссана.",al={"завдання ріджвелла","завдання діадеми переноль","чого він хоче"}},{q="Хто така Маяра Брайтвінг?",a="Маяра Брайтвінг — агентка, яку найняв Граф Ріджвелл. Він послав її до Палаючих Степів шукати старожитності в давніх Руїнах Тауріссана.",al={"зв'язок з маярою брайтвінг","хто така маяра"}},{q="Де знайти Графа Ремінгтона Ріджвелла?",a="Він перебуває в Палаті Прохача у Фортеці Стормвінда разом з іншими шляхтичами й сановниками, що чекають на аудієнцію при королівському дворі.",al={"де граф ріджвелл","місце ріджвелла","шляхтич у кімнаті прохачів"}}},fp="25,278,28.615.0,33.222.0,41.225.0,25.158.0,45.147.0"}
P.entries["npc:crane-operator-bigglefuzz"] = {n="Кранівник Бігглфаз",s="Кранівник Бігглфаз — гоблін-докер, що працює на важких машинах у порту Раджета. Після того як перевантажений кран розкидав вантаж по всіх причалах, він відчайдушно намагається повернути цінну вкрадену пляшку, поки не помітило начальство.",h="Кранівник Бігглфаз — гоблін-докер, що працює на важких машинах у порту Раджета.",kw={"кранівник бігглфаз","раджет","доки","99-річний портвейн","скажений маґґліш","ґазлоу"},ang={["class:Rogue"]="Розбійники оцінять, як швидко спритні злодії на кшталт Скаженого Маґґліша вміють скористатися хвилиною метушні в доках, щоб поцупити безцінну здобич просто з-під носа в гобліна.",["profession:Engineering"]="Інженери оцінять, що перевантаження снастей і кранів картелю Стімвідл досі лишається головною причиною промислових аварій на узбережжях Калімдору."},sec={{t="Халепа в доках",b="Як і чимало гоблінів-докерів, Кранівник Бігглфаз ставив швидкість і поспіх вище за найпростіші запобіжні заходи. Коли він намагався підняти з торгового судна надто важкий вантаж, його кран прогнувся, і ящики з гуркотом посипалися на пристані Раджета. У сум'ятті, що зчинилося, налетіли спритні пройдисвіти, тож Бігглфазові довелося гарячково прибирати безлад і рятувати найцінніший товар, поки Ґазлоу чи місцеві портові начальники не зрізали йому платню."},{t="Викрадений портвейн",b="Найгіршою втратою під час аварії стали не потрощені дошки, а ящик рідкісного дев'яностодев'ятирічного портвейну. Перш ніж Бігглфаз устиг усе прибрати, невловимий волоцюга на прізвисько Скажений Маґґліш вихопив пляшку й сховався, і тепер Бігглфазові загрожує відповідати за непоправну втрату."}},faq={{q="Хто такий Кранівник Бігглфаз?",a="Це гоблін-кранівник із причалів Раджета, що відповідає за навантаження й розвантаження морських вантажів для картелю Стімвідл.",al={"хто такий бігглфаз","кранівник","бігглфаз рятчет"}},{q="Що спричинило аварію на причалах?",a="Бігглфаз спробував підняти краном забагато вантажу за раз: механізм не витримав, і вантаж розсипався по всій пристані.",al={"чому кран упустив вантаж","аварія в доках рятчета","халепа з краном"}},{q="Хто обікрав Бігглфаза?",a="Пройдисвіт на ім'я Скажений Маґґліш скористався розсипаним вантажем, поцупив цінну пляшку дев'яностодев'ятирічного портвейну й утік.",al={"хто взяв портвейн","вантаж скаженого маґґліша","хто обікрав бігглфаза"}},{q="Чому Бігглфаз так переймається через украдену пляшку?",a="Дев'яностодев'ятирічний портвейн надзвичайно рідкісний і дорогий. Утратити його через недбалість — означає суворі штрафи, а то й гірше, від босів картелю Стімвідл.",al={"чому бігглфаз переймається вином","причина халепи в доках"}}},fp="25,257,19.467.0,15.303.0,33.144.0,38.138.0,26.150.0,53.175.0"}
P.entries["npc:craven-drok"] = {n="Малодушний Дрок",s="Малодушний Дрок — орк-блукач, що ховається в тьмяних тунелях Тіньової Розколини під Оргріммаром. Цілком виправдовуючи своє прізвисько, він тримається темних закутків міста й час від часу звертається до мандрівників, готових доставити делікатне листування про ворогів Орди.",h="Малодушний Дрок — орк-блукач, що ховається в тьмяних тунелях Тіньової Розколини під Оргріммаром.",kw={"малодушний дрок","тіньова розколина","оргріммар","боягуз","депеші","розбійники"},ang={["class:Rogue"]="Тіньова Розколина — природне місце зборів для тих, хто діє не на видноті, тож такі знайомці, як Дрок, — звичні мешканці підземного світу під столицею.",["race:Orc"]="Більшість орків дивиться на Малодушного Дрока зверхньо: його звичка ховатися в похмурій Тіньовій Розколині різко суперечить традиційним уявленням орків про честь і мужність."},sec={{t="Тінь серед тіней",b="Більшість орків Оргріммара гордо ходять осяяними сонцем вулицями Долини Честі чи Долини Сили, а Малодушний Дрок цілком уникає денного світла. Він блукає звивистими підземними стежками Тіньової Розколини — кварталу, що зазвичай належить чорнокнижникам, розбійникам і майстрам не надто почесних ремесел. Дрок цілком виправдовує свою боягузливу славу: воліє не потрапляти на очі й наймає перехожих виконувати його делікатні доручення, зокрема доставляти депеші про дії Альянсу."}},faq={{q="Де знайти Малодушного Дрока?",a="Малодушний Дрок блукає печерними підземними переходами Тіньової Розколини глибоко під головними вулицями Оргріммара.",al={"місце дрока","де малодушний дрок","дрок оргріммар"}},{q="Чому його звуть Малодушним?",a="Культура орків понад усе цінує відкриту хоробрість і бойову славу. Дрок заслужив своє прізвисько тим, що ховається в темних печерах, не висовується й наймає інших для справ, якими не хоче займатися сам.",al={"чому малодушний","ім'я малодушного дрока","чи дрок боягуз"}},{q="Що пов'язує його з Альянсом?",a="Дрок пов'язаний із донесенням щодо стосунків з Альянсом: він посередник, що посилає гінців через землі Орди з важливими відомостями про ворожі фракції.",al={"зв'язок з альянсом","стосунки дрока з альянсом"}},{q="Чи родич Малодушний Дрок Капітанові Дроку?",a="Вони мають спільне ім'я й походження, але чи пов'язані Малодушний Дрок і Капітан Дрок родинними узами, не підтверджено.",al={"родич капітана дрока","родина дрока"}}},fp="11,290,24.500.0,29.137.0,26.223.0,42.182.0,39.135.0"}
P.entries["npc:cyrus-therepentous"] = {n="Сайрус Терепентус",s="Сайрус Терепентус — грізний чорний драконород, що мешкає в печерних глибинах Звивистої Скелі в Палаючих Степах. Він не вбиває зайд одразу, а випробовує сміливих смертних, щоб з'ясувати, чи стане їм сили послужити цілям чорного драконячого роду.",h="Сайрус Терепентус — грізний чорний драконород, що мешкає в печерних глибинах Звивистої Скелі в Палаючих...",kw={"сайрус терепентус","драконород","звивиста скеля","палаючі степи","чорні дракони"},sec={{t="Володар Звивистої Скелі",b="Усамітнившись у печері Звивистої Скелі, Сайрус Терепентус наглядає за вулканічними скелями Палаючих Степів. Як і багато його родичів, він дивиться на смертних мандрівників із безмежною зверхністю й заявляє, що тільки дурні наважилися б потривожити його лігво. Та під лютою зовнішністю ховається холодний розрахунок: замість пожирати кожного зайду, щойно побачить, він пропонує смертельне випробування проти своїх посіпак — і охоче використовує тих, хто виявиться досить витривалим, щоб пройти крізь вогонь."}},faq={{q="Хто такий Сайрус Терепентус?",a="Сайрус Терепентус — розумний чорний драконород, що мешкає в печері біля Звивистої Скелі в Палаючих Степах. Він служить Чорному драконячому роду й випробовує смертних шукачів пригод, що наважуються ввійти до його лігва.",al={"сайрус терепентус","хто такий сайрус","драконід слізерок"}},{q="Де знайти Сайруса Терепентуса?",a="Він живе глибоко в печері біля Звивистої Скелі на північному сході Палаючих Степів.",al={"місце сайруса","де сайрус терепентус","печера сайруса"}},{q="Чому Сайрус не нападає на шукачів пригод одразу?",a="Хоч він і відверто розмірковує, чи не з'їсти непроханих гостей, Сайрус воліє з'ясувати, чи не знадобляться йому смертні. Тих, хто виявиться корисним, він милує й натомість кидає проти смертельних випробувань і своїх прислужників.",al={"чому сайрус дружній","чому сайрус мене не вбиває","розмова з сайрусом"}}},fp="18,283,26.477.0,26.201.0,38.105.0,46.191.0"}
P.entries["npc:dalar-dawnweaver"] = {n="Далар Донвівер",s="Далар Донвівер — колишній архімаг Даларана, що нині служить Відступникам у Гробниці в Срібноліссі. Загинувши, коли Погибель знищувала місто магів, і згодом звільнившись з-під влади Короля-Ліча, він спрямовує свій магічний розум на розбір загроз краю. Із тіні гробниці він керує зусиллями, щоб з'ясувати, що досі робить у краї Даларан, і виправити наслідки божевілля Архімага Аруґала.",h="Далар Донвівер — колишній архімаг Даларана, що нині служить Відступникам у Гробниці в Срібноліссі.",kw={"далар донвівер","архімаг","гробниця","кірін-тор","амбермілл","срібнолісся"},ang={["class:Mage"]="Маги-Відступники побачать у Даларі темне віддзеркалення колишньої величі Даларана: він показує, як вишкіл Кірін-Тору можна обернути на зброю на службі Темній Леді.",["faction:Horde"]="Далар, що несе службу в Гробниці, береже західне прикордоння Орди, організовуючи удари по воргенах Фортеці Шадовфенг і ворожих анклавах Кірін-Тору.",["race:Undead"]="Далар утілює здобуту Відступниками свободу волі: знання, якими він володів за життя, він обертає проти решток Даларана й чарівників-ренегатів, що загрожують їхній незалежності."},sec={{t="Полеглий архімаг",b="За життя Далар Донвівер мав високий ранг у Кірін-Торі й ходив залами Фіолетової Цитаделі, коли Даларан був вершиною таємної майстерності. Його смертне життя обірвалося, коли Погибель сплюндрувала місто, щоб розчистити шлях для виклику Архімонда. Піднятий як бездумний раб Короля-Ліча, Далар вирвався на волю разом із Леді Сильваною Віндраннер, коли хватка Погибелі ослабла. Нині, у Гробниці, він зберігає гострий розум архімага, цілком спрямований на захист королівства Відступників."},{t="Око на Амбермілл і Шадовфенг",b="Срібнолісся затиснуте між багатьма небезпеками, і Далар — головний знавець таємної магії й стратег Гробниці. На півдні даларанські чарівники засіли в Амберміллі під захисним куполом, втручаючись у справи, які Далар прагне розкрити й зірвати. Ще ближче нависає Фортеця Шадовфенг і дикі воргени, випущені в ліси. Далар добре знає свого колишнього колегу, Архімага Аруґала, і ретельно організовує походи, щоб знешкодити звірині творіння Аруґала, перш ніж ті заполонять край."}},faq={{q="Хто такий Далар Донвівер?",a="Далар Донвівер — маг-Відступник із Гробниці в Срібноліссі. За життя він був архімагом Кірін-Тору в Даларані. Загинувши під час Третьої війни й повставши з волі Погибелі, він вирвався з-під влади Короля-Ліча, щоб служити Темній Леді.",al={"хто такий далар","лор далара донвівера","минуле далара"}},{q="Що з ним сталося під час Третьої війни?",a="Далар був у Даларані, коли Артас Менетіл і Погибель вдерлися туди по Книгу Медіва. Убитого під час штурму, коли Кел'Тузад закликав Архімонда в Азерот, Далара підняли з мертвих слугою Погибелі, доки Сильвана його не звільнила.",al={"як помер далар","смерть далара","далар третя війна"}},{q="Чому Далар служить у Гробниці?",a="Він — місцевий авторитет у тайній магії для Відступників у Срібноліссі. Він добре знає і сили Кірін-Тору, що засіли в Амбермілі, і свого колишнього колегу, Архімага Аруґала, тож найкраще годиться, щоб протистояти цим загрозам.",al={"чому далар у склепі","роль далара в сільверпайні"}},{q="Що пов'язує Далара з Архімагом Аруґалом?",a="Обидва були магами Кірін-Тору в Даларані до його падіння. Далар розуміє трагічне падіння Аруґала й смертельну небезпеку його дослідів із викликом у Фортеці Шадовфенг, тож доручає шукачам пригод збирати свідчення безумства Аруґала, а зрештою вимагає смерті божевільного мага.",al={"далар і аруґал","чи далар знав аруґала"}},{q="Що Далар хоче від решток Даларана?",a="Далар пильно стежить за своєю колишньою батьківщиною й силами Кірін-Тору, що вціліли й стоять в Амбермілі. Він посилає агентів перехоплювати їхні повідомлення й з'ясовувати їхні наміри, щоб вони не загрожували Відступникам у Срібноліссі.",al={"далар і даларан","далар амбермілл"}},{q="Чи Далар на боці Кірін-Тору?",a="Ні. Хоч колись він і був серед них архімагом, тепер він вірний Відступникам і Орді. Він завзято протистоїть силам Кірін-Тору, що діють у Срібноліссі.",al={"чи далар кірін-тор","чи далар вірний даларану"}}},fp="16,419,17.525.0,32.503.0,24.268.0,42.265.0,40.245.0,46.275.0,45.248.0,36.186.0"}
P.entries["npc:daphne-stilwell"] = {n="Дафна Стілвелл",s="Дафна Стілвелл доглядає відлюдний сад на прибережних кручах Вестфолу над Лонгшором. Разом із чоловіком Джорданом вона втекла від смути на півночі й переселилася на південь, де тихо допомагає Церкві Святого Світла й боронить свій дім від сусідніх розбійників.",h="Дафна Стілвелл доглядає відлюдний сад на прибережних кручах Вестфолу над Лонгшором.",kw={"дафна стілвелл","ферма","вестфол","фоліант звитяги","паладини","дефіас"},ang={["class:Paladin"]="Дафна Стілвелл — важлива постать у випробуваннях Фоліанта Звитяги: захистивши її від безжальних грабіжників Дефіас, паладин доводить свою відданість захисту невинних.",["faction:Alliance"]="Стілвелли уособлюють долю переселенців із півночі, які й далі служать Альянсу й Церкві Святого Світла попри небезпеки вестфольського прикордоння."},sec={{t="Життя на кручах",b="На урвищах на захід від Мунбрука й виходу з Мертвих Копалень Дафна Стілвелл веде відлюдне господарство з яблуневим садом. Знизу, з Лонгшору, чи згори, з грифонових маршрутів на південь до Долини Стренглторну, маленька ферма здається тихою й непримітною. Та тримати господарство в нинішньому Вестфолі — аж ніяк не безпечно. Попри розбійників, що підступають, і мародерів, що никають довкола, Дафна сумлінно доглядає дерева й пильнує свій відлюдний клаптик землі."},{t="Біженці з півночі",b="До того як оселитися на пагорбах Вестфолу, Дафна з чоловіком Джорданом жили в Лордероні біля Села Пайрвуд і працювали там, де нині стоїть Фортеця Шадовфенг. Коли той край поглинули темрява й лихо, вони разом із тисячами інших людських біженців мусили податися на південь. Поблизу Стормвінда славетна майстерність Джордана й незмінна стійкість Дафни привели їх до тісних зв'язків із Церквою Святого Світла: вони підтримують паладинів Срібної Длані й постачають їм святу зброю."},{t="Оборона ферми",b="Життя так близько до Мертвих Копалень ставить Дафну просто на шляху Братства Дефіас. Поки Джордан у мандрах або кує святу зброю далеко від столиці, Дафна часто лишається сама доглядати їхній прибережний дім. Коли розбійники напали на ферму, шукаючи помсти чи здобичі, Дафна взяла до рук зброю й билася пліч-о-пліч із молодими паладинами, яких прислав Собор, і довела, що в розпалі бою вона напрочуд люта й вправна."}},faq={{q="Хто така Дафна Стілвелл?",a="Дафна Стілвелл — жінка-поселенка, що живе у відлюдному фермерському будинку над Лонгшором у Вестфолі. Вона дружина славетного коваля Джордана Стілвелла, з яким утекла зі спустошених північних королівств.",al={"хто така дафна","інфо про дафну стілвелл","дружина стілвелла"}},{q="Звідки родом Дафна?",a="Колись Дафна жила на півночі біля Села Пайрвуд і працювала в замку, що тепер відомий як Фортеця Шадовфенг, доки лихо не погнало її з Джорданом на південь, у землі Стормвінда.",al={"походження дафни","звідки дафна","чи дафна гілнеанка"}},{q="Чому на її ферму нападає Братство Дефіас?",a="Її ферма стоїть на кручах просто над південними водами Вестфолу, над вихідними тунелями Мертвих Копалень. Через близькість до твердині Дефіасу вона — легка мішень для розбійників, що шукають припасів або хочуть позбутися зайвих свідків.",al={"чому дефіас нападають на дафну","напад дефіас на ферму","бандити ферми стілвеллів"}},{q="Що пов'язує Дафну з паладинами?",a="Її чоловік Джордан допомагає Церкві Святого Світла, куючи освячену зброю. У межах випробувань для Фоліанта Звитяги паладинів Срібної Длані посилають до Вестфолу захищати Дафну від нападів бандитів.",al={"завдання паладинів дафна","том доблесті дафна","чому паладини в дафни"}},{q="Чи може Дафна сама себе захистити?",a="Так. Коли Дефіас нападає на її сад, вона не ховається: бере зброю й б'ється з нападниками пліч-о-пліч із паладинами, що захищають обійстя.",al={"чи дафна б'ється","чи дафна воїн"}},{q="Як дістатися до її ферми?",a="Її ферма примостилася на вершинах круч на південному заході Вестфолу, на південний захід від Мунбрука, біля таємного виходу з Мертвих Копалень у бухту, звідки видно Лонгшор.",al={"де ферма дафни","як дістатися ферми стілвеллів","місце дафни стілвелл"}}},fp="15,287,20.475.0,21.485.0,18.451.1,23.211.0,27.183.0,51.248.0,40.226.0,26.163.0,31.157.0"}
P.entries["npc:darcy-parker"] = {n="Дарсі Паркер",s="Дарсі — офіціантка в Корчмі Лейкшира, яка подає напої й гарячі страви. Серед постійних загроз, що нависли над Редріджем, вона не падає духом і дбає про місцевих захисників — особливо про Вартового Паркера.",h="Дарсі — офіціантка в Корчмі Лейкшира, яка подає напої й гарячі страви.",kw={"дарсі","вартовий паркер","корчма лейкшира","марті джейнроуз","три кути","лейкшир"},ang={["faction:Alliance"]="Дарсі уособлює стійких простих людей Лейкширу: вона підтримує дух і годує захисників, поки місто чекає допомоги зі Стормвінда."},sec={{t="Привітне обличчя в корчмі",b="За гамірним шинквасом Корчми Лейкшира Дарсі день і ніч працює, щоб утомлене міське ополчення було нагодоване й напоєне. Лейкшир під постійним тиском гнолів і орків Блекрок, тож таверна — одне з небагатьох теплих місць, що лишилися в поселенні. Дарсі щиро переймається вартовими, які стоять довкола містечка, і часто просить мандрівних шукачів пригод віднести гарячий обід чи передати привіт тим, хто несе варту на кордонах."},{t="Роман на посту",b="Особливо тепло Дарсі ставиться до Вартового Паркера, який патрулює дороги біля Трьох Кутів. Переконана, що він надто багато працює на порожній шлунок, вона раз у раз відправляє до нього мандрівників з обідом, щоб він тримався на ногах. Її симпатія не лишилася непоміченою: Дарсі пильно стежить за Марті Джейнроуз, яку вважає ревнивою суперницею в боротьбі за прихильність Паркера, — і оборона Лейкширу стає тлом для щирої історії кохання в маленькому містечку."}},faq={{q="Хто така Дарсі?",a="Дарсі — офіціантка-людина з Корчми Лейкшира в Горах Редріджу. Вона готує їжу для захисників містечка й часто просить перехожих мандрівників віднести обід вартовим на посту.",al={"хто така дарсі","дарсі паркер нпс","офіціантка лейкшира"}},{q="Що пов'язує Дарсі з Вартовим Паркером?",a="Дарсі глибоко небайдужа до Вартового Паркера. Вона з усіх сил дбає, щоб пакувати йому свіжі обіди й передавати з мандрівниками, аби він не голодував, патрулюючи дороги біля Трьох Кутів.",al={"дарсі та вартовий паркер","вартовий паркер дарсі","хто подобається дарсі"}},{q="Чому Дарсі з підозрою ставиться до Марті Джейнроуз?",a="Дарсі вважає Марті Джейнроуз ревнивою й бачить у ній суперницю в боротьбі за увагу Вартового Паркера, що додає трохи особистого суперництва в повсякденне життя містечка.",al={"дарсі та марті","марті джейнроуз","суперниця дарсі"}},{q="Де знайти Дарсі?",a="Вона обслуговує відвідувачів у Корчмі Лейкшира — у самому серці Лейкширу на північному березі Озера Незрушне в Редріджі.",al={"місце дарсі","де дарсі","знайти дарсі"}}},fp="12,207,26.456.0,25.444.0,13.216.0,47.193.0,43.179.0,25.152.0"}
P.entries["npc:darion-mograine"] = {n="Даріон Моґрейн",s="Даріон Моґрейн — молодший син полеглого Верховного Лорда Александроса Моґрейна, легендарного Ешбрінгера. Паладин, що приєднався до Срібного світанку після загадкової загибелі батька, Даріон у відчайдушних пошуках правди про долю своєї родини опинився в самому центрі конфлікту, що поглинає Чумні Землі.",h="Даріон Моґрейн — молодший син полеглого Верховного Лорда Александроса Моґрейна, легендарного Ешбрінгера.",kw={"даріон моґрейн","александрос моґрейн","ешбрінгер","срібний світанок","паладин","чумні землі","наксрамас"},ang={["class:Paladin"]="Даріон уособлює глибоку кризу віри, яку пережили паладини після падіння Лордерону: він намагається поєднати обов'язок перед Світлом із суворою реальністю Чумних Земель.",["race:Human"]="Трагічний розкол родини Моґрейнів віддзеркалює загибель самого Лордерону: серед попелу королівства брати опинилися у ворожих орденах."},sec={{t="Син Срібної Длані",b="Даріон виріс у тіні величної батькової спадщини. Він ріс неподалік Брілла в королівстві Лордерон, став свідком початку чуми нежиття й невдовзі після Третьої війни приєднався до Лицарів Срібної Длані. Даріон упав у бою під Стратгольмом і ледве вижив, а згодом його світ розсипався, коли батько загинув за підозрілих обставин. Борючись із горем і сумнівами у вірі у Святе Світло, Даріон обрав інший шлях, ніж фанатичний Багряний Хрестовий Похід, і зрештою пристав до щойно створеного Срібного світанку."},{t="Пошуки Ешбрінгера",b="Коли після смерті батька Даріон засумнівався у Світлі, до нього прийшов жрець-троль Забра Гекс і порадив шукати батька у фортеці, що ширяє над палаючим містом. Це загадкове знамення повело Даріона новим шляхом — до Срібного світанку — і тепер вказує йому на жахливий некрополь Наксрамас, де, як він вірить, прихована правда про долю Александроса."}},faq={{q="Хто такий Даріон Моґрейн?",a="Даріон — воїн-людина й паладин Срібного світанку, молодший син Верховного Лорда Александроса Моґрейна, першого володаря легендарного клинка Ешбрінгер.",al={"лор даріона моґрейна","хто такий даріон","син моґрейна"}},{q="Чому Даріон не приєднався до Багряного Хрестового Походу, як його брат?",a="Поки його старший брат Рено піднімався щаблями фанатичного Багряного Хрестового Походу, Даріон після смерті батька розчарувався у фанатизмі. Прислухаючись до сторонніх порад і шукаючи справжнього спокутування, а не сліпої люті, Даріон присягнув своїм мечем відкритішому Срібному Світанку.",al={"даріон багряний хрестовий похід","чому срібний світанок даріон"}},{q="Що пов'язує Даріона з Ешбрінгером?",a="Ще юнаком Даріон потай був присутній на зустрічі свого батька зі Срібною Дланню в корчмі в Саутшорі й бачив очищення того, що згодом стало серцем Ешбрінгера — клинка, який його батько зробив легендарним.",al={"даріон і ешбрінґер","чи даріон отримав меч"}}},fp="15,307,24.568.0,28.375.1,23.166.0,60.300.0,46.232.1"}
P.entries["npc:darius-crowley"] = {n="Даріус Кровлі",s="Лорд Даріус Кровлі — палкий ґілнеаський вельможа, що завзято підтримував Великий Альянс і виступав проти політики самоізоляції короля Ґенна Ґреймейна. Коли зведена Стіна Ґреймейна відрізала його північні володіння й відгородила королівство від зовнішнього світу, Кровлі очолив Повстання Північної Брами — збройний заколот, через який зрештою опинився у В'язниці Кам'яної Варти за державну зраду.",h="Лорд Даріус Кровлі — палкий ґілнеаський вельможа, що завзято підтримував Великий Альянс і виступав проти...",kw={"даріус кровлі","ґілнеас","ґенн ґреймейн","стіна ґреймейна","повстання північної брами","в'язниця кам'яної варти"},ang={["faction:Alliance"]="Кровлі лишався одним із небагатьох ґілнеаських вельмож, вірних Великому Альянсу: він пішов проти свого короля, щоб послати війська з Джайною Праудмур до Калімдору.",["race:Human"]="Люди по цей бік зачиненої брами Стіни Ґреймейна пам'ятають Кровлі як рідкісного ґілнеаського проводиря, що не покинув сусідів у темні дні Третьої війни."},sec={{t="Друг Альянсу",b="Під час Другої війни лорд Даріус Кровлі був одним із найхаризматичніших і найпопулярніших молодих вельмож Ґілнеасу. Коли король Ґенн Ґреймейн вирушив до Лордерона послухати Андуїна Лотара про загибель Стормвінда, Кровлі закликав свого монарха допомогти братнім людським народам проти Старої Орди. Його прихильність до Альянсу ніколи не хиталася, навіть коли Ґреймейна дедалі більше обурювали витрати на табори для інтернованих і податки на відбудову півдня. Коли спалахнула Третя війна й Ґреймейн обрав відокремленість, Кровлі всупереч королівським наказам послав Ґілнеаську бригаду через Велике море разом з експедицією Леді Джайни Праудмур до Калімдору."},{t="Повстання Північної Брами",b="Рішення короля Ґреймейна звести велетенську Стіну Ґреймейна розтяло прадідівські землі Кровлі навпіл і покинуло такі володіння, як Амбермілл і Село Пайрвуд, на поталу дикій місцині за стіною. Вважаючи стіну водночас образою й тиранічним боягузтвом, Кровлі зібрав збройний загін, відомий як повстанці Північної Брами, щоб скинути короля. Громадянська війна, що спалахнула, роздирала Ґілнеас, доки повстанці не пішли на штурм самого Міста Ґілнеас, обстрілюючи столицю з гармат. Прихильники короля згуртувалися й розгромили заколот, а Кровлі схопили й ув'язнили у В'язниці Кам'яної Варти, затаврувавши зрадником."}},faq={{q="Хто такий Даріус Кровлі?",a="Лорд Даріус Кровлі — відомий ґілнеаський лорд, що палко обстоював, щоб Ґілнеас лишався у Великому Альянсі. Він виступав проти відособленості Короля Ґенна Ґреймейна, всупереч волі короля профінансував експедицію до Калімдору, а зрештою очолив збройну громадянську війну, щоб повалити корону.",al={"лор даріуса кровлі","хто такий кровлі","лорд кровлі"}},{q="Де зараз Даріус Кровлі?",a="Кровлі ув'язнений глибоко у В'язниці Кам'яної Варти в Місті Ґілнеас. Після поразки його повстанців у Повстанні Північної Брами корона Ґілнеаса засудила його за державну зраду й тримає під суворою вартою.",al={"де кровлі","чи кровлі живий","місце кровлі"}},{q="Чому Кровлі повстав проти Короля Ґреймейна?",a="Кровлі виступав проти рішення Ґреймейна вивести Ґілнеас з Альянсу й звести Стіну Ґреймейна. Стіна пройшла просто через північні володіння Кровлі й залишила поселення на кшталт Амбермілла й Пайрвуда поза захистом королівства. Вважаючи це тиранічною зрадою, Кровлі взявся за зброю.",al={"чому кровлі повстав","причина повстання північної брами","кровлі проти ґреймейна"}},{q="Якими землями Кровлі володів за Стіною Ґреймейна?",a="Доки Стіна Ґреймейна не відгородила Ґілнеас від Срібнолісся, Кровлі володів поселеннями Амбермілл і Село Пайрвуд та керував ними разом із довколишніми землями на півночі.",al={"землі кровлі","лорд пайрвуда","амбермілл кровлі"}}},fp="14,370,24.643.0,23.622.0,22.288.0,34.229.0,44.315.0,54.200.0"}
P.entries["npc:dark-cleric-beryl"] = {n="Темна Клірикиня Берил",s="Темна Клірикиня Берил — наставниця жерців Відступників, що перебуває в Таверні «Шибеничний Кінець» у Бріллі. Вона веде щойно пробуджених жерців-нежить, поки ті вчаться володіти магією тіні й звикають до свого нового, нечестивого існування під рукою Темної Леді.",h="Темна Клірикиня Берил — наставниця жерців Відступників, що перебуває в Таверні «Шибеничний Кінець» у Бріллі.",kw={"темна клірикиня берил","жрець","тінь","таверна шибеничний кінець","брілл","наставниця"},ang={["class:Priest"]="Для жерців Відступників, що вирушають на Галявини Тірісфалю, Берил — неодмінна наставниця у Бріллі: вона підказує, як володіти магією тіні й пережити суворий перехід до нечестивої сили.",["race:Undead"]="Берил утілює пристосування Відступників до свого проклятого стану: сліпу відданість колишнім вірам Лордерону вони проміняли на практичну, тіньову стійкість."},sec={{t="Провідниця в тінях",b="Темна Клірикиня Берил, що мешкає на горішньому поверсі Таверни «Шибеничний Кінець» у Бріллі, служить Відступникам як наставниця жерців-початківців. За життя віддані Святому Світлу, багато жерців Відступників після підняття в нежитті виявили, що їхній зв'язок зі святою магією став нестерпно болісним або й урвався зовсім. Берил допомагає цим щойно піднятим чародіям перевести увагу на тінь і темні мистецтва, провадячи їх крізь перші випробування — як-от виготовлення Шат Темряви — і доводячи їхню відданість новому шляху."}},faq={{q="Хто така Темна Клірикиня Берил?",a="Темна Клірикиня Берил — наставниця жерців із Відступників на верхньому поверсі Таверни «Шибеничний Кінець» у Бріллі. Вона вчить новопіднятих жерців із нежиті розширювати свою магію й приймати тінь.",al={"роль берил","хто така берил","лор клірикині берил"}},{q="Де знайти Темну Клірикиню Берил?",a="Вона перебуває на Галявинах Тірісфалю, у містечку Брілл, — на верхньому поверсі Таверни «Шибеничний Кінець».",al={"місце берил","де берил","знайти темну клірикиню берил"}},{q="Чому жерці-Відступники мають звання темного кліриха?",a="Звання темного кліриха беруть жерці-Відступники, що відкидають традиційні догми Святого Світла або врівноважують їх темнішими практиками. Спрямовувати Світло нестерпно боляче для їхньої неживої плоті, тож багато хто з них схиляється до магії тіні й Культу Забутих Тіней.",al={"що таке темний клірик","темні клірики відступників","чому темний клірик"}},{q="Які завдання дає Берил?",a="Берил пов'язана з першими навчальними завданнями жерців-Відступників, зокрема «На користь темряви» й «Шати темряви», які вчать молодих послушників допомагати союзникам і вбиратися в шати, гідні тіні.",al={"завдання берил","завдання темної клірикині берил"}}},fp="17,231,22.511.0,25.197.0,35.116.0,50.281.0,29.231.0"}
P.entries["npc:dark-iron-ambassador"] = {n="Посол Темного Заліза",kw={"посол темного заліза","темне залізо","тауріссан","термаплаґ","гномреґан","змова"},sec={{t="Тіньовий посланець",b="The Dark Iron Ambassador is found among the dangers of irradiated Gnomeregan. He represents the Dark Iron clan, but the purpose of his mission is not explained."},{t="Змови в глибинах",b="Investigators and goblins raise suspicions about Dark Iron involvement in Gnomeregan's troubles and its mysterious super rig. These remain theories; the ambassador's presence does not establish who caused the city's fall or the terms of any agreement."}},faq={{q="Хто такий Посол Темного Заліза?",a="He is a Dark Iron emissary found inside Gnomeregan. His precise diplomatic mission is unknown.",al={"хто цей дворф","особа посла темного заліза","що за посол темного заліза"}},{q="Що дворф Темного Заліза робить у Гномреґані?",a="His purpose is not established. His presence shows that the Dark Iron clan has an interest in Gnomeregan.",al={"чому темне залізо в гномереґані","що він тут робить","призначення дворфа темного заліза"}},{q="Чи допомогло Темне Залізо спричинити падіння Гномреґану?",a="That is not established. Investigators have raised suspicions, but their theories do not prove who caused the disaster.",al={"чи темне залізо винне в падінні","змова темного заліза","чи таурісан допоміг термаплаґу"}},{q="Звідки посол?",a="He belongs to the Dark Iron clan, whose ruler is Emperor Dagran Thaurissan.",al={"звідки посол","хто його надіслав","на кого він працює"}},{q="Чи він у союзі із Сікко Термаплаґом?",a="An alliance is suspected, but no confirmed agreement is established by his presence alone.",al={"союзник термаплаґа","чи він із термаплаґом","працює з термаплаґом"}},{q="Де знайти Посла Темного Заліза?",a="Це невловимий, рідкісний супротивник, що блукає зараженими інженерними секторами й коридорами майстерень у підземеллі Гномреґан.",al={"поява посла","де з'являється посол","місце посла в гномереґані"}}},fp="20,176,15.160.0,24.251.1,32.94.0,43.105.0,53.119.0,36.75.0,36.90.0,44.135.0"}
P.entries["npc:darkmaster-gandling"] = {n="Темний Майстер Ґандлінґ",s="Темний Майстер Ґандлінґ — смертний директор Сколомансії, що наглядає за навчанням і вишколом некромантів для Культу Проклятих. З глибин зруйнованої твердині Каер Дарроу він служить Погибелі, влаштовуючи жахливі магічні досліди над живими й мертвими.",h="Темний Майстер Ґандлінґ — смертний директор Сколомансії, що наглядає за навчанням і вишколом некромантів для...",kw={"ґандлінґ","сколомансія","культ проклятих","каер дарроу","некромантія","кел'тузад","директор"},ang={["class:Mage"]="Ґандлінґ — найглибше спотворення наукових традицій Даларана: академічну сумлінність він перетворив на жахливу фабрику нежиття.",["race:Undead"]="Для Відступників Ґандлінґ — ненависний наглядач, що промиває мізки на користь Погибелі й заковує вільні душі у вічне рабство під Каер Дарроу."},sec={{t="Володіння директора",b="У темних залах під Каер Дарроу Темний Майстер Ґандлінґ керує Сколомансією — найголовнішою академією для честолюбних некромантів Погибелі. Ґандлінґ — жива людина на службі Культу Проклятих; разом із лічем Расом Фроствіспером він чинив звірства над незліченними безневинними бранцями, захопленими в навколишніх землях. Учнів у його класах навчають варити чуму, оживляти мерців і ліпити плоть. Директором його призначив сам Кел'Тузад, засновник Культу, — і саме йому Ґандлінґ звітує напряму."},{t="Володар сховища реліквій",b="Ґандлінґ мешкає глибоко в Кабінеті Директора й повеліває темними реліквіями та духами, ув'язненими в прадавній школі. Він володіє руйнівною тайною й тіньовою магією разом із забороненим некромантським мистецтвом: проклинає непроханих гостей і жбурляє їх крізь тіньові портали до замкнених покоїв навколо свого кабінету, де їм доводиться самотужки битися з повсталими мерцями, поки сам Ґандлінґ ховається від будь-якої шкоди."}},faq={{q="Хто такий Темний Майстер Ґандлінґ?",a="Темний Майстер Ґандлінґ — некромант-людина з Культу Проклятих. Він директор Сколомансії: керує темною школою й готує нових некромантів на службу Королю-Лічу.",al={"хто такий ґандлінґ","лор ґандлінґа","бос сколомантії"}},{q="Ґандлінґ — нежить чи жива людина?",a="Попри майстерність у магії смерті й вірність Погибелі, Ґандлінґ лишається живою смертною людиною. Він очолює смертних послушників і культистів у Сколомансії й служить Погибелі з власної волі.",al={"чи ґандлінґ нежить","чи ґандлінґ живий","раса ґандлінґа"}},{q="Що пов'язує його з Расом Фроствіспером?",a="Рас Фроствіспер був учителем Ґандлінґа. Разом директор-людина й могутній ліч зробили Сколомансію осередком темного навчання й наглядали за жахіттями, що їх чинили над невинними душами, як-от Саркгоффи, у Каер Дарроу.",al={"ґандлінґ і фроствіспер","рас фроствіспер учитель"}},{q="Де знайти Темного Майстра Ґандлінґа?",a="Ґандлінґ перебуває в Кабінеті Директора на самому дні Сколомансії, куди можна дістатися катакомбами під Каер Дарроу на Озері Дарроумер.",al={"місце ґандлінґа","де ґандлінґ","як знайти ґандлінґа"}}},fp="19,305,23.534.0,23.418.0,27.199.0,40.194.0,43.253.0,35.150.0"}
P.entries["npc:darn-talongrip"] = {n="Дарн Талонґріп",s="Дарн Талонґріп — орк-розвідник, що стоїть на порубіжжі Гір Кам'яного Кігтя біля Малака'джина. Він стежить за місцевими загрозами серед скель і допомагає налагоджувати зв'язок Орди між передовими заставами й командирами краю.",h="Дарн Талонґріп — орк-розвідник, що стоїть на порубіжжі Гір Кам'яного Кігтя біля Малака'джина.",kw={"дарн талонґріп","малака'джин","розвідник","орки","гори кам'яного кігтя","кадрак"},ang={["faction:Horde"]="Дарн Талонґріп першим стоїть на варті на підйомі до Гір Кам'яного Кігтя й стає цінним зв'язковим для шукачів пригод з Орди, що щойно прийшли з Пусток.",["race:Orc"]="Як і багато орків-розвідників, Дарн приймає суворі умови порубіжжя, стоячи на варті серед гострих скель і ворожої звірини."},sec={{t="Порубіжний розвідник Гір Кам'яного Кігтя",b="Дарн Талонґріп наглядає за суворими підйомами, що ведуть із південних Пусток у Гори Кам'яного Кігтя. Служачи в поселенні Малака'джин, Дарн спрямовує новобранців на нові фронти Орди в Ашенвалі. Його пост — один із перших пунктів, де мандрівники, що піднімаються до спірних вершин, можуть знайти своїх."},{t="Очі командування",b="Зі свого поста в Малака'джині Дарн дбає, щоб повідомлення й донесення з передової доходили до ключових командирів — як-от Кадрака на сторожовій вежі в північних Пустках. Віддалені табори в цих горах живуть під постійним тиском, тож служба Дарна як вартового й гінця вкрай важлива, щоб авангард Орди знав про все, що відбувається."}},faq={{q="Хто такий Дарн Талонґріп?",a="Дарн Талонґріп — орк-розвідник, що служить у Малака'джині на півдні Гір Кам'яного Кігтя.",al={"хто такий дарн","особа дарна талонґріпа","хто цей орк"}},{q="Де знайти Дарна Талонґріпа?",a="Його можна знайти в поселенні тролів Малака'джин у Горах Кам'яного Кігтя.",al={"місце дарна","де дарн талонґріп","координати дарна"}},{q="Яка його роль у Горах Кам'яного Кігтя?",a="Дарн посилає новобранців до Кадрака на північ Пусток, щоб допомогти боронити застави Орди в Ашенвалі.",al={"що робить дарн","призначення дарна"}},{q="Хто такий Кадрак і чому Дарн посилає до нього мандрівників?",a="Кадрак — командир Орди на дозорній вежі на півночі Пусток, що очолює похід Орди в Ашенваль. Дарн посилає до нього новобранців, щоб допомогти боронити нові фронти Орди в Ашенвалі.",al={"хто такий кадрак","доповісти кадраку"}}},fp="14,234,28.296.0,20.315.0,22.107.0,34.82.0,31.109.0,55.209.0"}
P.entries["npc:darsok-swiftdagger"] = {n="Дарсок Свіфтдаґґер",s="Дарсок Свіфтдаґґер — орк-воїн і розвідник, що несе службу на Перехресті в самому серці Пусток. Відомий лютою ненавистю до гарпій, він посилає шукачів пригод з Орди на північ, до Сухих Пагорбів, щоб зламати пташиний матріархат, який допікає мандрівникам і поселенням. Він підтримує зв'язки по всіх рівнинах і є довіреною особою Знахаря Джин'Зіла в Малака'джині.",h="Дарсок Свіфтдаґґер — орк-воїн і розвідник, що несе службу на Перехресті в самому серці Пусток.",kw={"дарсок свіфтдаґґер","перехрестя","гарпії","відьмокрилі","серена бладфезер","пустки"},ang={["class:Rogue"]="Виправдовуючи своє ім'я — Свіфтдаґґер, «швидкий кинджал», — Дарсок віддає перевагу точним смертельним ударам по ворожих ватажках, а не виснажливій війні на знищення.",["faction:Horde"]="Для мандрівників Орди Дарсок дає важливі ранні бойові доручення, що захищають торгові шляхи Перехрестя від нападів із повітря.",["race:Orc"]="Дарсок утілює зосереджений бойовий дух орків, яким доручено приборкати й утримати небезпечне прикордоння Калімдору."},sec={{t="Вартовий на Перехресті",b="Серед гамору Перехрестя Дарсок Свіфтдаґґер пильно стежить за загрозами, що виповзають із північних чагарників. Торговий шлях, який з'єднує Дуротар, Малгор і північні краї, постійно в облозі — не лише від грабіжників і кентаврів, а й від злагоджених повітряних мисливців. Свій гнів Дарсок спрямовує на гарпій Відьмокрилих, чиї гнізда в Сухих Пагорбах на північний захід від Забутих ставків прямо загрожують північним караванам."},{t="Війна з Відьмокрилими",b="Дарсок не просто боронить дороги — він організовує точкові удари вглиб володінь гарпій. Його кампанія починається з того, що треба прорідити агресивних гарпій-нальотчиць; потім загартовані бійці мають знищити їхніх ватажок, а зрештою — принести голову їхньої матріархині, Серени Бладфезер. Методично знищуючи верхівку зграї, Свіфтдаґґер прагне розбити хижаків і розпорошити їх по скелях."},{t="Зв'язки серед чагарників",b="Хоч головний обов'язок Дарсока Свіфтдаґґера — винищення гарпій, він ще й важлива ланка в мережі Орди. Він листується зі Знахарем Джин'Зілом — загадковим тролем, що живе в Малака'джині на межі з Горами Кам'яного Кігтя. Звістки й розвідані, що проходять через Дарсока, допомагають віддаленим поселенням знати, що діється на центральних рівнинах."}},faq={{q="Де перебуває Дарсок Свіфтдаґґер?",a="Дарсок Свіфтдаґґер служить на Перехресті — головному поселенні Орди в Пустках. Він готовий скерувати перехожих мандрівників проти північних загроз.",al={"де дарсок","де дарсок свіфтдаґґер","знайти дарсока","місце дарсока"}},{q="Чому Дарсок полює на гарпій?",a="Гарпії-Відьмокрилі гніздяться в каньйонах на північний захід від Забутих ставків і постійно загрожують, мов хижаки, караванам, мандрівникам і розвідникам Орди на північних стежках Пусток.",al={"чому вбивати гарпій","образа дарсока на гарпій","гарпії відьмокрилі пустища"}},{q="Хто така Серена Бладфезер?",a="Серена Бладфезер — жорстока матріарха, що очолює гарпій-Відьмокрилих на Сухих Пагорбах. Дарсок доручає шукачам пригод убити її, щоб розладнати згуртованість і командування зграї.",al={"серена бладфезер","ватажок гарпій пустища","вожак відьмокрилих"}},{q="Що пов'язує Дарсока зі Знахарем Джин'Зілом?",a="Дарсок — союзник і кореспондент Знахаря Джин'Зіла, троля Темного Спису з Малака'джину. Він допомагає їм підтримувати зв'язок і посилає шукачів пригод із листами до віддаленого табору Джин'Зіла.",al={"лист джин'зіла","дарсок і джин'зіл","зв'язок з знахарем джин'зілом"}},{q="Чи підзвітний Дарсок Серґрі Даркторн або Торку?",a="Дарсок організовує свій похід проти гарпій із Перехрестя. Жодне джерело Класики тут не називає ні Серґру Даркторн, ні Торка його безпосереднім начальником.",al={"дарсок торк","кому підзвітний дарсок","керівництво перехрестя"}},{q="Де гніздяться гарпії-Відьмокрилі?",a="Гарпії-Відьмокрилі гніздяться на Сухих Пагорбах — серед зубчастих ярів і круч на північний захід від Забутих ставків на півночі Пусток.",al={"місце відьмокрилих","гарпії сухих пагорбів","де гарпії пустища"}}},fp="18,370,27.449.0,24.425.1,24.426.0,36.164.0,30.202.0,27.182.0,52.205.0,48.147.0,36.165.0"}
P.entries["npc:daryl-the-youngling"] = {n="Деріл Молодий",s="Деріл Молодий — людський мисливець, що живе на Хуторі Далекоходів у південно-східних пагорбах Лох Модану. Прагнучи довести свою влучність досвідченим дворфійським слідопитам, він кидає виклик мандрівним шукачам пригод: відточити вміння виживати в дикій місцині й помірятися силою з місцевими звірами.",h="Деріл Молодий — людський мисливець, що живе на Хуторі Далекоходів у південно-східних пагорбах Лох Модану.",kw={"деріл молодий","хутір далекоходів","мисливець","лох модан","полювання","кабани"},ang={["class:Hunter"]="Деріл говорить мовою слідів, звичок звірів і полювання, тож його змагання — природне випробування для мисливців, які завітали на Хутір Далекоходів.",["race:Human"]="Молодий чоловік, що вчиться жити в дикій місцині глибоко на дворфійських землях, — яскравий знак щирого товариства між Айронфорджем і людськими королівствами."},sec={{t="Людина серед горян",b="Хутір Далекоходів — передусім притулок для дворфійських горян, слідопитів і бувалих лісовиків, які наглядають за дикою місциною Лох Модану. Деріл вирізняється серед них — це молодий чоловік, що прагне заслужити місце поруч із цими досвідченими мисливцями. Він не покладається на саму лише браваду, а залюбки міряється мисливським чуттям з іншими мандрівниками, викликаючи їх полювати на міцних диких кабанів і звірів, що блукають скелями й берегом озера."}},faq={{q="Хто такий Деріл Молодий?",a="Деріл — юний мисливець-людина з Хутора Далекоходів у Лох Модані. Серед бувалих дворфів-стрільців він випробовує новачків мисливськими змаганнями, щоб ті довели свою вправність у полюванні й вистежуванні.",al={"хто такий деріл","лор деріла","хто такий деріл молодий"}},{q="Де знайти Деріла?",a="Деріл перебуває на Хуторі Далекоходів — на лісистих кручах над південно-східними берегами озера в Лох Модані.",al={"місце деріла","де деріл молодий","де знайти деріла"}},{q="Чому його звуть Молодим?",a="Порівняно з досвідченими дворфами-стрільцями й завсідниками хутора, що десятиліттями патрулюють суворі нетрі Каз Модану, Деріл ще молодий і невипробуваний — він тільки здобуває собі славу справжнього мисливця.",al={"чому молодий","прізвисько деріла"}}},fp="19,287,26.448.0,27.203.0,25.127.0,33.236.0"}
P.entries["npc:dashel-stonefist"] = {n="Дешел Стоунфіст",s="Дешел Стоунфіст — сумнозвісний дворф-забіяка, що вештається темними завулками Старого Міста в Стормвінді. Прозваний «Кулаком» за запальну вдачу й важкі руки, він — звична постать міського підпілля. Проте за його бандитською зовнішністю ховаються тихі й небезпечні зв'язки, що привертають увагу таємних слідчих.",h="Дешел Стоунфіст — сумнозвісний дворф-забіяка, що вештається темними завулками Старого Міста в Стормвінді.",kw={"дешел стоунфіст","кулак","старе місто","братство дефіас","зниклий дипломат","забіяка"},ang={["class:Rogue"]="Для розбійників, що пробираються злочинною павутиною Старого Міста, Дешел — приклад агента, який забагато базікає, щойно йому струснуть щелепу, — застереження не довіряти делікатних таємниць грубим м'язам.",["faction:Alliance"]="Дешел уособлює тиху гниль усередині стормвіндської столиці й доводить, що руки Братства Дефіас сягають не лише ферм Вестфолу, а й самого престольного міста.",["race:Dwarf"]="Хоч багато дворфів з Айронфорджу в Стормвінді працюють шанованими ковалями, горянами чи посланцями, Стоунфіст показує, що й дворфи можуть скотитися до вуличного бандитизму й зради."},sec={{t="Забіяка зі Старого Міста",b="Серед вузьких брукованих завулків Старого Міста Дешел Стоунфіст схожий на будь-якого іншого п'яного задерикуватого дворфа, що шукає приводу помахати кулаками. Місцеві й міська варта знають його просто як «Кулака» — прізвисько, здобуте в незліченних вуличних бійках і сутичках біля дверей таверн. Та Дешел — далеко не простий шинковий забіяка: у Старому Місті він опиняється в самому вузлі стормвіндського підпілля, де контрабандисти, кишенькові злодії й політичні підбурювачі обмінюються монетами й чутками подалі від пильних очей Соборної Площі."},{t="Зникнення дипломата",b="Коли високопоставлений дипломат зникає під час таємної подорожі за кордон, королівські слідчі йдуть за шепотом про зраду просто до Дешела. Стоунфіст — вуличний зв'язковий Братства Дефіас у самих мурах Стормвінда, і він має важливі відомості про викрадення. Аж ніяк не охочий інформатор, Дешел відмовляється говорити, доки його не відгамселять, — і тоді виявляється, що змова сягає політики королівства значно глибше, ніж звичайне викрадення."}},faq={{q="Хто такий Дешел Стоунфіст?",a="Дешел Стоунфіст — дворф зі Старого Міста в Стормвінді. Прозваний Кулаком за свою буйну славу й любов до бійок, він дрібний головоріз та інформатор, що осів у темних закутках столиці.",al={"хто такий дешел","хто кулак","лор дешела стоунфіста"}},{q="Де знайти Дешела Стоунфіста?",a="Він стоїть просто неба в Старому Місті в Стормвінді, серед завулків кварталу, неподалік від місць, де збираються розбійники й воїни.",al={"місце дешела","де дешел стоунфіст","знайти дешела"}},{q="Чому слідчим доводиться з ним битися?",a="У розслідуванні зникнення королівського дипломата сліди ведуть просто до Дешела як до спільника. Він запекло вірний своїм темним наймачам і поважає лише силу, тож слідчі мусять здолати його в кулачному бою, перш ніж він розповість, що знає.",al={"чому нападати на дешела","приборкати дешела стоунфіста","бій з дешелом"}},{q="Що пов'язує його з Братством Дефіас?",a="Дешел — внутрішній агент і посланець Братства Дефіас у Стормвінді. Він допомагає координувати місцевих зв'язкових і вуличних громил, щоб приховувати задуми Братства від міської варти.",al={"чи дешел дефіас","дешел стоунфіст дефіас","дефіас у стормвінді"}},{q="Хто той зниклий дипломат, пов'язаний із Дешелом?",a="В офіційній справі, яку ведуть королівські агенти, фігурує безіменний дипломат, що зник дорогою до Терамора.",al={"хто зниклий дипломат","ланцюжок про зниклого дипломата","король варіан зник"}},{q="Чи родич Дешел інших відомих дворфів?",a="Він має те саме прізвище, що й Тельда Стоунфіст, а це натякає на родинний зв'язок, хоча злочинні знайомства Дешела в Стормвінді відділяють його від поважного дворфського товариства.",al={"тельда стоунфіст родичка","родина дешела стоунфіста","родина стоунфістів"}}},fp="16,349,21.557.0,28.482.1,24.221.0,34.149.0,39.272.1,49.213.1,48.107.2,45.164.0"}
P.entries["npc:david-trias"] = {n="Девід Тріас",s="Девід Тріас — наставник розбійників Відступників, що перебуває в Похоронному Подзвоні. Він навчає щойно пробуджених мерців мистецтва скритності, хитрощів і володіння клинком на службі королеві Сильвані й Відступникам.",h="Девід Тріас — наставник розбійників Відступників, що перебуває в Похоронному Подзвоні.",kw={"девід тріас","наставник розбійників","похоронний подзвін","відступники","еллінг тріас","розбійник"},ang={["class:Rogue"]="Для розбійників Відступників Девід Тріас — ваш найперший наставник: він допомагає розшифрувати таємні сувої й навчає обертати холодну точність нежиття на смертоносне володіння клинком.",["race:Undead"]="Девід Тріас утілює похмуру дійсність Відступників: колишні люди Лордерону, чиї минулі життя й родовід відтяла чума, тепер спрямовані на службу королеві Сильвані."},sec={{t="Провідник із тіні",b="Девід Тріас, що влаштувався серед надгробків і руїн Похоронного Подзвону, має виявляти й навчати тих щойно піднятих мерців, у кого є хист до непомітного вбивства. Для молодих Відступників виживання вимагає більшого, ніж сила зброї: воно потребує точних ударів із темряви. Тріас розшифровує накази й навчає посвячених володіти кинджалами, приховувати рухи й обертати свої оживлені рефлекси на смертоносну точність проти живих і Погибелі."},{t="Знайоме ім'я",b="Прізвище Тріас дивно відлунює по всьому континенту. Далеко на півдні, у королівстві Стормвінд, сидить Еллінг Тріас — відомий торговець сиром, який потай підтримує тісні зв'язки з майстрами-розбійниками й начальниками шпигунів. Девід і Еллінг мають одне прізвище, але жодного родинного зв'язку між ними не підтверджено."}},faq={{q="Хто такий Девід Тріас?",a="Девід Тріас — наставник розбійників із Відступників у Похоронному Подзвоні на Галявинах Тірісфалю. Він навчає щойно пробуджених розбійників-Відступників перших бойових прийомів і дає їм перші таємні доручення.",al={"девід тріас","хто такий девід тріас","вчитель розбійників смертельного дзвону"}},{q="Де знайти Девіда Тріаса?",a="Він перебуває в Похоронному Подзвоні — початковому селищі Відступників на Галявинах Тірісфалю: стоїть біля будівель поселення й допомагає новопіднятій нежиті.",al={"місце девіда тріаса","де девід тріас","вчитель розбійників смертельний дзвін"}},{q="Чи родич Девід Тріас Еллінгові Тріасу зі Стормвінда?",a="Він має те саме прізвище, що й Еллінг Тріас зі Стормвінда, але жодного родинного зв'язку не підтверджено.",al={"родич еллінга тріаса","родина тріасів","чи родич еллінга тріаса"}},{q="Яку роль він відіграє в навчанні Відступників?",a="Новачків-розбійників, що виходять зі склепу Похоронного Подзвону, направляють до Девіда Тріаса із зашифрованим сувоєм. Він розшифровує їхні вказівки, веде їхнє початкове навчання й ставить на шлях скритних агентів Відступників.",al={"завдання девіда тріаса","зашифрований сувій","чого він навчає"}}},fp="11,194,24.477.0,15.308.1,19.198.0,29.162.0,52.92.0,44.246.0"}
P.entries["npc:dawnwatcher-selgorm"] = {n="Дозорець Світанку Селґорм",s="Дозорець Світанку Селґорм — людина, представник Срібного Світанку на Терасі Ремісників у Дарнасусі. Як спостерігач і посередник у столиці нічних ельфів, він стежить за донесеннями про діяльність темних культів і похмурі загрози, що ворушаться на півночі Калімдору.",h="Дозорець Світанку Селґорм — людина, представник Срібного Світанку на Терасі Ремісників у Дарнасусі.",kw={"дозорець світанку селґорм","срібний світанок","дарнасус","тераса ремісників","чорноглибинні печери","молот присмерку"},ang={["faction:Alliance"]="Для шукачів пригод з Альянсу, що досліджують північ Калімдору, Селґорм — важлива ланка між Дарнасусом і походом проти лиховісних культів, що ховаються на узбережжі.",["race:Human"]="Людські мандрівники, що відвідують далеке гілля Тельдрассила, можуть утішитися зустріччю зі співвітчизником, що служить шляхетному Срібному Світанку."},sec={{t="Очі у Світовому Дереві",b="Хоч Срібний Світанок здебільшого зосереджений на нежиті Погибелі, що гниє у Східних Чумних землях, його пильність сягає всюди, де пускає коріння давнє зло. Дозорець Світанку Селґорм несе варту в Дарнасусі, поєднуючи замкнених у собі нічних ельфів із ширшим походом проти злоби. З Тераси Ремісників він збирає відомості про нові загрози в дикій глушині Калімдору й залучає вправних мандрівників з Альянсу, щоб ударити по сектантах і темних силах, перш ніж їхній вплив зіпсує край."},{t="Удар по темряві",b="Найбільше Селґорма непокоять Чорноглибинні Печери на Зорамському Березі Ашенвалю. Бачачи мерзенне єднання культу Молота Присмерку й зміїних наг під хвилями, він винагороджує досвідчених звитяжців, що вирушають у затоплені руїни. Б'ючи по лиходійських ватажках культу й повертаючи осквернені реліквії, він сподівається вгамувати тіні, що згущуються над священними берегами Калімдору."}},faq={{q="Хто такий Дозорець Світанку Селґорм?",a="Дозорець Світанку Селґорм — агент Срібного світанку, людина. Він служить у Дарнасусі, столиці нічних ельфів, щоб стежити за злом, яке підкрадається до Калімдору.",al={"селґорм","хто такий селґорм","лор дозорця селґорма"}},{q="Де знайти Дозорця Світанку Селґорма?",a="Він стоїть просто неба на Терасі Ремісників у Дарнасусі, звідки видно гамірні майстерні столиці нічних ельфів.",al={"місце селґорма","де селґорм","селґорм дарнасус"}},{q="Чому член Срібного Світанку служить у Дарнасусі?",a="Срібний Світанок славиться боротьбою з Погибеллю в Лордероні, але орден присвятив себе викоріненню зла будь-де. Селґорм стежить за дедалі активнішими культами, як-от Молот Присмерку, на півночі Калімдору.",al={"срібний світанок у дарнасусі","чому срібний світанок тут"}},{q="Що Селґорм доручає шукачам пригод?",a="Селґорм чекає героїв Альянсу, що повертаються з Чорноглибинних Печер в Ашенвалі з головою сутінкового володаря Келріса, ватажка тамтешнього Молота Присмерку: поранений Срібний Вартовий Таелрід закликає їх убити його, щоб зупинити поширення скверни культу.",al={"завдання селґорма","видавець завдання чорноглибинних печер"}}},fp="19,276,22.517.0,25.401.1,27.159.0,39.139.0,52.224.0,40.255.0"}
P.entries["npc:dawnwatcher-shaedlass"] = {n="Дозорець Світанку Шедласс",s="Дозорець Світанку Шедласс — нічний ельф, пов'язаний зі Срібним Світанком, що несе службу на Терасі Ремісників у Дарнасусі. Він — тихі очі й вуха ордену в Калімдорі й шукає звісток про своїх побратимів, яких послали в небезпечну розвідку на ворожі землі.",h="Дозорець Світанку Шедласс — нічний ельф, пов'язаний зі Срібним Світанком, що несе службу на Терасі Ремісників...",kw={"дозорець світанку шедласс","срібний світанок","таелрід","дарнасус","чорноглибинні печери","нічні ельфи"},ang={["faction:Alliance"]="Шедласс дає героям Альянсу в Дарнасусі прямий зв'язок із таємницями Чорноглибинних Печер і посилає розвідників рятувати агента глибоко в тилу ворога.",["race:NightElf"]="Як один із небагатьох нічних ельфів, що відкрито служать під стягом Срібного Світанку, Шедласс поєднує замкнену в собі політику Тельдрассила зі світовою вартою проти темряви."},sec={{t="Очі Срібного Світанку",b="Срібний Світанок найбільше відомий своїм запеклим походом проти Погибелі у Східних Чумних землях, але його пильність сягає далеко за межі Лордерону. Дозорець Світанку Шедласс представляє орден у столиці нічних ельфів, Дарнасусі, і пильнує його інтереси в Калімдорі. Зі свого тихого посту на Терасі Ремісників він стежить за таємними вилазками проти темних культів і згубних сил, що загрожують усьому світові."},{t="Зниклий брат",b="Найбільше Шедласса непокоїть доля Срібного Вартового Таелріда — побратима, якого послали на південь перевірити донесення про підступну діяльність культу в Чорноглибинних Печерах на узбережжі Ашенвалю. Побоюючись, що Таелрід став жертвою Молота Присмерку й морських жахіть прадавнього ельфійського храму, Шедласс залучає відважних шукачів пригод з Альянсу, щоб ті проникли в руїни й з'ясували долю розвідника."}},faq={{q="Хто такий Дозорець Світанку Шедласс?",a="Дозорець Світанку Шедласс — нічний ельф, агент Срібного світанку. Він служить на Терасі Ремісників у Дарнасусі як зв'язковий і контактна особа ордену на півночі Калімдору.",al={"хто такий шедласс","лор дозорця шедласса","нпс срібного світанку дарнасус"}},{q="Чому член Срібного Світанку перебуває в Дарнасусі?",a="Хоч Срібний Світанок воює передусім із Погибеллю в Лордероні, він тримає пильних агентів по всьому Азероту, щоб вистежувати згубне зло. Шедласс збирає відомості й стежить за загрозами, що назрівають по всьому Калімдору, зокрема за темними культами.",al={"чому срібний світанок у дарнасусі","срібний світанок нічний ельф"}},{q="Що Шедласс доручає шукачам пригод?",a="Шедласс посилає шукачів пригод з Альянсу до затопленого храму Чорноглибинних Печер у завданні «У пошуках Таелріда». Він доручає їм знайти Срібного Вартового Таелріда — таємного розвідника, що пішов у руїни розслідувати діяльність Молота Присмерку й так і не повернувся зі звітом.",al={"завдання шедласса","завдання в пошуках телріда"}},{q="Де знайти Дозорця Світанку Шедласса?",a="Він перебуває в Дарнасусі на Терасі Ремісників, неподалік від торговців і ремісників столиці.",al={"місце шедласса","де дозорець шедласс"}}},fp="21,273,23.442.0,17.434.1,29.204.0,42.256.0,42.278.0,39.116.0"}
P.entries["npc:dazalar"] = {n="Дазалар",s="Дазалар — наставник мисливців, нічний ельф, що перебуває в Доланаарі на Тельдрассилі. Він веде молодих вартових і розвідників, поки ті відточують влучність і опановують священне мистецтво зріднення з дикими звірами великого віття.",h="Дазалар — наставник мисливців, нічний ельф, що перебуває в Доланаарі на Тельдрассилі.",kw={"дазалар","мисливець","наставник","доланаар","тельдрассил","приборкання звірів","тінедол"},ang={["class:Hunter"]="Дазалар — один із найперших наставників, яких зустрічає мисливець — нічний ельф; він веде вас крізь основні випробування влади над звірами й навчання улюбленця.",["race:NightElf"]="Він підтримує традиції калдорейських вартових і розвідників, навчаючи молодих нічних ельфів жити в рівновазі з лютими хижаками природи."},sec={{t="Табір у Доланаарі",b="Перебуваючи в поселенні Доланаар, Дазалар — головний наставник молодих мисливців, що виходять за межі затишної долини Тінедолу. Суспільство нічних ельфів значною мірою покладається на своїх рейнджерів і вартових, які патрулюють нетрі, і Дазалар дбає, щоб новачки мали дисципліну й терпіння, потрібні для захисту крихкого живого світу Тельдрассила."},{t="Зріднення з дикою природою",b="Ключовий обряд посвяти під проводом Дазалара — навчитися приборкувати звірів і дбати про них. Замість гнути створінь під волю мисливця грубою силою, калдорейський звичай наголошує на взаємній угоді з лісовими хижаками — нічними шаблезубами, совами й стригідними мисливцями, — і вчить їх битися пліч-о-пліч із господарями з повагою."}},faq={{q="Хто такий Дазалар?",a="Дазалар — наставник мисливців із нічних ельфів у селищі Доланаар на Тельдрассилі. Він навчає мисливців-початківців нових бойових умінь і веде їх шляхом приборкання диких звірів.",al={"хто такий дазалар","лор дазалара","особа дазалара"}},{q="Де знайти Дазалара?",a="Він стоїть просто неба в Доланаарі — центральному поселенні Тельдрассила, до якого шукачі пригод доходять невдовзі після того, як покидають початкові землі Тінедолу.",al={"місце дазалара","де дазалар","вчитель мисливців доланаару"}},{q="Чого навчає Дазалар?",a="Дазалар навчає молодих мисливців різних дальніх атак, пасток і прийомів виживання, а ще посилає новачків на випробування, щоб вони опанували приборкання диких тварин.",al={"чого навчає дазалар","навички дазалара","навчання мисливців дазалар"}},{q="Чи дає Дазалар якісь особливі завдання?",a="Так, Дазалар дає ключові навчальні завдання мисливця, зокрема «Шлях мисливця», багатоетапне випробування «Приборкання звіра» та «Навчання звіра», які вчать молодих мисливців єднатися зі звірами-супутниками й доглядати їх.",al={"завдання дазалара","завдання мисливців доланаару","завдання приборкання звіра"}},{q="Чому нічні ельфи так покладаються на мисливців?",a="Тисячоліттями калдореї жили в злагоді з прадавніми лісами Калімдору. Лучники й розвідники — кістяк війська Вартових: скритність, влучність і звірі-союзники допомагають їм берегти свої землі, не порушуючи природи.",al={"лор мисливців нічних ельфів","чому вартові використовують мисливців","мисливці калдорей"}},{q="Яких звірів Дазалар посилає мисливців приборкувати?",a="Він посилає мисливців вистежувати корінну живність Тельдрассила — місцевих павуків, нічних шаблезубів і хижих птахів, — перевіряючи, чи здатен мисливець наблизитися до дикого хижака й заспокоїти його.",al={"яких звірів приборкувати","випробування приборкання доланаар","звірі тельдрассила для приборкання"}}},fp="7,229,23.355.0,21.340.0,15.185.0,25.148.0,35.178.0,38.218.0,46.249.0,54.180.0"}
P.entries["npc:deathguard-bartholomew"] = {n="Вартовий Смерті Бартоломью",s="Вартовий Смерті Бартоломью — пильний солдат Відступників, що несе службу в містечку Брілл. Відповідаючи за безпеку на Галявинах Тірісфалю, він допомагає мандрівникам орієнтуватися в ураженому поселенні й підтримує дисципліну серед місцевих захисників.",h="Вартовий Смерті Бартоломью — пильний солдат Відступників, що несе службу в містечку Брілл.",kw={"вартовий смерті бартоломью","варта","брілл","галявини тірісфалю","відступники","дорога"},ang={["faction:Horde"]="Союзники, що прибувають із Калімдору, можуть покластися на Бартоломью, щоб зорієнтуватися на оповитих імлою вулицях Брілла.",["race:Undead"]="Для щойно звільнених Відступників, що виходять із Похоронного Подзвону, вартові на кшталт Бартоломью у Бріллі — перше організоване обличчя регулярної армії Леді Сильвани."},sec={{t="Вартовий Брілла",b="Стоячи на варті в поселенні Брілл, Вартовий Смерті Бартоломью уособлює стійкий військовий хребет Відступників. Як і його побратими Вартові Смерті по всіх Галявинах Тірісфалю, він захищає відвойовану землю від недобитків Погибелі, фанатичних багряних хрестоносців і будь-яких інших загроз володінням Леді Сильвани. Окрім варти, він підказує дорогу мандрівникам, що намагаються знайти міські служби, і допомагає підтримувати лад серед щойно піднятих."}},faq={{q="Хто такий Вартовий Смерті Бартоломью?",a="Вартовий Смерті Бартоломью — вартовий-Відступник із Брілла на Галявинах Тірісфалю. Він стоїть на посту, охороняючи містечко, і показує мандрівникам, де що знайти.",al={"бартоломью","хто такий бартоломью","лор вартового смерті бартоломью"}},{q="Яка роль Вартових Смерті?",a="Вартові Смерті — головна піхота й оборонна сила Відступників. Вони патрулюють землі Лордерону, захищають поселення на кшталт Брілла від Погибелі й Багряного Хрестового Походу та підтримують лад від імені Темної Леді.",al={"хто такі вартові смерті","фракція вартових смерті","охорона відступників"}},{q="Чи може Вартовий Смерті Бартоломью підказати дорогу?",a="Так. Як і багато міських вартових по всьому Азероту, Бартоломью може підказати мандрівникам, де в Бріллі наставники, корчма й торговці ремісничим товаром.",al={"де корчма","шлях по бріллу","дорога у бріллі від вартового"}}},fp="22,253,17.495.0,30.173.0,35.236.0,43.172.0"}
P.entries["npc:deathguard-burgess"] = {n="Вартовий Смерті Берджесс",s="Вартовий Смерті Берджесс — вартовий Відступників, що несе службу в містечку Брілл на Галявинах Тірісфалю. Стоячи на сторожі поселення, він підтримує лад і скеровує мандрівників до потрібних служб селища.",h="Вартовий Смерті Берджесс — вартовий Відступників, що несе службу в містечку Брілл на Галявинах Тірісфалю.",kw={"вартовий смерті берджесс","варта","брілл","андерсіті","відступники","служби"},ang={["faction:Horde"]="Союзники з Калімдору можуть звернутися до Берджесса, щоб зорієнтуватися в незнайомому, ураженому плануванні Брілла, шукаючи торговців припасами чи відпочинку в корчмі.",["race:Undead"]="Для щойно пробуджених Відступників, що покидають Похоронний Подзвін, вартові на кшталт Берджесса у Бріллі — ваше перше знайомство з ширшою інфраструктурою Лордерону."},sec={{t="Сторож у Бріллі",b="Вартовий Смерті Берджесс, що стоїть у поселенні Брілл одразу на північ від Андерсіті, — один із міських вартових, які бережуть його від двох напастей: це Погибель і Багряний Хрестовий Похід. Як і інші Вартові Смерті по всіх Галявинах Тірісфалю, Берджесс допомагає новоприбулим Відступникам, підказуючи дорогу до місцевих ремісників, наставників класів і міських служб, щоб уразливий форпост працював без збоїв."}},faq={{q="Хто такий Вартовий Смерті Берджесс?",a="Вартовий Смерті Берджесс — вартовий із нежиті, що служить Відступникам у містечку Брілл. Він допомагає підтримувати лад у селищі й підказує гостям, де знайти місцевих наставників та інші важливі місця.",al={"берджесс брилл","хто такий берджесс","лор вартового смерті берджесса"}},{q="Яку роль Вартові Смерті відіграють у Бріллі?",a="Вартові Смерті — звичайна військова й поліційна сила Відступників. У місцях на кшталт Брілла вони захищають жителів від зовнішніх загроз, як-от Погибель і Багряний Хрестовий Похід, і підтримують громадський лад.",al={"хто такі вартові смерті","роль вартових смерті"}},{q="Чи може Вартовий Смерті Берджесс підказати дорогу?",a="Так. Як і багато міських вартових по всьому Азероту, Берджесс підкаже мандрівникам, де в Бріллі наставники класів, місцева корчма, майстри ремесел та інші важливі місця.",al={"шлях від берджесса","куди йти в бріллі"}}},fp="18,204,19.392.0,26.194.0,44.221.0,42.197.0"}
P.entries["npc:deathguard-dillinger"] = {n="Вартовий Смерті Діллінджер",s="Вартовий Смерті Діллінджер — вартівник Відступників у Бріллі, у Галявинах Тірісфалю. Пильнуючи околиці містечка, він скеровує новоприбулих мерців до потрібних служб і доручає новобранцям тримати на відстані рештки Погибелі.",h="Вартовий Смерті Діллінджер — вартівник Відступників у Бріллі, у Галявинах Тірісфалю.",kw={"вартовий смерті діллінджер","брілл","варта смерті","погибель","гулі","улаг різник","відступники"},ang={["class:Warrior"]="Майбутні воїни Відступників часто працюють безпосередньо з Діллінджером, випробовуючи бойовий гарт проти лютих гулів і кістяних страхіть, що нишпорять околицями Брілла.",["faction:Horde"]="Діллінджер утілює боротьбу Відступників за надійний плацдарм у північному Лордероні й показує союзникам з Орди невпинну загрозу безтямної Погибелі на їхньому порозі.",["race:Undead"]="Для щойно звільнених Відступників, що приходять із Похоронного Подзвону, Діллінджер часто стає першим обличчям військової влади: він скеровує їх на навчання й до перших обов'язків на службі в Сильвани."},sec={{t="Вартовий Брілла",b="Як член Варти Смерті Відступників, Діллінджер стоїть біля входу до Брілла — водночас захисник передової й провідник для подорожніх, що приходять із Похоронного Подзвону. Він підказує дорогу до корчми, ратуші й місцевих наставників, допомагаючи щойно пробудженим мерцям зорієнтуватися в новій дійсності під владою Темної Леді."},{t="Убезпечення прикордоння",b="Діллінджер активно залучає здібних шукачів пригод вичищати залишки безтямної Погибелі з сусідніх ферм і млинів. Через такі доручення, як винищення гнилих гулів і повернення заражених господарств, він прагне створити довкола Брілла смугу безпеки, щоб молоді поселення Відступників встояли перед нескінченними набігами нежиті."},{t="Стримування безтямних страхіть",b="Окрім звичайних патрулів, Діллінджер керує відсіччю невідступним загрозам Погибелі, що чаяться в руїнах довкола Брілла. Коли з сусідніх гробниць чи покинутих садиб виринають покликані страхіття на кшталт Улага Різника, Діллінджер дбає, щоб здібних бійців вислали покінчити з шаленими чудовиськами, перш ніж ті прорвуться за межі поселення."}},faq={{q="Де знайти Вартового Смерті Діллінджера?",a="Вартовий Смерті Діллінджер стоїть на посту на околиці Брілла в центрі Галявин Тірісфалю й пильнує стежку до містечка.",al={"місце діллінджера","де діллінджер","координати вартового смерті діллінджера"}},{q="Яка роль Вартових Смерті?",a="Вартові Смерті — постійна армія й варта Відступників: вони охороняють поселення на кшталт Брілла й Андерсіті від Погибелі, Багряного Хрестового Походу та інших загроз краю.",al={"що таке вартовий смерті","хто такі вартові смерті","призначення вартових смерті"}},{q="Які доручення дає Вартовий Смерті Діллінджер?",a="Діллінджер доручає шукачам пригод нищити бездумну Погибель, що блукає довколишніми полями й млинами, повертати важливі місцеві споруди й упоратися з небезпечними створіннями на кшталт Улага Різника.",al={"завдання діллінджера","які завдання у діллінджера"}},{q="Чи може Вартовий Смерті Діллінджер підказати дорогу?",a="Так, у Діллінджера можна спитати, де в Бріллі важливі служби, наставники ремесел і наставники класів.",al={"шлях від діллінджера","спитати діллінджера про допомогу"}},{q="Чому Відступники біля Брілла б'ються з іншою нежиттю?",a="Бездумна нежить, що блукає Тірісфалем, і досі під владою Погибелі й Короля-Ліча. Відступники, що вирвалися з-під цієї влади над розумом, мусять знищувати ці здичавілі рештки, щоб захистити власні землі.",al={"чому битися з нежиттю","нежить проти нежиті","гулі брилла"}},{q="Хто такий Улаг Різник?",a="Улаг Різник — небезпечне жахіття Погибелі, пов'язане з сусідніми гробницями за Бріллом. Діллінджер разом із новобранцями-Відступниками викликає й знищує Улага, щоб уберегти околиці.",al={"завдання улага","хто такий улаг","улаг різник"}}},fp="20,251,17.361.0,24.352.0,27.354.1,38.121.0,35.205.0,43.199.0,44.153.0,54.220.0,24.189.0"}
P.entries["npc:deathguard-humbert"] = {n="Вартовий Смерті Гумберт",s="Вартовий Смерті Гумберт — вартовий-Відступник, що служить у Таррен Міллі в Передгір'ї Гілсбреда. Йому доручили стежити за дедалі ближчою присутністю Альянсу, але він потрапив у прикру халепу, втративши своє військове спорядження через дворфів Дун Ґарока.",h="Вартовий Смерті Гумберт — вартовий-Відступник, що служить у Таррен Міллі в Передгір'ї Гілсбреда.",kw={"вартовий смерті гумберт","таррен мілл","дун ґарок","меч гумберта","відступники","передгір'я гілсбреда"},ang={["faction:Horde"]="Повернення загубленого меча Гумберта — удар у відповідь по зухвалому дворфійському плацдарму в Гілсбреді, що водночас береже гідність гарнізону Таррен Мілла.",["race:Undead"]="Від солдатів-Відступників чекають невтомної пильності на службі Темній Леді, тож неуважність Гумберта перед живими — ганебна пляма на Вартових Смерті."},sec={{t="Вартовий без сталі",b="Охороняючи периметр Таррен Мілла від місцевих загроз, Вартовий Смерті Гумберт зазнав принизливої невдачі від горян Дун Ґарока. Дворфи з гарнізону Дун Ґарока забрали в Гумберта його цінний меч і різне спорядження, і тепер мертвий вояк відчайдушно прагне повернути собі гідність і зброю, перш ніж про це дізнається командування."}},faq={{q="Хто такий Вартовий Смерті Гумберт?",a="Вартовий Смерті Гумберт — воїн-Відступник, що служить розвідником і вартовим у Таррен Міллі. Він має стежити за ворожими діями Альянсу по всьому Передгір'ю Гілсбреда.",al={"лор гумберта","хто такий гумберт","гумберт таррен мілл"}},{q="Що сталося з мечем і обладунками Гумберта?",a="Розвідуючи південні передгір'я, Гумберт натрапив на дворфів із фортеці Дун Ґарок. Дворфи подолали його й забрали його зброю та обладунки, зокрема його вірний клинок.",al={"меч гумберта вкрадено","хто взяв спорядження гумберта","чому гумберту потрібна допомога"}},{q="Чому Гумберт сам не поверне своє спорядження?",a="Дун Ґарок добре укріплений, і там стоять дисципліновані дворфи-стрільці й горяни. Самотній розвідник під його окопами не має шансів, а покинути пост Гумберт не може, не пояснивши, як узагалі втратив своє спорядження.",al={"чому гумберт не може битися","гумберт дан ґарок"}}},fp="18,259,29.373.0,26.188.0,43.220.0,50.250.0"}
P.entries["npc:deathguard-linnea"] = {n="Вартова Смерті Ліннея",s="Вартова Смерті Ліннея — солдатка Відступників, що несе службу на заставі Вартових Смерті на південному сході Галявин Тірісфалю. Вона допомагає убезпечити дороги між Бріллом і східними кордонами, пильнуючи дві загрози: Багряний Хрестовий Похід і недобитки Погибелі. Шукачі пригод, що проходять головними шляхами, часто допомагають її загонові з патрулюванням.",h="Вартова Смерті Ліннея — солдатка Відступників, що несе службу на заставі Вартових Смерті на південному сході...",kw={"вартова смерті ліннея","застава","патруль","дороги","магістрат севрен","галявини тірісфалю"},ang={["faction:Horde"]="Союзники Відступників, що перетинають Галявини Тірісфалю, можуть заслужити прихильність, допомагаючи Ліннеї стабілізувати віддалені дороги проти ворожих сил.",["race:Undead"]="Для Відступників, щойно піднятих у Похоронному Подзвоні, допомога Вартовій Смерті Ліннеї на заставі — один із найперших обов'язків заради убезпечення кордонів їхнього нового королівства."},sec={{t="Варта при дорозі",b="Вартова Смерті Ліннея стоїть на чатах біля невеликої укріпленої застави на південний схід від Брілла. Життя — чи то пак нежиття — в патрулі на Галявинах Тірісфалю небезпечне: Відступники мусять невсипно боронити своє молоде володіння від лазутчиків Багряного Хрестового Походу й безтямної Погибелі, що никає хащами. Разом зі своїми побратимами-вартовими Ліннея керує патрулюванням уздовж дороги й узгоджує донесення з місцевою владою, як-от Магістратом Севреном у Бріллі, щоб південний підступ до володіння лишався безпечним."}},faq={{q="Хто така Вартова Смерті Ліннея?",a="Ліннея — воїтелька з нежиті, що служить серед Вартових Смерті, війська, якому доручено захищати землі Відступників. Вона стоїть на придорожньому посту Вартових Смерті на південний схід від Брілла на Галявинах Тірісфалю.",al={"ліннея","лор вартової смерті ліннеї","хто така ліннея"}},{q="Чому їй потрібна допомога в патрулюванні?",a="Військові сили Відступників розпорошені по всіх Галявинах Тірісфалю. Ліннея покладається на мандрівників і звитяжців, що набираються сили, щоб ті допомогли розчистити околиці від загроз і гінці та постачальники могли безпечно ходити до Брілла й назад.",al={"патрулювання тилової варти","чому допомагати ліннеї"}}},fp="17,339,23.501.0,25.211.0,34.247.0"}
P.entries["npc:deathguard-samsa"] = {n="Вартовий Смерті Самса",s="Вартовий Смерті Самса — вартовий-Відступник, що служить у Таррен Міллі в Передгір'ї Гілсбреда. Пильнуючи напружене прикордоння Орди, він скеровує мандрівних поборників нищити місцеві загрози, що підступають до поселення.",h="Вартовий Смерті Самса — вартовий-Відступник, що служить у Таррен Міллі в Передгір'ї Гілсбреда.",kw={"вартовий смерті самса","таррен мілл","передгір'я гілсбреда","відступники","саутшор","застава"},ang={["faction:Horde"]="Мандрівники Орди, що проходять Передгір'ям Гілсбреда, покладаються на вартових на кшталт Самси, які організовують оборону від нападів Альянсу із сусіднього Саутшора.",["race:Undead"]="Для Відступників Вартовий Смерті Самса уособлює прагматичну й похмуру оборону, потрібну, щоб утримати південний кордон Лордерону від ворожих сусідів."},sec={{t="Прикордонний вартовий Таррен Мілла",b="Вартовий Смерті Самса, що стоїть на варті в Таррен Міллі, — частина оборонного хребта Відступників у спірному Передгір'ї Гілсбреда. Таррен Мілл — головна застава Орди в цьому краї, на яку безпосередньо тиснуть застави Альянсу на кшталт Саутшора, а також дикі місцеві звірі. Обов'язки Самси — убезпечувати периметр і скеровувати вправних шукачів пригод, щоб ті знищували загрози, перш ніж вони стануть небезпечними для табору."}},faq={{q="Хто такий Вартовий Смерті Самса?",a="Вартовий Смерті Самса — воїн із нежиті на службі війська Відступників у Таррен Міллі. Він охороняє містечко й дає доручення шукачам пригод, щоб убезпечити край від довколишніх небезпек.",al={"самса","хто такий самса","роль вартового смерті самси"}},{q="Де знайти Вартового Смерті Самсу?",a="Він перебуває в Таррен Міллі — великому поселенні Орди в північній частині Передгір'я Гілсбреда.",al={"місце самси","де вартовий смерті самса","місце охоронця таррен мілла"}},{q="Які доручення дає Вартовий Смерті Самса?",a="Самса посилає шукачів пригод у дикі краї Гілсбреда, зокрема збирати черепи людей Гілсбреда, убитих під час походу Орди проти них.",al={"завдання самси","видавець сувенірів смерті"}}},fp="16,244,30.437.0,24.201.0,34.114.0,42.171.0"}
P.entries["npc:deathguard-simmer"] = {n="Вартовий Смерті Сіммер",s="Вартовий Смерті Сіммер — солдат Відступників, що несе службу одразу за межами Похоронного Подзвону на Галявинах Тірісфалю. Він придивляється до щойно піднятих Відступників й посилає їх грабувати людську гарбузову ферму на заході, яку патрулює Багряний Хрестовий Похід, по реагенти, потрібні аптекарям Брілла.",h="Вартовий Смерті Сіммер — солдат Відступників, що несе службу одразу за межами Похоронного Подзвону на...",kw={"вартовий смерті сіммер","похоронний подзвін","хутір соллідена","гарбузи","багряний хрестовий похід","аптекар йогаан"},ang={["race:Undead"]="Сіммер дає одні з перших завдань, спрямованих безпосередньо проти Багряного Хрестового Походу, і знаменує випуск шукача пригод-нежиті зі склепів Похоронного Подзвону до ширшої оборони Лордерону."},sec={{t="Охоронець за межами Похоронного Подзвону",b="Вартовий Смерті Сіммер, поставлений одразу за межами Похоронного Подзвону, уособлює військову лінію Відступників, що тримає кордон між безпечним прихистком Похоронного Подзвону й ширшими небезпеками Галявин Тірісфалю. Край кишить живими людьми — насамперед фанатиками Багряного Хрестового Походу, — які мають усю нежить за гидоту, що її належить вичистити вогнем і клинком. Сіммер випробовує молодих Відступників, посилаючи їх на захід — туди, де лежить Хутір Соллідена і де з сусідньої вежі патрулює Багряний Хрестовий Похід, — щоб украсти десять гарбузів і віднести їх Аптекареві Йогаану в Брілл."}},faq={{q="Хто такий Вартовий Смерті Сіммер?",a="Вартовий Смерті Сіммер — вартовий-Відступник, що стоїть одразу за Похоронним Подзвоном на Галявинах Тірісфалю. Він випробовує молодих Відступників, посилаючи їх красти гарбузи з людської ферми, яку патрулює Багряний Хрестовий Похід.",al={"вартовий смерті сіммер","хто такий сіммер","сіммер нпс"}},{q="Де перебуває Вартовий Смерті Сіммер?",a="Він стоїть одразу за Похоронним Подзвоном на південному заході Галявин Тірісфалю, на дорозі, якою новопідняті Відступники виходять зі склепів.",al={"місце вартового смерті сіммера","де сіммер","знайти вартового смерті сіммера"}},{q="З якими загрозами бореться Вартовий Смерті Сіммер?",a="Сіммер зневажає живих людей, що досі обробляють землю Тірісфалю, і Багряний Хрестовий Похід, що патрулює біля них. Він посилає молодих Відступників грабувати гарбузи на Хуторі Соллідена — і людей провчити, і аптекарів Брілла забезпечити.",al={"вороги сіммера","з ким воює сіммер","завдання багряної огорожі"}}},fp="17,264,27.543.0,25.206.0,35.126.0,42.252.0"}
P.entries["npc:deathstalker-faerleia"] = {n="Скрадачка Смерті Фаерлея",s="Скрадачка Смерті Фаерлея — агентка розвідки Відступників, що діє глибоко на ворожій землі, у Селі Пайрвуд. Зі своєї схованки в ратуші поселення вона влаштовує таємні удари по місцевій ґілнеаській верхівці.",h="Скрадачка Смерті Фаерлея — агентка розвідки Відступників, що діє глибоко на ворожій землі, у Селі Пайрвуд.",kw={"скрадачка смерті фаерлея","село пайрвуд","рада пайрвуда","скрадачі смерті","відступники","срібнолісся"},ang={["class:Rogue"]="Для розбійників на службі Відступників Фаерлея — вершина польової майстерності скрадачів смерті: непомітно прослизнути просто в осередок ворожої влади й улаштувати засідку.",["race:Undead"]="Фаерлея — приклад того, як скрадачі смерті покладаються на проникнення й холодний розрахунок, щоб розбивати ворогів Темної Леді, не кидаючи в бій цілу армію."},sec={{t="У ворожому тилу",b="Як агентка скрадачів смерті — таємної розвідки й убивць Андерсіті, — Фаерлея має завдання пробратися в Село Пайрвуд у південному Срібноліссі. Цей відрізаний людський анклав ховає темні таємниці, зокрема прокляття, що під нічним небом перетворює його мешканців. Засівши на верхніх поверхах ратуші, Фаерлея налагоджує операції, щоб розхитати поселення зсередини, і закликає агентів Орди знищити впливових членів Ради Пайрвуда."}},faq={{q="Хто така Скрадачка Смерті Фаерлея?",a="Вона агентка скрадачів смерті — розвідувального підрозділу Відступників Королеви Сильвани Віндраннер, що діє потай. Вона пробралася до Села Пайрвуд, щоб вести таємну війну проти його проводу.",al={"фаерлея","хто така фаерлея","скрадачка смерті фаерлея"}},{q="Де знайти Скрадачку Смерті Фаерлею?",a="Фаерлея ховається в ратуші Села Пайрвуд на півдні Срібнолісся, трохи на північ від Стіни Ґреймейна.",al={"де фаерлея","місце фаерлеї","знайти фаерлею"}},{q="Яке доручення вона дає?",a="Вона керує шукачами пригод у «Засідці в Пайрвуді» — операції з усунення радників, що правлять Селом Пайрвуд, щоб послабити опір поселення Відступникам.",al={"завдання фаерлеї","завдання засідки пайрвуда"}},{q="Чому скрадачі смерті полюють на Село Пайрвуд?",a="Пайрвуд — досі живе людське поселення, пов'язане з Ґілнеасом, просто на межі земель Відступників. Послабивши його провід, можна вберегти Срібнолісся від ворожих загроз.",al={"чому нападати на пайрвуд","скрадачі смерті в пайрвуді"}}},fp="21,251,18.516.0,29.203.0,41.136.0,27.174.0,53.188.0"}
P.entries["npc:deathstalker-lesh"] = {n="Скрадач Смерті Леш",s="Скрадач Смерті Леш — розбійниця-Відступниця, що служить передовою розвідницею у Вежі Південного Мису в Передгір'ї Гілсбреда. Підпорядкована безпосередньо Верховному Екзекуторові Дарталії, вона стежить за людськими фермами на Полях Гілсбреду, щоб визначити, коли Відступникам час завдати удару.",h="Скрадач Смерті Леш — розбійниця-Відступниця, що служить передовою розвідницею у Вежі Південного Мису в...",kw={"скрадач смерті леш","скрадачі смерті","вежа південного мису","поля гілсбреду","дарталія","розвідка"},ang={["class:Rogue"]="Скрадач Смерті Леш показує, яку важливу військову роль відіграють таємні агенти у війні Орди.",["race:Undead"]="Для Відступників розвідники на кшталт Леш виконують життєво важливу прикордонну роботу, оберігаючи Лордерон від відродження Альянсу."},sec={{t="Очі над полями",b="Зі своєї позиції у Вежі Південного Мису над південною дорогою через Передгір'я Гілсбреда Скрадач Смерті Леш стежить за людськими фермерами й міським ополченням, що працюють на сусідніх Полях Гілсбреду. Як агентка скрадачів смерті — таємної мережі розвідників і вбивць Відступників, — Леш відстежує пересування й чисельність ворога для Верховного Екзекутора Дарталії в Таррен Міллі. Коли людська оборона слабшає, Леш спрямовує точкові напади, щоб тримати людей Альянсу в розгубленості й прокласти шлях для просування Відступників на південь."}},faq={{q="Хто такий Скрадач Смерті Леш?",a="Леш — розвідниця-Відступниця з Вежі Південного Мису. Вона підзвітна Верховному Екзекуторові Дарталії в Таррен Міллі й стежить за діями людей на Полях Гілсбреду.",al={"скрадач смерті леш","хто такий леш","леш гілсбред"}},{q="Хто такі скрадачі смерті?",a="Скрадачі смерті служать Королеві Сильвані Віндраннер як розвідники, шпигуни й убивці. Це таємне крило війська Відступників, що збирає відомості й усуває важливі цілі по всьому Лордерону.",al={"хто такі скрадачі смерті","орден скрадачів смерті","розбійники відступників"}},{q="Яка роль Леш у Вежі Південного Мису?",a="Вона передовий спостерігач. З Вежі Південного Мису вона пильнує Поля Гілсбреду й посилає мандрівників Орди вдарити по людських фермерах і ополченцях, щойно випаде нагода.",al={"розвідник вежі південного мису","завдання леш","чому леш тут"}},{q="Кому підзвітна Леш?",a="Вона підзвітна Верховному Екзекуторові Дарталії — командирці Відступників у Таррен Міллі, що керує наступом на людські сили в Гілсбреді.",al={"бос леш","хто командує леш","верховний виконавець дарталія"}}},fp="17,265,18.536.0,25.170.0,27.216.0,40.179.0,24.153.0"}
P.entries["npc:deathstalker-rane-yorick"] = {n="Скрадачка Смерті Рейн Йорік",s="Скрадачка Смерті Рейн Йорік — агентка розвідувальної служби Відступників, що діє глибоко в Срібноліссі. Разом зі своїм братом Квінном її послали розвідати хутори північного Срібнолісся й доповісти Верховному Екзекуторові Гадреку.",h="Скрадачка Смерті Рейн Йорік — агентка розвідувальної служби Відступників, що діє глибоко в Срібноліссі.",kw={"скрадачка смерті рейн йорік","рейн йорік","квінн","івар мерзенний","скрадачі смерті","срібнолісся","верховний екзекутор гадрек"},ang={["class:Rogue"]="Для розбійників-Відступників Рейн Йорік — приклад небезпечної польової роботи, якої чекають від скрадачів смерті: зберігати потайність і збирати відомості під постійним тиском ворога.",["faction:Horde"]="Її розвідка допомагає тримати шляхи постачання Орди через Срібнолісся вільними від воргенів і місцевих засідок.",["race:Undead"]="Поборники-Відступники зустрічають Рейн як передову розвідницю, що не дає дикому порубіжжю Срібнолісся знову опинитися у ворожих руках."},sec={{t="Очі в лісі",b="Скрадачі смерті — очі, вуха й клинки Леді Сильвани Віндраннер по всьому Лордерону. Діючи з тіні й таємних схованок, агенти на кшталт Рейн Йорік стежать за дикою місциною, вишукуючи загрози, що можуть похитнути владу Відступників. Коли Рейн і її брата Квінна послали розвідати північне Срібнолісся, вони опинилися в кільці диких небезпек, і таємна розвідка обернулася боротьбою за виживання."},{t="У пастці на Іваровій ділянці",b="Засівши в занедбаній хаті на Іваровій ділянці, Рейн Йорік бачить, що її місія під загрозою. Гуль Івар Мерзенний тяжко пошматував її брата Квінна, а полями між нею й безпечною Гробницею блукають ворги. Не бажаючи покидати доручення, вона покладається на мандрівників з Орди: вони мають зібрати серця воргів для цілющого зілля, убити Івара й доставити її звіт командуванню."}},faq={{q="Хто така Скрадачка Смерті Рейн Йорік?",a="Вона агентка скрадачів смерті — розбійницького ордену вбивць і розвідників Відступників. Нині вона перебуває в занедбаному фермерському будинку на Ділянці Івара в Срібноліссі.",al={"хто така рейн йорік","лор рейн йорік","хто скрадачка йорік"}},{q="Хто такі скрадачі смерті?",a="Скрадачі смерті — таємна розбійницька гільдія Відступників, підзвітна Леді Сильвані Віндраннер. Вони ведуть таємну розвідку, шпигунство й цілеспрямовані вбивства по всьому Лордерону.",al={"хто такі скрадачі смерті","фракція скрадачів смерті","хто скрадачі смерті"}},{q="Чому вона застрягла у фермерському будинку?",a="Рейн і її брата Квінна послали розвідати ферми на півночі Срібнолісся, але гуль Івар Мерзенний напав на них на Ділянці Івара й тяжко покалічив Квінна, тож їм довелося сховатися в будинку, доки він загоїться.",al={"чому рейн застрягла","ферма івара","чому вона ховається"}},{q="Хто її брат?",a="Її брат — Квінн Йорік, теж скрадач смерті з того самого розвідувального загону, якого тяжко покалічив гуль Івар Мерзенний на Ділянці Івара.",al={"брат рейн йорік","хто такий ерланд","скрадач смерті ерланд"}},{q="За якими загрозами вони стежать у Срібноліссі?",a="Їхнім завданням було розвідати ферми на півночі Срібнолісся й виявити загрози для Відступників, що тримають край. Вони натрапили на куди більші сили Погибелі, ніж очікували, а ще на варгів, що никають довкола, і гуля Івара Мерзенного.",al={"що вони розвідують","що розслідує рейн"}},{q="Кому вона доповідає про знахідки?",a="Вона доповідає Верховному Екзекуторові Гадреку в Гробниці, що керує присутністю Відступників у Срібноліссі.",al={"куди йдуть звіти","хто начальник рейн"}}},fp="24,236,17.438.0,21.398.1,32.201.0,27.194.0,34.227.0,19.153.0,45.211.0,35.112.0"}
P.entries["npc:deathstalker-vincent"] = {n="Скрадач Смерті Вінсент",s="Скрадач Смерті Вінсент — розвідник Відступників, якого разом зі Скрадачем Смерті Адамантом послали пробратися у Фортецю Шадовфенг. Його вбив божевільний маг Аруґал, і тіло Вінсента досі лежить у твердині як похмуре застереження кожному, хто кине виклик диким воргенам усередині.",h="Скрадач Смерті Вінсент — розвідник Відступників, якого разом зі Скрадачем Смерті Адамантом послали пробратися...",kw={"скрадач смерті вінсент","скрадач смерті адамант","фортеця шадовфенг","аруґал","відступники","розвідка"},ang={["class:Rogue"]="Страта Вінсента — тверезе нагадування про ризики, на які йдуть таємні агенти, що поодинці пробираються у ворожі твердині.",["faction:Horde"]="Знахідка тіла Вінсента підтверджує найгірші побоювання командирів Відступників у Срібноліссі: розвідка зазнала невдачі, і тепер фортецю доведеться очищати силою."},sec={{t="Смертельний кінець розвідника",b="Перш ніж Відступники могли піти в повномасштабний наступ на звірів, що тримають Фортецю Шадовфенг, їм украй потрібні були відомості про те, що коїться всередині. Двоє агентів скрадачів смерті — розвідки Відступників — прослизнули повз барикади: Вінсент і Адамант. Їхня місія скінчилася лихом. Адаманта схопили й замкнули в камері підземелля, а Вінсента притягли просто до володаря Шадовфенга. Він відмовився схилити коліно чи служити темним задумам Аруґала — і його стратили на місці, а тіло кинули гнити на кам'яній підлозі як свідчення люті мага."},{t="Зухвальство Аруґала",b="Смерть Вінсента Аруґал обернув на гнівне послання чужинцям у своїй фортеці. Ставши перед полоненим агентом, божевільний маг глузував з Відступників і порівнював їхнє вторгнення з марними спробами своїх колишніх товаришів із Кірін-Тору. Він вимагав, щоб Вінсент віддав свій клинок і таємниці його господареві, а коли той відмовився, убив розвідника, проголосивши, що його тліючі рештки стануть пересторогою кожному, хто наважиться вдертися в його володіння."}},faq={{q="Хто такий Скрадач Смерті Вінсент?",a="Вінсент був розвідником-Відступником зі скрадачів смерті. Його послали разом зі Скрадачем Смерті Адамантом зібрати важливі відомості у Фортеці Шадовфенг перед запланованим наступом з Андерсіті.",al={"хто такий вінсент","вінсент шедоуфенґ","мертвий розбійник шедоуфенґ"}},{q="Що сталося з Вінсентом у Фортеці Шадовфенг?",a="Під час розвідки Вінсента схопили, і Архімаг Аруґал стратив його, коли той відмовився перейти на інший бік чи видати відомості про Відступників. Аруґал залишив його тіло там, де воно впало, на знак своєї сили.",al={"як помер вінсент","чому вінсент мертвий","хто вбив вінсента"}},{q="Де його напарник, Скрадач Смерті Адамант?",a="Вінсента стратили просто на видноті, а Скрадача Смерті Адаманта схопили живим і замкнули в сусідній темничній камері під пильним оком воргена-вартового.",al={"де адамант","інший скрадач смерті","місце адаманта"}},{q="Навіщо скрадачів смерті послали до Фортеці Шадовфенг?",a="Срібнолісся — важливий край для Сильвани й Відступників, але воргени Аруґала тримають тамтешню фортецю Шадовфенг. Вінсента й Адаманта послали розвідати її будову й оборону, щоб Відступники могли успішно піти в наступ.",al={"чому скрадачі в шедоуфенґ","місія відступників шедоуфенґ"}}},fp="20,243,19.612.0,17.479.1,29.206.0,44.215.0,43.161.0,51.249.0"}
P.entries["npc:deathwing"] = {n="Детвінг",s="Детвінг Руйнівник, колись відомий як Нелтаріон Охоронець Землі, — занепалий Аспект чорного драконячого роду. Зведений з розуму темним шепотом Древніх Богів, він обернувся проти інших Аспектів і кинув світ у вогонь і смуту. Хоча після Другої війни його здолали біля Ґрім Батола й вважали загиблим або прихованим, жах його спадщини досі блукає глибинами Азерота.",h="Детвінг Руйнівник, колись відомий як Нелтаріон Охоронець Землі, — занепалий Аспект чорного драконячого роду.",kw={"детвінг","нелтаріон","аспект","чорні дракони","душа дракона","престор","оніксія","нефаріан"},ang={["faction:Alliance"]="Знать Альянсу досі здригається, згадуючи, як близько лорд Давал Престор підійшов до корони Альтераку і як маніпулював Радою Семи Держав, щоб зруйнувати Альянс зсередини.",["faction:Horde"]="Під час Другої війни Стара Орда уклала з Детвінгом підступну угоду, щоб через клан Драконячої Пащі здобути червоних драконів, — пляма, яку нова Орда прагне лишити в минулому.",["race:NightElf"]="Старійшини калдореїв пам'ятають раптову нищівну зраду Нелтаріона десять тисяч років тому, під час Війни Прадавніх, — злочин, що зламав драконячий рід і прирік їхню прадавню імперію."},sec={{t="Падіння Нелтаріона",b="Ще до того, як його прозвали Руйнівником, пантеон титанів віддав Нелтаріонові владу над землею й підземними глибинами Азерота. Та життя так близько до найглибших надр світу відкрило його підступному шепоту ув'язнених Древніх Богів. Під час Війни Прадавніх божевілля цілком заволоділо ним. Він ошукав інших Аспектів драконів, умовивши їх вкласти частку своєї сутності в золотий диск — Душу Дракона — нібито для того, щоб зупинити Палаючий Легіон, а тоді обернув цю жахливу зброю проти союзників і завдав катастрофічних руйнувань."},{t="Підступи людського лорда",b="Following the Second War, Deathwing sought to tear down mortal kingdoms from within. Taking the human identity of Lord Daval Prestor, a charismatic noble, he charmed King Terenas Menethil II and the high council of the Alliance of Lordaeron, plotting to install himself on the vacant throne of Alterac. Meanwhile, he aided the Dragonmaw clan at Grim Batol to keep Queen Alexstrasza enslaved while harvesting her clutches. His machinations unraveled when Rhonin destroyed the Demon Soul, restoring the other Aspects' stolen power and enabling them to drive Deathwing away."},{t="Покинутий виводок",b="Нині королівства смертних здебільшого вважають, що Детвінга знищено або назавжди вигнано зі світу. Та чорний драконячий рід і далі сіє лихо по всьому Азероту. На чолі з його підступним виводком — зокрема донькою Оніксією та сином Нефаріаном — чорні дракони смикають за ниточки політики смертних і тероризують краї зі своїх гірських лігв. Рани від давньої зради чорного Аспекта глибокі, і мандрівники, що блукають скелястими безлюдними землями й глибокими підземними тунелями, досі бояться, що Великий Дракон прокинеться."}},faq={{q="Ким спершу був Детвінг?",a="Спершу Детвінг був Нелтаріоном, Охоронцем Землі, — провідником чорного драконячого роду, якого титани наділили силою опікуватися землями й горами Азероту. Тисячоліття тому через близькість до земних глибин він став вразливим до підступного шепоту Древніх Богів, що підточив його розум.",al={"історія нелтаріона","хто такий нелтаріон","походження хранителя землі"}},{q="Що таке Душа Дракона?",a="Душа Дракона, згодом відома як Душа Демона, — золотий артефакт, який Нелтаріон викував під час Війни Прадавніх. Він обманом змусив чотирьох інших Аспектів влити в нього свою силу, а тоді обернув руйнівну міць цієї зброї і проти своїх побратимів-драконів, і проти смертних захисників.",al={"душа дракона","демонічна душа","артефакт нелтаріона"}},{q="Хто такий Лорд Давал Престор?",a="Лорд Давал Престор — людська личина, яку Детвінг прибрав після Другої війни. Могутніми чарами й придворними підступами він намагався захопити трон Альтераку й маніпулювати Альянсом Лордерону зсередини, доки його зраду не викрили.",al={"лорд престор","особа даваля престора","лор престора"}},{q="Що пов'язує Детвінга з Ґрім Батолом?",a="Deathwing covertly provided the Dragonmaw orcs with the Demon Soul at Grim Batol, ensuring the red dragon queen Alexstrasza remained chained and bred for war. Later, Rhonin destroyed the artifact with one of Deathwing's scales. Their powers restored, the other Aspects fought Deathwing and drove him away.",al={"детвінг ґрім батол","що сталося в ґрім батолі"}},{q="Хто нині очолює чорний драконячий рід?",a="Детвінга немає, і його вважають загиблим, тож його головні нащадки діють незалежно. Його дочка Оніксія висиджує кладки у своєму лігві в Багні Пилоброду, а син Нефаріан командує чорними драконами й експериментує з драконячою кров'ю на вершині Гори Блекрок.",al={"хто очолює чорних драконів","нині лідер чорного виводку","нефаріан і оніксія"}}},fp="9,406,22.588.0,24.571.1,21.547.0,29.287.0,25.292.0,27.265.1,45.305.0,39.252.2"}
P.entries["npc:deino"] = {n="Дейно",s="Дейно — тролиця з племені Темного Спису, наставниця магів у Долині Духів Оргріммара. Разом зі своїми товаришками вона вчить молодих чарівників опановувати арканну магію й приборкувати непокірні сили стихій. А досвідчених заклиначів вона посилає в мандри Калімдором — розгадувати давні магічні аномалії й шукати відлюдних наставників.",h="Дейно — тролиця з племені Темного Спису, наставниця магів у Долині Духів Оргріммара.",kw={"дейно","маг","долина духів","темний спис","ашенваль","табета","оргріммар"},ang={["class:Mage"]="Дейно — важлива наставниця класу в Оргріммарі: вона навчає ключових умінь і заклять порталів і дає особливі завдання, що ведуть до Ашенвалю й Багна Пилоброду.",["faction:Horde"]="Перебуваючи в духовному кварталі Оргріммара, вона дбає, щоб заклиначі Орди мали грізну арканну силу поряд із шаманами й чорнокнижниками.",["race:Troll"]="Дейно — приклад того, як Темний Спис пристосував арканну магію: вона поєднує класичну вчену чародійську науку з культурним середовищем Долини Духів."},sec={{t="Чарівниця Долини",b="Серед тотемів, хиж і спокійних вод Долини Духів Дейно навчає магів Орди, що опиняються в оркській столиці. Тролі-заклиначі споконвіку балансують між духовним шануванням і чистою арканною майстерністю, і Дейно втілює цей особливий шлях у племені Темного Спису, стоячи пліч-о-пліч із наставницями Еніо й Пефредо."},{t="Розгадуючи арканні таємниці",b="Окрім основ чарування, Дейно доручає обдарованим заклиначам польові дослідження далеко за межами червоного пилу Дуротару. Вона посилає їх на північ, у зіпсовані хащі Ашенвалю, — по отруєні Води Ксавіана й зачароване волосся Регітливих Сестер. Коли сила учня переростає те, що може дати Оргріммар, Дейно скеровує його до віддалених майстрів, як-от до чарівниці-відлюдниці Табети в Багні Пилоброду."}},faq={{q="Де знайти Дейно?",a="Дейно стоїть на підвищених майданчиках у Долині Духів на південному заході Оргріммара разом з іншими тролями — наставницями магів Еніо й Пефредо.",al={"місце дейно","де дейно","дейно оргріммар"}},{q="Чого навчає Дейно?",a="Вона навчає магів заклять тайної магії, вогню й криги, створення порталів і нових рангів заклять у міру того, як заклиначі набираються досвіду.",al={"чого навчає дейно","які закляття навчає дейно"}},{q="Навіщо Дейно посилає магів до Ксавіану?",a="Дейно шукає опоганені Води Ксавіану з володінь сатирів на півночі Ашенвалю, щоб допомогти магам зрозуміти нестійкі, зіпсовані магічні резонанси.",al={"завдання вод зав'яну","чому зав'ян"}},{q="Хто ці наставниці, що стоять поряд із Дейно?",a="Вона стоїть з Еніо та Пефредо. Разом ці троє носять імена сестер Грай із давнього міфу й становлять головне коло наставниць-тролів для магів в Оргріммарі.",al={"хто такі еніо й пефредо","наставниці біля дейно","троль-маги долини духів"}},{q="Навіщо Дейно посилає магів до Багна Пилоброду?",a="Коли маг досягає більшої майстерності, Дейно посилає його до Табети — могутньої відлюдниці-людини, що живе глибоко в Багні Пилоброду й знає особливі тайні секрети.",al={"дейно табета","подорож до болота"}},{q="Чи можуть у Дейно навчатися не тролі?",a="Так. Будь-який маг Орди — хоч Нежить, хоч троль — може опанувати класові закляття й отримати настанови від Дейно в Долині Духів.",al={"чи орки можуть вчитися в дейно","навчання магів орди"}}},fp="5,345,21.404.0,27.451.0,23.152.0,22.130.0,36.153.0,41.178.0,46.181.0,32.128.0"}
